          GUID = "0F459F9C",
          NextDialogue = 6100503,
          RougeTalkActorType = 3
        },
        [6100503] = {
          ContentKR = "\"오라, 신의 은총을 받아, 구름 위 하늘로 오르노라. 속세에 미련 없으리, 더없는 행복이 기다릴지어다.\"",
          DialogueId = 6100503,
          GUID = "0F459FC6",
          NextOptions = {
            [1] = 6100504,
            [2] = 6100506,
            [3] = 6100508
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room305_Char01"
        },
        [6100504] = {
          ContentKR = "지상에 남는다.",
          DialogueId = 6100504,
          GUID = "0F459FF0",
          IsKeyOption = true,
          NextDialogue = 6100505,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100505] = {
          ContentKR = "알다시피 하늘에서 떨어지는 행복 뒤에는, 반드시 그에 따른 대가가 있다.\n허황된 천국의 길보다, 당신은 자신이 남긴 발자국 하나하나를 믿으려 한다.",
          DialogueId = 6100505,
          GUID = "0F45A01A",
          RougeTalkActorType = 3
        },
        [6100506] = {
          ContentKR = "은총을 받아들인다.",
          DialogueId = 6100506,
          GUID = "0F45A044",
          IsKeyOption = true,
          NextDialogue = 6100507,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100507] = {
          ContentKR = "어머니의 부드러운 포옹처럼, 구름이 당신을 감싸안는다.\n금빛 대문이 천천히 열리고, 당신은 신의 그림자가 문 뒤로 스쳐 지나가는 것을 본 듯하다. 구름이 걷히고 당신은 지상으로 돌아온다.",
          DialogueId = 6100507,
          GUID = "0F45A06E",
          NextDialogue = 6100510,
          RougeTalkActorType = 3
        },
        [6100508] = {
          ContentKR = "구름 한 점을 잡아 본다.",
          DialogueId = 6100508,
          GUID = "0F45A098",
          IsKeyOption = true,
          NextDialogue = 6100509,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100509] = {
          ContentKR = "당신은 하늘을 향해 힘껏 손을 뻗어 보지만, 부드러워 보이는 구름은 당신의 손가락을 활활 태운다.\n빛은 사라지고, 귓가에 바람 소리가 윙윙거린다. 당신은 자신이 추락하고 있다는 것을 깨닫는다.",
          DialogueId = 6100509,
          GUID = "0F45A0C2",
          NextDialogue = 6100510,
          RougeTalkActorType = 3
        },
        [6100510] = {
          ContentKR = "맞다, 당신은 잊고 있었다. 심연 속에 하늘은 존재하지 않는다.",
          DialogueId = 6100510,
          GUID = "0F45A0EC",
          RougeTalkActorType = 3
        },
        [6100601] = {
          ContentKR = "야위고 작은 그림자가 걸어온다.\n가까이 온 그녀는, 키가 크지 않은 소녀였다.",
          DialogueId = 6100601,
          GUID = "0F45AFDA",
          NextDialogue = 6100602,
          RougeTalkActorType = 3
        },
        [6100602] = {
          ContentKR = "\"실례합니다... 혹시... 여기서... 불 좀 쬘 수 있을까요?\"\n소녀는 오들오들 떨고 있다. 치맛자락에서 물방울이 뚝뚝 떨어지는 것이 보인다. 드레스가 흠뻑 젖어 있다.",
          DialogueId = 6100602,
          GUID = "0F45B004",
          NextDialogue = 6100603,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100603] = {
          ContentKR = "\"엄마를 잃어버렸어요... 추워요... 불 좀 쬐게 해주세요! 잠깐이면 돼요.\"",
          DialogueId = 6100603,
          GUID = "0F45B02E",
          NextOptions = {
            [1] = 6100604,
            [2] = 6100613
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100604] = {
          ContentKR = "동의한다.",
          DialogueId = 6100604,
          GUID = "0F45B058",
          IsKeyOption = true,
          NextDialogue = 6100605,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100605] = {
          ContentKR = "\"감사합니다.\"\n그녀는 오돌오돌 떨며, 감사의 인사를 한다.",
          DialogueId = 6100605,
          GUID = "0F45B082",
          NextDialogue = 6100606,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100606] = {
          ContentKR = "왜 여기에 온 건지 묻는다.",
          DialogueId = 6100606,
          GUID = "0F45B0AC",
          NextDialogue = 6100607,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100607] = {
          ContentKR = "\"왜... 왜요...? 아... 생각났어요...\"\n\"아빠랑... 엄마... 는 휘페르보레아 사람인데... 엘리시안으로... 도망...\"\n\"바다에서... 배가... 검은 소용돌이에...\"",
          DialogueId = 6100607,
          GUID = "0F45B0D6",
          NextDialogue = 6100608,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100608] = {
          ContentKR = "검은 소용돌이. 당신도 알다시피, 그것은 흑조다. 배고픈 심연이 형체를 가진 모든 것을 뱃속으로 삼키는 것이다.",
          DialogueId = 6100608,
          GUID = "0F45B100",
          NextDialogue = 6100609,
          RougeTalkActorType = 3
        },
        [6100609] = {
          ContentKR = "왜 엘리시안에 가려고 하는지 묻는다.",
          DialogueId = 6100609,
          GUID = "0F45B12A",
          NextDialogue = 6100610,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100610] = {
          ContentKR = "\"엄마 말이... 우린 '악마의 아이'라고...\"\n\"최악의 상황으로 심연에 떨어진다고 해도... 휘페르보레아에 남는 것보다는... 나을 테니까...\"",
          DialogueId = 6100610,
          GUID = "0F45B154",
          NextDialogue = 6100611,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100611] = {
          ContentKR = "\"불을 쬐게 해 주셔서 감사하고... 알려주셔서 감사해요... 저는 이미 이 세상에 없어요.\"",
          DialogueId = 6100611,
          GUID = "0F45B17E",
          NextDialogue = 6100612,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100612] = {
          ContentKR = "그녀는 사라졌다. 처음부터 아무도 없었던 것처럼, 당신 곁에는 바싹바싹 타오르는 모닥불만이 남아 있다.",
          DialogueId = 6100612,
          GUID = "0F45B1A8",
          RougeTalkActorType = 3
        },
        [6100613] = {
          ContentKR = "거절한다.",
          DialogueId = 6100613,
          GUID = "0F45B1D2",
          IsKeyOption = true,
          NextDialogue = 6100614,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100614] = {
          ContentKR = "\"죄... 죄송합니다... 귀찮게 해서 죄송합니다.\"",
          DialogueId = 6100614,
          GUID = "0F45B1FC",
          NextDialogue = 6100615,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100615] = {
          ContentKR = "소녀는 덜덜 떨면서 가버렸다. 아무도 오지 않았던 것처럼, 당신 곁에는 활활 타오르는 모닥불만이 남아 있다.",
          DialogueId = 6100615,
          GUID = "0F45B226",
          RougeTalkActorType = 3
        },
        [6100701] = {
          ContentKR = "\"안녕하세요!\"",
          DialogueId = 6100701,
          GUID = "0F45C042",
          NextDialogue = 6100702,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100702] = {
          ContentKR = "배낭을 멘 쾌활한 청년이 모닥불 옆으로 다가와, 큰소리로 인사를 한다.",
          DialogueId = 6100702,
          GUID = "0F45C06C",
          NextDialogue = 6100703,
          RougeTalkActorType = 3
        },
        [6100703] = {
          ContentKR = "\"좀 실례되는 말이지만, 당신은 아직 살아있군요! 맞죠?\"",
          DialogueId = 6100703,
          GUID = "0F45C096",
          NextOptions = {
            [1] = 6100704,
            [2] = 6100711
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100704] = {
          ContentKR = "고개를 끄덕인다.",
          DialogueId = 6100704,
          GUID = "0F45C0C0",
          IsKeyOption = true,
          NextDialogue = 6100705,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100705] = {
          ContentKR = "\"여기서 살아있는 사람을 만날 줄은 정말 몰랐어요. 당신도 저처럼, 엄청난 행운아네요!\"",
          DialogueId = 6100705,
          GUID = "0F45C0EA",
          NextDialogue = 6100706,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100706] = {
          ContentKR = "\"저는 열여섯 살 되던 해에 아버지와 함께 노래를 한 곡 썼는데, 성재로부터 신성 모독 판결을 받았어요.\"\n\"재수라곤 더럽게 없는 아버지처럼 저도 목이 날아갈 뻔했는데, 사형 집행인이 처형일에 벼락을 맞아 사면됐죠.\"",
          DialogueId = 6100706,
          GUID = "0F45C114",
          NextDialogue = 6100707,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100707] = {
          ContentKR = "\"스무 살 되던 해에 유랑 상인 무리에 합류했는데, 북쪽 숲에서 강도를 당했어요. 납치돼서 동굴에 버려졌죠.\"\n\"동료들처럼 굶어 죽나 했는데, 일주일째 되는 날 아침 돼지 한 마리가 깨우더니, 한 소녀가 먹을 걸 주더라고요. 천사를 만난 줄 알았죠.\"",
          DialogueId = 6100707,
          GUID = "0F45C13E",
          NextDialogue = 6100708,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100708] = {
          ContentKR = "\"그 후 전 상인으로서 기사단을 따라 심연으로 왔어요. 손에 든 랜턴이 하나둘 꺼졌고, 기사 나리 하나는 넘어지면서 자신의 검에 목을 찔렸어요. 제가 유일한 생존자였죠.\"\n\"그래서 전 운명의 여신을 믿게 됐어요. 여신께선 제게 더없는 행운과 행복을 주실 거예요.\"",
          DialogueId = 6100708,
          GUID = "0F45C168",
          NextDialogue = 6100709,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100709] = {
          ContentKR = "\"그분이 절 인도했다는 건, 이곳 깊숙이 유일무이한 보물이 절 기다리고 있다는 뜻이죠. 이제, 전 그걸 찾아서 떠나야 해요.\"\n그가 무거운 배낭을 짊어진다.",
          DialogueId = 6100709,
          GUID = "0F45C192",
          NextDialogue = 6100710,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100710] = {
          ContentKR = "\"참, 저기요! 그분께서 당신을 살아남게 했으니, 당신도 당신만의 유일무이한 행운을 만나게 될 거예요!\"\n그는 두 주먹을 불끈 쥐고, 크게 웃는다.\n\"우리의 행복을 위하여!\"",
          DialogueId = 6100710,
          GUID = "0F45C1BC",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100711] = {
          ContentKR = "누워서 죽은 척한다.",
          DialogueId = 6100711,
          GUID = "0F45C1E6",
          IsKeyOption = true,
          NextDialogue = 6100712,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100712] = {
          ContentKR = "\"기절했나?\"\n그는 쪼그리고 앉아, 당신이 숨을 쉬는지 코에 손을 댄다.\n\"설마, 당신도 그들과 같은 망령인가요?\"",
          DialogueId = 6100712,
          GUID = "0F45C210",
          NextDialogue = 6100713,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100713] = {
          ContentKR = "당신은 침묵한다.\n그는 배낭을 내려놓고, 물과 음식을 꺼낸다.",
          DialogueId = 6100713,
          GUID = "0F45C23A",
          NextDialogue = 6100714,
          RougeTalkActorType = 3
        },
        [6100714] = {
          ContentKR = "\"불쌍한 친구, 이걸 놓고 갈게요! 성탑에 첫 번째 햇살이 비출 때, 당신이 깨어나서 처음처럼 건강해지기를 바라요.\"",
          DialogueId = 6100714,
          GUID = "0F45C264",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100801] = {
          ContentKR = "같은 줄기에서 자라난 검붉은 꽃 한 쌍이 어둠 속에서 그윽한 빛을 발하고 있다.\n당신이 랜턴을 들자, 희끗희끗한 금발머리 몇 가닥과 몇 마디의 창백한 등뼈가 비친다. 이건 사람 모양의 필토이드일까? 아니면 곧 필토이드가 될 사람일까?\n당신은 경계하며 무기를 움켜쥐지만, 그것은 당신을 공격하지 않는다. 다만 어둠 속에 박힌 검붉은 눈동자로, 당신을 소리 없이 주시하고 있을 뿐이다.",
          DialogueId = 6100801,
          GUID = "0F45D0AA",
          NextDialogue = 6100802,
          RougeTalkActorType = 3
        },
        [6100802] = {
          ContentKR = "갑자기, 그것이 목에서 뭔가 산산조각 나는 소리를 낸다. 날카로운 돌멩이들이 서도 부딪치며 내는 소리 같기도 하고, 어떤 리듬을 타는 것 같기도 하다. 이유는 모르지만, 당신은 그 의미를 이해할 수 있을 것 같다.",
          DialogueId = 6100802,
          GUID = "0F45D0D4",
          NextDialogue = 6100803,
          RougeTalkActorType = 3
        },
        [6100803] = {
          ContentKR = "\"랜턴을 든 여행자님, 가지 마세요. 당신의 랜턴에 비친 제 모습이 여전히 아름다운가요? 제발 알려주세요.\"",
          DialogueId = 6100803,
          GUID = "0F45D0FE",
          NextDialogue = 6100804,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room308_Char01"
        },
        [6100804] = {
          ContentKR = "\"전 윤기 나게 머리를 빗고 곱게 땋았어요.\" 필토이드가 머리 뒤의 갈라진 피부를 어루만진다.\n\"치마의 주름도 가지런히 다려, 화려한 보석으로 장식했어요.\" 필토이드가 표면에 깊이 박힌 결정을 어루만진다.\n\"사랑하는 이가 준 목걸이를 목에 걸고, 그의 간절한 마음을 생각해요.\" 필토이드가 목 사이로 뻗은 뼈마디를 어루만진다.",
          DialogueId = 6100804,
          GUID = "0F45D128",
          NextOptions = {
            [1] = 6100805,
            [2] = 6100808
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room308_Char01"
        },
        [6100805] = {
          ContentKR = "\"네, 아름답습니다.\"",
          DialogueId = 6100805,
          GUID = "0F45D152",
          IsKeyOption = true,
          NextDialogue = 6100806,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100806] = {
          ContentKR = "마치 바람에 흔들리는 꽃잎처럼, 붉은 눈동자가 가늘게 떨린다.",
          DialogueId = 6100806,
          GUID = "0F45D17C",
          NextDialogue = 6100807,
          RougeTalkActorType = 3
        },
        [6100807] = {
          ContentKR = "\"감사합니다, 친절한 여행자님. 제 감사의 선물을 받아 주세요.\"\n\"혹시 제 애인을 만난다면, 제가 영원히 사랑할 거라고 전해 주세요.\"",
          DialogueId = 6100807,
          GUID = "0F45D1A6",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room308_Char01"
        },
        [6100808] = {
          ContentKR = "\"당신은 무서운 괴물입니다.\"",
          DialogueId = 6100808,
          GUID = "0F45D1D0",
          IsKeyOption = true,
          NextDialogue = 6100809,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100809] = {
          ContentKR = "험상궂은 발톱이 그 붉은 눈동자를 덮는다.",
          DialogueId = 6100809,
          GUID = "0F45D1FA",
          NextDialogue = 6100810,
          RougeTalkActorType = 3
        },
        [6100810] = {
          ContentKR = "\"오, 안 돼! 이렇게 못생긴 내 모습을 사랑하는 사람에게 보여주고 싶지 않아요.\"\n\"자비로운 여행자님, 저를 끝내주세요.\"",
          DialogueId = 6100810,
          GUID = "0F45D224",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room308_Char01"
        },
        [6100901] = {
          ContentKR = "\"안녕하세요, 낯선 여행자님.\"",
          DialogueId = 6100901,
          GUID = "0F45E112",
          NextDialogue = 6100902,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100902] = {
          ContentKR = "화려한 옷차림의 한 청년이 모닥불에 흔들리는 빛과 그림자 속에서 걸음을 멈추고, 당신을 향해 우아하게 인사한다.",
          DialogueId = 6100902,
          GUID = "0F45E13C",
          NextDialogue = 6100903,
          RougeTalkActorType = 3
        },
        [6100903] = {
          ContentKR = "\"전 빨간 눈동자를 가진 여인을 찾고 있어요. 혹시 그녀가 얼마나 아름다운지 본 적 있으세요?\"",
          DialogueId = 6100903,
          GUID = "0F45E166",
          NextDialogue = 6100904,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100904] = {
          ContentKR = "\"그녀는 세상에서 가장 아름다운 목소리를 가지고 있어요. 나이팅게일도 무색할 정도죠.\"\n\"그녀는 봄날에 피는 금잔화처럼, 부드럽고 아름다운 금빛 머리카락을 가지고 있어요.\"\n\"그녀는 화려하면서도 단아한 원피스를 입고 있어요. 치맛자락에는 별처럼 빛나는 보석이 가득 달려 있죠.\"\n\"그녀는 제가 선물한 목걸이를 하고 있어요. 신비롭고 그윽한 검붉은 색 수정이 마치 절 응시하는 그녀의 눈처럼 보이죠.\"",
          DialogueId = 6100904,
          GUID = "0F45E190",
          NextDialogue = 6100905,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100905] = {
          ContentKR = "그런 여인을 본 적이 없다.",
          DialogueId = 6100905,
          GUID = "0F45E1BA",
          NextDialogue = 6100906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100906] = {
          ContentKR = "\"그래요...\"\n그는 우울하게 눈을 내리깔지만, 곧 우아한 모습으로 돌아온다.\n\"괜찮아요, 계속 찾아보면 되니까요.\"",
          DialogueId = 6100906,
          GUID = "0F45E1E4",
          NextDialogue = 6100907,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100907] = {
          ContentKR = "청년이 모닥불 옆에 앉자, 밝은 불길이 그의 눈동자에 비친다.",
          DialogueId = 6100907,
          GUID = "0F45E20E",
          NextDialogue = 6100908,
          RougeTalkActorType = 3
        },
        [6100908] = {
          ContentKR = "\"저는 그녀와 오래전에 약혼했어요. 성인이 되면 혼례를 올리기로 했죠. 그런데 그녀가 신의 은총을 입어, 이마의 성흔이 점점 뚜렷해지더니, 열네 살 생일 전날 밤 사자가 찾아와서 데려갔어요.\"\n\"그녀는 떠나기 전에 저에게 다른 짝을 찾으라는 편지를 남겼죠. 하지만 전 맹세했어요. 이번 생은 오직 그녀와 함께하겠다고요.\"\n\"그녀를 찾으면, 다시 이 세상에 데려올 거예요. 만월의 신께선 사람들에게 사랑의 아름다움을 노래하라고 가르치셨으니, 반드시 저희를 도와주실 거예요.\"",
          DialogueId = 6100908,
          GUID = "0F45E238",
          NextOptions = {
            [1] = 6100909,
            [2] = 6100911
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100909] = {
          ContentKR = "하루빨리 연인을 찾기를 바란다.",
          DialogueId = 6100909,
          GUID = "0F45E262",
          IsKeyOption = true,
          NextDialogue = 6100910,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100910] = {
          ContentKR = "\"정말 고맙습니다, 친절한 여행자님.\"\n\"작은 선물이지만 받아주세요. 당신도 원하는 것을 얻길 바랍니다.\"",
          DialogueId = 6100910,
          GUID = "0F45E28C",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100911] = {
          ContentKR = "\"만약 신이 동의하지 않으면요?\"",
          DialogueId = 6100911,
          GUID = "0F45E2B6",
          IsKeyOption = true,
          NextDialogue = 6100912,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100912] = {
          ContentKR = "그는 당신을 향해 담담하게 미소 짓는다.\n\"그러면 이 몸을 성스러운 호수에 바쳐, 영혼이나마 영원히 그녀와 함께하겠습니다.\"",
          DialogueId = 6100912,
          GUID = "0F45E2E0",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6101001] = {
          ContentKR = "모닥불 옆에 한 여인이 나타난다. 그녀는 활활 타오르는 모닥불에 왼손을 뻗어 재를 묻히고, 바닥에 당신이 알아볼 수 없는 글을 쓴다.",
          DialogueId = 6101001,
          GUID = "0F45F17A",
          NextDialogue = 6101002,
          RougeTalkActorType = 3
        },
        [6101002] = {
          ContentKR = "\"아, 시간을 거스르는 여행자여, 그대의 동반자는 절망이요, 죽음은 그림자처럼 따라다닌다네.\"\n그녀가 낮은 소리로 읊조린다.",
          DialogueId = 6101002,
          GUID = "0F45F1A4",
          NextOptions = {
            [1] = 6101003,
            [2] = 6101005
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room310_Char01"
        },
        [6101003] = {
          ContentKR = "뭘 하고 있는지 묻는다.",
          DialogueId = 6101003,
          GUID = "0F45F1CE",
          IsKeyOption = true,
          NextDialogue = 6101004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101004] = {
          ContentKR = "\"오, 친구여! 보시다시피, 저는 시인입니다.\"\n\"저는 지금 제 1001번째 작품을 창작하고 있어요. 맞습니다. 당신을 위한 시죠!\"",
          DialogueId = 6101004,
          GUID = "0F45F1F8",
          NextDialogue = 6101008,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room310_Char01"
        },
        [6101005] = {
          ContentKR = "\"불꽃이 뜨겁지 않나요?\"",
          DialogueId = 6101005,
          GUID = "0F45F222",
          IsKeyOption = true,
          NextDialogue = 6101006,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101006] = {
          ContentKR = "여자가 깔깔거리며 웃는다.",
          DialogueId = 6101006,
          GUID = "0F45F24C",
          NextDialogue = 6101007,
          RougeTalkActorType = 3
        },
        [6101007] = {
          ContentKR = "\"잘 보세요, 친구.\"\n그녀가 당신의 눈앞에 손바닥을 편다. 하얀 손은 흠결 없이 멀쩡하다.\n\"당신처럼 지혜로운 여행자는, 이 불이 진짜가 아니라는 걸 눈치챘겠죠. 저도 마찬가지로 진짜가 아니고요.\"",
          DialogueId = 6101007,
          GUID = "0F45F276",
          NextDialogue = 6101008,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room310_Char01"
        },
        [6101008] = {
          ContentKR = "시인이 다시 손을 뻗어 모닥불을 휘젓는다. 가느다란 손끝이 무용수의 두 발처럼 날렵하게 불 속을 누빈다.",
          DialogueId = 6101008,
          GUID = "0F45F2A0",
          NextDialogue = 6101009,
          RougeTalkActorType = 3
        },
        [6101009] = {
          ContentKR = "\"이곳은 정말 아름다운 곳이죠, 그렇지 않나요?\"\n\"저는 마침내 육체적인 고통에서 벗어났어요. 다시는 지루한 일들로 제 창작을 방해받지 않게 됐죠. 전 무한한 자유와 영원한 시간을 얻었어요.\"\n\"여행자님, 여기 멈춰서 한 줄기 빛을 가져다주셔서 감사해요. 제 시를 받아주세요. 반드시 이 끝없는 윤회에서 벗어나, 소망을 이루시길 바랄게요.\"",
          DialogueId = 6101009,
          GUID = "0F45F2CA",
          NextDialogue = 6101010,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room310_Char01"
        },
        [6101010] = {
          ContentKR = "시인이 손을 뻗자, 연기가 폭풍처럼 순식간에 눈앞을 가린다.\n연기가 흩어지자, 시인은 이미 사라진 뒤였다.",
          DialogueId = 6101010,
          GUID = "0F45F2F4",
          RougeTalkActorType = 3
        },
        [6101101] = {
          ContentKR = "\"안녕하세요, 혹시 당신의 빛을 좀 빌려주실 수 있을까요.\"",
          DialogueId = 6101101,
          GUID = "0F4601E2",
          NextDialogue = 6101102,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101102] = {
          ContentKR = "소년이 어리숙한 걸음으로 짐짓 점잖은 체하며, 천천히 모닥불 옆에 앉는다.\n너무 큰 턱시도를 입고 있어, 앙상한 체구가 안쓰러워 보일 정도다. 그는 불빛 아래 얇은 책 한 권을 들고, 아주 그럴듯하게 낭독하기 시작한다.",
          DialogueId = 6101102,
          GUID = "0F46020C",
          NextDialogue = 6101103,
          RougeTalkActorType = 3
        },
        [6101103] = {
          ContentKR = "\"화염의 신이여, 우리에게 지혜를 주소서... 물의 신이시여, 우리에게 풍요를 주소서...\"",
          DialogueId = 6101103,
          GUID = "0F460236",
          NextOptions = {
            [1] = 6101104
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101104] = {
          ContentKR = "뭘 읽는 건가요?",
          DialogueId = 6101104,
          GUID = "0F460260",
          NextDialogue = 6101105,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101105] = {
          ContentKR = "\"아, 형들이 준 책을 읽고 있어요.\" 소년은 부끄러워하며 머리를 쓰다듬는다. \"신을 뵙기 전에 더 똑똑해져야 하거든요.\"\n\"전 어릴 때부터 집안에서 가장 맹한 아이였어요. 형들은 저보다 훨씬 똑똑했죠. 그런데 신께서 하필이면 절 뽑으신 거예요. 다들 말도 안 된다고 했죠.\"\n\"형들이 이 성가책을 주면서 아홉 신을 뵙기 전에 잘 읽으라고 했어요. 집안 망신시키지 않도록요.\"",
          DialogueId = 6101105,
          GUID = "0F46028A",
          NextDialogue = 6101106,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101106] = {
          ContentKR = "소년이 몸을 움직여 당신 곁에 더 가까이 앉는다. 그리곤 책을 치켜들고, 같이 보자는 눈짓을 한다.",
          DialogueId = 6101106,
          GUID = "0F4602B4",
          NextDialogue = 6101107,
          RougeTalkActorType = 3
        },
        [6101107] = {
          ContentKR = "\"저랑 같이 보실래요?\"",
          DialogueId = 6101107,
          GUID = "0F4602DE",
          NextOptions = {
            [1] = 6101108,
            [2] = 6101112
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101108] = {
          ContentKR = "함께 책을 읽는다.",
          DialogueId = 6101108,
          GUID = "0F460308",
          IsKeyOption = true,
          NextDialogue = 6101109,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101109] = {
          ContentKR = "당신은 제안을 받아들여 책으로 시선을 옮긴다. 놀랍게도 책장엔 누군가가 시커먼 펜으로 쓴, 당신이 상상조차 하지 못할 악담과 상스러운 말들로 뒤덮여 있다.\n글자는 순식간에 검은 가시덤불이 되어, 책장을 뚫고 나와, 사냥에 나선 독사처럼 몸을 휘감는다. 시야가 천천히 흐려진다.\n당신은 살아남기 위해 본능적으로 몸을 뒤로 젖혀, 시선을 책장 밖으로 옮긴다.",
          DialogueId = 6101109,
          GUID = "0F460332",
          NextDialogue = 6101110,
          RougeTalkActorType = 3
        },
        [6101110] = {
          ContentKR = "\"어? 왜 그러세요? 책에 무서운 거라도 있나요?\"\n소년은 당신을 곤혹스럽게 바라보지만, 눈빛은 여전히 맑고 투명하다.",
          DialogueId = 6101110,
          GUID = "0F46035C",
          NextDialogue = 6101111,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101111] = {
          ContentKR = "당신은 입을 열지만, 아무 소리도 내지 못한다.\n검은 가시덤불은 소년을 뒤덮어 삼켰다. 곧이어 소년과 책, 가시덤불은 모두 사라져 버렸다.",
          DialogueId = 6101111,
          GUID = "0F460386",
          RougeTalkActorType = 3
        },
        [6101112] = {
          ContentKR = "함께 읽기를 거절한다.",
          DialogueId = 6101112,
          GUID = "0F4603B0",
          IsKeyOption = true,
          NextDialogue = 6101113,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101113] = {
          ContentKR = "당신은 여기에 공부하러 온 것이 아니다.",
          DialogueId = 6101113,
          GUID = "0F4603DA",
          NextDialogue = 6101114,
          RougeTalkActorType = 3
        },
        [6101114] = {
          ContentKR = "\"알았어요. 그럼 저 혼자 읽을게요...\"\n소년이 책을 다시 무릎 위에 놓는다.",
          DialogueId = 6101114,
          GUID = "0F460404",
          NextDialogue = 6101115,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101115] = {
          ContentKR = "갑자기 책에서 검은 가시덤불이 뻗어 나온다.\n놀랄 새도 없이, 가시덤불은 소년을 뒤덮어 삼켰다. 곧이어 소년과 책, 가시덤불은 모두 사라져 버렸다.",
          DialogueId = 6101115,
          GUID = "0F46042E",
          RougeTalkActorType = 3
        },
        [6101201] = {
          ContentKR = "한 중년 여인이 침울한 얼굴로 모닥불 앞에 앉았으나, 불빛은 그녀의 어두운 눈을 비추지 못했다.",
          DialogueId = 6101201,
          GUID = "0F46124A",
          NextDialogue = 6101202,
          RougeTalkActorType = 3
        },
        [6101202] = {
          ContentKR = "\"안녕하세요, 낯선 분. 실례지만 여기가 어디인가요?\"",
          DialogueId = 6101202,
          GUID = "0F461274",
          NextDialogue = 6101203,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101203] = {
          ContentKR = "대답한다.",
          DialogueId = 6101203,
          GUID = "0F46129E",
          NextDialogue = 6101204,
          RougeTalkActorType = 3
        },
        [6101204] = {
          ContentKR = "\"성스러운 호수...? 심연...?\" 그녀의 말투는 막막함과 당혹스러움으로 가득 차 있다. \"전 어째서 그런 말들을 들어본 적 없는 것 같죠...\"\n그녀는 주름 골이 가득한 자신의 손바닥을 바라본다. \"제가 여기 왜 왔는지 잊어버렸어요.\"",
          DialogueId = 6101204,
          GUID = "0F4612C8",
          NextOptions = {
            [1] = 6101205,
            [2] = 6101207
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101205] = {
          ContentKR = "성스러운 호수의 역사를 알려준다.",
          DialogueId = 6101205,
          GUID = "0F4612F2",
          IsKeyOption = true,
          NextDialogue = 6101206,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101206] = {
          ContentKR = "\"몸에 성흔이 생긴 사람은... 이곳으로 오게 된다고요...?\"\n\"아... 생각났어요. 제 아이가 여기 있어요. 아이의 눈가에 날개를 퍼덕이며 날아오르려는 나비 같은 성흔이 나타났어요.\"",
          DialogueId = 6101206,
          GUID = "0F46131C",
          NextDialogue = 6101210,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101207] = {
          ContentKR = "소지품을 살펴보라고 조언한다.",
          DialogueId = 6101207,
          GUID = "0F461346",
          IsKeyOption = true,
          NextDialogue = 6101208,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101208] = {
          ContentKR = "\"그 말이 맞아요.\"\n그녀는 손을 주머니에 넣어, 은색 브로치 하나를 더듬어 꺼낸다.",
          DialogueId = 6101208,
          GUID = "0F461370",
          NextDialogue = 6101209,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101209] = {
          ContentKR = "\"아... 생각났어요.\" 그녀는 조심스럽게 소매 끝으로 브로치를 깨끗이 닦는다. \"이건 제가 그 아이에게 준 선물이에요.\"",
          DialogueId = 6101209,
          GUID = "0F46139A",
          NextDialogue = 6101210,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101210] = {
          ContentKR = "고개를 든 여자의 눈에, 불빛이 또렷이 비친다.",
          DialogueId = 6101210,
          GUID = "0F4613C4",
          NextDialogue = 6101211,
          RougeTalkActorType = 3
        },
        [6101211] = {
          ContentKR = "\"전 제 아이를 찾기 위해 여기 왔어요.\"\n\"그들은 제가 집에 없는 틈을 타, 깊이 잠든 아이를 데리고 갔어요. 그 아이는 어려서부터 낯을 가리는 아이예요. 깨어났을 때 낯익은 얼굴이 보이지 않으면 무서워할 거예요.\"\n\"제가 곁에 있어 줘야 해요... 맞아요, 전 아이를 찾으러 왔어요.\"",
          DialogueId = 6101211,
          GUID = "0F4613EE",
          NextDialogue = 6101212,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101212] = {
          ContentKR = "\"아이가 떠난 지 얼마나 됐나요?\"",
          DialogueId = 6101212,
          GUID = "0F461418",
          NextDialogue = 6101213,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101213] = {
          ContentKR = "\"10일 전... 아니, 10달... 아니, 10년... 아... 생각이 안 나요.\"",
          DialogueId = 6101213,
          GUID = "0F461442",
          NextDialogue = 6101214,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101214] = {
          ContentKR = "여인은 말을 잃은 채, 멍한 얼굴로, 꼼짝도 하지 않는다. 마치 호흡마저 멈춘 것 같다.\n당신이 무슨 말을 해도, 그녀는 아무런 반응이 없다.",
          DialogueId = 6101214,
          GUID = "0F46146C",
          RougeTalkActorType = 3
        },
        [6101301] = {
          ContentKR = "\"펑!\"\n갑자기 눈앞의 모닥불이 더 활활 타오른다.\n금발 소녀가 치맛자락에 황금빛 자갈을 싸서, 자갈을 모닥불 한가운데 하나씩 던져 넣는 게 보인다.",
          DialogueId = 6101301,
          GUID = "0F4622B2",
          NextDialogue = 6101302,
          RougeTalkActorType = 3
        },
        [6101302] = {
          ContentKR = "불빛은 마치 생애 첫 봄을 맞아 미친 듯이 가지를 뻗어 싹을 피우는 초목처럼 점점 거세게 타오른다.",
          DialogueId = 6101302,
          GUID = "0F4622DC",
          NextOptions = {
            [1] = 6101303,
            [2] = 6101305
          },
          RougeTalkActorType = 3
        },
        [6101303] = {
          ContentKR = "불길의 아름다움을 칭찬한다.",
          DialogueId = 6101303,
          GUID = "0F462306",
          IsKeyOption = true,
          NextDialogue = 6101304,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101304] = {
          ContentKR = "\"맞아요!\" 그녀가 불길처럼 뜨겁게 말한다. \"저와 같은 생각을 하는 사람을 만나서 기뻐요.\"",
          DialogueId = 6101304,
          GUID = "0F462330",
          NextDialogue = 6101307,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01"
        },
        [6101305] = {
          ContentKR = "돌이 어디서 났는지 묻는다.",
          DialogueId = 6101305,
          GUID = "0F46235A",
          IsKeyOption = true,
          NextDialogue = 6101306,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101306] = {
          ContentKR = "\"근처에서 주운 돌이에요.\" 그녀가 설명한다. \"제 생각엔 이 돌들이 어떤 화염 마법 수정이 아닌가 싶어요.\"",
          DialogueId = 6101306,
          GUID = "0F462384",
          NextDialogue = 6101307,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01"
        },
        [6101307] = {
          ContentKR = "소녀는 계속 돌멩이를 던진다. 착시인지는 몰라도, 불길이 소녀에게 점점 다가오며, 금빛 머리카락을 부드럽게 핥는 듯하다.",
          DialogueId = 6101307,
          GUID = "0F4623AE",
          NextDialogue = 6101308,
          RougeTalkActorType = 3
        },
        [6101308] = {
          ContentKR = "\"내일이면 모닥불은 원래대로 돌아가고, 이 자갈들은 다시 근처에 흩어질 거예요.\"\n\"그래서 전 이 돌을 매일 주워서 다시 던져야 해요. 총 146개에서 한 개도 빠지면 안 돼요.\"",
          DialogueId = 6101308,
          GUID = "0F4623D8",
          NextDialogue = 6101309,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01"
        },
        [6101309] = {
          ContentKR = "\"무의미한 일 아닐까요?\"",
          DialogueId = 6101309,
          GUID = "0F462402",
          NextDialogue = 6101310,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101310] = {
          ContentKR = "소녀는 고개를 갸웃하더니, 눈을 깜박이며, 천진난만한 미소를 짓는다.",
          DialogueId = 6101310,
          GUID = "0F46242C",
          NextDialogue = 6101311,
          RougeTalkActorType = 3
        },
        [6101311] = {
          ContentKR = "\"아뇨, 저는 불을 좋아해요.\" 그녀가 말한다. \"저는 불이 춤추듯 타오를 때의 모습을 보며 거센 불길 소리를 듣는 게 좋아요.\"\n\"아시겠지만 여긴 혼란스러운 공간이잖아요. 눈을 감아도 모닥불이 곁에 있고, 깨어나 보면 호수 밑바닥에 있죠.\"\n\"하지만 이 돌멩이들은 달라요. 주변이 어떻게 변하든, 이것들은 항상 다시 나타나죠. 내일도 이 돌멩이들을 찾아낼 수 있다고 생각하면 안심하고 잠들 수 있어요.\"",
          DialogueId = 6101311,
          GUID = "0F462456",
          NextDialogue = 6101312,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01"
        },
        [6101312] = {
          ContentKR = "\"저는 확실한 것들이 좋아요.\"",
          DialogueId = 6101312,
          GUID = "0F462480",
          NextDialogue = 6101313,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01"
        },
        [6101313] = {
          ContentKR = "소녀는 그 말과 함께 마지막 돌을 던진다.\n불빛이 그녀를 완전히 감싸고, 금빛 머리카락이 불꽃과 하나가 되어 더 이상 경계를 분간할 수 없게 되었다.",
          DialogueId = 6101313,
          GUID = "0F4624AA",
          RougeTalkActorType = 3
        },
        [6101401] = {
          ContentKR = "\"우... 어...\"",
          DialogueId = 6101401,
          GUID = "0F46331A",
          NextDialogue = 6101402,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01"
        },
        [6101402] = {
          ContentKR = "아래쪽에서 약한 신음소리가 들려온다. 뼈만 앙상하게 남은 남자가 모닥불 옆에 쓰러져 있는 게 보인다. 오랫동안 굶은 것 같다.",
          DialogueId = 6101402,
          GUID = "0F463344",
          NextOptions = {
            [1] = 6101403,
            [2] = 6101409
          },
          RougeTalkActorType = 3
        },
        [6101403] = {
          ContentKR = "음식을 조금 나누어 준다.",
          DialogueId = 6101403,
          GUID = "0F46336E",
          IsKeyOption = true,
          NextDialogue = 6101404,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101404] = {
          ContentKR = "\"...고맙습니다, 좋은 분이시네요. 하지만 저는 음식이 필요 없어요.\"\n\"전 검은 물결에 휩쓸려 들어왔어요. 이미 돌아갈 수 없죠. 음식을 아무리 먹어도 돌아갈 수 없어요.\"\n\"당신을 보니 엘리시안 소녀 한 명이 생각나네요... 당신처럼 착한 아이였죠.\"",
          DialogueId = 6101404,
          GUID = "0F463398",
          NextDialogue = 6101405,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01"
        },
        [6101405] = {
          ContentKR = "\"금발 머리를 하고 분홍색 돼지를 타고 있었죠. 제가 허기진 채 길을 걷고 있을 때, 저한테 빵 한 조각을 건네줬어요...\"\n\"하지만 그때 전 오만해서, 교회의 자비를 받고 싶지 않았어요. 소녀가 선의란 걸 알면서도 큰 소리로 욕했죠.\"",
          DialogueId = 6101405,
          GUID = "0F4633C2",
          NextDialogue = 6101406,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01"
        },
        [6101406] = {
          ContentKR = "\"제 삶을 돌이켜 보면... 저한테 진심으로 대해준 사람은 그 소녀가 유일했어요.\"\n\"신앙, 인종, 출신... 사람들은 항상 이런 걸로... 자신을 미화하죠... 하지만 아무리 대단한 이름을 가져도, 진정한 선이 가져다주는 빛을 덮을 수는 없어요...\"",
          DialogueId = 6101406,
          GUID = "0F4633EC",
          NextDialogue = 6101407,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01"
        },
        [6101407] = {
          ContentKR = "\"다시 돌아갈 수 있다면... 그 소녀에게 직접 사과하고 싶어요... 하지만, 이미... 기회가 없겠죠...\"",
          DialogueId = 6101407,
          GUID = "0F463416",
          NextDialogue = 6101408,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01"
        },
        [6101408] = {
          ContentKR = "남자의 목소리는 점점 가벼워졌고, 당신이 눈을 깜빡이자 그의 모습은 사라졌다.\n공기 중에 갓 구운 빵의 향기가 풍겨온다.",
          DialogueId = 6101408,
          GUID = "0F463440",
          RougeTalkActorType = 3
        },
        [6101409] = {
          ContentKR = "아무것도 하지 않는다.",
          DialogueId = 6101409,
          GUID = "0F46346A",
          IsKeyOption = true,
          NextDialogue = 6101410,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101410] = {
          ContentKR = "불쌍해 보이긴 하지만, 당신도 보급품이 얼마 남지 않았다.\n이 험난한 심연에선, 먼저 자신부터 살아남아야 한다.",
          DialogueId = 6101410,
          GUID = "0F463494",
          RougeTalkActorType = 3
        },
        [6101501] = {
          ContentKR = "한 줄기 금빛이 공중에서 번뜩인다. 태양이 떠오르는 줄 알았지만 자세히 보니 온몸이 황금빛인 새 한 마리다.\n새는 공중을 빙빙 돌며 내려와 당신 곁에 우아하게 날개를 접고 앉는다. 금빛 깃털이 모닥불에 비쳐, 귀족 소녀가 아끼는 금장식보다 더 섬세하게 빛난다.",
          DialogueId = 6101501,
          GUID = "0F464382",
          NextOptions = {
            [1] = 6101502,
            [2] = 6101505,
            [3] = 6101509
          },
          RougeTalkActorType = 3
        },
        [6101502] = {
          ContentKR = "새에게 물을 먹인다.",
          DialogueId = 6101502,
          GUID = "0F4643AC",
          IsKeyOption = true,
          NextDialogue = 6101503,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101503] = {
          ContentKR = "당신은 손바닥에 물을 조금 붓고, 새에게 오라고 손짓한다.",
          DialogueId = 6101503,
          GUID = "0F4643D6",
          NextDialogue = 6101504,
          RougeTalkActorType = 3
        },
        [6101504] = {
          ContentKR = "새는 고개를 갸웃거리며 경계 태세로 당신을 관찰한다. 잠시 후 새는 금빛 부리를 내밀고 손바닥 위의 물을 작은 입으로 홀짝홀짝 마신다.\n물을 다 마시자, 새는 즐겁게 깃털을 펄럭이고, 당신에게 감사하다는 듯 소리를 낸 후, 하늘로 빙빙 돌아 날아간다.",
          DialogueId = 6101504,
          GUID = "0F464400",
          RougeTalkActorType = 3
        },
        [6101505] = {
          ContentKR = "새의 꽁무니에서 깃털 하나를 뽑는다.",
          DialogueId = 6101505,
          GUID = "0F46442A",
          IsKeyOption = true,
          NextDialogue = 6101506,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101506] = {
          ContentKR = "새가 눈을 감고 쉬고 있을 때, 조용히 손을 뻗어 꼬리 깃털 하나를 뽑는다. 상등품 황금 같은 깃털이니 분명히 가치가 훌륭할 것이다.",
          DialogueId = 6101506,
          GUID = "0F464454",
          NextDialogue = 6101507,
          RougeTalkActorType = 3
        },
        [6101507] = {
          ContentKR = "새는 화가 나서 소리를 지르고, 날개를 퍼덕이며 날아든다. 그리곤 당신의 손바닥에 금으로 된 용암을 떨어뜨리듯 온 힘을 다해 쪼아대, 손바닥에 선명한 붉은 자국을 남긴다.",
          DialogueId = 6101507,
          GUID = "0F46447E",
          NextDialogue = 6101508,
          RougeTalkActorType = 3
        },
        [6101508] = {
          ContentKR = "지독한 고통에서 정신을 차렸을 때, 새는 이미 먼 곳으로 날아가 버렸다.",
          DialogueId = 6101508,
          GUID = "0F4644A8",
          RougeTalkActorType = 3
        },
        [6101509] = {
          ContentKR = "새의 머리에서 깃털 하나를 뽑는다.",
          DialogueId = 6101509,
          GUID = "0F4644D2",
          IsKeyOption = true,
          NextDialogue = 6101510,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101510] = {
          ContentKR = "살며시 새의 머리 가까이 손을 뻗어보지만, 힘을 주기도 전에 새가 당신의 의도를 알아채고 눈을 뜬다.\n새는 화가 나서 소리를 지르고, 날개를 퍼덕이며 날아든다. 그리곤 당신의 손바닥에 금으로 된 용암을 떨어뜨리듯 온 힘을 다해 쪼아대, 손바닥에 선명한 붉은 자국을 남긴다.",
          DialogueId = 6101510,
          GUID = "0F4644FC",
          NextDialogue = 6101511,
          RougeTalkActorType = 3
        },
        [6101511] = {
          ContentKR = "지독한 고통에서 정신을 차렸을 때, 새는 이미 먼 곳으로 날아가 버렸다.",
          DialogueId = 6101511,
          GUID = "0F464526",
          RougeTalkActorType = 3
        },
        [6101601] = {
          ContentKR = "근처에서 더러운 썩은 내가 풍겨온다.\n쳐다보니 어린 소녀가 모닥불 가까이에서 나타나는 게 보인다. 빰과 팔뚝은 무시무시한 종기가 가득하다. 모닥불에 반사된 눈동자의 생명의 빛이 아니었다면, 당신은 눈앞에 보이는 게 시체라고 생각했을 것이다.",
          DialogueId = 6101601,
          GUID = "0F4653EA",
          NextOptions = {
            [1] = 6101602,
            [2] = 6101606,
            [3] = 6101612
          },
          RougeTalkActorType = 3
        },
        [6101602] = {
          ContentKR = "당신은 배낭에서 약을 찾아내, 소녀에게 건네준다.",
          DialogueId = 6101602,
          GUID = "0F465414",
          IsKeyOption = true,
          NextDialogue = 6101603,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101603] = {
          ContentKR = "\"감사합니다... 친절한 여행자님...\"\n그녀는 천천히 고개를 들어 당신을 바라본다. 입가에 맺힌 미소가 진짜 웃음인지, 아니면 통증으로 인한 근육의 뒤틀림인지 확실하지 않다.",
          DialogueId = 6101603,
          GUID = "0F46543E",
          NextDialogue = 6101604,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room316_Char01"
        },
        [6101604] = {
          ContentKR = "\"하지만 도와주지... 않으셔도 돼요...\" 그녀가 낮은 목소리로 말한다. \"사제님께서, 전 저주를 받아 심연병에 걸린 거라고 하셨어요. 제가 받아야 할 죄업이래요...\"\n\"저는 진심으로 참회해야 해요... 그러면, 다 나을 거예요... 그전까진 누구에게도 가까이 가면 안 돼요.\"",
          DialogueId = 6101604,
          GUID = "0F465468",
          NextDialogue = 6101605,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room316_Char01"
        },
        [6101605] = {
          ContentKR = "소녀는 비틀거리며 몸을 일으켜, 어둠 속으로 사라졌다.",
          DialogueId = 6101605,
          GUID = "0F465492",
          RougeTalkActorType = 3
        },
        [6101606] = {
          ContentKR = "소녀의 상처를 치료해 본다.",
          DialogueId = 6101606,
          GUID = "0F4654BC",
          IsKeyOption = true,
          NextDialogue = 6101607,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101607] = {
          ContentKR = "당신은 조심스럽게 소녀에게 다가가, 그녀의 몸에 난 상처의 상태를 확인하려고 한다.",
          DialogueId = 6101607,
          GUID = "0F4654E6",
          NextDialogue = 6101608,
          RougeTalkActorType = 3
        },
        [6101608] = {
          ContentKR = "\"콜록, 콜록...!\"\n그녀가 강하게 기침을 하자, 검붉은 피가 당신이 내민 손에 튀며, 불길한 검은 연기가 피어오른다.",
          DialogueId = 6101608,
          GUID = "0F465510",
          NextDialogue = 6101609,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room316_Char01"
        },
        [6101609] = {
          ContentKR = "\"죄, 죄송해요...!\"\n그녀는 비틀거리며 몸을 일으켜 뒤로 물러나려 하지만, 또 실수로 땅에 넘어지고 만다.",
          DialogueId = 6101609,
          GUID = "0F46553A",
          NextDialogue = 6101610,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room316_Char01"
        },
        [6101610] = {
          ContentKR = "\"사제님께서, 전 저주를 받아 심연병에 걸린 거라고 하셨어요. 제가 받아야 할 죄업이래요...\"\n\"저는 진심으로 참회해야 해요... 그러면, 다 나을 거예요... 그전까진 누구에게도 가까이 가면 안 돼요.\"",
          DialogueId = 6101610,
          GUID = "0F465564",
          NextDialogue = 6101611,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room316_Char01"
        },
        [6101611] = {
          ContentKR = "소녀는 다시 힘겹게 일어나 비틀거리며, 어둠 속으로 사라졌다.",
          DialogueId = 6101611,
          GUID = "0F46558E",
          RougeTalkActorType = 3
        },
        [6101612] = {
          ContentKR = "그녀에게서 멀리 떨어진다.",
          DialogueId = 6101612,
          GUID = "0F4655B8",
          IsKeyOption = true,
          NextDialogue = 6101613,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101613] = {
          ContentKR = "당신은 소녀가 어떤 위험한 병에 걸렸을 수도 있음을 직감하고, 얼른 일어나서 그녀에게서 떨어진다.",
          DialogueId = 6101613,
          GUID = "0F4655E2",
          NextDialogue = 6101614,
          RougeTalkActorType = 3
        },
        [6101614] = {
          ContentKR = "\"놀라게 해서 죄송해요... 어, 얼른 다른 곳으로 갈게요...\"",
          DialogueId = 6101614,
          GUID = "0F46560C",
          NextDialogue = 6101615,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room316_Char01"
        },
        [6101615] = {
          ContentKR = "소녀는 비틀거리며 몸을 일으켜, 어둠 속으로 사라졌다.",
          DialogueId = 6101615,
          GUID = "0F465636",
          RougeTalkActorType = 3
        },
        [6101701] = {
          ContentKR = "당신은 모닥불 옆에 앉아서 쉬며, 들고 있던 랜턴을 발 옆에 놓는다.\n손가락을 랜턴에서 떼는 순간, 땅에 갑자기 물빛이 번진다. 반응할 겨를도 없이, 램프가 물속에서 소용돌이치며 삼켜진다.",
          DialogueId = 6101701,
          GUID = "0F466452",
          NextDialogue = 6101702,
          RougeTalkActorType = 3
        },
        [6101702] = {
          ContentKR = "우스꽝스러운 새 마스크를 쓴 사람이 물속에서 몸을 반쯤 내밀고 머리를 흔들더니, 두 팔을 벌린다. 그러자 모양은 같고 재질이 다른 세 개의 랜턴이 물 위에 떠오른다.",
          DialogueId = 6101702,
          GUID = "0F46647C",
          NextDialogue = 6101703,
          RougeTalkActorType = 3
        }
      }
    end
  },
  {
    MinKey = 6101703,
    MaxKey = 6200220,
    Loader = function()
      return {
        [6101703] = {
          ContentKR = "\"안녕? 친애하는 여행자! 실례지만 네가 떨어뜨린 것은 이 황금 랜턴일까? 아니면 이 나무 랜턴일까? 아니면 이 일반 랜턴일까?\"",
          DialogueId = 6101703,
          GUID = "0F4664A6",
          NextOptions = {
            [1] = 6101704,
            [2] = 6101707,
            [3] = 6101710
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room317_Char01"
        },
        [6101704] = {
          ContentKR = "황금 랜턴.",
          DialogueId = 6101704,
          GUID = "0F4664D0",
          IsKeyOption = true,
          NextDialogue = 6101705,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101705] = {
          ContentKR = "\"아하하하!\" 그가 한바탕 과장되게 크게 웃는다. \"좋아, 마음에 들어! 좋은 물건을 만나면, 수단과 방법을 가리지 않고 쟁취해야지!\"\n\"마음대로 가져가, 여행자! 누가 반짝이는 금을 싫어하겠어. 안 그래?\"",
          DialogueId = 6101705,
          GUID = "0F4664FA",
          NextDialogue = 6101706,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room317_Char01"
        },
        [6101706] = {
          ContentKR = "그는 물속으로 뛰어들었고, 수면은 곧 사라졌다.\n아래를 보니 랜턴은 아직 당신의 발밑에 멀쩡히 놓여 있었지만, 주위에는 온통 잿불이 흩어져 있었다.",
          DialogueId = 6101706,
          GUID = "0F466524",
          RougeTalkActorType = 3
        },
        [6101707] = {
          ContentKR = "나무 랜턴.",
          DialogueId = 6101707,
          GUID = "0F46654E",
          IsKeyOption = true,
          NextDialogue = 6101708,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101708] = {
          ContentKR = "\"오? 재미있는 친구네!\" 그는 고개를 갸웃거리며 예측할 수 없는 눈빛을 보인다. \"나무는 확실히 랜턴으로 사용할 수 없어. 하지만 여기는 심연인데 안 될 게 뭐 있지? 불가능한 일은 없어!\"\n\"축복할게, 여행자! 넌 반드시 재미있는 여행길에 오를 거야.\"",
          DialogueId = 6101708,
          GUID = "0F466578",
          NextDialogue = 6101709,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room317_Char01"
        },
        [6101709] = {
          ContentKR = "그는 물속으로 뛰어들었고, 수면은 곧 사라졌다.\n아래를 보니 랜턴은 아직 당신의 발밑에 멀쩡히 놓여 있었지만, 주위에는 온통 유물이 흩어져 있었다.",
          DialogueId = 6101709,
          GUID = "0F4665A2",
          RougeTalkActorType = 3
        },
        [6101710] = {
          ContentKR = "일반 랜턴.",
          DialogueId = 6101710,
          GUID = "0F4665CC",
          IsKeyOption = true,
          NextDialogue = 6101711,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101711] = {
          ContentKR = "\"예, 예, 너희들은 모두 교회에서 바보 같은 가르침을 받았구나.\" 그는 당신의 대답이 매우 불만인지 연신 한숨을 쉰다. \"솔직히 말하면, 정말 재미없어. 다른 랜턴으로 바꾸고 싶지 않아?\"",
          DialogueId = 6101711,
          GUID = "0F4665F6",
          NextDialogue = 6101712,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room317_Char01"
        },
        [6101712] = {
          ContentKR = "\"알았어, 알았어.\" 그가 고개를 가로젓는다. \"솔직한 게 미덕인 거지? 처음 말한 대로 약간의 보상을 줄게.\"",
          DialogueId = 6101712,
          GUID = "0F466620",
          NextDialogue = 6101713,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room317_Char01"
        },
        [6101713] = {
          ContentKR = "그는 물속으로 뛰어들었고, 수면은 곧 사라졌다.\n아래를 보니 랜턴은 아직 당신의 발밑에 멀쩡히 놓여 있었지만, 랜턴의 빛은 확실히 더 밝아졌다.",
          DialogueId = 6101713,
          GUID = "0F46664A",
          RougeTalkActorType = 3
        },
        [6101801] = {
          ContentKR = "당신은 모닥불 옆에 앉아 휴식을 취하고 있다.\n갑자기, 어디선가 이상한 소리가 들려온다. 소리는 바로 귓가에서 들려오는 듯하다가, 이내 점점 멀어져 머리 위로 옮겨간다.\n그리곤 조금씩 커지며, 부드러운 무언가가 사락대는 소리를 낸다.",
          DialogueId = 6101801,
          GUID = "0F4674BA",
          NextDialogue = 6101802,
          RougeTalkActorType = 3
        },
        [6101802] = {
          ContentKR = "\"안녕! 운 좋은 여행자!\"",
          DialogueId = 6101802,
          GUID = "0F4674E4",
          NextDialogue = 6101803,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6101803] = {
          ContentKR = "알록달록한 깃털이 머리 위에서 팔랑팔랑 떨어져 내린다. 심연에서 이렇게 다양한 색깔을 보는 건 이번이 처음이다.\n바닥에 수북이 쌓인 깃털 더미에 둘러싸인 지금 모습을 보니, 마치 거리의 장난꾸러기 꼬마들에게 걸려든 운 없는 행인 같아 어색하기도 하고, 왠지 처량함도 느껴진다.",
          DialogueId = 6101803,
          GUID = "0F46750E",
          NextDialogue = 6101804,
          RougeTalkActorType = 3
        },
        [6101804] = {
          ContentKR = "\"아니, 왜 이렇게 반응이 없어? 심연에 이렇게 오래 있었는데, 지겹지도 않아?\"\n우스꽝스러운 새 머리 가면을 쓴 사람이 위에서부터 스르륵 내려와, 당신과 눈높이를 맞춘다.\n대체 어떻게 저런 자세를 유지하는 건지는 알 수 없지만, 그건 중요하지 않다. 중요한 건, 저 가면의 뾰족한 뿌리가 당신의 얼굴을 찌를 것만 같다는 사실이다.",
          DialogueId = 6101804,
          GUID = "0F467538",
          NextOptions = {
            [1] = 6101805
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6101805] = {
          ContentKR = "그쪽이랑 같이 놀아 줄 시간 없어요.",
          DialogueId = 6101805,
          GUID = "0F467562",
          NextDialogue = 6101806,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101806] = {
          ContentKR = "\"너무 쌀쌀맞게 그러지 마. 교회 늙은이들이 하루에 착한 일을 하나 하면, 그게 다 복으로 돌아온다고 알려 줬을 거 아냐.\"\n\"나하고 <H>게임</> 하자. 이기면 상을 줄 거고, 져도 아무런 벌칙은 없어. 완전히 남는 장사잖아, 어때?\"",
          DialogueId = 6101806,
          GUID = "0F46758C",
          NextOptions = {
            [1] = 6101807,
            [2] = 6101808
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6101807] = {
          ContentKR = "알겠어요.",
          DialogueId = 6101807,
          GUID = "0F4675B6",
          IsKeyOption = true,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101808] = {
          ContentKR = "저 진짜 시간 없어요.",
          DialogueId = 6101808,
          GUID = "0F4675E0",
          IsKeyOption = true,
          NextDialogue = 6101809,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101809] = {
          ContentKR = "\"그래, 알겠어. 나도 싫다는 사람 억지로 시키는 그런 못된 녀석은 아니야.\"\n\"그럼 나중에 또 보자고!\"",
          DialogueId = 6101809,
          GUID = "0F46760A",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6101901] = {
          ContentKR = "타오르는 모닥불 너머로, 노인의 주름진 얼굴이 드러난다.\n손에 쇠망치를 쥔 노인의 발치에는 무기 몇 자루가 흩어져 있다.\n당신을 보자, 노인의 눈이 미묘하게 커진다.",
          DialogueId = 6101901,
          GUID = "0F468522",
          NextDialogue = 6101902,
          RougeTalkActorType = 3
        },
        [6101902] = {
          ContentKR = "\"젊은이, 혹시 엘리시안으로 가는 길이 어느 쪽인지 아나?\"\n노인이 입을 열자, 메마르고 잠긴 목소리가 새어 나온다.\n\"이 근처를 몇 바퀴나 돌았는데, 도무지 집으로 가는 길을 찾을 수가 없구먼...\"",
          DialogueId = 6101902,
          GUID = "0F46854C",
          NextOptions = {
            [1] = 6101903
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01"
        },
        [6101903] = {
          ContentKR = "아무 말도 하지 않는다.",
          DialogueId = 6101903,
          GUID = "0F468576",
          NextDialogue = 6101904,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101904] = {
          ContentKR = "\"그런가... 자네도 길을 잃었나 보구먼...\"\n노인은 길게 한숨을 내쉬며, 힘없이 고개를 떨군다.",
          DialogueId = 6101904,
          GUID = "0F4685A0",
          NextOptions = {
            [1] = 6101905
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01"
        },
        [6101905] = {
          ContentKR = "노인에게 무기를 하나 줄 수 있는지 묻는다.",
          DialogueId = 6101905,
          GUID = "0F4685CA",
          NextDialogue = 6101906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101906] = {
          ContentKR = "\"무기? 바닥에 있는 이것들 말인가?\"\n\"으흠... 이제야 기억이 나는군. 난... 대장장이야.\"\n\"사람들이 도망칠 수 있게 무기를 만들어 줬지. 그리고...\"",
          DialogueId = 6101906,
          GUID = "0F4685F4",
          NextDialogue = 6101907,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01"
        },
        [6101907] = {
          ContentKR = "순간, 자신이 이곳에 온 이유가 생각난 듯, 노인의 눈빛이 순간 흐릿해진다.\n그는 곧 고개를 가로젓고는, 씁쓸한 미소를 지어 보인다.",
          DialogueId = 6101907,
          GUID = "0F46861E",
          NextDialogue = 6101908,
          RougeTalkActorType = 3
        },
        [6101908] = {
          ContentKR = "\"당연히 줄 수 있다네, 젊은이.\"\n\"마음 가는 대로 고르게나. 그 무기가 자네를 지켜 줄 수 있기를 바라지.\"",
          DialogueId = 6101908,
          GUID = "0F468648",
          NextOptions = {
            [1] = 6101909,
            [2] = 6101910
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01"
        },
        [6101909] = {
          ContentKR = "노인의 왼쪽에 있는 무기 중 하나를 고른다.",
          DialogueId = 6101909,
          GUID = "0F468672",
          IsKeyOption = true,
          NextDialogue = 6101911,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101910] = {
          ContentKR = "노인의 오른쪽에 있는 무기 중 하나를 고른다.",
          DialogueId = 6101910,
          GUID = "0F46869C",
          IsKeyOption = true,
          NextDialogue = 6101911,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101911] = {
          ContentKR = "무기를 하나 골라 가방에 챙겼다.\n노인은 이미 당신이 있다는 사실도 잊은 듯, 손에 쥔 쇠망치를 응시하며, 말없이 생각에 잠겨 있다.",
          DialogueId = 6101911,
          GUID = "0F4686C6",
          RougeTalkActorType = 3
        },
        [6102001] = {
          ContentKR = "금속이 부딪치는 소리가 울려 퍼지고, 튀어 오른 불꽃이 모닥불 빛 속으로 녹아든다.\n소리가 들려오는 쪽을 바라보자, 땀을 비 오듯 흘리는 한 노인이 허름한 작업대 앞에서 쇠망치질에 여념이 없다.",
          DialogueId = 6102001,
          GUID = "0F46958A",
          NextDialogue = 6102002,
          RougeTalkActorType = 3
        },
        [6102002] = {
          ContentKR = "\"반갑네, 젊은이!\"\n노인이 호쾌하게 인사를 건넨다.",
          DialogueId = 6102002,
          GUID = "0F4695B4",
          NextOptions = {
            [1] = 6102003
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102003] = {
          ContentKR = "안녕하세요.",
          DialogueId = 6102003,
          GUID = "0F4695DE",
          NextDialogue = 6102004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102004] = {
          ContentKR = "\"자네도 이곳에 발이 묶인 모양이지?\" 노인이 자신을 가리키며 말한다. \"나도 같은 처지라네.\"",
          DialogueId = 6102004,
          GUID = "0F469608",
          NextOptions = {
            [1] = 6102005
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102005] = {
          ContentKR = "또 만났네요, 어르신.",
          DialogueId = 6102005,
          GUID = "0F469632",
          NextDialogue = 6102006,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102006] = {
          ContentKR = "\"우리가 구면이었나?\" 노인이 살짝 당혹스러워하며 말한다. \"내가 요즘 들어갈수록 기억력이 영 시원치 않구먼...\"",
          DialogueId = 6102006,
          GUID = "0F46965C",
          NextDialogue = 6102007,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102007] = {
          ContentKR = "\"이곳은 위험하니, 내가 만든 무기 중 하나를 가져가게나.\"\n노인이 호탕하게 자신의 작품들을 보여 준다.\n\"아무리 용을 써 봐야 여기선 못 나갈 테니, 내 본업에 충실하기로 했다네. 혹시 아나? 내 무기가 어떤 훌륭한 기사님께 도움이 돼서, 우리를 이 지긋지긋한 곳에서 데리고 나가 줄지.\"",
          DialogueId = 6102007,
          GUID = "0F469686",
          NextOptions = {
            [1] = 6102008,
            [2] = 6102009,
            [3] = 6102010
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102008] = {
          ContentKR = "갓 완성된 새 무기 중 하나를 고른다.",
          DialogueId = 6102008,
          GUID = "0F4696B0",
          IsKeyOption = true,
          NextDialogue = 6102011,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102009] = {
          ContentKR = "가지런히 정리된 무기 중 하나를 고른다.",
          DialogueId = 6102009,
          GUID = "0F4696DA",
          IsKeyOption = true,
          NextDialogue = 6102011,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102010] = {
          ContentKR = "먼지 쌓인 구석에 보관된 무기 중 하나를 고른다.",
          DialogueId = 6102010,
          GUID = "0F469704",
          IsKeyOption = true,
          NextDialogue = 6102011,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102011] = {
          ContentKR = "노인의 따뜻한 배웅을 받으며, 당신은 무기를 챙겨 다시 길을 나섰다.",
          DialogueId = 6102011,
          GUID = "0F46972E",
          RougeTalkActorType = 3
        },
        [6102101] = {
          ContentKR = "꺼질 듯한 불빛이 고개 숙인 시인의 옆얼굴을 비춘다.\n여자는 모닥불 옆에 반쯤 무릎을 꿇고 앉아, 손끝으로 천천히 잿더미를 휘저으며 구불구불한 문양을 새긴다.",
          DialogueId = 6102101,
          GUID = "0F46A5F2",
          NextDialogue = 6102102,
          RougeTalkActorType = 3
        },
        [6102102] = {
          ContentKR = "\"피할 수 없다면, 운명을 받아들여라.\"\n\"글이 거짓을 꿰뚫는 칼날이 될 수 없다면, 아름다운 꿈을 쌓아 올릴 벽돌이 되어라...\"\n시인은 잠시 읊조림을 멈추고, 살며시 손끝을 들어 올린다.\n\"으음...\"",
          DialogueId = 6102102,
          GUID = "0F46A61C",
          NextDialogue = 6102103,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102103] = {
          ContentKR = "깊숙이 잠들어 있던 기억이 불현듯 떠오르며, 귀에 익은 시라는 확신이 든다.\n한 줄기 연기와 재가 뺨을 스치자, 당신은 무의식적으로 마지막 빈 구절을 읊는다...",
          DialogueId = 6102103,
          GUID = "0F46A646",
          NextOptions = {
            [1] = 6102104
          },
          RougeTalkActorType = 3
        },
        [6102104] = {
          ContentKR = "\"거짓을 써 내려가, 꺼지지 않는 불꽃을 피워 올려라.\"",
          DialogueId = 6102104,
          GUID = "0F46A670",
          NextDialogue = 6102105,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102105] = {
          ContentKR = "\"어...?!\"\n시인이 고개를 들어, 놀랍다는 표정으로 바라본다.\n\"정말 아름다운 구절이군요! 제가 바라던 마무리였어요! 이런 곳에서 마음이 통하는 분을 만나다니, 정말 행운이네요.\"",
          DialogueId = 6102105,
          GUID = "0F46A69A",
          NextOptions = {
            [1] = 6102106
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102106] = {
          ContentKR = "\"사실 방금 그 구절은 다른 시간대의 당신이 쓴 거예요.\"",
          DialogueId = 6102106,
          GUID = "0F46A6C4",
          NextDialogue = 6102107,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102107] = {
          ContentKR = "\"'다른 시간대'요...?\"\n의아한 표정을 짓던 시인의 눈동자가, 모닥불이 옮겨붙은 듯 반짝인다.\n\"그런 거였군요... 당신은 이 서사시의 주인공이자, 제가 앞으로 어딘가에서 다시 만나게 될 특별한 인물인 거예요, 그렇죠?\"",
          DialogueId = 6102107,
          GUID = "0F46A6EE",
          NextOptions = {
            [1] = 6102108
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102108] = {
          ContentKR = "고개를 끄덕인다.",
          DialogueId = 6102108,
          GUID = "0F46A718",
          NextDialogue = 6102109,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102109] = {
          ContentKR = "\"그렇다면 이 시는 당신이 쓴 걸까요, 아니면 제가 쓴 걸까요? 후후... 정말 매력적인 질문이네요. 성수 아카데미의 학자들도 푹 빠져 버릴 만한 이야기예요.\"\n시인이 재미있다는 듯 소리 내어 웃는다.\n\"다음에 만나면, 시를 한 수 지어 드릴게요. 지금은, 손을 내밀어 제 축복을 받아 주세요.\"",
          DialogueId = 6102109,
          GUID = "0F46A742",
          NextOptions = {
            [1] = 6102110,
            [2] = 6102111
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102110] = {
          ContentKR = "왼손을 내민다.",
          DialogueId = 6102110,
          GUID = "0F46A76C",
          IsKeyOption = true,
          NextDialogue = 6102112,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102111] = {
          ContentKR = "오른손을 내민다.",
          DialogueId = 6102111,
          GUID = "0F46A796",
          IsKeyOption = true,
          NextDialogue = 6102112,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102112] = {
          ContentKR = "시인은 손끝에 남은 잿가루로 당신의 손바닥에 무언가를 적는다.\n글자의 의미는 여전히 헤아릴 수 없지만, 뜨거우면서도 데지 않을 만큼의 선명한 온기가 전해져 온다.\n다시 고개를 들어 보니, 시인은 연기처럼 사라져 버렸다.",
          DialogueId = 6102112,
          GUID = "0F46A7C0",
          RougeTalkActorType = 3
        },
        [6102201] = {
          ContentKR = "\"변덕스러운 운명의 신이시여, 때로는 기쁨을, 때로는 고통을 내리시니...\"\n\"항상 경건한 마음을 잃지 않으면... 순백의 실을 내려 우리를 제천의 하늘 위 낙원으로 이끌어 주시리라...\"\n소년은 당신의 존재조차 알아차리지 못한 채, 진지하고 경건하게 책을 낭독하고 있다.",
          DialogueId = 6102201,
          GUID = "0F46B65A",
          NextDialogue = 6102202,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room321_Char01"
        },
        [6102202] = {
          ContentKR = "당신은 슬그머니 소년의 곁으로 다가가, 재빨리 책을 곁눈질한다.\n당신의 기억 그대로, 책장에 쓰인 성가는 악의에 찬 새카만 글자로 뒤덮여 있다.\n그 글자들은, 종이 밖으로 빠져나오려는 듯 꿈틀거린다.",
          DialogueId = 6102202,
          GUID = "0F46B684",
          NextDialogue = 6102203,
          RougeTalkActorType = 3
        },
        [6102203] = {
          ContentKR = "\"안녕하세요... 혹시 이 책을 읽고 싶으세요?\"\n마침내 인기척을 느낀 소년이 호기심 가득한 눈으로 고개를 든다.",
          DialogueId = 6102203,
          GUID = "0F46B6AE",
          NextOptions = {
            [1] = 6102204,
            [2] = 6102208
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room321_Char01"
        },
        [6102204] = {
          ContentKR = "소년이 책을 더 읽지 못하게 막는다.",
          DialogueId = 6102204,
          GUID = "0F46B6D8",
          IsKeyOption = true,
          NextDialogue = 6102205,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102205] = {
          ContentKR = "당신은 소년에게서 책을 빼앗아, 힘껏 덮어 버린다.",
          DialogueId = 6102205,
          GUID = "0F46B702",
          NextDialogue = 6102206,
          RougeTalkActorType = 3
        },
        [6102206] = {
          ContentKR = "\"괜찮으세요?!\"\n걱정스러운 표정으로 일어난 소년의 시선이, 이내 텅 빈 자기 손으로 향한다.\n\"어? 나... 이제 책 안 읽어도 돼? 나... 이제 자유야?\"",
          DialogueId = 6102206,
          GUID = "0F46B72C",
          NextDialogue = 6102207,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room321_Char01"
        },
        [6102207] = {
          ContentKR = "당신은 손끝의 고통을 삼킨 채, 소년에게 미소를 지으며 고개를 끄덕인 후, 책을 모닥불 속에 던져 넣는다.\n불길이 치솟아 오르고, 화염을 휘감은 검은 가시덩굴이 덮쳐 온다...",
          DialogueId = 6102207,
          GUID = "0F46B756",
          RougeTalkActorType = 3
        },
        [6102208] = {
          ContentKR = "아무 말도 하지 않는다.",
          DialogueId = 6102208,
          GUID = "0F46B780",
          IsKeyOption = true,
          NextDialogue = 6102209,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102209] = {
          ContentKR = "당신은 지금의 행동으로 소년의 운명을 결코 바꿀 수 없다는 사실을 알고 있다.\n게다가 더 중요한 임무가 남아 있다. 당신은 유리를 모아 이 기나긴 악몽을 끝내야만 한다.",
          DialogueId = 6102209,
          GUID = "0F46B7AA",
          NextDialogue = 6102210,
          RougeTalkActorType = 3
        },
        [6102210] = {
          ContentKR = "순식간에 퍼져 나간 검은 가시덩굴이 소년의 모습을 집어삼킨다.\n당신은 얕은 한숨을 내쉬고, 다시 앞으로 발걸음을 옮겼다.",
          DialogueId = 6102210,
          GUID = "0F46B7D4",
          RougeTalkActorType = 3
        },
        [6102301] = {
          ContentKR = "\"아가... 이리 와 보렴. 모닥불이 있단다.\"\n불빛 건너편에 홀로 서 있던 여인이 미소와 함께 고개를 들자, 수척한 얼굴이 불빛에 어린다.\n\"마음씨가 참 고우시네요. 정말 따뜻해요. 감사합니다.\"",
          DialogueId = 6102301,
          GUID = "0F46C6C2",
          NextOptions = {
            [1] = 6102302
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102302] = {
          ContentKR = "아이는 어디에 있는지 묻는다.",
          DialogueId = 6102302,
          GUID = "0F46C6EC",
          NextDialogue = 6102303,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102303] = {
          ContentKR = "\"바로 여기 있는걸요. 자, 보세요.\"",
          DialogueId = 6102303,
          GUID = "0F46C716",
          NextDialogue = 6102304,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102304] = {
          ContentKR = "여인이 가리키는 곳으로 시선을 옮기자, 사람 키 절반만 한 바위 하나가 이끼에 뒤덮여 있다.\n바위 중심보다 조금 위, 갈라진 틈 사이에 브로치 하나가 박혀 있고, 그 주위로 이끼가 빽빽이 자라나, 마치 심장을 감싼 듯 보인다.\n여인은 손에 흙이 묻는 줄도 모른 채, 바위 표면을 부드럽게 어루만진다.",
          DialogueId = 6102304,
          GUID = "0F46C740",
          NextOptions = {
            [1] = 6102305,
            [2] = 6102308
          },
          RougeTalkActorType = 3
        },
        [6102305] = {
          ContentKR = "사실대로 말해 준다.",
          DialogueId = 6102305,
          GUID = "0F46C76A",
          IsKeyOption = true,
          NextDialogue = 6102306,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102306] = {
          ContentKR = "\"무슨 황당한 소리를 하는 건가요?!\"\n순식간에 여인의 눈에 적의가 번뜩인다. 그녀는 아이를 감싸듯 바위를 등 뒤에 숨긴 후, 히스테릭하게 소리치기 시작한다.\n\"이건 내 아이예요... 바로 여기 있잖아요. 이젠 아무한테도 빼앗기지 않을 거예요... 절대로...\"",
          DialogueId = 6102306,
          GUID = "0F46C794",
          NextDialogue = 6102307,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102307] = {
          ContentKR = "당신은 순간적으로 말문이 막힌다.\n저 달콤한 꿈을 헤집는 것은 부질없는 일이었다.\n결국 당신은 여인과 그녀의 '아이'에게 모닥불을 내주려 자리에서 몸을 일으켰다. 바로 그 순간, 어둠 속에 도사리던 그림자가 때를 기다렸다는 듯 덮쳐 온다...",
          DialogueId = 6102307,
          GUID = "0F46C7BE",
          RougeTalkActorType = 3
        },
        [6102308] = {
          ContentKR = "여자의 말에 맞장구친다.",
          DialogueId = 6102308,
          GUID = "0F46C7E8",
          IsKeyOption = true,
          NextDialogue = 6102309,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102309] = {
          ContentKR = "\"고마워요. 원래 낯을 많이 가리는 아이인데, 당신은 마음에 드나 봐요.\"\n여인은 틈틈이 바위를 쓰다듬으며 더없이 온화하게 말한다.\n\"혼자 다니시는 건가요? 저런, 가족들이 많이 걱정하겠네요... 어서 돌아가세요.\"",
          DialogueId = 6102309,
          GUID = "0F46C812",
          NextDialogue = 6102310,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102310] = {
          ContentKR = "당신은 정중히 감사 인사를 건네고 몸을 일으켜 자리를 떠난다.\n등 뒤로, 여인과 그녀의 '아이'의 모습이 모닥불 속으로 점차 희미해진다.",
          DialogueId = 6102310,
          GUID = "0F46C83C",
          RougeTalkActorType = 3
        },
        [6102401] = {
          ContentKR = "\"없어져 버렸어... 안 보여...\"\n텅 빈 눈의 소녀가 땅에 엎드린 채, 손톱으로 땅을 파헤치듯 흙바닥을 더듬고 있다.",
          DialogueId = 6102401,
          GUID = "0F46D72A",
          NextOptions = {
            [1] = 6102402
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102402] = {
          ContentKR = "뭘 찾고 있는지 물어본다.",
          DialogueId = 6102402,
          GUID = "0F46D754",
          NextDialogue = 6102403,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102403] = {
          ContentKR = "\"내 돌멩이... 돌멩이를 찾고 있어... 분명 여기 있었는데...\"\n소녀가 힘없이 중얼거리며, 절망 어린 눈으로 당신 발치의 모닥불을 본다.\n\"내 불꽃이... 꺼지려고 해... 어쩌지... 어떡하면 좋지...\"",
          DialogueId = 6102403,
          GUID = "0F46D77E",
          NextOptions = {
            [1] = 6102404,
            [2] = 6102408
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102404] = {
          ContentKR = "소녀를 도와준다.",
          DialogueId = 6102404,
          GUID = "0F46D7A8",
          IsKeyOption = true,
          NextDialogue = 6102405,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102405] = {
          ContentKR = "소녀가 아끼던 돌멩이의 모양을 떠올려 본다. 어디서 난 건지는 몰라도, 불꽃 마법을 사용하면 비슷한 걸 만들 수 있을 것 같다.\n당신은 모닥불의 기운을 빌려 힘을 모은다...\n금세, 금빛으로 반짝이는 작은 돌들이 유성처럼 쏟아져 내리며, 서로 부딪혀 맑은 소리를 낸다.",
          DialogueId = 6102405,
          GUID = "0F46D7D2",
          NextDialogue = 6102406,
          RougeTalkActorType = 3
        },
        [6102406] = {
          ContentKR = "\"아...! 내 돌멩이! 바로 이거야! 고마워, 신의 전령!\"\n소녀는 마치 소중한 보물을 다루듯, 돌멩이를 하나하나 주워 치맛자락에 조심스레 갈무리한다.",
          DialogueId = 6102406,
          GUID = "0F46D7FC",
          NextDialogue = 6102407,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102407] = {
          ContentKR = "소녀가 품에 안고 있던 돌과 꼭 닮은 결정들을 보니, 문득 저 돌멩이들은 당신이 어느 여정에서 무심결에 흘린 흔적에서 비롯된 건 아닐까 하는 생각이 스친다.\n어쨌든 소녀는 자신만의 '확신'을 되찾았다. 그리고 당신도, 당신의 여정을 계속해야 한다.",
          DialogueId = 6102407,
          GUID = "0F46D826",
          RougeTalkActorType = 3
        },
        [6102408] = {
          ContentKR = "세상일은 늘 뜻대로 되지 않는다고 말해 준다.",
          DialogueId = 6102408,
          GUID = "0F46D850",
          IsKeyOption = true,
          NextDialogue = 6102409,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102409] = {
          ContentKR = "\"알아... 나도 안다고.\"\n\"그래서 다 포기했잖아. 이제 책 같은 건 들여다보지도 않고, 마법의 기원 따위를 궁금해하지도 않아. 저 탑에 뭐가 있는지도 더는 묻지 않는다고...\"\n\"이제 내가 바라는 건 작은 불빛 하나뿐인데, 이것도 안 되는 거야?\"",
          DialogueId = 6102409,
          GUID = "0F46D87A",
          NextDialogue = 6102410,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102410] = {
          ContentKR = "당신은 아무 말도 해 줄 수 없다.\n순간, 소녀가 자리에서 벌떡 일어나더니, 어떻게 해 볼 새도 없이 결연히 불길 속으로 걸어 들어간다.\n이윽고, 소녀의 모습은 이지러지는 불꽃과 하나 되어 사라졌다.\n당신은 몸을 돌려, 다시 갈 길을 재촉한다.",
          DialogueId = 6102410,
          GUID = "0F46D8A4",
          RougeTalkActorType = 3
        },
        [6102501] = {
          ContentKR = "모닥불이 고요히 타오르고, 이번에는 어떤 환영도 비치지 않는다.\n막 자리를 뜨려는 순간, 바닥에서 반짝이는 무언가가 시선을 사로잡는다.\n마치 땅으로 떨어진 별들처럼 여기저기 흩뿌려진 금빛 돌멩이들이다.",
          DialogueId = 6102501,
          GUID = "0F46E792",
          NextOptions = {
            [1] = 6102502,
            [2] = 6102506
          },
          RougeTalkActorType = 3
        },
        [6102502] = {
          ContentKR = "돌멩이를 주워 불길 속으로 던진다.",
          DialogueId = 6102502,
          GUID = "0F46E7BC",
          IsKeyOption = true,
          NextDialogue = 6102503,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102503] = {
          ContentKR = "불길이 거세게 타오르더니, 이내 비정상적으로 퍼져나가기 시작한다.\n당신이 조심스럽게 한 걸음 물러서자, 화염 속에서 어떤 형체가 나타난다. 당신은 그제야 옆으로 뻗어 나가던 빛은 불꽃이 아니라, 소녀의 머리칼이었음을 깨닫는다.",
          DialogueId = 6102503,
          GUID = "0F46E7E6",
          NextDialogue = 6102504,
          RougeTalkActorType = 3
        },
        [6102504] = {
          ContentKR = "\"안녕! 내 돌멩이 찾았구나, 맞지?\"\n소녀가 모닥불 속에서 훌쩍 뛰쳐나와 고개를 흔들자, 금빛 돌멩이들이 짤랑이며 쏟아져 내린다.\n\"이제 밖에서 안 찾아다녀도 돼! 불 속으로 걸어 들어가기만 하면, 나 혼자서도 돌멩이를 만들 수 있거든!\"",
          DialogueId = 6102504,
          GUID = "0F46E810",
          NextDialogue = 6102505,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room324_Char01"
        },
        [6102505] = {
          ContentKR = "\"미안, 길게 얘기할 시간이 없어. 146개를 다 못 모았거든.\"\n\"하지만 쓸모 있을 만한 걸 좀 찾았어. 자, 받아. 여행 잘해!\"\n소녀는 내게 무언가를 억지로 쥐여 주더니, 몸을 휙 돌려 다시 불길 속으로 사라진다.",
          DialogueId = 6102505,
          GUID = "0F46E83A",
          NextDialogue = 6102510,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room324_Char01"
        },
        [6102506] = {
          ContentKR = "조용히 지켜본다.",
          DialogueId = 6102506,
          GUID = "0F46E864",
          IsKeyOption = true,
          NextDialogue = 6102507,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102507] = {
          ContentKR = "불길은 여전히 소리 없이 너울거리고, 그 일렁임 속에서 어렴풋이 어떤 소리가 들려온다.",
          DialogueId = 6102507,
          GUID = "0F46E88E",
          NextDialogue = 6102508,
          RougeTalkActorType = 3
        },
        [6102508] = {
          ContentKR = "\"응... 그래. 기억할게.\"\n불길 너머로 소녀의 행복에 젖은 평온한 목소리가 들려온다.\n\"궁금증도 적당히 해야 하니까. 불은 신의 선물이지, 물질의 반응이 아니야. 이 돌멩이들처럼 말이지. 난 신께서 주신 이 보물들 덕분에, 편히 잠들 수 있어...\"",
          DialogueId = 6102508,
          GUID = "0F46E8B8",
          NextDialogue = 6102509,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room324_Char01"
        },
        [6102509] = {
          ContentKR = "말없이 몸을 돌려 내디딘 첫걸음에, 마침 발치로 굴러온 돌멩이 하나가 힘없이 바스러진다.\n신이 내린 보물은, 이렇게나 연약했던 것이다.",
          DialogueId = 6102509,
          GUID = "0F46E8E2",
          NextDialogue = 6102510,
          RougeTalkActorType = 3
        },
        [6102510] = {
          ContentKR = "문득 저 불꽃이 소녀에게 행복한 '확신'을 안겨 준 것인지, 아니면 그녀를 이곳에 영원히 옭아맬 '족쇄'가 된 것인지 궁금해진다.\n어쩌면, 그 둘 사이엔 처음부터 아무 차이가 없었는지도 모른다.",
          DialogueId = 6102510,
          GUID = "0F46E90C",
          RougeTalkActorType = 3
        },
        [6102601] = {
          ContentKR = "\"죄송해요. 제가 다 잘못했어요... 멍청해서 성가도 다 못 외우고... 게을러서 설교도 끝까지 못 들었어요...\"\n\"신이시여, 부디 절 용서해 주세요...\"",
          DialogueId = 6102601,
          GUID = "0F46F7FA",
          NextDialogue = 6102602,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102602] = {
          ContentKR = "소녀는 자신만의 세계에 갇혀 기도에 매달리고 있다. 어쩌면, 정말 이제 더는 다른 이가 보이지 않게 된 건지도 모른다.\n한층 깊어진 병세로 소녀의 두 눈은 생기라곤 찾아볼 수 없는 잿빛이 되었다.",
          DialogueId = 6102602,
          GUID = "0F46F824",
          NextDialogue = 6102603,
          RougeTalkActorType = 3
        },
        [6102603] = {
          ContentKR = "\"혹시... 그때 그 여행자님이세요? 벌써... 시간이 많이 흐른 거예요?\"\n마침내 인기척을 느낀 소녀가 천천히 고개를 돌린다.\n\"여행자님... 제발 가르쳐 주세요... 밤낮으로 신께 기도드리고 있는데, 왜 단 한 번도 답해 주시지 않는 걸까요?\"",
          DialogueId = 6102603,
          GUID = "0F46F84E",
          NextOptions = {
            [1] = 6102604,
            [2] = 6102608
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102604] = {
          ContentKR = "계속 기도하라고 응원한다.",
          DialogueId = 6102604,
          GUID = "0F46F878",
          IsKeyOption = true,
          NextDialogue = 6102605,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102605] = {
          ContentKR = "아직 결말을 고쳐 쓸 때가 아니라면, 거짓을 이어 나가는 편이 나으리라... 적어도 일종의 '희망'이니까.\n당신은 소녀에게 계속 기도하면 언젠가 다들 구원받을 것이라 말한다.\n언젠가는 심연을 이겨낼 테니, 아주 틀린 말은 아니다. 단지, 소녀의 기도는 무의미하고, 진정한 해답은 당신이 손에 든 이 랜턴에 있을 뿐이다.",
          DialogueId = 6102605,
          GUID = "0F46F8A2",
          NextDialogue = 6102606,
          RougeTalkActorType = 3
        },
        [6102606] = {
          ContentKR = "\"알겠어요... 믿을게요.\"\n소녀는 굳은 의지를 실은 채, 두 손을 마주 잡고 다시 나지막이 기도를 올린다.",
          DialogueId = 6102606,
          GUID = "0F46F8CC",
          NextDialogue = 6102607,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102607] = {
          ContentKR = "당신은 가볍게 한숨을 내쉬고, 랜턴을 힘껏 쥔 채 앞으로 나아간다.",
          DialogueId = 6102607,
          GUID = "0F46F8F6",
          RougeTalkActorType = 3
        },
        [6102608] = {
          ContentKR = "신은 응답하지 않을 것이라고 말한다.",
          DialogueId = 6102608,
          GUID = "0F46F920",
          IsKeyOption = true,
          NextDialogue = 6102609,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102609] = {
          ContentKR = "\"아무 답도... 해 주지 않으실 거라고요?\"\n\"제 죄가 너무 깊어서, 구원받을 자격조차 없는 거예요?\"\n절망에 찬 눈으로 당신을 바라보는 소녀의 고름과 딱지가 가득한 뺨 위로 눈물이 흘러내린다.",
          DialogueId = 6102609,
          GUID = "0F46F94A",
          NextOptions = {
            [1] = 6102610
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102610] = {
          ContentKR = "\"넌 애초에 죄를 짓지 않았으니까.\"",
          DialogueId = 6102610,
          GUID = "0F46F974",
          NextDialogue = 6102611,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102611] = {
          ContentKR = "\"네...?\"\n소녀의 두 눈이 잠시 멍해졌다가, 당혹스러움이 감돈다.",
          DialogueId = 6102611,
          GUID = "0F46F99E",
          NextDialogue = 6102612,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102612] = {
          ContentKR = "당신은 반드시 이 고통을 끝낼 방법을 찾아내겠다는 무언의 맹세를 담아, 소녀를 향해 결의에 찬 미소를 지어 보인다.\n알 듯 말 듯 고개를 끄덕이는 소녀의 상처에서, 더는 피가 배어 나오지 않는다.\n당신은 손을 흔들어 소녀에게 작별을 고한 뒤, 손안의 랜턴을 단단히 움켜쥔 채 다시 앞으로 나아간다.",
          DialogueId = 6102612,
          GUID = "0F46F9C8",
          RougeTalkActorType = 3
        },
        [6102701] = {
          ContentKR = "\"만월의 여신 포르소시여...\"\n\"찬란한 발자취의 주인이자, 운명의 실을 잣는 분이시여...\"\n\"드높은 하늘과 달빛 아래, 경건한 믿음의 노래를 바치나이다...\"",
          DialogueId = 6102701,
          GUID = "0F470862",
          NextDialogue = 6102702,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room326_Char01"
        },
        [6102702] = {
          ContentKR = "일렁이는 불길 너머 사람들의 형체가 어른거리고, 신을 향한 기도가 하나의 목소리가 되어 울려 퍼진다.",
          DialogueId = 6102702,
          GUID = "0F47088C",
          NextDialogue = 6102703,
          RougeTalkActorType = 3
        },
        [6102703] = {
          ContentKR = "\"누구시죠? 혹시 길을 잃으셨나요?\"\n기도하던 사람 중 하나가 당신을 발견하곤, 미소 지으며 손을 내민다.\n\"저희와 함께 만월의 여신님께 기도드리지 않겠어요? 당신의 앞길을 축복해 주실 거예요!\"",
          DialogueId = 6102703,
          GUID = "0F4708B6",
          NextDialogue = 6102704,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room326_Char01"
        },
        [6102704] = {
          ContentKR = "이들은 <H>아홉 번째 신</>이자 운명의 신 <H>포르소</>에게 찬가를 바치고 있었다.\n만월의 주인 포르소는, 달빛을 모아 운명의 실을 잣는 신이다.",
          DialogueId = 6102704,
          GUID = "0F4708E0",
          NextOptions = {
            [1] = 6102705,
            [2] = 6102709
          },
          RougeTalkActorType = 3
        },
        [6102705] = {
          ContentKR = "기도에 동참한다.",
          DialogueId = 6102705,
          GUID = "0F47090A",
          IsKeyOption = true,
          NextDialogue = 6102706,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102706] = {
          ContentKR = "어릴 적엔 가장 싫어하던 시간이었다. 아름답지만 무의미한 말들의 집합이라고 치부하며, 외우자마자 잊어버렸던 기도가 지금은 왠지 그리워진다.\n당신은 그들과 함께 기도를 시작한다.",
          DialogueId = 6102706,
          GUID = "0F470934",
          NextDialogue = 6102707,
          RougeTalkActorType = 3
        },
        [6102707] = {
          ContentKR = "\"포르소, 무질서한 운명의 흐름에서 영원히 창공을 가로지르는 만월의 신이시여.\"\n\"바라옵건대, 당신의 신도들을 굽어살피시고.\"\n\"저희에게 위없는 행운과 복을 내려 주시옵소서.\"",
          DialogueId = 6102707,
          GUID = "0F47095E",
          NextDialogue = 6102708,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102708] = {
          ContentKR = "당신은 두 눈을 감고 경건한 신도들을 따라 속으로 기도를 읊조린다.\n마지막 구절이 끝나고 눈을 뜨자, 그들은 흔적도 없이 사라진 채였다.",
          DialogueId = 6102708,
          GUID = "0F470988",
          RougeTalkActorType = 3
        },
        [6102709] = {
          ContentKR = "기도에 동참하지 않는다.",
          DialogueId = 6102709,
          GUID = "0F4709B2",
          IsKeyOption = true,
          NextDialogue = 6102710,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102710] = {
          ContentKR = "\"거절하겠다고요? 어째서죠?\"\n기도하던 사람 중 하나가 날카롭게 외친다.\n\"이단이다! 암월파의 신도냐? 아니면 네파의 추종자냐?\"",
          DialogueId = 6102710,
          GUID = "0F4709DC",
          NextDialogue = 6102711,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room326_Char01"
        },
        [6102711] = {
          ContentKR = "결코 입에 담아서는 안 될 이름이 들리자, 신도들이 살기 등등한 얼굴로 일제히 당신을 돌아본다.\n당신은 한숨을 내쉰다. 어떻게든 이 포위망을 빠져나가야 한다.",
          DialogueId = 6102711,
          GUID = "0F470A06",
          RougeTalkActorType = 3
        },
        [6102801] = {
          ContentKR = "\"운명의 실타래를 끊는 가위이자, 영원한 고요의 주인이시여...\"\n\"심연과 긴 밤 아래, 이 미천한 기도를 주시옵소서...\"",
          DialogueId = 6102801,
          GUID = "0F4718CA",
          NextDialogue = 6102802,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char01"
        },
        [6102802] = {
          ContentKR = "일렁이는 불길 너머 사람들의 형체가 어른거리고, 신을 향한 기도가 하나의 목소리가 되어 울려 퍼진다.\n가만히 귀를 기울이니, 전혀 들어 본 적 없는 기도문이다.",
          DialogueId = 6102802,
          GUID = "0F4718F4",
          NextDialogue = 6102803,
          RougeTalkActorType = 3
        },
        [6102803] = {
          ContentKR = "\"누구시죠? 혹시 길을 잃으셨나요?\"\n기도하던 사람 중 하나가 당신을 발견하곤, 미소 지으며 손을 내민다.\n\"그게 아니라면, 그쪽도 하늘의 뜻을 헤아리고, 저희와 함께 진정한 구원자이신 네파님의 품에 안기려 하는 건가요?\"",
          DialogueId = 6102803,
          GUID = "0F47191E",
          NextDialogue = 6102804,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char01"
        },
        [6102804] = {
          ContentKR = "<H>네파</>... 기억난다.\n엘리시안 정교회의 기록에서는 좀처럼 찾아볼 수 없고, 먼지 쌓인 고문서에서나 발견할 수 있는, 금기시된 이름이자, 오래전에 잊힌 <H>열 번째 신</>이다.",
          DialogueId = 6102804,
          GUID = "0F471948",
          NextDialogue = 6102805,
          RougeTalkActorType = 3
        },
        [6102805] = {
          ContentKR = "네파는 만월과 운명의 신 포르소의 자매이자, 어두운 달과 죽음의 신이다.\n언니가 운명의 실을 잣는다면, 동생은 그 운명을 가차 없이 끊어 낸다.\n두 신의 끊임없는 반목은 달을 차고 이지러지게 만들고, 밀물과 썰물을 자아낸다.\n그런 네파의 추종자들이라면, 아마...",
          DialogueId = 6102805,
          GUID = "0F471972",
          NextOptions = {
            [1] = 6102806
          },
          RougeTalkActorType = 3
        },
        [6102806] = {
          ContentKR = "그들의 신앙에 대해 묻는다.",
          DialogueId = 6102806,
          GUID = "0F47199C",
          NextDialogue = 6102807,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102807] = {
          ContentKR = "\"이곳에 오신 걸 보면, 이미 아시겠지만, 심연은 살아 있어요. 끊임없이 자라고, 뻗어 나가고 있죠.\"\n\"기사단의 황금 성검은 어둠의 파도를 막을 수 없고, 만월은 그윽한 고요를 꿰뚫지 못해요.\n\"모든 빛이 꺼지기 위해 타오르고, 모든 생명은 죽음을 향해 나아가듯, 소멸은 단 하나의 확고한 진리예요. 저희가 속한 이 심연이야말로, 이 세상의 본모습인 거죠.\"\n\"<H>암월 교단</>에 오신 걸 환영해요, 여행자님.\"",
          DialogueId = 6102807,
          GUID = "0F4719C6",
          NextOptions = {
            [1] = 6102808,
            [2] = 6102811
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char02"
        },
        [6102808] = {
          ContentKR = "초대를 받아들인다.",
          DialogueId = 6102808,
          GUID = "0F4719F0",
          IsKeyOption = true,
          NextDialogue = 6102809,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102809] = {
          ContentKR = "환영일 뿐이지만, 쓸데없는 마찰을 빚고 싶지는 않다.\n그래서 당신은 '죽음의 본능'이니 '네파의 구원'이니 '심연은 곧 영원이니'하는 어깨너머로 주워들었던 암월 교단의 소문들을 그럴싸하게 늘어놓는다... 제법 먹혀들었는지, 그들은 연신 고개를 끄덕이며 내 말에 맞장구를 친다.",
          DialogueId = 6102809,
          GUID = "0F471A1A",
          NextDialogue = 6102810,
          RougeTalkActorType = 3
        },
        [6102810] = {
          ContentKR = "\"정말 감탄이 나올 정도로 박식하고 지혜로우시네요. 부디 이 선물을 받아 주세요!\"\n어릴 적 설교나 논쟁 시간에 매번 졸기만 한 건 아니었는지, 다행히 그들을 속여 넘길 수 있었다.",
          DialogueId = 6102810,
          GUID = "0F471A44",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char02"
        },
        [6102811] = {
          ContentKR = "초대를 거절한다.",
          DialogueId = 6102811,
          GUID = "0F471A6E",
          IsKeyOption = true,
          NextDialogue = 6102812,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102812] = {
          ContentKR = "기나긴 고행 속에서, 당신 또한 삶과 죽음의 의미를 수없이 되뇌었으며, 죽음만이 유일한 안식이라 믿었던 적도 있었다.\n하지만 <H>예기치 못한 만남들</> 덕분에, 당신은 이미 어둠 속을 수없이 헤매는 의미를 깨달았다.\n몸을 장작으로 불태워 찰나의 빛으로 스러진다고 해도, 당신은 이 어둠을 몰아내고, 이 굳어진 불멸을 불태울 것이다.",
          DialogueId = 6102812,
          GUID = "0F471A98",
          NextDialogue = 6102813,
          RougeTalkActorType = 3
        },
        [6102813] = {
          ContentKR = "\"심연은 영원하지 않아. 너희는 산 사람이 남긴 환영일 뿐이야.\"\n당신은 무기를 쥔다.\n\"죽은 자는, 죽은 자가 있어야 할 곳으로 돌아가도록 해...\"",
          DialogueId = 6102813,
          GUID = "0F471AC2",
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102901] = {
          ContentKR = "당신은 모닥불 옆에 앉아 휴식을 취하고 있다.\n갑자기, 어디선가 이상한 소리가 들려온다. 소리는 바로 귓가에서 들려오는 듯하다가, 이내 점점 멀어져 머리 위로 옮겨간다.\n그리곤 조금씩 커지며, 부드러운 무언가가 사락대는 소리를 낸다.",
          DialogueId = 6102901,
          GUID = "0F472932",
          NextDialogue = 6102902,
          RougeTalkActorType = 3
        },
        [6102902] = {
          ContentKR = "\"안녕! 운 좋은 여행자!\"",
          DialogueId = 6102902,
          GUID = "0F47295C",
          NextDialogue = 6102903,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6102903] = {
          ContentKR = "알록달록한 깃털이 머리 위에서 팔랑팔랑 떨어져 내린다. 심연에서 이렇게 다양한 색깔을 보는 건 이번이 처음이다.\n바닥에 수북이 쌓인 깃털 더미에 둘러싸인 지금 모습을 보니, 마치 거리의 장난꾸러기 꼬마들에게 걸려든 운 없는 행인 같아 어색하기도 하고, 왠지 처량함도 느껴진다.",
          DialogueId = 6102903,
          GUID = "0F472986",
          NextDialogue = 6102904,
          RougeTalkActorType = 3
        },
        [6102904] = {
          ContentKR = "\"아니, 왜 이렇게 반응이 없어? 심연에 이렇게 오래 있었는데, 지겹지도 않아?\"\n우스꽝스러운 새 머리 가면을 쓴 사람이 위에서부터 스르륵 내려와, 당신과 눈높이를 맞춘다.\n대체 어떻게 저런 자세를 유지하는 건지는 알 수 없지만, 그건 중요하지 않다. 중요한 건, 저 가면의 뾰족한 뿌리가 당신의 얼굴을 찌를 것만 같다는 사실이다.",
          DialogueId = 6102904,
          GUID = "0F4729B0",
          NextOptions = {
            [1] = 6102905
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6102905] = {
          ContentKR = "그쪽이랑 같이 놀아 줄 시간 없어요.",
          DialogueId = 6102905,
          GUID = "0F4729DA",
          NextDialogue = 6102906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102906] = {
          ContentKR = "\"너무 쌀쌀맞게 그러지 마. 교회 늙은이들이 하루에 착한 일을 하나 하면, 그게 다 복으로 돌아온다고 알려 줬을 거 아냐.\"\n\"나하고 <H>게임</> 하자. 이기면 상을 줄 거고, 져도 아무런 벌칙은 없어. 완전히 남는 장사잖아, 어때?\"",
          DialogueId = 6102906,
          GUID = "0F472A04",
          NextOptions = {
            [1] = 6102907
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6102907] = {
          ContentKR = "알겠어요.",
          DialogueId = 6102907,
          GUID = "0F472A2E",
          IsKeyOption = true,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103001] = {
          ContentKR = "\"오, 다 함께 <H>사리엘</>을 위해 노래하세!\n\"엘리시안의 성자 사리엘.\"\n\"포르소의 계시를 받고 이 세상에 자비와 용서와 사랑을 전하시고.\"\n\"주홍빛 엘리시안의 대지에 평화의 새싹을 틔우셨네!\"",
          DialogueId = 6103001,
          GUID = "0F47399A",
          NextDialogue = 6103002,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103002] = {
          ContentKR = "음유시인 차림의 노인 하나가 부서진 벽의 일부를 어루만진다.\n그나마 온전한 벽면 위로, 희미한 불빛을 받아 시인의 노래에 등장하는 <H>사리엘</>의 거대한 벽화가 모습을 드러낸다.\n사리엘은 2천 년 전의 성자이자, 최초의 <H>세븐 버튜스</> 중 '절제'를 맡았던 인물이다.\n시인은 당신에게는 아랑곳하지 않은 채, 열심히 노래를 이어 나간다.",
          DialogueId = 6103002,
          GUID = "0F4739C4",
          NextOptions = {
            [1] = 6103003
          },
          RougeTalkActorType = 3
        },
        [6103003] = {
          ContentKR = "계속 듣는다.",
          DialogueId = 6103003,
          GUID = "0F4739EE",
          NextDialogue = 6103004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103004] = {
          ContentKR = "\"그러나 늘 한 가지가 성자의 가슴을 옥죄였으니.\"\n\"포르소께서 약속하신, 제천의 하늘이 바로 그것이라.\"\n\"푸른 물결의 호숫가에서 일흔하고도 이레를 앉아 지낸 어느 날.\"\n\"드디어 만월 아래 진리를 깨닫고, 호수 속에서 영원에 도달했네.\"",
          DialogueId = 6103004,
          GUID = "0F473A18",
          NextDialogue = 6103005,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103005] = {
          ContentKR = "무슨 노래인지 짐작이 간다.\n사리엘이 호숫가에서 만월과 운명의 여신 포르소의 계시를 받아, 영혼이 제천의 하늘에 도달해 '영원'을 얻고, 첫 번째 '신에게 선택받은 자'가 되었다는 이야기일 것이다.\n사리엘을 시작으로 사람들의 몸에는 성흔이 나타나기 시작했고, 이는 신의 부름을 받았다는 증표였다. 그들은 차례대로 성스러운 호수를 통해 약속의 땅에 이르렀다.\n내게도 낯설지 않은, 교회의 초창기 역사이다.",
          DialogueId = 6103005,
          GUID = "0F473A42",
          NextOptions = {
            [1] = 6103006
          },
          RougeTalkActorType = 3
        },
        [6103006] = {
          ContentKR = "계속 듣는다.",
          DialogueId = 6103006,
          GUID = "0F473A6C",
          NextDialogue = 6103007,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103007] = {
          ContentKR = "\"그렇지만 2천 년이 지난 후, 내가 이 겹겹의 산 위에서 성스러운 호수를 바라보니.\"\n\"어찌하여 칠흑 같은 소용돌이만 남아 있는가?\"\n\"사리엘, 우리의 지혜로운 성자여...\"\n\"여신께서 약속한 낙원은 대체 어디에 있단 말인가?\"",
          DialogueId = 6103007,
          GUID = "0F473A96",
          NextDialogue = 6103008,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103008] = {
          ContentKR = "머나먼 역사를 거슬러 올라간 시인의 노래가 마침내 어두운 심연이라는 비극에 닿자, 그의 눈에서 소리 없이 눈물이 흘러내린다.\n2천 년 동안 교회에서 가장 신성하고 순수하다 여긴 성스러운 호수가, 언제부터인지 이 더러운 혼돈으로 뒤바뀌어 버린 것이다.\n마치 천 년 전 교회를 버린 타락자들의 예견이 현실이 된 것만 같은 광경이다.... \"아홉 신은 죽었다!\"\n계속 들어 볼까?",
          DialogueId = 6103008,
          GUID = "0F473AC0",
          NextOptions = {
            [1] = 6103009,
            [2] = 6103013
          },
          RougeTalkActorType = 3
        },
        [6103009] = {
          ContentKR = "계속 듣는다.",
          DialogueId = 6103009,
          GUID = "0F473AEA",
          IsKeyOption = true,
          NextDialogue = 6103010,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103010] = {
          ContentKR = "\"저 더러운 심연은 어찌하여 침묵하는가?\"\n\"만월의 광휘가 당신을 비추건만, 여신께선 어찌 답이 없으신가?\"\n\"사리엘이여, 설마 암월파 신도들의 말처럼...\"\n\"제천의 하늘에 오른 적 없이, 밝은 달을 등지고 마귀가 되었단 말인가?\"",
          DialogueId = 6103010,
          GUID = "0F473B14",
          NextDialogue = 6103011,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103011] = {
          ContentKR = "\"잠깐만요... 뭐라고요?\"\n시인이 뜻밖의 구절을 노래한다. 성스러운 호수는 성스러운 적도 없었고, 사리엘 또한 신에게 선택받은 자가 아니라 거대한 희생제에 바쳐진 제물이었다는... 이단들 사이에서 가장 은밀하게 떠돌던 소문이다.\n당신은 <H>누군가</>에게서 똑같은 추측을 들은 적이 있다.",
          DialogueId = 6103011,
          GUID = "0F473B3E",
          NextDialogue = 6103012,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103012] = {
          ContentKR = "하지만 시인은 당신은 안중에도 없다는 듯, 리라를 연주하며 다음 노래를 시작한다.\n그의 노랫소리는 점차 멀어져 가고, 이내 그의 모습마저 사라진다.",
          DialogueId = 6103012,
          GUID = "0F473B68",
          RougeTalkActorType = 3
        },
        [6103013] = {
          ContentKR = "이곳을 떠난다.",
          DialogueId = 6103013,
          GUID = "0F473B92",
          IsKeyOption = true,
          NextDialogue = 6103014,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103014] = {
          ContentKR = "대화를 나눠 보려 몇 번이나 인사를 건네 봤지만, 시인은 조금 전의 그 오래된 노래만 부를 뿐이다.\n아무래도 시인에게서 유용한 정보를 얻기는 힘들어 보여, 당신은 몸을 돌려 자리를 떠난다.",
          DialogueId = 6103014,
          GUID = "0F473BBC",
          RougeTalkActorType = 3
        },
        [6200101] = {
          ContentKR = "심연에서 오랜만에 열정적이고, 생기 넘치고, 아직 심연의 어둠에 물들지 않은 청년 몇 명의 목소리가 들려온다.\n이건 망령도, 환영도 아닌, 살아 있는 사람의 목소리가 확실하다.",
          DialogueId = 6200101,
          GUID = "0F857412",
          NextDialogue = 6200102,
          RougeTalkActorType = 3
        },
        [6200102] = {
          ContentKR = "당신은 자신도 모르게 소리가 있는 곳으로 걸어간다. 주위를 둘러싼 안개가 점차 걷히자, 네 명의 젊은 기사와 마주친다.\n옷차림과 장비는 제각각이지만 모두 엘리시안의 상징인 아이리스 휘장을 달고 있다.",
          DialogueId = 6200102,
          GUID = "0F85743C",
          NextDialogue = 6200103,
          RougeTalkActorType = 3
        },
        [6200103] = {
          ContentKR = "\"이 방향 맞아요, 대장?\"\n젊은 금발의 여기사가 낡은 계단을 성큼성큼 올라갔다가, 단숨에 뛰어내린다.\n\"여긴 그냥 폐허 같은데요.\"",
          DialogueId = 6200103,
          GUID = "0F857466",
          NextDialogue = 6200104,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200104] = {
          ContentKR = "\"우리가 와 본 적 없는 곳인 건 확실해요.\"\n대장이라 불린 청년이 침착하게 소녀의 옆을 지나간다.\n\"성스러운 호수에선 방향 감각이 무뎌지니까, 일단은 가는 데까지 가 보는 수밖에 없어요.\"",
          DialogueId = 6200104,
          GUID = "0F857490",
          NextDialogue = 6200105,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200105] = {
          ContentKR = "\"그런데 캐시, 이렇게 폴짝폴짝 뛰어다니는 거 힘들지 않아요?\"\n자신의 활발한 동료를 보며, 청년은 어이없다는 듯 한숨을 내쉰다.\n\"이곳은 주변이 위험하니, 신중한 게 좋아요. 전투 외의 일에 체력을 소모하지 말아요.\"",
          DialogueId = 6200105,
          GUID = "0F8574BA",
          NextDialogue = 6200106,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200106] = {
          ContentKR = "\"전혀 피곤하지 않아요! 전 당신처럼 무거운 장검과 방패를 들고 있지 않거든요.\"\n소녀는 검지에 권총을 걸고, 공중에서 빙글빙글 돌린다.\n\"그런데 왜 이곳을 '성스러운 호수'라고 부르는 거예요? 제가 보기에 여긴 필토이드와 기괴한 환영투성이라, 별로 신성하지 않아 보이는데요.\"",
          DialogueId = 6200106,
          GUID = "0F8574E4",
          NextDialogue = 6200107,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200107] = {
          ContentKR = "\"캐시, 언사를 주의하세요.\"\n지팡이 든 남성 카론 사제가 굳은 표정으로 입을 연다.\n\"성스러운 호수는 신의 부름을 받은 사람이 신의 은총을 입은 성지입니다. 지금은 어둠에 물들었지만, 우리는 엘리시안의 일원으로서, 경외심을 가져야 합니다.\"",
          DialogueId = 6200107,
          GUID = "0F85750E",
          NextDialogue = 6200108,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char03"
        },
        [6200108] = {
          ContentKR = "네 사람 중 마지막 한 명은 긴 활을 등에 묶고 망토를 두른 여자 마법사다. 그녀는 그의 말에 동의하지 않는다는 듯이 웃는다. 검은 망토가 얼굴을 가려 표정이 보이지 않는다.",
          DialogueId = 6200108,
          GUID = "0F857538",
          NextDialogue = 6200109,
          RougeTalkActorType = 3
        },
        [6200109] = {
          ContentKR = "대장인 청년이 어색함을 달래려는 듯 입을 열지만 아무 말도 하지 못한다. 그는 이러지도 저러지도 못하다가, 문득 당신을 발견한다.",
          DialogueId = 6200109,
          GUID = "0F857562",
          NextDialogue = 6200110,
          RougeTalkActorType = 3
        },
        [6200110] = {
          ContentKR = "\"기사단 사람은 아닌 것 같은데, 혹시 이곳에 잘못 들어온 평민이신가요?\"",
          DialogueId = 6200110,
          GUID = "0F85758C",
          NextOptions = {
            [1] = 6200111
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200111] = {
          ContentKR = "저는 여행자입니다.",
          DialogueId = 6200111,
          GUID = "0F8575B6",
          NextDialogue = 6200112,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200112] = {
          ContentKR = "\"여행자...?\" 청년의 얼굴에 순간 곤혹스러움이 스치다, 다시 온화한 표정으로 돌아온다. \"잘 모르시는 듯한데, 이곳은 엘리시안의 성지이며, 현재는 여러 가지 이유로 매우 위험해져서, 여행하기에 적합하지 않습니다.\"",
          DialogueId = 6200112,
          GUID = "0F8575E0",
          NextDialogue = 6200113,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200113] = {
          ContentKR = "\"저는 플린이라고 합니다. 엘리시안 교회 산하 날개 기사단의 기사이고, 여긴 모두 제 동료입니다. 괜찮으시다면, 이곳을 떠나시도록 저희가 호송해 드리겠습니다.\"",
          DialogueId = 6200113,
          GUID = "0F85760A",
          NextOptions = {
            [1] = 6200114
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200114] = {
          ContentKR = "아니요, 저는 아직 이루지 못한 목표가 있습니다.",
          DialogueId = 6200114,
          GUID = "0F857634",
          NextDialogue = 6200115,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200115] = {
          ContentKR = "\"이곳은 성지이기도 하지만, 금단의 땅이라는 걸 말씀드려야겠네요. 기사로서 우리는 외부인을 추방할 의무가 있습니다.\"",
          DialogueId = 6200115,
          GUID = "0F85765E",
          NextDialogue = 6200116,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char03"
        },
        [6200116] = {
          ContentKR = "\"...어떻게 추방한다는 거죠?\" 시큰둥한 차가운 웃음과 함께, 망토를 걸친 여자 마법사가 마침내 입을 연다. \"우리도 어떻게 나가야 할지 모르지 않나요?\"\n차가운 그녀의 말이, 차가운 겨울 눈처럼 뺨을 스쳐 지나간다.",
          DialogueId = 6200116,
          GUID = "0F857688",
          NextDialogue = 6200117,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char04"
        },
        [6200117] = {
          ContentKR = "\"어... 그만해요.\" 금발의 여기사가 분위기를 수습한다. \"이 '손님'은 솜씨도 제법 괜찮고, 신성모독자 같지도 않은데요. 어차피 우리 임무엔 지장이 없으니 그냥 못 본 걸로 하죠?\"",
          DialogueId = 6200117,
          GUID = "0F8576B2",
          NextDialogue = 6200118,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200118] = {
          ContentKR = "\"참, 참, 여행자님.\" 그녀는 플린을 밀쳐내고 당신 앞으로 다가선다. \"혹시 대략 열서너 살 정도의, 분홍색 긴 머리에, 거대한 검을 든 여검사를 본 적이 있으신가요?\"",
          DialogueId = 6200118,
          GUID = "0F8576DC",
          NextOptions = {
            [1] = 6200119
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200119] = {
          ContentKR = "...아니요.",
          DialogueId = 6200119,
          GUID = "0F857706",
          NextDialogue = 6200120,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200120] = {
          ContentKR = "\"그런가요... 그럼, 나중에라도 혹시 만나게 된다면, <H>침묵의 황혼</> 소대가 찾고 있다고 말해 주시겠어요? 부탁이에요!\"",
          DialogueId = 6200120,
          GUID = "0F857730",
          NextOptions = {
            [1] = 6200121
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200121] = {
          ContentKR = "왜 그녀를 찾는 거죠?",
          DialogueId = 6200121,
          GUID = "0F85775A",
          NextDialogue = 6200122,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200122] = {
          ContentKR = "\"말하기 좀 그렇지만, 어쨌든 그녀는 우리의... 지휘관이에요. 어, 저도 더 이상은 말씀드릴 수 없어요. 그렇지 않으면 밀턴에게 혼날 거예요.\"",
          DialogueId = 6200122,
          GUID = "0F857784",
          NextDialogue = 6200123,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200123] = {
          ContentKR = "\"알면 더 이상 말하지 마세요.\" 사제가 눈살을 찌푸린다. \"문제를 더 복잡하게 만들지 마세요. 임무가 중하니, 이만 갑시다.\"",
          DialogueId = 6200123,
          GUID = "0F8577AE",
          NextDialogue = 6200124,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char03"
        },
        [6200124] = {
          ContentKR = "\"정말 도움이 필요 없으신가요?\" 청년이 다시 근심스럽게 당신을 바라본다. \"여긴 정말 위험한 곳이니, 저희와 동행하시는 게 어떨까요.\"",
          DialogueId = 6200124,
          GUID = "0F8577D8",
          NextOptions = {
            [1] = 6200125
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200125] = {
          ContentKR = "정말 괜찮습니다.",
          DialogueId = 6200125,
          GUID = "0F857802",
          NextDialogue = 6200126,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200126] = {
          ContentKR = "\"알겠습니다. 뜻이 그러시다면...\"",
          DialogueId = 6200126,
          GUID = "0F85782C",
          NextOptions = {
            [1] = 6200127
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200127] = {
          ContentKR = "위험한 곳인데 당신들은 무섭지 않나요?",
          DialogueId = 6200127,
          GUID = "0F857856",
          IsKeyOption = true,
          NextDialogue = 6200128,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200128] = {
          ContentKR = "\"신앙이 있으니, 두렵지 않습니다.\" 청년이 확고한 미소를 짓는다. \"안녕히 계세요, 여행자님. 부디 만월의 신께서 당신의 여정을 굽어살펴 주시기를 바랍니다.\"",
          DialogueId = 6200128,
          GUID = "0F857880",
          NextDialogue = 6200129,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200129] = {
          ContentKR = "기사들은 떠나고, 당신의 눈앞에는 끝없는 안개만이 남는다.",
          DialogueId = 6200129,
          GUID = "0F8578AA",
          RougeTalkActorType = 3
        },
        [6200201] = {
          ContentKR = "젊은 여기사가 어둠 속에서 모습을 드러내고, 금빛 머리카락이 흘러내리는 불빛처럼 혼돈 속을 비춘다.\n그녀는 지난번에 만났을 때와는 좀 달라졌다. 옷이 몇 군데 찢어졌고, 검붉은 자국이 약간 묻어 있다.",
          DialogueId = 6200201,
          GUID = "0F85847A",
          NextDialogue = 6200202,
          RougeTalkActorType = 3
        },
        [6200202] = {
          ContentKR = "\"당신이었군요, 여행자님, 또 만났네요!\" 그녀는 약간 지친 듯하지만, 다시 기운을 차리고 당신에게 힘껏 손을 흔든다.",
          DialogueId = 6200202,
          GUID = "0F8584A4",
          NextOptions = {
            [1] = 6200203
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200203] = {
          ContentKR = "동료들은요?",
          DialogueId = 6200203,
          GUID = "0F8584CE",
          NextDialogue = 6200204,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200204] = {
          ContentKR = "\"그게... 아까 필토이드와 유령... 그러니까, 그 어둠 속의 그림자 무리와 부딪쳤는데요...\"",
          DialogueId = 6200204,
          GUID = "0F8584F8",
          NextDialogue = 6200205,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200205] = {
          ContentKR = "\"정신없이 놈들을 몰아내고 나니 동료들이 보이지 않더라고요. 혹시 그들을 만나셨나요?\"",
          DialogueId = 6200205,
          GUID = "0F858522",
          NextOptions = {
            [1] = 6200206
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200206] = {
          ContentKR = "아니요.",
          DialogueId = 6200206,
          GUID = "0F85854C",
          NextDialogue = 6200207,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200207] = {
          ContentKR = "캐시는 흘러가는 구름이 태양을 가리듯, 가만히 눈을 내리깐다.",
          DialogueId = 6200207,
          GUID = "0F858576",
          NextDialogue = 6200208,
          RougeTalkActorType = 3
        },
        [6200208] = {
          ContentKR = "\"플린이 항상 전투에 임할 때 대형에 주의하고, 서로가 서로를 지켜야 한다고 했거든요... 아, 그렇게 제멋대로 굴지 말고 플린의 말을 들었어야 했어요.\"",
          DialogueId = 6200208,
          GUID = "0F8585A0",
          NextDialogue = 6200209,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200209] = {
          ContentKR = "\"전 성스러운 호수가 이런 곳인 줄 몰랐어요. 평소엔 제가 실수로 뒤처져도, 동료들을 금방 찾을 수 있었거든요. 근데 여긴... 분명히 방금 지나갔던 곳인데도, 뒤돌아보면 완전히 달라져 있어요. 마치...\"\n그녀는 주먹을 꽉 쥔다.\n\"마치 그 그림자들이 모두를 데려가 버리고... 그들이 남긴 흔적까지 몽땅 지워버린 것 같아요.\"",
          DialogueId = 6200209,
          GUID = "0F8585CA",
          NextOptions = {
            [1] = 6200210
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200210] = {
          ContentKR = "걱정 말아요, 분명 다시 만나게 될 거예요. 지금 절 만난 것처럼요.",
          DialogueId = 6200210,
          GUID = "0F8585F4",
          NextDialogue = 6200211,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200211] = {
          ContentKR = "캐시는 약간 놀란 듯이 눈을 깜박이며, 당신을 한참 쳐다본다.",
          DialogueId = 6200211,
          GUID = "0F85861E",
          NextDialogue = 6200212,
          RougeTalkActorType = 3
        },
        [6200212] = {
          ContentKR = "\"우리 혹시 전에 만난 적이 있나요?\"\n그녀의 맑은 눈동자에 당신의 모습이 비친다. 그 모습이 왠지 낯설게 느껴진다.",
          DialogueId = 6200212,
          GUID = "0F858648",
          NextDialogue = 6200213,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200213] = {
          ContentKR = "\"왠지 당신을 만난 적이 있는 것 같아요. 지난번 얘기가 아니라, 훨씬 더 전에, 우리가 성스러운 호수에 들어오기 전부터요...\"",
          DialogueId = 6200213,
          GUID = "0F858672",
          NextOptions = {
            [1] = 6200214
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200214] = {
          ContentKR = "착각일 거예요.",
          DialogueId = 6200214,
          GUID = "0F85869C",
          NextDialogue = 6200215,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200215] = {
          ContentKR = "\"음, 맞아요.\"\n그녀가 입가에 미소를 짓는다. 마치 가려진 햇살이 구름을 뚫고 한 줄기 빛을 내려고 노력하는 것처럼.",
          DialogueId = 6200215,
          GUID = "0F8586C6",
          NextDialogue = 6200216,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200216] = {
          ContentKR = "\"모두와 헤어진 후, 저는 아주 오랫동안 혼자 걸었어요. 당신을 만나지 못했더라면 전 제가 신의 벌을 받고 지옥에 떨어진 건가 하고 의심했을 거예요.\"",
          DialogueId = 6200216,
          GUID = "0F8586F0",
          NextDialogue = 6200217,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200217] = {
          ContentKR = "\"어쩌면 전 단지 <H>살아 있는 생명</>의 숨결이 그리운 것인지도 몰라요.\"",
          DialogueId = 6200217,
          GUID = "0F85871A",
          NextOptions = {
            [1] = 6200218
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200218] = {
          ContentKR = "하루빨리 동료와 합류할 수 있길 바라요.",
          DialogueId = 6200218,
          GUID = "0F858744",
          IsKeyOption = true,
          NextDialogue = 6200219,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200219] = {
          ContentKR = "\"네, 고마워요! 사실 그들은 모두 대단한 기사들이니, 제가 없어도 아무 문제 없을 거예요. 하지만 전 그들을 꼭 찾아내야만 해요...\"",
          DialogueId = 6200219,
          GUID = "0F85876E",
          NextDialogue = 6200220,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200220] = {
          ContentKR = "\"안녕히 가세요, 여행자님. 당신도 목표를 꼭 이루시길 바라요.\"",
          DialogueId = 6200220,
          GUID = "0F858798",
          NextDialogue = 6200221,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        }
      }
    end
  },
  {
    MinKey = 6200221,
    MaxKey = 6201602,
    Loader = function()
      return {
        [6200221] = {
          ContentKR = "캐시는 당신을 향해 손을 흔들고, 돌아서서 떠난다.\n사방은 다시 어두워져, 마치 한 번도 아침이 찾아온 적 없는 긴 밤처럼 캄캄해진다.",
          DialogueId = 6200221,
          GUID = "0F8587C2",
          RougeTalkActorType = 3
        },
        [6200301] = {
          ContentKR = "무너진 기와와 담장, 또 하나의 폐허.\n특별할 것도 없는, 심연에서 수없이 많이 본 광경이다.",
          DialogueId = 6200301,
          GUID = "0F8594E2",
          NextDialogue = 6200302,
          RougeTalkActorType = 3
        },
        [6200302] = {
          ContentKR = "부서진 건물 잔해 안에는 이제 아무도 들지 않을 무기들이 널브러져 있고, 폐허 위에는 이미 숨을 거둔 시체가 누운 채, 피비린내와 연기 냄새로 자욱하다.\n이미 수없이 보았다. 이들은 스스로 원해서, 또는 어쩔 수 없이 '성스러운 호수'에 제물로 바쳐진 영혼들일 뿐이다.",
          DialogueId = 6200302,
          GUID = "0F85950C",
          NextDialogue = 6200303,
          RougeTalkActorType = 3
        },
        [6200303] = {
          ContentKR = "문득, 피로 물든 휘장에 시선이 멎는다. 매우 익숙한 아이리스 문양이다. 당신은 얼마전에 이 휘장을 본 적이 있다.",
          DialogueId = 6200303,
          GUID = "0F859536",
          NextDialogue = 6200304,
          RougeTalkActorType = 3
        },
        [6200304] = {
          ContentKR = "부서진 돌조각을 헤치니, 피로 얼룩진 장검이 보인다. 검은 땅에 꽂혀 있었는데, 어쩌면 검을 쥔 사람이 끝까지 쓰러지지 않기 위해 헛되이 몸을 일으키려 했기 때문인 것 같다.",
          DialogueId = 6200304,
          GUID = "0F859560",
          NextDialogue = 6200305,
          RougeTalkActorType = 3
        },
        [6200305] = {
          ContentKR = "그리고 부서진 지팡이, 흐트러진 화살, 망가진 권총이 보인다.\n이 영혼들이 누구인지 당신은 이제 안다.",
          DialogueId = 6200305,
          GUID = "0F85958A",
          NextDialogue = 6200306,
          RougeTalkActorType = 3
        },
        [6200306] = {
          ContentKR = "\"신앙이 있으니, 두렵지 않습니다.\" 마지막 순간, 그들이 믿는 신앙은 죽음의 고통을 덜어주었을까?\n당신은 알 수도 없고, 알 필요도 없다.",
          DialogueId = 6200306,
          GUID = "0F8595B4",
          NextDialogue = 6200307,
          RougeTalkActorType = 3
        },
        [6200307] = {
          ContentKR = "어차피 다시 다이얼을 돌리면, 모든 건 흔적도 없이 사라지기 때문이다.\n추모와 기도는 무의미하고 당신은 시간을 더 쓸 생각이 없다. 당신은 고인을 위해 두 눈을 감은 후, 돌아서서 떠나려고 한다.",
          DialogueId = 6200307,
          GUID = "0F8595DE",
          NextDialogue = 6200308,
          RougeTalkActorType = 3
        },
        [6200308] = {
          ContentKR = "\"하지만 전 그들을 꼭 찾아내야만 해요...\"\n하지만 마치 누군가 당신을 부르듯, 머릿속에 문득 소녀의 말이 울려 퍼지고, 당신에게 무언가를 일깨워준다.",
          DialogueId = 6200308,
          GUID = "0F859608",
          NextDialogue = 6200309,
          RougeTalkActorType = 3
        },
        [6200309] = {
          ContentKR = "다시 폐허로 눈을 돌리니, 이번에는 뭔가 이상한 점이 보인다. 젊은 기사 네 명의 몸은 이미 얼음장처럼 차가워졌지만, 캐시의 옷에는 검은 재가 묻어 있지 않다.\n그녀의 몸에는 바짝 마른, 또는 반쯤 마른 필토이드의 핏자국만 뒤덮여 있을 뿐이다.",
          DialogueId = 6200309,
          GUID = "0F859632",
          NextOptions = {
            [1] = 6200310
          },
          RougeTalkActorType = 3
        },
        [6200310] = {
          ContentKR = "당신은 깨닫는다. 그녀도 당신과 마찬가지로 한발 늦게 도착한 것이다.",
          DialogueId = 6200310,
          GUID = "0F85965C",
          IsKeyOption = true,
          NextDialogue = 6200311,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200311] = {
          ContentKR = "그녀가 동료를 찾아냈을 때, 그들은 이미 폐허 속에서 형체를 분간할 수 없는 잔해가 되어 있었다.",
          DialogueId = 6200311,
          GUID = "0F859686",
          NextDialogue = 6200312,
          RougeTalkActorType = 3
        },
        [6200312] = {
          ContentKR = "그래서 그녀는 이곳에 남아 더 이상 전진하지 않고, 잠시 그녀와 헤어진 이 동료들을 지키며, 마지막 순간까지 싸운 것이다.\n동료들의 시신을 보호하기 위해서였을까? 그녀에게 '버림받은' 동료들에게 속죄하기 위해서? 기사의 신조를 지키기 위해?\n아니면 긴 어둠이 마침내 그녀의 마지막 희망마저 무너뜨려, 그녀가 죽음의 연민을 구걸할 수밖에 없게 만든 걸까?",
          DialogueId = 6200312,
          GUID = "0F8596B0",
          NextDialogue = 6200313,
          RougeTalkActorType = 3
        },
        [6200313] = {
          ContentKR = "그녀는 이미 대답할 수 없다.",
          DialogueId = 6200313,
          GUID = "0F8596DA",
          RougeTalkActorType = 3
        },
        [6200401] = {
          ContentKR = "심연에서 오랜만에 열정적이고, 생기 넘치고, 아직 심연의 어둠에 물들지 않은 청년 몇 명의 목소리가 들려온다.\n이건 망령도, 환영도 아닌, 살아 있는 사람의 목소리가 확실하다.",
          DialogueId = 6200401,
          GUID = "0F85A54A",
          NextDialogue = 6200402,
          RougeTalkActorType = 3
        },
        [6200402] = {
          ContentKR = "당신은 그들이 누구인지 알고 있다.",
          DialogueId = 6200402,
          GUID = "0F85A574",
          NextDialogue = 6200403,
          RougeTalkActorType = 3
        },
        [6200403] = {
          ContentKR = "당신은 소리가 나는 곳을 향해 걸어간다. 주위를 둘러싼 안개가 점차 걷히고, 네 명의 젊은 기사가 나타난다.\n그들의 옷차림과 장비는 아직 티 없이 깨끗하고, 몸에 지닌 아이리스 휘장도 반짝반짝 빛나며, 어디서 내리쬐는지 알 수 없는 금빛을 반사하고 있다.",
          DialogueId = 6200403,
          GUID = "0F85A59E",
          NextDialogue = 6200404,
          RougeTalkActorType = 3
        },
        [6200404] = {
          ContentKR = "\"이 방향 맞아요, 대장?\"\n젊은 금발의 여기사가 낡은 계단을 성큼성큼 올라갔다가, 단숨에 뛰어내린다.\n\"여긴 그냥 폐허 같은데요.\"",
          DialogueId = 6200404,
          GUID = "0F85A5C8",
          NextDialogue = 6200405,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200405] = {
          ContentKR = "\"우리가 와 본 적 없는 곳인 건 확실해요.\"\n대장이라 불린 청년이 침착하게 소녀의 옆을 지나간다.\n\"성스러운 호수에선 방향 감각이 무뎌지니까, 일단은 가는 데까지 가 보는 수밖에 없어요.\"",
          DialogueId = 6200405,
          GUID = "0F85A5F2",
          NextDialogue = 6200406,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200406] = {
          ContentKR = "\"그런데 캐시, 이렇게 폴짝폴짝 뛰어다니는 거 힘들지 않아요?\"\n자신의 활발한 동료를 보며, 청년은 어이없다는 듯 한숨을 내쉰다.\n\"이곳은 주변이 위험하니, 신중한 게 좋아요. 전투 외의 일에 체력을 소모하지 말아요.\"",
          DialogueId = 6200406,
          GUID = "0F85A61C",
          NextDialogue = 6200407,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200407] = {
          ContentKR = "\"전혀 힘들지 않아요! 전 당신과 달리...\"",
          DialogueId = 6200407,
          GUID = "0F85A646",
          NextOptions = {
            [1] = 6200408
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200408] = {
          ContentKR = "그 사람 말이 맞아요.",
          DialogueId = 6200408,
          GUID = "0F85A670",
          NextDialogue = 6200409,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200409] = {
          ContentKR = "당신의 말에 소녀는 말을 끊고, 멍하니 고개를 돌린다.",
          DialogueId = 6200409,
          GUID = "0F85A69A",
          NextDialogue = 6200410,
          RougeTalkActorType = 3
        },
        [6200410] = {
          ContentKR = "\"당신은...?\"",
          DialogueId = 6200410,
          GUID = "0F85A6C4",
          NextOptions = {
            [1] = 6200411
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200411] = {
          ContentKR = "전 여행자입니다. 저는 여기에 여러분보다 더 오래 있었으니, 제 말을 믿으세요. 여긴 여러분이 상상하는 것보다 훨씬 더 끔찍해요.",
          DialogueId = 6200411,
          GUID = "0F85A6EE",
          NextDialogue = 6200412,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200412] = {
          ContentKR = "\"여행자...?\" 청년의 얼굴에 순간 곤혹스러움이 스친다. 지난번에 만났을 때와 똑같다. \"하지만 여긴 엘리시안의 성지인데... 어떻게 들어오셨죠?\"",
          DialogueId = 6200412,
          GUID = "0F85A718",
          NextOptions = {
            [1] = 6200413
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200413] = {
          ContentKR = "제겐 저만의 이유와, 반드시 이뤄야 할 목표가 있습니다. 아마 여러분도 마찬가지겠죠.",
          DialogueId = 6200413,
          GUID = "0F85A742",
          NextDialogue = 6200414,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200414] = {
          ContentKR = "\"음...?\"",
          DialogueId = 6200414,
          GUID = "0F85A76C",
          NextDialogue = 6200415,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char03"
        },
        [6200415] = {
          ContentKR = "이번엔, 망토를 두른 여자 마법사가 당신에게 약간의 흥미를 느낀 듯하다.\n그녀가 고개를 들자, 당신은 마침내 그녀의 눈을 마주한다. 그윽하고, 의심이 가득한, 뭔가를 찾는 듯한 눈빛은, 마치 어두운 호수에 떠오른 거품을 연상시킨다.",
          DialogueId = 6200415,
          GUID = "0F85A796",
          NextDialogue = 6200416,
          RougeTalkActorType = 3
        },
        [6200416] = {
          ContentKR = "\"보아하니, 당신은 우리가 모르는 진실을 알고 있는 것 같군요. 이 심연의 진실 말이에요.\"",
          DialogueId = 6200416,
          GUID = "0F85A7C0",
          NextDialogue = 6200417,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char03"
        },
        [6200417] = {
          ContentKR = "\"칼리스타...! 그건 이단자나 입에 담을 법한 불경한 말입니다! 여긴 성스러운 호수예요.\"",
          DialogueId = 6200417,
          GUID = "0F85A7EA",
          NextDialogue = 6200418,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char04"
        },
        [6200418] = {
          ContentKR = "칼리스타는 그의 질책에도 아랑곳하지 않고, 여전히 똑바로 당신을 바라보며, 당신의 대답을 기다리고 있다.",
          DialogueId = 6200418,
          GUID = "0F85A814",
          NextDialogue = 6200419,
          RougeTalkActorType = 3
        },
        [6200419] = {
          ContentKR = "뭐라고 대답해야 할까? 뭐라고 대답할 수 있을까?",
          DialogueId = 6200419,
          GUID = "0F85A83E",
          NextDialogue = 6200420,
          RougeTalkActorType = 3
        },
        [6200420] = {
          ContentKR = "지금 당장 돌아가라고 말할까? 하지만 그들의 신앙을 꺾을 수 없다는 것을 안다.\n신앙이란 아주 무거운 단어다. 그것은 낯선 여행자, 혹은 얼굴을 전혀 알아볼 수 없는 옛사람의 충고 한마디보다 훨씬 무게가 있다.",
          DialogueId = 6200420,
          GUID = "0F85A868",
          NextDialogue = 6200421,
          RougeTalkActorType = 3
        },
        [6200421] = {
          ContentKR = "신앙의 빛 속에서 자란 사람이 불필요한 진실을 알게 되는 것은, 빛에 화상을 입고, 찌르는 듯한 대낮의 가시만 남아, 영원한 마음의 고통을 받는 것과 같다.",
          DialogueId = 6200421,
          GUID = "0F85A892",
          NextDialogue = 6200422,
          RougeTalkActorType = 3
        },
        [6200422] = {
          ContentKR = "당신은 고개를 가로저으며 그녀의 시선을 피한다.",
          DialogueId = 6200422,
          GUID = "0F85A8BC",
          NextOptions = {
            [1] = 6200423
          },
          RougeTalkActorType = 3
        },
        [6200423] = {
          ContentKR = "심연에선 길을 잃기 쉬우니, 뒤처지지 않도록 주의하세요, 캐시.",
          DialogueId = 6200423,
          GUID = "0F85A8E6",
          NextDialogue = 6200424,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200424] = {
          ContentKR = "\"네? 왜 저를 지목해서 그런 말을 하세요?\"",
          DialogueId = 6200424,
          GUID = "0F85A910",
          NextDialogue = 6200425,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200425] = {
          ContentKR = "\"그러니까 반성해요. 당신의 취미가 함부로 돌아다니는 거란 걸 낯선 사람조차 알아챌 정도잖아요.\"",
          DialogueId = 6200425,
          GUID = "0F85A93A",
          NextDialogue = 6200426,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200426] = {
          ContentKR = "\"제가 언제요! 게다가 일행과 떨어지더라도, 전 모두를 금세 찾아낼 수 있다고요.\" 소녀가 입을 삐죽 내민다.",
          DialogueId = 6200426,
          GUID = "0F85A964",
          NextOptions = {
            [1] = 6200427
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200427] = {
          ContentKR = "하지만 항상 제때 찾아내는 건 아니죠.",
          DialogueId = 6200427,
          GUID = "0F85A98E",
          IsKeyOption = true,
          NextDialogue = 6200428,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200428] = {
          ContentKR = "캐시가 멍해진다. 아마도 당신의 지나치게 진지한 말투에 놀란 듯하다.",
          DialogueId = 6200428,
          GUID = "0F85A9B8",
          NextDialogue = 6200429,
          RougeTalkActorType = 3
        },
        [6200429] = {
          ContentKR = "그때 플린이 딱 맞게 나선다. 그는 역시 자격을 갖춘 엘리시안 기사다. 훌륭한 기사라면, 순결한 신앙뿐만 아니라 신중함도 꼭 갖춰야 한다. 호기심은 정보를 얻되 괜한 화를 불러일으키지 않을 정도로만 유지해야 함을 그는 잘 안다. 늘 잠겨 있던 성당의 문이 살며시 틈을 내보이며 유혹할 때, 최고의 선택은 언제나 걸음을 멈추고 돌아서서 아무것도 못 본 척하는 것이다.",
          DialogueId = 6200429,
          GUID = "0F85A9E2",
          NextDialogue = 6200430,
          RougeTalkActorType = 3
        },
        [6200430] = {
          ContentKR = "\"여행자님의 정체는 알 수 없지만, 갈 길이 있으신 것 같군요. 저희는 아직 임무가 있으니, 먼저 가보겠습니다.\" 그는 당신에게 정중하게 인사한다. \"부디 만월의 신께서 당신의 여정을 굽어살펴 주시기를 바랍니다.\"",
          DialogueId = 6200430,
          GUID = "0F85AA0C",
          NextDialogue = 6200431,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200431] = {
          ContentKR = "기사들은 떠나고, 당신의 눈앞에는 끝없는 안개만이 남는다.",
          DialogueId = 6200431,
          GUID = "0F85AA36",
          RougeTalkActorType = 3
        },
        [6200501] = {
          ContentKR = "계속되는 전투로 당신은 힘이 다했다.\n마지막 남은 한 가닥의 잿불도 손에서 흘러내리고, 당신은 완전히 길을 잃었다.",
          DialogueId = 6200501,
          GUID = "0F85B5B2",
          NextDialogue = 6200502,
          RougeTalkActorType = 3
        },
        [6200502] = {
          ContentKR = "랜턴이 땅에 떨어지고, 유리 깨지는 소리가 고요한 어둠을 칼날처럼 가른다.\n조각난 어둠이 당신을 향해 여기저기서 쏟아지며 당신의 몸을 갉아 먹고, 당신의 신경을 갉아 먹는다.",
          DialogueId = 6200502,
          GUID = "0F85B5DC",
          NextDialogue = 6200503,
          RougeTalkActorType = 3
        },
        [6200503] = {
          ContentKR = "모든 감각이 어둠과 하나가 될 때, 당신은 갑자기 더 이상 저항하지 않는다. 그것이 당신을 부드럽게 감싸고, 상처를 받아들이고, 피로를 어루만지는 것을 느낄 수 있다.",
          DialogueId = 6200503,
          GUID = "0F85B606",
          NextDialogue = 6200504,
          RougeTalkActorType = 3
        },
        [6200504] = {
          ContentKR = "어쩌면 이것이 올바른 결말일지도 모른다. 어디선가 어둠이 이렇게 속삭이는 듯하다.\n\"지금까지 버틴 것만으로도 충분해.\"",
          DialogueId = 6200504,
          GUID = "0F85B630",
          NextDialogue = 6200505,
          RougeTalkActorType = 3
        },
        [6200505] = {
          ContentKR = "맞다... 당신은 이미 충분히 노력했다. 반복된 고독 속에서, 필사적으로 싸웠고, 몸부림쳤으며, 끝없는 고통을 음미했다. 절망을 아름다운 술로 여기고 기꺼이 들이켰지만, 여전히 희망의 빛에 닿지 못했다.",
          DialogueId = 6200505,
          GUID = "0F85B65A",
          NextDialogue = 6200506,
          RougeTalkActorType = 3
        },
        [6200506] = {
          ContentKR = "당신은 지쳤다. 이제 그만하자.",
          DialogueId = 6200506,
          GUID = "0F85B684",
          NextDialogue = 6200507,
          RougeTalkActorType = 3
        },
        [6200507] = {
          ContentKR = "당신은 어둠의 요람에서 깊이 잠든 듯하다. 그때 머릿속에 아득한 그림자가 떠오른다. 그림자 주인의 확실한 모습은 더 이상 기억나지 않지만, 희미한 상념은 무감각해지는 살과 피를 칼로 베듯, 당신을 깨어 있게 한다. 그리고 끊임없이 생각의 바다를 휘젓고, 조수를 감아올린다.",
          DialogueId = 6200507,
          GUID = "0F85B6AE",
          NextDialogue = 6200508,
          RougeTalkActorType = 3
        },
        [6200508] = {
          ContentKR = "그건 어둠을 함께 이겨내자고 당신고 약속했던 사람이었고, 모든 고통을 준 장본인이기도 했다.",
          DialogueId = 6200508,
          GUID = "0F85B6D8",
          NextDialogue = 6200509,
          RougeTalkActorType = 3
        },
        [6200509] = {
          ContentKR = "생각났다. 당신은 아직 그 사람을 찾지 못했다.\n그렇다, 여기에서 잠들면 안 된다. 어둠의 초대장이 아무리 유혹적이라 해도, 그것은 당신이 원하는 결말이 아니다.\n끝까지 버텨야 한다. 결승점에 도달하기 위해, 약속을 지키기 위해, 그리고 터무니없는 윤회를 끊기 위해.",
          DialogueId = 6200509,
          GUID = "0F85B702",
          NextOptions = {
            [1] = 6200510
          },
          RougeTalkActorType = 3
        },
        [6200510] = {
          ContentKR = "시계 다이얼 돌리기",
          DialogueId = 6200510,
          GUID = "0F85B72C",
          IsKeyOption = true,
          NextDialogue = 6200511,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200511] = {
          ContentKR = "그리하여 당신은 다시 한번 랜턴의 다이얼을 돌려, 이야기의 시작점으로 향한다.",
          DialogueId = 6200511,
          GUID = "0F85B756",
          RougeTalkActorType = 3
        },
        [6200601] = {
          ContentKR = "심연에서 방향은 시시각각 변화하고, 당신은 자신이 전진하고 있는지 후퇴하고 있는지 분간할 수 없다.\n심지어 당신은 때로 자신이 앞뒤가 맞닿은 나선 속에 갇혀, 헛되이 맴돌고 있으며, 영원히 끝에 도달할 수 없다고 생각한다.",
          DialogueId = 6200601,
          GUID = "0F85C61A",
          NextDialogue = 6200602,
          RougeTalkActorType = 3
        },
        [6200602] = {
          ContentKR = "하지만 눈앞의 이 거대한 물건이 시야에 나타나는 순간, 당신은 본능적으로 그가 바로 이 심연의 '중심'이라는 것을 깨닫게 된다.",
          DialogueId = 6200602,
          GUID = "0F85C644",
          NextDialogue = 6200603,
          RougeTalkActorType = 3
        },
        [6200603] = {
          ContentKR = "당신은 랜턴을 들어, 그 얼굴을 비추려 하지만, 가엾은 빛은 경계에 닿자마자 가차 없이 묻혀버린다.\n주변을 뒤덮은 혼돈의 어둠은 탁한 잉크처럼 소용돌이치며, 똑같은 목적지를 향해 밀려온다.",
          DialogueId = 6200603,
          GUID = "0F85C66E",
          NextDialogue = 6200604,
          RougeTalkActorType = 3
        },
        [6200604] = {
          ContentKR = "땅이 울렁울렁 흔들리고, 당신은 중심을 잃고 어둠 속으로 떨어진다.\n어렴풋이, 자신의 몸도 그 탁류의 일부가 되어 무너지고 녹아내려, 모든 것을 집어삼키는 존재를 향해 흐르고 있는 것처럼 느껴진다.",
          DialogueId = 6200604,
          GUID = "0F85C698",
          NextDialogue = 6200605,
          RougeTalkActorType = 3
        },
        [6200605] = {
          ContentKR = "귀를 찢는 듯한 정적이 고막을 짓누르고, 생존 본능은 당신에게 이제 그만 돌아가라고 말한다.",
          DialogueId = 6200605,
          GUID = "0F85C6C2",
          NextOptions = {
            [1] = 6200606,
            [2] = 6200615
          },
          RougeTalkActorType = 3
        },
        [6200606] = {
          ContentKR = "계속 혼돈을 직시한다.",
          DialogueId = 6200606,
          GUID = "0F85C6EC",
          IsKeyOption = true,
          NextDialogue = 6200607,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200607] = {
          ContentKR = "당신은 위축되지 않는다.\n당신은 어둠 속에서 몸을 일으켜 머리를 치켜세우고, 손에 든 랜턴을 움켜쥔다. 그리고 그 형언할 수 없는 존재에게 당신은 결코 두려워하지 않는다고 선언한다.",
          DialogueId = 6200607,
          GUID = "0F85C716",
          NextDialogue = 6200608,
          RougeTalkActorType = 3
        },
        [6200608] = {
          ContentKR = "천천히, 무언가가 사방의 혼돈을 비틀고, 한 가닥 틈으로 새어 나오는 것이 느껴진다. 깊이를 알 수 없는 어둠 속에서, 어떤 것이 거꾸로 당신의 심장으로 파고든다. 놀랍게도, 당신은 그게 뭔지 이해할 수 있다.",
          DialogueId = 6200608,
          GUID = "0F85C740",
          NextDialogue = 6200609,
          RougeTalkActorType = 3
        },
        [6200609] = {
          ContentKR = "그것은 인간의 감정이었다. 의혹, 분노, 고통, 절망, 그리고... 슬픔. 압도하는 슬픔.\n마치 이 심연 스스로가 어떤 끝맺음을 기다리고 있는 듯했다.",
          DialogueId = 6200609,
          GUID = "0F85C76A",
          NextDialogue = 6200610,
          RougeTalkActorType = 3
        },
        [6200610] = {
          ContentKR = "\"내가 어떻게 도와주면 될까?\" 당신은 마음속으로 묻는다.",
          DialogueId = 6200610,
          GUID = "0F85C794",
          NextDialogue = 6200611,
          RougeTalkActorType = 3
        },
        [6200611] = {
          ContentKR = "\"이 랜턴은 아직 너무 어두워. 네 여정을 계속 이어가.\" 그가 말한다. \"윤회의 끝에 도착하면 답을 얻을 수 있을 거야.\"",
          DialogueId = 6200611,
          GUID = "0F85C7BE",
          NextDialogue = 6200612,
          RougeTalkActorType = 3
        },
        [6200612] = {
          ContentKR = "\"끝이 어딘데?\" 당신은 다시 묻는다.",
          DialogueId = 6200612,
          GUID = "0F85C7E8",
          NextDialogue = 6200613,
          RougeTalkActorType = 3
        },
        [6200613] = {
          ContentKR = "그는 질문에 대답하지 않고, 다만 어둠으로 부드럽게 당신을 에워싼다. 당신의 시야에는 랜턴의 빛만 남는다.",
          DialogueId = 6200613,
          GUID = "0F85C812",
          NextDialogue = 6200614,
          RougeTalkActorType = 3
        },
        [6200614] = {
          ContentKR = "그래서 당신은 랜턴의 다이얼을 돌려, 시간을 다시 되돌렸다.",
          DialogueId = 6200614,
          GUID = "0F85C83C",
          RougeTalkActorType = 3
        },
        [6200615] = {
          ContentKR = "뒤돌아간다.",
          DialogueId = 6200615,
          GUID = "0F85C866",
          IsKeyOption = true,
          NextDialogue = 6200616,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200616] = {
          ContentKR = "현명한 선택이다.\n뒤돌아 몸을 돌려, 걸음을 내디딘다. 당신은 본능적으로 도망친다. 지나온 길은 이미 찾을 수 없다는 걸 알고 있으면서도.",
          DialogueId = 6200616,
          GUID = "0F85C890",
          NextDialogue = 6200617,
          RougeTalkActorType = 3
        },
        [6200617] = {
          ContentKR = "문득 등 뒤에서 오는 시선이 느껴진다. 그는 마치 당신이 떠난 것을 슬퍼하는 듯, 말없이 당신을 바라보고 있다.",
          DialogueId = 6200617,
          GUID = "0F85C8BA",
          NextDialogue = 6200618,
          RougeTalkActorType = 3
        },
        [6200618] = {
          ContentKR = "\"내가 돌아왔으면 좋겠어?\" 당신은 마음속으로 묻는다.",
          DialogueId = 6200618,
          GUID = "0F85C8E4",
          NextDialogue = 6200619,
          RougeTalkActorType = 3
        },
        [6200619] = {
          ContentKR = "\"아니, 넌 자신의 길을 가야 해.\" 그가 말한다. \"윤회의 끝에서 우리는 저절로 다시 만날 거야.\"",
          DialogueId = 6200619,
          GUID = "0F85C90E",
          NextDialogue = 6200620,
          RougeTalkActorType = 3
        },
        [6200620] = {
          ContentKR = "\"끝이 어딘데?\" 당신은 다시 묻는다.",
          DialogueId = 6200620,
          GUID = "0F85C938",
          NextDialogue = 6200621,
          RougeTalkActorType = 3
        },
        [6200621] = {
          ContentKR = "그는 질문에 대답하지 않는다. 어둠이 당신의 어깨를 넘어와 주변을 부드럽게 메우고, 시야에는 랜턴의 빛만 남는다.",
          DialogueId = 6200621,
          GUID = "0F85C962",
          NextDialogue = 6200622,
          RougeTalkActorType = 3
        },
        [6200622] = {
          ContentKR = "그래서 당신은 랜턴의 다이얼을 돌려, 시간을 다시 되돌렸다.",
          DialogueId = 6200622,
          GUID = "0F85C98C",
          RougeTalkActorType = 3
        },
        [6200701] = {
          ContentKR = "모닥불 곁에 신비로운 분위기의 청년이 서 있다. 사실 목소리만 듣고 청년이라 짐작할 뿐, 나이는 가늠하기 어렵다.\n이 청년과 만난 건, 이번이 처음은 아니다.",
          DialogueId = 6200701,
          GUID = "0F85D682",
          NextDialogue = 6200702,
          RougeTalkActorType = 3
        },
        [6200702] = {
          ContentKR = "\"용감한 여행자님, 또 만났네요.\"",
          DialogueId = 6200702,
          GUID = "0F85D6AC",
          NextDialogue = 6200703,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200703] = {
          ContentKR = "청년이 예의 바르게 인사를 건넨다.\n날카로운 금속 가면이 청년의 얼굴 상반부를 완전히 가리고 있어, 그의 두 눈은 보이지 않는다.",
          DialogueId = 6200703,
          GUID = "0F85D6D6",
          NextDialogue = 6200704,
          RougeTalkActorType = 3
        },
        [6200704] = {
          ContentKR = "\"심연을 너무 오래 헤매다 보면, 대부분 길을 잃고, 결국 저 그림자들처럼 되고 말죠.\"\n\"여기 이 물건들이 내뿜는 <H>빛</>이 여행자님의 길을 밝혀, 아무것도 잃지 않게 지켜 드릴 겁니다.\" 청년이 말했다. \"이걸 랜턴 안에 넣어 심지로 쓰세요.\"\n청년의 눈동자 대신, 금속 가면이 모닥불의 빛을 반사해 반짝인다.",
          DialogueId = 6200704,
          GUID = "0F85D700",
          NextDialogue = 6200705,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200705] = {
          ContentKR = "\"하긴, 이런 걸 잊으셨을 리가 없군요. 여행자님은 <H>늘</> 이곳에 도달하셨으니까요.\"\n\"이번에도 모닥불 옆에 보급품을 준비해 뒀습니다. 필요하면 언제든 가져가 사용하세요.\"",
          DialogueId = 6200705,
          GUID = "0F85D72A",
          NextOptions = {
            [1] = 6200706
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200706] = {
          ContentKR = "당신은 누구죠?",
          DialogueId = 6200706,
          GUID = "0F85D754",
          NextDialogue = 6200707,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200707] = {
          ContentKR = "\"또 그 질문이군요. 여러 번 물으셨었는데 말이죠. 그래도 지금은 대답해 드릴 수 없으니, 부디 양해 바랍니다.\"\n\"일부러 숨기는 건 아닙니다. 단지 저도 지금 이 순간, 여기 서 있는 저 자신을 뭐라고 소개해야 할지 확신이 서지 않네요.\"\n청년이 가볍게 웃는다.",
          DialogueId = 6200707,
          GUID = "0F85D77E",
          NextDialogue = 6200708,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200708] = {
          ContentKR = "\"그러니까, 서로 조금 더 편하게 생각해 보는 건 어떨까요? 절 그냥 평범한 <H>상인</>이라고 여겨 주시면 됩니다.\"\n\"당신이 늘 스스로를 평범한 여행자라고 소개하시는 것처럼 말이죠.\"",
          DialogueId = 6200708,
          GUID = "0F85D7A8",
          NextOptions = {
            [1] = 6200709
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200709] = {
          ContentKR = "전 이제 출발해야겠어요.",
          DialogueId = 6200709,
          GUID = "0F85D7D2",
          IsKeyOption = true,
          NextDialogue = 6200710,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200710] = {
          ContentKR = "\"다음에 또 뵙죠, 용감한 여행자님.\" 청년이 말한다. \"부디 여행자님의 여로에 늘 빛이 함께하길 바랍니다.\"\n청년의 표정은 여전히 읽을 수 없지만, 가면 아래 그의 눈동자에는 불빛이 일렁이고 있을지 모른다.",
          DialogueId = 6200710,
          GUID = "0F85D7FC",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200801] = {
          ContentKR = "심연 행상인은 여느 때처럼 모닥불 곁을 지키고 있다.\n이곳에는 그림자의 울음소리 대신, 정적만이 흐른다.",
          DialogueId = 6200801,
          GUID = "0F85E6EA",
          NextDialogue = 6200802,
          RougeTalkActorType = 3
        },
        [6200802] = {
          ContentKR = "\"또 뵙는군요, 방랑하는 여행자님.\"\n\"이 희미한 <H>빛</>을 원해서 오셨겠죠.\"\n심연 행상인의 목소리는 언제나처럼 잔잔한 호수 같다.\n\"전 언제나처럼, 이곳에서 랜턴에 새로운 심지를 채워 드리죠.\"",
          DialogueId = 6200802,
          GUID = "0F85E714",
          NextOptions = {
            [1] = 6200803
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200803] = {
          ContentKR = "차라리 그냥 주면 안 돼요?",
          DialogueId = 6200803,
          GUID = "0F85E73E",
          NextDialogue = 6200804,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200804] = {
          ContentKR = "\"보시는 대로, 제게 그 정도의 힘은 남아 있지 않습니다.\"\n상인은 고개를 가로젓는다.\n\"지금 제가 할 수 있는 건, 작은 마법으로 그 자그마한 잿불을, 빛을 머금은 심지로 바꾸는 것뿐이죠.\"",
          DialogueId = 6200804,
          GUID = "0F85E768",
          NextDialogue = 6200805,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200805] = {
          ContentKR = "심연 행상인에게 랜턴을 건넨다.\n이윽고 잔불이 서서히 빛나기 시작하더니, 이내 흩날리는 반딧불처럼 변했다가, 한데 뭉쳐 밝은 심지가 된다.",
          DialogueId = 6200805,
          GUID = "0F85E792",
          NextOptions = {
            [1] = 6200806
          },
          RougeTalkActorType = 3
        },
        [6200806] = {
          ContentKR = "알겠어요, 고마워요.",
          DialogueId = 6200806,
          GUID = "0F85E7BC",
          NextDialogue = 6200807,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200807] = {
          ContentKR = "손에 든 랜턴을 흔들자, 새 심지 덕분인지 희미하던 불빛이 조금은 밝아진 것 같다.\n이 랜턴은 이 어둡고 깊은 심연 속에서, 길을 잃지 않도록 지켜 주는 당신의 유일한 동반자다.",
          DialogueId = 6200807,
          GUID = "0F85E7E6",
          NextOptions = {
            [1] = 6200808
          },
          RougeTalkActorType = 3
        },
        [6200808] = {
          ContentKR = "전 이제 출발해야겠어요.",
          DialogueId = 6200808,
          GUID = "0F85E810",
          IsKeyOption = true,
          NextDialogue = 6200809,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200809] = {
          ContentKR = "\"다음에 또 뵙죠, 방황하는 여행자님.\" 청년이 말한다. \"여행자님의 여로에 늘 빛이 함께하길 바랍니다.\"",
          DialogueId = 6200809,
          GUID = "0F85E83A",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200901] = {
          ContentKR = "또다시, 이곳에 도착했다.\n이 어둠 속에서 잠시나마 마음을 놓을 수 있는 곳은, 오직 여기뿐이다.",
          DialogueId = 6200901,
          GUID = "0F85F752",
          NextOptions = {
            [1] = 6200902
          },
          RougeTalkActorType = 3
        },
        [6200902] = {
          ContentKR = "아직 여기 있었네요.",
          DialogueId = 6200902,
          GUID = "0F85F77C",
          NextDialogue = 6200903,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200903] = {
          ContentKR = "\"네.\"\n상인은 여느 때처럼 차분하고 온화하다.\n\"여행자님께서 이곳의 어둠을 끝장낼 때까지, 전 항상 이 자리에 있을 겁니다.\"",
          DialogueId = 6200903,
          GUID = "0F85F7A6",
          NextOptions = {
            [1] = 6200904
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200904] = {
          ContentKR = "하지만 다른 사람들은 날 기억하지도 못하는걸요.",
          DialogueId = 6200904,
          GUID = "0F85F7D0",
          NextDialogue = 6200905,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200905] = {
          ContentKR = "\"심연 속의... 저 유령들이나 몇 안 되는 사람들은, 제가 다이얼을 돌려 과거로 돌아가면, 저랑 만난 적도 없고, 얘기한 적도 없는 것처럼, 까맣게 잊어버려요.\"\n\"누군가의 목숨을 구해도, 다음번엔 대부분이 또 죽어 버리고요.\"\n\"아무리 많은 사람을 만나도, 결국엔 저 혼자예요.\"",
          DialogueId = 6200905,
          GUID = "0F85F7FA",
          NextDialogue = 6200906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200906] = {
          ContentKR = "\"맞습니다. 심연의 모든 것은 밀물과 썰물처럼 반복되며, 몇 번이고 과거를 되풀이하죠.\"\n\"하지만 여행자님은 특별합니다. 그 다이얼의 주인으로서, 이미 시간의 바깥에 서 계시니까요.\"\n청년이 한숨을 내쉰다.",
          DialogueId = 6200906,
          GUID = "0F85F824",
          NextDialogue = 6200907,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200907] = {
          ContentKR = "\"이 심연 속에서, 시간을 지배하는 건 여행자님입니다. 오직 여행자님만이 <H>영원</>하죠. 신의 권능이랄까요.\"\n\"하지만 바로 그 권능이 여행자님을 신의 옥좌에 앉은 죄수로 만드는 겁니다. 모든 것이 속절없이 스쳐 지나가는 걸, 마냥 지켜만 봐야 한다는 의미거든요.\"\n차분하던 행상인의 목소리에 희미한 동요가 스친다.\n\"그렇지만 그게 바로 여행자님이 이 심연과 맞설 유일한 방법이기도 합니다.\"",
          DialogueId = 6200907,
          GUID = "0F85F84E",
          NextOptions = {
            [1] = 6200908
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200908] = {
          ContentKR = "전 이제 출발해야겠어요.",
          DialogueId = 6200908,
          GUID = "0F85F878",
          IsKeyOption = true,
          NextDialogue = 6200909,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200909] = {
          ContentKR = "\"다음에 또 뵙죠, 고독한 여행자님.\" 청년이 말한다. \"여행자님의 여로에 늘 빛이 함께하길 바랍니다.\"",
          DialogueId = 6200909,
          GUID = "0F85F8A2",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201001] = {
          ContentKR = "다시 한번 숨 돌릴 틈을 얻었다.\n그림자의 방해도, 영혼의 비명도 없는 이곳은 안전하다.\n당신은 무너진 담벼락에 등을 기댄 채 천천히 주저앉는다.",
          DialogueId = 6201001,
          GUID = "0F8607BA",
          NextOptions = {
            [1] = 6201002
          },
          RougeTalkActorType = 3
        },
        [6201002] = {
          ContentKR = "이젠 지쳤어요.",
          DialogueId = 6201002,
          GUID = "0F8607E4",
          NextDialogue = 6201003,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201003] = {
          ContentKR = "\"아무리 앞으로 나아가도, 몇 번이고 다시 돌아와 버려요.\"\n\"나만의 싸움이란 건 알지만, 그래도 언제까지 이래야 하는 건지 모르겠어요.\"",
          DialogueId = 6201003,
          GUID = "0F86080E",
          NextDialogue = 6201004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201004] = {
          ContentKR = "\"신의 축복인 <H>순수한 유리</>가 다시 하나 되어 랜턴이 제 모습을 되찾으면, 그 안에서 기적이 일어날 겁니다.\"\n\"여행자님은 어둠을 가를 빛을 얻게 될 거예요.\"",
          DialogueId = 6201004,
          GUID = "0F860838",
          NextOptions = {
            [1] = 6201005
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201005] = {
          ContentKR = "아니요, 제가 알고 싶은 건 그게 아니에요.",
          DialogueId = 6201005,
          GUID = "0F860862",
          NextDialogue = 6201006,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201006] = {
          ContentKR = "\"전 제가 여기서 얼마나 있었는지도 모르겠어요. 10년? 20년? 아니면 더 오래됐을까요? 제가 아는 거라곤, 다이얼을 돌린 횟수뿐이에요.\"\n\"그런데도 랜턴의 불빛은 금방이라도 꺼질 것 같죠. 제가 아무 의미도 없는 짓을 하는 것 같다고요.\"\n\"제가 죽을 때까지 이걸 못 고칠 수도 있잖아요? 그럼 이게 다 무슨 소용이죠?\"\n\"어리석고 부조리한 비극?\"",
          DialogueId = 6201006,
          GUID = "0F86088C",
          NextDialogue = 6201007,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201007] = {
          ContentKR = "\"그렇습니다.\"\n상인의 긍정에, 당신은 할 말을 잃는다.",
          DialogueId = 6201007,
          GUID = "0F8608B6",
          NextDialogue = 6201008,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201008] = {
          ContentKR = "\"여행자님이 수없이 칼을 휘둘러 그림자를 퇴치하는 모습은, 수많은 장인이 매일 돌을 깎아 신전의 초석을 다지는 모습과 다르지 않습니다.\"\n\"어느 소녀는 끝없이 불 속에 조약돌을 던지더군요. 이 모습은 수많은 농부가 해마다 밭에 씨앗을 뿌리는 모습과 다르지 않습니다.\"\n\"모든 노고는, 그저 다음의 노고를 위한 것뿐이고, 여행자님과 저, 심연 속의 그림자들과 지상의 생명들까지, 모두가 이 비극을 되풀이하고 있습니다.\"\n\"만약 고통스러우시다면, 언제든 멈추셔도 좋습니다. 그러면 모든 게 끝날 테니까요.\"",
          DialogueId = 6201008,
          GUID = "0F8608E0",
          NextOptions = {
            [1] = 6201009
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201009] = {
          ContentKR = "거절할게요.",
          DialogueId = 6201009,
          GUID = "0F86090A",
          NextDialogue = 6201010,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201010] = {
          ContentKR = "모든 것을 끝낸다는 건, 당신 또한 저들 같은 유령이 된다는 의미다.\n상처받을 예민한 여린 마음이 사라지고, 고독에 대한 두려움도, 끝없는 반복이 주는 고통도 느끼지 못하게 되겠지.\n하지만... 그게 과연 행복일까?",
          DialogueId = 6201010,
          GUID = "0F860934",
          NextDialogue = 6201011,
          RougeTalkActorType = 3
        },
        [6201011] = {
          ContentKR = "\"아니에요.\" 당신은 다시 무기를 고쳐 잡는다.\n\"저는 계속 싸워서, 어떻게든 그 빌어먹을 유리를 찾아내고 말 거예요.\"",
          DialogueId = 6201011,
          GUID = "0F86095E",
          NextOptions = {
            [1] = 6201012
          },
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201012] = {
          ContentKR = "전 이제 출발해야겠어요.",
          DialogueId = 6201012,
          GUID = "0F860988",
          IsKeyOption = true,
          NextDialogue = 6201013,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201013] = {
          ContentKR = "\"다음에 또 뵙죠, 굳센 여행자님.\" 청년이 말한다. \"부디 여행자님의 여로에 늘 빛이 함께하길 바랍니다.\"",
          DialogueId = 6201013,
          GUID = "0F8609B2",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201101] = {
          ContentKR = "심연 행상인이 당신에게서 랜턴을 건네받는다. 아무 말 없이도, 두 사람은 익숙하게 서로의 잿불과 심지를 교환한다.\n이번에는 이곳에서 오래 머물지 않을 예정이다.",
          DialogueId = 6201101,
          GUID = "0F861822",
          NextOptions = {
            [1] = 6201102
          },
          RougeTalkActorType = 3
        },
        [6201102] = {
          ContentKR = "전 이제 출발해야겠어요.",
          DialogueId = 6201102,
          GUID = "0F86184C",
          IsKeyOption = true,
          NextDialogue = 6201103,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201103] = {
          ContentKR = "\"이걸 받아 주세요.\"\n뒤에서 청년의 목소리가 들리더니, 손에 무언가를 쥐여 준다.\n\"이건 빛이 나지 않으니까, 잿불은 안 주셔도 됩니다.\"\n수정처럼 투명한 사탕 한 알이, 피와 재로 더러워진 당신의 손 위에서 반짝인다.",
          DialogueId = 6201103,
          GUID = "0F861876",
          NextDialogue = 6201104,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201104] = {
          ContentKR = "사탕을 천천히 입안에 넣자, 산박하의 맛이 입안에 확 퍼진다. 정신이 그 어느 때보다도 맑아지고, 마침내 인간의 감각이 되돌아온다.\n머릿속을 떠돌던 그림자들의 흔적이 사라지고, 구름을 찌를 듯 솟아 있던 탑, 당신도 모르게 자꾸 올라가게 되던 떡갈나무, 접시 위의 차가운 크림, 정원에서 흔들리던 그네가 떠오른다.\n이 모든 건 당신이 살아온 증거다.",
          DialogueId = 6201104,
          GUID = "0F8618A0",
          NextDialogue = 6201105,
          RougeTalkActorType = 3
        },
        [6201105] = {
          ContentKR = "그렇다면, 이 수수께끼의 심연 행상인은 어떨까? 이 행상인은 사람일까? 아니면 유령일까? 이 행상인도 단맛을 좋아할까? 이 심연이라는 감옥에서 고통을 느끼고 있을까? 어쩌면 이 행상인도... 햇볕이 내리쬐는 세계에서 살았던 적이 있을까?\n하지만 이런 상념에 잠길 시간은 없다.\n당신은 영원히, 쉼 없이 싸워야만 한다.",
          DialogueId = 6201105,
          GUID = "0F8618CA",
          NextDialogue = 6201106,
          RougeTalkActorType = 3
        },
        [6201106] = {
          ContentKR = "\"다음에 또 뵙죠, 맑은 정신의 여행자님.\" 청년이 말한다. \"여행자님의 여로에 늘 빛이 함께하길 바랍니다.\"",
          DialogueId = 6201106,
          GUID = "0F8618F4",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201201] = {
          ContentKR = "요즘 들어 피로를 거의 느끼지 못하고 있다. 심지어는 저 그림자들과 스스럼없이 대화를 나눌 정도다.\n마음이 단단해지고 무뎌진 것인지, 아니면 무너져 내리기 직전의 전조인지는 알 수 없다.\n그렇지만 적어도 지금 이 순간만큼은, 기분이 나쁘지 않다.",
          DialogueId = 6201201,
          GUID = "0F86288A",
          NextDialogue = 6201202,
          RougeTalkActorType = 3
        },
        [6201202] = {
          ContentKR = "\"하루는 포르소를 믿는 사람들이랑 네파를 믿는 사람들을 만났었어요.\"\n\"한쪽은 빛을 믿는다고 하고, 다른 한쪽은 어둠을 숭배한다고 하던데, 그쪽 신들한테 관심 없다고 하니까, 양쪽 다 험한 소리를 해서 엄청 웃기더라고요.\"\n\"당신은 어때요? 당신도 누굴 믿나요?",
          DialogueId = 6201202,
          GUID = "0F8628B4",
          NextDialogue = 6201203,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201203] = {
          ContentKR = "\"저는 포르소님의 시종입니다.\"\n상인이 자신과 관련된 질문에 대답한 건 이번이 처음이다.\n\"저는 그분을 존경하고, 그분의 자애를 찬미하며, 만월의 광휘를 경배하죠.\"",
          DialogueId = 6201203,
          GUID = "0F8628DE",
          NextDialogue = 6201204,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201204] = {
          ContentKR = "더 흥미로운 대답을 기대했는데, 심연 행상인의 대답은 조금 의외다.",
          DialogueId = 6201204,
          GUID = "0F862908",
          NextDialogue = 6201205,
          RougeTalkActorType = 3
        },
        [6201205] = {
          ContentKR = "\"그러니까, 엘리시안 교회의 교리를 믿는다는 거네요?\"\n\"만월의 여신께 경건하게 기도만 드리면, 여신님이 행복의 실을 자아내서 우리를 구원해 주신다는 거죠?\"",
          DialogueId = 6201205,
          GUID = "0F862932",
          NextDialogue = 6201206,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201206] = {
          ContentKR = "\"아니요. 저는 포르소님을 <H>따를</> 뿐 <H>믿지</>는 않습니다.\"\n\"그저 제가 옳다고 믿는 길을 걷기 위한, 확고한 명분이 필요할 뿐입니다.\"",
          DialogueId = 6201206,
          GUID = "0F86295C",
          NextOptions = {
            [1] = 6201207
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201207] = {
          ContentKR = "무슨 뜻인지 잘 모르겠어요.",
          DialogueId = 6201207,
          GUID = "0F862986",
          NextDialogue = 6201208,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201208] = {
          ContentKR = "\"서로 빼앗지 않고 베풀어야 한다.\"\n\"서로 증오하지 않고, 사랑해야 한다.\"\n\"서로 상처 주지 않고, 포용해야 한다.\"\n\"이게 바로 제가 믿는 '올바름'입니다만... 인간이 자유롭다는 걸 믿는다면, 이것들이 왜 옳은지 증명할 길이 사라지죠.\"",
          DialogueId = 6201208,
          GUID = "0F8629B0",
          NextDialogue = 6201209,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201209] = {
          ContentKR = "\"그래서 저는 '자유'를 포기하고, 모든 것을 초월한 포르소를 택했습니다. 덕분에 제가 옳다고 여기는 것들은, 증명이 필요 없는 절대적인 진리가 되었고요.\"\n상인의 한숨 소리가 들려온다.\n\"어떤 의미에선, 제가 포르소님의 가장 불경한 신도일지도 모르겠군요.\"",
          DialogueId = 6201209,
          GUID = "0F8629DA",
          NextDialogue = 6201210,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201210] = {
          ContentKR = "\"그러니까, 결론은...\"\n당신은 머릿속으로 생각을 정리한다.\n\"만약 왜 계속 이 심연을 돌아다녀야 하는지 스스로를 설득하고 싶다면... 음, 걷기의 신 같은 걸 믿으면서, 계속 걸어야 한다고 믿으라는 건가요?\"",
          DialogueId = 6201210,
          GUID = "0F862A04",
          NextDialogue = 6201211,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201211] = {
          ContentKR = "\"음... 뭐, 그렇게 이해하셔도 좋습니다.\"\n상인이 작게 웃는다.",
          DialogueId = 6201211,
          GUID = "0F862A2E",
          NextOptions = {
            [1] = 6201212
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201212] = {
          ContentKR = "참 희한한 사람이군요. 아무튼 전 이제 가 볼게요. 여기에 너무 오래 있었어요.",
          DialogueId = 6201212,
          GUID = "0F862A58",
          IsKeyOption = true,
          NextDialogue = 6201213,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201213] = {
          ContentKR = "\"다음에 또 뵙죠, 슬기로운 여행자님.\" 청년이 말한다. \"여행자님의 여로에 늘 빛이 함께하길 바랍니다.\"",
          DialogueId = 6201213,
          GUID = "0F862A82",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201301] = {
          ContentKR = "\"마지막으로 언제 쉬었는지 이제 기억도 안 나요.\"\n이곳에 도착하기 전부터, 이번 거래를 염두에 두고 있었다.\n\"혹시 그쪽한테서... 꿈도 살 수 있어요?\"\n\"판다면 말이에요.\"",
          DialogueId = 6201301,
          GUID = "0F8638F2",
          NextDialogue = 6201302,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201302] = {
          ContentKR = "\"저는 직몽사가 아니라 원하시는 꿈을 보여 드릴 수 있을지 모르겠군요.\"\n상인이 천천히 고개를 젓는다.\n\"하지만, 시도는 해 보겠습니다.\"\n\"오래전 일이지만, 제가 누이에게 이야기를 들려주면, 누이는 항상 곤히 잠들곤 했거든요.\"",
          DialogueId = 6201302,
          GUID = "0F86391C",
          NextDialogue = 6201303,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201303] = {
          ContentKR = "당신은 짚 더미를 모아 최대한 푹신한 자리를 만든다.\n다시금 피로가 온몸을 짓누른다. 꿈이라도 좋으니, 조금 쉬고 싶어진다.",
          DialogueId = 6201303,
          GUID = "0F863946",
          NextDialogue = 6201304,
          RougeTalkActorType = 3
        },
        [6201304] = {
          ContentKR = "\"옛날 옛적에, 금을 다루는 소년이 달님을 사랑했답니다.\"\n\"소년은 몰래 달님의 치수를 쟀답니다. 이 세상에서 가장 반짝이는 보석으로 가장 아름다운 목걸이를 만들어, 저 가느다란 초승달에게 선물하기로 마음먹었거든요.\"\n\"하지만, 마침내 목걸이를 완성했을 때, 달님은 어느새 살이 조금 올라 그 예쁜 목걸이가 맞지 않게 되었습니다.\"\n\"소년은 새로 만들기로 했습니다. 그리곤 자신이 가진 모든 보석을 아낌없이 박아 넣었죠. 하지만 달님은 그새 둥근 쟁반처럼 더욱 통통해지고 말았어요.\"",
          DialogueId = 6201304,
          GUID = "0F863970",
          NextDialogue = 6201305,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201305] = {
          ContentKR = "이건 아주 오래된 동화다. 어머니께서 이야기해 주신 기억이 희미하게 난다.\n희미한 졸음이 당신을 감싸안는다.",
          DialogueId = 6201305,
          GUID = "0F86399A",
          NextDialogue = 6201306,
          RougeTalkActorType = 3
        },
        [6201306] = {
          ContentKR = "\"...젊은 금속 장인은, 그렇다면 크기가 다른 목걸이를 3개 만들면 그중 하나는 맞을 것이라고 생각했습니다.\"\n\"하지만 그 목걸이들을 바치려고 하자, 달님이 보이지 않았습니다. 칠흑 같은 밤하늘에는 처음부터 달님은 존재하지도 않았던 것처럼, 별들만 가득할 뿐이었습니다.\"",
          DialogueId = 6201306,
          GUID = "0F8639C4",
          NextDialogue = 6201307,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201307] = {
          ContentKR = "당신은 은빛 꿈결 속으로 서서히 가라앉는다.",
          DialogueId = 6201307,
          GUID = "0F8639EE",
          NextDialogue = 6201308,
          RougeTalkActorType = 3
        },
        [6201308] = {
          ContentKR = "\"...달님을 잃은 금속 장인은 매일 망치질을 하며, 헛되이 목걸이만 만들고 또 만들었습니다.\"\n\"땅에 떨어진 금속 장인의 눈물에선 투명한 나무가 자라났고, 그가 사랑했던 달님처럼 영롱한 열매가 열렸습니다.\"\n\"훗날, 사람들은 그 나무를 '천국의 나무', 그 열매를 '월석'이라 불렀답니다...\"\n\"피곤한 여행자님, 잠드신 건가요? 부디 좋은 꿈 꾸시길.\"",
          DialogueId = 6201308,
          GUID = "0F863A18",
          NextDialogue = 6201309,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201309] = {
          ContentKR = "첫 번째 꿈에서 보인 건 꽃이 가득 핀 정원에 있는 그네였다.\n당신은 아주 어려져 있었고, 그네 옆에는 나이가 지긋한 집사가 어서 오라는 듯 당신을 향해 두 팔을 벌리고 있었다.\n\"어서 오십시오, 우리 ▇▇.\"\n......",
          DialogueId = 6201309,
          GUID = "0F863A42",
          NextDialogue = 6201310,
          RougeTalkActorType = 3
        },
        [6201310] = {
          ContentKR = "두 번째 꿈에선 백리향이 가득 핀 언덕에 서 있는 젊은 기사들의 모습이 보였다.\n젊은 기사들이 쥐고 있던 금빛 아이리스 깃발이 바람에 나부끼고, 그들이 미소 지으며 내 이름을 부른다.\n\"출발하세요, 우리 ▇▇님.\"\n......",
          DialogueId = 6201310,
          GUID = "0F863A6C",
          NextDialogue = 6201311,
          RougeTalkActorType = 3
        },
        [6201311] = {
          ContentKR = "세 번째 꿈에선 당신과 똑같은 랜턴을 든 여행자가 보인다. 당신은 이 사람과 지금껏 3번 마주쳤다.\n{성별: 남자|여자}가 내게서 멀어지며, 그윽한 어둠으로 발을 내딛는다.\n당신은 헐레벌떡 그 사람을 뒤쫓는다.",
          DialogueId = 6201311,
          GUID = "0F863A96",
          NextDialogue = 6201312,
          RougeTalkActorType = 3
        },
        [6201312] = {
          ContentKR = "\"여기 남아주면 안 돼?\"\n소리쳐 보지만 목소리가 잠겨 쇳소리가 난다. 그 어떤 전투 때보다도 비참한 모습이다.",
          DialogueId = 6201312,
          GUID = "0F863AC0",
          NextDialogue = 6201313,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201313] = {
          ContentKR = "\"미안해, ▇▇.\"\n{성별: 남자|여자}가 고개를 돌리자, 흔들리는 불빛이 어렴풋이 {성별: 그|그녀}의 얼굴을 비춘다.\n\"우리는 서로 <H>정반대의 길</>을 걸어야만 해. 그래서, 난 떠날 수밖에 없어.\"",
          DialogueId = 6201313,
          GUID = "0F863AEA",
          NextDialogue = 6201314,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char02"
        },
        [6201314] = {
          ContentKR = "\"그렇지만... 이제 혼자는 싫어!\"\n당신은 아이가 떼를 쓰듯 그 사람의 옷자락을 향해 손을 뻗었지만, 결국 아무것도 잡지 못한다.\n마지막으로 울어 본 게 언제였을까? 두 눈에 눈물이 흐른다...",
          DialogueId = 6201314,
          GUID = "0F863B14",
          NextDialogue = 6201315,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201315] = {
          ContentKR = "\"울지 마, ▇▇.\"\n{성별: 남자|여자}가 당신의 뺨에 흐르는 눈물을 다정하게 닦아 주자, 그의 호흡과 인간의 따스한 체온이 느껴진다.\n\"우리의 여정은 결국 <H>하나의 원</>을 그리는 거야. 그러니까 서로 반대 방향으로 가더라도, 우린 꼭 다시 만날 수 있어.\"",
          DialogueId = 6201315,
          GUID = "0F863B3E",
          NextDialogue = 6201316,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char02"
        },
        [6201316] = {
          ContentKR = "{성별: 남자|여자}가 들고 있던 랜턴이 점점 밝아지며, 마치 은빛 실을 내뿜는 만월처럼, 눈부신 은빛 광채를 발한다...\n이윽고, 그 {성별: 남자|여자}는 그 찬란한 은백색 빛 속으로 걸어 들어간다.\n......\n......\n당신은 산박하의 향기에 잠에서 깨어난다.",
          DialogueId = 6201316,
          GUID = "0F863B68",
          NextDialogue = 6201317,
          RougeTalkActorType = 3
        },
        [6201317] = {
          ContentKR = "\"좋은 꿈 꾸셨나요?\"",
          DialogueId = 6201317,
          GUID = "0F863B92",
          NextDialogue = 6201318,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201318] = {
          ContentKR = "\"네... 아주 긴 꿈이었어요. 몇 년은 훌쩍 지나 버린 것처럼 정말 길었죠.\"",
          DialogueId = 6201318,
          GUID = "0F863BBC",
          NextDialogue = 6201319,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201319] = {
          ContentKR = "\"잘됐네요. 아직 꿈을 꿀 수 있다니, 운이 아주 좋군요.\"",
          DialogueId = 6201319,
          GUID = "0F863BE6",
          NextDialogue = 6201320,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201320] = {
          ContentKR = "당신은 자리에서 몸을 일으키고, 랜턴을 단단히 움켜쥔다. 다시 전장으로...\n끝이 보이지 않는 고독한 여정으로 돌아갈 시간이다.",
          DialogueId = 6201320,
          GUID = "0F863C10",
          NextOptions = {
            [1] = 6201321
          },
          RougeTalkActorType = 3
        },
        [6201321] = {
          ContentKR = "고마워요, 전 이제 슬슬 가 볼게요.",
          DialogueId = 6201321,
          GUID = "0F863C3A",
          IsKeyOption = true,
          NextDialogue = 6201322,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201322] = {
          ContentKR = "\"다음에 또 뵙죠, 인내하는 여행자님.\" 청년이 말한다.\n\"부디 여행자님이, 이제 더는 홀로이지 않기를 바랍니다.\"",
          DialogueId = 6201322,
          GUID = "0F863C64",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201401] = {
          ContentKR = "칠흑 같은 어둠, 그리고 더 깊은 암흑...\n당신은 고요한 물속을 부유하고 있다.\n깊고 어두운 강을 따라, 아래로 또 아래로.",
          DialogueId = 6201401,
          GUID = "0F86495A",
          NextDialogue = 6201402,
          RougeTalkActorType = 3
        },
        [6201402] = {
          ContentKR = "...그때, 멀리서 빛 하나가 다가온다.\n바로 <H>랜턴</>이다.",
          DialogueId = 6201402,
          GUID = "0F864984",
          NextDialogue = 6201403,
          RougeTalkActorType = 3
        },
        [6201403] = {
          ContentKR = "\"왔구나. 돌아올 줄 알고 있었단다.\"\n일렁이는 랜턴 너머로 모습을 드러낸 건, 나이 든 노부인이었다.",
          DialogueId = 6201403,
          GUID = "0F8649AE",
          NextOptions = {
            [1] = 6201404
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201404] = {
          ContentKR = "절 아세요?",
          DialogueId = 6201404,
          GUID = "0F8649D8",
          NextDialogue = 6201405,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201405] = {
          ContentKR = "\"그럼.\"\n노부인의 바짝 메마른 눈에 마치 꽃이 피어나듯 생기가 돈다.\n\"널 아주 오랫동안 기다려 왔지.\"",
          DialogueId = 6201405,
          GUID = "0F864A02",
          NextOptions = {
            [1] = 6201406
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201406] = {
          ContentKR = "제가 누구였는지 기억이 나질 않아요.",
          DialogueId = 6201406,
          GUID = "0F864A2C",
          NextDialogue = 6201407,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201407] = {
          ContentKR = "\"우리의 여정은 결국 <H>원 하나</>를 그리는 일이란다.\"\n노부인의 입가에 옅은 웃음이 번진다.\n\"다시 이곳에 돌아오게 되면, 그때 모든 게 떠오를 거야.\"",
          DialogueId = 6201407,
          GUID = "0F864A56",
          NextOptions = {
            [1] = 6201408
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201408] = {
          ContentKR = "전 이제 뭘 해야 하나요?",
          DialogueId = 6201408,
          GUID = "0F864A80",
          NextDialogue = 6201409,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201409] = {
          ContentKR = "\"여길 떠나렴. 이 <H>심연</>에서 벗어나는 건 <H>모든 너</>의 오랜 염원이었거든.\"\n노부인이 내 손에 랜턴을 쥐여 준다. 유령처럼 차가운 손길이지만, 랜턴에서 뿜어져 나오는 황금빛 광채는 강렬하고 따스하다.\n불현듯, 랜턴에 <H>눈금</>이 새겨진 작은 다이얼이 박혀 있는 게 눈에 들어온다.",
          DialogueId = 6201409,
          GUID = "0F864AAA",
          NextOptions = {
            [1] = 6201410
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201410] = {
          ContentKR = "어떻게 하면 여길 떠날 수 있죠?",
          DialogueId = 6201410,
          GUID = "0F864AD4",
          IsKeyOption = true,
          NextDialogue = 6201411,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201411] = {
          ContentKR = "\"이건 신의 축복이 깃든 랜턴이란다.\"\n\"<H>순수한 유리</>를 충분히 모아, 이 랜턴의 원래 모습을 되찾아 주면, 이 심연의 바다에도 길이 열릴 게야.\"\n\"목숨이 위험해지거든, 그 다이얼을 <H>거꾸로</> 돌리렴.\"",
          DialogueId = 6201411,
          GUID = "0F864AFE",
          NextDialogue = 6201412,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201412] = {
          ContentKR = "\"여정을 시작하기 전에, 이 심연에 얽힌 이야기를 들어 보겠니?\"\n노부인은 여전히 고요하고 온화하게 미소 짓는다.\n\"이 이야기들은 시간이라는 강을 부유하는 나무토막과 비슷하단다... 내가 우리의 여정은 결국 하나의 원을 그리는 거라고 했었지? 어떤 이야기는 네게 '과거'의 이야기일 수도 있고, 반대로 '미래'의 이야기일 수도 있단다.\"\n\"하지만 이것만은 기억하렴. <H>이 이야기의 주인공은 바로 너란다</>.\"",
          DialogueId = 6201412,
          GUID = "0F864B28",
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201501] = {
          ContentKR = "어둠 속에서 둔탁하게 발을 질질 끄는 소리가 들려온다.\n소리가 나는 방향으로 향하자, 침묵의 황혼 소대 소속 젊은 기사들의 모습이 보인다. 당신은 이번에도 이들과 여정에서 마주친다. 이 네 명은 아직은 무사해 보이지만, 지난번과는 분위기가 완전히 달라져 있다.",
          DialogueId = 6201501,
          GUID = "0F8659C2",
          NextDialogue = 6201502,
          RougeTalkActorType = 3
        },
        [6201502] = {
          ContentKR = "\"대체 얼마나 더 가야 해요? 우리, 얼마나 걸었죠?\"\n마법사는 마치 망토가 아닌 무거운 석판을 두르고 있는 것처럼, 피로에 잠긴 목소리로 말한다.",
          DialogueId = 6201502,
          GUID = "0F8659EC",
          NextDialogue = 6201503,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201503] = {
          ContentKR = "\"나흘이었나...? 아니, 닷새였나...? 더 오래됐을지도 모르죠. 제 회중시계는 먹통이 된 지 오래라서요.\"\n평소에는 그렇게 경건하고 예의 바르던 사제마저도 까칠한 목소리로 이야기하고 있다.",
          DialogueId = 6201503,
          GUID = "0F865A16",
          NextDialogue = 6201504,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201504] = {
          ContentKR = "\"다들 지쳤으니까, 여기서 잠깐 쉬었다 가죠. 다들 잠깐 눈 좀 붙여요. 망은 제가 볼게요.\"\n상냥하게 말하는 청년의 목소리에서도 역력한 피로가 느껴진다.",
          DialogueId = 6201504,
          GUID = "0F865A40",
          NextDialogue = 6201505,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201505] = {
          ContentKR = "\"저도 같이 망볼래요! 그럼 깜빡 잠들어도, 서로 깨워 줄 수 있잖아요!\"\n캐시는 애써 밝은 목소리로 이야기하며, 자책하듯 \"미안해요\"라고 사과하려는 플린에게 그러지 말라는 눈빛을 보낸다.",
          DialogueId = 6201505,
          GUID = "0F865A6A",
          NextDialogue = 6201506,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201506] = {
          ContentKR = "네 사람은 그나마 바닥이 평평한 곳을 찾아, 짐을 풀고, 허술한 임시 야영지를 꾸린다.\n칼리스타와 밀턴이 눈을 붙이자, 플린과 캐시가 살짝 자리를 피한다. 마치 정지 화면처럼, 침묵이 두 사람의 뒷모습을 감싼다.\n갑자기, 플린이 고개를 푹 숙이며 자신과 캐시에게만 들릴 정도로 작게 한숨을 내쉰다.",
          DialogueId = 6201506,
          GUID = "0F865A94",
          NextDialogue = 6201507,
          RougeTalkActorType = 3
        },
        [6201507] = {
          ContentKR = "\"어? 대장이 한숨을 다 쉬네요?\" 소녀가 생긋 웃으며 주머니에서 작은 종이 꾸러미를 꺼낸다. \"사탕 드실래요? 몰래 챙겨 온 건데, 딱 2개 남았어요. 우리 둘이 하나씩 먹어요.\"",
          DialogueId = 6201507,
          GUID = "0F865ABE",
          NextDialogue = 6201508,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201508] = {
          ContentKR = "\"...괜찮아요. 캐시, 사탕 좋아하잖아요. 많이 먹어요.\"",
          DialogueId = 6201508,
          GUID = "0F865AE8",
          NextDialogue = 6201509,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201509] = {
          ContentKR = "\"사탕은 함께 나눠 먹어야 더 단 거예요.\"",
          DialogueId = 6201509,
          GUID = "0F865B12",
          NextDialogue = 6201510,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201510] = {
          ContentKR = "캐시는 사탕 한 알을 입에 쏙 넣고, 남은 한 알은 포장지째 플린의 손에 쥐여 준다. 하지만 플린은 아무 말 없이 고개만 숙이고 있다.\n캐시는 더는 캐묻지 않고, 입안에서 사탕을 굴리며, 친구가 생각을 정리하고 말해 주기를 기다린다.",
          DialogueId = 6201510,
          GUID = "0F865B3C",
          NextDialogue = 6201511,
          RougeTalkActorType = 3
        },
        [6201511] = {
          ContentKR = "\"아까... 검을 들고 있던 그림자 말이죠... 혹시 봤어요?\"\n드디어, 청년이 나직이 말문을 연다.",
          DialogueId = 6201511,
          GUID = "0F865B66",
          NextDialogue = 6201512,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201512] = {
          ContentKR = "\"적군 아군 안 가리고 같은 그림자까지 마구 베던 그 녀석이요? 저도 봤어요! 은빛 검에서 빛이 막 뿜어져 나오는 게, 대장이 동경하는 전설 속 기사님이 쓰던... 무기랑... 똑같던데요...\"\n캐시는 여기까지 말하다가 무언가 깨달은 듯, 고개를 돌려 플린을 바라본다.\n\"설마... 그게 <H>달오름</>의 기사님이에요?\"",
          DialogueId = 6201512,
          GUID = "0F865B90",
          NextDialogue = 6201513,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201513] = {
          ContentKR = "\"...맞아요, 그분이에요. 영상과 화첩은 질리도록 봐서, 착각했을 리는 절대 없어요.\"\n청년은 한숨을 내쉬며 두 손으로 자기 얼굴을 감싼다.\n\"솔직히... 알아본 순간, 너무 두려웠어요. 그분조차 굴복한 심연을, 우리가 무슨 수로 이겨 내죠? 우리도 결국 저렇게 되고, 저도... 동포들한테 칼을 휘두르게 되는 건 아닐까 하는 생각이 들었어요.\"",
          DialogueId = 6201513,
          GUID = "0F865BBA",
          NextDialogue = 6201514,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201514] = {
          ContentKR = "\"하긴, 심연에 들어오기 전까진 우리 중 누구도 여기가 이렇게 무시무시한 곳인 줄 몰랐으니까요... 그래도 전 믿어요. 인간의 의지로 심연 정도는 충분히 이겨 낼 수 있을 거예요.\"\n소녀가 친구의 등을 살며시 토닥인다.\n\"생각해 보세요, 그 기사님이 다른 그림자를 공격했다는 건, 아직 포기하지 않았다는 거 아닌가요? 그런 모습이 됐어도, 맨 처음 목표를 잊지 않은 거잖아요?\"",
          DialogueId = 6201514,
          GUID = "0F865BE4",
          NextDialogue = 6201515,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201515] = {
          ContentKR = "\"음...\"",
          DialogueId = 6201515,
          GUID = "0F865C0E",
          NextDialogue = 6201516,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201516] = {
          ContentKR = "대화에 끼어들 때가 아닌 것 같다. 당신은 젊은 기사들의 휴식을 방해하고 싶지 않다.\n하지만 막 자리를 떠나려는 순간, 캐시가 당신을 발견한다.",
          DialogueId = 6201516,
          GUID = "0F865C38",
          NextDialogue = 6201517,
          RougeTalkActorType = 3
        },
        [6201517] = {
          ContentKR = "\"어?\" 소녀가 잔뜩 들뜬 채 다가온다. \"저번에 그 여행자님이다! 무사해서 정말 다행이에요!\"",
          DialogueId = 6201517,
          GUID = "0F865C62",
          NextDialogue = 6201518,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201518] = {
          ContentKR = "청년 역시 놀란 기색으로 다가온다.\n\"역시 보통 분이 아니시군요. 저희보다 먼저 이 심연에 오셨을 텐데, 어떻게 아직까지 흔들림 없는 의지를 갖고 계신 거죠?\"",
          DialogueId = 6201518,
          GUID = "0F865C8C",
          NextOptions = {
            [1] = 6201519
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201519] = {
          ContentKR = "그냥... 익숙해진 것뿐이에요. 저도 한때 방황하고, 후회하고, 절망했지만, 이젠 다 받아들였어요.",
          DialogueId = 6201519,
          GUID = "0F865CB6",
          NextDialogue = 6201520,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201520] = {
          ContentKR = "청년의 놀라워하는 얼굴이 서서히 경외감으로 물든다.\n\"그러면... 심연을 어떻게 생각하시나요? 인간이, 심연을 이겨 낼 수 있다고 보세요?\"",
          DialogueId = 6201520,
          GUID = "0F865CE0",
          NextOptions = {
            [1] = 6201521,
            [2] = 6201524
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201521] = {
          ContentKR = "반드시 이겨 낼 수 있어요.",
          DialogueId = 6201521,
          GUID = "0F865D0A",
          IsKeyOption = true,
          NextDialogue = 6201522,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201522] = {
          ContentKR = "\"봐요, 여행자님도 그렇게 말씀하시잖아요. 우린 임무를 꼭 완수하고 말 거예요, 그러니까 기운 내요!\"",
          DialogueId = 6201522,
          GUID = "0F865D34",
          NextDialogue = 6201523,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201523] = {
          ContentKR = "소녀에게 오해를 산 모양이지만, 당신이 믿는 '승리'는 교회에서 이 기사들에게 준 목표와는 전혀 다르다.\n당신은 알고 있다. 이들을 기다리고 있는 건 고통과 절망뿐이며, 그들은 어떤 지옥에 갇혔는지도 모른 채, 수없이 죽음을 되풀이할 운명이다.\n그렇지만 당신은 입을 꾹 다문다. 어차피 바꿀 수 없는 미래라면, 차라리 모르는 편이 행복할 것이다.",
          DialogueId = 6201523,
          GUID = "0F865D5E",
          RougeTalkActorType = 3
        },
        [6201524] = {
          ContentKR = "잘 모르겠어요.",
          DialogueId = 6201524,
          GUID = "0F865D88",
          IsKeyOption = true,
          NextDialogue = 6201525,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201525] = {
          ContentKR = "\"여행자님께서도... 확답을 못 주시는군요...\"\n청년은 잠시 눈빛이 어두워지지만, 이내 고개를 들고, 이상할 정도로 단호하게 말한다. 자기를 격려하기 위해서인지, 스스로를 속이기 위해서인지는 당신도 알 수 없다.\n\"어쨌든, 엘리시안의 기사로서 저희는 물러설 수 없습니다. 정말로 희망이 없다 하더라도, 마지막 순간까지 싸울 겁니다.\"",
          DialogueId = 6201525,
          GUID = "0F865DB2",
          NextDialogue = 6201526,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201526] = {
          ContentKR = "당신은 알고 있다. 이들을 기다리고 있는 건 고통과 절망뿐이며, 그들은 어떤 지옥에 갇혔는지도 모른 채, 수없이 죽음을 되풀이할 운명이다.\n하지만 기사의 굳은 결의가 담긴 눈을 보자, 차마 입이 떨어지지 않는다.",
          DialogueId = 6201526,
          GUID = "0F865DDC",
          RougeTalkActorType = 3
        },
        [6201601] = {
          ContentKR = "격렬한 전투가 벌어지고 있음을 알리듯, 어둠 속에서 강철이 부딪히는 소리가 울려 퍼진다.\n젊은 기사가 힘껏 장검을 휘둘러, 눈앞의 그림자에게 최후의 일격을 가한다.",
          DialogueId = 6201601,
          GUID = "0F866A2A",
          NextDialogue = 6201602,
          RougeTalkActorType = 3
        },
        [6201602] = {
          ContentKR = "그 순간, 가느다란 검은 그림자가 스쳐 지나간다. 반사적으로 방패를 들어 기습을 막아 낸 기사는, 방패의 틈새에 박힌 화살을 보고 순식간에 얼어붙는다.\n바탕색은 검게 칠해져 있지만, 화살 깃에는 엘리시안을 상징하는 금빛 아이리스 문양이 선명하다. 이런 화살을 쓰는 건 단 한 사람뿐이다.",
          DialogueId = 6201602,
          GUID = "0F866A54",
          NextDialogue = 6201603,
          RougeTalkActorType = 3
        }
      }
    end
  },
  {
    MinKey = 6201603,
    MaxKey = 10011708,
    Loader = function()
      return {
        [6201603] = {
          ContentKR = "\"칼리스타...?\"",
          DialogueId = 6201603,
          GUID = "0F866A7E",
          NextDialogue = 6201604,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201604] = {
          ContentKR = "서서히 다가오는 그림자의 팔다리는 이미 어둠에 침식되어 망토와 거의 분간이 되지 않는다. '그녀'는 플린의 절규 따위는 들리지 않는 듯, 말없이 다시 활시위를 당긴다.",
          DialogueId = 6201604,
          GUID = "0F866AA8",
          NextDialogue = 6201605,
          RougeTalkActorType = 3
        },
        [6201605] = {
          ContentKR = "심연에 발을 들인 지 얼마 되지 않은 시점에 이들을 경악하게 만든 건, 자신들을 공격해 오는 그림자 중 대부분이 낯익은 얼굴이라는 사실이었다. 심연을 토벌하러 나섰던 엘리시안의 기사들은 사망 후 심연의 일부와 동화해, 한때 동료였던 이들에게 칼을 겨누는 존재가 되어 버렸다.",
          DialogueId = 6201605,
          GUID = "0F866AD2",
          NextDialogue = 6201606,
          RougeTalkActorType = 3
        },
        [6201606] = {
          ContentKR = "심연의 가장 끔찍한 저주는 바로 '생존' 그 자체가 저주라는 점이었다. 차라리 심연에 들어오고 얼마 되지 않아 목숨을 잃었다면, 생전의 모습을 간직한 평범한 망령이 되었을 것이다.",
          DialogueId = 6201606,
          GUID = "0F866AFC",
          NextDialogue = 6201607,
          RougeTalkActorType = 3
        },
        [6201607] = {
          ContentKR = "그렇지만 쉽게 죽지는 않겠다며 앞으로 나아가는 순간, 혼돈으로 가득 찬 어둠은 끊임없이 의지를 좀먹기 시작하고, 모든 전투는 도박이 된다. 잠깐이라도 의지가 흔들리면, 어둠이 이성을 집어삼켜 공격밖에 모르는 괴물로 전락하는 것이다.",
          DialogueId = 6201607,
          GUID = "0F866B26",
          NextDialogue = 6201608,
          RougeTalkActorType = 3
        },
        [6201608] = {
          ContentKR = "바로 지금 플린의 눈앞에 서 있는 '그녀'처럼.",
          DialogueId = 6201608,
          GUID = "0F866B50",
          NextDialogue = 6201609,
          RougeTalkActorType = 3
        },
        [6201609] = {
          ContentKR = "\"안 돼... 이러지 말아요... 당신을 해치고 싶지 않아요... 제발...\" 장검을 쥔 청년의 손이 떨리기 시작한다. \"이미 밀턴을 잃었어요. 만약 당신까지 잃는다면...\"",
          DialogueId = 6201609,
          GUID = "0F866B7A",
          NextDialogue = 6201610,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201610] = {
          ContentKR = "하지만 화살은 정확히 심장을 향해 또다시 날아온다. 청년은 방패로 화살을 막아냈지만, 또 다른 화살이 날아든다. 한 줄기 선혈이 그의 뺨을 타고 흐른다.",
          DialogueId = 6201610,
          GUID = "0F866BA4",
          NextDialogue = 6201611,
          RougeTalkActorType = 3
        },
        [6201611] = {
          ContentKR = "\"으아아악...!\"",
          DialogueId = 6201611,
          GUID = "0F866BCE",
          NextDialogue = 6201612,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201612] = {
          ContentKR = "고통스러운 절규가 메아리친다. 청년은 눈앞의 그림자가 사라질 때까지, 손에 쥔 장검을 휘두르고, 또 휘두르고, 다시 휘두른다.\n이미 잿더미가 되어 버린 동료 앞에서, 청년은 장검에 몸을 기댄 채 소리 없이 통곡한다.",
          DialogueId = 6201612,
          GUID = "0F866BF8",
          NextDialogue = 6201613,
          RougeTalkActorType = 3
        },
        [6201613] = {
          ContentKR = "슬픈 울음소리가 잦아들자, 주위가 이상할 정도로 고요해진다. 하지만 전투가 끝났는데도, 늘 곁에서 재잘거리며 함께 싸워 주던 친구가 평소처럼 웃으며 다가와 주지 않는다.",
          DialogueId = 6201613,
          GUID = "0F866C22",
          NextDialogue = 6201614,
          RougeTalkActorType = 3
        },
        [6201614] = {
          ContentKR = "\"캐시... 캐시? 괜찮아요?\"\n청년은 상처투성이 몸을 끌며, 친구가 있는 방향을 향해 조금씩 기어간다.",
          DialogueId = 6201614,
          GUID = "0F866C4C",
          NextDialogue = 6201615,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201615] = {
          ContentKR = "소녀는 청년의 외침이 들리지 않는 듯, 제자리에 서서 두 손을 힘없이 늘어뜨린 채, 곧 숨이 끊어질 사람처럼 가쁜 숨을 내쉰다.\n소녀의 상처에서 불길한 검은 기운이 아지랑이처럼 피어올라, 이내 사지를 휘감고, 아리따운 금빛 머리칼을 검게 물들이더니, 끝내 그녀의 형체를 집어삼킨다.",
          DialogueId = 6201615,
          GUID = "0F866C76",
          NextDialogue = 6201616,
          RougeTalkActorType = 3
        },
        [6201616] = {
          ContentKR = "장검이 피와 눈물이 뒤엉킨 진흙 바닥에 떨어지고, 청년은 힘없이 무릎을 꿇는다.",
          DialogueId = 6201616,
          GUID = "0F866CA0",
          NextDialogue = 6201617,
          RougeTalkActorType = 3
        },
        [6201617] = {
          ContentKR = "\"...항복할게요. 듣고 있어요?\"\n청년은 두 눈을 감고, 하늘을 향해 아무 감정도 느껴지지 않는 목소리로 말한다. 저 깊은 어둠도 하늘이라 부를 수 있다면 말이다.\n\"당신이 뭔지... 왜 우릴 이렇게까지 괴롭히는지 모르겠지만, 이젠 지긋지긋해요. 다 지겨우니까 그냥 여기서 끝냅시다. 저도 그만 데려가세요...\"",
          DialogueId = 6201617,
          GUID = "0F866CCA",
          NextDialogue = 6201618,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201618] = {
          ContentKR = "앞에서 부스럭거리는 소리와 함께, 무언가 천천히 다가온다. 하지만 플린은 모든 것을 체념한 채 눈을 감고 죽음을 기다린다.\n그때 누군가 청년의 장검을 주워, 다시 그의 손에 쥐여 준다.",
          DialogueId = 6201618,
          GUID = "0F866CF4",
          NextDialogue = 6201619,
          RougeTalkActorType = 3
        },
        [6201619] = {
          ContentKR = "\"제가 그렇게 못 미더웠나요?\"\n어둠 속에서 소녀의 목소리가 들려온다. 검은 그림자가 청년의 눈물을 닦고, 고개 숙인 그를 감싸안으며, 온몸의 핏자국을 가려 준다.\n\"걱정 말아요. 무슨 일이 있어도... 나만큼은 절대 변하지 않을게요. 약속해요.\"",
          DialogueId = 6201619,
          GUID = "0F866D1E",
          NextDialogue = 6201620,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201620] = {
          ContentKR = "\"...믿을게요.\"\n청년은 두 팔을 벌려, 기꺼이 그 어둠을 받아들인다.",
          DialogueId = 6201620,
          GUID = "0F866D48",
          NextDialogue = 6201621,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201621] = {
          ContentKR = "이 모든 게 부질없는 희망이고, 더 큰 고통을 안겨 줄 뿐이라는 사실을 알면서도, 당신은 끝내 외면할 수 없다...\n당신은 랜턴을 들고 서둘러 두 사람에게 다가간다. 유리의 반짝임이 그들을 뒤덮던 어둠을 내몰고, 소녀의 긴 머리카락도 다시 아름다운 금빛을 되찾는다.\n구조받은 두 기사는 고개를 들고, 멍하니 당신을 바라본다.",
          DialogueId = 6201621,
          GUID = "0F866D72",
          NextDialogue = 6201622,
          RougeTalkActorType = 3
        },
        [6201622] = {
          ContentKR = "\"여행자님...? 우리를 구해 준 거예요?\"\n소녀가 원래대로 되돌아온 자신의 두 손을 내려다보며, 믿기지 않는다는 표정을 짓는다.\n\"정말 감사해요! 평범한 분은 아닐 줄 알았지만, 이렇게 엄청난 힘을 가지고 계셨군요!\"",
          DialogueId = 6201622,
          GUID = "0F866D9C",
          NextDialogue = 6201623,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201623] = {
          ContentKR = "\"하아...\"\n청년은 아직도 머리가 얼떨떨한지, 한숨만 내쉰다.",
          DialogueId = 6201623,
          GUID = "0F866DC6",
          NextOptions = {
            [1] = 6201624
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201624] = {
          ContentKR = "고마워하지 않아도 돼요. 두 사람은... 이제 어쩔 셈이에요?",
          DialogueId = 6201624,
          GUID = "0F866DF0",
          IsKeyOption = true,
          NextDialogue = 6201625,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201625] = {
          ContentKR = "\"살아남았으니까, 계속 앞으로 나아가야죠. 아, 그래도 일단 좀 쉬면서, 플린의 몸 상태가 좀 나아지고 나면요.\"",
          DialogueId = 6201625,
          GUID = "0F866E1A",
          NextDialogue = 6201626,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201626] = {
          ContentKR = "당신의 염려를 눈치챘는지, 소녀가 환하게 웃어 보인다.",
          DialogueId = 6201626,
          GUID = "0F866E44",
          NextDialogue = 6201627,
          RougeTalkActorType = 3
        },
        [6201627] = {
          ContentKR = "\"여행자님, 저번에 플린이 했던 질문 아직 기억해요? 전 이제 답을 알 것 같아요.\" 소녀는 한층 차분하고 진중한 목소리로 천천히 말을 잇는다. \"진정으로 심연을 이길 수 있는 건, 전투도, 어느 한 사람도 아닌, 우리 모두의 노력이에요. 계속해 나가다 보면, 언젠가는... 분명히 뭔가 바뀔 거예요. 그러니까, 각자의 결말이 어떻든 너무 신경 쓸 필요 없어요. 계속 나아가면, 어떻게든 마지막 승리에 힘을 보태게 될 테니까요.\"",
          DialogueId = 6201627,
          GUID = "0F866E6E",
          NextDialogue = 6201628,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201628] = {
          ContentKR = "\"하하... 캐시는 그런 깊이 있는 말도 할 줄 아는군요... 몰랐어요. 대장인 제가 너무 한심해 보이네요.\"\n청년은 드디어 정신을 차린 듯, 친구의 부축을 받으며 곧게 일어선다.\n\"심연은 지금도 계속 넓어지고 있어요. 이대로 두면 엘리시안 전체를 삼키고 말 거예요. 시간 끌기밖에 안 되더라도, 끝까지 싸워야 해요. 게다가, 아직 리사벨 님도 못 찾았는걸요.\"",
          DialogueId = 6201628,
          GUID = "0F866E98",
          NextDialogue = 6201629,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201629] = {
          ContentKR = "\"맞아요! 리사벨 님이랑 같이 돌아가야 해요! 여행자님, 그러니까 저희는 걱정하지 말고, 여행자님의 길을 가세요. 저희 몫까지 뭔가를 짊어지려고 하지도 말고, 그냥 축복만 받아 주세요.\"\n소녀는 진지한 눈으로 당신을 바라보며, 가슴에 손을 얹는다.\n\"<H>운명의 신께서 그대에게 천 갈래의 달빛을 내리시어, 두 날개가 영원히 저 만월처럼 티 없이 희고 맑기를 바라노라.</>\"",
          DialogueId = 6201629,
          GUID = "0F866EC2",
          NextDialogue = 6201630,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201630] = {
          ContentKR = "이건 엘리시안에서 앞으로 다시 만날 수 없을지도 모르는 사람에게만 전하는 아주 엄숙한 축복이다.\n하지만, 이 축복은 작별을 비관하는 것이 아니라, 오히려 운명을 담담히 받아들이겠다는 의미를 담고 있다.\n\"당신의 앞날이 순조롭기를 바라지만, 만약 이게 우리의 마지막 만남이라 해도, 기꺼이 받아들일게요.\"",
          DialogueId = 6201630,
          GUID = "0F866EEC",
          NextDialogue = 6201631,
          RougeTalkActorType = 3
        },
        [6201631] = {
          ContentKR = "당신은 캐시에게 고개를 끄덕인 후, 랜턴을 쥔 채 다시 길을 나선다.",
          DialogueId = 6201631,
          GUID = "0F866F16",
          RougeTalkActorType = 3
        },
        [6201701] = {
          ContentKR = "심연에서 오랜만에 열정적이고, 생기 넘치고, 아직 심연의 어둠에 물들지 않은 청년 몇 명의 목소리가 들려온다.\n이건 망령도, 환영도 아닌, 살아 있는 사람의 목소리가 확실하다.",
          DialogueId = 6201701,
          GUID = "0F867A92",
          NextDialogue = 6201702,
          RougeTalkActorType = 3
        },
        [6201702] = {
          ContentKR = "당신은 또, 그들과 조우한다.",
          DialogueId = 6201702,
          GUID = "0F867ABC",
          NextDialogue = 6201703,
          RougeTalkActorType = 3
        },
        [6201703] = {
          ContentKR = "매번 그래 왔듯이, 안개 속에서 네 명의 기사가 모습을 드러낸다.\n아직도 이들이 피투성이가 된 채 쓰러진 모습이 생생하다. 재회는 과연 누구에게 더 잔인한 것일까? 절망 속에서 몇 번이고 죽음을 맞이하는 이들일까? 아니면 그 모습을 매번 지켜봐야 하는 나일까?",
          DialogueId = 6201703,
          GUID = "0F867AE6",
          NextDialogue = 6201704,
          RougeTalkActorType = 3
        },
        [6201704] = {
          ContentKR = "\"이 방향 맞아요, 대장?\"\n젊은 금발의 여기사가 낡은 계단을 성큼성큼 올라갔다가, 단숨에 뛰어내린다.\n\"여긴 그냥 폐허 같은데요.\"",
          DialogueId = 6201704,
          GUID = "0F867B10",
          NextDialogue = 6201705,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201705] = {
          ContentKR = "\"우리가 와 본 적 없는 곳인 건 확실해요.\"\n대장이라 불린 청년이 침착하게 소녀의 옆을 지나간다.\n\"성스러운 호수에선 방향 감각이 무뎌지니까, 일단은 가는 데까지 가 보는 수밖에 없어요.\"",
          DialogueId = 6201705,
          GUID = "0F867B3A",
          NextOptions = {
            [1] = 6201706,
            [2] = 6201716
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201706] = {
          ContentKR = "돌아가요... 아직 늦지 않았어요.",
          DialogueId = 6201706,
          GUID = "0F867B64",
          IsKeyOption = true,
          NextDialogue = 6201707,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201707] = {
          ContentKR = "\"음? 실례지만 누구신지...?\"",
          DialogueId = 6201707,
          GUID = "0F867B8E",
          NextDialogue = 6201708,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201708] = {
          ContentKR = "\"리사벨의 친구들, 맞죠? 말 좀 전해 달라는 부탁을 받았거든요. 심연은 상상 이상으로 위험해서, 기사단 소대 하나론 감당 못 하니까, 무의미한 희생 하지 말고 돌아가라고 했어요.\"\n이제 다른 걸 신경 쓸 겨를은 없다. 전부 거짓말이라도 좋으니, <W>이번만큼은</> 이 사람들이 살아남아 주었으면 한다.",
          DialogueId = 6201708,
          GUID = "0F867BB8",
          NextDialogue = 6201709,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201709] = {
          ContentKR = "\"어?! 리사벨 님의 행방을 아세요? 무사하신가요? 지금 어디 계세요?\"",
          DialogueId = 6201709,
          GUID = "0F867BE2",
          NextDialogue = 6201710,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201710] = {
          ContentKR = "\"잠깐만요, 캐시.\"\n사제가 동료를 가로막으며, 의심의 눈초리로 당신을 바라본다.\n\"리사벨 님은 결코 나약한 분이 아니에요. 그분의 이름을 빙자한 거짓말은 삼가 주세요. 그리고, 심연 토벌은 교황 성하께서 직접 내리신 명령인 만큼, 이 앞이 지옥이라도, 저희는 물러서지 않을 겁니다.\"",
          DialogueId = 6201710,
          GUID = "0F867C0C",
          NextDialogue = 6201711,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201711] = {
          ContentKR = "당신은 나직이 한숨을 삼킨다.\n사람들은 '지옥'이라는 단어가 무슨 뜻인지도 모르면서, 너무도 쉽게 그 단어를 내뱉곤 한다.",
          DialogueId = 6201711,
          GUID = "0F867C36",
          NextDialogue = 6201712,
          RougeTalkActorType = 3
        },
        [6201712] = {
          ContentKR = "\"우리보고 돌아가라고...\"\n망토를 두른 여자 마법사가 깊이를 알 수 없는 눈으로 바라보며, 싸늘하게 말한다.\n\"솔직히... 우리가 돌아간다 해도, 아무 의미 없잖아요, 안 그래요?\"",
          DialogueId = 6201712,
          GUID = "0F867C60",
          NextDialogue = 6201713,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201713] = {
          ContentKR = "당신은 아무 대답도 할 수 없다.\n저 마법사의 말대로, 지금 돌아가 봐야, 왔던 길은 찾을 수 없거니와, 이 심연에서 '전진'과 '후퇴'를 나누는 것 자체가 무의미한 자기기만에 불과하다.\n이들을 정말 구하고 싶다면, 이 절망의 순환을 끊어 내야만 한다.",
          DialogueId = 6201713,
          GUID = "0F867C8A",
          NextDialogue = 6201714,
          RougeTalkActorType = 3
        },
        [6201714] = {
          ContentKR = "\"저기요...\"\n당신은 젊은 기사들을 바라보며, 경건하게 가슴에 손을 올린다.\n\"<H>운명의 신께서 그대들에게 천 갈래의 달빛을 내리시어, 그대들의 날개가 영원히 저 만월처럼 티 없이 희고 맑기를 바라노라.</>\"",
          DialogueId = 6201714,
          GUID = "0F867CB4",
          NextDialogue = 6201715,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201715] = {
          ContentKR = "내 축복을 들은 칼리스타가 서글픈 미소를 짓는다.\n설령 거짓말일지라도, 그녀는 내심 당신이 자신의 말을 부정해 주길 바랐을지도 모른다.",
          DialogueId = 6201715,
          GUID = "0F867CDE",
          RougeTalkActorType = 3
        },
        [6201716] = {
          ContentKR = "용감한 기사들이여, 만월의 신께서 그대들의 여정을 굽어살펴 주시기를.",
          DialogueId = 6201716,
          GUID = "0F867D08",
          IsKeyOption = true,
          NextDialogue = 6201717,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201717] = {
          ContentKR = "\"음?\"\n당신의 갑작스러운 축복에, 청년은 당혹감을 감추지 못한다.\n\"실례지만 누구시죠...?\"",
          DialogueId = 6201717,
          GUID = "0F867D32",
          NextDialogue = 6201718,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201718] = {
          ContentKR = "\"리사벨의 친구들, 맞죠? 말 좀 전해 달라는 부탁을 받았거든요. 심연은 상상 이상으로 위험해서, 지금껏 겪어 보지 못한 어려움과 도전을 마주하게 될 테니까, 각오 단단히 하라고 했어요.\"",
          DialogueId = 6201718,
          GUID = "0F867D5C",
          NextDialogue = 6201719,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201719] = {
          ContentKR = "\"어?! 리사벨 님의 행방을 아세요? 무사하신가요? 지금 어디 계세요?\"",
          DialogueId = 6201719,
          GUID = "0F867D86",
          NextDialogue = 6201720,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201720] = {
          ContentKR = "\"잠깐만요, 캐시. 누군지도 모를 사람을 쉽게 믿으면 안 돼요.\"\n사제가 동료를 가로막으며, 의심의 눈초리로 당신을 바라본다.\n\"리사벨 님은 그리 성숙한 분은 아니시니, 그렇게 진지한 말씀을 하셨을 리 없습니다. 또한, 심연 토벌은 교황 성하께서 직접 내리신 명령인 만큼, 굳이 주의 주시지 않아도, 저희는 최선을 다할 겁니다.\"",
          DialogueId = 6201720,
          GUID = "0F867DB0",
          NextDialogue = 6201721,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201721] = {
          ContentKR = "\"전 오히려 이 여행자가 진실을 말하고 있는 것 같아요. 이런 데 오래 있다 보면 정신도 나가는데, 성격 좀 바뀌는 게 뭐 대수인가요...\"\n여자 마법사는 고개를 들고, 마치 수수께끼의 답을 찾으려는 듯 깊은 눈으로 당신을 빤히 바라본다.\n\"여행자님은 누구시죠? 왠지... 전에 만난 적 있는 것 같은데요.\"",
          DialogueId = 6201721,
          GUID = "0F867DDA",
          NextDialogue = 6201722,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201722] = {
          ContentKR = "\"...제가 누군지는 중요하지 않아요.\"\n당신은 젊은 기사들을 바라보며, 담담히 미소 짓는다.\n\"진심 어린 축복이었다는 것만 알아주세요. 결말이 정해져 있다 해도... 모두 이 여정의 의미를 발견할 수 있길 바랄게요.\"",
          DialogueId = 6201722,
          GUID = "0F867E04",
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201801] = {
          ContentKR = "저 멀리, 밀턴과 칼리스타가 그림자에 포위되어 고전하고 있다.\n서로 힘을 합쳐 몰아치는 공격을 막아 내고 있지만, 그림자는 끝없이 밀려든다.\n랜턴을 들고 두 사람에게 다가간다. 유리가 반짝이며 빛을 내뿜자 그림자들이 잠시 물러난다.",
          DialogueId = 6201801,
          GUID = "0F868AFA",
          NextDialogue = 6201802,
          RougeTalkActorType = 3
        },
        [6201802] = {
          ContentKR = "\"당신은 그때 그...\"\n사제는 당신을 보고 깜짝 놀라더니, 이내 미안한 기색을 보인다.\n\"제가 그렇게 의심했는데도, 이렇게 도움을 주시다니... 정말 감사하고 또 죄송합니다, 신비로운 여행자님.\"",
          DialogueId = 6201802,
          GUID = "0F868B24",
          NextDialogue = 6201803,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201803] = {
          ContentKR = "\"역시 보통 분은 아니었군요. 도움, 감사해요.\"\n마법사가 예를 표하며 망토에 달린 모자를 벗는다. 다만, 그 아래 드러난 머리카락은 여전히 칠흑 같은 검은색이다.\n\"들고 계신 그 랜턴... 혹시 신성한 힘이 깃들어 있는 물건인가요? 어째서 그림자들을 쫓아낼 수 있는 거죠?\"",
          DialogueId = 6201803,
          GUID = "0F868B4E",
          NextOptions = {
            [1] = 6201804
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201804] = {
          ContentKR = "다른 사람한테 받은 거예요.",
          DialogueId = 6201804,
          GUID = "0F868B78",
          NextDialogue = 6201805,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201805] = {
          ContentKR = "\"그렇다면 더는 묻지 않을게요. 하지만, 그 랜턴이 있으면 심연 속에서 움직이기 수월할 것 같은데, 혹시 저희가 동행해도 될까요?\"",
          DialogueId = 6201805,
          GUID = "0F868BA2",
          NextDialogue = 6201806,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201806] = {
          ContentKR = "\"딱히 상관은 없는데, 서로 목표가 다를 거예요. 전 이 랜턴을 고치려고 유리 조각을 모으고 있는 것뿐이거든요.\"",
          DialogueId = 6201806,
          GUID = "0F868BCC",
          NextDialogue = 6201807,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201807] = {
          ContentKR = "\"저희 목표는 더 이상 중요하지 않아요... 직감으로 알 수 있어요. 이 심연의 진실에 도달하려면, 여행자님과 동행하는 편이 낫다고요.\"",
          DialogueId = 6201807,
          GUID = "0F868BF6",
          NextDialogue = 6201808,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201808] = {
          ContentKR = "\"무슨 헛소리를 하는 거예요, 칼리스타?\"\n당신이 뭐라 대답하기도 전에, 사제가 급하게 동료를 꾸짖는다.\n\"비록 다른 소대원들과 떨어졌다고는 해도... 우리는 여전히 엘리시안의 기사예요. 단 한 명이 남더라도, 사명을 포기해서는 안 돼요!\"",
          DialogueId = 6201808,
          GUID = "0F868C20",
          NextDialogue = 6201809,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201809] = {
          ContentKR = "\"하하... 사명, 그놈의 사명, 당신 머릿속엔 그런 허울 좋은 것 말곤 없어요?\"\n마법사도 감정이 격해졌는지, 화살통에 든 화살이 그녀의 움직임에 맞춰 달그락거리는 소리를 낸다.\n\"우리가 여기서 마주친 게 뭐였죠? 필토이드에 환영, 온갖 망령들 아니었나요? 높으신 분들 말대로 성스러운 호수에 들어간 사람들이 제천의 하늘로 승천했다면, 우리가 본 그림자들은 뭐죠? 여긴 성스러운 호수보단, 암월파가 말하는 마왕의 소굴하고 더 닮지 않았나요...?\"",
          DialogueId = 6201809,
          GUID = "0F868C4A",
          NextDialogue = 6201810,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201810] = {
          ContentKR = "\"감히... 그런 말을! 지금 그 발언은 이단들이나 하는 소리예요!\"\n사제는 애써 침착함을 유지하려 하지만, 목소리에서 미세한 망설임이 묻어난다.\n\"우리가 본 그림자들은... 신앙이 부족해 마지막 시련을 통과하지 못한 자들일지도 몰라요. 그런 불필요한 장애물을 모두 제거하면, 성스러운 호수도 제 모습을 되찾을 거예요. 어쩌면, 이건 아홉 신께서 우리를 시험하시는 걸지도 모르겠군요. 우리가 경건한 마음을 잃지 않는다면, 신들께서 우리를 침식으로부터 보호해 주실...\"",
          DialogueId = 6201810,
          GUID = "0F868C74",
          NextDialogue = 6201811,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201811] = {
          ContentKR = "\"당신이 그렇게 입에 달고 사는 신들이 진짜 우리를 신경 썼다면, 자기들이 직접 와서 이 지옥을 해결했겠죠.\"\n마법사는 피식 웃더니, 이내 깊게 한숨을 내쉰다.\n\"우리는 그냥 심연의 욕망을 채울 싱싱한 제물로 던져진 걸지도 몰라요. 애초에 토벌은 중요하지 않았고, 그냥 죽으라고 보내진 거죠. 우리가 본 그림자 중 대부분은, 심연을 토벌에 파견된 기사들이었어요...\"",
          DialogueId = 6201811,
          GUID = "0F868C9E",
          NextDialogue = 6201812,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201812] = {
          ContentKR = "\"다들 우리보다 연륜도, 실전 경험도 풍부했어요. 역량과 정신력도 우리보다 수백 배는 더 강했던 사람들인데, 결국엔 저 모양 저 꼴이 됐잖아요. 우린 여기서 못 나가요. 늦든 빠르든 미쳐 버리거나, 죽어 버리겠죠. 그게 우리 결말이에요.\"",
          DialogueId = 6201812,
          GUID = "0F868CC8",
          NextDialogue = 6201813,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201813] = {
          ContentKR = "사제는 굳은 표정으로 아무 말도 하지 않다가, 몸의 떨림을 감추려는 듯, 손에 쥔 지팡이를 힘껏 움켜쥔다.\n잠시 후, 평정을 되찾은 사제가 다시 입을 연다.\n\"...상황이 상황인 만큼, 방금 그 발언은 못 들은 셈 치죠. 지금은 플린이 없으니, 계급에 따라 당신은 제 결정을 따라야 합니다. 지금 당장 교리와 성자에 대한 모독을 중단하고, 기사의 책임을 다하세요.\"",
          DialogueId = 6201813,
          GUID = "0F868CF2",
          NextDialogue = 6201814,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201814] = {
          ContentKR = "\"...그래요, 어차피 죽을 거라면 일찍 죽는 것도 나쁘지 않겠죠.\"\n마법사는 체념한 듯 다시 망토에 달린 모자를 뒤집어쓴다.\n\"하지만 벗으로서 한마디만 하죠... 만약 당신이 믿는 모든 게 애초부터 거짓이었다면, 그걸 위해 목숨을 버리는 건 너무 아깝지 않아요?\"",
          DialogueId = 6201814,
          GUID = "0F868D1C",
          NextDialogue = 6201815,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201815] = {
          ContentKR = "\"......\"\n사제는 살며시 고개를 젓고는, 당신 앞으로 한 걸음 다가와 인사를 건넨다.\n\"추태를 보여 송구스럽군요. 저희는 이제 괜찮으니, 잠시 재정비한 후 다시 전진하겠습니다. 여기서 헤어지는 게 좋겠군요. 선한 여행자님, 부디 만월의 신께서 당신의 여정을 굽어살펴 주시기를 바랍니다.\"",
          DialogueId = 6201815,
          GUID = "0F868D46",
          NextOptions = {
            [1] = 6201816,
            [2] = 6201818,
            [3] = 6201820
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201816] = {
          ContentKR = "만월의 신께서 여러분의 여정도 굽어살펴 주시길 바랄게요.",
          DialogueId = 6201816,
          GUID = "0F868D70",
          IsKeyOption = true,
          NextDialogue = 6201817,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201817] = {
          ContentKR = "당신의 대답에 밀턴의 얼굴에 만족스러운 미소가 번진다. 칼리스타도 더는 반박하지 않고, 표정을 읽을 수 없게 그저 말없이 고개를 돌린다.\n당신은 두 사람에게 고개를 끄떡여 인사를 건네고, 몸을 돌려 자리를 떠난다.",
          DialogueId = 6201817,
          GUID = "0F868D9A",
          RougeTalkActorType = 3
        },
        [6201818] = {
          ContentKR = "만월의 신은 제게 도움을 별로 못 주실 것 같아요.",
          DialogueId = 6201818,
          GUID = "0F868DC4",
          IsKeyOption = true,
          NextDialogue = 6201819,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201819] = {
          ContentKR = "내 대답에 밀턴은 불편한 듯 시선을 피했지만, 더는 아무 말도 하지 않는다. 칼리스타는 내게 서글픈 미소를 지어 보이고는, 이내 지친 듯 고개를 숙인다.\n당신은 두 사람에게 고개를 끄떡여 인사를 건네고, 몸을 돌려 자리를 떠난다.",
          DialogueId = 6201819,
          GUID = "0F868DEE",
          RougeTalkActorType = 3
        },
        [6201820] = {
          ContentKR = "제 생각에... 중요한 건 신앙이 아니라, 우리가 가진 용기일지도 몰라요.",
          DialogueId = 6201820,
          GUID = "0F868E18",
          IsKeyOption = true,
          NextDialogue = 6201821,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201821] = {
          ContentKR = "당신의 대답은 밀턴과 칼리스타 모두에게 예상 밖이었던 모양인지, 깜짝 놀라더니 이내 생각에 잠긴다.\n당신 역시 더 말하지 않는다. 어차피 다른 사람한테서 들은 말이고, 당신 또한 아직 그 진짜 의미를 찾아가는 중일 뿐이다.\n당신은 두 사람에게 고개를 끄떡여 인사를 건네고, 몸을 돌려 자리를 떠난다.",
          DialogueId = 6201821,
          GUID = "0F868E42",
          RougeTalkActorType = 3
        },
        [6201901] = {
          ContentKR = "앞에서 불길하고 진한 피비린내가 풍겨 온다.\n깊은 어둠과 숨 막히는 정적. 당신은 저 너머에 당신이 찾는 물건은 없다고 확신한다. 그러나 동시에 당신이 그곳에 찾아오길 바라는 존재가 있는 듯한 기묘한 예감을 느낀다. 당신은 시험 삼아, 걸음을 내디뎌 본다...",
          DialogueId = 6201901,
          GUID = "0F869B62",
          NextDialogue = 6201902,
          RougeTalkActorType = 3
        },
        [6201902] = {
          ContentKR = "갑자기, 사방에서 하얀빛이 나타난다. 자세히 보니, 빛이 아니라 필토이드의 겉껍데기였다. 서로 엉기고 쌓여, 마치 술 취한 이단 예술가가 흩뿌려 놓은 작품 같아 보인다.\n당신이 본능적으로 한 걸음 물러서자, 익숙한 두 사람이 곁에 나타난다.",
          DialogueId = 6201902,
          GUID = "0F869B8C",
          NextDialogue = 6201903,
          RougeTalkActorType = 3
        },
        [6201903] = {
          ContentKR = "\"쿨럭, 쿨럭... 정말 끝도 없군요...\"\n마법사가 입가의 피를 닦아내며, 손에 쥔 장궁을 바닥에 내던진다.\n\"화살도 다 떨어져서... 이제 남은 건 마법밖에 없어요. 하하, 나름대로 당신의 신께 최선을 다한 셈인가요? 죽으면 시체는 멀쩡했으면 좋겠군요. 그리고 부탁인데 공동묘지에 묻진 말아 주세요.\"",
          DialogueId = 6201903,
          GUID = "0F869BB6",
          NextDialogue = 6201904,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201904] = {
          ContentKR = "\"또 헛소리를! 뒤를 조심하세요!\"\n사제가 급히 지팡이를 휘두르자, 마법의 빛이 터져 나온다.\n\"큭... 그림자가 또 나타났군요.\"",
          DialogueId = 6201904,
          GUID = "0F869BE0",
          NextDialogue = 6201905,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201905] = {
          ContentKR = "칼리스타와 함께 뒤를 돌아보자, 필토이드들의 시체를 넘어오는 거대한 그림자 무리가 보인다. 이번엔 그 이단 예술가가 검은색 물감이라도 엎은 듯하다.\n당신은 서둘러 랜턴을 들어 보지만, 그림자들은 한 치의 망설임도 없이 움직인다. 그런데, 랜턴의 빛이 밀턴의 지팡이를 통과하는 게 보인다.",
          DialogueId = 6201905,
          GUID = "0F869C0A",
          NextDialogue = 6201906,
          RougeTalkActorType = 3
        },
        [6201906] = {
          ContentKR = "그제야 당신은 눈앞의 모든 상황이 기억의 잔상에 불과하다는 사실을 깨닫는다. 분명히 두 사람 곁에 서 있는데도, 당신은 아무것도 할 수 없고, 그들이 힘이 다하고, 상처투성이가 되어 쓰러지는 모습을 지켜볼 수밖에 없다.",
          DialogueId = 6201906,
          GUID = "0F869C34",
          NextDialogue = 6201907,
          RougeTalkActorType = 3
        },
        [6201907] = {
          ContentKR = "그림자 무리는 어느새 흩어지고, 이제 마지막 넷... 셋... 둘... 하나만이 남아 있다. 만약 두 기사 중 한 명이라도 반격할 힘이 남아 있었다면, 이곳에 작은 유리 파편이라도 남아 있었다면, 두 사람은 이 전투에서 승리하고, 살아남을 수 있었을 것이다.\n그렇지만... 이곳에는 뒤늦게 도착한 방관자인 당신을 제외하고는, 아무것도 없다.",
          DialogueId = 6201907,
          GUID = "0F869C5E",
          NextDialogue = 6201908,
          RougeTalkActorType = 3
        },
        [6201908] = {
          ContentKR = "인간형 그림자가 다가온다. 한때는 그들의 선배나 동료, 또는 친구였을지도 모르는 누군가가 칼리스타의 심장에 시커먼 창을 찔러 넣는다.\n당신은 차마 이 잔인한 광경을 볼 수 없어, 두 눈을 질끈 감는다.",
          DialogueId = 6201908,
          GUID = "0F869C88",
          NextDialogue = 6201909,
          RougeTalkActorType = 3
        },
        [6201909] = {
          ContentKR = "\"밀턴...?! 당신이... 왜...?\"",
          DialogueId = 6201909,
          GUID = "0F869CB2",
          NextDialogue = 6201910,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201910] = {
          ContentKR = "깜짝 놀라 눈을 뜨자, 밀턴의 가슴이 장창에 꿰뚫려 있다. 그림자가 사라지자, 그는 힘없이 땅으로 쓰러진다. 언제나 티끌 하나 없이 단정했던 옷은 피로 붉게 물들어 있다.",
          DialogueId = 6201910,
          GUID = "0F869CDC",
          NextDialogue = 6201911,
          RougeTalkActorType = 3
        },
        [6201911] = {
          ContentKR = "\"왜 그랬어요..? 왜...\"\n마법사는 망연자실한 채 동료의 곁에 무릎을 꿇고 앉아, 허둥지둥 치유 마법을 쓰려 하지만, 모두 헛수고일 뿐이다.\n\"이단이라고... 나보고 이단이라고 했잖아요... 그런데 왜 이단 하나 구하자고 목숨을 버리는 거죠?! 당신은 아직 신앙을 증명해야 하잖아요...\"",
          DialogueId = 6201911,
          GUID = "0F869D06",
          NextDialogue = 6201912,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201912] = {
          ContentKR = "\"제 신앙이... 동료를 지키라고 하더군요... 당신이 아무리 의심해도... 저는 이 가르침만큼은 옳다고 믿어요.\"\n죽음의 문턱에 와서야, 사제의 늘 엄격하기만 하던 얼굴에 인간적인 미소가 피어오른다.\n\"이 정도면, 충분히 신께 헌신한 거겠죠... 그러니, 마지막은 속마음을 얘기할게요. 칼리스타... 사명과 의무 따위는 잊고, 여길 떠나, 살아남아 주세요.\"",
          DialogueId = 6201912,
          GUID = "0F869D30",
          NextDialogue = 6201913,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201913] = {
          ContentKR = "\"네...?\"",
          DialogueId = 6201913,
          GUID = "0F869D5A",
          NextDialogue = 6201914,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201914] = {
          ContentKR = "\"제가 없으면 당신이 지휘관이니, 당신 뜻대로 움직이면 돼요. 늘 말했던 것처럼, 도망치세요... 이 심연을 떠나거나, 그 여행자를 찾으세요... 살아남을 수만 있다면, 뭐든 좋아요.\"",
          DialogueId = 6201914,
          GUID = "0F869D84",
          NextDialogue = 6201915,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201915] = {
          ContentKR = "눈물이 쉴 새 없이 칼리스타의 하얀 뺨을 타고 흘러내린다. 눈물방울이 밀턴의 옷에 떨어지자, 굳어가던 핏덩어리가 다시 녹아내린다.\n\"그렇지만, 나 혼자서... 대체 어디로 가라는 거예요...\"",
          DialogueId = 6201915,
          GUID = "0F869DAE",
          NextDialogue = 6201916,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201916] = {
          ContentKR = "\"또... 엉뚱한 소리를 하는군요.\"\n사제는 지팡이를 굳게 쥐었던 손으로, 힘겹게 자신의 가슴에 달린 휘장을 떼어 칼리스타의 손에 쥐여 준다.\n\"당신의 시험 성적은 늘 우리 중 최고였어요. 이곳에 도착하고 나서, 처음으로 현실을 직시하고, 용기 있게 의심을 품은 것도 당신이었죠... 그러니까... 분명히... 살아남을 거예요...\"",
          DialogueId = 6201916,
          GUID = "0F869DD8",
          NextDialogue = 6201917,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201917] = {
          ContentKR = "환영은 흩어졌고, 당신은 칼리스타의 대답을 듣지 못했다.\n고요한 어둠 속에, 사제의 시체가 덩그러니 놓여 있다. 검은 그림자가 상처에서 피어오른다. 그는 곧 당신이 보아 왔던 수많은 이들처럼, 안식에 들지 못하는 그림자가 될 것이다.",
          DialogueId = 6201917,
          GUID = "0F869E02",
          NextOptions = {
            [1] = 6201918,
            [2] = 6201920
          },
          RougeTalkActorType = 3
        },
        [6201918] = {
          ContentKR = "(밀턴의 고통을 끝내 준다.)",
          DialogueId = 6201918,
          GUID = "0F869E2C",
          IsKeyOption = true,
          NextDialogue = 6201919,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201919] = {
          ContentKR = "밀턴이 그림자로 변하기 전에, 당신은 랜턴의 힘으로 그가 영면에 들도록 도왔다.\n\"고맙습니다...\"\n밀턴의 목소리가 들린 것만 같았지만, 어쩌면 나 자신을 위로하기 위한 환청이었을지도 모른다.",
          DialogueId = 6201919,
          GUID = "0F869E56",
          RougeTalkActorType = 3
        },
        [6201920] = {
          ContentKR = "(차마 손을 대지 못한다.)",
          DialogueId = 6201920,
          GUID = "0F869E80",
          IsKeyOption = true,
          NextDialogue = 6201921,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201921] = {
          ContentKR = "당신은 자리를 떠날 생각으로, 한 걸음 물러선다.\n그러나 그림자가 일어선다. 그리곤 한때 친구의 손에서 힘없이 떨어졌던 그 창백한 손으로, 다시 지팡이를 쥐고 당신을 공격해 온다.\n당신은 한숨을 내쉬고, 무기를 들어, 언제나처럼 그림자를 쓰러뜨린다.",
          DialogueId = 6201921,
          GUID = "0F869EAA",
          RougeTalkActorType = 3
        },
        [6202001] = {
          ContentKR = "또다시, 당신은 윤회의 끝자락에 도달했다.\n지금까지 모은 유리 파편은 아직 심연의 핵과 맞서기엔 턱없이 부족하기에, 당신은 다시 한번 시간을 되돌려야만 한다.",
          DialogueId = 6202001,
          GUID = "0F86ABCA",
          NextDialogue = 6202002,
          RougeTalkActorType = 3
        },
        [6202002] = {
          ContentKR = "당신은 혼돈의 흐름 속을 목적 없이 떠돈다. 이미 수없이 그의 시선을 마주했기에, 더는 두렵지 않다. 그저 담담하게, 이번 생의 마지막 몇 분이 지나가기를 기다릴 뿐이다.\n그때, 갑자기 익숙한 누군가의 모습이 보인다.",
          DialogueId = 6202002,
          GUID = "0F86ABF4",
          NextDialogue = 6202003,
          RougeTalkActorType = 3
        },
        [6202003] = {
          ContentKR = "\"하하... 여행자님이셨군요... 역시 아직 살아 계셨네요.\"\n여자는 너덜너덜해진 망토로도 가릴 수 없는 상처투성이의 몸으로, 무너진 담벼락에 비스듬히 기대 있다.\n\"여행자님은 대체 정체가 뭔가요...? 어째서, 그런 걸 보고도 아무렇지 않은 거죠?\"",
          DialogueId = 6202003,
          GUID = "0F86AC1E",
          NextOptions = {
            [1] = 6202004,
            [2] = 6202006
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202004] = {
          ContentKR = "윤회의 시간 속에서, 이미 여러 번 만났거든요.",
          DialogueId = 6202004,
          GUID = "0F86AC48",
          IsKeyOption = true,
          NextDialogue = 6202005,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6202005] = {
          ContentKR = "\"윤회요?\"\n마치 난제를 풀어낸 학자처럼, 여자의 눈이 번뜩인다.\n\"아... 그랬군요. 이제야 이해가 가네요. 당신이 왜 우리를 그렇게... 자비로운 눈으로 보는 걸까 했거든요... 우리의 결말을 수도 없이 봐 온 거죠? 윤회라... 하하... 그러면 저도 곧 모두와 다시 만날 수 있겠네요...? 그렇게 생각하니까, 죽음도 별로 두렵지는 않군요.\"",
          DialogueId = 6202005,
          GUID = "0F86AC72",
          NextDialogue = 6202008,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202006] = {
          ContentKR = "모르는 게 약일 때도 있어요.",
          DialogueId = 6202006,
          GUID = "0F86AC9C",
          IsKeyOption = true,
          NextDialogue = 6202007,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6202007] = {
          ContentKR = "\"하하... 맞아요. 전 상상도 못하겠어요. 대체 어떤 일들을 겪으셨길래 이렇게 강인하고도 무서울 정도의... 평온함을 가지게 되신 건지 말이에요.\"\n여자는 검은 눈동자로 당신을 오랜 친구처럼 부드럽게 바라본다.\n\"저희한테 아직 숨기는 게 많으신 것 같아요. 하지만 여행자님만의 이유가 있으시겠죠. 자신만의 신념을 고집했던 제 동료들처럼 말이에요.\"",
          DialogueId = 6202007,
          GUID = "0F86ACC6",
          NextDialogue = 6202008,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202008] = {
          ContentKR = "\"이걸 받아 주세요... 괜찮다면, 가지고 다녀 주셨으면 해요. 제 마지막 부탁이라고 생각해 주세요...\"\n여자가 힘겹게 손을 뻗어, 노트를 한 권 건넨다.\n\"밀턴은 저한테 도망치라고 했지만, 이미 돌아갈 수 없다는 건 저도 알아요. 그러니까 적어도... 이 마지막 목숨으로, 조금이나마 가치 있는 일을 하게 해 주세요.\"",
          DialogueId = 6202008,
          GUID = "0F86ACF0",
          NextDialogue = 6202009,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202009] = {
          ContentKR = "\"심연 속에서... 전 오랫동안 고민했어요. 만월의 신과 암월의 신 중에서, 어느 쪽이 진짜일까? 어떤 신앙이 옳은 걸까라고요. 하지만 계속 답을 찾지 못해서, 동료들하고도 몇 번이나 다퉜었어요.\"\n여자는 자조하듯 감회에 젖은 탄식을 내쉰다.\n\"이제야 겨우 깨달았어요. 사실 어떤 게 진짜인지 가짜인지는 중요하지 않았다는 걸요. 정말 중요한 건, 그 신앙을 가진 사람이 어떤 행동을 했냐는 거였어요. 제 동료들은 스스로의 행동으로 자신들이 옳다는 걸 증명했죠. 그러니까, 저도 그게 가짜든 진짜든, 동료들이 지녔던 신앙으로... 여행자님께 축복을 드리고 싶어요.\"",
          DialogueId = 6202009,
          GUID = "0F86AD1A",
          NextDialogue = 6202010,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202010] = {
          ContentKR = "\"그러니까... 여행자님...\"\n여자가 떨리는 창백한 오른손을 가슴에 얹고, 초점을 잃어가는 눈으로 최선을 다해 내 모습을 좇는다.\n\"<H>운명의 신께서 그대에게 천 갈래의 달빛을 내리시어, 두 날개가 영원히 저 만월처럼 티 없이 희고 맑기를 바라노라</>.\"",
          DialogueId = 6202010,
          GUID = "0F86AD44",
          NextDialogue = 6202011,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202011] = {
          ContentKR = "여자는 숨을 거두었다.\n당신은 그녀의 두 눈을 감겨 주었다. 여자의 얼굴에는 마치 단잠에 빠진 사람처럼, 평온한 미소가 어려 있다.",
          DialogueId = 6202011,
          GUID = "0F86AD6E",
          NextDialogue = 6202012,
          RougeTalkActorType = 3
        },
        [6202012] = {
          ContentKR = "당신은 그녀가 남긴 노트를 펼친다. 종이는 먼지와 핏자국으로 얼룩져 있지만, 글씨는 매우 또렷하다.\n\"나, 엘리시안 교회 소속 날개 기사단 '침묵의 황혼' 소대원 칼리스타는 이곳에서 내가 관측한 성스러운 호수에 대한 모든 것을 기록한다. 만약 누군가 이 노트를 발견한다면, 이 기록이 이곳을 벗어나는 데 조금이나마 도움이 되기를 바란다.\"",
          DialogueId = 6202012,
          GUID = "0F86AD98",
          NextDialogue = 6202013,
          RougeTalkActorType = 3
        },
        [6202013] = {
          ContentKR = "당신은 랜턴의 불빛에 의지해 노트를 읽어 내려간다. 어두운 곳에서 급하게 쓴 듯 어지러운 글씨체의 노트에는, 수많은 그림자와 환영에 대한 정보는 물론, 유령의 약점들과 환상을 몰아내는 방법까지 상세히 적혀 있다.\n당신은 아무 페이지나 펼쳐 읽는다.\n\"<H>암월파</>의 기록이 전부 거짓이 아니라는 점만은 확실하다... 적어도, 성스러운 호수는 신화 속의 제천의 하늘과는 아무런 관련이 없으며, 선택은 일종의 희생 제의에 가깝다. 이곳은 죽은 자들이 담긴 악의와 사념으로 가득 찬 공간이다.\"\n\"우리 가문은 암월파의 신도로서, 심연과 암월의 여신을 믿는다. 또한 초대 세븐 버튜스 중 하나인 <H>사리엘</>이 2천 년 전 제천의 하늘로 간 것이 아니라, 성스러운 호수 바닥에서 <H>마왕</>, 즉 심연의 핵이 되었다고 굳게 믿는다. 마왕은 끊임없이 영혼을 집어삼켜 네파에게 바치는 제물로 삼는다.\"",
          DialogueId = 6202013,
          GUID = "0F86ADC2",
          NextDialogue = 6202014,
          RougeTalkActorType = 3
        },
        [6202014] = {
          ContentKR = "\"지난 세월 동안, 그 끔찍한 전설들을 믿고 싶지 않았던 나는, 엘리시안 교회의 가르침으로 끊임없이 나 자신을 바로잡으려 애썼다. 하지만 이 심연의 모든 것은 내게 암월파의 교리가 진실이라면... 우리의 세계가 맞이하는 끝이 정말로 어둠과 허무라면 어떻게 할 것이냐 쉼 없이 묻는다...\"\n\"그렇다면, 심연을 이길 방법은 없는 것일까?\"\n\"안타깝게도, 내 몸은 그 답을 찾을 때까지 버티지 못할 것이다.\"",
          DialogueId = 6202014,
          GUID = "0F86ADEC",
          NextDialogue = 6202015,
          RougeTalkActorType = 3
        },
        [6202015] = {
          ContentKR = "\"<H>코로네</>라는 <H>성검</>이 성스러운 호수에서 파손되었다는 이야기를 밀턴에게서 들은 적이 있다. 그 성검은 엘리시안 교회의 성물로, 아주 특별한 힘을 지녔다고 한다... 또한, 이 심연에서 한 여행자를 만난 적이 있는데, 그 인물이 지닌 랜턴 역시 그림자를 몰아내는 특별한 힘을 지닌 것 같았다.\" \n\"만약 정말로 심연을 이겨 낼 무언가가 있다면, 아마도 이 두 가지가 열쇠일 것이다.\"",
          DialogueId = 6202015,
          GUID = "0F86AE16",
          NextDialogue = 6202016,
          RougeTalkActorType = 3
        },
        [6202016] = {
          ContentKR = "노트에 페이지가 많이 남아 있는 것을 보고, 당신은 서둘러 페이지를 넘긴다. 그녀는 또 어떤 진실을 알고 있을까?\n그렇지만 당신은 금세 노트의 뒷부분은 심연과는 무관한 내용이 담겨 있다는 사실을 깨닫는다.",
          DialogueId = 6202016,
          GUID = "0F86AE40",
          NextDialogue = 6202017,
          RougeTalkActorType = 3
        },
        [6202017] = {
          ContentKR = "\"이 노트를 읽고 있는 당신! 여기까지 읽어 줘서 고마워요. 그리고 저를 대신해서 부디 이 사람들을 기억해 줘요.\"",
          DialogueId = 6202017,
          GUID = "0F86AE6A",
          NextDialogue = 6202018,
          RougeTalkActorType = 3
        },
        [6202018] = {
          ContentKR = "순식간에, 당신의 의식은 심연을 떠나, 이 글자들이 이끄는 다른 세계로 향한다.\n엘리시안 기사단의 야영지에 있는 어느 자그마한 숙소의 따스한 노란 불빛 아래, 당신은 한 젊은 기사의 일기장을 펼쳐, 그녀와 세 친구의 이야기를 읽어 내려간다.",
          DialogueId = 6202018,
          GUID = "0F86AE94",
          NextDialogue = 6202019,
          RougeTalkActorType = 3
        },
        [6202019] = {
          ContentKR = "네 사람은 함께 훈련을 받았다.\n\"교관한테 꼭 한 팀 같다는 이야기를 몇 번이나 듣더니, 플린이 잔뜩 신이 나서 우리 넷으로 이루어진 소대에 이름을 붙여 주자고 했다. 원래 캐시하고 플린은 맨날 같이 붙어 다니면서 떠들어 대니까, 캐시가 저러는 건 그러려니 하겠는데, 설마 밀턴까지 찬성할 줄은 몰랐다. 설마 밀턴도 영웅 같은 게 되고 싶고 그런가?\"\n\"플린과 캐시가 각각 내놓은 이름 후보는 '침묵의 황혼'과 '용감한 감자'였는데, 나와 밀턴은 바로 첫 번째 이름에 투표했다. 저녁에 감자 스튜가 나왔으니까, 밥 먹다 그냥 생각 없이 지은 게 분명하다.\"\n\"플린이 지은 이름에 들어간 '황혼'... 후후, 다른 사람은 눈치채지 못했어도, 우리 넷은 플린이 자기가 제일 좋아하는 '달오름' 기사에게 슬쩍 경의를 표한 거란 사실을 바로 알 수 있었다.\"",
          DialogueId = 6202019,
          GUID = "0F86AEBE",
          NextDialogue = 6202020,
          RougeTalkActorType = 3
        },
        [6202020] = {
          ContentKR = "네 사람은 함께 전장에 나섰다.\n\"행군할 때마다, 캐시는 늘 흔적도 없이 사라져 버리곤 한다. 처음에는 다들 걱정도 꽤 많이 했지만, 매번 불쑥 나타나 우리를 놀래키는 바람에, 이제는 다들 그러려니 한다. 그런데, 대체 어떻게 하는 걸까? 그 머리로 순간이동 같은 어려운 마법을 배웠을 리가 없는데...\"\n\"책벌레 밀턴이, 시간 날 때마다 읽겠다고 전장에 책을 가져왔다. 정말 어이가 없다...\"\n\"결국, 밀턴의 책은 제국의 병사가 쏜 불화살에 맞아 몽땅 타 버렸다. 밀턴은 하루 종일 울상이었지만... 덕분에 짐 무게가 적어도 3분의 2는 줄었을 테니까, 오히려 그 병사한테 고마워해야 한다고 생각한다.\"",
          DialogueId = 6202020,
          GUID = "0F86AEE8",
          NextDialogue = 6202021,
          RougeTalkActorType = 3
        },
        [6202021] = {
          ContentKR = "네 사람은 함께 사명을 받았다.\n\"골치 아픈 건 싫으니까, 심연 토벌에 지원했단 사실은 부모님껜 숨기고 오빠한테만 말했다... 그런데 오빠도 심연은 엘리시안 교회의 음모라느니, 마왕이 모두를 제물로 삼을 거라느니 하면서 잔소리를 늘어놨다... 귀찮아 죽겠다.\"\n\"사실, 심연 토벌 같은 덴 별로 관심 없지만, 플린이 워낙 적극적이라 차마 반대하진 못했다. 지금까지 우린 참여한 전투에서 별 도움도 못 됐고, 툭하면 지곤 했으니, 어떻게든 스스로를 증명할 기회가 필요했을 것이다... 그래서, 기사가 되고 싶단 플린의 꿈을 이뤄 주기로 했다. 어차피 어디에 가든, 네 사람이 함께라면 다 똑같다.\"",
          DialogueId = 6202021,
          GUID = "0F86AF12",
          NextDialogue = 6202022,
          RougeTalkActorType = 3
        },
        [6202022] = {
          ContentKR = "......",
          DialogueId = 6202022,
          GUID = "0F86AF3C",
          NextDialogue = 6202023,
          RougeTalkActorType = 3
        },
        [6202023] = {
          ContentKR = "당신은 노트의 마지막 페이지를 펼쳤다.",
          DialogueId = 6202023,
          GUID = "0F86AF66",
          NextDialogue = 6202024,
          RougeTalkActorType = 3
        },
        [6202024] = {
          ContentKR = "\"침묵의 신이시여, 밀턴의 말처럼 항상 우리를 지켜보고 계신다면... 부디, 제 마지막 소원을 들어주세요.\"\n\"제 영혼이 다시 그들과 만나게 해 주세요.\"\n\"그렇게만 해 주신다면, 당신의 무심함과 잔인함, 그리고 당신이 내린 수많은 고난과 당신이 지어낸 모든 거짓을 용서하겠습니다.\"",
          DialogueId = 6202024,
          GUID = "0F86AF90",
          NextDialogue = 6202025,
          RougeTalkActorType = 3
        },
        [6202025] = {
          ContentKR = "<H>\"나의 날개는 더 이상 만월의 빛이 필요치 않으니, 한 줄기 맑은 바람이 나를 동료들이 있는 곳으로 데려다주기를.\"</>",
          DialogueId = 6202025,
          GUID = "0F86AFBA",
          NextDialogue = 6202026,
          RougeDialogueMainIcon = "Texture2D'/Game/UI/Texture/Dynamic/Image/RougeLike/T_Rouge_Story13.T_Rouge_Story13'",
          RougeTalkActorType = 3
        },
        [6202026] = {
          ContentKR = "노트를 덮자, 아직도 종이에 남아 있는 온기가 손끝에 느껴진다.",
          DialogueId = 6202026,
          GUID = "0F86AFE4",
          NextDialogue = 6202027,
          RougeTalkActorType = 3
        },
        [6202027] = {
          ContentKR = "\"제가... 반드시 이 윤회를 끝내고, 모두가 맑은 만월 아래서 다시 만나게 해 줄게요.\"",
          DialogueId = 6202027,
          GUID = "0F86B00E",
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [7002001] = {
          ContentKR = "위문품들이 아무렇게나 널브러져 있다, 며칠 새 많은 사람들이 보내온 모양이다.\n자세히 보니 여러가지 선물들이 있다. 이름 모를 들꽃, 이미 식었지만 여전히 맛있는 냄새가 나는 고깃국, 스크래치가 난 정교한 오르골, 작은 새가 그려져 있는 솜사탕 한 캔...\n그 외, 서명은 없지만 삐뚤어진 리본을 맨 소박한 선물 상자도 있다. 상자를 열어보니 제국 최고의 진통제 한 병이 들어있다. 배려의 마음은 좋으나, 기절한 사람에게 진통제를 선물하는 것은 별 의미가 없다.",
          DialogueId = 7002001,
          GUID = "11875DCA"
        },
        [7003001] = {
          ContentKR = "최근 아이스레이크 시티 외성에서 잔혹한 폭행 사건이 많이 발생하고 있습니다. 범행 수법이 매우 잔인하고 현장은 아직 매우 혼잡하니 시민 여러분들은 심야 외출을 자제하고 문과 창문을 잠가 주시기 바랍니다.\n무기 허가증을 소지하고 계신 시민 여러분, 범인을 만나게 된다면 절대 반격을 시도하지 마시고(매우 위험합니다!!!), 자신의 생명 안전부터 유의하시기를 바랍니다.\n범인의 단서를 가지고 계신 분들은 즉시 방위대의 리듬 페실에게 연락해 주시기를 바랍니다.\n황제 폐하께서 충성스러운 백성들이 이 난관을 헤쳐나갈 수 있도록 지켜줄 것입니다. 황제 폐하께 영광을.",
          DialogueId = 7003001,
          GUID = "118801DA"
        },
        [10010101] = {
          Camera = "67.539062,-1123.730225,550.733276,0.000081,-22.799314,91.999741,35.0,1000.0,false,Manual,2.8",
          ContentKR = "베레, 나...",
          DefaultLookAt = "KeepState",
          DialogueId = 10010101,
          DisableMouth = 1,
          Duration = 1.5,
          ExStoryInfo = "Player",
          GUID = "190F2A32",
          RelatedWikiId = {
            [1] = 304001,
            [2] = 204001,
            [3] = 408001,
            [4] = 201001
          },
          SpeakNpcId = 100001,
          Subtitle = "Berry, I...",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2A32"
        },
        [10010102] = {
          ContentKR = "쉿.",
          DialogueId = 10010102,
          DisableMouth = 1,
          Duration = 3,
          GUID = "190F2A5C",
          SpeakNpcId = 100003,
          Subtitle = "Ssh...",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2A5C"
        },
        [10010103] = {
          ContentKR = "괜찮아?",
          DialogueId = 10010103,
          DisableMouth = 1,
          Duration = 2,
          GUID = "190F2A86",
          SpeakNpcId = 100003,
          Subtitle = "Are you all right?",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2A86"
        },
        [10010104] = {
          ContentKR = "응.",
          DialogueId = 10010104,
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "190F2AB0",
          SpeakNpcId = 100001,
          Subtitle = "Yeah.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2AB0"
        },
        [10010105] = {
          ContentKR = "조금만 더 쉬자. 내가 여기 있을게. 아무 데도 안 가.",
          DialogueId = 10010105,
          DisableMouth = 1,
          Duration = 5,
          GUID = "190F2ADA",
          SpeakNpcId = 100003,
          Subtitle = "Get some more sleep. I won't leave — I'll be right here when you wake up.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2ADA"
        },
        [10010106] = {
          ContentKR = "괜찮아. 이제 그만 돌아가자.",
          DialogueId = 10010106,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "190F2B04",
          SpeakNpcId = 100001,
          Subtitle = "It's okay. We should get down the mountain and head to the village.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B04"
        },
        [10010107] = {
          ContentKR = "벌써 마을로 돌아가자고? 요 며칠 계속 괴성이 들렸는걸...",
          DialogueId = 10010107,
          DisableMouth = 1,
          Duration = 4,
          GUID = "190F2B2E",
          SpeakNpcId = 100003,
          Subtitle = "You wanna go back? There've been roars coming from there for days...",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B2E"
        },
        [10010108] = {
          ContentKR = "내 말은, 집에 있는 무기만 얻을 수 있다면...",
          DialogueId = 10010108,
          DisableMouth = 1,
          Duration = 4.5,
          ExStoryInfo = "Player",
          GUID = "190F2B58",
          SpeakNpcId = 100001,
          Subtitle = "I was thinking, if we could make it home and grab our weapons—",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B58"
        },
        [10010109] = {
          ContentKR = "네 힘이라면 분명 살길을 찾을 수 있을 거야.",
          DialogueId = 10010109,
          DisableMouth = 1,
          Duration = 2.5,
          ExStoryInfo = "Player",
          GUID = "190F2B82",
          SpeakNpcId = 100001,
          Subtitle = "And with your strength, you'll find a way out. ",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B82"
        },
        [10010110] = {
          ContentKR = "여기에 있어 봤자... 아무도 우릴 구하러 오지 않잖아.",
          DialogueId = 10010110,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "Player",
          GUID = "190F2B83",
          SpeakNpcId = 100001,
          Subtitle = "No one's gonna save us no matter how long we stay here anyway.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B83"
        },
        [10010111] = {
          ContentKR = "...가자.",
          DialogueId = 10010111,
          DisableMouth = 1,
          Duration = 3,
          GUID = "190F2BAC",
          SpeakNpcId = 100003,
          Subtitle = "...Let's go then.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAC"
        },
        [10010112] = {
          ContentKR = "조심해.",
          DialogueId = 10010112,
          GUID = "190F2BAD",
          SpeakNpcId = 100003,
          Subtitle = "Take it easy.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAD"
        },
        [10010113] = {
          ContentKR = "발밑을 잘 봐. 헛디디면 안 돼.",
          DialogueId = 10010113,
          GUID = "190F2BAE",
          SpeakNpcId = 100003,
          Subtitle = "Watch your step.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAE"
        },
        [10010114] = {
          ContentKR = "상처는 괜찮아? 참을 만해?",
          DialogueId = 10010114,
          GUID = "190F2BAF",
          NextDialogue = 10010115,
          SpeakNpcId = 100003,
          Subtitle = "You're not fully recovered. Are you sure you can do this?",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAF"
        },
        [10010115] = {
          ContentKR = "진작 다 나았어, 별 거 아닌 생채기 몇 개인데 뭐.",
          DialogueId = 10010115,
          ExStoryInfo = "Player",
          GUID = "190F2BB1",
          NextDialogue = 10010116,
          SpeakNpcId = 100001,
          Subtitle = "I'm okay. It's just a few scratches.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BB1"
        },
        [10010116] = {
          ContentKR = "무리하지 마. 필토이드를 만나기도 전에 지치면 어쩌려고 그래.",
          DialogueId = 10010116,
          GUID = "190F2BB2",
          SpeakNpcId = 100003,
          Subtitle = "Don't push yourself too hard. We still have to save some strength for those Filthoids.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BB2"
        },
        [10010201] = {
          ContentKR = "살고 싶다면 사실대로 말해라.",
          DialogueId = 10010201,
          Duration = 4,
          GUID = "190F3A9A",
          SpeakNpcId = 100005,
          Subtitle = "Tell me the truth if you want to live.",
          VoiceName = "voice/$Locale$/story/1001/100102/190F3A9A"
        },
        [10010202] = {
          ContentKR = "이곳에 있는 이유와 네 동료가 누구인지를.",
          DialogueId = 10010202,
          Duration = 5,
          GUID = "190F3AC4",
          SpeakNpcId = 100005,
          Subtitle = "Why are you here, who's with you,",
          VoiceName = "voice/$Locale$/story/1001/100102/190F3AC4"
        },
        [10010203] = {
          ContentKR = "그리고, 넌 누군지.",
          DialogueId = 10010203,
          Duration = 3.5,
          GUID = "190F3AEE",
          SpeakNpcId = 100005,
          Subtitle = "and who on earth are you?",
          VoiceName = "voice/$Locale$/story/1001/100102/190F3AEE"
        },
        [10010204] = {
          Camera = "10000,11000,2000,0.000046,-4.799929,73.987312,35.0,150.0,false,Manual,2.8",
          Content = "……",
          DialogueId = 10010204,
          Duration = 2,
          GUID = "190F3AEF",
          NextDialogue = 10010205
        },
        [10010205] = {
          Camera = "10000,11000,2000,0.000046,-4.799929,73.987312,35.0,150.0,false,Manual,2.8",
          Content = "……",
          DialogueId = 10010205,
          Duration = 2,
          GUID = "190F3AF0",
          NextDialogue = 10010206
        },
        [10010206] = {
          Camera = "10000,11000,2000,0.000046,-4.799929,73.987312,35.0,150.0,false,Manual,2.8",
          Content = "……",
          DialogueId = 10010206,
          Duration = 2,
          GUID = "190F3AF1"
        },
        [10010301] = {
          Content = "我们现在赤手空拳，尽可能避开它们吧。",
          DialogueId = 10010301,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "190F4B02",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100103/190F4B02"
        },
        [10010401] = {
          ContentKR = "그 검, 잘 들고 있어. 필요한 순간이 있을 거야.",
          DialogueId = 10010401,
          DisableMouth = 1,
          Duration = 3,
          GUID = "190F5B6A",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001
          },
          SpeakNpcId = 100003,
          Subtitle = "Take that sword with you. It might be helpful one day.",
          TalkActionId = {
            [1] = "100001:FuXiong_Start"
          },
          VoiceName = "voice/$Locale$/story/1001/100104/190F5B6A"
        },
        [10010402] = {
          ContentKR = "조심해. 필토이드는 내가 처리할게.",
          DialogueId = 10010402,
          DisableMouth = 1,
          Duration = 4,
          GUID = "190F5B94",
          SpeakNpcId = 100003,
          Subtitle = "Keep yourself safe. I'll take care of these Filthoids.",
          TalkActionId = {
            [1] = "100001:FuXiong_End"
          },
          VoiceName = "voice/$Locale$/story/1001/100104/190F5B94"
        },
        [10010501] = {
          Content = "拿起剑的时候，熟悉而陌生的记忆涌上来……",
          DialogueId = 10010501,
          Duration = 3,
          GUID = "190F6BD2",
          NextDialogue = 10010502,
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100105/190F6BD2"
        },
        [10010502] = {
          Content = "……已经很久没有像这样战斗过了。",
          DialogueId = 10010502,
          Duration = 2.5,
          GUID = "190F6BFC",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100105/190F6BFC"
        },
        [10010601] = {
          ContentKR = "가자, 부두로.",
          DialogueId = 10010601,
          Duration = 2,
          GUID = "190F7D0C",
          SpeakNpcId = 100003,
          Subtitle = "Let's head to the wharf.",
          VoiceName = "voice/$Locale$/story/1001/100106/190F7D0C"
        },
        [10010701] = {
          ContentKR = "흠, 정말이지... 배 한 척도 안 남겨뒀네.",
          DialogueId = 10010701,
          GUID = "190F8CA2",
          NextDialogue = 10010702,
          SpeakNpcId = 100003,
          Subtitle = "Ugh, they didn't leave even one single boat.",
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CA2"
        },
        [10010702] = {
          ContentKR = "필토이드가 왔을 때 넌 마을에 있었지? 날 찾으러 돌아오지 않았다면 너도 도망갈 수 있었을 텐데.",
          DialogueId = 10010702,
          ExStoryInfo = "Player",
          GUID = "190F8CCC",
          NextDialogue = 10010703,
          SpeakNpcId = 100001,
          Subtitle = "You were at the village when the Filthoids came, weren't you? If it wasn't for coming back for me, you could have escaped with them.",
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CCC"
        },
        [10010703] = {
          ContentKR = "쓸데없는 말 하지 마. 네가 나였어도 똑같이 했을 거야. 일단 해안가를 따라서 낡은 배라도 찾아보자.",
          DialogueId = 10010703,
          GUID = "190F8CF6",
          SpeakNpcId = 100003,
          Subtitle = "Don't be silly. You'd have done the same for me. Let's search along the shore and see if there's any old boats or something.",
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CF6"
        },
        [10010704] = {
          Content = "别说傻话。我们先沿着海岸找找有没有废旧的船。",
          DialogueId = 10010704,
          GUID = "190F8CF7",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CF7"
        },
        [10010801] = {
          Camera = "233.692749,98.025391,337.437744,0.000525,-38.008308,-170.090546,35.000008,500.0,false,Disable,22.0",
          ContentKR = "이건... 사람들이 도망치다 떨어뜨린 건가?",
          DefaultLookAt = "KeepState",
          DialogueId = 10010801,
          ExStoryInfo = "Player",
          FinalCamera = "233.692749,98.025391,306.806396,0.000525,-38.008308,-170.090546,35.000008,500.0,false,Disable,22.0",
          GUID = "190F9D0A",
          LookAt = {
            [1] = "100001:p(QuestPoint102)",
            [2] = "100003:p(QuestPoint102)"
          },
          NextDialogue = 10010802,
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 303001
          },
          SpeakNpcId = 100001,
          Subtitle = "Look... Someone must have lost them when they ran away.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1001/100108/190F9D0A"
        },
        [10010802] = {
          Camera = "45.787476,-42.09668,191.500977,0.000512,-35.408981,145.509857,30.0,500.0,false,Disable,22.0",
          ContentKR = "챙겨 두자. 뭐라도 있으면 좋지.",
          DefaultLookAt = "KeepState",
          DialogueId = 10010802,
          FinalCamera = "25.377319,-28.079102,173.898438,0.000512,-35.408981,145.509857,30.0,500.0,false,Disable,22.0",
          GUID = "190F9D34",
          SpeakNpcId = 100003,
          Subtitle = "Hmm, let's grab one. It's always good to be well-armed.",
          TalkActionId = {
            [1] = "100003:Agree"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1001/100108/190F9D34"
        },
        [10010901] = {
          Content = "这边。",
          DialogueId = 10010901,
          Duration = 2,
          GUID = "190FAD9D",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100109/190FAD9D"
        },
        [10011001] = {
          ContentKR = "필토이드가 또 따라붙었어...",
          DialogueId = 10011001,
          GUID = "190FBDDA",
          NextDialogue = 10011002,
          SpeakNpcId = 100003,
          Subtitle = "More Filthoids are coming...",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBDDA"
        },
        [10011002] = {
          ContentKR = "{nickname}, 나한테서 너무 멀리 떨어지지 마. 그리고 필요하면 우리의 암호를 사용하자.",
          DialogueId = 10011002,
          GUID = "190FBE04",
          NextDialogue = 10011003,
          SpeakNpcId = 100003,
          Subtitle = "Stay close, Phoxhunter. If necessary, give out the secret signals.",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE04"
        },
        [10011003] = {
          ContentKR = "기억하지? 산에 오르기 전에 맹수들을 놀라게 하지 않기 위해 약속한 암호 말이야.",
          DialogueId = 10011003,
          GUID = "190FBE05",
          NextDialogue = 10011004,
          SpeakNpcId = 100003,
          Subtitle = "We made them up earlier so as not to alert the beasts up the mountain, remember?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE05"
        },
        [10011004] = {
          ContentKR = "물론이지.",
          DialogueId = 10011004,
          ExStoryInfo = "Player",
          GUID = "190FBE06",
          NextDialogue = 10011005,
          SpeakNpcId = 100001,
          Subtitle = "Yeah.",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE06"
        },
        [10011005] = {
          ContentKR = "좋아. 다시 확인해 보자. 오른쪽 어깨를 두 번 두드리면?",
          DialogueId = 10011005,
          GUID = "190FBE07",
          NextDialogue = 10011006,
          SpeakNpcId = 100003,
          Subtitle = "Alright, a quick check — Two pats on the right shoulder means...?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE07"
        },
        [10011006] = {
          ContentKR = "\"뒤를 조심해\".",
          DialogueId = 10011006,
          ExStoryInfo = "Player",
          GUID = "190FBE08",
          NextDialogue = 10011007,
          SpeakNpcId = 100001,
          Subtitle = "\"Watch your back.\"",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE08"
        },
        [10011007] = {
          ContentKR = "가슴을 두 번 두드리면?",
          DialogueId = 10011007,
          GUID = "190FBE09",
          NextDialogue = 10011008,
          SpeakNpcId = 100003,
          Subtitle = "And two taps on the chest?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE09"
        },
        [10011008] = {
          ContentKR = "\"가까이 붙어\".",
          DialogueId = 10011008,
          ExStoryInfo = "Player",
          GUID = "190FBEA0",
          NextDialogue = 10011009,
          SpeakNpcId = 100001,
          Subtitle = "\"Come closer.\"",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA0"
        },
        [10011009] = {
          ContentKR = "콧등을 살짝 긁으면?",
          DialogueId = 10011009,
          GUID = "190FBEA1",
          NextDialogue = 10011010,
          SpeakNpcId = 100003,
          Subtitle = "And scraping on the nose?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA1"
        },
        [10011010] = {
          ContentKR = "\"이제 괜찮아\".",
          DialogueId = 10011010,
          ExStoryInfo = "Player",
          GUID = "190FBEA2",
          NextDialogue = 10011011,
          SpeakNpcId = 100001,
          Subtitle = "\"Everything's okay now.\"",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA2"
        },
        [10011011] = {
          ContentKR = "좋아. 마지막으로, 눈을 세 번 깜빡이면?",
          DialogueId = 10011011,
          GUID = "190FBEA3",
          NextDialogue = 10011012,
          SpeakNpcId = 100003,
          Subtitle = "Good. And the last one — three quick blinks?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA3"
        },
        [10011012] = {
          ContentKR = "...까먹었어.",
          DialogueId = 10011012,
          ExStoryInfo = "Player",
          GUID = "190FBEA4",
          NextDialogue = 10011013,
          SpeakNpcId = 100001,
          Subtitle = "...I forgot that.",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA4"
        },
        [10011013] = {
          ContentKR = "기억해. 눈을 세 번 깜빡이면...",
          DialogueId = 10011013,
          GUID = "190FBEA5",
          NextDialogue = 10011014,
          SpeakNpcId = 100003,
          Subtitle = "Remember, three quick blinks means—",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA5"
        },
        [10011014] = {
          ContentKR = "됐어. 안 들을래. 말해도 기억 못 할 거야.",
          DialogueId = 10011014,
          ExStoryInfo = "Player",
          GUID = "190FBEA6",
          NextDialogue = 10011015,
          SpeakNpcId = 100001,
          Subtitle = "...I'm not interested in that signal, and I won't remember it anyway.",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA6"
        },
        [10011015] = {
          ContentKR = "...휴.",
          DialogueId = 10011015,
          GUID = "190FBEA7",
          SpeakNpcId = 100003,
          Subtitle = "... *sigh*",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA7"
        },
        [10011101] = {
          ContentKR = "여긴... 신전?",
          DialogueId = 10011101,
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "190FCE42",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 303001,
            [4] = 401001
          },
          SpeakNpcId = 100001,
          Subtitle = "Is this place... a temple?",
          VoiceName = "voice/$Locale$/story/1001/100111/190FCE42"
        },
