        },
        [10019104] = {
          ContentKR = "무슨 말을 하는 거야...",
          DialogueId = 10019104,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "Player",
          GUID = "1914EF17",
          SpeakNpcId = 100001,
          Subtitle = "Wait, I can't hear you...",
          VoiceName = "voice/$Locale$/story/1001/100191/1914EF17"
        },
        [10019201] = {
          Content = "关于那柄剑……除了它从小就在身边之外，我一无所知。",
          DialogueId = 10019201,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1914FF2A",
          NextDialogue = 10019202,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100192/1914FF2A"
        },
        [10019202] = {
          Content = "正如我不知道自己从何而来——我没有与贝蕾相遇之前的任何记忆。",
          DialogueId = 10019202,
          Duration = 3.5,
          ExStoryInfo = "Player",
          GUID = "1914FF54",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100192/1914FF54"
        },
        [10019301] = {
