        [10030605] = {
          Camera = "0.396332,244.167969,21.378906,0.000094,25.396158,-121.224731,35.000011,411.428223,false,Manual,22.0",
          ContentKR = "퉤퉤퉤, 안달복달하면서 온 도시에 의사를 찾아다닌 사람이 누구였지? 카밀라한테 얘를 보살펴달라고 굽신거리던 건 또 누구였나? 막상 깨어나면 또 이런다니까!",
