          VoiceName = "voice/$Locale$/story/1003/100306/191C4EA0"
        },
        [10030609] = {
          ContentKR = "아주 좋아. '불사의 백기사, 다시 태어난 녹토 보이저의 별, 축복받은 악마 백작'이 이 마왕님을 버리고 가지 않을 줄 알았어!",
