          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100309/191C7F06"
        },
        [10030904] = {
          ContentKR = "어떻게 범인 특징을 빠르게 잡아낼지 생각중입니다.",
