          Scripts = "SEQ{CameraMoveTo{_delay{7},TargetPosition{\"102.716476,171.84108,50.386719,0.000454,10.197875,-148.500732,35.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"102.716476,171.84108,55.585938,0.000454,9.397876,-148.300888,35.0,100000.0,false,DoNotOverride,22.0\"},duration{8}}}",
          SpeakNpcId = 100313,
