          VoiceName = "voice/$Locale$/story/1003/100329/191DC6D2"
        },
        [10032902] = {
          ContentKR = "리듬 장교님은 이곳에 익숙하신가 보네요?",
          DialogueId = 10032902,
          GUID = "191DC6FC",
          NextDialogue = 10032903,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC6FC"
        },
        [10032903] = {
          ContentKR = "제국은 최근 몇 년 동안 각 도시의 지하 시설 건설에 큰 주의를 기울이고 있습니다. 따라서 방위대도 유지보수를 책임져야죠.",
          DialogueId = 10032903,
          GUID = "191DC726",
          NextDialogue = 10032904,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC726"
        },
        [10032904] = {
          ContentKR = "처음 방위대에 들어왔을 땐, 매일 이곳의 청소를 배정받았습니다.",
          DialogueId = 10032904,
          GUID = "191DC750",
          NextDialogue = 10032905,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC750"
        },
        [10032905] = {
          ContentKR = "매일 하수도 청소라니... 카론은 군단에 들어가도 괴롭힘을 당하는 건가요?",
          DialogueId = 10032905,
          GUID = "191DC77A",
          NextDialogue = 10032906,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC77A"
        },
        [10032906] = {
          ContentKR = "편견의 뿌리는 깊습니다. 하지만 적어도 군단에선 공적을 쌓는 것을 통해 존경을 받을 수 있습니다.",
          DialogueId = 10032906,
          GUID = "191DC7A4",
          NextDialogue = 10032907,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC7A4"
        },
        [10032907] = {
          ContentKR = "이 또한 '악마의 아이'로서 속죄할 수 있는 방법 중 하나죠.",
          DialogueId = 10032907,
          GUID = "191DC7CE",
          NextDialogue = 10032908,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC7CE"
        },
        [10032908] = {
          ContentKR = "잠깐... 무슨 소리 못 들었어?",
