        [10034001] = {
          ContentKR = "군인의 비밀 아지트라니, 어떤 모습일까? 진짜 짜릿하네!",
          DialogueId = 10034001,
          GUID = "191E7B4A",
          NextDialogue = 10034002,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100340/191E7B4A"
        },
        [10034002] = {
          ContentKR = "열쇠에 적혀있는 곳은 고속도로 환승소 근처인 것 같은데.",
          DialogueId = 10034002,
          GUID = "191E7B74",
          NextDialogue = 10034003,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100340/191E7B74"
        },
        [10034003] = {
          ContentKR = "비밀 아지트를 이런 곳에 만들다니...",
          DialogueId = 10034003,
          GUID = "191E7B9E",
          NextDialogue = 10034004,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100340/191E7B9E"
        },
        [10034004] = {
          ContentKR = "사람들은 가끔 아무도 이해할 수 없는 곳에 혼자만의 피난처를 만들기 좋아하지...",
          DialogueId = 10034004,
          GUID = "191E7BC8",
          NextDialogue = 10034005,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100340/191E7BC8"
        },
        [10034005] = {
          ContentKR = "누군가는 차 안에, 누군가는 파이프 속에 말이야. 그러니까 이런 곳을 비밀 아지트로 삼는 것도 이상하진 않아.",
          DialogueId = 10034005,
          GUID = "191E7BF2",
          NextDialogue = 10034006,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100340/191E7BF2"
        },
        [10034006] = {
          ContentKR = "어... 꽤 일반적이잖아. 나만 어릴 때 어딘가 파고 들어가는 걸 좋아했나?",
          DialogueId = 10034006,
          GUID = "191E7C1C",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100340/191E7C1C"
        },
        [10034007] = {
          ContentKR = "여긴가?",
          DialogueId = 10034007,
          GUID = "191E7C46",
          NextDialogue = 10034008,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100340/191E7C46"
        },
        [10034008] = {
          ContentKR = "입구가 근처에 있을 거야, 찾아보자.",
          DialogueId = 10034008,
          GUID = "191E7C70",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100340/191E7C70"
        },
        [10034101] = {
          Camera = "-1302.09375,188.645508,676.1875,1.753743,-22.554377,-9.436762,35.000008,199.365784,false,DoNotOverride,8.0",
          ContentKR = "오? 버려진 정비실을 개조한 것 같네.",
          DialogueId = 10034101,
          FinalCamera = "-1145.925781,162.691406,610.441406,1.753743,-22.554377,-9.436762,35.000008,199.365784,false,DoNotOverride,8.0",
          GUID = "191E8BB2",
          NextDialogue = 10034102,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:ConfidentLRToExplainR_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8BB2"
        },
        [10034102] = {
          Camera = "330.632812,-30.893555,59.353516,1.753803,12.445362,178.965683,35.0,199.365784,false,DoNotOverride,8.0",
          ContentKR = "이건 그냥 스노우의 난잡한 방이잖아, 아니, 마왕의 호화 침실이랑 비슷하네!",
          DialogueId = 10034102,
          FacialId = {
            [1] = "200002:Doubt01",
            [2] = "200021:Angry01",
            [3] = "100001:Doubt01"
          },
          FinalCamera = "330.792969,-23.540039,59.5625,1.753803,12.445362,178.965683,35.0,199.365784,false,DoNotOverride,8.0",
          GUID = "191E8BDC",
          NextDialogue = 10034103,
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Talk01_Start",
            [2] = "200021:ConfidentLRToExplainR_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8BDC"
        },
        [10034103] = {
          Camera = "-157.855469,20.635742,139.306641,1.753745,-2.15362,-32.439327,35.000015,199.365784,false,DoNotOverride,8.0",
          ContentKR = "흩어져서 찾아보자, 그 은색 도장.",
          DialogueId = 10034103,
          FinalCamera = "-148.238281,18.021484,147.634766,1.753745,-4.553892,-31.638124,35.000011,199.365784,false,DoNotOverride,8.0",
          GUID = "191E8C06",
          Scripts = "MoveTo{ActorId{100001},TargetPoint{\"cp2fixsimple30Point01\"},MoveSpeed{100},Visibility{\"Show\"}}",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "200002:Talk01_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C06"
        },
        [10034104] = {
          ContentKR = "코퀴투스 주 아이스레이크 시티 제6군단 소속 방위대, <H>리듬 페실</>은 수년간, 여러 차례의 <H>필토이드 토벌 작전</>을 현명한 판단과 용맹한 전투로 신속하게 마무리 지음.\n지역 치안을 유지하는 과정에서 더할 나위 없이 핵심적인 작용을 발휘함.\n군단의 평가를 거쳐, 황제 폐하 율리우스의 이름으로 리듬 페실에게 황제 새끼손가락 반지 훈장과 함께 준위의 계급을 수여하니 모든 군인은 이를 모범으로 삼아 정진하고 성장하기를 바람.\n황제 폐하께 영광을.",
          DialogueId = 10034104,
          DialoguePanelType = "{type:showtext;topic:READ_NAME_2000047;content:READ_TEXT_2000047}",
          GUID = "191E8C30",
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C30"
        },
        [10034105] = {
          ContentKR = "석회벽의 한쪽 구석에는 나이프로 새겨진 글자가 빽빽하게 덮여있다. 어떤 글자는 아이의 필체처럼 삐뚤삐뚤하고, 어떤 글자는 어른처럼 성숙한 필체로 쓰여 있다. 글자들은 전부 같은 말이다.\n\"더 이상 그 누구도 필토이드에게 죽는 걸 보고만 있지 않겠다.\"",
          DialogueId = 10034105,
          GUID = "191E8C5A",
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C5A"
        },
        [10034106] = {
          ContentKR = "<H>침식자는 매우 위험하니 겉모습에 속지 마세요!</>\n9월 24일, 본 시에서 매우 끔찍한 '침식' 사건이 발생했습니다. 제6군단 방위대의 조사를 거쳐 얻어낸 결론은 다음과 같습니다.\n아이스레이크 시티 주민 페실 부부는 9월 13일 눈물의 호수 옆 도로변에서 로비 브라운이라는 청년을 우연히 만났습니다. 페실 부부는 중상을 입은 그를 집으로 데려가 돌보았습니다.\n그러나 로비 브라운은 제국의 잠재적 침식자에 대한 조사를 피해 도시 밖으로 도피한 침식자였고, 페실 부부의 도움을 받을 때 자신의 침식 흔적을 의도적으로 숨겼습니다. 10일 후, 비극이 발생했습니다. 브라운은 필토이드로 변하여 페실 부부를 포함한 아이스레이크 남쪽 구역 시민 수십 명을 살해했습니다. 제6군단 소속 아이스레이크 시티 방위대가 긴급 출동하여 이번 소란을 진압했습니다.\n이번 사태로 총 18명이 사망했고, 그중 3명은 솔라인 것으로 밝혀졌습니다. 그 외 34명이 다쳤습니다. 시민 여러분들, 명심해 주십시오. 신원불명의 카론을 함부로 수용해서는 안 됩니다. 침식자를 발견하게 되면 즉시 치안서에 신고해 주십시오. 그들은 하나도 빠짐없이, 영원히 인간의 적입니다. 의도적으로 침식자에게 협력하거나 침식자를 은폐하는 자는 <휘페르보레아 형사 법전>제 54조에 따라 사형에 처합니다.\n",
          DialogueId = 10034106,
          DialoguePanelType = "{type:showtext;topic:READ_NAME_2000048;content:READ_TEXT_2000048}",
          GUID = "191E8C84",
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C84"
        },
