        },
        [10036216] = {
          ContentKR = "세상이, 끝날 때까지, 기절해 있을 줄 알았어.",
          DialogueId = 10036216,
          GUID = "191FE6B0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036217,
          RelatedWikiId = {
            [1] = 407003,
