        [10036333] = {DialogueId = 10036333, GUID = "191FF719"},
        [10036334] = {
          ContentKR = "멋진 분, 이따 같이 춤 한 곡 출래요?",
          DialogueId = 10036334,
          Duration = 5,
          GUID = "191FF521",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF521"
        },
        [10036335] = {
          ContentKR = "어이, 이 총 진짜 같지? 고무탄도 나간다고. 끝내주지!",
          DialogueId = 10036335,
          Duration = 8,
          GUID = "191FF522",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF522"
        },
        [10036336] = {
          ContentKR = "아, 안 취했다니까! 봐, 나 아직, 바닥에서 춤도 출 수 있어.",
          DialogueId = 10036336,
          Duration = 8,
          GUID = "191FF523",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF523"
        },
        [10036337] = {
          ContentKR = "올해는 왜 아무도 물바퀴 분장 안 했지? 엄청 기대했는데.",
          DialogueId = 10036337,
          Duration = 7,
          GUID = "191FF524",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF524"
        },
        [10036338] = {
          ContentKR = "크르르르, 난 필토이드다! 크르르릉, 와앙.",
          DialogueId = 10036338,
          Duration = 6,
          GUID = "191FF525",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF525"
        },
        [10036339] = {
          ContentKR = "밟지 마. 시체 역할 하는 중이잖아.",
          DialogueId = 10036339,
          Duration = 4,
          GUID = "191FF526",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF526"
        },
        [10036340] = {
          ContentKR = "내가 먼저 댄스 파트너 요청했거든? 지금 뭐야, 싸우자는 거야?",
          DialogueId = 10036340,
          Duration = 8,
          GUID = "191FF527",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF527"
        },
        [10036341] = {
          ContentKR = "극장 안에선 싸우지 마세요. 은촛불 축제 기간에도 예외는 없습니다!",
          DialogueId = 10036341,
          Duration = 7,
          GUID = "191FF528",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF528"
        },
        [10036342] = {
          ContentKR = "몸 진짜 좋다! 복근 한번 만져 봐도 돼?",
          DialogueId = 10036342,
          Duration = 6,
          GUID = "191FF529",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF529"
        },
        [10036343] = {
          ContentKR = "조금 전에 그 공연 정말 멋졌어요. 누구 이 편지좀 우아한 주연 아가씨한테 전해 주실 분?",
          DialogueId = 10036343,
          Duration = 10,
          GUID = "191FF52A",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF52A"
        },
        [10036344] = {
          ContentKR = "브라보, 멋진 춤이야!",
          DialogueId = 10036344,
          Duration = 2,
          GUID = "191FF52B",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF52B"
        },
        [10036345] = {
          ContentKR = "이 필토이드 풍선 어때? 진짜 같지?",
          DialogueId = 10036345,
          Duration = 6,
          GUID = "191FF52C",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF52C"
        },
        [10036346] = {
          ContentKR = "아직 이르잖아, 일어나서 계속해! 오늘은 잘 생각들 하지 말라고! 하하하하하!",
          DialogueId = 10036346,
          Duration = 9,
          GUID = "191FF52D",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF52D"
        },
