        [10100202] = {
          Camera = "1.257812,221.437988,150.764648,0.001272,-6.900089,-89.157776,35.0,492.602234,false,Manual,1.8",
          ContentKR = "당신들... 내 이름을 어떻게...? 베레, 여긴 어디...",
          DialogueId = 10100202,
          ExStoryInfo = "Player",
          FacialId = {
