CameraMoveTo{_delay{2},TargetPosition{"-29.773438,54.472656,127.289062,0.00116,-1.800137,-76.755142,35.000008,170.437286,false,Manual,4.0"},duration{0.4}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Hyperborea... I'm in the Hyperborean Empire...?!",
          TalkActionId = {
            [1] = "200002:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101002/1948E960"
