PlayAnimation{_delay{7},ActorId{200065},AnimationId{"Sigh_Start"},Duration{1}}
}]],
          SpeakNpcId = 200065,
          Subtitle = "Oh, and I can also catch {性别:him|her} up on our line of work. To be honest, it's been pretty tough lately,\nany commission worth a jot has to be fought for.",
          TalkActionId = {
            [1] = "200003:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101040/194B5828"
        },
        [10104005] = {
          Camera = "1019.142822,-738.232422,198.009766,-0.0,0.200002,87.801537,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "방금 오늘 의뢰를 봤는데, 죄다 돈도 안 되는 작은 일들뿐이야. '그 일' 말고는...",
          DialogueId = 10104005,
          FinalCamera = "1021.591187,-674.18457,195.511719,-0.0,0.200002,87.801537,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "194B5852",
          LookAt = {
            [1] = "100001:n(200065)"
          },
          NextOptions = {
            [1] = 101040051
          },
          SpeakNpcId = 200065,
          Subtitle = "I just had a gander at today's jobs, and they're all thankless. Except for that hot potato...",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101040/194B5852"
        },
        [10104006] = {
          Camera = "206.755127,354.53418,169.501953,0.000076,-7.199996,-92.795441,30.000002,292.884125,false,Manual,2.0",
          ContentKR = "무슨 이상한 돌을 찾는 귀찮은 의뢰야... 하아, 말해봐야 소용없어. 우리 같은 베테랑도 받지 않는 일이거든. 이제 막 시작한 네가 뭘 할 수 있겠어.",
          DialogueId = 10104006,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "194B587C",
          LookAt = {
            [1] = "200003:n(100001)",
            [2] = "200002:n(200065)"
          },
          NextOptions = {
            [1] = 101040061
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200065},AnimationId{"Sigh_End"},Duration{2.2}},
PlayAnimation{ActorId{200065},AnimationId{"Talk01_Start"},Duration{2}},
PlayAnimation{ActorId{200065},AnimationId{"Talk01_End"},Duration{0.7}},
PlayAnimation{ActorId{200065},AnimationId{"Disagree"},Duration{1.7}},
PlayAnimation{ActorId{200065},AnimationId{"Explain02_Start"},Duration{1}}
}]],
          SpeakNpcId = 200065,
          Subtitle = "A right bother of a job, finding some daft stone — eh, no point in telling you, even us old hands don't dare touch it,\nlet alone a newbie like you.",
          VoiceName = "voice/$Locale$/story/1002/101040/194B587C"
        },
        [10104007] = {
          Camera = "-60.295044,-143.261719,150.679688,0.001294,-1.100057,41.202648,65.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "글로스터 폐광으로 가서 <H>'반짝이는 수정'</>이라는 희귀한 광석을 찾는 거야. <H>헨릭 애설레드</>가 의뢰한 건이야. 아, 네가 만난 그 헨릭말이야.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104007,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "194B58A6",
          NextDialogue = 10104008,
          RelatedWikiId = {
            [1] = 301004
          },
          Scripts = [[
PARA{
SEQ{
PlayAnimation{ActorId{200003},AnimationId{"Think_Start"},Duration{4.9}},
PlayAnimation{ActorId{200003},AnimationId{"Think_End"},Duration{1}},
PlayAnimation{ActorId{200003},AnimationId{"Explain01_Start"},Duration{3.5}},
PlayAnimation{ActorId{200003},AnimationId{"Explain01_End"},Duration{1.4}},
PlayAnimation{ActorId{200003},AnimationId{"Agree"},Duration{1}}
},
TurnTo{_delay{1},TurnToDescription{"200065:n(200003)"}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "It's looking for a rare mineral called Crystallo of Stella in the old Glevum Pit. The client is Henrik Ethelred—\nYes, the very same Henrik you know.",
          TalkActionId = {
            [1] = "200065:Explain02_End"
          },
          TurnTo = {
            [1] = "100001:n(200003)"
          },
          VoiceName = "voice/$Locale$/story/1002/101040/194B58A6"
        },
        [10104008] = {
          ContentKR = "글로스터 폐광은 이제 필토이드의 소굴이 됐어. 운이 좋으면 남은 월석이라도 발견할까 싶어서, 몇몇 월석 사냥꾼이 위험을 무릅쓰고 갔었지만 모두 못 돌아왔어.",
          DialogueId = 10104008,
          GUID = "194B58D0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10104008.T_Story_Recall_10104008'",
          NextDialogue = 10104009,
          RelatedWikiId = {
            [1] = 406001
          },
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SpeakNpcId = 200003,
          Subtitle = [[
Glevum Pit is now a den for Filthoids. A few Phoxhunters tried their luck, hoping to find some Phoxene scraps there,
but not a soul came back.]],
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101040/194B58D0"
        },
        [10104009] = {
          Camera = "124.620239,-443.34668,310.703125,0.001321,-20.100447,76.801399,25.0,680.331482,false,Manual,1.2",
          ContentKR = "그래서 하루가 지나도록 5천 실버나 걸린 헨릭의 의뢰를 하겠다고 나서는 월석 사냥꾼이 없는 거고.",
          DialogueId = 10104009,
          GUID = "194B58FA",
          NextDialogue = 10104010,
          Scripts = [[
