          SpeakNpcId = 200065,
          Subtitle = [[
Phoxhunters are born adventurers, but we're not reckless fools! The stone's very existence aside...
Who knows if Henrik can even cough up the cash?]],
          VoiceName = "voice/$Locale$/story/1002/101040/194B5924"
        },
        [10104011] = {
          Camera = "77.71582,492.297852,137.373047,0.001236,-2.698307,-72.790131,35.0,468.643616,false,Manual,2.0",
          ContentKR = "헨릭은 최근에 파산했잖아. 오죽하면 가문 재산까지 팔려고 하겠어? 아, 설마 반짝이는 수정도 되팔려는 건 아니겠지? ... 아니지, 수정의 거래가 금지된 게 벌써 몇 년인데 어떻게 판로를 찾겠어?",
          DialogueId = 10104011,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "88.144165,495.515625,137.373047,0.001236,-2.698307,-72.790131,35.0,471.859924,false,Manual,6.0",
          GUID = "194B594E",
          NextDialogue = 10104012,
