          SpeakNpcId = 200065,
          Subtitle = "You serious? Kid, I'm not joking with you — this isn't child's play!",
          VoiceName = "voice/$Locale$/story/1002/101040/194B5A20"
        },
        [10104017] = {
          ContentKR = "감사해요, 저도 알아요. 하지만 카밀라 씨...",
          DialogueId = 10104017,
          ExStoryInfo = "Player",
          FacialId = {
