          VoiceName = "voice/$Locale$/story/1002/101046/194BBA98"
        },
        [10104605] = {
          ContentKR = "마왕이 되어서 전장에서 도망칠 수는 없지. 그러다 시종에게 무시나 당한다고. 프시케, 너도 따라와!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104605,
          FacialId = {
