          SpeakNpcId = 200002,
          Subtitle = "This Demon King can't just scarper from the battle and let the little minion think less of her. Psyche, you should also come with us!",
          VoiceName = "voice/$Locale$/story/1002/101046/194BBAC2"
        },
        [10104606] = {
