          SpeakNpcId = 100001,
          Subtitle = "...Alright then. Be careful, both of you.",
          TalkActionId = {
            [1] = "200006:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101046/194BBC3C"
        },
        [10104701] = {
          ContentKR = "잠겼어? 내가 여는 거 잘 봐!",
          DialogueId = 10104701,
          Duration = 3,
          GUID = "194BCA82",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104702,
          SpeakNpcId = 200002,
          Subtitle = "It's locked? Watch me bash it open!",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCA82"
        },
        [10104702] = {
          ContentKR = "(문에 박치기하는 소리)",
          DialogueId = 10104702,
          DisableMouth = 1,
          Duration = 2,
          GUID = "194BCA83",
          NextDialogue = 10104703,
          Subtitle = "*Sound of headbutting the door*",
          VoiceName = "sfx/common/story/01/tietougong"
        },
        [10104703] = {
          ContentKR = "...악!",
          DialogueId = 10104703,
          Duration = 2,
          GUID = "194BCAD6",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104704,
          SpeakNpcId = 200002,
          Subtitle = "...Ouchie!",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCAD6"
        },
        [10104704] = {
          ContentKR = "이 정도 두께라면 아무리 힘을 써도 열리지 않겠어.",
          DialogueId = 10104704,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BCB00",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104705,
          SpeakNpcId = 100001,
          Subtitle = "A door this thick is probably impervious to brute force.",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCB00"
        },
        [10104705] = {
          ContentKR = "그럼 다른 입구가 있는지 주변을 둘러보자.",
          DialogueId = 10104705,
          Duration = 3,
          GUID = "194BCB2A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104706,
          SpeakNpcId = 200006,
          Subtitle = "Then let's look around to see if there's another way in.",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCB2A"
        },
        [10104706] = {
          ContentKR = "스노우, 머리 많이 아프겠다. 내가 도와줄게.",
          DialogueId = 10104706,
          Duration = 3,
          GUID = "194BCB54",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104707,
          SpeakNpcId = 200006,
          Subtitle = "Snow, does your head hurt? Let me help you—",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCB54"
        },
        [10104707] = {
          ContentKR = "...이렇게 불면 아프지 않을 거야.",
          DialogueId = 10104707,
          Duration = 3,
          GUID = "194BCB7E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104708,
          SpeakNpcId = 200006,
          Subtitle = "...There, a little puff to ease the pain.",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCB7E"
        },
        [10104708] = {
          ContentKR = "흑흑... 넌 정말 좋은 사람이야. 이 마왕님께서 여길 점령하면 널...",
          DialogueId = 10104708,
          Duration = 3,
          GUID = "194BCBA8",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104709,
          SpeakNpcId = 200002,
          Subtitle = "Awww... you're such a nice person. When this Demon King conquers this place, I'll appoint you—",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCBA8"
        },
        [10104709] = {
          ContentKR = "'온화한 녹색 옷의 마법사, 현명한 월석의 주재자, 초대 글로스터 광갱 대공'으로 임명하겠어!",
          DialogueId = 10104709,
          Duration = 3,
          GUID = "194BCBD2",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104710,
          SpeakNpcId = 200002,
          Subtitle = "\"The Gentle Green-Cloaked Mage, the Wise Master of Phoxene, the Inaugural Grand Duke of Glevum Pit\"!",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCBD2"
        },
        [10104710] = {
          ContentKR = "(저번에 나는 하수도 공작이었는데... 대공이면 나보다 높은 작위 아닌가?)",
          DialogueId = 10104710,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BCBFC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104711,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(I was the Duke of the Sewers... is a grand duke a higher rank than a duke?)",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCBFC"
        },
        [10104711] = {
          ContentKR = "(왜 프시케의 작위가 나보다 높은 거지? 잠깐, 난 또 뭘 진지하게 생각하는 거야.)",
          DialogueId = 10104711,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BCC26",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(How come Psyche gets a higher title than me? Hold on, why am I seriously mulling this over again?)",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCC26"
        },
        [10104801] = {
          ContentKR = "\"본 마왕 스노우 님의 인도 하에, 막 아이스레이크 시티에 도착한 시종은 하루 만에 뛰어난 '월석 사냥꾼'이 되었다.\"",
          DialogueId = 10104801,
          GUID = "194BDAEA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104802,
          SpeakNpcId = 200002,
          Subtitle = "\"Guided by Snow the Demon King, the little minion who just arrived in Icelake from afar has become a brilliant Phoxhunter in a mere day.\"",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDAEA"
        },
        [10104802] = {
          ContentKR = "이 마왕님의 전설에 또 새로운 페이지가 더해지는군.",
          DialogueId = 10104802,
          GUID = "194BDB14",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104803,
          SpeakNpcId = 200002,
          Subtitle = "A new chapter of the legend of this Demon King!",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB14"
        },
        [10104803] = {
          ContentKR = "'월석 사냥꾼'이라... 꽤나 독특한 이름이네... 월석을 사냥하는 사람이라는 뜻인 건가?",
          DialogueId = 10104803,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BDB3E",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104804,
          SpeakNpcId = 100001,
          Subtitle = "\"Phoxhunter\" is a cool name... Do they all hunt something called Phox?",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB3E"
        },
        [10104804] = {
          ContentKR = "땡! '월석 사냥꾼'은 의뢰를 받아서 수행하는 현상금 사냥꾼이라는 뜻이야. 월석을 채집하는 건 옛날 얘기라고!",
          DialogueId = 10104804,
          GUID = "194BDB68",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104805,
          SpeakNpcId = 200002,
          Subtitle = "Nah! Phoxhunters nowadays are actually bounty hunters. It has something to do with Phoxene a long time ago.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB68"
        },
        [10104805] = {
          ContentKR = "응, 이 직업은 아이스레이크 시티에서 유래된 거라고 들었어.",
          DialogueId = 10104805,
          GUID = "194BDB92",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104806,
          SpeakNpcId = 200006,
          Subtitle = "Right, I heard it used to refer to a profession that originated right here in Icelake.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB92"
        },
        [10104806] = {
          ContentKR = "베드르폴니르 산 일대에는 천국의 나무 광맥이 풍부하고, 그 위에 달린 월석이 아주 좋은 가격에 팔렸기 때문일 거야...",
          DialogueId = 10104806,
          GUID = "194BDBBC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104807,
          SpeakNpcId = 200006,
          Subtitle = "It seemed to all start with the rich Heaventree veins in the Vidofnir Mountains, and the Phoxene on them could be sold for a good price...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDBBC"
        },
        [10104807] = {
          ContentKR = "맞아! 그래서 아주 오래전 많은 사람이 위험을 무릅쓰고 의뢰를 받아 월석을 캐러 왔지.",
          DialogueId = 10104807,
          GUID = "194BDBE6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104808,
          SpeakNpcId = 200002,
          Subtitle = "Exactly! So, a long, long time ago, many people braved the risks of collecting Phoxene for money.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDBE6"
        },
        [10104808] = {
          ContentKR = "하지만 거상과 제국이 이 부근의 광산을 차례로 접수하면서 일반인들은 월석을 마주할 기회를 잃게 됐어... 거기다 이 근처 광맥도 점점 고갈됐고 말이야.",
          DialogueId = 10104808,
          GUID = "194BDC10",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104815,
          SpeakNpcId = 200006,
          Subtitle = "But then the big merchants and the Empire took over the mines around here, and ordinary folk hardly had a chance with Phoxene anymore... After that, the local veins gradually ran dry.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC10"
        },
        [10104809] = {
          ContentKR = "하지만 그렇게 의뢰를 받아 생계를 유지하는 월석 사냥꾼은 여전히 특별한 직업으로 남아있어. 물론 의뢰 종류는 더 다양해졌지만.",
          DialogueId = 10104809,
          GUID = "194BDC3A",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104810,
          SpeakNpcId = 200002,
          Subtitle = "While Phoxhunters, who lived off commissions, remained as a profession. It's just that the types of commissions changed a lot since then.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC3A"
        },
        [10104810] = {
          ContentKR = "크게는 필토이드의 마수에서 도시를 보호하고, 작게는 개가 물고 가려는 갓 구운 빵을 빼앗는 것까지 있거든...",
          DialogueId = 10104810,
          GUID = "194BDC64",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104811,
          SpeakNpcId = 200002,
          Subtitle = "There are big ones like protecting the city from the claws of Filthoids, and little ones like getting freshly baked bread back from a dog's mouth...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC64"
        },
        [10104811] = {
          ContentKR = "개와 빵을 두고 다툰다고?",
          DialogueId = 10104811,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BDC8E",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104812,
          SpeakNpcId = 100001,
          Subtitle = "Fighting dogs for bread?",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC8E"
        },
        [10104812] = {
          ContentKR = "더 무서운 것도 있어. 예를 들면 자기가 싫어하는 사람을 다시는 눈앞에 나타나지 못하게 하는 거라던가",
          DialogueId = 10104812,
          GUID = "194BDCB8",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104813,
          SpeakNpcId = 200002,
          Subtitle = "And some even more terrifying commissions like making sure a certain someone you don't like never shows up again...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDCB8"
        },
        [10104813] = {
          ContentKR = "하지만 아스포델에 다녀오는 사이에 개가 빵을 다 먹어 치우지 않을까?",
          DialogueId = 10104813,
          GUID = "194BDCE2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104814,
          SpeakNpcId = 200006,
          Subtitle = "But by the time you make a trip down to The Asphodel, wouldn't the bread have been gobbled up by the dog already?",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDCE2"
        },
        [10104814] = {
          ContentKR = "이봐, 너희 둘! 지금 개가 중요한 게 아니잖아!",
          DialogueId = 10104814,
          GUID = "194BDD0C",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "You're both missing the point here!",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDD0C"
        },
        [10104815] = {
          ContentKR = "그 후에 이 부근 광맥도 점점 고갈됐어. 지금 이 글로스터 폐광처럼...",
          DialogueId = 10104815,
          GUID = "194BDC11",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104816,
          SpeakNpcId = 200006,
          Subtitle = "After that, the local veins gradually ran dry, including this Glevum Pit...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC11"
        },
        [10104816] = {
          ContentKR = "맞아, 정말 아쉽다니까! 안 그랬으면 시종도 월석을 팔아 큰돈을 벌 수 있었을 텐데.",
          DialogueId = 10104816,
          GUID = "194BDC12",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104809,
          SpeakNpcId = 200002,
          Subtitle = "Yeah, what a pity! Otherwise my little minion could have made a fortune selling Phoxene.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC12"
        },
        [10104901] = {
          ContentKR = "괜찮아?",
          DialogueId = 10104901,
          ExStoryInfo = "Player",
          GUID = "194BEB52",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104902,
          SpeakNpcId = 100001,
          Subtitle = "Everything alright?",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEB52"
        },
        [10104902] = {
          ContentKR = "...!!",
          DialogueId = 10104902,
          GUID = "194BEB7C",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104903,
          SpeakNpcId = 200006,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEB7C"
        },
        [10104903] = {
          ContentKR = "방금 갑자기 앞이 잘 안보여서 필토이드를 놀라게 해 버렸네... 정말 미안해!",
          DialogueId = 10104903,
          GUID = "194BEBA6",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104904,
          SpeakNpcId = 200006,
          Subtitle = "I suddenly couldn't see clearly back there and ended up startling that monster... I'm so sorry!",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEBA6"
        },
        [10104904] = {
          ContentKR = "이제 좀 괜찮아?",
          DialogueId = 10104904,
          ExStoryInfo = "Player",
          GUID = "194BEBD0",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104905,
          SpeakNpcId = 100001,
          Subtitle = "Are you feeling better now?",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEBD0"
        },
        [10104905] = {
          ContentKR = "응, 괜찮아.",
          DialogueId = 10104905,
          GUID = "194BEBFA",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10104906,
          SpeakNpcId = 200006,
          Subtitle = "Yeah, I'm fine now.",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEBFA"
        },
        [10104906] = {
          ContentKR = "좋아, 싸울 수 있으면 이 덩치 큰 놈을 같이 상대해 보자.",
          DialogueId = 10104906,
          ExStoryInfo = "Player",
          GUID = "194BEC24",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104907,
          SpeakNpcId = 100001,
          Subtitle = "Great. If you're in the condition to fight, let's take on this monster together.",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEC24"
        },
        [10104907] = {
          ContentKR = "알았어! 최선을 다해 널 도울게.",
          DialogueId = 10104907,
          GUID = "194BEC4E",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Sure! I'll do my best to support you.",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEC4E"
        },
        [10105001] = {
          ContentKR = "아무리 흉폭한 녀석이라도 <H>약점</>만 찾는다면, 무찌를 수 있다고 했어...",
          DialogueId = 10105001,
          GUID = "194BFBB9",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105002,
          SpeakNpcId = 200006,
          Subtitle = "They say even the fiercest beasts can be brought down by targeting their weaknesses...",
          VoiceName = "voice/$Locale$/story/1002/101050/194BFBB9"
        },
        [10105002] = {
          ContentKR = "필토이드도 마찬가지야! 차분히 생각하자... 약점을 찾는 거야.",
          DialogueId = 10105002,
          GUID = "194BFBBA",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "It must be the same with this Filthoid! Let's take a breath and find its weakness.",
          VoiceName = "voice/$Locale$/story/1002/101050/194BFBBA"
        },
        [10105101] = {
          ContentKR = "움직임이 느려졌어. {nickname}, 아무래도 <H>어깨 부위</>가 약점인 것 같아!",
          DialogueId = 10105101,
          ExStoryInfo = "Player",
          GUID = "194C0C4C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "It's become slow. , those gems must be its weak points!",
          VoiceName = "voice/$Locale$/story/1002/101051/194C0C4C"
        },
        [10105201] = {
          ContentKR = "멈췄다, 바로 지금이야!",
          DialogueId = 10105201,
          GUID = "194C1C8A",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10105202,
          SpeakNpcId = 200006,
          Subtitle = "It's stopped — now's our chance!",
          VoiceName = "voice/$Locale$/story/1002/101052/194C1C8A"
        },
        [10105202] = {
          ContentKR = "정말 다행이야...!",
          DialogueId = 10105202,
          GUID = "194C1CB4",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Great...!",
          VoiceName = "voice/$Locale$/story/1002/101052/194C1CB4"
        },
        [10105301] = {
          ContentKR = "반짝이는 수정이라... 이렇게 아름다우니 다들 좋아하지.",
          DialogueId = 10105301,
          GUID = "194C2CF2",
          SpeakNpcId = 200021,
          SpeakNpcName = "UI_Npc_Name_Man_17",
          Subtitle = "Crystallo of Stella... Look at its beauty! No wonder everyone wants a piece of it.",
          VoiceName = "voice/$Locale$/story/1002/101053/194C2CF2"
        },
        [10105302] = {
          ContentKR = "설마 방금 그 소리가... 너희가 저 덩치를 해치우면서 난 거였어? 꽤 하는걸?",
          DialogueId = 10105302,
          GUID = "194C2D1C",
          SpeakNpcId = 200021,
          SpeakNpcName = "UI_Npc_Name_Man_17",
          Subtitle = "What a commotion I just heard. So it was you guys that took out that giant thing? Impressive.",
          VoiceName = "voice/$Locale$/story/1002/101053/194C2D1C"
        },
        [10105401] = {
          Camera = "-29.328125,-255.251953,164.21875,0.001081,-14.107393,94.226692,50.000008,544.145996,false,Manual,5.0",
          ContentKR = "아웃사이더?! 장난치지 마. 반짝이는 수정이 어떻게 네 손에 있는데? 그건 우리 시종이 먼저...",
          DialogueId = 10105401,
          FacialId = {
            [1] = "200021:Smile02",
            [2] = "200002:Angry01"
          },
          FinalCamera = "-3.181641,-258.998047,197.030273,0.001091,-23.507626,104.626007,50.000008,311.108795,false,Manual,5.0",
          GUID = "194C3D5A",
          LookAt = {
            [1] = "200021:n(200021)",
            [2] = "200006:n(200021)",
            [3] = "200061:n(200021)",
            [4] = "200002:n(200021)"
          },
          NextDialogue = 10105402,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405004,
            [3] = 201007,
            [4] = 201005,
            [5] = 301004,
            [6] = 406001,
            [7] = 303004,
            [8] = 201009
          },
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt01/0033_story_humour"}},
SEQ{
MoveTo{ActorId{200002},MoveSpeed{201},TargetPoint{"P101054_BaiMove1"}},
