            [2] = [[

200002:Angry01_End]]
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C3DD8"
        },
        [10105406] = {
          Camera = "-152.238281,212.773438,135.039062,3.000984,-3.001451,-63.853107,25.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeOutQuad",
          ContentKR = "말이 통하지 않으면 우리도 행동으로 보여줄 수밖에.",
          DialogueId = 10105406,
          ExStoryInfo = "Player",
          FacialId = {
