          GUID = "194C40F6",
          NextDialogue = 10105429,
          SpeakNpcId = 200021,
          Subtitle = "If it hadn't been for this monster, their owners might still be chilling at The Asphodel, sipping drinks and swapping stories.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101054/194C40F6"
