          VoiceName = "voice/$Locale$/story/1002/101054/194C4396"
        },
        [10105445] = {
          Camera = "86.544922,-391.478516,183.082031,0.001313,-9.799319,109.31813,35.000008,210.591583,false,DoNotOverride,10.0",
          ContentKR = "그렇게 고상한 게 아니야. 다들 그저 살아남으려고 하다보니 그런 거지. 자, 얼른 가. 이제부터는 나 혼자 하면 돼.",
          DialogueId = 10105445,
          FacialId = {
            [1] = "200061:None"
          },
          FinalCamera = "73.251953,-447.859375,181.362305,0.001316,-9.599339,106.918709,35.000011,210.591583,false,DoNotOverride,10.0",
          GUID = "194C43C0",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          NextDialogue = 10105446,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"200021:p(180)"}},
MoveTo{_delay{0.5},ActorId{200021},TargetPoint{"P101054_AoteMove2"},MoveSpeed{90},Visibility{"Show"}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "I'll be back a bit late. Come find me at my place — it's among those shabby houses south of the city,\nthe one with a little bird drawn on the door.",
          TalkActionId = {
            [1] = "200021:Confident_End",
            [2] = [[

200061:Explain02_End]]
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101054/194C43C0"
        },
        [10105446] = {
          Camera = "227.804688,530.064453,114.802734,0.000015,-1.793635,-114.596718,35.0,803.517822,false,DoNotOverride,4.0",
          ContentKR = "난 좀 늦게 돌아갈 테니 나중에 우리 집으로 와. 우리 집은 시티 남쪽에 있는 낡은 집 중, 문에 작은 새가 그려진 곳이야.",
          DialogueId = 10105446,
          FinalCamera = "227.804688,530.064453,104.378906,0.000015,-1.393611,-114.396393,35.0,803.517822,false,DoNotOverride,4.0",
          GUID = "194C43EA",
          NextDialogue = 10105447,
          Scripts = [[
SEQ{
