          SpeakNpcId = 100001,
          Subtitle = "We got separated and lost touch yesterday... or maybe longer ago. I'm not sure.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101062/194CC292"
        },
        [10106214] = {
