          SpeakNpcId = 100001,
          Subtitle = "I've got what you were looking for, the Crystallo of Stella.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101067/194D12F6"
        },
        [10106705] = {
          ContentKR = "너한테 오라고 한 적 없어. 아스포델에 가서 물건을 카밀라 스칼렛에게 넘겨.",
          DialogueId = 10106705,
          GUID = "194D1320",
          NextDialogue = 10106706,
          SpeakNpcId = 200005,
          Subtitle = "No one asked you to come here. Go to The Asphodel and give it to Camilla Scarlet.",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101067/194D1320"
        },
        [10106706] = {
          Camera = "43.533447,190.366211,124.659058,0.001232,1.999995,-65.366714,15.0,73.0,false,Manual,2.8",
          ContentKR = "난 외지에서 와서 아이스레이크 시티의 규칙은 잘 몰라요. 우리가 있는 곳에선 거래란 돈을 내면 물건을 건네는 거라서요.",
          DialogueId = 10106706,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          FinalCamera = "43.533447,190.366211,132.331177,0.001219,-1.200071,-66.367569,15.000005,73.0,false,Manual,2.8",
          GUID = "194D134A",
          NextDialogue = 10106707,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1.5},ActorId{100001},AnimationId{"DisagreeHead"},Duration{1.8}},
PlayAnimation{ActorId{100001},AnimationId{"Think_Start"},Duration{1}}
