        [10107002] = {
          Camera = "-11.103516,535.533691,150.160156,0.0,-3.999349,-87.40229,35.0,549.519409,false,Manual,4.291738",
          ContentKR = "숙소 일로 온 거지? 일단 조급해하지 말고 여기 잠깐 숨어 있어. 내가 헨릭 아저씨한테 다시 부탁해 볼게. 며칠 더 머물게 허락해 주실 거야.",
