        [10108302] = {
          Camera = "243.050781,-58.478027,50.348633,0.000132,11.999521,161.197205,35.0,321.520721,false,Manual,4.0",
          CameraBlendCurve = "easeOutQuad",
          ContentKR = "좋아, 요 며칠 성장이 꽤 빠른걸. 그래도 아직 멀었어.",
          DialogueId = 10108302,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "241.128906,-63.912598,50.348633,0.000133,12.199516,158.997177,35.0,321.520721,false,Manual,4.0",
          GUID = "194E194C",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10108303,
          SpeakNpcId = 200021,
          Subtitle = "Not bad, you've improved a lot these past few days. Still, there's more to learn.",
          TalkActionId = {
            [1] = "200021:AgreeHead",
            [2] = "100001:Sigh_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101083/194E194C"
        },
        [10108303] = {
          Camera = "3226.708984,-329.703857,-858.430176,-0.0,2.99999,145.59549,15.0,100000.0,false,Disable,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "예를 들면 이런 큰 필토이드는 달리기는 빨라도 몸집이 육중하잖아. 그러니 벽이나 나무줄기 앞에 서서 녀석들을 도발하는 거야. 그 놈들이 돌진해서 너에게 다가왔을 때쯤 네가 옆으로 살짝 비켜서서 자기 혼자 머리를 부딪혀 정신을 못 차리게 하는 거지.",
          DialogueId = 10108303,
          FinalCamera = "3120.359375,-484.996094,-858.430176,-0.0,2.99999,145.59549,15.0,100000.0,false,Disable,2.8",
          GUID = "194E19A0",
          NextOptions = {
            [1] = 10108304,
            [2] = 10108305
          },
          Scripts = "CameraMoveTo{_delay{6},TargetPosition{\"82.828125,-22.881592,132.529785,0.000104,-1.397983,140.189499,35.000008,161.268082,false,Manual,4.0\"},duration{0}}",
          SpeakNpcId = 200021,
          Subtitle = "For example, with that Filthoid just now: it's fast but clumsy, so you can stand in front of some solid surface, like a wall or a tree, and provoke it to charge at you, then dodge its charge to let it knock itself out.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101083/194E19A0",
          bForbidSkipOptions = true
        },
        [10108304] = {
          ContentKR = "음, 괜찮은 방법인걸.",
          DialogueId = 10108304,
          ExStoryInfo = "Player",
          GUID = "10108304",
          ImprPlusId = 1006,
          NextDialogue = 10108306,
          SpeakNpcId = 100001,
          Subtitle = "Hmm, that's a clever tactic."
        },
        [10108305] = {
          ContentKR = "윽... 비겁한 수단이잖아.",
          DialogueId = 10108305,
          ExStoryInfo = "Player",
          GUID = "10108305",
          ImprPlusId = 1007,
          NextDialogue = 10108308,
          SpeakNpcId = 100001,
          Subtitle = "Hmm... that's rather underhanded."
        },
        [10108306] = {
          Camera = "352.355469,-143.926758,113.639648,0.000176,0.800027,154.399246,50.000008,466.962006,false,Manual,8.0",
          CameraBlendCurve = "easeOutQuad",
          ContentKR = "하, 그거야 당연하지. 이건 내가 어릴 때부터 고생하며 익힌 묘수라고. 적을 상대하는 것도 비슷한 원리야. 화가 난 인간은 야수와 별반 다를 것 없어.",
          DialogueId = 10108306,
          FacialId = {
            [1] = "200021:Smile02"
          },
          FinalCamera = "354.804688,-138.704834,113.639648,0.000176,0.80002,155.399689,50.000008,466.962006,false,Manual,8.0",
          GUID = "194E19CA",
          NextDialogue = 10108307,
          SpeakNpcId = 200021,
          Subtitle = "Hah, naturally. It's a trick I picked up growing up tough. It's the same with these enemies — an enraged person isn't much different from a beast.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1002/101083/194E19CA"
        },
        [10108307] = {
          Camera = "1436.363281,-566.314941,420.743164,0.000009,-12.299579,153.401611,20.0,489.882812,false,DoNotOverride,1.2",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "좋아, 이런 것들은 어차피 네 상대가 안 돼. 이제 제대로 된 걸로 가볼까...",
          DialogueId = 10108307,
          FinalCamera = "1506.460938,-601.418945,437.838379,0.000008,-12.299579,153.401855,20.0,489.882812,false,DoNotOverride,1.2",
          GUID = "194E19F4",
          NextDialogue = 10108311,
          SpeakNpcId = 200021,
          Subtitle = "Alright, these random critters were mere appetisers. Now, let's get you a worthy opponent...",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101083/194E19F4"
        },
        [10108308] = {
          Camera = "352.355469,-143.926758,113.639648,0.000176,0.800027,154.399246,50.000008,466.962006,false,Manual,8.0",
          CameraBlendCurve = "easeOutQuad",
          ContentKR = "이건 기본적인 상식이야. 비 오는데 우산 쓴다고 '비겁'하다고 하는 거 봤어?",
          DialogueId = 10108308,
          FinalCamera = "354.804688,-138.704834,113.639648,0.000176,0.80002,155.399689,50.000008,466.962006,false,Manual,8.0",
          GUID = "194E1A1E",
          NextDialogue = 10108309,
          SpeakNpcId = 200021,
          Subtitle = "It's called a life hack. You wouldn't call people using umbrellas in the rain \"underhanded\", would you?",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1A1E"
        },
        [10108309] = {
          Camera = "-32.097656,61.484131,137.130859,0.00022,-3.49942,-43.808128,50.0,142.954285,false,Manual,5.0",
          CameraBlendCurve = "easeOutQuad",
          ContentKR = "네가 말하니까 유난히 비겁하게 들리는 건가...",
          DialogueId = 10108309,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Uninterested01"
          },
          FinalCamera = "-32.097656,61.484131,137.130859,0.00022,-3.49942,-43.808128,52.0,142.954285,false,Manual,5.0",
          GUID = "194E1A48",
          NextDialogue = 10108310,
          SpeakNpcId = 100001,
          Subtitle = "Maybe it just sounds more underhanded because it's coming from you...",
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1A48"
        },
        [10108310] = {
