          NextDialogue = 10108709,
          Scripts = "PlayAnimation{_delay{3.2},ActorId{200002},AnimationId{\"Talk02_Start\"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "Powder... Why would Henrik bother to put a box of powder in the water? That's so strange.",
