        },
        [10109011] = {
          Camera = "27.23291,-17.217773,150.117188,0.000137,-1.001114,-142.583847,20.0,150.644867,false,Manual,1.449662",
          ContentKR = "그냥 때려 맞춘 거야. 너 반응이 너무 심각하니까. 고민하던 것도 다 내팽개치고 말이야. 그 사람이 너한테 꽤나 중요했나 보네?",
          DialogueId = 10109011,
          GUID = "194E8D74",
          NextDialogue = 10109012,
          SpeakNpcId = 200021,
          Subtitle = "I can see it. When it comes to things you truly care about, you toss all caution and reservations to the wind.",
          TalkActionId = {
            [1] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101090/194E8D74"
        },
        [10109012] = {
          Camera = "-443.760742,1671.63916,3315.651855,0.000195,-7.202202,93.220032,10.0,150.644867,false,DoNotOverride,1.449662",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "낯선 곳에 홀로 떨어졌을 때 느끼는 그 기분 알지? 공처럼 이리저리 차이는 듯한 느낌. 그런데 그때 누군가 손을 내밀며 살아있으면 좋은 일이 생길 거라고 말해준다면.",
          DialogueId = 10109012,
          ExStoryInfo = "Player",
          FacialId = {
