        },
        [10109411] = {
          ContentKR = "응.",
          DialogueId = 10109411,
          GUID = "10109411"
        },
        [10109501] = {
          ContentKR = "눈물의 호수를 가고 싶어. 그 주변에 오래된 나무 뿌리도 있는데, 어릴 때 아빠가 날 거기 데려갔었거든.",
          DialogueId = 10109501,
          GUID = "194EDE02",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10109502,
          SpeakNpcId = 200006,
          Subtitle = "It's a cave... My dad once took me there when I was little.",
          VoiceName = "voice/$Locale$/story/1002/101095/194EDE02"
        },
        [10109502] = {
          ContentKR = "...벌써 몇 년이나 지난 일이지만...",
          DialogueId = 10109502,
          GUID = "194EDE2C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...It's been so long...",
          VoiceName = "voice/$Locale$/story/1002/101095/194EDE2C"
        },
        [10109601] = {
          ContentKR = "도착했어.",
          DialogueId = 10109601,
          ExStoryInfo = "Player",
          GUID = "194EEE6A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10109602,
          SpeakNpcId = 100001,
          Subtitle = "We've arrived.",
          VoiceName = "voice/$Locale$/story/1002/101096/194EEE6A"
        },
        [10109602] = {
          ContentKR = "나무 뿌리... 주위에 작은 상자가 묻혀 있을 거야. {nickname}, 그걸 찾아줄 수 있을까?",
          DialogueId = 10109602,
          ExStoryInfo = "Player",
          GUID = "194EEEBE",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "There should be a small box buried under that tree.",
          VoiceName = "voice/$Locale$/story/1002/101096/194EEEBE"
        },
        [10109701] = {
          Camera = "-190.949219,140.849609,112.655273,0.000004,-12.601363,-7.686144,50.0,234.678116,false,Manual,8.0",
          DialogueId = 10109701,
          DialoguePanelType = "None",
