          FinalCamera = "207.707031,-186.716797,8.631836,-3.000001,7.397299,129.297287,35.0,479.576324,false,Manual,3.0",
          GUID = "194F00CA",
          SpeakNpcId = 200006,
          Subtitle = "Since we're already here, how about a little stroll around the lake?",
          TalkActionId = {
            [1] = "200006:Talk02_Start"
          },
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1002/101097/194F00CA"
        },
        [10109801] = {
          ContentKR = "어릴 때 종종 아빠와 함께 호숫가를 산책하고는 했어.",
          DialogueId = 10109801,
          GUID = "194F0F3A",
          NextDialogue = 10109802,
          SpeakNpcId = 200006,
          Subtitle = "When I was little, Dad would sometimes bring me here for walks.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F0F3A"
        },
        [10109802] = {
          ContentKR = "가끔은 필토이드와 숨바꼭질을 해야 했지만, 그래도 항상 여기 오길 바랐어.",
          DialogueId = 10109802,
          GUID = "194F0F64",
          NextDialogue = 10109803,
          SpeakNpcId = 200006,
          Subtitle = "Despite the occasional hide-and-seek with the Filthoids, I always looked forward to coming here.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F0F64"
        },
        [10109803] = {
          ContentKR = "이곳의 빙하와 산봉우리를 좋아하거든, 거기에 열차가 씽씽 달리며 지나가는 걸 보는 것도 좋았어.",
          DialogueId = 10109803,
          GUID = "194F0F8E",
          NextDialogue = 10109804,
          SpeakNpcId = 200006,
          Subtitle = "Because I loved the floating ice and mountains here, and more so, I loved watching the trains roar by.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F0F8E"
        }
      }
    end
