        },
        [10110206] = {
          Camera = "74.595703,85.75,141.061523,0.000114,1.99839,-111.626167,35.0,100000.0,false,Disable,2.8",
          ContentKR = "잠깐만, 잠깐만! 지갑 돌려줄게! 나도 며칠째 굶어서 정신이 나가서 그랬던 거야... 아, 내가 잘못했어!",
          DialogueId = 10110206,
          GUID = "194F51AC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110206.T_Story_Recall_10110206'",
          NextDialogue = 10110207,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          Subtitle = "Tsk... If I hadn't been starved all day, I'd never have touched this bloody thing, let alone lost to you!",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101032/194AD496"
        },
        [10110207] = {
          Camera = "49.960938,32.921875,126.546875,0.000111,8.397717,119.570648,35.0,362.075562,false,Manual,22.0",
          ContentKR = "그 사람을 죽였다고요? 죄를 짓기는 했지만... 죽을 정도는 아니었지 않나요?",
          DialogueId = 10110207,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unacceptable01"
          },
          GUID = "194F51D6",
          LookAt = {
            [1] = "100001:n(200004)"
          },
          NextDialogue = 10110208,
          Scripts = "CameraMoveTo{_delay{1.5},TargetPosition{\"53.412109,-207.308594,178.919922,0.000045,-11.599839,106.600044,35.000008,338.707367,false,Manual,4.0\"},duration{0}},",
          SpeakNpcId = 100001,
          Subtitle = "...He may be a thief, but he doesn't deserve to be killed for this!",
          TalkActionId = {
            [1] = "100001:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F51D6"
        },
        [10110208] = {
          Camera = "2442.902344,1375.00293,-15.568359,0.000018,1.799891,-157.005646,50.0,546.458801,false,Manual,1.2",
          ContentKR = "조용히 해! 내가 한 게 아니라니까, 난 그냥 시신을 몰래 옮기는 것뿐이야.",
          DialogueId = 10110208,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "2446.085938,1367.493164,-15.568359,0.000015,1.799891,-157.005661,50.0,2902.307617,false,Manual,4.0",
          GUID = "194F5200",
          NextDialogue = 10110209,
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          Subtitle = "Keep it down! I told you, it wasn't me. I was just trying to sneak the body out.",
          TalkActionId = {
            [1] = "200004:Talk01_Start",
            [2] = "100001:Angry01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5200"
        },
        [10110209] = {
          ContentKR = "난 케빈이라고 해. 전에 본 적 있지? 아이스레이크 시티 외곽 방위대... 이 재수 없는 놈은 하알인데 내 이웃이었어. 어릴 때부터 알던 사이지.",
          DialogueId = 10110209,
          GUID = "194F522A",
          NextDialogue = 10110210,
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          Subtitle = "My name's Kevin. We've met before — I'm in the outskirts escort... And this poor soul here is Hal, my old neighbour. We've known each other since we were kids.",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F522A"
        },
        [10110210] = {
          Camera = "155.150391,89.697266,40.088867,0.000099,0.594261,-127.181572,25.0,379.426514,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "이 녀석은 어머니가 일찍 돌아가셨어. 어려서부터 밥 먹듯이 싸우고 자랐어. 가족들은 내가 카론과 어울리지 못하게 했지만 그래도 같이 놀고 자라서 종종 도와주던 사이야...",
          DialogueId = 10110210,
          FinalCamera = "155.150391,89.697266,40.088867,0.000105,18.793825,-127.379799,25.0,379.426514,false,Manual,22.0",
          GUID = "194F5254",
          NextDialogue = 10110211,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.2},TargetPosition{"108.958984,10.623047,103.797852,0.000065,16.595993,-129.197327,35.0,379.426514,false,Manual,22.0"},duration{0}},
PlayAnimation{_delay{2},ActorId{200004},AnimationId{"Talk01_Start"},Duration{2}},
SEQ{
LookAt{LookAtDescription{"200004:p(P101102Bag)"}},
LookAt{_delay{2},LookAtDescription{"200004:n(100001)"}}
}
}]],
          SpeakNpcId = 200004,
          Subtitle = "He lost his mother at an early age and had been getting into countless brawls ever since. My family doesn't allow me to interact with Charons, but he was an old friend from when I was a kid, so I'd sometimes help him out...",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5254"
        },
        [10110211] = {
          Camera = "189.996094,-133.302734,149.913086,0.000003,1.39997,178.999893,35.0,180.0,false,Manual,4.146463",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "그런데 어느 날 녀석이 몰래 날 찾아왔어. 난 또 녀석이 빚을 졌거나 술주정뱅이 아버지한테 얻어맞아서 하소연하러 온 줄 알았지. 그런데 나한테 그러더군, 자신한테 '<W>침식</>' 징조가 나타났다고...",
          DialogueId = 10110211,
          FinalCamera = "190.324219,-114.291016,149.913086,0.000003,1.39997,178.999893,35.0,180.0,false,Manual,4.146463",
          GUID = "194F527E",
          LookAt = {
            [1] = "200004:n(100001)"
          },
          NextDialogue = 10110212,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.1},TargetPosition{"204.705078,100.296875,134.578125,0.0,0.0,-179.999954,35.0,180.0,false,Manual,4.146463"},duration{0}},
CameraMoveTo{_delay{4.2},TargetPosition{"204.707031,113.621094,134.578125,0.0,-0.200008,-179.399948,35.0,180.0,false,Manual,4.146463"},blend{"easeOutQuad"},duration{4}},
SEQ{
PlayAnimation{_delay{0.1},ActorId{200004},AnimationId{"Talk01_End"},Duration{1}}
}
}]],
          SpeakNpcId = 200004,
          Subtitle = "One day, he came to me, acting all weird. I thought he'd racked up debts again, or that he came to moan about being hit again by his drunkard dad. But to my surprise, he said he was showing signs of Deterioration...",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101102/194F527E"
        },
        [10110212] = {
          Camera = "32.447266,-94.166016,150.726562,0.000106,-6.001796,98.975403,35.000011,165.117889,false,Manual,4.0",
          CameraBlendCurve = "easeOutQuad",
          ContentKR = "대체 '침식'이 뭔데요?",
          DialogueId = 10110212,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "27.117188,-60.277344,147.863281,0.000109,-4.801753,98.975227,35.000008,165.117889,false,Manual,4.0",
          GUID = "194F52A8",
          NextDialogue = 10110213,
          SpeakNpcId = 100001,
          Subtitle = "What exactly is \"Deterioration\"?",
          TalkActionId = {
            [1] = "100001:Angry01_Start"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1002/101102/194F52A8"
        },
        [10110213] = {
          Camera = "65.837891,244.282227,142.673828,0.000056,-1.002317,-107.63298,35.000011,311.117737,false,Manual,4.0",
          ContentKR = "카론이 '침식'을 모른다고? 너 제국인이 맞긴 해?",
          DialogueId = 10110213,
          GUID = "194F52D2",
          NextOptions = {
            [1] = 10110214,
            [2] = 10110216
          },
          SpeakNpcId = 200004,
          Subtitle = "As a Charon, you don't know about Deterioration? Are you really a native?",
          TalkActionId = {
            [1] = "200004:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F52D2"
        },
        [10110214] = {
          ContentKR = "전 외딴 시골에서 와서 세상물정을 잘 몰라서요...",
          DialogueId = 10110214,
          GUID = "10110214",
          ImprPlusId = 1007,
          NextDialogue = 10110215
        },
        [10110215] = {
          Camera = "65.837891,244.282227,142.673828,0.000056,-1.002317,-107.63298,35.000011,311.117737,false,Manual,4.0",
          ContentKR = "아참, 카밀라가 그랬었지. 그래, 어쩐지.",
          DialogueId = 10110215,
          GUID = "194F52FC",
          NextDialogue = 10110218,
          SpeakNpcId = 200004,
          Subtitle = "Ah right, Camilla did mention something about that. Makes sense then.",
          TalkActionId = {
            [1] = "200004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F52FC"
        },
        [10110216] = {
          ContentKR = "계속 물으면 오늘 일을...",
          DialogueId = 10110216,
          ExStoryInfo = "Player",
          GUID = "10110216",
          ImprPlusId = 1010,
          NextDialogue = 10110217
        },
        [10110217] = {
          Camera = "65.837891,244.282227,142.673828,0.000056,-1.002317,-107.63298,35.000011,311.117737,false,Manual,4.0",
          ContentKR = "아, 알았어. 안 물어볼게. 절대 말하지 마!",
          DialogueId = 10110217,
          FacialId = {
            [1] = "200004:Sad01"
          },
          GUID = "194F5326",
          NextDialogue = 10110218,
          SpeakNpcId = 200004,
          Subtitle = "Alright, alright! I won't ask any more questions! Please don't tell anyone!",
          VoiceName = "voice/$Locale$/story/1002/101102/194F5326"
        },
        [10110218] = {
          Camera = "774.716797,904.916992,888.727539,0.000136,-34.801495,-130.630646,35.0,100000.0,false,Disable,2.8",
          ContentKR = "<W>침식</>은 카론 몸에만 나타나는 특수한 질병이야. 고칠 방법도 없어.",
          DialogueId = 10110218,
          FinalCamera = "819.070312,866.855469,888.727539,0.000136,-34.801495,-130.630646,35.0,100000.0,false,Disable,2.8",
          GUID = "194F5350",
          NextDialogue = 10110219,
          SpeakNpcId = 200004,
          Subtitle = "So Deterioration is a peculiar disease that only Charons might suffer from. Once you've got it, there's no cure.",
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5350"
        },
        [10110219] = {
          Camera = "59.294922,60.157227,158.963867,0.000116,-1.401753,-106.029457,35.0,179.344406,false,Manual,2.8",
          ContentKR = "너처럼 20살이 되기 몇 년 전, 어떤 힘을 각성하게 되지만, 모두 순조롭게 각성하는 건 아니야.",
          DialogueId = 10110219,
          FinalCamera = "54.453125,61.650391,158.963867,0.000116,-1.201751,-105.029655,35.0,179.344406,false,Manual,2.8",
          GUID = "194F537A",
          NextDialogue = 10110220,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.1},TargetPosition{"14.539062,-57.106445,149.019531,0.000111,-4.801684,98.370773,35.0,179.344406,false,Manual,2.8"},duration{0}},
CameraMoveTo{_delay{4.2},TargetPosition{"24.572266,-55.670898,149.019531,0.00011,-5.001706,97.770851,35.0,179.344406,false,Manual,2.8"},duration{4}}
}]],
          SpeakNpcId = 200004,
          Subtitle = "You folks usually awaken some kind of power around your teens, but not everyone's that lucky.",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101102/194F537A"
        },
        [10110220] = {
          ContentKR = "운이 더럽게 나쁜 녀석들은 항상 있으니까, 그런 녀석들은 <W>필토이드</>로 변하기도 해. 하지만 그 위력은 엄청나서 일반 필토이드와는 비교도 안 될 정도야. 방위대 한 소대가 나서도 제압에 성공할지 미지수거든.",
          DialogueId = 10110220,
          GUID = "194F53A4",
          NextDialogue = 10110221,
          RelatedWikiId = {
            [1] = 303003
          },
          SpeakNpcId = 200004,
          Subtitle = "There are always a few poor wretches who somehow get it wrong and turn into Filthoids — but way stronger than the regular Filthoids out there; a whole escort might not even be able to take one down.",
          VoiceName = "voice/$Locale$/story/1002/101102/194F53A4"
        },
        [10110221] = {
          Camera = "582.199219,778.926758,7556.786133,0.000033,22.586451,-62.627708,15.000007,179.344406,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "시티 내에 침식자가 나타나면, 그 주변 사람들은 알아서 살길을 도모해야 할 거야.",
          DialogueId = 10110221,
          FinalCamera = "731.279297,485.125,7697.886719,0.000031,23.186407,-63.027958,15.000007,179.344406,false,DoNotOverride,22.0",
          GUID = "194F53CE",
          NextDialogue = 10110222,
          SpeakNpcId = 200004,
          Subtitle = "If a Deteriorator appears in the city... the entire neighbourhood is doomed.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F53CE"
        },
        [10110222] = {
          Camera = "3.785156,91.553711,146.086914,0.000137,1.597711,-88.227295,35.000008,234.413483,false,Manual,4.0",
          ContentKR = "이제 왜 그렇게 많은 솔라들이 카론을 미워하는지 알겠지? 모두 카론의 몸에 흐르는 사악한 마력이 이런 재앙을 불러온다고 믿거든. 그리고 침식자란, 카론 중에서도 가장 사악한 존재야.",
          DialogueId = 10110222,
          FacialId = {
            [1] = "200004:None"
          },
          GUID = "194F53F8",
          NextDialogue = 10110223,
          Scripts = "PlayAnimation{_delay{1},ActorId{200004},AnimationId{\"Talk01_Start\"},Duration{1}}",
          SpeakNpcId = 200004,
          Subtitle = "Now you get why so many people hate Charons, right? Everyone says it's the evil magic coursing through Charon veins that brings such disaster. The Deteriorators are considered the most evil among all Charons.",
          TalkActionId = {
            [1] = "200004:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F53F8"
        },
        [10110223] = {
          Camera = "3.785156,91.553711,146.086914,0.000137,1.597711,-88.227295,35.000008,234.413483,false,Manual,4.0",
          ContentKR = "솔직히 말하자면 나도 다 믿는 건 아니야... 아! 어쨌든 이런 일이 왜 하알한테 일어난 건지.",
          DialogueId = 10110223,
          GUID = "194F5422",
          NextDialogue = 10110224,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"200004:p(P101102Bag)"}},
PlayAnimation{ActorId{200004},AnimationId{"Disagree"},Duration{2}},
LookAt{_delay{2},LookAtDescription{"200004:n(100001)"}}
}]],
          SpeakNpcId = 200004,
          Subtitle = "Honestly, I'm not entirely sold on this, but... sigh! How come such a rare thing had to happen to Hal?",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5422"
        },
        [10110224] = {
          Camera = "59.203125,-199.486328,172.362305,0.000048,-11.20041,106.99884,35.000008,100000.0,false,Disable,4.0",
          ContentKR = "보름 전쯤, 녀석이 급하게 날 찾아왔는데 내가 뭘 어떻게 하겠어! 침식자를 비호하는 건 포세이큰 동맹을 비호하는 것과 같은 중죄야. 까딱하면 목숨을 잃는다고. 내가 할 수 있는 건 먹을 걸 좀 주고 혼자 방법을 생각하도록 하는 게 다였어.",
          DialogueId = 10110224,
          GUID = "194F544C",
          NextDialogue = 10110225,
          Scripts = "CameraMoveTo{_delay{11},TargetPosition{\"74.595703,85.75,141.061523,0.000114,1.99839,-111.626167,35.0,100000.0,false,Disable,2.8\"},duration{0}}",
          SpeakNpcId = 200004,
          Subtitle = "About two weeks ago, he came to me all in a flap, but what could I do? Harbouring a Deteriorator is as severe as sheltering a member of the Forsakens — one wrong move could cost you your life. All I could do was give him some food and tell him to sort himself out.",
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F544C"
        },
        [10110225] = {
          Camera = "81.287109,-34.47168,231.873047,0.000089,-31.399204,-132.789673,35.000008,100000.0,false,Disable,4.0",
          ContentKR = "나중에 녀석이 남의 돈을 훔치다가 현행범으로 잡혔다는 말을 들었어. 게다가 침식자인 걸 걸려서 그대로 치안서로 보내졌다고 하더군.",
          DialogueId = 10110225,
          GUID = "194F5476",
          NextOptions = {
            [1] = 10110226
          },
          SpeakNpcId = 200004,
          Subtitle = "Later I heard he got nabbed for stealing and was found to be a Deteriorator. They took him straight to the Security Bureau.",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5476"
        },
        [10110226] = {
          ContentKR = "치안서로 보내진 후 무슨 일이 있었나요?",
          DialogueId = 10110226,
          ExStoryInfo = "Player",
          GUID = "194F5477",
          NextDialogue = 10110227
        },
        [10110227] = {
          Camera = "777.373047,-100.292969,25.057617,0.000009,4.599859,172.998215,40.000011,332.596619,false,Manual,22.0",
          ContentKR = "침식자는 약도 없다고 하는데 또 무슨 일이 있겠어? 당연히 우리 방위대에 넘어왔고, 그 후에는... 하아.",
          DialogueId = 10110227,
          GUID = "194F54A0",
          NextDialogue = 10110228,
          SpeakNpcId = 200004,
          Subtitle = "Like I said, there's no cure for Deteriorators. What else could happen? They get handed over to the Escort, and then... well, you know.",
          TalkActionId = {
            [1] = "200004:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F54A0"
        },
        [10110228] = {
          Camera = "-30.980469,-249.970703,249.849609,0.000058,-40.098839,61.201523,20.000011,207.029022,false,Manual,3.5",
          ContentKR = "자업자득이긴 하지만... 그래도 친구로 지낸 세월이 얼만데, 차마 차가운 시체를 안치소에다 둘 순 없어서 몰래... 데리고 나와서 녀석 어머니가 묻힌 눈물의 호수 쪽에 묻어주려던 거야.",
          DialogueId = 10110228,
          FinalCamera = "-23.003906,-235.451172,235.890625,0.000058,-40.098839,61.201523,20.000011,207.029022,false,Manual,3.5",
          GUID = "194F54CA",
          NextDialogue = 10110229,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"200004:p(P101102Bag)"}},
SetLocation{ActorId{100001},TargetPoint{"P101102Nvzhu2"},Visibility{"Show"}}
}]],
          SpeakNpcId = 200004,
          Subtitle = "Although he pretty much had it coming... But still, we were friends for a few years. I couldn't bear the thought of him lying in a cold morgue, so I sneaked him out... I was gonna bury him by Lamenting Lake, right next to his mother.",
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "200004:p(-110)"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F54CA"
        },
        [10110229] = {
          Camera = "34.142578,-193.462891,170.493164,0.000065,-9.900208,102.009438,40.000011,278.887787,false,Manual,3.0",
          ContentKR = "잠깐만요, 궁금한 게 있어요... 침식 징후가 나타나고 침식이 발병할 때까지... 그사이에 어떤 증상이 있나요?",
          DialogueId = 10110229,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "194F54F4",
          NextDialogue = 10110230,
          Scripts = [[
PARA{
LookAt{_delay{1},LookAtDescription{"200004:n(100001)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Hold on, I'm curious — what symptoms would appear between the onset of Deterioration and its full development?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F54F4"
        },
        [10110230] = {
          Camera = "29.394531,154.411133,135.935547,0.000082,4.298655,-102.209503,40.000011,300.548492,false,Manual,4.0",
          ContentKR = "내가 어떻게 알아? 아, 광적으로 초조하게 변한다든가, 정상적인 감각을 잃는다고 들었어. 눈이 멀거나 귀가 안 들리는 거지.",
          DialogueId = 10110230,
          FacialId = {
            [1] = "200004:Sad01"
          },
          GUID = "194F551E",
          NextDialogue = 10110231,
          RelatedWikiId = {
            [1] = 303006
          },
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"200004:n(100001)"}},
PlayAnimation{_delay{1.5},ActorId{200004},AnimationId{"Think_Start"},Duration{1}},
PlayAnimation{_delay{5},ActorId{200004},AnimationId{"Think_End"},Duration{1}},
}]],
          SpeakNpcId = 200004,
          Subtitle = "How should I know? Oh, but I've heard that some would turn extremely violent, and some poor souls would gradually lose their senses, like going blind or deaf or something, perhaps.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F551E"
        },
        [10110231] = {
          ContentKR = "나도 그냥 들은 것뿐이야. 궁금하면 의사를 찾아가 물어봐. 그런데 넌 이미 각성에 성공한 것 같은데, 뭘 그런 걸 걱정해.",
          DialogueId = 10110231,
          FacialId = {
            [1] = "200004:None"
          },
          GUID = "194F5548",
          NextDialogue = 10110232,
          Scripts = "PlayAnimation{_delay{3},ActorId{200004},AnimationId{\"Talk01_Start\"},Duration{2}}\n",
          SpeakNpcId = 200004,
          Subtitle = "This is all just hearsay though. If you're curious about it, better ask a doctor. But it seems to me you've already awakened successfully, why do you care?",
          VoiceName = "voice/$Locale$/story/1002/101102/194F5548"
        },
        [10110232] = {
          Camera = "71.007812,-49.522461,222.453125,0.000127,-26.599911,112.772514,37.500008,159.011261,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "...",
          DialogueId = 10110232,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unacceptable01"
          },
          FinalCamera = "60.40625,-24.273438,208.739258,0.000127,-26.599911,112.772514,37.500008,159.011261,false,Manual,22.0",
          GUID = "194F5572",
          NextDialogue = 10110233,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200004:Talk01_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5572"
        },
        [10110233] = {
          ContentKR = "응! 방금 좀 어지러워서 계단을 못 봤어. 고마워.",
          DialogueId = 10110233,
          GUID = "194F559C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110233.T_Story_Recall_10110233'",
          NextDialogue = 10110234,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 200006,
          Subtitle = "Uh! I got a little dizzy and didn't see the step, thank you.",
          VoiceName = "voice/$Locale$/story/1002/101013/19499D06"
        },
        [10110234] = {
          ContentKR = "방금 갑자기 앞이 잘 안보여서 필토이드를 놀라게 해 버렸네... 정말 미안해!",
          DialogueId = 10110234,
          GUID = "10110234.0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110234.T_Story_Recall_10110234'",
          NextDialogue = 10110235,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 200006,
          Subtitle = "I suddenly couldn't see clearly back there and ended up startling that monster... I'm so sorry!",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEBA6"
        },
        [10110235] = {
          ContentKR = "눈이... 언제부터 잘 안 보인 거야?",
          DialogueId = 10110235,
          ExStoryInfo = "Player",
          GUID = "10110235.0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110235.T_Story_Recall_10110235'",
          NextDialogue = 10110236,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 100001,
          Subtitle = "Your eyes... When did you lose your sight?",
          VoiceName = "voice/$Locale$/story/1002/101094/194ECE42"
        },
        [10110236] = {
          ContentKR = "언제부터였더라...",
          DialogueId = 10110236,
          GUID = "10110236.0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110236.T_Story_Recall_10110236'",
          NextDialogue = 10110237,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 200006,
          Subtitle = "When was it...",
          VoiceName = "voice/$Locale$/story/1002/101094/194ECE6C"
        },
        [10110237] = {
          Camera = "19.232422,44.570312,117.50293,0.000166,18.198389,104.808296,35.000008,162.592728,false,Manual,22.0",
          CameraBlendCurve = "easeOutQuad",
          ContentKR = "(...설마 프시케의 눈도 '침식' 증상일까... 설마 히프노스의 집 모든 '투숙객'이 전부 침식자라고?)",
          DialogueId = 10110237,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          FinalCamera = "29.253906,6.640625,104.633789,0.000168,17.198368,104.608376,35.000008,162.592728,false,Manual,22.0",
          GUID = "194F5644",
          NextDialogue = 10110238,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...Could Psyche's sight loss be a symptom of Deterioration... Could all the \"lodgers\" at the Hypnos' House be Deteriorators?)",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5644"
        },
        [10110238] = {
          Camera = "37.144531,202.914062,126.870117,0.000128,3.900086,-105.196716,40.0,278.887787,false,Manual,3.0",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "병사님, 제가 뭔가 여쭤볼 건데 솔직하게 대답해 주세요. 이 사진기 보이시죠? 솔직하게 말하지 않으시면 치안서에 넘길지도 몰라요. 그곳에 계신 분이 참 좋아하시겠네요.",
          DialogueId = 10110238,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "50.792969,198.213867,126.870117,0.000126,3.900086,-107.797836,40.0,278.887787,false,Manual,3.0",
          GUID = "194F566E",
          NextDialogue = 10110239,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.1},TargetPosition{"72.476562,-210.320312,168.837891,0.000193,-9.201282,108.579414,35.000008,371.235565,false,Manual,3.0"},duration{0}},
CameraMoveTo{_delay{4.2},TargetPosition{"59.669922,-214.0625,168.837891,0.000192,-9.801321,105.5793,35.000008,371.235565,false,Manual,3.0"},blend{"easeOutQuad"},duration{4}},
PlayAnimation{_delay{4.2},ActorId{100001},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Sir, I'd like to inquire about someone, and I hope you'll be frank and supportive. See this camera? If you refuse, I might just hand it over to the Security Bureau — they'd surely be interested.",
          TalkActionId = {
            [1] = "100001:Shock_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101102/194F566E"
        },
        [10110239] = {
          Camera = "75.552734,-84.876953,197.44043,0.000166,-23.601746,-165.823135,35.000008,239.561539,false,Manual,22.0",
          ContentKR = "맙소사, 좀 봐줘. 네가 무슨 군단 기밀을 묻는다 해도 나 같은 병사는 몰라. 난 그냥 문지기라고!",
          DialogueId = 10110239,
          FacialId = {
            [1] = "200004:Sad01"
          },
          FinalCamera = "78.841797,-97.880859,197.44043,0.000168,-18.601685,-166.822098,35.000011,239.561539,false,Manual,22.0",
          GUID = "194F5698",
          NextDialogue = 10110240,
          SpeakNpcId = 200004,
          Subtitle = "Good grief! Cut me some slack... If you're digging for some military secrets, you don't need to corner a mere foot soldier like me — I'm basically just a gatekeeper!",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5698"
        },
        [10110240] = {
          Camera = "24.123047,-69.332031,126.121094,0.000172,2.398667,98.17495,35.000011,177.910553,false,Manual,4.0",
          ContentKR = "시티 북쪽의 '히프노스의 집' 주인 헨릭 애설레드가 뭘 하는지 아세요? 저한테 전부 사실대로 알려주세요.",
          DialogueId = 10110240,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194F56C2",
          NextDialogue = 10110241,
          SpeakNpcId = 100001,
          Subtitle = "Do you know anything about Henrik Ethelred, the owner of the Hypnos' House in the north of the city? I mean ANYTHING, and I'd like to hear them all, sir.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F56C2"
        },
        [10110241] = {
          Camera = "121.794922,416.958008,140.132812,0.000136,-2.801443,-106.219742,35.000008,100000.0,false,Disable,2.8",
          ContentKR = "헨릭 애설레드라... 여관 주인 아니야? 아, 생각해 보니 내 상관 중에도 친하신 분이 계셔. 그 사람... 전과가 있긴 해도 최근 몇 년간 성실하게 지냈어. 아무 일도 없었지.",
          DialogueId = 10110241,
          FacialId = {
            [1] = "200004:None"
          },
          FinalCamera = "182.132812,391.785156,140.132812,0.00013,-3.201432,-116.019501,35.000008,100000.0,false,Disable,2.8",
          GUID = "194F56EC",
          NextDialogue = 10110242,
          Scripts = "PlayAnimation{_delay{1},ActorId{200004},AnimationId{\"Think_Start\"},Duration{2}}\n",
          SpeakNpcId = 200004,
          Subtitle = "Henrik Ethelred... isn't he just an inn owner? Oh, my superior does have some connection with him. He's got a bit of a history, but has been a law-abiding citizen these past years.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F56EC"
        },
        [10110242] = {
          Camera = "182.132812,391.785156,140.132812,0.00013,-3.201432,-116.019501,35.000008,100000.0,false,Disable,2.8",
          ContentKR = "아, 그 녀석 성질이 더러워서 투숙하러 온 외지인을 쫓아낸 적이 한두 번이 아니야. 하지만 그 전에 본업을 할 때는 성질은 고약해도, 그래도 식구들은 잘 돌봤다고 들었어.",
          DialogueId = 10110242,
          GUID = "194F5716",
          NextDialogue = 10110261,
          SpeakNpcId = 200004,
          Subtitle = "Oh, that man's got quite the temper, not a rare occasion he's shut the door on travellers. But that's just how he is — even back in his proper job days, he wasn't a nice guy either, though at least back then he had his family to keep him in check.",
          TalkActionId = {
            [1] = "200004:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5716"
        },
        [10110243] = {
          ContentKR = "'전과'라고요?",
          DialogueId = 10110243,
          GUID = "10110243",
          NextDialogue = 10110246
        },
        [10110244] = {
          ContentKR = "'본업'이요?",
          DialogueId = 10110244,
          GUID = "10110244.0",
          NextDialogue = 10110251
        },
        [10110245] = {
          ContentKR = "'그의 가족'은요?",
          DialogueId = 10110245,
          GUID = "10110245.0",
          NextDialogue = 10110254
        },
        [10110246] = {
          Camera = "182.132812,391.785156,140.132812,0.00013,-3.201432,-116.019501,35.000008,100000.0,false,Disable,2.8",
          ContentKR = "그게... 어디 보자, 한 10년 전이었나? 대략 15년쯤 전에 헨릭 애설레드가 플래그슨 주에 있는 <H>스칼렛</>에서 살인을 저질렀어.",
          DialogueId = 10110246,
          GUID = "194F5740",
          NextDialogue = 10110247,
          RelatedWikiId = {
            [1] = 408006
          },
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}}",
          SpeakNpcId = 200004,
          Subtitle = "Well, it was... what, some fourteen, fifteen years ago? Henrik Ethelred committed a murder up in Scarletriver, Flagson.",
          TalkActionId = {
            [1] = "200004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5740"
        },
        [10110247] = {
          Camera = "48.828125,-238.466797,197.088867,0.000132,-14.601796,105.386505,35.000008,394.862823,false,Manual,4.0",
          ContentKR = "피해자는 카론이었어. 아, 그래, <W>침식자</> 징후가 나타난 카론이었지. 우리가 방금 말한 것처럼 말이야. 그런데 그건 무슨 중죄가 아니어서, 몇 개월 감옥살이하고 풀려났어.",
          DialogueId = 10110247,
          GUID = "194F576A",
          NextDialogue = 10110248,
          SpeakNpcId = 200004,
          Subtitle = "The victim was a Charon, one with signs of Deterioration — like I just said. Not a major crime though, so he only served a few months before getting released.",
          TalkActionId = {
            [1] = "200004:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F576A"
        },
        [10110248] = {
          Camera = "11.783203,35.181641,158.039062,0.000169,-12.8009,95.373573,35.000008,83.272263,false,Manual,5.0",
          ContentKR = "왜 그런 거죠?",
          DialogueId = 10110248,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Angry01"
          },
          GUID = "194F5794",
          NextDialogue = 10110249,
          SpeakNpcId = 100001,
          Subtitle = "Why would he do that?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5794"
        },
        [10110249] = {
          Camera = "781.091797,122.442383,14.25293,0.00013,1.998233,-169.017654,25.0,182.242599,false,Manual,22",
          ContentKR = "...모르지, 하지만 인간이라면 침식자를 두려워하고 증오하는 게 이상할 건 없잖아?",
          DialogueId = 10110249,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "781.091797,122.442383,33.219727,0.00013,0.0,-169.01709,25.0,182.242599,false,Manual,22",
          GUID = "194F57BE",
          NextDialogue = 10110250,
          SpeakNpcId = 200004,
          Subtitle = "...I don't know. But any Mortalan would fear and despise a Deteriorator, I guess.",
          TalkActionId = {
            [1] = "200004:Disagree",
            [2] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F57BE"
        },
        [10110250] = {
          Camera = "31.501953,148.584961,134.270508,0.000126,2.597808,-102.621628,35.000008,314.487457,false,Manual,4.0",
          ContentKR = "이 일은 나도 상사한테 들은 거야. 어쨌든 이미 몇 년이나 지난 일인데, 여기서 일어난 일도 아니라서 아이스레이크 시티에는 아는 사람이 몇 없어. 내가 잘못 말했다고 해도 내 탓은 하지 마!",
          DialogueId = 10110250,
          GUID = "194F57E8",
          NextDialogue = 10110261,
          Scripts = "PlayAnimation{_delay{4},ActorId{200004},AnimationId{\"Talk01_End\"},Duration{1}}",
          SpeakNpcId = 200004,
          Subtitle = "I just heard this from my superior. It's been a long time and it didn't happen locally, so don't hold it against me if I've got some details wrong!",
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F57E8"
        },
        [10110251] = {
          Camera = "31.501953,148.584961,134.270508,0.000126,2.597808,-102.621628,35.000008,314.487457,false,Manual,4.0",
          ContentKR = "아이스레이크 시티에서 나이 좀 먹은 사람들은 헨릭이 예전에 이곳에서 유명한 <H>의사</>였다는 걸 다 알아. 아주 뛰어나서 대단하다는 귀족 나리들도 진료받으러 왔거든.",
          DialogueId = 10110251,
          GUID = "194F5812",
          NextDialogue = 10110252,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}}",
          SpeakNpcId = 200004,
          Subtitle = "The older folks in Icelake all know that Henrik was once a renowned doctor. Quite the skilled medic, he was, even the nobles from the inner city would go to him.",
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5812"
        },
        [10110252] = {
          Camera = "327.693359,662.063477,356.859375,0.000096,-19.999989,-112.616272,35.0,100000.0,false,Disable,2.8",
          ContentKR = "하지만 그 후 무슨 일인지 가장 명성이 자자할 때 병원 문을 닫았어. 2년이 지나 병원 문을 다시 열긴 했지만 간판이\n'여관'으로 바뀌어 있었지.",
          DialogueId = 10110252,
          FinalCamera = "350.828125,717.59375,368.043945,0.000096,-19.999989,-112.616272,35.0,100000.0,false,Disable,2.8",
          GUID = "194F583C",
          NextDialogue = 10110253,
          Scripts = "PlayAnimation{_delay{1},ActorId{200004},AnimationId{\"Think_Start\"},Duration{1}}",
          SpeakNpcId = 200004,
          Subtitle = "But then something happened, and he shut down his clinic at the height of his fame, only to reopen it as an inn a couple of years later.",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F583C"
        },
        [10110253] = {
          Camera = "62.0,13.855469,151.842773,0.000098,1.998315,-117.01268,35.000008,143.588394,false,Manual,5.149117",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "아, 그러고 보니 마침 헨릭이 스칼렛에서 일을 저지른 것도 그때쯤이었어.",
          DialogueId = 10110253,
          FinalCamera = "100.847656,-14.870117,151.862305,0.000107,6.598201,-135.012131,35.000011,143.588394,false,Manual,5.149117",
          GUID = "194F5866",
          NextDialogue = 10110261,
          SpeakNpcId = 200004,
          Subtitle = "Oh, come to think of it, that was right around the time he got in trouble in Scarletriver...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5866"
        },
        [10110254] = {
          Camera = "37.912109,160.816406,132.972656,0.000113,2.998043,-103.822327,35.000008,305.385315,false,Manual,2.8",
          ContentKR = "아내와 딸이 하나 있었어. 그냥 평범한 세 식구였지. 그의 아내는 아주 일찍 세상을 떠서 혼자 딸을 키웠어.",
          DialogueId = 10110254,
          GUID = "194F5890",
          NextDialogue = 10110255,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}}",
          SpeakNpcId = 200004,
          Subtitle = "He had a wife and a daughter, they were just an ordinary family of three. But then his wife passed away quite early, and he raised his daughter on his own.",
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5890"
        },
        [10110255] = {
          Camera = "67.521484,-246.492188,192.460938,0.000153,-11.802217,107.784149,35.000011,445.644928,false,Manual,4.0",
          ContentKR = "헨릭의 딸... 이름이 뭐였더라? 하이디? 헤일리? 기억이 잘 안 나네. 어쨌든 그 아가씨는 헨릭과 같이 스칼렛에 여행 갔다가 돌아오지 않았어.",
          DialogueId = 10110255,
          GUID = "194F58BA",
          NextDialogue = 10110256,
          RelatedWikiId = {
            [1] = 201006
          },
          SpeakNpcId = 200004,
          Subtitle = "As for his daughter... what's her name? Heidi? Hayley? I don't quite remember — anyway, she went on a trip to Scarletriver with Henrik but never returned with him.",
          TalkActionId = {
            [1] = "200004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F58BA"
        },
        [10110256] = {
          Camera = "67.521484,-246.492188,192.460938,0.000153,-11.802217,107.784149,35.000011,445.644928,false,Manual,4.0",
          ContentKR = "헨릭은 지금까지도 딸에 대한 얘기를 안 해. 언젠가 누가 헨릭이랑 술을 마시던 중에 딸의 행방을 물었더니 그 자리에서 컵을 내던지고 갔다고 들었어.",
          DialogueId = 10110256,
          GUID = "194F58E4",
          NextDialogue = 10110261,
          SpeakNpcId = 200004,
          Subtitle = "He never talks about his daughter. One year, my superior asked about her over drinks, and Henrik just smashed his glass and stormed off.",
          VoiceName = "voice/$Locale$/story/1002/101102/194F58E4"
        },
        [10110257] = {
          Camera = "68.076172,242.375977,133.895508,0.000118,1.598292,-108.029732,35.000008,377.188965,false,Manual,4.0",
          ContentKR = "휴, 내가 아는 건 정말 다 말했어. 이만 날 보내 줘. 그리고 필름은 나한테 넘겨줘. 젠장, 외지인, 넌 순진하게 생겨서는 왜 이렇게 독한 거야.",
          DialogueId = 10110257,
          GUID = "194F590E",
          NextOptions = {
            [1] = 10110258,
            [2] = 10110259
          },
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"200004:n(100001)"}},
PlayAnimation{ActorId{200004},AnimationId{"Talk01_Start"},Duration{2}},
}]],
          SpeakNpcId = 200004,
          Subtitle = "Whew, I swear, I've told you everything I know and have heard about. Can you please let me off now? Just give me the film — darn it, you look nice, how could you be so cunning!",
          VoiceName = "voice/$Locale$/story/1002/101102/194F590E"
        },
        [10110258] = {
          ContentKR = "아까는 실례했어요. 사실 농담이었어요. 사진 같은 건 찍지도 않았다고요...",
          DialogueId = 10110258,
          ExStoryInfo = "Player",
          GUID = "10110258",
          ImprPlusId = 1009,
          NextDialogue = 10110260
        },
        [10110259] = {
          ContentKR = "필름은 제가 일단 가져갈게요. 다음에 또 궁금한 게 있으면 그때 돌려드리죠. 훌륭하신 병.사.님.",
          DialogueId = 10110259,
          ExStoryInfo = "Player",
          GUID = "10110259",
          ImprPlusId = 1006,
          NextDialogue = 10110260
        },
        [10110260] = {
          Camera = "68.076172,242.375977,133.895508,0.000118,1.598292,-108.029732,35.000008,377.188965,false,Manual,4.0",
          ContentKR = "또 봐요, 케빈 병사님.",
          DialogueId = 10110260,
          ExStoryInfo = "Player",
          GUID = "194F5938",
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.2},TargetPosition{"201.574219,-68.02832,168.996094,0.000123,-2.201465,-165.821976,35.000008,243.340027,false,Manual,4.0"},duration{0}},
SEQ{
LookAt{LookAtDescription{"100001:n(100001)"}},
TurnTo{TurnToDescription{"100001:p(180)"}},   
MoveTo{ActorId{100001},TargetPoint{"P101102Nvzhu3"},MoveSpeed{80},Visibility{"Show"}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Well, take care, sir.",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5938"
        },
        [10110261] = {
          DialogueId = 10110261,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 10110257,
          GUID = "194F5717",
          NextOptions = {
            [1] = 10110243,
            [2] = 10110244,
            [3] = 10110245
          }
        },
        [10110301] = {
          ContentKR = "이봐, 이렇게 가는 거야? 어디로 가는데, 이봐!",
          DialogueId = 10110301,
          GUID = "194F6142",
          NextDialogue = 10110302,
          SpeakNpcId = 200004,
          Subtitle = "Hey! You're just gonna leave like that? Where are you going?! Oi!",
          VoiceName = "voice/$Locale$/story/1002/101103/194F6142"
        },
        [10110302] = {
          ContentKR = "말하지 않기로 약속한 거지?! 약속은 꼭 지켜.",
          DialogueId = 10110302,
          GUID = "194F616C",
          SpeakNpcId = 200004,
          Subtitle = "You promised not to tell anyone, didn't you? You have to stick to your word...",
          VoiceName = "voice/$Locale$/story/1002/101103/194F616C"
        },
        [10110401] = {
          ContentKR = "...너, 너 아직도 여기 있었어?! 깜짝이야.",
          DialogueId = 10110401,
          GUID = "194F71AA",
          SpeakNpcId = 200004,
          Subtitle = "You're still here?! Scared me half to death.",
          VoiceName = "voice/$Locale$/story/1002/101104/194F71AA"
        },
        [10110501] = {
          Camera = "668.771606,50.456543,139.82666,0.000123,-1.999995,86.357468,45.0,207.220764,false,Manual,2.5",
          ContentKR = "다 준비됐어.",
          DialogueId = 10110501,
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194F8212",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "100001:n(100001)"
          },
          NextDialogue = 10110502,
          RelatedWikiId = {
            [1] = 201006,
            [2] = 201007,
            [3] = 405002,
            [4] = 303006
          },
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/mute"}},
SEQ{
MoveTo{ActorId{200021},TargetPoint{"P101105Aote"},MoveSpeed{75},Visibility{"Show"}},
PlayAnimation{ActorId{200021},AnimationId{"Confident_Start"},Duration{1}}
},
LookAt{_delay{1},LookAtDescription{"100001:n(200021)"}},
CameraMoveTo{_delay{1.6},TargetPosition{"614.092041,-84.750488,127.766602,0.000123,-3.400054,86.35746,35.0,365.6586,false,Manual,2.5"},duration{0}},
CameraMoveTo{_delay{1.7},TargetPosition{"614.092041,-84.750488,156.081787,0.000124,-6.0,86.35746,35.0,255.410522,false,Manual,3.227706"},blend{"easeOutQuad"},duration{3}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "It is all set.",
          VoiceName = "voice/$Locale$/story/1002/101105/194F8212"
        },
        [10110502] = {
          Camera = "801.704407,333.576172,133.333984,0.000171,-0.800471,-142.436356,30.000002,310.031403,false,Manual,3.5",
          ContentKR = "내성의 친구와 연락해 봤어. 오늘 밤 마차가 이 부근에서 멈출 거래. 프시케가 나오면 일단 성 밖으로 보내 피신시키는 거야. 헨릭, 그놈이 아무리 간이 커도 감히 귀족의 마차는 못 건드리겠지.",
          DialogueId = 10110502,
          GUID = "194F823C",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10110503,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200021},AnimationId{"Confident_End"},Duration{2}},
PlayAnimation{ActorId{200021},AnimationId{"Talk02_Start"},Duration{2}},
PlayAnimation{ActorId{200021},AnimationId{"Talk02_End"},Duration{2}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "I've squared things with a friend from the inner city, he will send his coach around here tonight. Once Psyche shows up, we'll take her out of town and lay low for a while. Henrik wouldn't dare rob a nob's coach.",
          VoiceName = "voice/$Locale$/story/1002/101105/194F823C"
        },
        [10110503] = {
          ContentKR = "그다음엔... 어떻게 할지 방법을 찾아보자.",
          DialogueId = 10110503,
          GUID = "194F8266",
          NextDialogue = 10110504,
          SpeakNpcId = 200021,
          Subtitle = "After that... we'll have to play it by ear.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F8266"
        },
        [10110504] = {
          Camera = "597.891357,-27.287598,177.053955,0.000212,-9.60052,80.358948,40.0,340.8461,false,Manual,5.0",
          ContentKR = "좋은 생각이네.",
          DialogueId = 10110504,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "194F8290",
          NextDialogue = 10110505,
          SpeakNpcId = 100001,
          Subtitle = "You really have a wide network, don't you?",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F8290"
        },
        [10110505] = {
          Camera = "722.716003,214.500488,130.546387,0.000153,5.999351,-137.037186,30.0,200.0,false,Manual,3.0",
          ContentKR = "경력이 몇 년인데, 이 정도는 해야지. 그나저나 정말 올까?",
          DialogueId = 10110505,
          FacialId = {
            [1] = "200021:Smile02"
          },
          GUID = "194F82BA",
          NextDialogue = 10110506,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200021},AnimationId{"Explain01_Start"},Duration{4}},
PlayAnimation{ActorId{200021},AnimationId{"Explain01_End"},Duration{2}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "Ha, got to make the most of all the cr*p I've been through these years. But are you sure she'll come?",
          VoiceName = "voice/$Locale$/story/1002/101105/194F82BA"
        },
        [10110506] = {
          Camera = "636.023804,126.125488,194.547607,0.000065,-21.999294,69.385223,35.000008,1936.839966,false,Manual,22.0",
          ContentKR = "...모르겠어. 오지 않으면 두 번째 계획대로 해야지.",
          DialogueId = 10110506,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200021:None",
            [2] = "100001:None"
          },
          GUID = "194F82E4",
          NextDialogue = 10110507,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"DisagreeHead"},Duration{2}},
PlayAnimation{ActorId{100001},AnimationId{"Explain02_Start"},Duration{2}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "...I'm not sure. Anyway, if she doesn't show up, we'll go with plan B.",
          VoiceName = "voice/$Locale$/story/1002/101105/194F82E4"
        },
        [10110507] = {
          Camera = "746.899231,298.530762,134.940918,0.000159,1.999148,-136.031906,30.000002,419.649261,false,Manual,3.0",
          ContentKR = "히프노스의 집으로 바로 쳐들어가 헨릭의 범죄를 철저히 폭로한다! 하하, 꼭 요즘 인기 많은 소설 속 괴도 같잖아.",
          DialogueId = 10110507,
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194F830E",
          NextDialogue = 10110508,
          SpeakNpcId = 200021,
          Subtitle = "We break into the Hypnos' House and confront Henrik with his crimes — ha, sounds like the story of a hero from some pulp novel.",
          TalkActionId = {
            [1] = "200021:Angry01_Start",
            [2] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F830E"
        },
        [10110508] = {
          ContentKR = "하지만 마음의 준비는 해. 오늘 우리가 프시케를 구한다 해도... 오래 버티지 못할 거야. 프시케도 폐광에서 본 녀석처럼 되겠지.",
          DialogueId = 10110508,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          GUID = "194F8338",
          NextDialogue = 10110509,
          SpeakNpcId = 200021,
          Subtitle = "But don't get your hopes up. Even if we manage to save Psyche today, she... won't last much longer. Remember the thing we saw in the pit? That's her inevitable fate.",
          TalkActionId = {
            [1] = "200021:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F8338"
        },
        [10110509] = {
          Camera = "597.891357,-27.287598,177.053955,0.000213,-9.60052,80.35907,40.0,340.8461,false,Manual,5.0",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "...상황을 보고 움직이자.",
          DialogueId = 10110509,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01",
            [2] = "200021:None"
          },
          FinalCamera = "595.481689,-41.476074,179.486816,0.000213,-9.60052,80.359016,40.0,340.8461,false,Manual,5.0",
          GUID = "194F8362",
          NextDialogue = 10110510,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"DisagreeHead"},Duration{2}},
PlayAnimation{ActorId{100001},AnimationId{"Explain02_Start"},Duration{2}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "...One thing at a time.",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101105/194F8362"
        },
        [10110510] = {
          Camera = "746.899231,298.530762,134.940918,0.000159,1.999148,-136.031906,30.000002,419.649261,false,Manual,3.0",
          ContentKR = "...아, 그러고 보니 침식자는 계속 방위대가 처리해 왔잖아? 헨릭은 대체 무슨 일이 있었길래 이 지경까지 온 거지...",
          DialogueId = 10110510,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194F838C",
          NextDialogue = 10110511,
          SpeakNpcId = 200021,
          Subtitle = "...Right. Speaking of which, aren't the Deteriorators usually handled by the Escort? What on earth has Henrik gone through to end up doing things like this...",
          TalkActionId = {
            [1] = "200021:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F838C"
        },
        [10110511] = {
          Camera = "594.983521,34.920898,147.270508,0.000067,-8.200632,79.375977,30.000008,567.112122,false,Manual,3.0",
          ContentKR = "난... 이유를 알 것 같아.",
          DialogueId = 10110511,
          ExStoryInfo = "Player",
          FinalCamera = "617.869507,29.944824,148.867676,0.000066,-6.800539,83.778397,30.000002,567.112122,false,Manual,3.0",
          GUID = "194F838D",
          NextOptions = {
            [1] = 10110512
          },
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101105/194F838D"
        },
        [10110512] = {
          ContentKR = "(케빈에게서 캐낸 정보를 말한다.)",
          DialogueId = 10110512,
          DisableMouth = 1,
          GUID = "10110512.0",
          NextDialogue = 10110513
        },
        [10110513] = {
          Camera = "960.668701,-341.848633,606.558594,0.000024,-38.601192,121.190224,30.000002,362.012939,false,Manual,3.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "...헨릭은 예전에 의사였지만 어떤 이유로 병원 문을 닫았어. 헨릭에게는 딸이 하나 있었는데, 스칼렛에서 행방이 묘연해졌고. 헨릭은 스칼렛에서 침식자를 한 명 죽였다고...",
          DialogueId = 10110513,
          FacialId = {
            [1] = "200021:Think01"
          },
          FinalCamera = "896.82605,-237.447266,505.624023,0.000011,-40.001194,121.590363,30.000002,362.012939,false,Manual,3.0",
          GUID = "194F83B6",
          NextDialogue = 10110514,
          SpeakNpcId = 200021,
          Subtitle = "...Henrik used to be a doctor, but he shut down his practice for some reason; he had a daughter, but she went missing in Scarletriver; Henrik murdered a Deteriorator in Scarletriver...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101105/194F83B6"
        },
        [10110514] = {
          Camera = "673.087097,200.460449,158.318604,0.000031,-18.200951,80.989815,30.000008,362.012939,false,Manual,22.0",
          ContentKR = "응. 더 중요한 건 이 세 사건이 같은 해에 일어났어. 분명 연관이 있을 거야.",
          DialogueId = 10110514,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200021:Doubt01"
          },
          GUID = "194F83E0",
          NextDialogue = 10110515,
          SpeakNpcId = 100001,
          Subtitle = "Right. More importantly, these three events happened in the same year, so they must be correlated.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F83E0"
        },
        [10110515] = {
          Camera = "801.704407,333.576172,133.333984,0.000171,-0.800471,-142.436356,30.000002,310.031403,false,Manual,3.5",
          ContentKR = "...히프노스의 집 투숙객들은 아마 전부 침식자일 거라고... 음, 무슨 말을 하려는 지 알겠어.",
          DialogueId = 10110515,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          GUID = "194F840A",
          NextDialogue = 10110516,
          SpeakNpcId = 200021,
          Subtitle = "And the lodgers at the Hypnos' House are likely all Deteriorators... Hmm, I see what you're getting at.",
          TalkActionId = {
            [1] = "200021:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F840A"
        },
        [10110516] = {
          Camera = "684.15155,260.363281,147.201416,0.000142,-1.401261,-120.639412,30.000002,200.0,false,Manual,3.0",
          ContentKR = "헨릭의 딸은 아마 스칼렛에서 불의의 사고를 당했을 거야. 아마 그 일이 침식자와 관련이 있겠지. 그래서 헨릭은 침식자에게 원한이 생겼고, 지금까지 여러 해가 지나도록 사라지지 않은 거야...",
          DialogueId = 10110516,
          GUID = "194F8434",
          NextDialogue = 10110517,
          SpeakNpcId = 200021,
          Subtitle = "Henrik's daughter was likely killed in Scarletriver, possibly by a Deterioration, sparking Henrik's deep-seated hatred towards them, which even after so many years, hasn't faded...",
          TalkActionId = {
            [1] = "200021:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F8434"
        },
        [10110517] = {
          ContentKR = "그래서 모종의 방식으로 몇몇 침식자를 통제하고, 손을 쓰는 거라고 생각하는 거지?",
          DialogueId = 10110517,
          GUID = "194F845E",
          NextDialogue = 10110518,
          SpeakNpcId = 200021,
          Subtitle = "So, he somehow managed to control some of the Deteriorations and administer his own brand of justice — that's your conclusion, right?",
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F845E"
        },
        [10110518] = {
          Camera = "649.498047,158.819336,162.394043,0.000159,-15.000577,73.956459,30.000002,106.04982,false,Manual,2.113648",
          ContentKR = "...응, 하지만 어떤 이유든, 침식자들의 마지막 운명이 무엇이든... 우린 반드시...",
          DialogueId = 10110518,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "194F8488",
          NextDialogue = 10110519,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Think_End"},Duration{2}},
PlayAnimation{ActorId{100001},AnimationId{"Angry01_Start"},Duration{2}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "...Yes. But regardless of what he's gone through, or what the Deteriorators would eventually become, we must—",
          VoiceName = "voice/$Locale$/story/1002/101105/194F8488"
        },
        [10110519] = {
          Camera = "964.300659,-14.221191,117.446289,0.000137,-2.199826,147.753998,20.0,107.293198,false,Manual,15.0",
          ContentKR = "으아아...",
          DialogueId = 10110519,
          GUID = "194F8489",
          LookAt = {
            [1] = "200021:p(P101105Bai)",
            [2] = "100001:p(P101105Bai)"
          },
