          NextDialogue = 10111103,
          SpeakNpcId = 100001,
          Subtitle = "Talk to me, Psyche...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE4AC"
        },
        [10111103] = {
          ContentKR = "네가 그랬잖아, 하고 싶은 게 그렇게 많다고...",
          DialogueId = 10111103,
          ExStoryInfo = "Player",
          GUID = "194FE4D6",
          NextDialogue = 10111104,
