          DialogueId = 10111105,
          ExStoryInfo = "Player",
          GUID = "194FE52A",
          NextDialogue = 10111106,
          SpeakNpcId = 100001,
          Subtitle = "...You'll go to a small island, where you can build a few houses by the sea...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE52A"
        },
        [10111106] = {
