          DialogueId = 10111106,
          ExStoryInfo = "Player",
          GUID = "194FE554",
          NextDialogue = 10111107,
          SpeakNpcId = 100001,
          Subtitle = "...and grow white flowers around them...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE554"
        },
        [10111107] = {
          ContentKR = "...눈부신 태양을 피해 챙이 넓은 모자를 쓰고, 친구들에게 아이스레이크 시티의 새하얀 눈 이야기를 해 주는 거야...",
          DialogueId = 10111107,
          ExStoryInfo = "Player",
          GUID = "194FE57E",
          NextDialogue = 10111108,
          SpeakNpcId = 100001,
          Subtitle = "...Talk about the snow in Icelake with your friends, while shading yourself with a wide-brimmed sunhat...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE57E"
        },
        [10111108] = {
          ContentKR = "...대답해줘...",
          DialogueId = 10111108,
          ExStoryInfo = "Player",
          GUID = "194FE5A8",
          SpeakNpcId = 100001,
          Subtitle = "Talk to me, Psyche...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE5A8"
        },
        [10111201] = {
          ContentKR = "프시케, 집에 가자.",
          DialogueId = 10111201,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194FF4EA",
          SpeakNpcId = 100001,
          Subtitle = "Psyche, I'm here to take you home.",
          VoiceName = "voice/$Locale$/story/1002/101127/1950EB02"
        },
        [10111301] = {
          ContentKR = "여기는... 우리 집이잖아?",
          DialogueId = 10111301,
          GUID = "191B889A",
          SpeakNpcId = 200006,
          Subtitle = "Is this... my home?",
          VoiceName = "voice/$Locale$/story/1002/101113/191B889A"
        },
        [10111401] = {
          ContentKR = "여보, 봐요. 프시케가 우리를 보고 웃고 있어요.",
          DialogueId = 10111401,
          GUID = "191B88C4",
          NextDialogue = 10111402,
          SpeakNpcId = 200039,
          Subtitle = "Honey, look, Psyche is smiling at us.",
          VoiceName = "voice/$Locale$/story/1002/101114/191B88C4"
        },
        [10111402] = {
          ContentKR = "...이 아이가 이 세상에 온 게 행운인지 불행인지 모르겠어.",
          DialogueId = 10111402,
          GUID = "191B88EE",
          NextDialogue = 10111403,
          SpeakNpcId = 200038,
          Subtitle = "...I wonder whether this child's birth in this world was a blessing or a curse.",
          VoiceName = "voice/$Locale$/story/1002/101114/191B88EE"
        },
        [10111403] = {
          ContentKR = "...그러네요, 우린 축복을 안고 태어난 게 아니니까요.",
          DialogueId = 10111403,
          GUID = "191B8918",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...Yes, we weren't born with blessings.",
          VoiceName = "voice/$Locale$/story/1002/101114/191B8918"
        },
        [10111501] = {
          ContentKR = "엄마! 오늘 프시케랑 집에서 블록을 쌓기로 했어요...",
          DialogueId = 10111501,
          GUID = "191BB9D2",
          NextDialogue = 10111502,
          SpeakNpcId = 200040,
          Subtitle = "Mum! I promised Psyche I'd bring her home today to play with blocks...",
          VoiceName = "voice/$Locale$/story/1002/101115/191BB9D2"
        },
        [10111502] = {
          ContentKR = "걔랑 놀지 말라고 했지? 몇 번이나 말했잖니, 그런 존재는 가까이하면 안 돼. 사악한 마법 때문에 큰일이라도 나면 어쩌려고 그래!",
          DialogueId = 10111502,
          GUID = "191BB9FC",
          NextDialogue = 10111503,
          SpeakNpcId = 200041,
          Subtitle = "Who says you can play with her? How many times have I told you to stay away from these unclean people? Do you want to be killed by dark magic?",
          VoiceName = "voice/$Locale$/story/1002/101115/191BB9FC"
        },
        [10111503] = {
          ContentKR = "휴, 멀쩡한 블록만 더러워졌네. 얼른 갖다 버려!",
          DialogueId = 10111503,
          GUID = "191BBA26",
          SpeakNpcId = 200041,
          Subtitle = "Ugh, now these blocks are all dirty. Throw them away now!",
          VoiceName = "voice/$Locale$/story/1002/101115/191BBA26"
        },
        [10111601] = {
          ContentKR = "그날 나는 억울함과 의아함을 안고 피가 날 때까지 밤새워 목욕했다.",
          DialogueId = 10111601,
          GUID = "191BBA50",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "That day, feeling wronged and confused, I bathed all night until my skin bled.",
          VoiceName = "voice/$Locale$/story/1002/101116/191BBA50"
        },
        [10111701] = {
          ContentKR = "아닙니다, 병사님. 제 딸은 착해서 절대 손님의 목걸이를 훔치지도, 화분에 숨기지도 않는다고요!",
          DialogueId = 10111701,
          GUID = "191BCA3A",
          NextDialogue = 10111702,
          SpeakNpcId = 200039,
          Subtitle = "So what if he hit your daughter? It was all because your daughter's stuff was an eyesore, wasn't it?",
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA3A"
        },
        [10111702] = {
          ContentKR = "변명은 집어치워, 카론 놈들 중에 깨끗한 놈이 얼마나 된다고!",
          DialogueId = 10111702,
          GUID = "191BCA64",
          NextDialogue = 10111703,
          SpeakNpcId = 200043,
          Subtitle = "Exactly. And it was just a pot of flowers, so cut the whimper, you little twerp. Don't get your filthy tears on my uniform.",
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA64"
        },
        [10111703] = {
          ContentKR = "그래, 훔치지 않았다면서? 그럼 직접 가게의 모든 화분을 깨부숴서 결백을 증명해봐.",
          DialogueId = 10111703,
          GUID = "191BCA8E",
          NextDialogue = 10111704,
          SpeakNpcId = 200044,
          Subtitle = "What are you still doing here? The Security Bureau isn't a place for your nonsense.",
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA8E"
        },
        [10111704] = {
          ContentKR = "...왜냐하면 우리는 '악마의 아이'니까요.",
          DialogueId = 10111704,
          GUID = "191BDAA2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...It's all because, we are \"demon's children.\"",
          VoiceName = "voice/$Locale$/story/1002/101117/191BDAA2"
        },
        [10111801] = {
          ContentKR = "아아... 어째서...",
          DialogueId = 10111801,
          GUID = "191BDACC",
          NextDialogue = 10111802,
          SpeakNpcId = 200039,
          Subtitle = "Aargh... why...",
          VoiceName = "voice/$Locale$/story/1002/101118/191BDACC"
        },
        [10111802] = {
          ContentKR = "이렇게 착한 아이에게... 우리 가족 모두 나쁜 짓 한 번 한 적이 없는데... 왜 이런 일이 우리한테 벌어지는 거죠?",
          DialogueId = 10111802,
          GUID = "191BDAF6",
          NextDialogue = 10111803,
          SpeakNpcId = 200039,
          Subtitle = "She's such a kind child, and we've always been decent, law-abiding people... Why did this happen to us?",
          VoiceName = "voice/$Locale$/story/1002/101118/191BDAF6"
        },
        [10111803] = {
          ContentKR = "...이렇게 된 이상 헨릭 애설레드 선생님께 부탁할 수밖에 없어. 이게 우리가 마지막으로 프시케를 위해 할 수 있는 거야.",
          DialogueId = 10111803,
          GUID = "191BDB20",
          NextDialogue = 10111804,
          SpeakNpcId = 200038,
          Subtitle = "...At this point, there's nothing left but to turn to Dr Henrik Ethelred. It's the last thing we can do for her.",
          VoiceName = "voice/$Locale$/story/1002/101118/191BDB20"
        }
      }
    end
