          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "무의미해. 넌 위선적인 웃는 얼굴로 다른 사람들을 맞이했지, 하지만 정말 사심이 없었나? 그럴 리가, 넌 그냥 비겁하게 그들의 동정을 바라고 있었을 뿐이야. 네가 아직 사람의 모습이었을 때를 기억해 달라면서 말이야.",
          DialogueId = 10112102,
          FinalCamera = "-1212.987305,506.90625,177.723389,0.000065,-6.399019,-3.700013,35.0,229.405197,false,Manual,6.0",
          GUID = "195088BC",
          NextDialogue = 10112103,
          Scripts = [[
