        [10112501] = {
          ContentKR = "미쳤어? 뭘 하는 거야?! 날 죽이면 너도 같이 죽을 거야!",
          DialogueId = 10112501,
          GUID = "1950CA5B",
          NextDialogue = 10112502,
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "What are you doing?!",
          VoiceName = "voice/$Locale$/story/1002/101125/1950CA5B"
        },
        [10112502] = {
          ContentKR = "너를 모욕하고 상처 준 건 그들이야, 그들! 그런데, 날 없애려고 하는 거야?!",
          DialogueId = 10112502,
          GUID = "1950CA5C",
          NextDialogue = 10112503,
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "They were the ones who scorned and hurt you! Yet, you choose to destroy me?!",
          VoiceName = "voice/$Locale$/story/1002/101125/1950CA5C"
        },
        [10112503] = {
          ContentKR = "왜 이 몸에 순종하지 않아? 왜 파괴와 멸망의 길을 택하지 않는 거야?",
          DialogueId = 10112503,
          GUID = "1950CA86",
          NextDialogue = 10112504,
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          VoiceName = "voice/$Locale$/story/1002/101125/1950CA86"
        },
        [10112504] = {
          ContentKR = "왜냐하면, 나는 기억하니까…",
          DialogueId = 10112504,
          GUID = "1950CA87",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Deterioration is irreversible. Even in my destruction, what could you possibly alter?",
          VoiceName = "voice/$Locale$/story/1002/101125/1950CA87"
        },
        [10112601] = {
          ContentKR = "프시케, 네가 줄곧 바라왔던 소원이 뭔지 기억나니?",
          DialogueId = 10112601,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1950DA9A",
          NextDialogue = 10112602,
