        [10113011] = {
          Camera = "-413.662109,-507.15625,157.617188,0.000528,-7.39734,53.794216,25.0,603.134277,false,Manual,4.0",
          ContentKR = "저, 저것들도 침식자와 한 패거리일지 모릅니다! 이 천한 것들, 하나같이 사악한 마법사에 좋은 놈은 하나도 없지! 저라면 죄다...",
          DialogueId = 10113011,
          GUID = "19511DB4",
          LookAt = {
