          GUID = "19511E08",
          LookAt = {
            [1] = "100304:n(700108)"
          },
          NextDialogue = 10113014,
          Scripts = "SetLocation{ActorId{700065},TargetPoint{\"P101130soldier2\"},Visibility{\"Show\"}}",
          SpeakNpcId = 700065,
          SpeakNpcName = "UI_Npc_Name_Man_1",
          Subtitle = "...Er, I'm not saying... I was just referring to them, ma'am. It's not that all Charons are... Anyway, I didn't mean anything by it!",
          TalkActionId = {
            [1] = "700108:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101130/19511E08"
