        [10113102] = {
          Camera = "-1578.376709,-656.11377,-24.818359,0.000068,-4.000004,20.828321,20.000008,1873.920044,false,Manual,4.0",
          ContentKR = "네가 계획을 세우는 걸 보고 충동적으로 움직이지 않을 줄 알았는데, 넌 그래도 너네. 하지만 괜찮아, 이래야 너답지.",
          DialogueId = 10113102,
          GUID = "19512CCC",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10113103,
          Scripts = "CameraMoveTo{_delay{1},TargetPosition{\"-240.073883,130.292801,45.828125,0.000082,6.799965,5.978205,35.0,244.755096,false,Manual,4.0\"},duration{0}},",
          SpeakNpcId = 200021,
          Subtitle = "I thought you wouldn't act so recklessly anymore. Yet, you remain false to yourself, which isn't bad — it suits you.",
          TalkActionId = {
            [1] = "100001:Crouch_End",
            [2] = "200021:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101131/19512CCC"
        },
        [10113103] = {
          Camera = "633.570557,243.739319,136.279297,0.000016,-7.999989,-172.621201,25.0,232.587921,false,DoNotOverride,2.0",
          ContentKR = "하지만 우리는 이미 용감한 친구 하나를 떠나보냈잖아... 너까지 위험에 빠뜨릴 순 없어.",
          DialogueId = 10113103,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          FinalCamera = "681.163269,249.893188,183.225586,0.000017,-12.0,-172.621384,25.0,232.587921,false,DoNotOverride,2.0",
          GUID = "19512CF6",
          NextDialogue = 10113104,
          SpeakNpcId = 200021,
          Subtitle = "Still, I have to say something you might not wanna hear: if you defend a Deteriorator, it's bound to raise suspicions. If the Escort decides to probe into your identity, a travel permit wouldn't be enough to protect you.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101131/19512CF6"
        },
        [10113104] = {
          Camera = "-93.82695,167.397736,69.485352,-5.000005,10.599298,-16.499649,20.000008,65.358772,false,Manual,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "아까 도와줘서... 고마워.",
          DialogueId = 10113104,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "-94.949982,139.65593,67.780273,-5.000005,10.799253,0.903312,20.000008,274.400574,false,Manual,4.0",
          GUID = "19512D20",
          NextDialogue = 10113106,
          SpeakNpcId = 100001,
          Subtitle = "We've just said goodbye to a brave young lady. I can't let you risk yourself again. As for that officer... she was just doing her job, there's no point in blaming her.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101131/19512D20"
        },
        [10113106] = {
          Camera = "-57.476639,131.761963,80.688477,0.000004,13.197796,-11.293015,35.0,189.241562,false,Manual,4.0",
          ContentKR = "고마워할 거 없어. 여기서 벌써 몇 년인데 세상 물정 모르고 고슴도치처럼 가시 세우던 건 벌써 지난 일이야. 이젠 잔머리 굴리는 쥐처럼 매일 살아남는 것 외에는 생각하지 않게 되어버렸지. 넌 나처럼 되지 마.",
          DialogueId = 10113106,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "19512D74",
          LookAt = {
            [1] = "200002:n(200021)"
          },
          NextDialogue = 10113107,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"200021:p(stone)\"}}",
          SpeakNpcId = 200021,
          Subtitle = "There's nothing to thank me for. After all these years, I've gone from a hedgehog to a rat, living only to see another day. Don't end up like me.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101131/19512D74"
        },
        [10113107] = {
          Camera = "10.66497,161.629562,248.601562,-15.000193,-59.999931,-45.621265,20.0,154.841125,false,Manual,2.0",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "뾰족한 가시를 가진 고슴도치라는 것에 긍지를 가져, 이런 일은 쥐한테 맡기고.",
          DialogueId = 10113107,
          FacialId = {
            [1] = "200021:Smile02"
          },
          FinalCamera = "-3.912712,176.5271,284.694336,-15.000193,-59.999931,-45.621265,20.0,154.841125,false,Manual,2.0",
          GUID = "19512D9E",
          LookAt = {
