          DialogueId = 10114901,
          GUID = "195253F2",
          SpeakNpcId = 200045,
          VoiceName = "voice/$Locale$/story/1002/101149/195253F2"
        },
        [10115001] = {
          ContentKR = "... 프시케가 헨릭 씨를... 대체 왜... 이렇게...",
          DialogueId = 10115001,
          GUID = "1952645A",
          NextDialogue = 10115002,
          SpeakNpcId = 700049,
          VoiceName = "voice/$Locale$/story/1002/101150/1952645A"
        },
        [10115002] = {
          ContentKR = "프시케는 언제나 웃고 있었어... 헨릭 씨는 말수는 적었지만, 우리를 자식처럼 챙겼다고... 모두 그렇게 좋은 사람인데...",
          DialogueId = 10115002,
          GUID = "19526484",
          SpeakNpcId = 700049,
          VoiceName = "voice/$Locale$/story/1002/101150/19526484"
        },
        [10115101] = {
          ContentKR = "헨릭 씨는 많이 지쳐 있었어요. 그에겐 어쩌면... 이런 결말도 괜찮을지 몰라요.",
          DialogueId = 10115101,
          GUID = "195274C2",
          SpeakNpcId = 200019,
          VoiceName = "voice/$Locale$/story/1002/101151/195274C2"
        },
        [10115201] = {
