          DialogueId = 10115201,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1952852A",
          NextDialogue = 10115202,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101152/1952852A"
        },
        [10115202] = {
          ContentKR = "내 기억력이 얼마나 좋은데, 물론 기억하지! 프시케는 성문을 향해 갔어!",
          DialogueId = 10115202,
          Duration = 4,
          GUID = "19528554",
          NextDialogue = 10115203,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101152/19528554"
        },
        [10115203] = {
          ContentKR = "... 설마 성을 나간 건가?",
          DialogueId = 10115203,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1952857E",
          NextDialogue = 10115204,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101152/1952857E"
        },
        [10115204] = {
          ContentKR = "그래, 우리도 성 밖으로 따라가자.",
