          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "195285A8",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101152/195285A8"
        },
        [10115301] = {
          ContentKR = "바람이 너무 많이 불어! 으악, 이러다 날아갈 것 같아...",
