          DialogueId = 10118201,
          Duration = 3,
          GUID = "1954715A",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101182/1954715A"
        },
        [10118202] = {
