        },
        [10119702] = {
          ContentKR = "하지만 이 광석은 너무 단단해 보이는데, 마르제 씨의 삽이 망가질지도 몰라.",
          DialogueId = 10119702,
          Duration = 3,
          GUID = "1955679C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101197/1955679C"
        },
        [10119801] = {
          ContentKR = "나도 도와줄게!",
          DialogueId = 10119801,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "195577DA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10119802,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101198/195577DA"
        },
        [10119802] = {
          ContentKR = "괜찮아. 프시케, '마왕님'이 보고 있지 않을 때... 우리끼리 나눠 가지는 건 어때?",
          DialogueId = 10119802,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19557804",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10119803,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101198/19557804"
        },
        [10119803] = {
          ContentKR = "그냥 네가 다 가져가. 예쁜 옷도 사고 그래. 난... 돈 쓸 데가 별로 없어서.",
          DialogueId = 10119803,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955782E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101198/1955782E"
        },
        [10119901] = {
          ContentKR = "이게 뭐지?",
          DialogueId = 10119901,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19558842",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101199/19558842"
        },
        [10120001] = {
          ContentKR = "음... 문을 여는 장치였네! 정말 잘 숨겨놨는걸.",
          DialogueId = 10120001,
          Duration = 3,
          GUID = "195598AA",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101200/195598AA"
        },
        [10120101] = {
          ContentKR = "뭐가 이렇게 많아... 으... 으으...",
          DialogueId = 10120101,
          Duration = 3,
          GUID = "1955A912",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10120102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A912"
        },
        [10120102] = {
          ContentKR = "일단 내 다리에서 내려와, 스노우. 네가 그러고 있으면 내가 못 움직이잖아... 먼저 아이스레이크 시티로 돌아가. 놀리지 않을 테니까.",
          DialogueId = 10120102,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A93C",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10120103,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A93C"
        },
        [10120103] = {
          ContentKR = "아, 안 안 돌아갈 거야, 모모모험을 경험해보지 못한 인생은 부부분명 완벽하지 않으니까!",
          DialogueId = 10120103,
          Duration = 3,
          GUID = "1955A966",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10120104,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A966"
        },
        [10120104] = {
          ContentKR = "좋아, 그럼 나도 {nickname}(이)랑 마왕님과 함께 인생을 좀 더 '완전하게' 만들어볼게.",
          DialogueId = 10120104,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A990",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10120105,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A990"
        },
        [10120105] = {
          ContentKR = "지금까지 내가 발목 붙잡은 일은 없었던 것 같은데... 그러니까 앞으로도 걱정하지 않아도 괜찮아!",
          DialogueId = 10120105,
          Duration = 3,
          GUID = "1955A9BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10120106,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A9BA"
        },
        [10120106] = {
          ContentKR = "응, 그러면 계속 앞으로 가보자.",
          DialogueId = 10120106,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A9E4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10120107,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A9E4"
        },
        [10120107] = {
          ContentKR = "(그저 평범한 필토이드일 뿐이야. 연옥도에서 마주쳤던 것만큼 위험하진 않아...)",
          DialogueId = 10120107,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955AA0E",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10120108,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101201/1955AA0E"
        },
        [10120108] = {
          ContentKR = "(베레가 가르쳐준 호신술을 잘 떠올리며, 조심스럽게 칼을 휘두르면... 할 수 있어.)",
          DialogueId = 10120108,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955AA38",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101201/1955AA38"
        },
