        },
        [11010208] = {
          Camera = "2388.339844,-2981.808594,458.513428,-15.00156,-8.397245,129.407578,25.0,2843.594727,false,Manual,1.2",
          ContentKR = "<W>네 두 손의 그 축축하고 끈적이는 것들이 과연 필토이드의 점액일까? 아니면 내장? 넌 모르겠지. 하지만 그것들이 네 영혼마저 떨리게 할 만큼 기쁘게 한다는 것만은 알고 있어.</>",
          DialogueId = 11010208,
          DisableMouth = 1,
