CameraMoveTo{TargetPosition{"-161.269531,-210.820312,183.930786,-18.022604,-14.005917,79.809784,45.0,100.319092,false,DoNotOverride,22.0"},duration{20}}
},
PARA{PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/evilvo"},PlayAs2D{true}},PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'"}}
}
}]],
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Your hands are drenched in wet, slimy filth, uncertain whether it's the Filthoid's secretions or its innards. Yet, a sudden joy tingles through your soul, bringing an inexplicable elation.",
          TalkActionId = {
            [1] = "110022:Sigh_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110102/1B901A40"
        },
        [11010209] = {
          ContentKR = "(닥쳐! 그렇지 않아!)",
          DialogueId = 11010209,
          GUID = "1B901A6A",
          NextDialogue = 11010210,
          Subtitle = "(Shut up! That was not how I felt!)"
        },
        [11010210] = {
          Camera = "-299.773438,-22.185547,-5.160034,-18.018326,38.192356,-12.391366,30.0,100.319092,false,DoNotOverride,22.0",
          ContentKR = "<W>저항할 필요 없어. 나야말로 진정한 너이자, 네가 가진 죽음의 본능이니. 언젠가 넌 나의 인도와 태초의 의지를 따르게 될 테니까...</>",
          DialogueId = 11010210,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-298.789062,-47.498047,-11.343872,-18.018387,40.392326,-2.390289,30.000002,100.319092,false,DoNotOverride,22.0",
          GUID = "1B901A94",
          NextOptions = {
            [1] = 11010211
          },
          Scripts = [[
PARA{PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/evilvo"},PlayAs2D{true}},PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'"}}
}]],
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Do not resist, because I am what you actually are. I am your instinct for death. One day you shall follow my lead and obey the ancient will...",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110102/1B901A94"
        },
        [11010211] = {
          ContentKR = "(더는 헛소리를 듣고 싶지 않아 이성을 유지하려 애쓴다.)",
          DialogueId = 11010211,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B901ABE",
          NextDialogue = 11010212,
          SpeakNpcId = 110022,
          Subtitle = "(You refuse to let the ramblings erode your will and try to stay sane.)",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901ABE"
        },
        [11010212] = {
          Camera = "-239.953125,-58.078125,187.926147,0.000086,-20.597841,-1.384277,35.0,299.071411,false,Manual,17.255875",
          ContentKR = "......",
          DialogueId = 11010212,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Pain01"
          },
          FinalCamera = "-253.742188,-57.75,193.109009,0.000086,-20.597841,-1.384277,35.0,299.071411,false,Manual,17.255875",
          GUID = "1B901AE8",
          Scripts = "PostProcess{MaterailInstance{\"None\"}}",
          SpeakNpcId = 110022,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110022:Sigh_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110102/1B901AE8"
        },
        [11010215] = {
          ContentKR = "(...짜증 나는 목소리는 이제 멈춘 건가.)",
          DialogueId = 11010215,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B901B66",
          NextDialogue = 11010216,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(...That annoying voice has finally stopped.)",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901B66"
        },
        [11010216] = {
          ContentKR = "다른 사람들은 어떤지 빨리 확인해 봐야겠어.",
          DialogueId = 11010216,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B901B90",
          SpeakNpcId = 110022,
          Subtitle = "I should go check on the others.",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901B90"
        },
        [11010221] = {
          ContentKR = "으윽... 다프네 선생님, 이걸로 임무는 완수한 건가요?",
          DialogueId = 11010221,
          Duration = 3,
          GUID = "1B901C62",
          SpeakNpcId = 110019,
          Subtitle = "Hssss... Dr Daphne, we've completed our mission, right?",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901C62"
        },
        [11010222] = {
          ContentKR = "...아뇨. 무사히 살아 돌아가야 임무를 완수하는 거예요.",
          DialogueId = 11010222,
          Duration = 3,
          GUID = "1B901C8C",
          SpeakNpcId = 110005,
          Subtitle = "...No, not until when we get back alive.",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901C8C"
        },
        [11010223] = {
          ContentKR = "괜찮아, 다프네. 진정해, 다 괜찮을 거야.",
          DialogueId = 11010223,
          Duration = 3,
          GUID = "1B901CB6",
          SpeakNpcId = 110005,
          Subtitle = "It's alright, Daphne. Calm down. Everything's going to be okay. Come down.",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901CB6"
        },
        [11010224] = {
          ContentKR = "아, 돌아오셨군요!",
          DialogueId = 11010224,
          Duration = 3,
          GUID = "1B901CE0",
          SpeakNpcId = 110005,
          Subtitle = "You're back!",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901CE0"
        },
        [11010225] = {
          ContentKR = "...어서 일어나요!!! 이러다간 죽을 수도 있다고요!",
          DialogueId = 11010225,
          Duration = 3,
          GUID = "1B90191A",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Wake up!! Or you'll die!",
          VoiceName = "voice/$Locale$/story/1002/110102/1B90191A"
        },
        [11010226] = {
          ContentKR = "대장님!",
          DialogueId = 11010226,
          Duration = 3,
          GUID = "1B901944",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Captain!",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901944"
        },
        [11010227] = {
          ContentKR = "앗, 대장님, 깨어나셨군요!",
          DialogueId = 11010227,
          Duration = 3,
          GUID = "1B901945",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Whoa, Captain's awake!",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901945"
        },
        [11010301] = {
          Camera = "-101.755859,41.945312,134.13269,0.000056,-2.6,-29.789253,35.000008,251.174286,false,Manual,14",
          ContentKR = "...다치진 않으셨나요?",
          DialogueId = 11010301,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unacceptable01"
          },
          FinalCamera = "-99.96875,45.089844,134.13269,0.000056,-2.6,-29.789253,35.000008,251.174286,false,Manual,14",
          GUID = "1B902982",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11010302,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012
          },
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"110005:n(110022)"}},
PlayAnimation{ActorId{110005},AnimationId{"Explain02_Start"},Duration{0}}
}]],
          SpeakNpcId = 110005,
          Subtitle = "...Are you injured?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110103/1B902982"
        },
        [11010302] = {
          Camera = "181.714844,-51.582031,136.406006,0.000081,-3.999717,173.611221,35.000008,237.587646,false,Manual,14",
          ContentKR = "괜찮습니다.",
          DialogueId = 11010302,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9029AC",
          LookAt = {
            [1] = "110022:n(110005)"
          },
          NextDialogue = 11010303,
          SpeakNpcId = 110022,
          Subtitle = "I'm all right.",
          TalkActionId = {
            [1] = "110022:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110103/1B9029AC"
        },
        [11010303] = {
          Camera = "-41.207031,-17.558594,131.959473,0.000208,-0.800314,-17.784134,35.0,195.280243,false,Manual,22.0",
          ContentKR = "다행이에요. 당신이 아까 필토이드한테 붙잡혔을 때, 저는 정말...",
          DialogueId = 11010303,
          FacialId = {
            [1] = "110005:Happy01"
          },
          FinalCamera = "-26.443359,-22.296875,131.742676,0.000208,-0.800321,-17.784128,35.0,195.280243,false,Manual,22.0",
          GUID = "1B9029D6",
          NextDialogue = 11010304,
          SpeakNpcId = 110005,
          Subtitle = "Good to hear that. When you got tangled up by that Filthoid, I thought I'd never...",
          TalkActionId = {
            [1] = "110005:Explain02_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110103/1B9029D6"
        },
        [11010304] = {
          ContentKR = "...어쨌든, 무사하셔서 다행이에요.",
          DialogueId = 11010304,
          FacialId = {
            [1] = "110005:None"
          },
          GUID = "1B902A00",
          NextDialogue = 11010305,
          SpeakNpcId = 110005,
          Subtitle = "...I'm just glad to see you're okay.",
          VoiceName = "voice/$Locale$/story/1002/110103/1B902A00"
        },
        [11010305] = {
          Camera = "-194.214844,180.058594,138.991333,0.000214,-4.200006,-43.389214,35.000008,195.280243,false,Manual,22.0",
          ContentKR = "하지만... 이제 남은 사람이 별로 없어요. 운 좋게 살아남은 사람들도 모두 부상이 심하고요.",
          DialogueId = 11010305,
          FacialId = {
            [1] = "110005:Sad01"
          },
          FinalCamera = "-202.876953,170.601562,138.991333,0.000215,-4.200006,-41.389534,35.000008,195.280243,false,Manual,22.0",
          GUID = "1B902A2A",
          NextDialogue = 11010306,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"110005:p(fix03hurt)"}}
}]],
          SpeakNpcId = 110005,
          Subtitle = "...There are so few of us left. And those who survived are heavily wounded.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110103/1B902A2A"
        },
        [11010306] = {
          Camera = "3.195312,-10.464844,135.754272,0.000049,-2.400326,-29.395937,35.0,139.800323,false,Manual,22.0",
          ContentKR = "혹시 괜찮으시다면, 부상자들과 이야기 좀 나눠주실 수 있으실까요?",
          DialogueId = 11010306,
          GUID = "1B902A54",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11010307,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6},TargetPosition{"79.023438,-32.414062,128.774658,0.000204,1.19906,172.210541,35.0,189.147873,false,Manual,22.0"},duration{0}},
PlayAnimation{ActorId{110022},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 110005,
          Subtitle = "If you have the time, would you stay and talk to the wounded?",
          VoiceName = "voice/$Locale$/story/1002/110103/1B902A54"
        },
        [11010307] = {
          Camera = "-201.763672,334.066406,336.065674,0.000205,-27.598082,-57.980461,26.0,189.147873,false,Manual,22.0",
          ContentKR = "고마워요. 제가 찾을 게 좀 있어서 잠깐 부탁드릴게요. 모두 당신에게 의지하고 있으니, 한 마디라도 해주시면 큰 힘이 될 거예요.",
          DialogueId = 11010307,
          FacialId = {
            [1] = "110005:Unhappy01"
          },
          FinalCamera = "-201.763672,334.066406,304.138428,0.000206,-27.598082,-57.980148,26.0,189.147873,false,Manual,22.0",
          GUID = "1B902A7E",
          NextDialogue = 11010308,
          SpeakNpcId = 110005,
          Subtitle = "Thank you. I'm heading back to find something, so please take care of them for the time being. The soldiers look up to you. Your encouragement will make them feel better.",
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110103/1B902A7E"
        },
        [11010308] = {
          Camera = "188.039062,-56.824219,140.151245,0.000181,-4.200928,174.81337,35.0,189.147873,false,Manual,22.0",
          ContentKR = "뭘 찾으려고요?",
          DialogueId = 11010308,
          ExStoryInfo = "EXPlayer",
          GUID = "1B902AA8",
          NextDialogue = 11010309,
          SpeakNpcId = 110022,
          Subtitle = "Where are you going?",
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110103/1B902AA8"
        },
        [11010309] = {
          Camera = "-31.5,-4.214844,98.260132,0.000095,10.799259,-24.393532,35.0,155.397324,false,Manual,22.0",
          ContentKR = "작전 지도를 보니 우리 위치에서 멀지 않은 곳에 창고가 있어요. 운이 좋다면 그 안에 구급상자가 있을지도 몰라요.",
          DialogueId = 11010309,
          GUID = "1B902AD2",
          NextDialogue = 11010310,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{3.5},TargetPosition{"-4824.253906,-1793.578125,399.504517,0.000149,-14.800787,8.606606,35.0,100000.0,false,Manual,22.0"},duration{0}}
}]],
          SpeakNpcId = 110005,
          Subtitle = "The battle map shows several warehouses near our location. We might find some first-aid kits there if we're lucky.",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110103/1B902AD2"
        },
        [11010310] = {
          Camera = "-19.5,-9.617188,101.238037,0.000106,10.999233,-24.590504,35.000008,169.901962,false,Manual,22.0",
          ContentKR = "지혈제랑 진통제가 다 떨어졌는데, 아직 치료받지 못한 부상자가 더 있거든요... 더 늦어지면 위험할 거예요.",
          DialogueId = 11010310,
          FacialId = {
            [1] = "110005:Sad01"
          },
          FinalCamera = "-8.886719,-14.484375,103.508179,0.000106,10.999233,-24.590261,35.000008,169.901962,false,Manual,22.0",
          GUID = "1B902AFC",
          NextDialogue = 11010311,
          SpeakNpcId = 110005,
          Subtitle = "I'm already out of coagulants and painkillers, but some of the soldiers haven't been treated yet... Their injuries can't afford any more delays.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110103/1B902AFC"
        },
        [11010311] = {
          Camera = "87.443359,-59.851562,132.342285,0.000173,-0.600893,160.005676,35.000008,196.017685,false,Manual,22.0",
          ContentKR = "제가 다녀올 테니, 여기 계세요.",
          DialogueId = 11010311,
          ExStoryInfo = "EXPlayer",
          GUID = "1B902B26",
          NextDialogue = 11010312,
          Scripts = "PlayAnimation{_delay{1},ActorId{110022},AnimationId{\"DisagreeHead\"},Duration{2}}",
          SpeakNpcId = 110022,
          Subtitle = "You should stay. I'll go.",
          TalkActionId = {
            [1] = "110022:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110103/1B902B26"
        },
        [11010312] = {
          Camera = "-147.375,86.609375,133.640381,0.000178,-1.801148,-38.594769,35.0,100000.0,false,Manual,22.0",
          ContentKR = "이건 의무관인 제가 해야 할 일이에요.",
          DialogueId = 11010312,
          FacialId = {
            [1] = "110005:Unacceptable01"
          },
          GUID = "1B902B50",
          NextDialogue = 11010313,
          SpeakNpcId = 110005,
          Subtitle = "This is the medic's job—",
          VoiceName = "voice/$Locale$/story/1002/110103/1B902B50"
        },
        [11010313] = {
          Camera = "87.443359,-59.851562,132.342285,0.000173,-0.600893,160.005676,35.000008,196.017685,false,Manual,22.0",
          ContentKR = "제 말 듣고 여기 있어요. 다프네, 아직 당신 실력으로는 필토이드라도 마주치면 위험하고, 또 마지막 남은 의무관이 여기서 죽으면 더 큰일이니까요.",
          DialogueId = 11010313,
          ExStoryInfo = "EXPlayer",
          GUID = "1B902B7A",
          NextDialogue = 11010314,
          SpeakNpcId = 110022,
          Subtitle = "And the medic stays. You aren't strong enough to deal with the Filthoids out there alone. We can't afford to lose our only medic.",
          TalkActionId = {
            [1] = "110022:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110103/1B902B7A"
        },
        [11010314] = {
          Camera = "-114.242188,52.828125,134.584595,0.000186,-2.000849,-30.397076,35.000008,203.938095,false,Manual,22.0",
          ContentKR = "......",
          DialogueId = 11010314,
          Duration = 2,
          FinalCamera = "-79.822266,32.675781,133.191162,0.000186,-2.000849,-30.397076,35.000008,203.938095,false,Manual,22.0",
          GUID = "1B902BA4",
          NextDialogue = 11010315,
          SpeakNpcId = 110005,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110005:Explain02_End",
            [2] = "110022:Talk02_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110103/1B902BA4"
        },
        [11010315] = {
          ContentKR = "알겠어요... 그러면 여기 있을게요.",
          DialogueId = 11010315,
          FacialId = {
            [1] = "110005:None"
          },
          GUID = "1B902BCE",
          NextDialogue = 11010316,
          SpeakNpcId = 110005,
          Subtitle = "Understood... I'll follow your orders.",
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110103/1B902BCE"
        },
        [11010316] = {
          ContentKR = "아! 통신기는 혹시 아직 사용할 수 있나요?",
          DialogueId = 11010316,
          GUID = "1B902BF8",
          NextDialogue = 11010317,
          SpeakNpcId = 110005,
          Subtitle = "Is your radio still working?",
          VoiceName = "voice/$Locale$/story/1002/110103/1B902BF8"
        },
        [11010317] = {
          Camera = "103.357422,-46.015625,131.054077,0.000209,-0.60077,165.802734,35.0,189.147873,false,Manual,22.0",
          ContentKR = "네, 아직은 괜찮은 것 같네요.",
          DialogueId = 11010317,
          ExStoryInfo = "EXPlayer",
          GUID = "1B902C22",
          NextDialogue = 11010318,
          SpeakNpcId = 110022,
          Subtitle = "Yes, it still works.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110103/1B902C22"
        },
        [11010318] = {
          Camera = "-200.285156,169.671875,157.805542,0.000194,-7.601222,-43.996536,35.0,203.938095,false,Manual,22.0",
          ContentKR = "다행이네요. 그럼 통신 상태를 유지해 주세요. 언제든 연락할 수 있도록요.",
          DialogueId = 11010318,
          GUID = "1B902C4C",
          SpeakNpcId = 110005,
          Subtitle = "Then please stay on the channel so we can keep in touch.",
          VoiceName = "voice/$Locale$/story/1002/110103/1B902C4C"
        },
        [11010401] = {
          ContentKR = "젠장... 이 빌어먹을 놈들!",
          DialogueId = 11010401,
          Duration = 3,
          GUID = "1B9039EA",
          NextOptions = {
            [1] = 11010402,
            [2] = 11010404,
            [3] = 11010406
          },
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012
          },
          SpeakNpcId = 110044,
          Subtitle = "Damn those friggin' rotters!",
          VoiceName = "voice/$Locale$/story/1002/110104/1B9039EA"
        },
        [11010402] = {
          ContentKR = "다친 곳은 좀 어떤가?",
          DialogueId = 11010402,
          GUID = "1B903A14",
          ImprPlusId = 1009,
          NextDialogue = 11010403,
          Subtitle = "Are you okay?"
        },
        [11010403] = {
          ContentKR = "대장님! 전, 괜찮습니다. 움직일 수 있습니다... 으윽...",
          DialogueId = 11010403,
          Duration = 3,
          GUID = "1B903A3E",
          NextDialogue = 11010408,
          SpeakNpcId = 110044,
          Subtitle = "Captain! I'm fine, I can still move... HSSSSS—",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903A3E"
        },
        [11010404] = {
          ContentKR = "모두 내 잘못이다.",
          DialogueId = 11010404,
          GUID = "1B903A68",
          ImprPlusId = 1007,
          NextDialogue = 11010405,
          Subtitle = "I failed to protect you. I'm sorry."
        },
        [11010405] = {
          ContentKR = "아닙니다, 대장님께서도 최선을 다하지 않으셨습니까. 그렇게 말씀하지 마십시오.",
          DialogueId = 11010405,
          Duration = 3,
          GUID = "1B903A92",
          NextDialogue = 11010408,
          SpeakNpcId = 110044,
          Subtitle = "Please don't say that, Captain! You did your best!",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903A92"
        },
        [11010406] = {
          ContentKR = "방금 누굴 욕한 거지?",
          DialogueId = 11010406,
          GUID = "1B903ABC",
          ImprPlusId = 1010,
          NextDialogue = 11010407,
          Subtitle = "Who are you cursing at?"
        },
        [11010407] = {
          ContentKR = "포세이큰 놈들 말고 누가 있겠습니까.",
          DialogueId = 11010407,
          Duration = 3,
          GUID = "1B903AE6",
          NextDialogue = 11010408,
          SpeakNpcId = 110044,
          Subtitle = "Who else could it be? The bastards who call themselves The Forsakens.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903AE6"
        },
        [11010408] = {
          ContentKR = "포세이큰... 양심은 개나 줘버린 놈들, 필토이드를 무기처럼 쓰다니... <W>포세이큰 동맹</>은 진짜 인간이 아니라 필토이드랑 같은 취급을 해야 하는 것 아닙니까!",
          DialogueId = 11010408,
          Duration = 3,
          GUID = "1B903B10",
          NextDialogue = 11010409,
          RelatedWikiId = {
            [1] = 101004
          },
          SpeakNpcId = 110044,
          Subtitle = "Those despicable cowards are using Filthoids as their weapon... The Forsakens are monsters, just like their Filthoid pets!",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903B10"
        },
        [11010409] = {
          ContentKR = "그리고 위의 그 멍청이들도 마찬가지입니다. 이렇게 필토이드가 많이 있는데, 우리 선발대 작전 계획서에는 한 글자도 언급이 없었다는 게 말이 안 되지 않습니까!",
          DialogueId = 11010409,
          Duration = 3,
          GUID = "1B903B3A",
          NextDialogue = 11010410,
          SpeakNpcId = 110044,
          Subtitle = "And those blasted airheads giving us the orders are just as bad. The mission brief mentioned nothing about the Filthoid hordes down here.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903B3A"
        },
        [11010410] = {
          ContentKR = "...죄송합니다. 이렇게 큰 소리 내는 걸 안 좋아하실 텐데, 제 싫은 소리만 한 것 같습니다.",
          DialogueId = 11010410,
          Duration = 3,
          GUID = "1B903B64",
          NextDialogue = 11010411,
          SpeakNpcId = 110044,
          Subtitle = "...Sorry about that. I shouldn't have vented my frustration in front of you, Captain.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903B64"
        },
        [11010411] = {
          ContentKR = "괜찮아. 속으로만 삭이는 것보다 말로 푸는 게 낫지.",
          DialogueId = 11010411,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B903B8E",
          NextDialogue = 11010412,
          SpeakNpcId = 110022,
          Subtitle = "It's alright. Letting out emotions is better than being unable to speak at all.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903B8E"
        },
        [11010412] = {
          ContentKR = "하하, 대장님도 위로라는 걸 할 줄 아시는 분인걸 이제야 알았습니다.",
          DialogueId = 11010412,
          Duration = 3,
          GUID = "1B903BB8",
          NextDialogue = 11010413,
          SpeakNpcId = 110044,
          Subtitle = "Hah! You always know how to soothe people, Captain!",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903BB8"
        },
        [11010413] = {
          ContentKR = "그래도 대장님이 계셔서 다행입니다. 아니었다면 저희들 따위 목숨은 여기서 끝났을 텐데 말입니다.",
          DialogueId = 11010413,
          Duration = 3,
          GUID = "1B903BE2",
          NextDialogue = 11010414,
          SpeakNpcId = 110044,
          Subtitle = "And thank goodness we have you. We thought we were goners.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903BE2"
        },
        [11010414] = {
          ContentKR = "<Highlight>아바르 님</>이라도 계셨다면... 우리 중에서 작전 경험이 가장 많은 분이시니, 분명 좋은 방법을 알려주셨을 텐데...",
          DialogueId = 11010414,
          Duration = 3,
          GUID = "1B903C0C",
          SpeakNpcId = 110044,
          Subtitle = "It's just that we're too green. If only Commander Avar were here... As a veteran, he must have a way to get us out.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903C0C"
        },
        [11010415] = {
          ContentKR = "(아바르 교관님은... 아직 소식이 없어.)",
          DialogueId = 11010415,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B903C36",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Sir Avar... Still no words from him.)",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903C36"
        },
        [11010416] = {
          ContentKR = "꼭 조심하세요. 다녀오실 때까지 여기서 기다리고 있을게요.",
          DialogueId = 11010416,
          GUID = "1B903C37",
          SpeakNpcId = 110005,
          Subtitle = "Please be careful. I'll be waiting for you right here.",
          VoiceName = "voice/$Locale$/story/1002/110104/1B903C37"
        },
        [11010501] = {
          ContentKR = "선생님... 다프네 선생님... 아, 이렇게 갇혀 버리다니, 진짜 여기까지 인가 봐요. 정말 이 끔찍한 곳에서 죽게 된다면, 절 묻어주실 수 있나요... 다프네 선생님...",
          DialogueId = 11010501,
          Duration = 3,
          GUID = "1B904A52",
          NextOptions = {
            [1] = 11010502,
            [2] = 11010504
          },
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012
          },
          SpeakNpcId = 110045,
          Subtitle = "Doctor... Dr Daphne... We're stuck in this bloody dump. Please, Dr Daphne, if I don't make it, do me a favour and bury me...",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904A52"
        },
        [11010502] = {
          ContentKR = "그만 말해, 상처가 덧날 수 있어.",
          DialogueId = 11010502,
          GUID = "1B904A7C",
          ImprPlusId = 1007,
          NextDialogue = 11010503,
          Subtitle = "Don't be discouraged. It'll worsen your wounds."
        },
        [11010503] = {
          ContentKR = "진통제도 없어서, 뭐라도 말하는 게 차라리 나은 것 같습니다.",
          DialogueId = 11010503,
          Duration = 3,
          FinalCamera = "19.119141,-1903.257812,170.347046,0.000149,-8.797147,-118.375465,35.0,100000.0,false,Manual,22.0",
          GUID = "1B904AA6",
          NextDialogue = 11010506,
          SpeakNpcId = 110045,
          Subtitle = "We're out of painkillers... so I have to grumble a bit to make myself feel better.",
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/110105/1B904AA6"
        },
        [11010504] = {
          ContentKR = "그렇게 소리가 작아서 필토이드한테 들리기나 하겠어?",
          DialogueId = 11010504,
          GUID = "1B904AD0",
          ImprPlusId = 1010,
          NextDialogue = 11010505,
          Subtitle = "Right, keep raising your voice to attract the Filthoids."
        },
        [11010505] = {
          ContentKR = "진통제도 없으니 뭐라도 말하면 나아질까 싶어서 그런 건데... 주의하겠습니다.",
          DialogueId = 11010505,
          Duration = 3,
          FinalCamera = "19.119141,-1903.257812,170.347046,0.000149,-8.797147,-118.375465,35.0,100000.0,false,Manual,22.0",
          GUID = "1B904AFA",
          NextDialogue = 11010506,
          SpeakNpcId = 110045,
          Subtitle = "Sorry, Captain. I'll zip it. With no painkillers left, I can only grumble a little to help distract me from the pain.",
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/110105/1B904AFA"
        },
        [11010506] = {
          ContentKR = "아까 다프네 선생님과 후방에 계시는 걸 본 것 같은데, 선생님은 괜찮으십니까?",
          DialogueId = 11010506,
          Duration = 3,
          GUID = "1B904B24",
          NextDialogue = 11010507,
          SpeakNpcId = 110045,
          Subtitle = "Dr Daphne and you covered our retreat just then. How is she?",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904B24"
        },
        [11010507] = {
          ContentKR = "괜찮아. 나한테 너희가 어떤지 봐달라고 하더군.",
          DialogueId = 11010507,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B904B4E",
          NextDialogue = 11010508,
          SpeakNpcId = 110022,
          Subtitle = "She's all right. She told me to come check on all of you.",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904B4E"
        },
        [11010508] = {
          ContentKR = "그렇다면 다행입니다. 참... 다프네 선생님은 사실 그냥 연금원에서 편하게 계셔도 되는 분인데 굳이 13군단에 오셔서 이런 고생을 하고 계시니... 솔직히 무슨 생각을 하고 계신지 모르겠습니다.",
          DialogueId = 11010508,
          Duration = 3,
          GUID = "1B904B78",
          NextDialogue = 11010509,
          RelatedWikiId = {
            [1] = 101007
          },
          SpeakNpcId = 110045,
          Subtitle = "Good to hear that. *sigh* A high-born lady like her could've stayed at the Academy, but no, she chose to serve with the 13th Legion. What was she thinking?",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904B78"
        },
        [11010509] = {
          ContentKR = "귀족님들이야 항상 말로는 언제나 폐하께 영광과 충성을 바친다고 하신다지만, 이곳까지 와서도 그런 소리가 나올지는 모르겠습니다. 그때 그런 말을 꺼냈던 자신의 입을 스스로 꿰매 버리고 싶을 것 같은데 말입니다.",
          DialogueId = 11010509,
          Duration = 3,
          GUID = "1B904BA2",
          NextDialogue = 11010510,
          SpeakNpcId = 110045,
          Subtitle = "...\"Eternal glory and loyalty to our Emperor!\" Those aristocrats say that all the time. I wonder if any of them would still be so keen on that when they're actually in a filth pit like this.",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904BA2"
        },
        [11010510] = {
          ContentKR = "하지만 다프네 선생님은 실력도 뛰어나시고 말씀도 따뜻하게 하십니다. 대장님, 다프네 선생님을 절대 여기서 돌아가시게 두면 안됩니다.",
          DialogueId = 11010510,
          Duration = 3,
          GUID = "1B904BCC",
          SpeakNpcId = 110045,
          Subtitle = "But Dr Daphne has real medical skills and a soft, pretty voice. We gotta keep her safe, Captain. Don't want her to die here.",
          VoiceName = "voice/$Locale$/story/1002/110105/1B904BCC"
        },
        [11010618] = {
          ContentKR = "창고에 정말 군수품 상자가 있긴 하네요.",
          DialogueId = 11010618,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B905D84",
          NextDialogue = 11010619,
          SpeakNpcId = 110022,
          Subtitle = "The warehouse does have a few military supply crates.",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905D84"
        },
        [11010619] = {
          ContentKR = "좋아요. 상자를 열기 전에 주변에 함정은 없는지 잘 살피셔야 해요.",
          DialogueId = 11010619,
          Duration = 3,
          GUID = "1B905DAE",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110005,
          Subtitle = "Great. But before your search, make sure the crates are safe to be approached.",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905DAE"
        },
        [11010621] = {
          ContentKR = "찾았습니다. 약품도 모두 멀쩡해요.",
          DialogueId = 11010621,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B905E02",
          NextDialogue = 11010622,
          SpeakNpcId = 110022,
          Subtitle = "I got it. The medicine appears to be in good condition.",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905E02"
        },
        [11010622] = {
          ContentKR = "감사합니다! 돌아오실 때도 조심하셔야 해요. 주변에 아직 필토이드가 있을 수 있으니까요.",
          DialogueId = 11010622,
          Duration = 3,
          GUID = "1B905E2C",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110005,
          Subtitle = "That's great! Thank you! Be careful on your way back. Filthoids are probably lurking around this place.",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905E2C"
        },
        [11010623] = {
          ContentKR = "다른 사람들은 어떻게 됐을까...",
          DialogueId = 11010623,
          Duration = 3,
          GUID = "1B905E56",
          SpeakNpcId = 110026,
          SpeakNpcName = "UI_Npc_Hurtsoldier",
          Subtitle = "Wonder how the other guys are doing...",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905E56"
        },
        [11010624] = {
          ContentKR = "썩을 놈들... 반드시 되갚아줘야 해.",
          DialogueId = 11010624,
          Duration = 3,
          GUID = "1B905E80",
          SpeakNpcId = 110028,
          SpeakNpcName = "UI_Npc_Hurtsoldier",
          Subtitle = "Gotta make those rotters pay.",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905E80"
        },
        [11010625] = {
          ContentKR = "빌어먹을 필토이드... 빌어먹을 포세이큰...",
          DialogueId = 11010625,
          Duration = 3,
          GUID = "1B905EAA",
          SpeakNpcId = 110024,
          SpeakNpcName = "UI_Npc_Hurtsoldier",
          Subtitle = "Damn those Filthoids... Damn The Forsakens...",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905EAA"
        },
        [11010626] = {
          ContentKR = "잠들면 안 돼... 여기서 쓰러질 순 없어...",
          DialogueId = 11010626,
          Duration = 3,
          GUID = "1B905ED4",
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Hurtsoldier",
          Subtitle = "Can't fall asleep... Can't die here...",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905ED4"
        },
        [11010627] = {
          ContentKR = "으윽... 팔이 말을 안 듣는 것 같아...",
          DialogueId = 11010627,
          Duration = 3,
          GUID = "1B905EFE",
          SpeakNpcId = 110027,
          SpeakNpcName = "UI_Npc_Hurtsoldier",
          Subtitle = "Hsss— I can't feel my arm...",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905EFE"
        },
        [11010628] = {
          ContentKR = "대장님은 무사하셔서 다행입니다.",
          DialogueId = 11010628,
          Duration = 3,
          GUID = "1B905F28",
          SpeakNpcId = 110027,
          SpeakNpcName = "UI_Npc_Hurtsoldier",
          Subtitle = "Thank goodness our Captain is all right. We're gonna make it.",
          VoiceName = "voice/$Locale$/story/1002/110106/1B905F28"
        },
        [11010701] = {
          Camera = "-181.388672,-39.609375,130.604614,-0.015137,-0.715817,67.630249,35.0,171.964966,false,Manual,22.0",
          ContentKR = "돌아오셨군요.",
          DialogueId = 11010701,
          Duration = 3,
          GUID = "1B906B22",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextOptions = {
            [1] = 11010702
          },
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 101004
          },
          Scripts = [[
PARA{
MoveTo{_delay{0.5},ActorId{110022},TargetPoint{"pNanzhumove"},MoveSpeed{80},Visibility{"Show"}},
CameraMoveTo{_delay{1.5},TargetPosition{"-101.953125,413.027344,207.724121,-0.015137,-12.916167,-98.55867,35.0,155.193787,false,Manual,22.0"},duration{0}},
PlayAnimation{ActorId{110005},AnimationId{"Explain02_Start"},Duration{3}}
}]],
          SpeakNpcId = 110005,
          Subtitle = "You're back!",
          VoiceName = "voice/$Locale$/story/1002/110107/1B906B22"
        },
        [11010702] = {
          ContentKR = "(약을 다프네에게 건넨다.)",
          DialogueId = 11010702,
          GUID = "1B906B4C",
          NextDialogue = 11010703,
          Subtitle = "(Give the medicine to Daphne)"
        },
        [11010703] = {
          Camera = "-362.734375,-126.394531,148.611084,0.000269,-5.800961,36.800026,35.0,396.962982,false,Manual,22.0",
          ContentKR = "좋아요. 이 정도면 부상자들의 상태를 어느 정도 안정시킬 수 있을 거예요.",
          DialogueId = 11010703,
          Duration = 3,
          FinalCamera = "-358.041016,-122.882812,148.015259,0.000269,-5.800961,36.800026,35.0,396.962982,false,Manual,22.0",
          GUID = "1B906B76",
          SpeakNpcId = 110005,
          Subtitle = "Great, this would help stabilise the wounded.",
          TalkActionId = {
            [1] = "110005:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906B76"
        },
        [11010704] = {
          Camera = "-38.066406,117.800781,137.944946,0.000298,-5.401026,-146.592728,29.45373,261.978973,false,Manual,22.0",
          ContentKR = "'스노우 울프'의 연락은 아직입니까?",
          DialogueId = 11010704,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B906BA0",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11010705,
          Scripts = "SetLocation{ActorId{110022},TargetPoint{\"pNanzhumove\"},Visibility{\"Show\"}}",
          SpeakNpcId = 110022,
          Subtitle = "Any news from the Snow Wolves?",
          TalkActionId = {
            [1] = "110022:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906BA0"
        },
        [11010705] = {
          Camera = "-191.169922,2.410156,140.592285,0.000278,-3.600862,52.200577,35.0,130.402435,false,Manual,22.0",
          ContentKR = "아직이에요. 안 계신 동안 제가 '스노우 울프'의 아바르 중령님, 그리고 총지휘부의 풀비스 장관님과 연락을 시도했지만 모든 통신 채널이 끊겨버렸어요.",
          DialogueId = 11010705,
          Duration = 3,
          GUID = "1B906BCA",
          NextDialogue = 11010706,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{110005},AnimationId{"DisagreeHead"},Duration{1.5}},
CameraMoveTo{TargetPosition{"-744.447266,-1296.125,176.616455,0.000267,-8.001067,112.406685,35.0,100000.0,false,Manual,22.0"},duration{0},_delay{2}},
CameraMoveTo{TargetPosition{"-847.738281,-1338.699219,176.616455,0.000268,-8.001067,112.406708,35.0,100000.0,false,Manual,22.0"},duration{3}}
}]],
          SpeakNpcId = 110005,
          Subtitle = "Not yet. While you were away, I tried reaching out to Commander Avar of the Snow Wolves and Chief Commander Fulvis, but none of the comm channels were working.",
          TalkActionId = {
            [1] = "110022:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110107/1B906BCA"
        },
        [11010706] = {
          Camera = "-515.240234,50.238281,106.900269,0.000249,0.398227,-7.393137,35.0,100000.0,false,Manual,22.0",
          ContentKR = "계속 시도해 보죠. 지금은 우선 부상자를 눕힐 수 있는 더 안전한 곳을 찾아보죠.",
          DialogueId = 11010706,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B906BF4",
          NextDialogue = 11010707,
          Scripts = [[
PARA{
SEQ{
TurnTo{TurnToDescription{"110022:n(110005)"}},
LookAt{LookAtDescription{"110022:n(110005)"}}
},
CameraMoveTo{_delay{1.5},TargetPosition{"-129.167969,149.335938,131.636841,0.000255,-1.001859,-106.992546,35.0,190.165726,false,Manual,22.0"},duration{0}}
}]],
          SpeakNpcId = 110022,
          Subtitle = "Keep trying. And meanwhile, let's see if we can find a safer place for the wounded.",
          VoiceName = "voice/$Locale$/story/1002/110107/1B906BF4"
        },
        [11010707] = {
          Camera = "-365.529297,-63.316406,169.275757,0.000246,-12.001523,22.80418,35.0,312.469208,false,Manual,22.0",
          ContentKR = "...그것과 관련해서 말씀드릴 게 하나 있어요.",
          DialogueId = 11010707,
          Duration = 3,
          FinalCamera = "-346.34375,-87.652344,150.890503,0.000338,-7.800048,30.019533,35.0,100000.0,false,Manual,22.0",
          GUID = "1B906C1E",
          NextDialogue = 11010708,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{110005},AnimationId{"Explain02_Start"},Duration{3}},
PlayAnimation{ActorId{110005},AnimationId{"Explain02_End"},Duration{1}}
}]],
          SpeakNpcId = 110005,
          Subtitle = "...Actually, I have a plan.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906C1E"
        },
        [11010708] = {
          Camera = "-346.34375,-87.652344,150.890503,0.000338,-7.800048,30.019533,35.0,100000.0,false,Manual,22.0",
          ContentKR = "무슨 일이시죠?",
          DialogueId = 11010708,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B906C48",
          NextDialogue = 11010709,
          SpeakNpcId = 110022,
          Subtitle = "What is it?",
          VoiceName = "voice/$Locale$/story/1002/110107/1B906C48"
        },
        [11010709] = {
          Camera = "-346.34375,-87.652344,150.890503,0.000338,-7.800048,30.019533,35.0,100000.0,false,Manual,22.0",
          ContentKR = "우선 이 지도를 한번 보시겠어요?",
          DialogueId = 11010709,
          Duration = 3,
          FinalCamera = "-286.345703,-87.492188,152.207397,0.000344,-7.199763,40.221565,35.0,100000.0,false,Manual,22.0",
          GUID = "1B906C72",
          NextDialogue = 11010710,
          SpeakNpcId = 110005,
          Subtitle = "Take a look at this map.",
          TalkActionId = {
            [1] = "110005:Explain01_Start"
          },
          ToFinalCameraBlendTime = 60,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906C72"
        },
        [11010710] = {
          ContentKR = "지금 우리가 있는 창고 구역 출구는 막혔지만, 아직 확인하지 않은 곳이 하나 있어요... 바로 <Highlight>지하 통로</>예요.",
          DialogueId = 11010710,
          Duration = 3,
          GUID = "1B906C9C",
          NextDialogue = 11010711,
          SpeakNpcId = 110005,
          Subtitle = "We're currently in the storage area where the exit is blocked. However, there are some underground tunnels that we haven't checked yet.",
          VoiceName = "voice/$Locale$/story/1002/110107/1B906C9C"
        },
        [11010711] = {
          ContentKR = "제국의 대부분 도시와 요새에는 잘 정비된 하수도가 있어요. 또 최근 10년이 훌쩍 넘는 기간 동안 공습이 있을 때 대피할 목적으로 이런 지하 하수도를 전면 확장했다고 들었어요.",
          DialogueId = 11010711,
          Duration = 3,
          GUID = "1B906CC6",
          NextDialogue = 11010712,
          SpeakNpcId = 110005,
          Subtitle = "Most imperial cities and fortresses have elaborate networks of underground sewers. In recent years, some of these tunnels were expanded and reinforced to serve as air raid shelters.",
          TalkActionId = {
            [1] = "110005:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110107/1B906CC6"
        },
        [11010712] = {
          ContentKR = "운이 좋아서 포세이큰 동맹이 지하에 매복해 있지 않다면, 어쩌면... 어쩌면 부상자들을 그곳으로 옮겨 쉬게 할 수 있을지도 몰라요. 지하 수로가 요새 밖과 연결되어 있어서 구조대가 오면 접선하기도 편할 거예요.",
          DialogueId = 11010712,
          Duration = 3,
          GUID = "1B906CF0",
          NextDialogue = 11010713,
          SpeakNpcId = 110005,
          Subtitle = "If we're lucky enough and The Forsakens didn't set up any ambushes, maybe we could get the wounded there to rest and recover. Besides, the sewer tunnels run all the way outside the fortress, so if our reinforcements arrive, they can easily get to us.",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110107/1B906CF0"
        },
        [11010713] = {
          ContentKR = "물, 물론... 지하도 위험할 수 있지만요. 괜찮으시다면 제가 먼저 가서 확인해 볼게요.",
          DialogueId = 11010713,
          Duration = 3,
          GUID = "1B906D1A",
          NextDialogue = 11010714,
          SpeakNpcId = 110005,
          Subtitle = "Of course... the tunnels might be risky as well. If you think it's feasible, allow me to scout ahead first.",
          VoiceName = "voice/$Locale$/story/1002/110107/1B906D1A"
        },
        [11010714] = {
          Camera = "-132.943359,121.832031,131.186157,0.000256,0.3982,-111.990349,35.0,190.165726,false,Manual,22.0",
          ContentKR = "괜찮은 생각이네요. 하지만 다프네, 당신 혼자 확인하러 가는 건 너무 위험합니다.",
          DialogueId = 11010714,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-138.074219,112.890625,131.25708,0.000256,-0.401793,-110.989861,35.0,190.165726,false,Manual,22.0",
          GUID = "1B906D44",
          NextDialogue = 11010715,
          SpeakNpcId = 110022,
          Subtitle = "It's worth a try, but we can't risk having our medic do this alone.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906D44"
        },
        [11010715] = {
          Camera = "-765.152344,-143.957031,167.94812,-0.001739,-7.41055,15.226987,35.0,100000.0,false,Manual,22.0",
          ContentKR = "지금 움직일 수 있는 건 우리 둘뿐이에요. 필토이드가 이곳을 습격할 수도 있으니, 그들을 보호하려면 대장님이 멀리 떨어질 수도 없고요.",
          DialogueId = 11010715,
          Duration = 3,
          FinalCamera = "-794.794922,3.945312,167.952271,-0.001739,-7.41055,2.827789,35.0,100000.0,false,Manual,22.0",
          GUID = "1B906D6E",
          NextDialogue = 11010716,
          SpeakNpcId = 110005,
          Subtitle = "But now only the two of us can move or act... And the Filthoids might attack this place anytime. You should stay and keep the squad safe.",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906D6E"
        },
        [11010716] = {
          Camera = "-236.480469,-19.691406,150.981567,0.000378,-8.399657,44.019459,35.0,178.234528,false,Manual,22.0",
          ContentKR = "저는... 전문 정찰병은 아니지만, 어느 정도 지식은 있으니까요...",
          DialogueId = 11010716,
          Duration = 3,
          FinalCamera = "-229.025391,-12.492188,149.450317,0.000378,-8.399657,44.019459,35.0,178.234528,false,Manual,22.0",
          GUID = "1B906D98",
          NextDialogue = 11010717,
          SpeakNpcId = 110005,
          Subtitle = "I may not be a professional scout, but over time I've picked up some useful skills, so...",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906D98"
        },
        [11010717] = {
          Camera = "-134.585938,137.484375,132.803467,0.00038,-2.599795,-102.382423,28.0,178.234528,false,Manual,22.0",
          ContentKR = "알겠습니다. 움직일 때 조심하시고, 적과 마주치면 정면 충돌은 절대로 피해야 합니다.",
          DialogueId = 11010717,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-135.685547,132.480469,132.570435,0.00038,-2.599795,-102.382423,28.0,178.234528,false,Manual,22.0",
          GUID = "1B906DC2",
          NextDialogue = 11010718,
          SpeakNpcId = 110022,
          Subtitle = "...Alright, be careful down there. Make sure to sidestep any confrontation with the enemies.",
          TalkActionId = {
            [1] = "110005:Explain02_End",
            [2] = "110022:AgreeHead"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906DC2"
        },
        [11010718] = {
          Camera = "-229.025391,-12.492188,146.342163,0.000379,-7.399601,41.019707,35.0,178.234528,false,Manual,22.0",
          ContentKR = "알겠어요. 계속 연락드릴게요. 당신도 다른 사람들과 연락을 유지해 주세요. 만약 제가 30분 이상 연락이 없으면... 다른 방법을 찾아주세요.",
          DialogueId = 11010718,
          Duration = 3,
          GUID = "1B906DEC",
          NextDialogue = 11010719,
          SpeakNpcId = 110005,
          Subtitle = "Understood. I'll stay on the radio while you keep contacting the others. And if I lose contact for more than half an hour, please... lead the squad to find another way.",
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110107/1B906DEC"
        },
        [11010719] = {
          Camera = "-216.220703,27.652344,122.164429,0.000382,5.200349,33.623096,35.0,178.234528,false,Manual,22.0",
          ContentKR = "겁먹지 마, 다프네. 모두가 살아남을 수 있는 희망이 너한테 달려 있어... 두려워할 필요 없어.",
          DialogueId = 11010719,
          Duration = 3,
          FacialId = {
            [1] = "110005:Iyada01"
          },
          FinalCamera = "-208.587891,32.714844,122.998535,0.000381,5.200349,33.623184,35.0,178.234528,false,Manual,22.0",
          GUID = "1B906E16",
          SpeakNpcId = 110005,
          Subtitle = "Don't be scared, Daphne. Everyone's survival depends on you... Don't be scared.",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110107/1B906E16"
        },
        [11010803] = {
          Content = "玩法教学预留",
          DialogueId = 11010803,
