        },
        [11011434] = {
          ContentKR = "동력실이 폭발한다. 빨리 나와!",
          DialogueId = 11011434,
          GUID = "1B90E2E9",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "The engine room is about to explode. Evacuate now!",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E2E9"
        },
        [11011501] = {
