        [11011827] = {
          Camera = "-397.019531,164.720703,139.713013,0.000156,-7.600183,-69.580688,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "프랭크 할아버지는 제 은인이세요.",
          DialogueId = 11011827,
          GUID = "1B9123DE",
          LookAt = {
            [1] = "110034:n(110022)"
          },
          NextDialogue = 11011828,
          SpeakNpcId = 110034,
          Subtitle = "Mr Frank saved my life.",
          VoiceName = "voice/$Locale$/story/1002/110118/1B9123DE"
        },
        [11011828] = {
          ContentKR = "며칠 전, 배가 아파서 잠시 쉬고 있었을 뿐인데 동맹 놈들이 채찍질하더군요. 죽어가던 저에게 할아버지가 물과 음식, 그리고 이 낡은 옷을 주셨고요.",
          DialogueId = 11011828,
          FacialId = {
            [1] = "110034:Sad01"
          },
          GUID = "1B912408",
          NextDialogue = 11011829,
          SpeakNpcId = 110034,
          Subtitle = "Just a few days ago, I had to take a break because my stomach was acting up, but those Forsaken rotters whipped me dozens of times and left me for dead. It was Mr Frank who gave me water, food, and this ragged robe to cover me up.",
          TalkActionId = {
            [1] = "110022:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B912408"
        },
        [11011829] = {
          Camera = "-180.152344,-181.611328,153.236694,0.000139,-8.80102,119.82122,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "할아버지가 아니었으면 저는 분명 죽었을 거예요. 할아버지 대신 제 목숨을 내놓을 테니 저를 쏘세요. 그리고 할아버지는 진심으로 여러분을 돕고 싶으신 거예요. 저희도 포세이큰 동맹을 용서할 수 없으니까요.",
          DialogueId = 11011829,
          FacialId = {
            [1] = "110034:None"
          },
          FinalCamera = "-188.547852,-186.429688,153.236694,0.000147,-8.80102,119.82122,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B912432",
          LookAt = {
            [1] = "110034:n(110022)",
            [2] = "110022:n(110034)"
          },
          NextDialogue = 11011830,
          Scripts = "CameraMoveTo{_delay{8},TargetPosition{\"-334.542969,94.224609,124.2948,0.000144,-1.4012,-78.373749,35.000011,142.471191,false,Manual,2.8\"},duration{0}}",
          SpeakNpcId = 110034,
          Subtitle = "I would have died if not for Mr Frank. So if you must shoot him, could you please shoot me instead? He just wants to help, because none of us can forgive what The Forsakens did to us.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110118/1B912432"
        },
        [11011830] = {
          Camera = "-340.931641,528.488281,131.870483,0.000145,-6.201326,-90.573792,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "하수도는 사방으로 이어져 있어서 여러분끼리 가면 길을 찾기 쉽지 않을 거예요. 할아버지는 밸브 수리 때문에 자주 불려 가셔서 길을 잘 아시니까 할아버지를 살려 주시면 분명 길을 찾는데 도움이 될 거예요.",
          DialogueId = 11011830,
          FinalCamera = "-326.59082,528.347656,131.870483,0.000145,-6.201326,-90.573792,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91245C",
          NextDialogue = 11011831,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"110034:n(110043)"}},
LookAt{_delay{2},LookAtDescription{"110034:n(110022)"}}
}]],
          SpeakNpcId = 110034,
          Subtitle = "The sewer tunnels are like a maze. You'd easily get lost without help. The Forsakens always get Mr Frank to fix the sewer valves, so he knows the place like the back of his hand. Let him live and he'll get you where you need to go.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110118/1B91245C"
        },
        [11011831] = {
          Camera = "-181.973633,-155.728516,141.303955,0.000168,-6.001311,124.018631,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "됐어. 마르코, 총 내려... 내리라고. 명령이다.",
          DialogueId = 11011831,
          ExStoryInfo = "EXPlayer",
          GUID = "1B912486",
          LookAt = {
            [1] = "110022:n(110016)",
            [2] = "110043:n(110022)"
          },
          NextDialogue = 11011832,
          Scripts = "SetLocation{ActorId{110034},TargetPoint{\"pKajiaset\"},Visibility{\"Show\"}}",
          SpeakNpcId = 110022,
          Subtitle = "Alright. Marco, lower your gun — Holster it, this is an order.",
          TurnTo = {
            [1] = "110016:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B912486"
        },
        [11011832] = {
          ContentKR = "레온, 몸수색해.",
          DialogueId = 11011832,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9124B0",
          LookAt = {
            [1] = "110022:n(110043)"
          },
          NextDialogue = 11011833,
          SpeakNpcId = 110022,
          Subtitle = "Leon, frisk him.",
          VoiceName = "voice/$Locale$/story/1002/110118/1B9124B0"
        },
        [11011833] = {
          Camera = "-335.610352,446.109375,125.748901,0.000156,-4.80109,-91.97982,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "알겠습니다!",
          DialogueId = 11011833,
          FacialId = {
            [1] = "110034:Sad01"
          },
          GUID = "1B9124DA",
          LookAt = {
            [1] = "110043:n(110034)"
          },
          NextDialogue = 11011834,
          Scripts = "SetLocation{ActorId{110034},TargetPoint{\"pKajiamove11\"},Visibility{\"Show\"}}",
          SpeakNpcId = 110043,
          Subtitle = "Yes, sir!",
          TalkActionId = {
            [1] = "110043:Agree"
          },
          TurnTo = {
            [1] = "110016:n(110034)"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B9124DA"
        },
        [11011834] = {
          Camera = "-400.358398,146.994141,125.597656,0.000137,-4.201385,-66.57859,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "......",
          DialogueId = 11011834,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
          GUID = "1B912504",
          LookAt = {
            [1] = "110022:n(110034)"
          },
          NextDialogue = 11011835,
          SpeakNpcId = 110022,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110118/1B912504"
        },
        [11011835] = {
          ContentKR = "며칠 전, 배가 아파서 잠시 쉬고 있었을 뿐인데 포세이큰 동맹 놈들이 채찍질하더군요. 죽어가던 저에게 할아버지가 물과 음식, 그리고 이 낡은 옷을 주셨고요.",
          DialogueId = 11011835,
          DisableMouth = 1,
          GUID = "1B91252E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11011835.T_Story_Recall_11011835'",
          NextDialogue = 11011836,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110034,
          Subtitle = "Just a few days ago, I had to take a break because my stomach was acting up, but those Forsaken rotters whipped me dozens of times and left me for dead. It was Mr Frank who gave me water, food, and this ragged robe to cover me up.",
          VoiceName = "voice/$Locale$/story/1002/110118/1B91252E"
        },
        [11011836] = {
          Camera = "-366.577148,190.160156,84.821045,0.000083,-15.39957,-74.754189,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "......",
          DialogueId = 11011836,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-366.577148,190.160156,84.821045,0.000078,-19.799494,-74.55323,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B912558",
          NextDialogue = 11011837,
          SpeakNpcId = 110022,
          Subtitle = "...",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/110118/1B912558"
        },
        [11011837] = {
          Camera = "-313.795898,108.09375,127.78833,0.000089,-2.19943,130.844772,35.000011,125.671875,false,Manual,2.8",
          ContentKR = "그 여자는 내버려둬.",
          DialogueId = 11011837,
          ExStoryInfo = "EXPlayer",
          GUID = "1B912582",
          LookAt = {
            [1] = "110022:n(110034)",
            [2] = "110034:n(110022)",
            [3] = "110017:n(110022)"
          },
          NextDialogue = 11011838,
          SpeakNpcId = 110022,
          Subtitle = "No need to frisk her.",
          VoiceName = "voice/$Locale$/story/1002/110118/1B912582"
        },
        [11011838] = {
          ContentKR = "예, 알겠습니다.",
          DialogueId = 11011838,
          GUID = "1B9125AC",
          NextDialogue = 11011839,
          Scripts = "SetLocation{ActorId{110034},TargetPoint{\"pKajiamove11\"},Visibility{\"Show\"}}",
          SpeakNpcId = 110043,
          Subtitle = "Yes, sir.",
          TalkActionId = {
            [1] = "110043:Agree"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B9125AC"
        },
        [11011839] = {
          Camera = "-331.882812,3.074219,121.966187,0.000118,-1.199463,-90.33371,35.000019,244.838531,false,Manual,2.8",
          ContentKR = "노인장, 하수도 길에 익숙하시다고 하니 안내를 부탁하죠.",
          DialogueId = 11011839,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9125D6",
          LookAt = {
            [1] = "110017:n(110022)"
          },
          NextDialogue = 11011840,
          Scripts = "PlayAnimation{_delay{6},ActorId{110017},AnimationId{\"Agree\"},Duration{2}}",
          SpeakNpcId = 110022,
          Subtitle = "I've heard you're familiar with these sewers. Please lead the way then.",
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B9125D6"
        },
        [11011840] = {
          Camera = "410.171875,-492.808594,467.956604,0.000058,-23.799349,145.841736,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "너희는 다른 포로들이 허튼수작 못 부리게 잘 지키고 있어. 근처에 수상한 움직임이 있으면 바로 철수하고.",
          DialogueId = 11011840,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "644.256836,-651.65625,592.720764,0.000058,-23.799349,145.841736,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1B912600",
          SpeakNpcId = 110022,
          Subtitle = "Stay alert and keep a close watch on them. If anything seems amiss, we pull out immediately.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110118/1B912600"
        },
        [11011841] = {
          ContentKR = "가만히 있어! 움직이지 말라는 말 못 들었어?",
          DialogueId = 11011841,
          Duration = 3,
          GUID = "1B91262A",
          NextDialogue = 11011842,
          SpeakNpcId = 110015,
          Subtitle = "Behave! Captain's orders — no sudden moves or funny business, alright?"
        },
        [11011842] = {
          ContentKR = "하지만 움직이지 않으면... 길을 안내할 수 없는걸요...",
          DialogueId = 11011842,
          Duration = 3,
          GUID = "1B912654",
          NextDialogue = 11011843,
          SpeakNpcId = 110034,
          Subtitle = "But if I'm not allowed to move, how am I supposed to lead the way...?"
        },
        [11011843] = {
          ContentKR = "아, 그렇네.",
          DialogueId = 11011843,
          Duration = 3,
          GUID = "1B91267E",
          NextDialogue = 11011844,
          SpeakNpcId = 110015,
          Subtitle = "Right, you have a point there."
        },
        [11011844] = {
          ContentKR = "그렇게 경계하지 않아도 돼요. 평범한 카론도 사람이에요. 여러분처럼 저희도 모두 엄마가 있고 또 어서 돌아가 엄마를 만나고 싶은 마음 뿐이에요.",
          DialogueId = 11011844,
          Duration = 3,
          GUID = "1B9126A8",
          NextDialogue = 11011845,
          SpeakNpcId = 110034,
          Subtitle = "There's no need to so on guard. We Charons are ordinary people too, with families we're desperate to see again."
        },
        [11011845] = {
          ContentKR = "...아아, 카지아...",
          DialogueId = 11011845,
          GUID = "1B9126D2",
          NextDialogue = 11011846,
          SpeakNpcId = 110017,
          Subtitle = "...*sigh* Katya..."
        },
        [11011846] = {
          ContentKR = "...대장님, 왜 저를 막으신 겁니까?!",
          DialogueId = 11011846,
          GUID = "1B9126FC",
          NextDialogue = 11011847,
          SpeakNpcId = 110016,
          Subtitle = "...Captain, why did you stop me!?"
        },
        [11011847] = {
          ContentKR = "모든 카론이 포세이큰 같이 적인 건 아니야. 아바르 중령님도 카론이잖아. 이 중 몇 명이 정말로 포세이큰 동맹 소속이라 해도 죽이는 것보단 살려 두는 게 더 쓸모 있을 거야.",
          DialogueId = 11011847,
          ExStoryInfo = "EXPlayer",
          GUID = "1B912726",
          NextDialogue = 11011848,
          SpeakNpcId = 110022,
          Subtitle = "Not all Charons are rebels from The Forsakens — Commander Avar is a Charon, remember? And even if they are, they'd be worth more to us alive."
        },
        [11011848] = {
          ContentKR = "...마음속에서 어떤 소리가 들리더라도 그것에 굴복하지 마라, 마르코. 충동에 사로잡히면 안돼.",
          DialogueId = 11011848,
          ExStoryInfo = "EXPlayer",
          GUID = "1B912750",
          SpeakNpcId = 110022,
          Subtitle = "...An inner voice might tell you otherwise, Marco, but don't listen to it. Don't let emotions cloud your judgment."
        },
        [11011849] = {
          Camera = "-206.832031,-274.033203,151.986694,0.000304,-7.786074,84.022697,30.000002,100000.0,false,DoNotOverride,22.0",
          ContentKR = "고마워요...",
          DialogueId = 11011849,
          Duration = 1,
          GUID = "1B91277A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          LookAt = {
            [1] = "110034:n(110022)"
          },
          NextDialogue = 11011850,
          SpeakNpcId = 110034,
          Subtitle = "Thank you...",
          VoiceName = "voice/$Locale$/story/1002/110118/1B91277A"
        },
        [11011850] = {
          Camera = "316.260742,671.15625,590.656799,0.000295,-32.38599,-125.777397,30.000002,100000.0,false,DoNotOverride,22.0",
          ContentKR = "나한테 말한 건가?",
          DialogueId = 11011850,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "248.001953,576.443359,518.394348,0.000295,-32.38599,-125.777397,30.000002,100000.0,false,DoNotOverride,22.0",
          GUID = "1B9127A4",
          NextDialogue = 11011851,
          SpeakNpcId = 110022,
          Subtitle = "You're talking to me?",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "110022:p(-150)"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B9127A4"
        },
        [11011851] = {
          Camera = "-178.519531,165.578125,130.494019,0.000272,-1.986786,-88.369873,35.000011,223.924484,false,Manual,4.0",
          ContentKR = "아까 몸수색을 하지 않으셨죠. 제국인이시면서도 카론 여자인 저의 존엄성을 지켜주신 것에 감사드리고 싶었어요.",
          DialogueId = 11011851,
          GUID = "1B9127CE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11011852,
          SpeakNpcId = 110034,
          Subtitle = "Yes. You didn't let your man frisk me, and I really appreciate it — it's rare to see an Imperial officer respect the dignity of a Charon girl like me.",
          VoiceName = "voice/$Locale$/story/1002/110118/1B9127CE"
        },
        [11011852] = {
          Camera = "-164.408203,79.375,128.996338,0.000276,-0.386739,-87.568512,39.0,140.506577,false,Manual,4.0",
          ContentKR = "은혜는 절대 잊지 않을게요.",
          DialogueId = 11011852,
          GUID = "1B9127F8",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "Your kindness will reap a just reward.",
          VoiceName = "voice/$Locale$/story/1002/110118/1B9127F8"
        },
        [11011901] = {
          Camera = "-144.767578,-92.228821,263.461792,0.000099,-22.001951,-14.432684,35.000023,62.085716,false,DoNotOverride,10.0",
          ContentKR = "...무슨 말씀이십니까? 지원이 늦을 거란 말입니까?",
          DialogueId = 11011901,
          Duration = 3,
          FinalCamera = "-215.302734,-74.076721,286.28595,0.0001,-22.001951,-14.432749,35.000023,62.085716,false,DoNotOverride,10.0",
          GUID = "1B913002",
          NextDialogue = 11011902,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 201015,
            [6] = 408007
          },
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_on\"},PlayAs2D{true}}",
          SpeakNpcId = 110010,
          Subtitle = "...What did you say!? The reinforcements are delayed!?",
          TalkActionId = {
            [1] = "110010:Call_Loop"
          },
          ToFinalCameraBlendTime = 0.3,
          VoiceName = "voice/$Locale$/story/1002/110119/1B913002"
        },
        [11011902] = {
          Camera = "224.40625,-305.362305,41.080444,-19.999933,31.393705,120.334618,18.0,215.299194,false,Manual,15.0",
          ContentKR = "'나르왈' 부대가 포세이큰 동맹 놈들의 작은 장난질에 당해서 다리 위에서 발이 묶였다.",
          DialogueId = 11011902,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          FinalCamera = "243.134766,-256.964966,50.642212,-19.999929,34.393909,140.333755,18.0,215.299194,false,Manual,15.0",
          GUID = "1B91302C",
          NextDialogue = 11011903,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "The Forsakens sabotaged the Narwhals at the bridge. Now we're stuck here.",
          ToFinalCameraBlendTime = 16,
          VoiceName = "voice/$Locale$/story/1002/110119/1B91302C"
        },
        [11011903] = {
          ContentKR = "얼마 남지도 않은 이 병력으로 중앙 관제실을 뚫으란 겁니까? 풀비스 대령님, 무슨 잠꼬대를 하는 겁니까. 거긴 <H>미스트 새도우</>의 <H>연락책</>이 버티고 있습니다!",
          DialogueId = 11011903,
          Duration = 3,
          GUID = "1B913056",
          NextDialogue = 11011904,
          RelatedWikiId = {
            [1] = 101004
          },
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6.5},TargetPosition{"252.482422,-28.591492,307.02533,0.000023,-41.604187,-127.463921,30.0,257.429108,false,DoNotOverride,15.0"},duration{0}},
CameraMoveTo{TargetPosition{"274.126953,-47.164124,307.02533,0.000027,-41.60405,-137.662704,30.0,257.429108,false,DoNotOverride,15.0"},duration{12}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "You expect me to break into the central control room with just two battered squads and directly confront their Messenger? You can't be serious, Fulvis. The enemies are Daimons, and god knows how many more ambushes lie ahead!",
          VoiceName = "voice/$Locale$/story/1002/110119/1B913056"
        },
        [11011904] = {
          Camera = "193.941406,-262.665161,172.085999,0.000077,-6.004569,117.326279,35.0,77.099098,false,Manual,15.0",
          ContentKR = "연락책이든 뭐든 상관없다. 군단이 너희 같은 '다이몬'들을 먹여 주고 재워 주는 건 이런 결정적인 순간을 위해서일 텐데? 게다가, 너희 쪽엔 '다이몬'에 맞먹는 {nickname2}도 있지 않나?",
          DialogueId = 11011904,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "190.306641,-252.121216,171.00824,0.000077,-6.004569,117.326279,35.0,77.099098,false,Manual,15.0",
          GUID = "1B913080",
          NextDialogue = 11011905,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "So what if they are Daimons? You're one too! Besides, don't you have  on your side, who's as strong as any Daimon?",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110119/1B913080"
        },
        [11011905] = {
          Camera = "-76.609375,-108.222046,132.998901,0.000015,1.195543,0.126938,12.0,77.099098,false,Manual,15.0",
          ContentKR = "중앙 관제실은 지금 너희가 있는 4호 포대에서 50m도 안 떨어져 있을 것이다.",
          DialogueId = 11011905,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          FacialId = {
            [1] = "110010:Angry01"
          },
          FinalCamera = "-44.5625,-111.956238,132.312683,0.000015,1.195543,0.126938,12.0,77.099098,false,Manual,15.0",
          GUID = "1B9130AA",
          NextDialogue = 11011906,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "The central control room is just right ahead. It's less than fifty yards away from the Turret you're at.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110119/1B9130AA"
        },
        [11011906] = {
          Camera = "257.480469,-189.943848,143.340332,-0.0,8.794633,169.723068,40.0,77.099098,false,Manual,15.0",
          ContentKR = "50미터만 더 전진하면 승리를 폐하께 바칠 수 있는데, 뭐가 그리 어려운 거지?",
          DialogueId = 11011906,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          FinalCamera = "245.064453,-188.491089,146.559082,-0.0,8.794633,169.723068,40.0,77.099098,false,Manual,15.0",
          GUID = "1B9130D4",
          NextDialogue = 11011907,
          Scripts = "PlayNormalSound{_delay{8},EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}}",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "Fifty yards further, and we can dedicate the victory to His Majesty! What's so hard about that?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110119/1B9130D4"
        },
        [11011907] = {
          Camera = "245.064453,-188.491089,146.559082,-0.0,8.794633,169.723068,40.0,77.099098,false,Manual,15.0",
          ContentKR = "......",
          DialogueId = 11011907,
          Duration = 1,
          FacialId = {
            [1] = "110010:None"
          },
          GUID = "1B9130FE",
          LookAt = {
