PlayAnimation{_delay{1},ActorId{110009},AnimationId{"Talk02_End"},Duration{1}}, 
PlayAnimation{_delay{4},ActorId{110009},AnimationId{"Confident_Start"},Duration{4}}
},
SEQ{
CameraMoveTo{_delay{1.5},TargetPosition{"50.555542,84.171387,71.75116,5.000197,8.604228,-107.607498,15.610331,100000.0,false,Manual,22.0"},duration{0}},
