          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/110124/1B9186A2"
        },
        [11012430] = {
          ContentKR = "우리 정보원 말로는 우리 위대하신 창백의 사신님께서는 최근 몇 년을 빼고는 기억이 싹 사라지셨다고, 어디서 온 누구인지 자신도 모른다고 했던가?",
          DialogueId = 11012430,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9186CC",
          NextDialogue = 11012431,
          Scripts = [[
PARA{
PlayAnimation{_delay{2},ActorId{110009},AnimationId{"Think_Start"},Duration{13}},
SEQ{
CameraMoveTo{_delay{5.01},TargetPosition{"68.789917,-13.603516,81.309998,0.000153,24.602831,-104.008942,35.0,100000.0,false,DoNotOverride,22.0"},duration{0}},
