        [11012435] = {
          Camera = "24.656494,7.404297,190.805542,-0.002769,-61.608364,102.005478,15.610328,100000.0,false,Manual,22.0",
          ContentKR = "<W>머리 아파 죽겠지? 저 미친 여자가 지껄이는 말이 피에 굶주린 거머리처럼 네 두개골과 뇌를 갉아 먹고 있거든.</>",
          DialogueId = 11012435,
          DisableMouth = 1,
