          GUID = "1B918A92",
          LookAt = {
            [1] = "110022:n(110015)"
          },
          NextDialogue = 11012454,
          Scripts = "MoveTo{ActorId{110015},TargetPoint{\"BP_Fix14Move02\"},MoveSpeed{80},Visibility{\"Show\"}}",
