          Camera = "132.141647,116.539062,60.872101,-15.005561,5.400951,-79.810699,35.000011,570.333496,false,DoNotOverride,20.0",
          ContentKR = "난 거기 꽉 막힌 늙은이들이랑은 달라서 말이야. 실용주의자는 쓸 수만 있다면 방법을 가리지 않지.",
          DialogueId = 11013603,
          Duration = 3,
          FinalCamera = "132.141647,116.539062,52.458649,-15.005593,5.400944,-79.810684,35.000011,570.333496,false,DoNotOverride,20.0",
          GUID = "1B92473E",
          NextDialogue = 11013604,
          SpeakNpcId = 110011,
          Subtitle = "I'm nothing like those stubborn old fools. I'm a pragmatist and would do anything that works.",
          TalkActionId = {
            [1] = "110011:DisagreeHead"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110136/1B92473E"
