          FinalCamera = "165.08638,2264.316406,568.964294,-0.001626,-67.592896,61.591228,39.663486,100000.0,false,Manual,22.0",
          GUID = "1B924768",
          LookAt = {
            [1] = "110011:n(110010)"
          },
          NextDialogue = 11013605,
          SpeakNpcId = 110011,
          Subtitle = "Isn't this your favourite protege? You did this?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924768"
