        [11014206] = {
          Camera = "268.478882,-80.285156,118.874451,0.000069,6.200179,118.608635,42.218384,149.297455,false,Manual,4.0",
          ContentKR = "...제가 확인해야겠어요. 그냥 중상일 수도 있어요. 그쪽으론 제가 전문가라고요...",
          DialogueId = 11014206,
          GUID = "1B92AA2C",
          NextDialogue = 11014207,
          SpeakNpcId = 110005,
          Subtitle = "...I have to check on him myself. Maybe he's just heavily wounded... As a medic, I can probably...",
          TalkActionId = {
