        [11014420] = {
          Camera = "182.500244,280.225098,23.764893,0.000076,0.00127,-168.670517,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentKR = "하지만 제가 아무리 치료해도 동료들은 이미 대부분 치명상을 입어서 결국 모두 구할 수 없었어요. 정말 우습지 않나요...\n그토록 가장 완벽한 공격을 적이 아닌 동료에게 가하다니요!",
          DialogueId = 11014420,
          FacialId = {
            [1] = "110005:Sad01"
          },
          GUID = "1B92CD48",
          NextDialogue = 11014421,
          SpeakNpcId = 110005,
          Subtitle = "But it was too late for most. They all suffered precise, fatal shots — ironically from our own men rather than the enemies.",
          TalkActionId = {
            [1] = "110005:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CD48"
        },
        [11014421] = {
          Camera = "11.563477,253.448242,41.453857,0.0,-1.000336,-159.073059,44.319668,100000.0,false,DoNotOverride,22.0",
          ContentKR = "이게 제가 알고 있는 전부예요... 이제 당신 차례예요, 중앙 관제실에서 무슨 일이 있었는지 말씀해 주세요.",
          DialogueId = 11014421,
          FacialId = {
            [1] = "110005:Unacceptable01"
          },
          GUID = "1B92CD72",
          NextDialogue = 11014422,
          SpeakNpcId = 110005,
          Subtitle = "That's all I know... Now, tell me what happened in the central control room.",
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CD72"
        },
        [11014422] = {
          Camera = "-156.207275,-25.750488,52.009644,0.000024,-6.59982,73.919052,35.000011,498.109375,false,Manual,22.0",
          ContentKR = "지금은 말해줄 수 없습니다, 하지만 언젠가는 말해 주겠다고 약속하죠.",
          DialogueId = 11014422,
          ExStoryInfo = "EXPlayer",
          GUID = "1B92CD9C",
          NextDialogue = 11014423,
          Scripts = "PlayAnimation{_delay{2},ActorId{110022},AnimationId{\"DisagreeHead\"},Duration{2}}",
          SpeakNpcId = 110022,
          Subtitle = "I'll explain later, now isn't the right time.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CD9C"
        },
        [11014423] = {
          Camera = "-121.629395,166.033203,40.3479,0.000025,-1.599514,54.320049,35.000011,498.109375,false,Manual,22.0",
          ContentKR = "하지만 당신 판단이 틀린 건 아닙니다. 지금 이 요새 안에 있는 병사들은 전부 적이라고 봐야겠죠. 풀비스 명령에 따라 우릴 죽이고 비밀을 지키려 할 게 분명합니다.",
          DialogueId = 11014423,
          ExStoryInfo = "EXPlayer",
          GUID = "1B92CDC6",
          NextDialogue = 11014424,
          Scripts = "PlayAnimation{_delay{2},ActorId{110022},AnimationId{\"Explain02_Start\"},Duration{2}}",
          SpeakNpcId = 110022,
          Subtitle = "But you were right about the situation — every soldier in this fortress is now our enemy. Fulvis has ordered them to eliminate us.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CDC6"
        },
        [11014424] = {
          ContentKR = "풀비스가... 포세이큰 동맹에 계획을 누설한 배신자였군요. 그 인간 때문에 우리가 많은 피를 본 거였어요.",
          DialogueId = 11014424,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Unhappy02"
          },
          GUID = "1B92CDF0",
          NextDialogue = 11014425,
          SpeakNpcId = 110022,
          Subtitle = "Fulvis... He's the despicable traitor who leaked our plans to The Forsakens. He's the one who decimated our squads.",
          TalkActionId = {
            [1] = "110022:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CDF0"
        },
        [11014425] = {
          Camera = "24.118896,279.948242,42.161743,0.000046,-3.600493,-154.483551,35.000011,498.106201,false,Manual,22.0",
          ContentKR = "......",
          DialogueId = 11014425,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unacceptable01"
          },
          GUID = "1B92CE1A",
          NextDialogue = 11014426,
          SpeakNpcId = 110005,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CE1A"
        },
        [11014426] = {
          Camera = "-121.629395,166.033203,40.3479,0.000025,-1.599514,54.320049,35.000011,498.109375,false,Manual,22.0",
          ContentKR = "이제 괜찮아졌습니다. 고맙습니다. 약효가 좋군요.",
          DialogueId = 11014426,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:None"
          },
          GUID = "1B92CE44",
          LookAt = {
            [1] = "110005:n(110022)"
          },
          NextDialogue = 11014427,
          SpeakNpcId = 110022,
          Subtitle = "Thanks to your medicine, I'm feeling much better.",
          TalkActionId = {
            [1] = "110022:AgreeHead",
            [2] = "110005:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CE44"
        },
        [11014427] = {
          Camera = "93.17627,284.239258,43.509888,0.000075,-3.800051,-161.083466,35.000011,498.106201,false,Manual,22.0",
          ContentKR = "좋아요. 당신이 지금 말하고 싶지 않다면, 그럴 만한 이유가 있다고 믿겠어요. 다만, 한 가지만 대답해 주실 수 있나요?",
          DialogueId = 11014427,
          FacialId = {
            [1] = "110005:Sad02"
          },
          GUID = "1B92CE6E",
          NextDialogue = 11014428,
          SpeakNpcId = 110005,
          Subtitle = "Fine. You must have your own reasons for withholding the information. But there's one thing I must know—",
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CE6E"
        },
        [11014428] = {
          Camera = "24.118896,279.948242,42.161743,0.000046,-3.600493,-154.483551,35.000011,498.106201,false,Manual,22.0",
          ContentKR = "<Highlight>제 아버지</>... 아바르는... 임무를 완수하셨나요?",
          DialogueId = 11014428,
          Duration = 1,
          GUID = "1B92CE98",
          NextOptions = {
            [1] = 11014429
          },
          Scripts = "CameraMoveTo{_delay{4},TargetPosition{\"-50.351318,192.186523,25.357666,0.000096,10.599087,-179.679947,46.347988,498.106201,false,Manual,22.0\"},duration{0}}",
          SpeakNpcId = 110005,
          Subtitle = "My father... Avar... Did he complete his mission?",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CE98"
        },
        [11014429] = {
          ContentKR = "완수하셨습니다.",
          DialogueId = 11014429,
          GUID = "1B92CEC2",
          NextDialogue = 11014430,
          Subtitle = "He did."
        },
        [11014430] = {
          Camera = "-40.314697,258.415039,36.010864,0.000067,0.599554,-141.683044,31.485687,498.106201,false,Manual,22.0",
          ContentKR = "...아, 고마워요.",
          DialogueId = 11014430,
          Duration = 1,
          FacialId = {
            [1] = "110005:Smile01"
          },
          GUID = "1B92CEEC",
          NextDialogue = 11014431,
          SpeakNpcId = 110005,
          Subtitle = "...Thank you.",
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CEEC"
        },
        [11014431] = {
          Camera = "7.207031,193.45166,173.61792,0.000137,-45.79509,179.723953,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentKR = "잘 가요, 아빠.",
          DialogueId = 11014431,
          Duration = 1,
          FacialId = {
            [1] = "110005:Sad01"
          },
          FinalCamera = "46.467285,193.266113,213.983521,0.000137,-45.79509,179.723953,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1B92CF16",
          NextDialogue = 11014432,
          Scripts = "LookAt{LookAtDescription{\"110005:p(P11014401)\"}}",
          SpeakNpcId = 110005,
          Subtitle = "Farewell, Dad.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CF16"
        },
        [11014432] = {
          Camera = "825.23584,-925.32959,105.616943,0.000043,-7.198575,129.922852,35.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "갑시다. 우리가 살아있는 한, 언젠가는 풀비스에게 이 빚을 갚을 수 있을 겁니다.",
          DialogueId = 11014432,
          Duration = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B92CF40",
          LookAt = {
            [1] = "110005:n(110022)"
          },
          SpeakNpcId = 110022,
          Subtitle = "Let's go. So long as we're alive, we'll find a chance to make Fulvis pay.",
          TalkActionId = {
            [1] = "110022:Talk02_Start",
            [2] = "110005:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110144/1B92CF40"
        },
        [11014601] = {
          ContentKR = "다프네 세오도어와 정체불명의 조력자가 하수도로 숨어들었다. 지금 1번 저수조 근처에 있다.",
          DialogueId = 11014601,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B92EAFA",
          NextDialogue = 11014602,
          SnapShot = "BROADCAST",
          SpeakNpcId = 110012,
          Subtitle = "Daphne Theodore and an unknown accomplice are currently hiding in the sewers near Reservoir 1.",
          VoiceName = "voice/$Locale$/story/1002/110146/1B92EAFA"
        },
        [11014602] = {
          ContentKR = "1번 저수조로 물을 방류해서 밖으로 나오게 만들어라!",
          DialogueId = 11014602,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B92EB24",
          NextDialogue = 11014603,
          SnapShot = "BROADCAST",
          SpeakNpcId = 110012,
          Subtitle = "Initiate the flooding of Reservoir 1 to force them out.",
          VoiceName = "voice/$Locale$/story/1002/110146/1B92EB24"
        },
        [11014603] = {
          ContentKR = "결국 들켰네요... 이곳이 물에 잠기기 전에 빠져나가야 해요!",
          DialogueId = 11014603,
          Duration = 3,
          GUID = "1B92EB4E",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 110005,
          Subtitle = "They found us... We need to get out before this section floods completely!",
          VoiceName = "voice/$Locale$/story/1002/110146/1B92EB4E"
        },
        [11014701] = {
          ContentKR = "현재 수위가 기준치보다 높아 안전문을 가동할 수 없습니다. 수위를 조절한 후 다시 시도하세요.",
          DialogueId = 11014701,
          Duration = 3,
          GUID = "1B92FB62",
          NextDialogue = 11014702,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Current water level exceeds safety threshold. Safety gate will remain closed. Reduce water level to reopen.",
          VoiceName = "voice/$Locale$/story/1002/110147/1B92FB62"
        },
        [11014702] = {
          ContentKR = "주입 장치는 놈들이 통제하고 있는데... 하지만 여긴 저수조니까 분명 배수 장치가 있을 거예요!",
          DialogueId = 11014702,
          Duration = 3,
          GUID = "1B92FB8C",
          NextDialogue = 11018915,
          SpeakNpcId = 110005,
          Subtitle = "They're controlling the inlets... But since this is a reservoir, it must also have drainage outlets.",
          VoiceName = "voice/$Locale$/story/1002/110147/1B92FB8C"
        },
        [11014803] = {
          ContentKR = "멀리 못 갔을 거다! 남은 필토이드들도 지하로 몰아넣어!",
          DialogueId = 11014803,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B930C1E",
          NextDialogue = 11014804,
          SnapShot = "BROADCAST",
          SpeakNpcId = 110012,
          Subtitle = "They can't be far! Herd the remaining Filthoids into the tunnels!",
          VoiceName = "voice/$Locale$/story/1002/110148/1B930C1E"
        },
        [11014804] = {
          ContentKR = "모든 지하 출구를 봉쇄하고, 반역자들이 나오면 즉시 처형해.",
          DialogueId = 11014804,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B930C48",
          NextDialogue = 11014805,
          SnapShot = "BROADCAST",
          SpeakNpcId = 110012,
          Subtitle = "Seal all exits. Once they surface, we'll eliminate the traitors.",
          VoiceName = "voice/$Locale$/story/1002/110148/1B930C48"
        },
        [11014805] = {
          ContentKR = "시간이 얼마 없으니 서둘러!",
          DialogueId = 11014805,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B930C72",
          NextDialogue = 11014806,
          SnapShot = "BROADCAST",
          SpeakNpcId = 110012,
          Subtitle = "Hurry up! We're running out of time!",
          VoiceName = "voice/$Locale$/story/1002/110148/1B930C72"
        },
        [11014806] = {
          ContentKR = "...우리도 서두르죠!",
          DialogueId = 11014806,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B930C9C",
          SpeakNpcId = 110022,
          Subtitle = "...We should hurry up too!",
          VoiceName = "voice/$Locale$/story/1002/110148/1B930C9C"
        },
        [11014901] = {
          ContentKR = "수위가 낮아졌어요!",
          DialogueId = 11014901,
          Duration = 3,
          GUID = "1B931C32",
          SpeakNpcId = 110005,
          Subtitle = "The water's receding!",
          VoiceName = "voice/$Locale$/story/1002/110149/1B931C32"
        },
        [11015001] = {
          ContentKR = "마지막 밸브 하나 남았어요!",
          DialogueId = 11015001,
          Duration = 3,
          GUID = "1B932C9A",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 110005,
          Subtitle = "Just one more valve!",
          VoiceName = "voice/$Locale$/story/1002/110150/1B932C9A"
        },
        [11015101] = {
          Camera = "5.064453,-47.199432,146.200714,0.000109,-3.600404,17.225021,35.0,100000.0,false,Manual,22.0",
          ContentKR = "일단은 안전한 것 같네요...",
          DialogueId = 11015101,
          Duration = 3,
          FinalCamera = "29.699219,-39.826668,144.779388,0.000113,-2.00018,14.432239,35.0,100000.0,false,Manual,22.0",
          GUID = "1B933D02",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11015102,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 201016,
            [6] = 408007,
            [7] = 101004
          },
          SpeakNpcId = 110005,
          Subtitle = "We should be safe for now...",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933D02"
        },
        [11015102] = {
          ContentKR = "저 앞이 출구일 거예요. 하지만...",
          DialogueId = 11015102,
          Duration = 3,
          GUID = "1B933D2C",
          NextDialogue = 11015103,
          SpeakNpcId = 110005,
          Subtitle = "The exit should be up ahead, but...",
          VoiceName = "voice/$Locale$/story/1002/110151/1B933D2C"
        },
        [11015103] = {
          Camera = "184.916016,-61.012665,145.951035,0.000085,-1.799372,155.628265,35.0,100000.0,false,Manual,22.0",
          ContentKR = "놈들이 매복해 있을 겁니다.",
          DialogueId = 11015103,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "207.275391,-71.141312,146.722122,0.000085,-1.799372,155.428955,35.0,100000.0,false,Manual,22.0",
          GUID = "1B933D56",
          NextDialogue = 11015104,
          SpeakNpcId = 110022,
          Subtitle = "They're definitely waiting to ambush us there.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933D56"
        },
        [11015104] = {
          Camera = "50.191406,-61.684036,121.714935,0.000108,8.400572,23.04035,35.0,100000.0,false,Manual,22.0",
          ContentKR = "상처가 이렇게 깊은데, 우리에게... 승산이 있을까요... 그리고 요새에서 탈출한다고 해도, 군단이 우릴 가만두지 않을 텐데... 추적과 암살 시도가 계속될 거예요...",
          DialogueId = 11015104,
          Duration = 3,
          FinalCamera = "32.810547,-69.076233,118.901154,0.000109,7.400571,23.039328,35.0,100000.0,false,Manual,22.0",
          GUID = "1B933D80",
          NextOptions = {
            [1] = 11015105,
            [2] = 11015107,
            [3] = 11015110
          },
          Scripts = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{\"Explain02_End\"},Duration{2}}",
          SpeakNpcId = 110005,
          Subtitle = "You're heavily wounded... Is there any chance of us escaping this place...? Even if we make it out, the Legion will hunt us down... We'll be fugitives forever, constantly dodging assassins...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933D80"
        },
        [11015105] = {
          ContentKR = "그럼 하수도에서 평생 사는 수밖에 없겠군요.",
          DialogueId = 11015105,
          GUID = "1B933DAA",
          ImprPlusId = 1010,
          NextDialogue = 11015106,
          Subtitle = "Maybe we should just live in the sewers forever."
        },
        [11015106] = {
          Camera = "39.349609,-74.855362,160.701706,0.000115,-7.799802,25.839321,35.0,100000.0,false,Manual,22.0",
          ContentKR = "하지만 여긴 음식과 옷이 없는... 아니지, 같이 제대로 된 방법을 생각해 보자니까요!",
          DialogueId = 11015106,
          Duration = 3,
          FinalCamera = "23.103516,-82.726669,163.175507,0.000116,-8.599856,25.63818,35.0,100000.0,false,Manual,22.0",
          GUID = "1B933DD4",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11015111,
          SpeakNpcId = 110005,
          Subtitle = "But this place doesn't have enough food or clothing — Please, let us figure something out!",
          TalkActionId = {
            [1] = "110005:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933DD4"
        },
        [11015107] = {
          ContentKR = "나가서 놈들과 목숨 걸고 싸우는 겁니다.",
          DialogueId = 11015107,
          GUID = "1B933DFE",
          ImprPlusId = 1007,
          NextDialogue = 11015108,
          Subtitle = "We should just head out and fight to the death."
        },
        [11015108] = {
          Camera = "39.349609,-74.855362,160.701706,0.000115,-7.799802,25.839321,35.0,100000.0,false,Manual,22.0",
          ContentKR = "안 돼요... 당신이 있다고 해도, 부상이 심해서 힘들 거예요...",
          DialogueId = 11015108,
          Duration = 3,
          FinalCamera = "23.103516,-82.726669,163.175507,0.000116,-8.599856,25.63818,35.0,100000.0,false,Manual,22.0",
          GUID = "1B933E28",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11015109,
          SpeakNpcId = 110005,
          Subtitle = "No... You might be a skilled soldier, but you're heavily wounded. We wouldn't stand a chance...",
          TalkActionId = {
            [1] = "110005:DisagreeHead"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933E28"
        },
        [11015109] = {
          ContentKR = "...다른 방법은 없을까요...",
          DialogueId = 11015109,
          Duration = 3,
          GUID = "1B933E52",
          NextDialogue = 11015111,
          SpeakNpcId = 110005,
          Subtitle = "...Do you have another idea...?",
          VoiceName = "voice/$Locale$/story/1002/110151/1B933E52"
        },
        [11015110] = {
          ContentKR = "...진정해요. 반드시 방법이 있을 겁니다.",
          DialogueId = 11015110,
          GUID = "1B933E7C",
          ImprPlusId = 1009,
          NextDialogue = 11015111,
          Subtitle = "...Let's take a deep breath. We'll come up with something."
        },
        [11015111] = {
          Camera = "184.492188,-49.928711,137.304932,0.000086,2.99945,161.84729,35.0,100000.0,false,Manual,22.0",
          ContentKR = "......",
          DialogueId = 11015111,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "200.958984,-55.329666,136.396576,0.000086,1.799379,162.846802,35.0,100000.0,false,Manual,22.0",
          GUID = "1B933EA6",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11015112,
          SpeakNpcId = 110022,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110022:Think_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933EA6"
        },
        [11015112] = {
          ContentKR = "겉옷을 벗으세요.",
          DialogueId = 11015112,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B933ED0",
          NextDialogue = 11015113,
          SpeakNpcId = 110022,
          Subtitle = "Take off your clothes.",
          TalkActionId = {
            [1] = "110022:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B933ED0"
        },
        [11015113] = {
          Camera = "-17.943359,-63.457489,146.000702,0.000093,-3.202395,18.475502,35.0,100000.0,false,Manual,22.0",
          ContentKR = "네?",
          DialogueId = 11015113,
          Duration = 3,
          FinalCamera = "-0.720703,-57.570724,144.94313,0.000094,-3.00238,17.275826,35.0,100000.0,false,Manual,22.0",
          GUID = "1B933EFA",
          NextDialogue = 11015114,
          SpeakNpcId = 110005,
          Subtitle = "What?",
          TalkActionId = {
            [1] = "110005:Shock04_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933EFA"
        },
        [11015114] = {
          Camera = "489.007812,-334.206299,292.918701,0.000068,-19.202305,139.670319,35.0,100000.0,false,Manual,22.0",
          ContentKR = "저와 옷을 바꿔 입자고요.",
          DialogueId = 11015114,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "445.892578,-297.610748,273.224854,0.000065,-19.402313,139.27037,35.0,100000.0,false,Manual,22.0",
          GUID = "1B933F24",
          NextDialogue = 11015115,
          SpeakNpcId = 110022,
          Subtitle = "We're switching outfits.",
          TalkActionId = {
            [1] = "110022:Talk02_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933F24"
        },
        [11015115] = {
          ContentKR = "놈들은 제가 중앙 관제실에서 죽은 줄 압니다. 지금 당신과 함께 있는 사람이 누군지 몰라요. 저쪽에서 확인할 수 있는 타깃은 당신뿐이죠.",
          DialogueId = 11015115,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B933F4E",
          NextDialogue = 11015116,
          SpeakNpcId = 110022,
          Subtitle = "They think I died in the central control room and they have no idea who your accomplice is. You are the only target they can identify.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B933F4E"
        },
        [11015116] = {
          ContentKR = "제가 당신인 척하고 밖으로 나가겠습니다. 의무관 제복은 눈에 잘 띄니까 놈들을 유인할 수 있을 테니 그때 어떻게든 빠져나가세요.",
          DialogueId = 11015116,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B933F78",
          NextDialogue = 11015117,
          Scripts = "PlayAnimation{_delay{3},ActorId{110022},AnimationId{\"Talk02_End\"},Duration{2}}",
          SpeakNpcId = 110022,
          Subtitle = "I'll wear your uniform and make a run out there. The medic's uniform is conspicuous enough to draw their attention. You'll make your escape during the chaos.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B933F78"
        },
        [11015117] = {
          Camera = "30.167969,-51.420792,112.9972,0.000112,8.79729,16.678789,35.0,100000.0,false,Manual,22.0",
          ContentKR = "지금... 농담하는 거죠? 체형이 달라서 금방 발각될 거라고요!",
          DialogueId = 11015117,
          Duration = 3,
          FinalCamera = "49.683594,-45.570618,123.095779,0.000108,7.997291,16.280628,35.0,100000.0,false,Manual,22.0",
          GUID = "1B933FA2",
          NextDialogue = 11015118,
          Scripts = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{\"Shock04_End\"},Duration{2}}",
          SpeakNpcId = 110005,
          Subtitle = "Are you serious? We're completely different sizes! They'll quickly realise they're chasing the wrong person!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933FA2"
        },
        [11015118] = {
          Camera = "174.623047,-31.802631,151.059662,0.000112,-2.002987,168.472702,35.0,100000.0,false,Manual,22.0",
          ContentKR = "저들에게 혼란을 주면 당신이 도망갈 시간을 1초라도 더 벌 수 있을 겁니다. 다프네, 교관님 유언을 따르셔야 합니다.",
          DialogueId = 11015118,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "182.253906,-34.744297,148.60463,0.000112,-1.403016,167.073715,35.0,100000.0,false,Manual,22.0",
          GUID = "1B933FCC",
          SpeakNpcId = 110022,
          Subtitle = "The longer I can distract them, the better your chances. This is the plan, Daphne. Honour Sir Avar's last wishes.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933FCC"
        },
        [11015119] = {
          ContentKR = "망설일 시간 없습니다. 어서요.",
          DialogueId = 11015119,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B933FF6",
          SpeakNpcId = 110022,
          Subtitle = "Don't hesitate, hurry up.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B933FF6"
        },
        [11015120] = {
          ContentKR = "...안 돼요.",
          DialogueId = 11015120,
          Duration = 2,
          GUID = "1B934020",
          SpeakNpcId = 110005,
          Subtitle = "...No.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934020"
        },
        [11015121] = {
          ContentKR = "아버지의 바람을 기억해 줘서 고마워요.",
          DialogueId = 11015121,
          Duration = 3,
          GUID = "1B93404A",
          SpeakNpcId = 110005,
          Subtitle = "Thank you for respecting my father's wish.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93404A"
        },
        [11015122] = {
          ContentKR = "혹시 <Highlight>제 바람</>도 들어 주실 수 있나요?",
          DialogueId = 11015122,
          Duration = 3,
          GUID = "1B934074",
          SpeakNpcId = 110005,
          Subtitle = "But could you at least hear my wishes?",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934074"
        },
        [11015123] = {
          ContentKR = "디즈마니아엔 비가 자주 내려요. 제가 아주 어렸을 때, 제 친구들은 비 때문에 예쁘게 빗은 머리카락이 젖고 깨끗한 새 치마가 더러워진다며, 모두 비를 싫어했죠.",
          DialogueId = 11015123,
          Duration = 3,
          FacialId = {
            [1] = "110005:Sad01"
          },
          GUID = "1B93409E",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11015124,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 201016,
            [6] = 408007,
            [7] = 101004
          },
          SpeakNpcId = 110005,
          Subtitle = "Dismania is a rainy place. When I was a little girl, all my friends hated the rain because it would mess with their hair and soil their pretty dresses.",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B93409E"
        },
        [11015124] = {
          ContentKR = "하지만 전 아니었어요. 제 어깨에는 빗방울이 닿지 않았거든요.\n제가 보는 비는 장화 아래에서 튀고, 우산 끝에서 떨어지는 물방울이 전부였어요.",
          DialogueId = 11015124,
          Duration = 3,
          GUID = "1B9340C8",
          NextDialogue = 11015125,
          SpeakNpcId = 110005,
          Subtitle = "But I didn't hate the rain, because it never reached my shoulders. In my eyes, the rain was just little ripples sprouting around my boots and droplets dripping off the brolly.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9340C8"
        },
        [11015125] = {
          ContentKR = "좀 크고 난 후에야 제가 비를 좋아하는 게 아니었다는 걸 깨달았어요. 어릴 땐 아빠가 곁에서 대신 비를 맞아 주신 거였죠.",
          DialogueId = 11015125,
          Duration = 3,
          GUID = "1B9340F2",
          NextDialogue = 11015126,
          SpeakNpcId = 110005,
          Subtitle = "But as I grew older, I realised that rain wasn't that nice. It used to look nice, only because my dad was there to bear it for me.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9340F2"
        },
        [11015126] = {
          ContentKR = "아빠는 무뚝뚝하셨지만 정말 좋은 분이셨어요. 하지만 평생 남을 챙기느라 자신은 돌보지 않으셨죠, 평생을요.",
          DialogueId = 11015126,
          Duration = 3,
          GUID = "1B93411C",
          NextDialogue = 11015128,
          SpeakNpcId = 110005,
          Subtitle = "My dad is such a kind man, and such a stubborn one too. He always put others first. Always.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93411C"
        },
        [11015127] = {
          ContentKR = "......",
          DialogueId = 11015127,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934146",
          NextDialogue = 11015128,
          SpeakNpcId = 110022,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934146"
        },
        [11015128] = {
          ContentKR = "아빠는 제가 태어나기 전에 엄마에게 '어울리는 사람'이 되기 위해 군단에 들어가 생사를 넘나들며 싸우셨고, 제가 크고 나선 '제 앞길에 방해가 되지 않기' 위해 저와 엄마 곁을 떠나셨죠.",
          DialogueId = 11015128,
          Duration = 3,
          GUID = "1B934170",
          NextDialogue = 11015129,
          SpeakNpcId = 110005,
          Subtitle = "Before I was born, he joined the Legion and fought hard to prove himself worthy of my mom. After I grew up, he left us because he didn't want to \"soil my future.\"",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934170"
        },
        [11015129] = {
          ContentKR = "...길에서 마주치면 냉정한 얼굴로 아빠라고도 못 부르게 하고선, 깊은 밤 술집에서 저와 엄마 이름을 부르며 술에 취해 울던 분이셨어요.\n얼마나 위대한 아버지인가요, 늘 혼자서 모든 걸 짊어지시다니...",
          DialogueId = 11015129,
          Duration = 3,
          GUID = "1B93419A",
          NextDialogue = 11015130,
          SpeakNpcId = 110005,
          Subtitle = "...In public, he'd scowl and forbid me to call him Dad. But deep in the night, he'd drunkenly shout mine and my mother's name, crying — He was always bearing the weight of everything on his own...",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93419A"
        },
        [11015130] = {
          ContentKR = "하지만, 아빠는 그 모든 걸 제가 원하는지 묻지 않으셨어요... 지금 당신처럼요. 당신도 제가 당신 목숨을 밟고 살아남길 원하는지 물어보지 않았다고요!",
          DialogueId = 11015130,
          Duration = 3,
          GUID = "1B9341C4",
          SpeakNpcId = 110005,
          Subtitle = "But he never asked if I wanted any of this... Just like you never asked if I wanted to live knowing you sacrificed yourself for me!",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9341C4"
        },
        [11015131] = {
          Camera = "74.1875,-11.549334,140.752075,0.000139,2.317531,0.270602,35.0,100000.0,false,Manual,22.0",
          ContentKR = "당신이나 아빠는 몰라요... 저는 한 번도 비바람을 대신 막아 줄 사람을 원한 적 없어요. 내가 정말 원하는 건...",
          DialogueId = 11015131,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unhappy01"
          },
          GUID = "1B9341EE",
          NextDialogue = 11015132,
          SpeakNpcId = 110005,
          Subtitle = "Neither of you know what I actually wanted... I never wished for a hero who'd shield me from the rain. My wish is that...",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9341EE"
        },
        [11015132] = {
          Camera = "74.1875,-11.549334,140.752075,0.000139,2.317531,0.270602,35.0,100000.0,false,Manual,22.0",
          ContentKR = "비바람을 막아 줄 우산이, 오직 한 사람만 지킬 수 있다면, 전 모두와 함께 빗속으로 들어가겠어요.",
          DialogueId = 11015132,
          Duration = 3,
          FinalCamera = "54.34375,-11.712122,143.421494,0.000139,-0.282503,0.470605,35.0,100000.0,false,Manual,22.0",
          GUID = "1B934218",
          NextDialogue = 11015133,
          SpeakNpcId = 110005,
          Subtitle = "If there's only room for one under the brolly, I'll brave the rain with you all.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934218"
        },
        [11015133] = {
          ContentKR = "제가 바라는 건, <Highlight>당신과 함께</> 살아남는 거예요.",
          DialogueId = 11015133,
          Duration = 3,
          FacialId = {
            [1] = "110005:Smile01"
          },
          GUID = "1B934242",
          NextDialogue = 11015134,
          SpeakNpcId = 110005,
          Subtitle = "I wish that we make it out and live on, together.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934242"
        },
        [11015134] = {
          Camera = "148.310547,4.638587,138.830399,0.000143,6.517544,-170.927872,35.0,100000.0,false,Manual,22.0",
          ContentKR = "다프네...",
          DialogueId = 11015134,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "160.496094,6.583258,134.802444,0.000143,6.317535,-170.927872,35.0,100000.0,false,Manual,22.0",
          GUID = "1B93426C",
          NextDialogue = 11015135,
          SpeakNpcId = 110022,
          Subtitle = "Daphne...",
          TalkActionId = {
            [1] = "110005:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93426C"
        },
        [11015135] = {
          Camera = "54.921875,23.440533,140.073502,0.000153,1.11843,-18.329687,35.0,100000.0,false,Manual,22.0",
          ContentKR = "다시 한번 잘 생각해 보죠... 분명 방법이 있을 거예요!",
          DialogueId = 11015135,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unhappy01"
          },
          FinalCamera = "70.310547,18.636772,139.925446,0.000152,2.918505,-16.931318,35.0,100000.0,false,Manual,22.0",
          GUID = "1B934296",
          NextDialogue = 11015136,
          SpeakNpcId = 110005,
          Subtitle = "Let's think together… There has to be another way!",
          TalkActionId = {
            [1] = "110005:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934296"
        },
        [11015136] = {
          Camera = "-35.435547,164.474655,360.730713,0.000111,20.917017,-153.732254,35.0,100000.0,false,Manual,22.0",
          ContentKR = "현재 상황을 정리해 보죠. 풀비스는 우리 입을 막는 게 목적이에요. 그래서 우리한테 스파이라는 누명을 씌워서 군단이 우릴 쫓고 있고, 결국 우릴 죽이려고 하고 있죠...",
          DialogueId = 11015136,
          Duration = 3,
          FinalCamera = "-35.435547,164.474655,327.571594,0.000111,20.717014,-153.73233,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9342C0",
          NextDialogue = 11015137,
          SpeakNpcId = 110005,
          Subtitle = "Fulvis wants us silenced. That's our situation. He's labelled us as spies so that our fellow soldiers would kill us for him...",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9342C0"
        },
        [11015137] = {
          ContentKR = "'그리핀'과 '스노우 울프' 두 선발대에 우리 둘만 남았고, 요새에 있는 병사는 전부 풀비스와 그의 부관인 펄시의 지시를 따르죠... 요새에 있는 병사...",
          DialogueId = 11015137,
          Duration = 3,
          GUID = "1B9342EA",
          NextDialogue = 11015138,
          Scripts = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{\"Think_End\"},Duration{2}}",
          SpeakNpcId = 110005,
          Subtitle = "We're the only ones left from the Griffins and Snow Wolves. Every soldier here follows Fulvis and his adjutant Falsi... Every soldier in the fortress...",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9342EA"
        },
        [11015138] = {
          Camera = "43.673828,56.272556,139.847488,0.000149,0.117582,-27.726179,35.0,100000.0,false,Manual,22.0",
          ContentKR = "잠깐, 생각났어요...! 아버지가 말씀하신 게 있거든요. \"이 보 전진을 위해 일 보 후퇴를 하고, 위험 속에서 기회를\n찾아라\"라고요...",
          DialogueId = 11015138,
          Duration = 3,
          FacialId = {
            [1] = "110005:Confident01"
          },
          FinalCamera = "58.037109,42.618416,142.168106,0.000149,1.317605,-24.925119,35.0,100000.0,false,Manual,22.0",
          GUID = "1B934314",
          NextDialogue = 11015139,
          SpeakNpcId = 110005,
          Subtitle = "Wait, I have an idea...! Father once said a strategic retreat could be a cover for an advance. Sometimes the greatest risks lead to victory.",
          TalkActionId = {
            [1] = "110005:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934314"
        },
        [11015139] = {
          Camera = "7.253906,20.019621,143.611893,0.00015,-1.08212,-15.727008,35.0,100000.0,false,Manual,22.0",
          ContentKR = "다른 선택지도 있는데... 호랑이 굴에 스스로 들어가는 거죠.",
          DialogueId = 11015139,
          Duration = 3,
          GUID = "1B93433E",
          NextOptions = {
            [1] = 11015140,
            [2] = 11015142
          },
          Scripts = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{\"Explain01_End\"},Duration{2}}",
          SpeakNpcId = 110005,
          Subtitle = "We still have one option... We can turn ourselves in.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93433E"
        },
        [11015140] = {
          ContentKR = "풀비스를 찾아가겠다는 겁니까?",
          DialogueId = 11015140,
          GUID = "1B934368",
          NextDialogue = 11015141,
          Subtitle = "You want to surrender to Fulvis?"
        },
        [11015141] = {
          Camera = "52.292969,25.010664,127.544891,0.000135,6.718037,-16.930437,35.0,100000.0,false,Manual,22.0",
          ContentKR = "아니요, 풀비스 말고 <Highlight>다른 사람</>요...",
          DialogueId = 11015141,
          Duration = 3,
          GUID = "1B934392",
          NextDialogue = 11015145,
          SpeakNpcId = 110005,
          Subtitle = "No, not to Fulvis. To someone else...",
          TalkActionId = {
            [1] = "110005:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B934392"
        },
        [11015142] = {
          ContentKR = "다른 사람...이라고요?",
          DialogueId = 11015142,
          GUID = "1B9343BC",
          NextDialogue = 11015143,
          Subtitle = "Turn ourselves in... to someone else?"
        },
        [11015143] = {
          Camera = "52.292969,25.010664,127.544891,0.000135,6.718037,-16.930437,35.0,100000.0,false,Manual,22.0",
          ContentKR = "네!",
          DialogueId = 11015143,
          Duration = 3,
          GUID = "1B9343E6",
          NextDialogue = 11015145,
          SpeakNpcId = 110005,
          Subtitle = "Exactly!",
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B9343E6"
        },
        [11015145] = {
          Camera = "52.292969,25.010664,127.544891,0.000135,6.718037,-16.930437,35.0,100000.0,false,Manual,22.0",
          ContentKR = "펄시가 한 말 기억해요?",
          DialogueId = 11015145,
          Duration = 3,
          FinalCamera = "48.234375,29.943214,125.579117,0.000142,6.717955,-19.329165,35.0,100000.0,false,Manual,22.0",
          GUID = "1B93443A",
          NextDialogue = 11015146,
          SpeakNpcId = 110005,
          Subtitle = "Remember what Falsi said in the broadcast?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93443A"
        },
        [11015146] = {
          ContentKR = "모든 지하 출구를 봉쇄하고, 반역자들이 나오면 즉시 처형해.",
          DialogueId = 11015146,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B934464",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014415.T_Story_Recall_11014415'",
          NextDialogue = 11015147,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SpeakNpcId = 110012,
          Subtitle = "Seal all exits. Once they surface, we'll eliminate the traitors.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934464"
        },
        [11015147] = {
          ContentKR = "시간이 얼마 없으니 서둘러!",
          DialogueId = 11015147,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B93448E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014413.T_Story_Recall_11014413'",
          NextDialogue = 11015148,
          SpeakNpcId = 110012,
          Subtitle = "Hurry up! We're running out of time!",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93448E"
        },
        [11015148] = {
          Camera = "-171.576172,354.275269,321.845215,0.000118,-24.091339,-52.323902,35.0,100000.0,false,Manual,22.0",
          ContentKR = "지금 풀비스가 론샤 요새를 장악하고 있으니, 우릴 잡는 건 시간문제인데 펄시는 왜 서둘렀을까요?",
          DialogueId = 11015148,
          Duration = 3,
          FinalCamera = "-196.277344,386.265381,339.917847,0.000119,-24.091339,-52.323936,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9344B8",
          NextDialogue = 11015149,
          SpeakNpcId = 110005,
          Subtitle = "Lonza Fortress is currently under Fulvis's full control. We're little more than rats in a cage. Then why is Falsi in such a hurry?",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9344B8"
        },
        [11015149] = {
          ContentKR = "아까 제가 어떤 병사가 하는 말을 몰래 들었다고 했잖아요.",
          DialogueId = 11015149,
          Duration = 3,
          GUID = "1B9344E2",
          NextDialogue = 11015150,
          SpeakNpcId = 110005,
          Subtitle = "Do you remember what I overheard earlier from one of the soldiers—",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9344E2"
        },
        [11015150] = {
          ContentKR = "게다가 전황이 좋지 않아 시빌라 군단장님도 론샤 요새로 오고 계십니다.",
          DialogueId = 11015150,
          Duration = 3,
          FacialId = {
            [1] = "110005:None"
          },
          GUID = "1B93450C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014415.T_Story_Recall_11014415'",
          NextDialogue = 11015151,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_Npc_EnemySoldier",
          Subtitle = "Chief Sibylle is en route to Lonza Fortress after hearing the battle has turned.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93450C"
        },
        [11015151] = {
          Camera = "154.445312,44.61274,163.534317,0.000121,-6.890936,-151.527649,35.0,100000.0,false,Manual,22.0",
          ContentKR = "...그러니까, 시빌라 군단장을 만나 보호를 요청하겠단 말입니까?",
          DialogueId = 11015151,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "177.171875,56.903561,166.748993,0.000123,-8.491031,-151.927643,35.0,100000.0,false,Manual,22.0",
          GUID = "1B934536",
          NextDialogue = 11015152,
          SpeakNpcId = 110022,
          Subtitle = "...So you want to seek protection from Sibylle?",
          TalkActionId = {
            [1] = "110022:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934536"
        },
        [11015152] = {
          Camera = "31.996094,51.468288,139.671326,0.000175,-0.491391,-24.739786,35.0,100000.0,false,Manual,22.0",
          ContentKR = "맞아요.",
          DialogueId = 11015152,
          Duration = 3,
          GUID = "1B934560",
          NextDialogue = 11015153,
          SpeakNpcId = 110005,
          Subtitle = "Correct.",
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B934560"
        },
        [11015153] = {
          Camera = "179.789062,39.516891,181.891464,0.000178,-14.491817,-158.539825,35.0,100000.0,false,Manual,22.0",
          ContentKR = "하지만 풀비스가 거짓 증거까지 준비해서 죄명을 마련해 뒀... 잠깐, 방금 얘기한 '호랑이 굴'에 들어가는 작전이 그 뜻이었군요.",
          DialogueId = 11015153,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B93458A",
          NextDialogue = 11015154,
          SpeakNpcId = 110022,
          Subtitle = "But Fulvis has already condemned us and even fabricated evidence... Wait, I get why you want to turn ourselves in.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93458A"
        },
        [11015154] = {
          Camera = "42.076172,35.060333,133.820343,0.000195,2.508544,-21.337816,35.0,100000.0,false,Manual,22.0",
          ContentKR = "네! 시빌라 군단장도 연금원 출신이에요. 제가 아는 그분이라면 어떠한 배반도 용납하지 않을 거예요. 설령 그게 가장 가까운 사람이더라도요.",
          DialogueId = 11015154,
          Duration = 3,
          FacialId = {
            [1] = "110005:Confident01"
          },
          FinalCamera = "28.144531,40.503914,129.73497,0.000195,2.508482,-21.537373,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9345B4",
          NextDialogue = 11015155,
          SpeakNpcId = 110005,
          Subtitle = "Mm-hmm! Chief Sibylle is also a graduate of the Academy. From what I know of her, she wouldn't tolerate betrayal from anyone, not even those she holds dear.",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9345B4"
        },
        [11015155] = {
          Camera = "-191.923828,110.773376,292.437317,0.000252,-26.092831,-22.740551,35.0,100000.0,false,Manual,22.0",
          ContentKR = "...하지만 그렇기 때문에 신중히 심문할 거예요. 용의자를 함부로 죽여서 단서가 끊어지게 두지 않을 거란 말이죠.",
          DialogueId = 11015155,
          Duration = 3,
          FinalCamera = "-139.972656,126.843193,222.647064,0.000272,-16.892361,-30.148384,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9345DE",
          NextDialogue = 11015156,
          SpeakNpcId = 110005,
          Subtitle = "...Which is also why Sibylle would carefully review any acts of treason. She would not make any hasty decisions to execute the suspects because she'd want to get to the bottom of it.",
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9345DE"
        },
        [11015156] = {
          ContentKR = "시빌라 군단장을 만나면, 우린 군교도소에 갇힐 가능성이 커요. 듣기로는 경계가 아주 삼엄해서 새 한 마리도 빠져나갈 수 없대요. 하지만 오히려 그렇기 때문에 우리를 해치려는 모든 위험도 들어올 수 없겠죠.",
          DialogueId = 11015156,
          Duration = 3,
          GUID = "1B934608",
          NextDialogue = 11015157,
          SpeakNpcId = 110005,
          Subtitle = "If we manage to meet her, she's most likely to throw us into the Imperial Prison. The Prison is reputedly so well guarded that even a fly could not escape the place. But it'll also keep out anyone who wishes to silence us.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934608"
        },
        [11015157] = {
          ContentKR = "오히려 그곳이 가장 안전한 장소가 될 거예요. 그리고 심문 과정에서 우리의 무죄를 증명하는 게, 우리가 살아남을 유일한 기회예요.",
          DialogueId = 11015157,
          Duration = 3,
          GUID = "1B934632",
          NextDialogue = 11015158,
          SpeakNpcId = 110005,
          Subtitle = "The Imperial Prison will be our safest refuge. We can prove our innocence during interrogations. This is our only chance to survive.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934632"
        },
        [11015158] = {
          Camera = "47.939453,49.246361,119.444901,0.000288,8.907598,-26.339521,35.0,100000.0,false,Manual,22.0",
          ContentKR = "문제는 스파이 혐의로 심문을 받으면 당신 명예에 큰 오점이 남는다는 거죠... 하지만 심문만 잘 견디면, 우리의 결백을 증명하고 진범을 처벌할 수 있을 거예요.",
          DialogueId = 11015158,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unacceptable01"
          },
          FinalCamera = "27.193359,59.519375,115.815987,0.000286,7.707581,-26.338728,35.0,100000.0,false,Manual,22.0",
          GUID = "1B93465C",
          NextDialogue = 11015159,
          SpeakNpcId = 110005,
          Subtitle = "Your reputation will suffer though, as you'll be interrogated for espionage... But once we endure the questioning, we will be able to clear our names and bring the real traitors to justice.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93465C"
        },
        [11015159] = {
          Camera = "243.919922,32.791145,139.274689,0.00031,-0.492122,-160.143555,35.0,100000.0,false,Manual,22.0",
          ContentKR = "...스파이 혐의로 심문을 받으면... 그 사실이 군단 밖으로, 예를 들면... 황실에 전해질 수도 있겠습니까?",
          DialogueId = 11015159,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "259.697266,38.494522,139.446808,0.000309,-1.092161,-160.143555,35.0,100000.0,false,Manual,22.0",
          GUID = "1B934686",
          NextDialogue = 11015160,
          SpeakNpcId = 110022,
          Subtitle = "...Being questioned for espionage... Any chance that word gets out beyond the Legion? Perhaps the royal family will hear of this?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934686"
        },
        [11015160] = {
          Camera = "49.503906,51.240067,154.416092,0.000309,-5.89185,-28.343378,35.0,100000.0,false,Manual,22.0",
          ContentKR = "율리우스 폐하는 늘 군사를 중시하시고, 제13군단을 직접 창설하셨으니까... 그럴 수 있겠죠.",
          DialogueId = 11015160,
          Duration = 3,
          FacialId = {
            [1] = "110005:None"
          },
          FinalCamera = "49.503906,51.240067,138.708191,0.000309,0.108293,-28.74304,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9346B0",
          NextDialogue = 11015161,
          RelatedWikiId = {
            [1] = 201018
          },
          SpeakNpcId = 110005,
          Subtitle = "The army has always been the focus of Emperor Julius. Moreover, His Majesty personally founded the 13th Legion. I believe it will reach his ears...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9346B0"
        },
        [11015161] = {
          Camera = "132.001953,71.535721,136.665466,0.000171,6.118688,-133.138336,35.0,100000.0,false,Manual,22.0",
          ContentKR = "...그렇다면, <Highlight>그 사람</>이 도움이 될 수도 있겠군요.",
          DialogueId = 11015161,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "143.138672,83.421745,135.787506,0.000172,4.518669,-132.938339,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9346DA",
          NextDialogue = 11015162,
          Scripts = "PlayAnimation{_delay{2},ActorId{110022},AnimationId{\"Think_End\"},Duration{2}}",
          SpeakNpcId = 110022,
          Subtitle = "Then perhaps... that person can help us.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9346DA"
        },
        [11015162] = {
          ContentKR = "좋아요, 당신 말대로 하죠. 시빌라를 찾아갑시다.",
          DialogueId = 11015162,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934704",
          SpeakNpcId = 110022,
          Subtitle = "Alrigh, let's go with your plan and find Sibylle.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B934704"
        },
        [11015163] = {
          ContentKR = "망설일 시간 없어요. 어서 가요!",
          DialogueId = 11015163,
          Duration = 3,
          GUID = "1B93472E",
          SpeakNpcId = 110005,
          Subtitle = "Time's against us. Let's move!",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93472E"
        },
        [11015201] = {
          ContentKR = "그래서 전 다프네의 손을 잡고 문틈 사이로 비치는 빛을 향해 걸어갔습니다.",
          DialogueId = 11015201,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934D6A",
          NextDialogue = 11015202,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "And thus, I took her hand and we stepped towards that narrow beam of sunlight piercing through the door's gap.",
          VoiceName = "voice/$Locale$/story/1002/110152/1B934D6A"
        },
        [11015202] = {
          ContentKR = "마치 찬란하게 빛나는 무덤으로 발을 내딛는 기분이었죠.",
          DialogueId = 11015202,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934D94",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "It felt as though we were stepping into a shimmering grave of our own making...",
          VoiceName = "voice/$Locale$/story/1002/110152/1B934D94"
        },
        [11015203] = {
          ContentKR = "우린 마지막 힘을 다해 추격자를 따돌리고, 막 요새에 도착한 시빌라 군단장을 찾아갔습니다.",
          DialogueId = 11015203,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934DBE",
          NextDialogue = 11015204,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "We expended our last ounces of strength evading our pursuers, in time to meet Chief Sibylle, who had just arrived at the fortress.",
          VoiceName = "voice/$Locale$/story/1002/110152/1B934DBE"
        },
        [11015204] = {
          ContentKR = "그리고 다프네가 예상한 대로, 이곳에 압송된 겁니다.",
          DialogueId = 11015204,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934DE8",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "And just as Daphne had predicted, we were escorted to this very place.",
          VoiceName = "voice/$Locale$/story/1002/110152/1B934DE8"
        },
        [11015301] = {
          Camera = "89.232414,-2.948067,11.488281,0.999996,-1.199982,-0.798315,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이야기는 흥미로웠다만 현장에 있던 '나르왈' 병사의 증언과는 완전 딴판이군. 넌 너와 아바르 헤데란이 무죄라고 주장하고 있지...",
          DialogueId = 11015301,
          Duration = 1,
          GUID = "1B935DD2",
          NextDialogue = 11019310,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 201019
          },
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{2.5},TargetPosition{"-93.449196,-7.990425,2.617188,0.0,1.599883,0.401891,35.000008,100000.0,false,DoNotOverride,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"-134.447235,-8.27565,1.480469,0.0,1.599883,0.401891,35.000008,100000.0,false,DoNotOverride,2.8"},duration{8}}
},
PlayOrStopBGM{PlayType{"Play"},
SoundType{"SOUND_BGM"},
EventPath{"event:/bgm/cbt02/0043_story_empire"}},
PlayAnimation{ActorId{110039},AnimationId{"Sit_Start"},Duration{1}}
}]],
          SpeakNpcId = 110039,
          Subtitle = "What a riveting story, which completely contradicts the testimonies provided by the Narwhals. Since you claim that you and Avar Hrodland are innocent—",
          TurnTo = {
            [1] = "110022:n(110039)"
          },
          VoiceName = "voice/$Locale$/story/1002/110153/1B935DD2"
        },
        [11015307] = {
          Camera = "175.138626,16.254257,-15.015625,0.000019,25.795355,-21.761339,25.000006,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...지금 자신이 무슨 말을 하고 있는지 알고 있는가?",
          DialogueId = 11015307,
          Duration = 3,
          GUID = "1B935ECE",
          NextDialogue = 11015308,
          SpeakNpcId = 110039,
          Subtitle = "...Do you have any idea what you just said?",
          VoiceName = "voice/$Locale$/story/1002/110153/1B935ECE"
        },
        [11015308] = {
          Camera = "389.865051,85.663879,11.320312,0.0,4.395124,-172.362595,25.000002,100000.0,false,DoNotOverride,2.8",
          ContentKR = "물론입니다. 전 지금 론샤 요새 사건의 진짜 배후, 안토니 풀비스를 정식으로 고발하는 겁니다.",
          DialogueId = 11015308,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Unhappy02"
          },
          FinalCamera = "378.377686,84.125763,12.214844,0.0,4.395124,-172.362595,25.000002,100000.0,false,DoNotOverride,2.8",
