        [11016619] = {
          ContentKR = "...{nickname2}, 내가 자랑스러워하는 제자야... 널 이런 일에 휘말리게 해서 미안하다.",
          DialogueId = 11016619,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94360E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016619.T_Story_Recall_11016619'",
