          DialogueId = 11016801,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9453EA",
          LookAt = {
            [1] = "110021:n(110040)",
            [2] = "110040:n(110021)",
            [3] = "110041:n(110040)"
          },
          NextDialogue = 11016802,
          RelatedWikiId = {
