        },
        [11016802] = {
          Camera = "164.65332,366.744141,129.46875,0.000159,-1.392819,123.993523,35.0,150.488785,false,DoNotOverride,22.0",
          ContentKR = "심문 중에도 계속 널 만나고 싶어하더군.",
          DialogueId = 11016802,
          FacialId = {
            [1] = "110041:Iyada01"
          },
          FinalCamera = "151.226562,386.651367,128.910156,0.000159,-1.392819,123.993523,35.0,150.488785,false,DoNotOverride,22.0",
          GUID = "1B945414",
          LookAt = {
            [1] = "110041:n(110021)"
          },
          NextDialogue = 11016803,
          Scripts = [[
SEQ{
SetLocation{ActorId{110005},TargetPoint{"fix27jt"},Visibility{"Hide"}},
}]],
          SpeakNpcId = 110021,
          Subtitle = "During her interrogation, she repeatedly requested to see you.",
          TalkActionId = {
            [1] = "110041:Sit_Idle_Loop"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110168/1B945414"
        },
        [11016803] = {
          DialogueId = 11016803,
          DialoguePanelType = "None",
          Duration = 3,
          FinalCamera = "57.932617,221.332031,127.285156,0.000213,-1.992188,-91.39418,35.0,150.488785,false,DoNotOverride,22.0",
          GUID = "1B94543E",
          IsBlack = 1,
