        },
        [11018402] = {
          Camera = "-114.378906,-14.172058,128.482971,-1.0,1.597315,-43.841934,18.000004,100000.0,false,DoNotOverride,20.0",
          ContentKR = "그래, 지금 요새의 동력이 마비됐으니 우선 이 캐논을 옮길 방법을 찾아야 해.",
          DialogueId = 11018402,
          FinalCamera = "-116.232422,-16.133057,128.436096,-1.0,1.597315,-43.44199,18.000004,100000.0,false,DoNotOverride,20.0",
