          Duration = 4,
          GUID = "1B9600CB",
          NextDialogue = 11019421
        },
        [11019421] = {
          ContentKR = "그녀의 비웃음이 들려온다. 그녀는 한때 날 굳세고 강하다고 생각했지만, 지금 보니 과거에 자신이 재판했던 다른 죄수들과 전혀 다를 바가 없다.",
          DialogueId = 11019421,
          Duration = 4,
          GUID = "1B9600CC",
          NextDialogue = 11019422
        },
        [11019422] = {
          ContentKR = "내가 지금 칠흑 같은 심연에 떨어지고 있다는 걸 깨닫는다. 만약 그때 내 의지가 좀 더 굳건했다면, 지금과는 다른 결과가 나타났을까?",
          DialogueId = 11019422,
          Duration = 4,
          GUID = "1B9600CD"
        },
