          Duration = 2,
          GUID = "1E0B6C23",
          NextDialogue = 12001557,
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6C23"
        },
        [12001557] = {
          ContentKR = "이 검에 대한 소식을 알고 계신 분은 오늘 자정, 광장 앞 빨간색 전화부스로 가져다주십시오. 반드시 후한 보답을 드리겠습니다...",
          DialogueId = 12001557,
          Duration = 4,
          GUID = "1E0B6C24",
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6C24"
        },
        [12001601] = {
          ContentKR = "(잠깐 쉬어가자...)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001601,
          GUID = "1E0B74AA",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120016/1E0B74AA"
        },
