        },
        [12004101] = {
          ContentKR = "...와, 사람 진짜 많네. 다들 공연 보러 온 거야?",
          DialogueId = 12004101,
          GUID = "1E0AE102",
          NextDialogue = 12004102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE102"
        },
        [12004102] = {
          ContentKR = "사람들이 재밌는 얘기 하는 것 같아, 시종, 우리 가서 들어보자.",
          DialogueId = 12004102,
          GUID = "1E0D0EFC",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120041/1E0D0EFC"
        },
        [12004201] = {
          ContentKR = "지류 언니, 아스포델에 가서 누굴 만나려는 거야?",
          DialogueId = 12004201,
          GUID = "1E0D1F3A",
          NextDialogue = 12004202,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1F3A"
        },
        [12004202] = {
          ContentKR = "내가 한번 맞춰볼게... 혹시 황금빛 곱슬곱슬 머리하고, 말할 때마다 까칠까칠한 여사장님 아니야?",
          DialogueId = 12004202,
          GUID = "1E0D1F64",
          NextDialogue = 12004203,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1F64"
        },
        [12004203] = {
          ContentKR = "하하, 다 맞혔네.",
          DialogueId = 12004203,
          GUID = "1E0D1F8E",
          NextDialogue = 12004204,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1F8E"
        },
        [12004204] = {
          ContentKR = "이 마왕님은 당연히 모든 걸 다 알고 있지!",
          DialogueId = 12004204,
          GUID = "1E0D1FB8",
          NextDialogue = 12004205,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1FB8"
        },
        [12004205] = {
          ContentKR = "아, 그런데 방금 말한 거, 카밀라한테는 절대 말하지 마! 안 그럼 오늘 용돈 또 다 깎일 거야...",
          DialogueId = 12004205,
          GUID = "1E0D1FE2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1FE2"
        },
        [12004206] = {
          ContentKR = "도착했어~",
          DialogueId = 12004206,
          GUID = "1E0D200C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D200C"
        },
        [12004301] = {
          ContentKR = "루나가 식식거리며 달려갔다.",
          DialogueId = 12004301,
          Duration = 2,
          GUID = "1E0D2FA2",
          VoiceName = "voice/$Locale$/story/1200/120043/1E0D2FA2"
        },
        [12004401] = {
          ContentKR = "저쪽 기계들 좀 이상해... 음, 그냥 피하는 게 좋을 것 같아!",
          DialogueId = 12004401,
          GUID = "1E0D400A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120044/1E0D400A"
        },
        [12004402] = {
          ContentKR = "돌아갔어, 지금이야!",
          DialogueId = 12004402,
          GUID = "1E0D4034",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120044/1E0D4034"
        },
        [12004501] = {
          ContentKR = "<W>목표 발견. 목표 발견.</>",
          DialogueId = 12004501,
          GUID = "1E0D5072",
          NextDialogue = 12004502,
          VoiceName = "voice/$Locale$/story/1200/120045/1E0D5072"
        },
        [12004502] = {
          ContentKR = "와... 우리 행적이 들킨 것 같네!",
          DialogueId = 12004502,
          GUID = "1E0D509C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120045/1E0D509C"
        },
        [12004503] = {
          Content = "任务失败，请重新开始。",
          DialogueId = 12004503,
          GUID = "1E0D509D",
          SpeakNpcId = 200002
        },
        [12004504] = {
          Content = "被动失败",
          DialogueId = 12004504,
          GUID = "1E0D509E",
          SpeakNpcId = 200002
        },
        [12030001] = {
          ContentKR = "이것은 얼마 전, 아이스레이크 시티에서 있었던——",
          DialogueId = 12030001,
          Duration = 4,
          GUID = "1E1DA80A",
          NextDialogue = 12030002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA80A"
        },
        [12030002] = {
          ContentKR = "작은 나이팅게일 한 마리가 따스한 둥지를 벗어나, 용감하게 날아오르기로 마음먹는 이야기이다.",
          DialogueId = 12030002,
          Duration = 4,
          GUID = "1E1DA834",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA834"
        },
        [12030003] = {
          Content = "菲娜坐在家里，看着故事书",
          DialogueId = 12030003,
          GUID = "1E1DA85E",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA85E"
        },
        [12030101] = {
          Content = "菲娜，晚上光线太暗，看书伤眼睛，还是早点睡吧。",
          DialogueId = 12030101,
          GUID = "1E1DB872",
          NextDialogue = 12030102,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB872"
        },
        [12030102] = {
          Content = "唔……",
          DialogueId = 12030102,
          GUID = "1E1DB89C",
          NextDialogue = 12030103,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB89C"
        },
        [12030103] = {
          Content = "怎么了？",
          DialogueId = 12030103,
          GUID = "1E1DB8C6",
          NextDialogue = 12030104,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB8C6"
        },
        [12030104] = {
          Content = "奥特赛德，菲娜……菲娜有一个愿望！",
          DialogueId = 12030104,
          GUID = "1E1DB8F0",
          NextDialogue = 12030105,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB8F0"
        },
        [12030105] = {
          Content = "是吗？你说，是什么愿望？",
          DialogueId = 12030105,
          GUID = "1E1DB91A",
          NextDialogue = 12030106,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB91A"
        },
        [12030106] = {
          Content = "菲娜想出去看看。",
          DialogueId = 12030106,
          GUID = "1E1DB944",
          NextDialogue = 12030107,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB944"
        },
        [12030107] = {
          Content = "出去……？现在吗？",
          DialogueId = 12030107,
          GUID = "1E1DB96E",
          NextDialogue = 12030108,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB96E"
        },
        [12030108] = {
          Content = "不是的，菲娜的意思是，菲娜也想像你和独角兽{性别：先生|小姐}一样，去外面的世界，认识很多的新朋友……",
          DialogueId = 12030108,
          GUID = "1E1DB998",
          NextDialogue = 12030109,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB998"
        },
        [12030109] = {
          Content = "这可不行，外面很危险的。我和{nickname}大多数时候遇到的都不是朋友，而是秽——怪兽，和很多坏——坏巫师，对，那些坏巫师可吓人了。",
          DialogueId = 12030109,
          GUID = "1E1DB9C2",
          NextDialogue = 12030110,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB9C2"
        },
        [12030110] = {
          Content = "所以，你还是待在家里最安全。",
          DialogueId = 12030110,
          GUID = "1E1DB9EC",
          NextDialogue = 12030111,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB9EC"
        },
        [12030111] = {
          Content = "呜……",
          DialogueId = 12030111,
          GUID = "1E1DBA16",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DBA16"
        },
        [12030112] = {
          ContentKR = "밤, 피나의 집.\n피나는 잠들어 있고, 아웃사이더는 피나가 책상 위에 놓아둔 동화책을 발견한다.",
          DialogueId = 12030112,
          GUID = "1E1DBA40",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DBA40"
        },
        [12030201] = {
          Camera = "-345.501678,523.378906,124.574219,0.000322,-4.833527,90.822472,35.000008,77.550713,false,Manual,4.0",
          ContentKR = "\"대마법사는 늘 둥지 밖은 위험으로 가득하니, 둥지 안이 가장 안전하다고 말했어요. 하지만... 자그마한 둥지는 따스해도, 그 안에선 네모난 하늘 조각만 보일 뿐이었죠.\"",
          DialogueId = 12030201,
          FinalCamera = "-351.068237,428.320312,123.277344,0.000143,-3.242031,91.01268,35.000008,212.663025,false,Manual,2.8",
          GUID = "1E1DC8DA",
          LookAt = {
