          SpeakNpcId = 211001,
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1201/120114/1E2017CE"
        },
        [12033804] = {
          Camera = "31.312517,53.192848,143.547852,-18.000196,15.799729,27.200317,35.000008,112.97599,false,Manual,2.8",
          ContentKR = "이때, 밖으로 나갔던 강도들이 소리를 듣고 돌아온다.",
          DialogueId = 12033804,
          FinalCamera = "-462.511353,-198.426529,435.666016,-18.002155,-15.800631,31.003305,35.000008,296.476868,false,Manual,22.0",
          GUID = "1E2017F8",
          ToFinalCameraBlendTime = 2,
          TurnTo = {
