        [12034002] = {
          Camera = "-60.111835,138.167587,81.243164,0.000218,5.395651,-9.014689,25.0,255.333679,false,Manual,6.0",
          ContentKR = "세상엔 우리 눈엔 보이지 않는 무시무시한 괴물이 하나 있어. '편견'이란 괴물이지... 편견은 서로 사랑해야 할 사람들이 서로 미워하고, 상처입히게 만들어. 너희 부모님도 그 괴물한테 붙잡혀 버리신 거야.",
          DialogueId = 12034002,
          GUID = "1E203874",
          NextDialogue = 12034003,
          Scripts = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Explain02_Start\"}}",
