          },
          FinalCamera = "-56.127686,4.689941,50.209229,0.00031,5.598692,-20.219845,50.0,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B654",
          NextDialogue = 20000515,
          SpeakNpcId = 200024,
          Subtitle = "!!!",
          ToFinalCameraBlendTime = 0.2,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B654"
        },
        [20000515] = {
          Camera = "-1132.003174,-2957.388672,210.885498,0.000319,-1.000759,65.576195,27.995377,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(그녀는 검의 무늬에서 무언가를 읽으려는 듯 검을 자세히 들여다보았다.)",
          DialogueId = 20000515,
          DialoguePanelType = "Voiceover",
          DisableMouth = 1,
          Duration = 3,
          FinalCamera = "-1148.861572,-2949.662109,210.885498,0.000319,-1.000759,64.376427,27.995377,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B67E",
          NextDialogue = 20000516,
          Subtitle = "(She carefully examined the sword, attempting to glean some information from its pattern.)",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B67E"
        },
        [20000516] = {
          Camera = "-134.061523,50.801758,95.63208,0.000289,-10.201447,-24.418987,50.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "좋은 검, 좋은 검이야! 검의 재질이나 검을 만든 기술을 보아하니 휘페르보레아의 범재들이 만든 것은 아닐 테지. 자넨 나이도 어린데 어떻게 이런 보물을 얻은 거지?",
          DialogueId = 20000516,
          Duration = 2,
          FacialId = {
            [1] = "200024:Happy01"
          },
          GUID = "3211B6A8",
          NextDialogue = 20000517,
          SpeakNpcId = 200024,
          Subtitle = "Jesus! That's incredible! Look at the texture and the craftsmanship! This clearly wasn't made by those mediocre Hyperborean blacksmiths. Where did you get it?",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B6A8"
        },
        [20000517] = {
          Camera = "-197.926575,232.563965,156.319824,0.000096,-15.201227,-51.775345,50.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(이 루나 대장장이는 이 검이 예사롭지 않다고 생각하는 것 같다.)",
          DialogueId = 20000517,
          DialoguePanelType = "Voiceover",
          DisableMouth = 1,
          Duration = 2,
          GUID = "3211B6FC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20000518.T_Story_Recall_20000518'",
          LookAt = {
            [1] = "100001:p(200005Point2)"
          },
          NextDialogue = 20000519,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          Subtitle = "(The Luno blacksmith recognised that this sword was no ordinary weapon. )",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B6FC"
        },
        [20000519] = {
          Camera = "47.933167,48.183594,106.281372,0.000106,0.998942,164.023529,50.0,162.033707,false,Manual,14.755679",
          ContentKR = "잘 모르겠는데...",
          DialogueId = 20000519,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Uninterested01"
          },
          GUID = "3211B750",
          NextDialogue = 20000520,
          SpeakNpcId = 100001,
          Subtitle = "I'm not sure...",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B750"
        },
        [20000520] = {
          Camera = "47.933167,48.183594,106.281372,0.000106,0.998942,164.023529,50.0,162.033707,false,Manual,14.755679",
          ContentKR = "내가 어릴 적부터 쭉 이 검은 나와 함께였어. 어쩌면 부모님이 남겨주신 게 아닐까?",
          DialogueId = 20000520,
          Duration = 2,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "3211B77A",
          LookAt = {
            [1] = "200024:n(100001)"
          },
          NextDialogue = 20000522,
          SpeakNpcId = 100001,
          Subtitle = "I got it when I was young. Maybe it was passed down to me by my parents?",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B77A"
        },
        [20000522] = {
          Camera = "-189.288086,203.751465,151.934326,0.000147,-16.40097,-49.57642,50.000008,162.033707,false,Disable,14.755679",
          ContentKR = "재미있군, 재미있어. 평생 대장장이로 살아왔지만, 이 검을 만든 사람의 실력에는 미치지 못하는군.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000522,
          Duration = 3,
          FacialId = {
            [1] = "200024:Happy02"
          },
          GUID = "3211B7CE",
          NextDialogue = 20000523,
          SpeakNpcId = 200024,
          Subtitle = "Intriguing. Very intriguing. I've been a blacksmith my whole life, yet I've never seen a weapon like this before.",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B7CE"
        },
        [20000523] = {
          ContentKR = "젊은이, 나는 오랫동안 떠돌아다니며 정착할 곳이 없었네. 한동안 자네를 따라다녀도 괜찮겠는가?",
          DialogueId = 20000523,
          Duration = 3,
          FacialId = {
            [1] = "200024:Smile02"
          },
          GUID = "3211B7F8",
          NextDialogue = 20000524,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Kiddo, I'm Lunosmith, a wandering blacksmith. Would you mind if I accompanied you on your journey?",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B7F8"
        },
        [20000524] = {
          Camera = "-38.022217,110.633789,44.966553,0.000129,4.598534,-58.971298,50.000008,162.033707,false,Disable,14.755679",
          ContentKR = "휘페르보레아에서 엘리시안까지, 못 본 무기가 없고 안 만든 무기가 없지! 무기를 만들고 싶다면, 나에게 맡기게.",
          DialogueId = 20000524,
          Duration = 2,
          FinalCamera = "-38.022217,110.633789,46.349609,0.000129,4.598534,-58.971333,50.000008,162.033707,false,Disable,14.755679",
          GUID = "3211B822",
          NextDialogue = 20000525,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "I've travelled all over the land, from Hyperborea to Elysium, and I've forged countless weapons. If you require any weapons, I'm at your disposal.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B822"
        },
        [20000525] = {
          Camera = "232.871338,-185.234375,83.503784,0.000127,-5.002772,134.234024,60.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "우와, 대장장이셨구나!",
          DialogueId = 20000525,
          Duration = 3,
          FacialId = {
            [1] = "200025:Shock02"
          },
          GUID = "3211B84C",
          NextDialogue = 20000526,
          SpeakNpcId = 200025,
          Subtitle = "Wow! So you're an experienced master blacksmith!",
          TalkActionId = {
            [1] = "200025:SpecialHappy_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B84C"
        },
        [20000526] = {
          Camera = "-189.288086,203.751465,151.934326,0.000147,-16.40097,-49.57642,50.000008,162.033707,false,Disable,14.755679",
          ContentKR = "가격은 다른 대장장이들보다 저렴할 걸세. 하지만 내게 그 검을 연구할 시간을 좀 주게나. 하하.",
          DialogueId = 20000526,
          Duration = 2,
          FacialId = {
            [1] = "200024:Happy02"
          },
          GUID = "3211B876",
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "All I request is a basic salary, and an opportunity to examine your sword, hehe.",
          TalkActionId = {
            [1] = "200025:SpecialHappy_End"
          },
          TalkOptions = {
            [1] = 200005261,
            [2] = 200005262
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B876"
        },
        [20000528] = {
          Camera = "112.837646,-162.337891,36.354004,0.000129,8.798526,128.416595,50.000008,421.26944,false,Manual,6.435696",
          ContentKR = "허... 젊은이 표정을 보아하니, 이 늙은이를 의심하는구나.",
          DialogueId = 20000528,
          Duration = 3,
          FacialId = {
            [1] = "200024:Shock01"
          },
          FinalCamera = "114.166748,-161.282227,36.354004,0.000129,8.798526,128.416595,50.000008,421.26944,false,Manual,6.435696",
          GUID = "3211B8CA",
          LookAt = {
            [1] = "200024:n(100001)"
          },
          NextDialogue = 20000529,
          Scripts = "CameraMoveTo{_delay{3.5},TargetPosition{\"-257.094238,105.374512,89.299316,0.000146,-7.001647,-20.17968,50.000008,421.26944,false,Manual,6.435696\"},duration{0}}",
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Look, I can see scepticism written on your face.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B8CA"
        },
        [20000529] = {
          Camera = "-69.666748,-17.761719,56.248047,0.000116,1.798375,-8.383431,50.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "걱정하지 말게. '루나는 결코 먼저 다른 이를 해치지 않는다'. 이건 아트라시아 대륙의 모두가 알고 있는 사실이지.",
          DialogueId = 20000529,
          Duration = 2,
          FacialId = {
            [1] = "200024:Ahaha02"
          },
          FinalCamera = "-69.666748,-17.761719,57.486084,0.000116,1.798375,-8.383431,50.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B8F4",
          NextDialogue = 20000530,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "You can trust me. You must know the saying, \"Lunos never harm.\" Everyone in Atlasia knows that.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B8F4"
        },
        [20000530] = {
          Camera = "-257.729492,-42.183594,76.834473,0.000131,-5.203491,35.769909,50.0,290.309357,false,Manual,3.710212",
          ContentKR = "맞아 맞아!",
          DialogueId = 20000530,
          Duration = 3,
          FacialId = {
            [1] = "200025:Doubt01"
          },
          GUID = "3211B91E",
          LookAt = {
            [1] = "200025:n(100001)"
          },
          NextDialogue = 20000531,
          SpeakNpcId = 200025,
          Subtitle = "Yes, exactly!",
          TalkActionId = {
            [1] = "200025:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B91E"
        },
        [20000531] = {
          Camera = "-7.611328,-33.099121,102.976074,0.0,0.0,129.770859,35.0,211.517212,false,Manual,3.358988",
          ContentKR = "(그래, 루나인 스노우도 따뜻한 마음을 가졌으니까. 게다가 대장장이가 빈털털이인 우리 둘을 노릴 이유가 있을까?)",
          DialogueId = 20000531,
          DialoguePanelType = "Voiceover",
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "-15.199463,-23.983398,104.64917,0.0,0.0,129.770859,35.0,211.517212,false,Manual,3.358988",
          GUID = "3211B948",
          NextDialogue = 20000532,
          Subtitle = "(She was right. You could see that trait in Snow. Besides, what could she get from you? You have nothing to offer.)",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B948"
        },
        [20000532] = {
          Camera = "-2423.703857,1080.132324,250.907959,0.000098,-4.001944,-26.573547,60.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그래, 내 생각이 짧았네. 같이 가자.",
          DialogueId = 20000532,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Happy02"
          },
          GUID = "3211B972",
          NextDialogue = 20000533,
          SpeakNpcId = 100001,
          Subtitle = "Yeah, you're right. Let's head back together then.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B972"
        },
        [20000533] = {
          Camera = "-2423.703857,1080.132324,250.907959,0.000098,-4.001944,-26.573547,60.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "젊은이가 동의한 모양이군. 좋아, 좋아! 어서 자네들이 사는 곳으로 가자고!",
          DialogueId = 20000533,
          Duration = 3,
          FinalCamera = "-2421.345459,1084.854004,250.907959,0.000098,-4.001944,-26.573236,60.0,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B99C",
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "So you'll have me? Excellent! Then take me to where you live.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B99C"
        },
        [20000601] = {
          Camera = "-301.271454,-116.678955,97.078186,0.000381,-2.200953,30.000952,25.0,87.874474,false,Disable,2.8",
          ContentKR = "역시 대단해! 연륜은 못 속인다니까!",
          DialogueId = 20000601,
          Duration = 3,
          FacialId = {
            [1] = "200002:Shock02"
          },
          FinalCamera = "-298.339691,-121.755859,97.078186,0.000381,-2.200953,30.000952,25.0,87.874474,false,Disable,2.8",
          GUID = "3211C49A",
          LookAt = {
            [1] = "100001:n(200024)",
            [2] = "200002:n(200024)"
          },
          NextDialogue = 20000602,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"StoryCustom\"},SoundType{\"SOUND_BGM\"},SoundUnitKey{\"sidestory_tiejiangjiaojiao\"},EventPath{\"event:/bgm/cbt02/0041_story_jiaojiao_tiejiang\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Awesome! You're truly amazing!",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C49A"
        },
        [20000602] = {
          Camera = "-160.725159,-13.358643,119.220985,0.0,4.999999,-2.79654,35.0,142.092117,false,Manual,5.04021",
          ContentKR = "그러고 보니 길에서 스노우와 대장장이님이랑 비슷하게 생긴 사람들을 봤는데, 그 사람들도 <H>루나</>인 건가?",
          DialogueId = 20000602,
          Duration = 2,
          ExStoryInfo = "Player",
          FinalCamera = "-174.055298,-12.71582,117.098991,0.0,4.999999,-2.79654,35.0,142.092117,false,Manual,5.04021",
          GUID = "3211C4C4",
          LookAt = {
            [1] = "200024:n(100001)"
          },
          NextDialogue = 20000603,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.6},TargetPosition{"-275.118378,-120.86499,74.379753,0.000004,3.39987,31.806273,25.0,279.088654,false,Manual,1.419143"},duration{0}},
CameraMoveTo{_delay{4.7},TargetPosition{"-287.599518,-128.604248,69.15966,0.000004,3.39987,31.807192,25.0,279.088654,false,Manual,1.419143"},duration{4}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "I've seen many who resemble you and Snow. Are they also Lunos?",
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C4C4"
        },
        [20000603] = {
          Camera = "-4.034668,-120.357422,84.402077,0.00001,-0.800252,111.203094,25.0,279.088654,false,Manual,4.45866",
          ContentKR = "젊은이, 어디 외진 곳에서 왔나?",
          DialogueId = 20000603,
          Duration = 3,
          GUID = "3211C4EE",
          NextDialogue = 20000604,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Did you come from a remote village or something, kiddo?",
          VoiceName = "voice/$Locale$/story/2001/200006/3211C4EE"
        },
        [20000604] = {
          Camera = "172.062653,-1154.075806,143.87851,0.0,0.0,89.999985,25.0,200.0,false,Disable,2.8",
          ContentKR = "맞아... 내 고향은 번화했다고 보기엔 힘든 곳이야.",
          DialogueId = 20000604,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          FinalCamera = "172.062653,-1154.075806,164.062302,-0.0,-0.999987,89.999985,25.0,200.0,false,Disable,2.8",
          GUID = "3211C518",
          NextDialogue = 20000605,
          SpeakNpcId = 100001,
          Subtitle = "Yes, my hometown isn't a big city.",
          TalkActionId = {
            [1] = "100001:Sigh_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C518"
        },
        [20000605] = {
          Camera = "375.018433,-82.650635,97.525391,0.000002,-1.800014,165.397888,25.0,200.0,false,Disable,2.8",
          ContentKR = "하하, 어쩐지, 어쩐지. 이 늙은이가 머물렀던 곳은 말이야, 사람이 있는 곳엔 항상 루나가 있었지. 자네처럼 우리 일족을 본 적이 없는 아이는 많지 않아.",
          DialogueId = 20000605,
          Duration = 1.5,
          FacialId = {
            [1] = "200024:Ahaha02"
          },
          FinalCamera = "356.082672,-77.70874,94.312401,0.000002,-1.800014,165.397888,25.0,200.0,false,Disable,2.8",
          GUID = "3211C542",
          NextOptions = {
            [1] = 200006051
          },
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Ha, that explains it. In all my travels, wherever there are humans, Lunos can always be found. It's quite uncommon to come across someone like you who's never heard of us.",
          TalkActionId = {
            [1] = "100001:Sigh_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C542"
        },
        [20000606] = {
          Camera = "155.926254,-348.624268,84.660477,0.0,-0.799986,116.795898,25.0,200.0,false,Disable,2.8",
          ContentKR = "우리 루나는 모두 스노우처럼 귀엽고 긴 수명을 가지고 있어.",
          DialogueId = 20000606,
          Duration = 3,
          FacialId = {
            [1] = "200002:Confident01"
          },
          GUID = "3211C56C",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)",
            [3] = "200024:n(200002)"
          },
          NextDialogue = 20000607,
          SpeakNpcId = 200002,
          Subtitle = "We share a similar appearance. Everyone is as attractive as me. And we live very long lives.",
          TurnTo = {
            [1] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/2001/200006/3211C56C"
        },
        [20000607] = {
          Camera = "-55.37558,-141.429932,74.678345,0.000005,-1.600122,102.597961,25.0,136.939529,false,Manual,2.8",
          ContentKR = "그리고 여기 대장장이님처럼, 각자 잘하는 것이 있다구!",
          DialogueId = 20000607,
          Duration = 3,
          FacialId = {
            [1] = "200002:Happy01"
          },
          GUID = "3211C596",
          LookAt = {
            [1] = "200002:n(200024)",
            [2] = "100001:n(200002)"
          },
          NextDialogue = 20000608,
          SpeakNpcId = 200002,
          Subtitle = "Like the master blacksmith, every Luno has a particular forte.",
          VoiceName = "voice/$Locale$/story/2001/200006/3211C596"
        },
        [20000608] = {
          Camera = "-273.669891,-169.162842,94.503487,0.000062,-4.201106,40.194386,20.0,189.105499,false,Manual,2.8",
          ContentKR = "호오, 그럼 스노우도 잘하는 게 있겠네?",
          DialogueId = 20000608,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Happy01",
            [2] = "200002:None",
            [3] = "200024:None"
          },
          GUID = "3211C5C0",
          NextDialogue = 20000609,
          SpeakNpcId = 100001,
          Subtitle = "Wow. Do you have any unique talents, Snow?",
          VoiceName = "voice/$Locale$/story/2001/200006/3211C5C0"
        },
        [20000609] = {
          Camera = "-124.017761,-72.534912,96.158783,0.000383,-4.797825,32.343403,30.0,153.148956,false,Manual,3.33564",
          ContentKR = "음... 그게... 당연히... 있지!",
          DialogueId = 20000609,
          Duration = 6,
          GUID = "3211C5EA",
          LookAt = {
            [1] = "200002:n(200002)"
          },
          NextDialogue = 20000610,
          SpeakNpcId = 200002,
          Subtitle = "Yeah... Hmm... Of course, I do!",
          TalkActionId = {
            [1] = "200002:Bai_Shock2Think2Confident"
          },
          VoiceName = "voice/$Locale$/story/2001/200006/3211C5EA"
        },
        [20000610] = {
          Camera = "-124.017761,-72.534912,96.158783,0.000383,-4.797825,32.343403,30.0,153.148956,false,Manual,3.33564",
          ContentKR = "이거, 이거, 보이지! 스노우는 다른 루나랑 다르게 생겼다니까!",
          DialogueId = 20000610,
          Duration = 3,
          FacialId = {
            [1] = "200002:Confident01"
          },
          FinalCamera = "-115.367767,-61.598877,96.529541,0.000382,-4.797825,32.34626,30.0,153.148956,false,Manual,3.33564",
          GUID = "3211C614",
          NextDialogue = 20000611,
          Scripts = "CameraMoveTo{_delay{3.1},TargetPosition{\"-29.559052,-9.855469,93.745667,0.000395,-1.597868,52.748596,30.0,80.996147,false,Manual,3.33564\"},duration{0}}",
          SpeakNpcId = 200002,
          Subtitle = "As you can see, I have demonic appendages on my head. No other Lunos have these!",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C614"
        },
        [20000611] = {
          Camera = "121.44281,0.996094,87.475624,0.000284,-1.203274,162.815094,40.0,255.986099,false,Manual,4.671523",
          ContentKR = "확실히, 이 늙은이가 이렇게 나이를 먹었지만, 너처럼 생긴 루나는 처음 보는 것 같군. 네 모습은, <H>카론</>이랑 비슷하게 생겼어....",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000611,
          Duration = 3,
          FinalCamera = "120.606506,-1.710693,87.475624,0.000284,-1.203274,162.815094,40.0,255.986099,false,Manual,4.671523",
          GUID = "3211C63E",
          NextDialogue = 20000612,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Indeed. In all my years, I've never seen a Luno with horns like those. You look just like those Charons.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C63E"
        },
        [20000612] = {
          Camera = "-400.428558,-346.687256,65.11969,0.000289,0.592908,43.232693,30.0,150.0,false,Disable,2.8",
          ContentKR = "그러니까, 스노우는 하나밖에 없는 마왕 루나라고! 어쩌면 스노우는 루나를 이끌어 세계를 정복하기 위해 태어났을지도!",
          DialogueId = 20000612,
          Duration = 3,
          FinalCamera = "-400.428558,-346.687256,74.75869,0.000289,0.592908,43.232693,30.0,150.0,false,Disable,2.8",
          GUID = "3211C668",
          NextDialogue = 20000613,
          SpeakNpcId = 200002,
          Subtitle = "Sooo, I'm the special and unique Luno the Demon King. Perhaps I was meant to lead the Lunos and dominate the world!",
          TalkActionId = {
            [1] = "200002:Bai_Talk03Quick"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C668"
        },
        [20000613] = {
          Camera = "73.592575,17.665527,68.467941,0.000294,7.195904,171.812531,50.0,197.801682,false,Manual,3.959335",
          ContentKR = "허... 젊은이가 야망이 크군!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000613,
          Duration = 3,
          FacialId = {
            [1] = "200024:Satisfy01"
          },
          GUID = "3211C692",
          NextDialogue = 20000614,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Oh... that's quite the aspiration.",
          VoiceName = "voice/$Locale$/story/2001/200006/3211C692"
        },
        [20000614] = {
          Camera = "-147.118195,-74.93335,97.300194,0.000344,-2.603818,35.809223,50.0,210.030212,false,Manual,5.267603",
          ContentKR = "휴, 보통 루나는 정말 야망이라고는 찾아볼 수 없다니까. 그저 인간을 따라다니는 것을 좋아하고, 인간의 칭찬을 받으면 기뻐서 빙빙 돌기나 하고... 하지만 이런 걸로는 이 스노우 님을 만족시킬 수 없지!",
          DialogueId = 20000614,
          Duration = 3,
          FacialId = {
            [1] = "200002:Syouganai01"
          },
          GUID = "3211C6BC",
          NextDialogue = 20000615,
          SpeakNpcId = 200002,
          Subtitle = "Unfortunately, most Lunos lack ambition. They'd rather follow the humans, and are content with just a few words of appreciation. But for me, I want so much more!",
          TalkActionId = {
            [1] = "200002:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200006/3211C6BC"
        },
        [20000615] = {
          BlendTime = 2,
          Camera = "-147.118195,-74.93335,97.300194,0.000344,-2.603818,35.809223,50.0,210.030212,false,Manual,5.267603",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "시종아! 이 스노우 님을 잘 따라다니면서 열심히 수행하라고! 스노우가 세계 정복을 하면 널 마왕군의 군단장으로 임명해 줄 테니! 그때 대장장이 루나님한테 우리 모습을 다시 보여주는 거야!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000615,
          Duration = 3,
          FacialId = {
            [1] = "200002:Confident01"
          },
          FinalCamera = "-155.359039,-80.880859,97.762383,0.000344,-2.603818,35.809223,50.0,210.030212,false,Manual,5.267603",
          GUID = "3211C6E6",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextOptions = {
            [1] = 200006151,
            [2] = 200006152
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{3.1},TargetPosition{"-277.723358,-99.678711,81.074387,0.000378,1.599985,26.80905,25.0,272.329132,false,Manual,1.32502"},duration{0}},
CameraMoveTo{_delay{3.2},TargetPosition{"-291.878387,-106.830566,80.631393,0.000378,1.599985,26.80905,25.0,272.329132,false,Manual,1.32502"},blend{"easeOutQuad"},duration{3}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "My little minion, you must stick with me. After I conquer the world, you'll be the leader of my legion! Just you wait and see!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C6E6"
        },
