            [1] = "200002:SpecialConfident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D00"
        },
        [20006017] = {
          Camera = "-734.274048,-630.614258,292.918457,0.000099,-3.391544,164.774017,35.000008,1674.542114,false,Manual,8.0",
          ContentKR = "음, 이상하네. 분명 우리가 녀석을 구해줬고 적대적인 태도도 보이지 않았잖아. 마령들은 비록 말은 못 해도, 누가 자기한테 잘해줬는지, 누가 해를 끼치는지는 분명히 구분할 줄 아는데 말이야.",
          DialogueId = 20006017,
          FacialId = {
            [1] = "200074:Sad01"
          },
          FinalCamera = "-798.274292,-613.4375,289.223145,0.000099,-3.191556,164.973953,35.000008,1674.542114,false,Manual,8.0",
          GUID = "32153D2A",
          NextDialogue = 20006018,
