        },
        [20006018] = {
          Camera = "-497.108154,-708.697266,244.088379,0.000021,1.403228,153.786591,35.0,174.116943,false,Manual,12.0",
          ContentKR = "생각해보자... 헤이즐넛이 이런 식으로 내가 전혀 이해할 수 없는 행동을 한 적이 있었나...?",
          DialogueId = 20006018,
          FinalCamera = "-522.647217,-696.478516,231.824707,0.000021,7.603175,151.787338,35.0,174.116943,false,Manual,12.0",
          GUID = "32153D54",
          NextDialogue = 20006019,
          SpeakNpcId = 200074,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D54"
        },
        [20006019] = {
          Camera = "-152.133362,-1170.719727,714.169434,0.000035,-27.996868,146.383102,35.0,174.116943,false,Manual,12.0",
          ContentKR = "한 번은 꼭 아무것도 없는 골짜기에 가야 한다고 고집을 부렸었지. 나중에 알고 보니 골짜기 깊숙한 곳에서 잔뜩 나는 베리 냄새를 맡았던 거였고... 또 한 번은 꽃집 문 앞에서 꼼짝도 안 하고 서 있었는데, 내가 꽃을 사니까 기뻐하며 한입에 먹어 치웠어...",
          DialogueId = 20006019,
          FinalCamera = "-66.008728,-699.472656,615.159668,0.000042,-26.596804,175.382294,35.0,174.116943,false,Manual,12.0",
          GUID = "32153D7E",
          NextDialogue = 20006020,
          SpeakNpcId = 200074,
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D7E"
        },
        [20006020] = {
          ContentKR = "또 한 번은, 갑자기 날 두고 산비탈 위로 필사적으로 뛰어간 거였어. 알고 보니 근처 풀숲에 뱀이 있었기 때문에... 뱀을 멀리 유인해 내려고 했던 거지...",
          DialogueId = 20006020,
          GUID = "32153DA8",
          NextDialogue = 20006021,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200060/32153DA8"
        },
        [20006021] = {
          Camera = "-854.367188,-711.143555,293.184082,0.000106,-12.591494,30.173449,35.000008,1674.542114,false,Manual,8.0",
          ContentKR = "음... 전부 뭔가 굉장히 신경 쓰이는 일이 있었기 때문이었네. 그렇다면 마령이 신경 쓸 만한 건 뭐가 있을까? 먹이... 그리고 동료!",
          DialogueId = 20006021,
          FinalCamera = "-942.035889,-762.558594,315.785645,0.000113,-12.391452,31.173887,35.000008,1674.542114,false,Manual,8.0",
          GUID = "32153DD2",
          NextDialogue = 20006022,
          SpeakNpcId = 200074,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153DD2"
