          VoiceName = "voice/$Locale$/story/2001/200061/32154B46"
        },
        [20006104] = {
          Camera = "-678.081421,-823.285156,256.820801,0.000206,7.409949,135.164078,35.000008,174.116943,false,Manual,5.0",
          ContentKR = "푸흡... 너희들... 내가 나이는 어리지만, 헤이즐넛이랑 같이 다니면서 사람도 많이 봤거든. 근데 마령 생각까지 신경 쓰는 사람은 정말 드물었어.",
          DialogueId = 20006104,
          FinalCamera = "-694.658569,-806.806641,259.938965,0.000206,6.409948,135.164078,35.000008,174.116943,false,Manual,5.0",
          GUID = "32154B70",
          LookAt = {
