          SpeakNpcName = "UI_Npc_Name_Pan_Common",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B1D0"
        },
        [20006801] = {
          ContentKR = "결국, 이 마령들은 모두 아스포델로 옮겨졌고, 술집에 가득 있던 손님들을 놀라 도망치게 만들었다.\n그리고 카밀라는 깊은 한숨을 내쉬며, 애초에 {nickname}을(를) 도시로 데려오지 말아야 했던 건 아닐까 하는 고민에 빠지고 말았다.",
          DialogueId = 20006801,
          Duration = 5,
          GUID = "3215BDCA",
          VoiceName = "voice/$Locale$/story/2001/200068/3215BDCA"
        },
        [20006901] = {
          ContentKR = "또 시간이 한동안 지나고, 카밀라의 찌푸렸던 미간이 마침내 서서히 펴지기 시작했다...",
          DialogueId = 20006901,
          Duration = 3,
          GUID = "3215CE32",
          VoiceName = "voice/$Locale$/story/2001/200069/3215CE32"
        },
        [20006902] = {
          Camera = "-77.774261,-546.844727,210.810547,-0.000763,-8.992114,80.412018,35.0,369.08606,false,Manual,12.0",
          ContentKR = "헤, 카밀라, '불닭이 특제 칵테일'로 한잔 부탁해. 이렇게 추운 날 한 모금이면 딱이지.",
          DialogueId = 20006902,
          GUID = "3215CE5C",
          LookAt = {
            [1] = "700253:n(700248)",
            [2] = "700254:n(700253)"
          },
          NextDialogue = 20006903,
          Scripts = [[
