          SpeakNpcId = 700253,
          VoiceName = "voice/$Locale$/story/2001/200069/3215CE5C"
        },
        [20006903] = {
          ContentKR = "처음엔 이 작은 녀석이 좀 수상쩍다고 생각했는데, 뿜어내는 불꽃으로 술을 데우다니, 완전 최고야!",
          DialogueId = 20006903,
          GUID = "3215CE86",
          LookAt = {
            [1] = "700253:n(700253)"
          },
          NextDialogue = 20006904,
          SpeakNpcId = 700253,
          TalkActionId = {
            [1] = "700253:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CE86"
        },
        [20006904] = {
          Camera = "-270.673706,295.446289,221.228516,-0.000763,-10.792361,-56.385796,35.000008,369.08606,false,Manual,12.0",
          ContentKR = "비참하군요, 웨일즈 씨. 애처롭군요, 웨일즈 씨.",
          DialogueId = 20006904,
          GUID = "3215CEB0",
          NextDialogue = 20006905,
          SpeakNpcId = 700254,
          TalkActionId = {
            [1] = "700254:Sigh_Start",
            [2] = "700253:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CEB0"
        },
        [20006905] = {
          Camera = "-37.503937,-47.555664,133.710938,-0.000763,-2.992312,-78.38279,35.000008,369.08606,false,Manual,12.0",
          ContentKR = "웨일즈 씨는 그저 불닭이의 불꽃이 술을 데워 배를 따뜻하게 해준다는 것만 알고 있을 뿐, 그 진정한 가치가 어둠을 갈라 저의 책을 밝혀주어 영감을 가져다주는 것이라는 걸 모르고 있군요!",
          DialogueId = 20006905,
          GUID = "3215CEDA",
          NextDialogue = 20006906,
          SpeakNpcId = 700254,
          TalkActionId = {
            [1] = "700254:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CEDA"
        },
        [20006906] = {
