        },
        [20007004] = {
          Camera = "385.531738,327.31543,122.824219,-0.000336,8.596824,174.251282,35.0,369.08606,false,Manual,12.0",
          ContentKR = "그리고 마령이 인간과 잘 지낼 수 있다면, 카론과 솔라도 언젠가는 화합하며 지낼 날이 오겠죠.",
          DialogueId = 20007004,
          GUID = "3215DF18",
          NextDialogue = 20007005,
          Scripts = "PlayFacial{_delay{0.5},ActorId{700248},FacialId{\"Smile01\"}}",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF18"
        },
        [20007005] = {
          Camera = "271.747681,244.423828,145.421875,0.000091,0.396629,32.112232,35.0,369.08606,false,Manual,12.0",
          ContentKR = "하하, 순진하다고 해야 할지, 멀리 내다본다고 해야 할지 모르겠네. 그럴 날이 오길 기대할게. 근데 그날이 오기 전에, 꼬마 친구와 작별할 때가 온 것 같네.",
          DialogueId = 20007005,
          FinalCamera = "134.401306,153.286133,129.798828,-0.000336,-0.203833,31.850718,35.000008,369.08606,false,Manual,12.0",
          GUID = "3215DF42",
          NextDialogue = 20007006,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Sigh_Start"},Duration{2}},
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Sigh_End"},Duration{1}}}]],
          SpeakNpcId = 700248,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF42"
        },
        [20007006] = {
          Camera = "721.993774,408.491211,205.130859,0.00002,-14.403127,-165.088608,35.0,369.08606,false,Manual,12.0",
          ContentKR = "엉엉엉, 트러플, 그냥 아이스레이크 시티에 남아 있으면 안 돼? 겨우 나랑 같이 빛의 마왕님이라는 칭호를 외쳐줄 친구를 구했단 말이야!",
          DialogueId = 20007006,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "3215DF6C",
          NextDialogue = 20007007,
          SpeakNpcId = 200002,
          TurnTo = {
            [1] = "200074:p(30)"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF6C"
        },
        [20007007] = {
          ContentKR = "울지 마, 스노우. 난 이미 너무 오래 나와 있었어, 이제 돌아가야 해. 게다가 그 마령 사냥꾼들도 이제 마령 학자가 됐잖아? 그 사람들과 같이 칭호를 외치면 되잖아.",
          DialogueId = 20007007,
          GUID = "3215DF96",
          NextDialogue = 20007008,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF96"
        },
        [20007008] = {
          Camera = "428.352539,486.96582,156.205078,0.000078,-8.003704,-124.08696,35.0,369.08606,false,Manual,12.0",
          ContentKR = "아니야, 걔들은 네 목소리만큼 듣기 좋지도 않고, 너처럼 헤이즐넛과 함께 드라이브시켜 줄 수도 없잖아. {nickname} 너도 멍하니 서 있지 말고, 트러플을 좀 붙잡아 봐!",
          DialogueId = 20007008,
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          GUID = "3215DFC0",
          NextOptions = {
            [1] = 200070081
          },
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "700248:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DFC0"
        },
        [20007009] = {
          Camera = "322.5,503.43457,157.886719,0.000066,-8.003506,-99.487526,35.000008,369.08606,false,Manual,12.0",
          ContentKR = "헤헤, 나중에 가끔 놀러 올 거야. {性别:오빠|언니}, 몰래 알려주는 거야. 내가 돌아가야 하는 그 아주아주 먼 곳은 사실 엘리시안 교회야.",
          DialogueId = 20007009,
          FacialId = {
            [1] = "200002:CM_Idle"
          },
          FinalCamera = "316.476074,471.517578,153.757812,0.000067,-8.603483,-101.087669,35.000008,369.08606,false,Manual,12.0",
          GUID = "3215DFEA",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20007010,
          SpeakNpcId = 200074,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DFEA"
        },
        [20007010] = {
          Camera = "-189.593018,180.383789,233.115234,0.000085,-10.602577,9.713165,35.0,369.08606,false,Manual,12.0",
          ContentKR = "난 식량을 모을 때 가끔 헤이즐넛과 함께 아무도 지키지 않는 높은 산을 넘어 휘페르보레아로 오곤 해. 처음엔 좀 무서웠어, 왜냐하면 교회랑 제국은 계속 전쟁 중이잖아.",
          DialogueId = 20007010,
          GUID = "3215E014",
          NextDialogue = 20007011,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E014"
        },
        [20007011] = {
          ContentKR = "근데 {性别:오빠|언니}를 만나고 난 뒤로 안 무서워졌어.",
          DialogueId = 20007011,
          GUID = "3215E03E",
          NextDialogue = 20007012,
          SpeakNpcId = 200074,
          TalkActionId = {
            [1] = "200074:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215E03E"
        },
        [20007012] = {
          ContentKR = "{性别:오빠|언니}가 마령과 인간이 함께 지낼 방법을 생각해 낼 수 있다면, 분명 카론과 솔라가 서로 미워하지 않게 만들 수도 있을 거야. 그러면 제국과 교회도 더 이상 싸우지 않을 수 있겠지.",
          DialogueId = 20007012,
          GUID = "3215E068",
          NextDialogue = 20007013,
          SpeakNpcId = 200074,
          TalkActionId = {
            [1] = "200074:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215E068"
        },
        [20007013] = {
          ContentKR = "그렇게 되면, 다들 배고프지 않게 될 거야!",
          DialogueId = 20007013,
          GUID = "3215E092",
          NextDialogue = 20007014,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E092"
        },
        [20007014] = {
          ContentKR = "그때가 되면, {性别:오빠|언니}랑 스노우, 그리고 카밀라 씨도 같이 남쪽으로 와줘. 통통한 붉은 버섯도 먹고, 따뜻한 바닷바람도 쐬고, 여기서는 볼 수 없는 별들도 보면서, 내가 여기서 지냈던 것처럼 행복하게 지내자! 기다릴게!",
          DialogueId = 20007014,
          GUID = "3215E0BC",
          NextDialogue = 20007015,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E0BC"
        },
        [20007015] = {
          ContentKR = "그래, 그렇게 해볼게.",
          DialogueId = 20007015,
          GUID = "3215E0E6",
          NextDialogue = 20007016,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E0E6"
        },
        [20007016] = {
          ContentKR = "약속이야.",
          DialogueId = 20007016,
          GUID = "3215E110",
          NextOptions = {
            [1] = 200070161
          },
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E110"
        },
        [20007017] = {
          ContentKR = "헤이즐넛과도 약속해.",
          DialogueId = 20007017,
          GUID = "3215E13A",
          NextDialogue = 20007018,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E13A"
        },
        [20007018] = {
          ContentKR = "헤이즐넛은 발굽이 너무 굵어서 새끼손가락을 걸 수가 없잖아.",
          DialogueId = 20007018,
          GUID = "3215E164",
          NextDialogue = 20007019,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E164"
        },
        [20007019] = {
          ContentKR = "그럼 그냥 발굽을 움켜쥐면 돼. 자, 다 같이, 새끼손가락 걸고 약속, 영원히 변치 말기!",
          DialogueId = 20007019,
          GUID = "3215E18E",
          NextDialogue = 20007020,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E18E"
        },
        [20007020] = {
          ContentKR = "꿀!",
          DialogueId = 20007020,
          GUID = "3215E1B8",
          SpeakNpcId = 200086,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E1B8"
        },
        [20007101] = {
          ContentKR = "이 몸은, 아이스레이크 시티 최고의 마령 학자시다! 마령에 대해 질문이 있다면 이 몸에게 물어보도록... 앗, 당신이군요... 무... 무슨 일이신지?",
          DialogueId = 20007101,
          GUID = "3215EF02",
          NextOptions = {
            [1] = 200071011,
            [2] = 200071012,
            [3] = 200071013
          },
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF02"
        },
        [20007102] = {
          ContentKR = "그 굉장히 똑똑한 마령 말씀이죠?",
          DialogueId = 20007102,
          GUID = "3215EF2C",
          NextDialogue = 20007103,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF2C"
        },
        [20007103] = {
          ContentKR = "판신 마령에 대한 기록은 매우 적어요. 저도 단 한 번 밖에 본 적 없습니다. 판신 마령의 인정을 받아야만 그들을 찾을 수 있다고 합니다.",
          DialogueId = 20007103,
          GUID = "3215EF56",
          NextDialogue = 20007104,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF56"
        },
        [20007104] = {
          ContentKR = "하지만 당신이라면 그들이 남긴 흔적을 따라 그들의 은신처를 찾을 수 있을 겁니다.",
          DialogueId = 20007104,
          GUID = "3215EF80",
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF80"
        },
        [20007105] = {
          ContentKR = "마량 사냥꾼보다 많이 낫습니다. 매일 사람들이 몰려와 저에게 마령에 대한 질문을 합니다. 마치 제가 무슨 대학자인 것처럼요.",
          DialogueId = 20007105,
          GUID = "3215EFAA",
          NextDialogue = 20007106,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EFAA"
        },
        [20007106] = {
          ContentKR = "이게 다 당신과 트러플이 너그럽게 봐주신 덕분입니다, 감사합니다.",
          DialogueId = 20007106,
          GUID = "3215EFD4",
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EFD4"
        },
        [20007107] = {
          ContentKR = "깊게 새겨진 흔적. 어떤 날카로운 물체로 긁은 듯하다.",
          DialogueId = 20007107,
          GUID = "3215EFD5"
        },
        [20007108] = {
          ContentKR = "\"위험, 통행금지\"라고 쓰여 있는 경고 푯말. 경고문이 낡자 그대로 새 경고문으로 덮은 모양인지, 종이가 덕지덕지 두껍게 붙어 있다. 가장 최근의 것은 신력 1004년, 즉 24년 전으로, 글로스터 광갱은 아마 그때 완전히 폐기된 듯하다.",
          DialogueId = 20007108,
          GUID = "3215EFD6"
        },
        [21000101] = {
          Content = "背白白进场台词（测试用）",
          DialogueId = 21000101,
          GUID = "34925112",
          TalkActionId = {
            [1] = "900005:Beibao_Start"
          }
        },
        [21000102] = {
          Content = "背白白退场台词（测试用）",
          DialogueId = 21000102,
          GUID = "3492513C",
          TalkActionId = {
            [1] = "900005:Beibao_Finish"
          }
        },
        [50000101] = {
          ContentKR = "이봐, 너 말이야, 너. 통행증은 있나?",
          DialogueId = 50000101,
          Duration = 3,
          GUID = "7D2B8592",
          SpeakNpcId = 700111,
          Subtitle = "Travel permit check — oi, I'm talking to you! Got your travel permit on you?",
          VoiceName = "voice/$Locale$/env/700002/7D2B8592"
        },
        [50000201] = {
          ContentKR = "자네 같은 월석 사냥꾼이 여기까지 오다니... 영웅의 기질이 보이는구먼.",
          DialogueId = 50000201,
          Duration = 4,
          GUID = "7D2B95FA",
          SpeakNpcId = 700003,
          Subtitle = "A Phoxhunter? Can't believe anyone would still make it here. You've got what it takes to be a hero like them, I guess.",
          VoiceName = "voice/$Locale$/env/700003/7D2B95FA"
        },
        [50000301] = {
          ContentKR = "젠장, 전부 그란데 탓이야. 대체 이제 어떡해야 하지... 응? 뭘 봐, 요 며칠은 뭘 부탁한 적도 없잖아!",
          DialogueId = 50000301,
          Duration = 3,
          GUID = "7D2BA662",
          SpeakNpcId = 700004,
          Subtitle = "D*mn it, it's all Grandet's fault! What am I supposed to do now... Hm? What are you looking at? I've got no work for you today!",
          VoiceName = "voice/$Locale$/env/700004/7D2BA662"
        },
        [50000401] = {
          ContentKR = "제 이름이... 애니라고요?",
          DialogueId = 50000401,
          Duration = 3,
          GUID = "7D2BB6CA",
          SpeakNpcId = 700032,
          Subtitle = "My name is... Annie?",
          TalkActionId = {
            [1] = "700032:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700032/7D2BB6CA"
        },
        [50000501] = {
          ContentKR = "몸만 회복되면 다음 모험을 떠나려고요.",
          DialogueId = 50000501,
          Duration = 3,
          GUID = "7D2BC732",
          SpeakNpcId = 700005,
          Subtitle = "As soon as I'm back in form, I'm off on another adventure.",
          TalkActionId = {
            [1] = "700032:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700005/7D2BC732"
        },
        [50000601] = {
          ContentKR = "엄마한테 갈 때 뭘 가져가면 좋을까... 분명 날 무척 보고 싶어 하실 텐데.",
          DialogueId = 50000601,
          Duration = 3,
          GUID = "7D2BD79A",
          SpeakNpcId = 700005,
          Subtitle = "What gift should I get for Elsa... She must've missed me terribly.",
          TalkActionId = {
            [1] = "700005:Think_Start"
          },
          VoiceName = "voice/$Locale$/env/700005/7D2BD79A"
        },
        [50000701] = {
          ContentKR = "애니... 애니!",
          DialogueId = 50000701,
          Duration = 3,
          GUID = "7D2BE802",
          SpeakNpcId = 700006,
          Subtitle = "Annie... Annie!",
          VoiceName = "voice/$Locale$/env/700006/7D2BE802"
        },
        [50000801] = {
          ContentKR = "어머, 이 꽃이 오늘 옷차림이랑 잘 어울리시네요... 그 아이도 있었다면 똑같이 말했을 거예요.",
          DialogueId = 50000801,
          Duration = 3,
          GUID = "7D2BF86A",
          SpeakNpcId = 700007,
          Subtitle = "The flowers today are quite lovely. I should save a few for that kid.",
          TalkActionId = {
            [1] = "700007:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700007/7D2BF86A"
        },
        [50000901] = {
          ContentKR = "안녕하세요, 이 꽃은 오늘 당신과 잘 어울리네요... 그 애가 살아 있다면 분명 이렇게 말했을 거예요.",
          DialogueId = 50000901,
          Duration = 5,
          GUID = "7D2C08D2",
          SpeakNpcId = 700203,
          Subtitle = "Good day, you look great with this flower... That kid would have said so, if she were still here.",
          VoiceName = "voice/$Locale$/env/700007/7D2C08D2"
        },
        [50001001] = {
          ContentKR = "그런 옷걸이를 가지고 우리 옷을 안 입는다니, 너무 아쉽네요.",
          DialogueId = 50001001,
          Duration = 3,
          GUID = "7D2C193A",
          SpeakNpcId = 700008,
          Subtitle = "Hello, gorgeous! I bet you'd be a vision in our apparel.",
          VoiceName = "voice/$Locale$/env/700008/7D2C193A"
        },
        [50001101] = {
          ContentKR = "우리 농장 과일이라 하는 말이 아니라 이런 기술로 키우는 데는 어디에도 없다니까!",
          DialogueId = 50001101,
          Duration = 3,
          GUID = "7D2C29A2",
          SpeakNpcId = 700009,
          Subtitle = "Try these fine fruits from our orchard — grown with unmatched cultivation techniques!",
          TalkActionId = {
            [1] = "700009:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700009/7D2C29A2"
        },
        [50001201] = {
          ContentKR = "아... 어, 으어어...",
          DialogueId = 50001201,
          Duration = 2,
          GUID = "7D2C3A0A",
          SpeakNpcId = 700010,
          Subtitle = "Ah... whoa, I... um...",
          VoiceName = "voice/$Locale$/env/700010/7D2C3A0A"
        },
        [50001301] = {
          ContentKR = "음... 첫 번째 실험 대상은 너로 정했어!",
          DialogueId = 50001301,
          Duration = 3,
          GUID = "7D2C4A72",
          SpeakNpcId = 700011,
          Subtitle = "Hmm... I've made up my mind — hello, Test subject No. 1!",
          TalkActionId = {
            [1] = "700011:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700011/7D2C4A72"
        },
        [50001401] = {
          ContentKR = "{NickName}, 또 만났네! 난 매일 새로운 것들을 열심히 공부하고 있어. 같이 힘내자!",
          DialogueId = 50001401,
          Duration = 4,
          GUID = "7D2C5ADA",
          SpeakNpcId = 700011,
          Subtitle = "lovely to see you again! I'm trying my best to learn new things every day, let's keep at it!",
          TalkActionId = {
            [1] = "700011:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700011/7D2C5ADA"
        },
        [50001501] = {
          ContentKR = "너는... 카론... 나와 같은...",
          DialogueId = 50001501,
          Duration = 6,
          GUID = "7D2C6B42",
          SpeakNpcId = 700012,
          Subtitle = "Are we... the same kind?",
          VoiceName = "voice/$Locale$/env/700012/7D2C6B42"
        },
        [50001601] = {
          ContentKR = "말로 표현하기 힘든 일들도 많이 보아 왔지만, 그 일들의 중심엔 항상 '악마'만 있는 것도 아니었지.\n...나도 가끔은 솔라와 카론 중 대체 누가 악마인지 잘 모르겠어.",
          DialogueId = 50001601,
          Duration = 4,
          GUID = "7D2C7BAA",
          SpeakNpcId = 700013,
          Subtitle = [[
I've witnessed deeds that daylight never sees, and not all are the work of "demons".
...Sometimes, between humans and Charons, I can't tell which is the true demon.]],
          VoiceName = "voice/$Locale$/env/700013/7D2C7BAA"
        },
        [50001701] = {
          ContentKR = "보는 눈도 없는 멍청한 여자 같으니! 언제까지 그렇게 뻗대나 보자고!",
          DialogueId = 50001701,
          Duration = 4,
          GUID = "7D2C8C12",
          SpeakNpcId = 700014,
          Subtitle = "Pah! Stupid hag! Let's see how long you can keep this charade up!",
          TalkActionId = {
            [1] = "700014:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/env/700014/7D2C8C12"
        },
        [50001801] = {
          ContentKR = "신이시어, 저같이 선량한 사람에게 영감을 훔치는 영혼을 보내시다니요! 이렇게 억울할 수가!",
          DialogueId = 50001801,
          Duration = 4,
          GUID = "7D2C9C7A",
          SpeakNpcId = 700015,
          Subtitle = "Good grief! Who'd have thought a gentle soul like myself would be beset by an inspiration-stealing spectre?! Such wretchedness would surely draw heaven's own tears!",
          VoiceName = "voice/$Locale$/env/700015/7D2C9C7A"
        },
        [50001901] = {
          ContentKR = "정말 짜증 나! 맨날 쓸데없는 행사만 하고, 차라리 좀 쉬는 게 낫겠네!",
          DialogueId = 50001901,
          Duration = 3,
          GUID = "7D2CACE2",
          SpeakNpcId = 700016,
          Subtitle = "What a drag! Who arranged these pointless events? I'd rather have half a day off!",
          VoiceName = "voice/$Locale$/env/700016/7D2CACE2"
        },
        [50002001] = {
          ContentKR = "\"비가 와서 엄마 꽃이 망가졌어요. 그래서 하늘이 물웅덩이에 작은 꽃들을 많이 만들어서 엄마한테 줬어요.\"",
          DialogueId = 50002001,
          Duration = 3,
          GUID = "7D2CBD4A",
          NextDialogue = 50002002,
          SpeakNpcId = 700017,
          Subtitle = "\"The rain hurt Mum's flowers, so the sky said sorry by leaving her lots of tiny flowers in the puddles.\"",
          VoiceName = "voice/$Locale$/env/700017/7D2CBD4A"
        },
        [50002002] = {
          ContentKR = "그거 알아요? 이건 제 여섯 살짜리 학생이 쓴 <사죄>라는 시예요.",
          DialogueId = 50002002,
          Duration = 3,
          GUID = "7D2CBD74",
          SpeakNpcId = 700017,
          Subtitle = "You know what, this little verse is called \"Apology\", and it's written by a six-year-old student of mine.",
          TalkActionId = {
            [1] = "700017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700017/7D2CBD74"
        },
        [50002101] = {
          ContentKR = "자연의 법칙을 거스르며 던진 돌은 결국 자신의 머리로 날아오는 법이죠.",
          DialogueId = 50002101,
          Duration = 3,
          GUID = "7D2CCDB2",
          SpeakNpcId = 700018,
          Subtitle = "The rocks cast against the laws of nature will inevitably fall back on one's own head.",
          TalkActionId = {
            [1] = "700018:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/env/700018/7D2CCDB2"
        },
        [50002201] = {
          ContentKR = "도대체 어디로 간 거야...",
          DialogueId = 50002201,
          Duration = 3,
          GUID = "7D2CDE1A",
          SpeakNpcId = 700019,
          Subtitle = "Where could he have gone off to...",
          TalkActionId = {
            [1] = "700019:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700019/7D2CDE1A"
        },
        [50002301] = {
          ContentKR = "오늘 저녁의 버섯 크림수프가 마님께 조금이나마 위안이 되었으면 좋겠는데요.",
          DialogueId = 50002301,
          Duration = 4,
          GUID = "7D2CEE82",
          SpeakNpcId = 700020,
          Subtitle = "I hope tonight's creamy mushroom soup will bring some comfort to her ladyship.",
          TalkActionId = {
            [1] = "700020:Agree"
          },
          VoiceName = "voice/$Locale$/env/700020/7D2CEE82"
        },
        [50002401] = {
          ContentKR = "언제나 제정신이 아니네. 정말 안쓰러워.",
          DialogueId = 50002401,
          Duration = 3,
          GUID = "7D2CFEEA",
          NextDialogue = 50002402,
          SpeakNpcId = 700023,
          Subtitle = "Poor thing, having lost her mind like that.",
          VoiceName = "voice/$Locale$/env/700023/7D2CFEEA"
        },
        [50002402] = {
          ContentKR = "딸이 떠난 것도 이해가 될 지경이야...",
          DialogueId = 50002402,
          Duration = 3,
          GUID = "7D2CFF14",
          SpeakNpcId = 700024,
          Subtitle = "No wonder her daughter had left.",
          VoiceName = "voice/$Locale$/env/700024/7D2CFF14"
        },
        [50002501] = {
          ContentKR = "도시의 모든 쓰레기통은 제 것이나 마찬가지죠. 그 안에는 별의별 것이 다 들어 있답니다! 몇 번밖에 신지 않은 사슴 가죽 장화, 아직 시들지 않은 백합, 그리고 누가 부쉈는지 알 수 없는 꿈도 있어요...",
          DialogueId = 50002501,
          Duration = 3,
          GUID = "7D2D0F52",
          SpeakNpcId = 700115,
          Subtitle = "I oversee all the rubbish bins around the city, and oh, the treasures to be found in each of them! Nearly new deerskin boots, still-fresh lilies, and the fragments of someone's shattered dreams...",
          TalkActionId = {
            [1] = "700115:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700022/7D2D0F52"
        },
        [50002601] = {
          ContentKR = "다음 역으로 가는 열차가 곧 출발할 예정이니 표는 이곳에서 구매하시면 됩니다. 돈이 없다고요? 그럼 헛된 꿈은 그만 꾸고 꺼지세요!",
          DialogueId = 50002601,
          Duration = 5,
          GUID = "7D2D0F53",
          SpeakNpcId = 700021,
          Subtitle = "The train to the next station is about to depart. Please process your ticket purchase here — What's that? You've got no money? Then less dreaming, more moving, if you please!",
          TalkActionId = {
            [1] = "700021:Confident_Start"
          }
        },
        [50002701] = {
          ContentKR = "13번 파이프는 벌써 고치는 중이야. 아, 진짜, 쥐가 너무 많아서 미치겠네.",
          DialogueId = 50002701,
          Duration = 4,
          GUID = "7D2D3022",
          SpeakNpcId = 700069,
          Subtitle = "Pipe No. 13 is under repair — blimey, it's swarming with rats in there.",
          TalkActionId = {
            [1] = "700069:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700069/7D2D3022"
        },
        [50002801] = {
          ContentKR = "꺼져! 망할 카론 자식!",
          DialogueId = 50002801,
          DialoguePanelType = "{type:Bubble;style:ExcitedBubble}",
          Duration = 3,
          GUID = "7D2D408A",
          SpeakNpcId = 700068,
          Subtitle = "Beat it, dirty Charon!",
          VoiceName = "voice/$Locale$/env/700068/7D2D408A"
        },
        [50002901] = {
          ContentKR = "아이고... 왜 이렇게 안 지워지는 거야.",
          DialogueId = 50002901,
          Duration = 3,
          GUID = "7D2D50F2",
          SpeakNpcId = 700067,
          Subtitle = "Ugh... why won't this bloodstain come off?",
          TalkActionId = {
            [1] = "700067:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700067/7D2D50F2"
        },
        [50003001] = {
          Content = "凶猛的狼咆哮着 撕咬着狡猾的狗",
          DialogueId = 50003001,
          Duration = 3,
          GUID = "7D2D615A",
          NextDialogue = 50003002,
          SpeakNpcId = 700071,
          TalkActionId = {
            [1] = "700071:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700071/7D2D615A"
        },
        [50003002] = {
          Content = "狡猾的狗呜咽着 啃食着腐朽的肉",
          DialogueId = 50003002,
          Duration = 3,
          GUID = "7D2D6184",
          SpeakNpcId = 700071,
          TalkActionId = {
            [1] = "700071:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700071/7D2D6184"
        },
        [50003101] = {
          Content = "您也喜欢这些百合吗？",
          DialogueId = 50003101,
          Duration = 3,
          GUID = "7D2D71C2",
          SpeakNpcId = 700072,
          TalkActionId = {
            [1] = "700072:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700072/7D2D71C2"
        },
        [50003201] = {
          ContentKR = "성 밖의 괴물은 우리의 살을 먹고~ 성안의 괴물은 우리의 털을 깎고~ 사냥개는 흰 빵을 먹지만~ 우리 양들은 풀만 뜯어 먹는다네~",
          DialogueId = 50003201,
          Duration = 3,
          GUID = "7D2D822A",
          NextDialogue = 50003202,
          SpeakNpcId = 700073,
          Subtitle = "♪ \"Monsters beyond the walls feast on our flesh; the ones within shear our fleece. While the hounds dine on fine white loaves; we lowly sheep are content with chewing grass...\"",
          TalkActionId = {
            [1] = "700073:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700073/7D2D822A"
        },
        [50003202] = {
          ContentKR = "젠장! 이 노래는 누구한테 배운 거야... 너 때문에 조만간 우리 둘 다 죽게 생겼어!",
          DialogueId = 50003202,
          Duration = 3,
          GUID = "7D2D8254",
          NextDialogue = 50003203,
          SpeakNpcId = 700074,
          Subtitle = "Whoa, whoa! Where did you learn that ditty... you're going to get us both killed one of these days!",
          TalkActionId = {
            [1] = "700074:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700074/7D2D8254"
        },
        [50003203] = {
          ContentKR = "오! 무엇이 필요하세요? 전부 제가 직접 만든 겁니다. 품질은 말할 것도 없죠!",
          DialogueId = 50003203,
          Duration = 3,
          GUID = "7D2D827E",
          SpeakNpcId = 700074,
          Subtitle = "Ah, welcome! What can I get you, dear customer? Each piece here is crafted by my own hands, top-notch quality guaranteed!",
          TalkActionId = {
            [1] = "700074:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700074/7D2D827E"
        },
        [50003301] = {
          Content = "真好呀！真好！生活这么美好，怎么大家都愁眉苦脸的呢？我们生活在一个幸福的世界里，多么幸运！",
          DialogueId = 50003301,
          Duration = 3,
          GUID = "7D2D9292",
          SpeakNpcId = 700075,
          TalkActionId = {
            [1] = "700075:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/env/700075/7D2D9292"
        },
        [50003401] = {
          Content = "呜呜……爸爸妈妈，你们在哪里……我好想你们……",
          DialogueId = 50003401,
          Duration = 3,
          GUID = "7D2DA2FA",
          SpeakNpcId = 700076,
          TalkActionId = {
            [1] = "700076:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700076/7D2DA2FA"
        },
        [50003501] = {
          Content = "这是我在广场那边买的纪念品！他们说来冰湖城绝不能错过……",
          DialogueId = 50003501,
          Duration = 3,
          GUID = "7D2DB362",
          SpeakNpcId = 700077,
          TalkActionId = {
            [1] = "700077:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700077/7D2DB362"
        },
        [50003601] = {
          Content = "求您了……再多给两个子儿吧，只给这个数，我连过冬的炭火都买不起啊……",
          DialogueId = 50003601,
          Duration = 3,
          GUID = "7D2DC3CA",
          NextDialogue = 50003602,
          SpeakNpcId = 700078,
          TalkActionId = {
            [1] = "700078:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700078/7D2DC3CA"
        },
        [50003602] = {
          Content = "子爵大人要最好的皮料！要从最健壮的头狼身上剥下的顶级货！懂了吗蠢蛋！你的这些残次品只配给乞丐穿！",
          DialogueId = 50003602,
          Duration = 3,
          GUID = "7D2DC3F4",
          SpeakNpcId = 700079,
          TalkActionId = {
            [1] = "700079:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700079/7D2DC3F4"
        },
        [50003701] = {
          ContentKR = "팝콘! 담배! 그리고 술! 뭔가 잃어버리셨다고요? 전 몰라요! 아, 진짜 못 봤다니까요!",
          DialogueId = 50003701,
          Duration = 4,
          GUID = "7D2DD432",
          SpeakNpcId = 700080,
          Subtitle = "Popcorn! Cigs! Booze! Lost something, you say? Didn't see it! I swear!",
          VoiceName = "voice/$Locale$/env/700080/7D2DD432"
        },
        [50003801] = {
          ContentKR = "모든 카론이 내 나이만큼만 살 수 있다면, 나도 이렇게 외롭진 않을 텐데.",
          DialogueId = 50003801,
          Duration = 7,
          GUID = "7D2DE49A",
          SpeakNpcId = 700081,
          Subtitle = "If every Charon could live as long as I have, I wouldn't feel so alone.",
          VoiceName = "voice/$Locale$/env/700081/7D2DE49A"
        },
        [50003901] = {
          ContentKR = "손이 부러진 적이 있지만, 잡화는 아직 옮길 수 있어요. 뭐가 필요하세요?",
          DialogueId = 50003901,
          Duration = 3,
          GUID = "7D2DF502",
          SpeakNpcId = 700082,
          TalkActionId = {
            [1] = "700082:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700082/7D2DF502"
        },
        [50004001] = {
          ContentKR = ".........(달걀 루나가 보드에 빠르게 \"안녕하세요\"라고 적었다)",
          DialogueId = 50004001,
          Duration = 3,
          GUID = "7D2E056A",
          SpeakNpcId = 900008,
          VoiceName = "voice/$Locale$/env/900008/7D2E056A"
        },
        [50004101] = {
          ContentKR = "새 의뢰를 받았는데, 늘 하던 대로 8:2로 나누자고. 이것만 다 마시면 바로 출발하려고 하는데, 어때?",
          DialogueId = 50004101,
          Duration = 3,
          GUID = "7D2E15D2",
          SpeakNpcId = 200015,
          TalkActionId = {
            [1] = "200015:Agree"
          },
          VoiceName = "voice/$Locale$/env/200015/7D2E15D2"
        },
        [50004201] = {
          ContentKR = "한 잔 줄까?",
          DialogueId = 50004201,
          Duration = 3,
          GUID = "7D2E263A",
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/char/Kami/vo_npc_01"
        },
        [50004301] = {
          ContentKR = "♪날지 못하는 나이팅게일, 울지 마렴...",
          DialogueId = 50004301,
          Duration = 3,
          GUID = "7D2E36A2",
          NextDialogue = 50004302,
          SpeakNpcId = 700142,
          TalkActionId = {
            [1] = "700142:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/200020/7D2E36A2"
        },
        [50004302] = {
          ContentKR = "♪나-의 나이팅게일, 여기 잠들지 마렴...",
          DialogueId = 50004302,
          Duration = 3,
          GUID = "7D2E36CC",
          SpeakNpcId = 700142,
          TalkActionId = {
            [1] = "700142:Explain02_End"
          },
          VoiceName = "voice/$Locale$/env/200020/7D2E36CC"
        },
        [50004401] = {
          ContentKR = "제, 제발... 가 주세요... 월석 사시려는 게 아니면 그냥 어서 가세요... 병사들이 오면 안 된다고요...",
          DialogueId = 50004401,
          Duration = 4,
          GUID = "7D2E470A",
          SpeakNpcId = 700113,
          TalkActionId = {
            [1] = "700113:Disagree"
          },
          VoiceName = "voice/$Locale$/env/700113/7D2E470A"
        },
        [50004501] = {
          ContentKR = "춤추자! 다 같이 춤추는 거야! 사는 게 뭐가 중요해? 골치 아픈 건 다 잊고 내일까지 춤추자고!",
          DialogueId = 50004501,
          Duration = 3,
          GUID = "7D2E5772",
          SpeakNpcId = 700129,
          VoiceName = "voice/$Locale$/env/700129/7D2E5772"
        },
        [50004601] = {
          ContentKR = "나리, 이번 달 보조금은... 아, 아직 안 나왔군요. 쿨럭 쿨럭... 괜찮습니다. 우선은 제 돈으로 보충하겠습니다... 귀찮게 해드려 죄송합니다...",
          DialogueId = 50004601,
          Duration = 4,
          GUID = "7D2E67DA",
          SpeakNpcId = 700070,
          TalkActionId = {
            [1] = "700070:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700070/7D2E67DA"
        },
        [50004701] = {
          ContentKR = "보물에 대한 정보가 내게 있소...",
          DialogueId = 50004701,
          Duration = 3,
          GUID = "7D2E7842",
          SpeakNpcId = 700048,
          TalkActionId = {
            [1] = "700048:Agree"
          },
          VoiceName = "voice/$Locale$/env/700048/7D2E7842"
        },
        [50004801] = {
          ContentKR = "어부 공제 조합에 대해 알아보겠나!",
          DialogueId = 50004801,
          Duration = 3,
          GUID = "7D2E88AA",
          SpeakNpcId = 700048,
          TalkActionId = {
            [1] = "700048:Agree"
          },
          VoiceName = "voice/$Locale$/env/700048/7D2E88AA"
        },
        [50004901] = {
          ContentKR = "제대로 소독만 하면 맛있는 요리가 된다고!",
          DialogueId = 50004901,
          Duration = 3,
          GUID = "7D2E9912",
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700116/7D2E9912"
        },
        [50005001] = {
          ContentKR = "흠, 처음 보는 얼굴이군.",
          DialogueId = 50005001,
          Duration = 3,
          GUID = "7D2EA97A",
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700096/7D2EA97A"
        },
        [50005101] = {
          ContentKR = "뭐, 살 거라도 있나?",
          DialogueId = 50005101,
          Duration = 3,
          GUID = "7D2EB9E2",
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Agree"
          },
          VoiceName = "voice/$Locale$/env/700096/7D2EB9E2"
        },
        [50005201] = {
          ContentKR = "욕망에 충실하라, 욕망에 충실하라, 욕망에 충실하라... 아, 도대체 어떻게 해야 욕망에 충실한 거야...",
          DialogueId = 50005201,
          Duration = 4,
          GUID = "7D2ECA4A",
          SpeakNpcId = 700077,
          TalkActionId = {
            [1] = "700077:Disagree"
          },
          VoiceName = "voice/$Locale$/env/700077/7D2ECA4A"
        },
        [50005301] = {
          ContentKR = "다음 역으로 가는 열차가 곧 출발합니다. 표는 이곳에서 구매하시면 됩니다. 뭐라고요? 돈이 없다고요? 헛된 꿈은 그만 꾸고 저리 가세요!",
          DialogueId = 50005301,
          Duration = 4,
          GUID = "7D2D1FBA",
          SpeakNpcId = 700147,
          TalkActionId = {
            [1] = "700147:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700021/7D2D1FBA"
        },
        [50005401] = {
          ContentKR = "하하하, 정말 빠르게 도망가네! 생쥐보다도 더 빠른걸!",
          DialogueId = 50005401,
          Duration = 3,
          GUID = "7D2EEB1A",
          SpeakNpcId = 700089
        },
        [50005501] = {
          ContentKR = "이 더러운 카론 녀석아, 뭘 멍하니 서 있어! 어서 쫓아가라고!",
          DialogueId = 50005501,
          Duration = 3,
          GUID = "7D2EFB82",
          SpeakNpcId = 700088,
          TalkActionId = {
            [1] = "700088:Confident_Start"
          }
        },
        [50005601] = {
          ContentKR = "간판을 좀 더 큰 걸로 바꿔봐야 할까...",
          DialogueId = 50005601,
          Duration = 3,
          GUID = "7D2F0BEA",
          SpeakNpcId = 700143
        },
        [51000001] = {
          ContentKR = "(수락)",
          DialogueId = 51000001,
          GUID = "7FAC53AA",
          NextDialogue = 51005311
        },
        [51000002] = {
          ContentKR = "(거절)",
          DialogueId = 51000002,
          GUID = "7FAC53D4",
          Scripts = "SetOutport{FinishType{\"Fail\"}}"
        },
        [51000101] = {
          ContentKR = "음, 오늘 저녁엔 버섯 크림수프를 만들어 볼까... 으음? 귀여운 아이구나.",
          DialogueId = 51000101,
          GUID = "7FAC6412",
          NextDialogue = 51000102,
          SpeakNpcId = 700020
        },
        [51000102] = {
          ContentKR = "(노부인이 두툼한 손으로 머리를 토닥이고, 뺨을 꼬집는다. 과하다 싶을 정도의 접촉에 조금 당황스럽기까지 하다.)",
          DialogueId = 51000102,
          GUID = "7FAC643C",
          NextDialogue = 51000103
        },
        [51000103] = {
          ContentKR = "자, 여기 버섯 크림수프 좀 먹어보렴! 스칼렛에서 배운 건데, 이런 건 아마 처음 먹어 볼 거야.",
          DialogueId = 51000103,
          GUID = "7FAC6466",
          NextDialogue = 51000104,
          SpeakNpcId = 700020
        },
        [51000104] = {
          ContentKR = "(노부인은 다짜고짜 뜨거운 수프 한 그릇을 내밀었다. 금방이라도 내 머리를 붙잡고 억지로 들이부을 것만 같은 느낌이 들었다.)",
          DialogueId = 51000104,
          GUID = "7FAC6490",
          NextOptions = {
            [1] = 510001041,
            [2] = 510001042
          },
          bForbidSkipOptions = true
        },
        [51000105] = {
          ContentKR = "(향긋한 버섯과 달콤한 크림이 어우러진 수프가 목을 따뜻하게 적시자, 무척이나 편안한 기분이 들었다.)",
          DialogueId = 51000105,
          GUID = "7FAC64BA",
          NextDialogue = 51000106
        },
        [51000106] = {
          ContentKR = "어때. 내 말이 맞지? 호호.",
          DialogueId = 51000106,
          GUID = "7FAC64E4",
          NextDialogue = 51000108,
          SpeakNpcId = 700020
        },
        [51000107] = {
          ContentKR = "철없는 것! 좋은 걸 줘도 먹지를 못하니.",
          DialogueId = 51000107,
          GUID = "7FAC650E",
          NextDialogue = 51000108,
          SpeakNpcId = 700020
        },
        [51000108] = {
          ContentKR = "마님이 젊은 아가씨였을 때부터 내가 끓인 수프를 드셨으니, 벌써 40년이 다 되어 가는구나.",
          DialogueId = 51000108,
          GUID = "7FAC6538",
          NextDialogue = 51000109,
          SpeakNpcId = 700020
        },
        [51000109] = {
          ContentKR = "...에휴, 마님! 병이 나을 수 있을지 모르겠네.",
          DialogueId = 51000109,
          GUID = "7FAC6562",
          NextDialogue = 51000110,
          SpeakNpcId = 700020
        },
        [51000110] = {
          ContentKR = "(노부인의 눈에 가득했던 웃음기는 점차 사라지고, 그 자리를 반짝이는 눈물이 대신했다.)",
          DialogueId = 51000110,
          GUID = "7FAC658C",
          NextOptions = {
            [1] = 510001101
          }
        },
        [51000111] = {
          ContentKR = "그래, 하루가 다르게 나빠지고 있지... 그런데도 스칼렛을 놔두고 굳이 이렇게 추운 곳에 오려 하시다니, 아무리 말려도 소용없었어.",
          DialogueId = 51000111,
          GUID = "7FAC65B6",
          NextDialogue = 51000112,
          SpeakNpcId = 700020
        },
        [51000112] = {
          ContentKR = "40년 전 그 일을 아직도 마음에 두고서, 매일 거리에 나가 사람들에게 묻고 다니지, 나는 끼어들지도 못하게 하고.",
          DialogueId = 51000112,
          GUID = "7FAC65E0",
          NextDialogue = 51000190,
          SpeakNpcId = 700020
        },
        [51000113] = {
          ContentKR = "에구, 난 이제 일하러 가봐야겠다!",
          DialogueId = 51000113,
          GUID = "7FAC660A",
          NextDialogue = 51000114,
          SpeakNpcId = 700020
        },
        [51000114] = {
          ContentKR = "(어떤 일에 대해 수소문하는 부인이라... 만약 만나게 된다면, 한번 주의 깊게 살펴보는 것도 좋을 것 같다.)",
          DialogueId = 51000114,
          GUID = "7FAC6634"
        },
        [51000190] = {
          ContentKR = "나도 마님의 마음의 병은 어쩔 수 없다만, 대신 매일 다른 맛의 수프를 준비해서 몸이라도 좀 편해지길 바랄 뿐이지.",
          DialogueId = 51000190,
          GUID = "7FAC72AC",
          NextDialogue = 51000113,
          SpeakNpcId = 700020
        },
        [51000201] = {
          ContentKR = "오늘 저녁 버섯 크림수프가 마님의 기분을 조금이나마 풀어줄 수 있기를 바라며... 어머나? 돌아왔구나, 얘야.",
          DialogueId = 51000201,
          GUID = "7FAC747A",
          NextDialogue = 51000202,
          SpeakNpcId = 700020
        },
        [51000202] = {
          ContentKR = "(노부인이 두툼한 손으로 머리를 토닥이고, 뺨을 꼬집는다. 과하다 싶을 정도의 접촉에 조금 당황스럽기까지 하다.)",
          DialogueId = 51000202,
          GUID = "7FAC74A4",
          NextDialogue = 51000203
        },
        [51000203] = {
          ContentKR = "자, 여기 버섯 크림수프 좀 먹어보렴! 스칼렛에서 배운 건데, 이런 건 아마 처음 먹어 볼 거야.",
          DialogueId = 51000203,
          GUID = "7FAC74CE",
          NextDialogue = 51000204,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_Start"
          }
        },
        [51000204] = {
          ContentKR = "(노부인은 다짜고짜 뜨거운 수프 한 그릇을 내밀었다. 금방이라도 내 머리를 붙잡고 억지로 들이부을 것만 같은 느낌이 들었다.)",
          DialogueId = 51000204,
          GUID = "7FAC74F8"
        },
        [51000205] = {
          ContentKR = "(향긋한 버섯과 달콤한 크림이 어우러진 수프가 목을 따뜻하게 적시자, 무척이나 편안한 기분이 들었다.)",
          DialogueId = 51000205,
          GUID = "7FAC7522",
          NextDialogue = 51000206
        },
        [51000206] = {
          ContentKR = "어때. 내 말이 맞지? 호호.",
          DialogueId = 51000206,
          GUID = "7FAC754C",
          NextDialogue = 51000208,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51000207] = {
          ContentKR = "철없는 것! 좋은 걸 줘도 먹지를 못하니.",
          DialogueId = 51000207,
          GUID = "7FAC7576",
          NextDialogue = 51000208,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51000208] = {
          ContentKR = "마님이 젊은 아가씨였을 때부터 내가 끓인 수프를 드셨으니, 벌써 40년이 다 되어 가는구나.",
          DialogueId = 51000208,
          GUID = "7FAC75A0",
          NextDialogue = 51000209,
          SpeakNpcId = 700020
        },
        [51000209] = {
          ContentKR = "...에휴, 마님! 병이 나을 수 있을지 모르겠네.",
          DialogueId = 51000209,
          GUID = "7FAC75CA",
          NextDialogue = 51000210,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51000210] = {
          ContentKR = "(노부인의 눈에 가득했던 웃음기는 점차 사라지고, 그 자리를 반짝이는 눈물이 대신했다.)",
          DialogueId = 51000210,
          GUID = "7FAC75F4",
          TalkActionId = {
            [1] = "700020:Sigh_End"
          }
        },
        [51000301] = {
          ContentKR = "도대체 어디로 간 거야...",
          DialogueId = 51000301,
          GUID = "7FAC84E2",
          NextDialogue = 51000302,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Sigh_Start"
          }
        },
        [51000302] = {
          ContentKR = "(노부인의 슬픈 눈동자는 먼 곳에 고정되어 있었고, 목소리를 듣지 못한 듯했다.)",
          DialogueId = 51000302,
          GUID = "7FAC850C",
          NextOptions = {
            [1] = 510003021,
            [2] = 510003022,
            [3] = 510003023
          },
          bForbidSkipOptions = true
        },
        [51000303] = {
          ContentKR = "(옷은 오래됐지만 만듦새가 정교하고 세련됐다. 꽤 부유한 집안 출신일지도 모르겠다.)",
          DialogueId = 51000303,
          GUID = "7FAC8536",
          NextOptions = {
            [1] = 510003051,
            [2] = 510003053
          },
          bForbidSkipOptions = true
        },
        [51000304] = {
          ContentKR = "(내내 성 밖을 바라보며 누군가가 돌아오길 기다리는 것 같다.)",
          DialogueId = 51000304,
          GUID = "7FAC8560",
          NextOptions = {
            [1] = 510003051,
            [2] = 510003053
          },
          bForbidSkipOptions = true
        },
        [51000305] = {
          ContentKR = "(노쇠한 두 눈에 슬픔이 가득한 것이 꼭 길고 희망 없는 기다림을 겪은 듯하다.)",
          DialogueId = 51000305,
          GUID = "7FAC858A",
          NextOptions = {
            [1] = 510003051,
            [2] = 510003053
          },
          bForbidSkipOptions = true
        },
        [51000306] = {
          ContentKR = "(노부인은 당신을 뒤돌아보더니 다시 고개를 돌렸다. 당신의 말에 관심 없는 듯하다.)",
          DialogueId = 51000306,
          GUID = "7FAC85B4"
        },
        [51000307] = {
          ContentKR = "...너는...",
          DialogueId = 51000307,
          GUID = "7FAC85DE",
          NextDialogue = 51000308,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Sigh_End"
          }
        },
        [51000308] = {
          ContentKR = "처음 보는 얼굴이구나. 근처 마을에서 왔니?",
          DialogueId = 51000308,
          GUID = "7FAC8608",
          NextDialogue = 51000309,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain02_Start"
          }
        },
        [51000309] = {
          ContentKR = "혹시 하멜 디킨슨이라는 카론 남자를 본 적 있니? 아이스레이크 시티에서 태어났고, 옅은 갈색 머리에 열여덟아홉 살쯤 되었고, 즐겨 입는 옷은... 아니, 지금은 나랑 비슷한 나이가 됐을 거야.",
          DialogueId = 51000309,
          GUID = "7FAC8632",
          NextDialogue = 51000310,
          SpeakNpcId = 700019
        },
        [51000310] = {
          ContentKR = "내가 아이스레이크 시티를 떠난 게 벌써 40년 전이지. 그때부터 연락이 끊겼는데 이번에 돌아오고 나서도 소식을 전해 듣지 못했어.",
          DialogueId = 51000310,
          GUID = "7FAC865C",
          NextDialogue = 51000311,
          SpeakNpcId = 700019
        },
        [51000311] = {
          ContentKR = "그는 아이스레이크 시티에서 태어나고 자랐으니까, 여길 떠났다고 하더라도 멀리 가지 않았을 거야. 젊은이, 혹시 하멜을 본 적이 있을까?",
          DialogueId = 51000311,
          GUID = "7FAC8686",
          NextOptions = {
            [1] = 510003111
          },
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51000312] = {
          ContentKR = "그렇구나...",
          DialogueId = 51000312,
          GUID = "7FAC86B0",
          NextDialogue = 51000313,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Agree"
          }
        },
        [51000313] = {
          ContentKR = "만약 나중에 그를 만나게 된다면, 그에게 한 마디 전해 줄 수 있겠니?",
          DialogueId = 51000313,
          GUID = "7FAC86DA",
          NextDialogue = 51000314,
          SpeakNpcId = 700019
        },
        [51000314] = {
          ContentKR = "\"시린이 아이스레이크 시티에 돌아왔다. 그녀가 계속 당신을 기다리고 있었고, 40년이나 늦은 이유를 듣고 싶어 한다.\"라고 말이야.",
          DialogueId = 51000314,
          GUID = "7FAC8704",
          NextDialogue = 51000315,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain01_Start"
          }
        },
        [51000315] = {
          ContentKR = "내년에 만나면 왜 41년 늦었는지 물어보고, 내후년에는 42년... 이래 봬도 계속 세고 있었거든.",
          DialogueId = 51000315,
          GUID = "7FAC872E",
          NextDialogue = 51000316,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain01_End"
          }
        },
        [51000316] = {
          ContentKR = "(시린 부인은 엄청나게 괴로워 보인다. 샐리가 말한 사람이 바로 이 사람이겠지. 도와줄 방법이 있을 거야.)",
          DialogueId = 51000316,
          GUID = "7FAC8758"
        },
        [51000401] = {
          ContentKR = "애니... 애니!",
          DialogueId = 51000401,
          GUID = "7FAC954A",
          NextDialogue = 51000402,
          SpeakNpcId = 700006,
          Subtitle = "Annie... Annie!",
          TalkActionId = {
            [1] = "700006:Shock_Start"
          }
        },
        [51000402] = {
          ContentKR = "아아, 내 딸아, 돌아와 줬구나!",
          DialogueId = 51000402,
          GUID = "7FAC9574",
          NextDialogue = 51000403,
          SpeakNpcId = 700006,
          Subtitle = "Ah, you're back, my dear daughter!"
        },
        [51000403] = {
          ContentKR = "(여성이 앞길을 가로막는다. 그녀의 메마른 두 눈은 내 몸을 필사적으로 살펴보고, 마치 뭔가 찾으려는 것처럼 보였다.)",
          DialogueId = 51000403,
          GUID = "7FAC959E",
          NextOptions = {
            [1] = 510004031,
            [2] = 510004032,
            [3] = 510004033
          },
          Subtitle = "(A woman stops you. Her dry, vacant eyes roam over you, as if desperately searching for something inside of you.)",
          bForbidSkipOptions = true
        },
        [51000404] = {
          ContentKR = "돌아올 줄 알았어! 엄마를 두고 떠날 아이가 아니니까!",
          DialogueId = 51000404,
          GUID = "7FAC95C8",
          NextDialogue = 51000493,
          SpeakNpcId = 700006,
          Subtitle = "I knew you'd come back! How could you leave me like that!",
          TalkActionId = {
            [1] = "700006:Shock_End"
          }
        },
        [51000405] = {
          ContentKR = "(여자는 자신만의 세계 속에 빠져 있어 무슨 말을 해도 소용없다.)",
          DialogueId = 51000405,
          GUID = "7FAC95F2",
          Subtitle = "(The woman is lost in her own world, and no matter what you say, it's futile.)"
        },
        [51000406] = {
          ContentKR = "애니가 아니라고...?",
          DialogueId = 51000406,
          GUID = "7FAC961C",
          NextDialogue = 51000407,
          SpeakNpcId = 700006,
          Subtitle = "You just said you're not Annie...",
          TalkActionId = {
            [1] = "700006:Disagree"
          }
        },
        [51000407] = {
          ContentKR = "내 탓이야! 다 내 탓이라고! 내가 애니를 쫓아낸 거야... 나한텐 딸 밖에 없어. 우리 모녀는 서로 의지하며 지냈어. 딸을 찾아주면 뭐든 보답할게!",
          DialogueId = 51000407,
          GUID = "7FAC9646",
          NextOptions = {
            [1] = 510004071,
            [2] = 51000002
          },
          SpeakNpcId = 700006,
          Subtitle = "It's all my fault! I pushed Annie away... She's all I have, it's been just us two all along. I'll do anything for you if you find my baby!",
          TalkActionId = {
            [1] = "700006:Explain02_Start"
          },
          bForbidSkipOptions = true
        },
        [51000408] = {
          ContentKR = "고마워, 고마워...",
          DialogueId = 51000408,
          GUID = "7FAC9670",
          SpeakNpcId = 700006,
          Subtitle = "Thank you. Thank you so much...",
          TalkActionId = {
            [1] = "700006:Explain02_End"
          }
        },
        [51000409] = {
          ContentKR = "제발 부탁할게...",
          DialogueId = 51000409,
