          GUID = "7FAC96B1",
          NextDialogue = 51000443
        },
        [51000443] = {
          ContentKR = "(일기장에 적힌 내용이 사실이라면, 기억을 잃은 소녀의 진짜 정체는 이제 확실해진 셈이다.)",
          DialogueId = 51000443,
          GUID = "7FAC96B2",
          NextDialogue = 51000444
