          ToFinalCameraBlendTime = 3
        },
        [51002106] = {
          Camera = "-160.396484,-385.0,156.553223,0.0,-14.799763,65.201347,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(필토이드들을 상대하는 건 어렵지 않았지만, 이 작은 해프닝은 내게 왠지 모를 기시감을 불러일으켰다. 잊고 있던 기억이 되살아나면서, 이 집 앞에서 시끄럽게 장난을 치던 두 아이의 목소리가 어렴풋이 들려오는 것 같았다.)",
          DialogueId = 51002106,
          FinalCamera = "-160.396484,-404.0,156.553223,0.0,-14.799763,65.201347,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC89",
          NextDialogue = 51002107,
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 7
        },
        [51002107] = {
          Camera = "119.585938,-26.257812,128.0,-0.0,-9.999997,-145.798935,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "왜 싸웠는지는 가물가물한데, 싸우기 직전에 했던 말은 기억나... 걔가 날 애꾸눈이라고 하길래, 내가 걔한테 눈 툭 튀어나온 개구리라고 받아쳤었지.",
          DialogueId = 51002107,
          FinalCamera = "119.585938,-26.257812,128.0,0.0,-9.999997,-138.598923,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8A",
          NextDialogue = 51002108,
          Scripts = "TurnTo{_delay{3},TurnToDescription{\"100001:n(700211)\"}}",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 7
        },
        [51002108] = {
          Camera = "-180.842773,-670.0,18.0,0.000018,4.000004,83.599602,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "하하, 나도 입이 험했을 때가 있었네... 지금 생각해 보면 그땐 화도 별로 안 났던 것 같아. 어쨌든 내 곁엔 베레가 있었으니까.",
          DialogueId = 51002108,
          GUID = "7FADAC8B",
          NextDialogue = 51002109,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Think_Start"},Duration{2}},
CameraMoveTo{_delay{3},TargetPosition{"88.632812,-31.105469,133.52002,0.000039,-12.79989,-135.199905,35.0,100000.0,false,DoNotOverride,2.8"},duration{0}},
PlayAnimation{_delay{1},ActorId{700211},AnimationId{"Angry01_Start"},Duration{1}},
}]],
          SpeakNpcId = 100001
        },
        [51002109] = {
          Camera = "-143.595703,-312.263672,94.0,0.0,0.0,57.398624,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그다음엔... 화해했었나? 같이 지붕 위에 올라갔던 기억은 나는데...",
          DialogueId = 51002109,
          GUID = "7FADAC8C",
          NextDialogue = 51002110,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Sigh_Start"},Duration{3}},
PlayAnimation{ActorId{100001},AnimationId{"Sigh_End"},Duration{2}},
PlayAnimation{ActorId{100001},AnimationId{"Explain02_Start"},Duration{2}}
}]],
          SpeakNpcId = 100001
        },
        [51002110] = {
          Camera = "70.748047,32.113281,1751.04126,0.000001,-10.799894,-176.601151,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그래, 바로 여기야. 며칠 지나서 걔가 먹을 걸 한 봉지 가지고 와서 미안하다고 했었어. 처음엔 욕을 한 바가지 해 주려고 했었는데, 빵이 3명이 먹어도 될 만큼 들어 있는 걸 보곤 자존심이고 뭐고 싹 잊었지.",
          DialogueId = 51002110,
          FinalCamera = "70.748047,32.113281,1859.0,0.000001,-10.799894,-176.601151,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8D",
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 7
        },
        [51002111] = {
          Camera = "51.001041,365.471497,103.367798,0.000078,-11.300083,-137.003372,20.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "음... 우리 셋은 이렇게 지붕에 앉아 새카맣게 타서 딱딱해진 빵을 조용히 우물거리면서, 해가 뉘엿뉘엿 지고 어른들이 고기 잡은 걸 배에 싣고 돌아오는 모습을 지켜봤어.",
          DialogueId = 51002111,
          FinalCamera = "14.224466,404.913452,103.367798,0.000078,-11.300083,-137.003372,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8E",
          NextDialogue = 51002112,
          SpeakNpcId = 700210,
          ToFinalCameraBlendTime = 7
        },
        [51002112] = {
          Camera = "-78.281792,63.089108,96.67688,0.000094,-0.099919,90.79702,20.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그러다 막판엔 걔가 목이 메어서 계속 딸꾹질을 하는 바람에 우리 셋 다 웃음이 터져 버렸고, 싸움은 그렇게 싱겁게 끝났어.",
          DialogueId = 51002112,
          FinalCamera = "-123.657745,62.460995,96.67688,0.000094,-0.099919,90.797005,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8F",
          NextDialogue = 51002113,
          SpeakNpcId = 700210,
          ToFinalCameraBlendTime = 7
        },
        [51002113] = {
          Camera = "-182.640976,408.587311,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그러다 막판엔 걔가 목이 메어서 계속 딸꾹질을 하는 바람에 우리 셋 다 웃음이 터져 버렸고, 싸움은 그렇게 싱겁게 끝났어.",
          DialogueId = 51002113,
          FacialId = {
            [1] = "700210:Ahaha02"
          },
          FinalCamera = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC90",
          NextDialogue = 51002114,
          SpeakNpcId = 700210,
          ToFinalCameraBlendTime = 7
        },
        [51002114] = {
          Camera = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "만약 정말 아무것도 찾을 수 없다면, 뭐라도 좋으니 가져와만 주시오. 풀쪼가리라도 괜찮으니.",
          DialogueId = 51002114,
          FacialId = {
            [1] = "700210:Smile02"
          },
          GUID = "7FADAC91",
          NextDialogue = 51002115,
          SpeakNpcId = 700210
        },
        [51002115] = {
          Camera = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "요맘때 생선이 살도 오르고 맛도 좋았던 것 같은데, 브루네토 씨한테 특산물도 좀 가져다드려야겠어.",
          DialogueId = 51002115,
          GUID = "7FADAC92",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030106.T_Story_Recall_10030106'",
          NextDialogue = 51002116,
          SpeakNpcId = 700048
        },
        [51002116] = {
          Camera = "167.319687,115.790215,166.645142,0.000015,-18.599697,145.793152,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이제 돌아가자. 이만하면 브루네토 씨의 향수를 달래드릴 수 있을 거야.",
          DialogueId = 51002116,
          FinalCamera = "181.948135,137.309357,166.645142,0.000015,-18.599697,145.793152,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC93",
          SpeakNpcId = 700210,
          ToFinalCameraBlendTime = 7
        },
        [51002117] = {
          ContentKR = "손자는 나한테 싸움질, 할아버지는 나한테 사기질... 하하... 별 희한한 인연이 다 있네...",
          DialogueId = 51002117,
          Duration = 3,
          GUID = "7FADAC94",
          NextDialogue = 51002118,
          SpeakNpcId = 100001
        },
        [51002118] = {
          ContentKR = "손자는 나한테 싸움질, 할아버지는 나한테 사기질... 하하... 별 희한한 인연이 다 있네...",
          DialogueId = 51002118,
          Duration = 4,
          GUID = "7FADAC95",
          SpeakNpcId = 100001
        },
        [51002201] = {
          ContentKR = "지나가는 친구들, 발걸음을 잠시 멈춰보시오. 약간의 쿠퍼만 주면 아이스레이크 시티 어부 공제조합의 일원이 되어 최고의 최신 정보를 얻을 수 있소...아! 당신이군...",
          DialogueId = 51002201,
          GUID = "7FADBC9A",
          NextDialogue = 51002202,
          SpeakNpcId = 700048,
          Subtitle = "Ladies and gentlemen, drop by and drop a few coins, and you can join the Icelake Fishermen's Mutual Aid Society\nto get the best and latest— Oh! It's you..."
        },
        [51002202] = {
          ContentKR = "이거 아저씨 물건이죠?",
          DialogueId = 51002202,
          GUID = "7FADBCC4",
          NextDialogue = 51002203,
          SpeakNpcId = 100001,
          Subtitle = "Is this yours?"
        },
        [51002203] = {
          ContentKR = "오! 그렇소. 내가 어릴 적에 자주 본 책이라오. 그 무렵엔 늘 이 책을 읽으며 이 손바닥만 한 작은 섬을 떠나고 싶었다오...",
          DialogueId = 51002203,
          GUID = "7FADBCEE",
          NextDialogue = 51002204,
          SpeakNpcId = 700048,
          Subtitle = "Jesus! Yes, this is the book I used to read over and over again when I was a kid. I thought about coming to the land because of it...",
          TalkActionId = {
            [1] = "700048:Agree"
          }
        },
        [51002204] = {
          ContentKR = "고맙소, 고마워. 오늘 밤에 다시 한번 꼼꼼히 읽어봐야겠소. 하지만 지금은 여기까지만 얘기해야겠소. 당장 먹고살 돈을 버는 게 더 급하니.",
          DialogueId = 51002204,
          GUID = "7FADBD18",
          NextDialogue = 51002205,
          SpeakNpcId = 700048,
          Subtitle = "Thank you. Thank you so much. I need to give it a good read tonight. But for now, *sigh* making a living is more important.",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002205] = {
          ContentKR = "전 이만 가 볼게요. 앞으론 정직하게 사세요. 참, 이 말린 생선들도 드릴게요. 연옥도에서 낚은 걸로 만들었어요.",
          DialogueId = 51002205,
          GUID = "7FADBD42",
          NextDialogue = 51002206,
          SpeakNpcId = 100001,
          Subtitle = "Take care, and don't be a swindler anymore.",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002206] = {
          ContentKR = "이건... 고맙소, 정말 고맙구려...",
          DialogueId = 51002206,
          GUID = "7FADBD6C",
          SpeakNpcId = 700048,
          Subtitle = "Ladies and gentlemen, those who are interested in Icelake Fishermen's Mutual Aid Society can learn more about it. We have decades of fishing experience from veteran fishermen. Fishing is great either serving as a hobby or a job!"
        },
        [51002207] = {
          ContentKR = "아이스레이크 시티 어부 공제조합에 관심 있는 사람은 이리 오시오. 수십 년 경력의 베테랑 어부가 직접 지도해 주니 취미로든 일로든 아주 좋다오!",
          DialogueId = 51002207,
          GUID = "7FADBD96",
          NextDialogue = 51002208,
          SpeakNpcId = 700048
        },
        [51002208] = {
          ContentKR = "어이쿠, {Nickname} 자네였구려! 동향 사람끼리, 시간 날 때 낚시 노하우 이야기나 나눠 보는 건 어떻소?",
          DialogueId = 51002208,
          GUID = "7FADBD97",
          NextDialogue = 51002209,
          SpeakNpcId = 700048
        },
        [51002209] = {
          ContentKR = "시간 나면요.",
          DialogueId = 51002209,
          GUID = "7FADBDC0",
          SpeakNpcId = 100001
        },
        [51002301] = {
          ContentKR = "젊은이, 하멜 디킨슨에 관해 새로 들은 소식이 있니?",
          DialogueId = 51002301,
          GUID = "7FADCD02",
          NextOptions = {
            [1] = 510023011
          },
          SpeakNpcId = 700019
        },
        [51002302] = {
          ContentKR = "(그래, 글로스터 광갱의 그 이름 없는 일기장, 표지에 하멜 디킨슨이라는 일기 주인의 이름이 적혀 있었어.)",
          DialogueId = 51002302,
          GUID = "7FADCD2C",
          NextDialogue = 51002303
        },
        [51002303] = {
          ContentKR = "(내 추측이 맞다면, 그 광산 깊은 곳에 웅크리고 있는 괴물의 진짜 정체는...)",
          DialogueId = 51002303,
          GUID = "7FADCD56",
          NextDialogue = 51002304
        },
        [51002304] = {
          ContentKR = "(그 남자의 이름을 언급하자마자 노부인의 생기 없던 눈에 약간의 빛이 돈다. 하멜 디킨슨이라는 이름은 그녀에게 각별한 의미가 있는 듯하다. 그녀가 대답을 기다리고 있다.)",
          DialogueId = 51002304,
          GUID = "7FADCD80",
          NextOptions = {
            [1] = 510023041,
            [2] = 510023042
          },
          bForbidSkipOptions = true
        },
        [51002305] = {
          ContentKR = "...",
          DialogueId = 51002305,
          GUID = "7FADCDAA",
          NextDialogue = 51002306,
          SpeakNpcId = 700019
        },
        [51002306] = {
          ContentKR = "(노부인은 일기를 한 글자 한 글자 조용히 읽었다. 주름진 눈가에 눈물이 계속 흘러내렸다.)",
          DialogueId = 51002306,
          GUID = "7FADCDD4",
          NextDialogue = 51002307
        },
        [51002307] = {
          ContentKR = "(그러고는 오랫동안 헤어진 연인을 안아주듯 일기장을 가슴에 꽉 움켜쥐었다.)",
          DialogueId = 51002307,
          GUID = "7FADCDFE",
          NextDialogue = 51002308
        },
        [51002308] = {
          ContentKR = "... 젊은이, 고마워. 40년 동안 묻혀 있던 답을 찾아줘서 고마워.",
          DialogueId = 51002308,
          GUID = "7FADCE28",
          NextDialogue = 51002309,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain02_Start"
          }
        },
        [51002309] = {
          ContentKR = "보상은 내 메이드 샐리에게 가면 될 거야. 잠시 혼자 있고 싶어.",
          DialogueId = 51002309,
          GUID = "7FADCE52",
          NextDialogue = 51002310,
          SpeakNpcId = 700019
        },
        [51002310] = {
          ContentKR = "(노부인은 노쇠하고 구부정한 등만 남긴 채 돌아섰다.)",
          DialogueId = 51002310,
          GUID = "7FADCE7C"
        },
        [51002311] = {
          ContentKR = "...",
          DialogueId = 51002311,
          GUID = "7FADCEA6",
          SpeakNpcId = 700019
        },
        [51002312] = {
          ContentKR = "죄송합니다. 저는 이 이름을 들어본 적이 없어요. 나중에 소식이 있으면 다시 찾아뵐게요.",
          DialogueId = 51002312,
          GUID = "7FADCED0",
          NextDialogue = 51002313,
          SpeakNpcId = 100001
        },
        [51002313] = {
          ContentKR = "그... 그래. 젊은이, 고마워.",
          DialogueId = 51002313,
          GUID = "7FADCEFA",
          NextDialogue = 51002314,
          SpeakNpcId = 700019
        },
        [51002314] = {
          ContentKR = "작은 선물을 준비했으니, 집으로 가서 내 메이드 샐리를 찾아 시린 부인이 오라고 하면 돼.",
          DialogueId = 51002314,
          GUID = "7FADCF24",
          NextDialogue = 51002315,
          SpeakNpcId = 700019
        },
        [51002315] = {
          ContentKR = "가라, 앞으로 순조롭길 바랄게...",
          DialogueId = 51002315,
          GUID = "7FADCF4E",
          SpeakNpcId = 700019
        },
        [51002320] = {
          ContentKR = "월석 사냥꾼 {nickname} 맞지? 마님이 보상을 미리 주라고 하셨어.",
          DialogueId = 51002320,
          GUID = "7FADD020",
          NextDialogue = 51002321,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002321] = {
          ContentKR = "부탁할게. 하멜 디킨슨에 대해 무슨 소식이 있으면 꼭 빨리 마님께 알려줘.",
          DialogueId = 51002321,
          GUID = "7FADD04A",
          NextDialogue = 51002322,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002322] = {
          ContentKR = "휴... 마님은 작년부터 몸이 점점 나빠졌으니, 이제 아마도 시간이 얼마 남지 않은 것 같아. 하멜은 그녀의 마지막 걱정거리다...",
          DialogueId = 51002322,
          GUID = "7FADD074",
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_End"
          }
        },
        [51002401] = {
          ContentKR = "나와 마님을 위해 뛰어다녀줘서 고마워, 이건 그에 대한 작은 감사의 표시란다.",
          DialogueId = 51002401,
          GUID = "7FADDD6A",
          NextDialogue = 51002402,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002402] = {
          ContentKR = "휴, 마님은 작년부터 몸이 점점 나빠지고 있었는데, 이제 정말 얼마 남지 않았을지도 몰라. 하멜의 일은 부인께 남은 마지막 마음의 짐이었던 거지...",
          DialogueId = 51002402,
          GUID = "7FADDD94",
          NextDialogue = 51002403,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002403] = {
          ContentKR = "비록 좋은 소식은 아니었지만, 마님의 마지막 소원을 이뤄줘서 고마워!",
          DialogueId = 51002403,
          GUID = "7FADDDBE",
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_End"
          }
        },
        [51002404] = {
          ContentKR = "에휴... 이제 와서 더 이상 숨길 수도 없겠지.",
          DialogueId = 51002404,
          GUID = "7FADDDE8",
          NextDialogue = 51002405,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_Start"
          }
        },
        [51002405] = {
          ContentKR = "눈치챘겠지만, 하멜은 마님이 40년 전에 사랑했던 사람이야. 그때 마님은... 아니, 아가씨라고 불러야겠군. 그녀는 열정적이고 활발한 소녀였다네.하멜 디킨슨은 아가씨 또래의 광부로, 아가씨의 아버지가 관리하는 글로스터 광갱에서 일하고 있었지.",
          DialogueId = 51002405,
          GUID = "7FADDE12",
          NextDialogue = 51002406,
          SpeakNpcId = 700020
        },
        [51002406] = {
          ContentKR = "많은 로맨스가 그렇듯, 둘은 신분 차이가 큰 만큼 고집스럽게 온 세상의 뜻을 거스르며 함께하려 했지.",
          DialogueId = 51002406,
          GUID = "7FADDE3C",
          NextDialogue = 51002407,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51002407] = {
          ContentKR = "그런 이야기들은 사랑이 불덩이 같아서, 다른 사람들이 끄려고 할수록 더 세차게 타오르려고 하지. 하지만 그런 이야기들은 그 불덩어리가 현실 앞에서 얼마나 보잘것없는지 말해주지 않아!",
          DialogueId = 51002407,
          GUID = "7FADDE66",
          NextDialogue = 51002408,
          SpeakNpcId = 700020
        },
        [51002408] = {
          ContentKR = "이 사실을 알게 된 당시 어르신, 그러니까 공학 연금원에서 글로스터로 파견 나온 관리인에게 하멜은 축복이 아닌 심한 매질을 당했지.",
          DialogueId = 51002408,
          GUID = "7FADDE90",
          NextDialogue = 51002409,
          SpeakNpcId = 700020
        },
        [51002409] = {
          ContentKR = "그의 신분뿐만 아니라 어르신은 이미 아가씨를 플래그슨 주의 귀족에게 시집보내기로 하셨거든. 광산 재벌과 몰락 귀족이 서로 원하는 것을 얻을 수 있는 이보다 더 어울리는 결혼은 없었을 거야.",
          DialogueId = 51002409,
          GUID = "7FADDEBA",
          NextDialogue = 51002410,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_Start"
          }
        },
        [51002410] = {
          ContentKR = "하지만 아가씨는 포기하지 않았어. 그때의 아가씨는 용감하고 결연했지. 아가씨는 몰래 나에게 하멜에게 편지 한 통을 전해 달라고 부탁했고, 한 달 후인 4월 26일 자정에 은색 평화 광장에서 만나기로 약속했지.",
          DialogueId = 51002410,
          GUID = "7FADDEE4",
          NextDialogue = 51002411,
          SpeakNpcId = 700020
        },
        [51002411] = {
          ContentKR = "그날은 마침 어르신의 생신을 맞아 시종들이 연회 준비로 바쁠 테니까, 아가씨는 그날 도망칠 계획을 세웠어. 아가씨께 그것은 유일한 탈출 기회였다네.",
          DialogueId = 51002411,
          GUID = "7FADDF0E",
          NextDialogue = 51002412,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51002412] = {
          ContentKR = "아가씨는 하멜이 오기만 하면 그와 함께 어디든 떠나기로 결심했어.",
          DialogueId = 51002412,
          GUID = "7FADDF38",
          SpeakNpcId = 700020
        },
        [51002415] = {
          ContentKR = "맞아. 시린 아가씨는 날이 밝을 때까지 그곳에서 기다렸지만, 아가씨를 맞이한 것은 화가 난 아버지뿐이었네. 얼마 후 그녀는 마치 화물처럼 플래그슨 주로 시집보내졌지.",
          DialogueId = 51002415,
          GUID = "7FADDFB6",
          NextDialogue = 51002416,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002416] = {
          ContentKR = "다행히도! 아가씨의 남편, 즉 나중의 어르신은 아가씨께 정말 자상했고, 마님도 40년간 평온한 세월을 보낼 수 있었지.아가씨도 과거의 일을 입 밖에 내는 법이 없었고, 하멜 디킨슨이라는 사람이 존재한 적도 없는 것처럼 행동했지.",
          DialogueId = 51002416,
          GUID = "7FADDFE0",
          NextDialogue = 51002417,
          SpeakNpcId = 700020
        },
        [51002417] = {
          ContentKR = "1년 전 어르신이 돌아가시고 마님의 몸도 예전 같지 않아 지시더니, 하루는 그녀가 갑자기 나에게 인생의 마지막 시간을 아이스레이크 시티로 돌아가 한 번도 얻지 못한 답을 찾고 싶다고 말하더군.그때 알았지, 마님께 있어 하멜은 단 한 번도 잊힌 적이 없었고, 마음속의 가시가 되어버린 것뿐이었다는 것을.",
          DialogueId = 51002417,
          GUID = "7FADE00A",
          NextDialogue = 51002418,
          SpeakNpcId = 700020
        },
        [51002418] = {
          ContentKR = "우리는 아이스레이크 시티로 이주해 왔지만, 성안에는 하멜의 행방을 아는 사람이 아무도 없었어. 아직 살아 있는 늙은 광부들을 몇 찾아냈지만, 그들도 한참을 회고하다가 마지막으로 하멜을 본 것이 이미 40년 전의 일이었다는 것만 기억해 냈지...",
          DialogueId = 51002418,
          GUID = "7FADE034",
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002419] = {
          ContentKR = "에휴... 마님이 생전에 마지막 소원을 이루실 수 있을지 모르겠구나.",
          DialogueId = 51002419,
          GUID = "7FADE05E",
          NextDialogue = 51002420,
          SpeakNpcId = 700020
        },
        [51002420] = {
          ContentKR = "다 오래된 일인데... 아, 너한테 이렇게 많은 얘기를 종알거리다니, 나도 이제 늙었나 봐.",
          DialogueId = 51002420,
          GUID = "7FADE088",
          NextDialogue = 51002421,
          SpeakNpcId = 700020
        },
        [51002421] = {
          ContentKR = "월석 사냥꾼이면 바쁘겠다. 이만 가볼게.",
          DialogueId = 51002421,
          GUID = "7FADE0B2",
          NextDialogue = 51002422,
          SpeakNpcId = 700020
        },
        [51002422] = {
          ContentKR = "(그녀는 그 답을 알지 못할 것이다.)",
          DialogueId = 51002422,
          GUID = "7FADE0DC",
          NextDialogue = 51002423
        },
        [51002423] = {
          ContentKR = "(하멜은 시린을 위해 광갱 깊숙이 들어가 필토이드가 되었고, 40년간 공포의 전설이 되어 마침내 사살되었다. 이 진실은 시간은 얼마 남지 않은 노부인에게 너무나 잔혹했다.)",
          DialogueId = 51002423,
          GUID = "7FADE106",
          NextDialogue = 51002424
        },
        [51002424] = {
          ContentKR = "(이 잔혹한 진실은 영원히 폐허 속에 묻히고, 시린 부인은 희망을 안고 마지막을 맞이할 거다. 어쩌면 이것이 최선의 결말인지도 모르겠다.)",
          DialogueId = 51002424,
          GUID = "7FADE130"
        },
        [51002425] = {
          ContentKR = "...하지만 이런 결과였을 줄은 꿈에도 몰랐는데! 하멜은 약속을 어긴 게 아니라 마님과의 약속을 지키기 위해 그 광갱에 간 거였어... 이게 마님께 위안이 될지 잔인한 일인지는 모르겠지만 말이야.",
          DialogueId = 51002425,
          GUID = "7FADE15A",
          NextDialogue = 51002426,
          SpeakNpcId = 700020
        },
        [51002426] = {
          ContentKR = "...이제 와서 어떻게 마님을 위로해야 할지 정말 모르겠네...",
          DialogueId = 51002426,
          GUID = "7FADE184",
          NextDialogue = 51002427,
          SpeakNpcId = 700020
        },
        [51002427] = {
          ContentKR = "정말 골치 아프단 말이지! 우선은 저녁 식사를 준비하러 가는 수밖에. 적어도 내가 끓인 진한 수프를 먹으면 몸이라도 조금은 편해지실 거라고 믿어!",
          DialogueId = 51002427,
          GUID = "7FADE1AE",
          NextDialogue = 51002428,
          SpeakNpcId = 700020
        },
        [51002428] = {
          ContentKR = "(그래, 진실은 잔혹하지만 마지막에 40년이나 기다린 해답을 찾았고, 의문과 불만을 해결하지 못한 채 무덤에 들어가지는 않게 되었으니까. 아마도 이게 최선의 결말일지도 몰라.)",
          DialogueId = 51002428,
          GUID = "7FADE1D8"
        }
      }
    end
  },
  {
