          DialogueId = 51002503,
          GUID = "7FADEE26",
          SpeakNpcId = 700113
        },
        [51002504] = {
          ContentKR = "(말을 듣자마자 남자는 자루를 챙겨 도망치려 한다. 겨우 농담이었다는 말과 함께 신분을 밝히니 슬그머니 본인의 고충을 털어놓는다.)",
          DialogueId = 51002504,
          GUID = "7FADEE50"
        },
        [51002505] = {
          ContentKR = "구매자를 찾아 주시면 몫의 70%... 아니, 80%를 드릴게요! 부탁이에요, 제발!",
          DialogueId = 51002505,
          GUID = "7FADEE7A",
          SpeakNpcId = 700113,
          TalkActionId = {
            [1] = "700113:Sigh_Start"
          }
        },
        [51002506] = {
          ContentKR = "(남자의 의뢰를 수락하긴 했지만, 그의 표정과 자루에 말라붙어 있는 검붉은 흔적은 이 월석들이 정상적인 물건이 아니라는 걸 말해 주고 있었다.)",
          DialogueId = 51002506,
          GUID = "7FADEEA4",
