        },
        [51003820] = {
          Camera = "-196.32959,376.199219,82.648193,0.000135,0.0,-68.609573,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아니야!... 그게, 그러니까, 나는...",
          DialogueId = 51003820,
          FinalCamera = "-158.777344,280.334961,89.867432,0.000135,0.0,-68.609573,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAEC638",
          SpeakNpcId = 700012,
          TalkActionId = {
            [1] = "700012:Disagree"
          },
          ToFinalCameraBlendTime = 6
        },
        [51003821] = {
          ContentKR = "(소녀가 귀를 막은 채 달아난다.)",
          DialogueId = 51003821,
          GUID = "7FAEC662",
          Scripts = "MoveTo{ActorId{700012},MoveSpeed{300},TargetPoint{\"QuestPoint_FayeRun\"},Visibility{\"Hide\"}}"
        },
        [51003901] = {
          ContentKR = "(소녀가 고개를 숙인 채 구석에 서 있다. 기분이 안 좋아 보인다.)",
          DialogueId = 51003901,
          GUID = "7FAED382",
          NextOptions = {
            [1] = 510039011
          },
          bForbidSkipOptions = true
        },
        [51003902] = {
          ContentKR = "(소녀는 말하기 싫다는 듯 고개를 살짝 돌린다.)",
          DialogueId = 51003902,
          GUID = "7FAED3AC"
        },
        [51003903] = {
          ContentKR = "너구나...",
          DialogueId = 51003903,
          GUID = "7FAED3D6",
          NextDialogue = 51003904,
          SpeakNpcId = 700104,
          TalkActionId = {
            [1] = "700104:Explain02_Start"
          }
        },
        [51003904] = {
          ContentKR = "아까 그 녀석들은... 학교 친구야?",
          DialogueId = 51003904,
          GUID = "7FAED400",
          NextDialogue = 51003905,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700104:Explain02_End"
          }
        },
        [51003905] = {
          ContentKR = "응... 미안... 미안해... 내가 또 망쳤어.",
          DialogueId = 51003905,
          GUID = "7FAED42A",
          NextDialogue = 51003906,
          SpeakNpcId = 700104,
          TalkActionId = {
            [1] = "700104:Sigh_Start"
          }
        },
        [51003906] = {
          ContentKR = "그 녀석들이 널 괴롭히는 거지?",
          DialogueId = 51003906,
          GUID = "7FAED454",
          NextDialogue = 51003907,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700104:Sigh_End"
          }
        },
        [51003907] = {
          ContentKR = "아니야... 다 내 잘못인걸...",
          DialogueId = 51003907,
          GUID = "7FAED47E",
          NextDialogue = 51003908,
          SpeakNpcId = 700104,
          TalkActionId = {
            [1] = "700104:Disagree"
          }
        },
        [51003908] = {
          ContentKR = "난 잘하는 게 없어. 엄마랑 선생님도 내가 바보 같대.",
          DialogueId = 51003908,
          GUID = "7FAED4A8",
          NextDialogue = 51003909,
          SpeakNpcId = 700104,
          TalkActionId = {
            [1] = "700104:Disagree"
          }
        },
        [51003909] = {
          ContentKR = "그 아이들은 모두 똑똑해. 내가 부모님의 마법으로 뿔을 감췄을 뿐, 카론이라 머리가 나쁜 거라고 했어.",
          DialogueId = 51003909,
          GUID = "7FAED4D2",
          NextDialogue = 51003910,
          SpeakNpcId = 700104,
          TalkActionId = {
            [1] = "700104:Explain01_Start"
          }
        },
        [51003910] = {
          ContentKR = "다 내 잘못이야... 솔라들 사이에 있으면 안 됐는데...",
          DialogueId = 51003910,
          GUID = "7FAED4FC",
          NextDialogue = 51003911,
          SpeakNpcId = 700104,
          TalkActionId = {
            [1] = "700104:Explain01_End"
          }
        },
        [51003911] = {
          ContentKR = "(아니, 이건 그냥 구차한 변명이다. 페이의 말에 베레와 연옥도에서 당한 불쾌한 괴롭힘이 떠올랐다.)",
          DialogueId = 51003911,
          GUID = "7FAED526",
          NextDialogue = 51003912
        },
        [51003912] = {
          ContentKR = "(힘이 없거나 다르다는 이유로, 또 때로는 그런 이유조차 없이 괴롭히곤 한다. 사람들은 분출구를 원할 뿐이고, 안타깝게도 내가 그 대상이 된 것이다.)",
          DialogueId = 51003912,
          GUID = "7FAED550",
          NextDialogue = 51003913,
          TalkActionId = {
            [1] = "700104:Disagree"
          }
        },
        [51003913] = {
          ContentKR = "(소녀는 베레니카처럼 함께할 사람도 없으니, 예전의 나보다도 더 막막한 상황이다.)",
