          },
          SpeakNpcId = 700105,
          bForbidSkipOptions = true
        },
        [51004134] = {
          ContentKR = "한 번만 해보자!",
          DialogueId = 51004134,
          GUID = "7FAEF9BC",
          NextDialogue = 51004135,
          SpeakNpcId = 700105
        },
        [51004135] = {
          ContentKR = "(소녀는 까치발을 들고, 본인이 닿을 수 있을 정도로 나의 허리를 숙이게 했다. 이제 기운을 차린 것 같다.)",
          DialogueId = 51004135,
          GUID = "7FAEF9E6",
          NextDialogue = 51004136
        },
        [51004136] = {
          ContentKR = "음, 살짝만 숙여봐...",
          DialogueId = 51004136,
          GUID = "7FAEFA10",
          NextDialogue = 51004137,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain01_Start"
          }
        },
        [51004137] = {
          ContentKR = "(뒷머리를 땋는 게 느껴졌다. 소녀의 부드러운 동작 덕분에 이마를 다칠 걱정은 안 해도 될 것 같다.)",
          DialogueId = 51004137,
          GUID = "7FAEFA3A",
          NextDialogue = 51004138,
          TalkActionId = {
            [1] = "700105:Explain01_End"
          }
        },
        [51004138] = {
          ContentKR = "다 됐어! 와, 머리를 땋으니까 너무 귀여워!",
          DialogueId = 51004138,
          GUID = "7FAEFA64",
          NextDialogue = 51004139,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004139] = {
          ContentKR = "거울을 안 가져와서 아쉽네...",
          DialogueId = 51004139,
          GUID = "7FAEFA8E",
          NextDialogue = 51004140,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Think_Start"
          }
        },
        [51004140] = {
          ContentKR = "아... 내가 그려줄게!",
          DialogueId = 51004140,
          GUID = "7FAEFAB8",
          NextDialogue = 51004141,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Think_End"
          }
        },
        [51004141] = {
          ContentKR = "(소녀는 가방에서 노트를 꺼내 그 위에 당신의 모습을 그린다.)",
          DialogueId = 51004141,
          GUID = "7FAEFAE2",
          NextDialogue = 51004142
        },
        [51004142] = {
          ContentKR = "맞다, 이름이 뭐야?",
          DialogueId = 51004142,
          GUID = "7FAEFB0C",
          NextOptions = {
            [1] = 510041421
          },
          SpeakNpcId = 700105,
          bForbidSkipOptions = true
        },
        [51004143] = {
          ContentKR = "응! {nickname}, 절대 잊지 않을게. 여기 내 그림이야. 그럼 이만 가볼게!",
          DialogueId = 51004143,
          GUID = "7FAEFB36",
          NextDialogue = 51004144,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004144] = {
          ContentKR = "...신기해. 이게 바로 예술인가...",
          DialogueId = 51004144,
          GUID = "7FAEFB60",
          NextDialogue = 51004145,
          SpeakNpcId = 100001
        },
        [51004145] = {
          ContentKR = "(떠나려던 소녀가 갑자기 고개를 돌려 당신을 본다.)",
          DialogueId = 51004145,
          GUID = "7FAEFB8A",
          NextDialogue = 51004146
        },
        [51004146] = {
          ContentKR = "아, 참... 아까 머리 땋아줄 때 생각난 게 있어.",
          DialogueId = 51004146,
          GUID = "7FAEFBB4",
          NextDialogue = 51004147,
          SpeakNpcId = 700105
        },
        [51004147] = {
          ContentKR = "친구들이 카론은 악마의 아이라, 멍청하고 악해서 늘 못된 짓만 한다고 했거든...",
          DialogueId = 51004147,
          GUID = "7FAEFBDE",
          NextDialogue = 51004148,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain01_Start"
          }
        },
        [51004148] = {
          ContentKR = "근데... 사실이 아닌 거지?",
          DialogueId = 51004148,
          GUID = "7FAEFC08",
          NextDialogue = 51004149,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain01_End"
          }
        },
        [51004149] = {
          ContentKR = "너희들을 괴롭히려고 했던 핑계였던 거야, 그렇지?",
          DialogueId = 51004149,
          GUID = "7FAEFC32",
          NextOptions = {
            [1] = 510041491,
            [2] = 510041492
          },
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Confident_Start"
          },
          bForbidSkipOptions = true
        },
        [51004150] = {
          ContentKR = "너희는... 나보다 더 힘들었겠구나.",
          DialogueId = 51004150,
          GUID = "7FAEFC5C",
          NextDialogue = 51004151,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Confident_End"
          }
        },
        [51004151] = {
          ContentKR = "앞으로 내가 도울 일이 있으면 알려줘... 동족인 걸 떠나서 우리는 친구니까.",
          DialogueId = 51004151,
          GUID = "7FAEFC86",
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain02_Start"
          }
        },
        [51004152] = {
          ContentKR = "학교 친구들은 여전히 날 싫어하지만, 더 이상 두렵지 않아! 다 네 덕분이야!",
          DialogueId = 51004152,
          GUID = "7FAEFCB0",
          SpeakNpcId = 700105
        },
        [51004201] = {
          ContentKR = "쯧, 처음 보는 얼굴이군.",
          DialogueId = 51004201,
          GUID = "7FAF04BA",
          NextDialogue = 51004202,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Talk03_Start"
          }
        },
        [51004202] = {
          ContentKR = "(눈을 가늘게 뜬 남자가 터진 입술을 문지르며 무미건조하게 말했다.)",
          DialogueId = 51004202,
          GUID = "7FAF04E4",
          NextDialogue = 51004203
        },
        [51004203] = {
          ContentKR = "누구 소개로 왔지?",
          DialogueId = 51004203,
          GUID = "7FAF050E",
          NextOptions = {
            [1] = 510042031,
            [2] = 510042032,
            [3] = 510042033
          },
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Talk03_End"
          },
          bForbidSkipOptions = true
        },
        [51004204] = {
          ContentKR = "(새로운 질문을 건네는 것이 최고의 대답이다.)",
          DialogueId = 51004204,
          GUID = "7FAF0538",
          NextDialogue = 51004207
        },
        [51004205] = {
          ContentKR = "('소개'라고? 그렇다는 건 분명 누군가를 기다리고 있다.)",
          DialogueId = 51004205,
          GUID = "7FAF0562",
          NextDialogue = 51004207
        },
        [51004206] = {
          ContentKR = "(뭘 물어보는 건지는 모르겠지만, 이런 대답은 아무도 거절할 수 없다.)",
          DialogueId = 51004206,
          GUID = "7FAF058C",
          NextDialogue = 51004207
        },
        [51004207] = {
          ContentKR = "(잠시 침묵하던 남자가 나를 훑어봤다. 고개를 들 때, 그의 등뼈에서 피로한 소리가 나는 것처럼 보였다.)",
          DialogueId = 51004207,
          GUID = "7FAF05B6",
          NextDialogue = 51004208
        },
        [51004208] = {
          ContentKR = "시끄럽긴.",
          DialogueId = 51004208,
          GUID = "7FAF05E0",
          NextDialogue = 51004209,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Disagree"
          }
        },
        [51004209] = {
          ContentKR = "(그가 작게 콧방귀를 뀌었고, 내 대답에 만족한 것 같았다.)",
          DialogueId = 51004209,
          GUID = "7FAF060A",
          NextDialogue = 51004210
        },
        [51004210] = {
          ContentKR = "누가 불렀든, 내가 갖고 있는 물건 때문에 온 거잖아. 맞지?",
          DialogueId = 51004210,
          GUID = "7FAF0634",
          NextDialogue = 51004211,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Confident_Start"
          }
        },
        [51004211] = {
          ContentKR = "(남자가 옷깃을 젖히자 검은 물체가 반짝였다. )",
          DialogueId = 51004211,
          GUID = "7FAF065E",
          NextDialogue = 51004212,
          TalkActionId = {
            [1] = "700096:Confident_End"
          }
        },
        [51004212] = {
          ContentKR = "(그리는 바로 옷깃을 여미고 주변을 경계한다.)",
          DialogueId = 51004212,
          GUID = "7FAF0688",
          NextDialogue = 51004213
        },
        [51004213] = {
          ContentKR = "4구경 연발식 샷건이다. 카론이든 필토이드든 한 방에 처리할 수 있지.",
          DialogueId = 51004213,
          GUID = "7FAF06B2",
          NextDialogue = 51004214,
          SpeakNpcId = 700096
        },
        [51004214] = {
          ContentKR = "(남자는 농업용 살충제의 효능을 설명하기라도 하듯 샐쭉한 표정을 짓는다.)",
          DialogueId = 51004214,
          GUID = "7FAF06DC",
          NextDialogue = 51004215
        },
        [51004215] = {
          ContentKR = "물건값은 받지 않을게. 대신 내 부탁 좀 들어줘.",
          DialogueId = 51004215,
          GUID = "7FAF0706",
          NextOptions = {
            [1] = 510042151,
            [2] = 510042152
          },
          SpeakNpcId = 700096,
          bForbidSkipOptions = true
        },
        [51004216] = {
          ContentKR = "뭘 그렇게 우물쭈물거려? 이것 때문에 온 거 아냐?",
          DialogueId = 51004216,
          GUID = "7FAF0730",
          NextDialogue = 51004217,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Explain01_Start"
          }
        },
        [51004217] = {
          ContentKR = "일만 제대로 처리하면, 물건에다가 추가로 보수도 줄게.",
          DialogueId = 51004217,
          GUID = "7FAF075A",
          NextOptions = {
            [1] = 510042171,
            [2] = 510042172
          },
          RestartTag = 51004216,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51004218] = {
          ContentKR = "오래 못 기다리니까 빨리 결정해.",
          DialogueId = 51004218,
          GUID = "7FAF0784",
          SpeakNpcId = 700096
        },
        [51004219] = {
          ContentKR = "좋아요. 제가 뭘 하면 되죠?",
          DialogueId = 51004219,
          GUID = "7FAF07AE",
          NextDialogue = 51004220,
          SpeakNpcId = 100001
        },
        [51004220] = {
          ContentKR = "시원시원하군. 내가 주소를 알려줄 테니, 그곳에 있는 여자만 제외하고 나머지를 모두 없애버려.",
          DialogueId = 51004220,
          GUID = "7FAF07D8",
          NextDialogue = 51004221,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Agree"
          }
        },
        [51004221] = {
          ContentKR = "혹시... 치정 문제인가요...?",
          DialogueId = 51004221,
          GUID = "7FAF0802",
          NextDialogue = 51004222,
          SpeakNpcId = 100001
        },
        [51004222] = {
          ContentKR = "조용히 해.",
          DialogueId = 51004222,
          GUID = "7FAF082C",
          NextDialogue = 51004223,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Disagree"
          }
        },
        [51004223] = {
          ContentKR = "(남자는 다시 옷깃을 여미고, 마른 입술을 문지르며 말을 아꼈다.)",
          DialogueId = 51004223,
          GUID = "7FAF0856"
        },
        [51004301] = {
          ContentKR = "됐어. 돈 받았으면 이제 가 봐. 이 근처에서 다시 마주치는 일은 없었으면 좋겠군.",
          DialogueId = 51004301,
          GUID = "7FAF1522",
          NextDialogue = 51004302,
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "700101:Agree"
          }
        },
        [51004302] = {
          ContentKR = "이 부근의 필토이드를 처치하려는 거였어요? 제가 아니었어도 누군가는 필토이드를 처리했을 텐데요.",
          DialogueId = 51004302,
          GUID = "7FAF154C",
          NextDialogue = 51004303,
          SpeakNpcId = 100001
        },
        [51004303] = {
          ContentKR = "누군가가 한다고? 누가? 설마 카론을 얕보는 그 비열한 자식들이?",
          DialogueId = 51004303,
          GUID = "7FAF1576",
          NextDialogue = 51004304,
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "700101:Angry01_Start"
          }
        },
        [51004304] = {
          ContentKR = "저들이 문을 열고 들어왔는데, 연약한 카론 여자 홀로 살고 있다고 생각해 봐. 저들이 과연 어떻게 했을까?",
          DialogueId = 51004304,
          GUID = "7FAF15A0",
          NextDialogue = 51004305,
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "700101:Angry01_End"
          }
        },
        [51004305] = {
          ContentKR = "(남자가 갑자기 가슴을 부여잡더니 고통을 참는 듯 부들부들 몸을 떨었다. 한참 뒤 진정한 후, 고개를 돌려 침을 뱉었다.)",
          DialogueId = 51004305,
          GUID = "7FAF15CA",
          NextDialogue = 51004306
        },
        [51004306] = {
          ContentKR = "한 착한 카론 여자가, 어느날 길가에 중상을 입고 쓰러져 있는 낯선 사람을 구하려고 내성에서 뛰쳐나오는 개를 때렸다.",
          DialogueId = 51004306,
          GUID = "7FAF15F4",
          NextDialogue = 51004307,
          SpeakNpcId = 700101
        },
        [51004307] = {
          ContentKR = "내성의 개를 때렸다고 여자는 흠씬 두들겨 맞고, 아이스레이크 시티 밖으로 끌려 나와 여기 황무지에 버려졌지.",
          DialogueId = 51004307,
          GUID = "7FAF161E",
          NextDialogue = 51004308,
          SpeakNpcId = 700101
        },
        [51004308] = {
          ContentKR = "그럼... 그 여자가 아이스레이크 시티가 아닌 다른 곳에서 살 방법을 생각하면 되잖아요.",
          DialogueId = 51004308,
          GUID = "7FAF1648",
          NextDialogue = 51004309,
          SpeakNpcId = 100001
        },
        [51004309] = {
          ContentKR = "...그것도 금방이야. 돈을 거의 다 모았거든.",
          DialogueId = 51004309,
          GUID = "7FAF1672",
          NextDialogue = 51004310,
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "700101:Agree"
          }
        },
        [51004310] = {
          ContentKR = "(남자는 몸을 돌려 텐트 쪽을 바라봤다. 굳게 다물고 있던 그의 입가에 옅은 미소가 보이는 듯했다.)",
          DialogueId = 51004310,
          GUID = "7FAF169C",
          LookAt = {
            [1] = "700101:n(700100)"
          },
          NextDialogue = 51004311,
          TurnTo = {
            [1] = "700101:n(700100)"
          }
        },
        [51004311] = {
          ContentKR = "(썩은 나무가 갈라지며 나는, 마른 소리를 들은 것 같다.)",
          DialogueId = 51004311,
          GUID = "7FAF16C6"
        },
        [51004401] = {
          ContentKR = "하수도에서 영원히 사라지지 않는 게 뭔지 알아?",
          DialogueId = 51004401,
          GUID = "7FAF258A",
          NextOptions = {
            [1] = 510044011,
            [2] = 510044012,
            [3] = 510044013
          },
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          bForbidSkipOptions = true
        },
        [51004402] = {
          ContentKR = "들어와.",
          DialogueId = 51004402,
          GUID = "7FAF25B4",
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51004403] = {
          ContentKR = "여긴 아무것도 모르는 멍청이가 올 곳이 아니야.",
          DialogueId = 51004403,
          GUID = "7FAF25DE",
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51004501] = {
          Camera = "-234.128906,122.0,168.883789,0.0,-11.799739,-20.999071,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "여자는 없고 필토이드만 있길래 전부 해치웠어요. 설마 이 허허벌판까지 갈아엎어 달라는 건 아니죠?",
          DialogueId = 51004501,
          FinalCamera = "-234.128906,132.925781,168.883789,0.0,-11.799766,-20.999094,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF35F2",
          LookAt = {
