          }
        },
        [51004504] = {
          Camera = "265.636719,135.800781,103.029297,0.00002,1.999995,-157.798172,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "프로답군. 월석 사냥꾼이라면 그 정도는 돼야지. 미안하지만 널 시험해 봤어. 이 바닥은 늘 조심해서 나쁠 게 없거든.",
          DialogueId = 51004504,
          GUID = "7FAF3670",
          NextDialogue = 51004505,
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700101:Agree"
          }
        },
        [51004505] = {
          Camera = "265.636719,135.800781,103.029297,0.00002,1.999995,-157.798172,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이 종이에 적힌 곳으로 가라. 아까처럼, 여자만 빼고 모조리 쓸어버리면 돼.",
          DialogueId = 51004505,
          GUID = "7FAF369A",
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "700101:Give"
          }
        },
        [51004901] = {
          Content = "（街边一位拿着一叠纸的女人吸引了你的注意：你留意到纸上罗列着一些药剂。也许这个女人与<H>玛尔洁给的某个线索</>有关。）",
          DialogueId = 51004901,
          GUID = "7FAF7792",
          LookAt = {
            [1] = "700010:n(0)"
          }
        },
        [51004902] = {
          ContentKR = "마르제가 전해준 단서들 중 하나를 그녀에게 보여주기로 한다.",
          DialogueId = 51004902,
          FinalDialogueId = 51004905,
          GUID = "7FAF77BC",
          NextOptions = {
            [1] = 510049021,
            [2] = 510049022,
            [3] = 510049023
          },
          bForbidSkipOptions = true
        },
        [51004903] = {
          ContentKR = "(여자가 말없이 경계하며 고개를 젓는다. 그녀가 잃어버린 물건이 아닌 것 같다.)",
          DialogueId = 51004903,
          GUID = "7FAF77E6",
          NextOptions = {
            [1] = 510049031,
            [2] = 510049032
          },
          TalkActionId = {
            [1] = "700010:Disagree"
          },
          bForbidSkipOptions = true
        },
        [51004905] = {
          ContentKR = "루나... 의사 선생님? 이 처방전은 당신 건가요?",
          DialogueId = 51004905,
          GUID = "7FAF783A",
          NextDialogue = 51004906,
          SpeakNpcId = 100001
        },
        [51004906] = {
          ContentKR = "(처방전에 적힌 글이 보이도록 종이를 펼쳐 루나에게 건넨다.)",
          DialogueId = 51004906,
          GUID = "7FAF7864",
          NextDialogue = 51004907
        },
        [51004907] = {
          ContentKR = "'성 밖의 필토이드는 우리의 살을 먹고, 성안의 농장주는 우리의 털을 깎는다. 사냥개는 흰 빵을 먹지만, 우리 카론은 양처럼 풀만 뜯어 먹는다네. 뒹굴고 꼬리를 흔들며 주인의 환심만 살 뿐이다.'",
          DialogueId = 51004907,
          GUID = "7FAF788E",
          NextDialogue = 51004908,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004908] = {
          ContentKR = "아... 어, 으어어...",
          DialogueId = 51004908,
          GUID = "7FAF78B8",
          NextDialogue = 51004909,
          SpeakNpcId = 700010,
          TalkActionId = {
            [1] = "700010:Shock_Start"
          }
        },
        [51004909] = {
          ContentKR = "(종이를 본 루나가 우물쭈물하며 허공에 다급한 손짓을 했다. 필체나 반응을 보니 주인을 찾은 것 같다.)",
          DialogueId = 51004909,
          GUID = "7FAF78E2",
          NextOptions = {
            [1] = 510049091,
            [2] = 510049092
          },
          TalkActionId = {
            [1] = "700010:Shock_Loop"
          }
        },
        [51004910] = {
          ContentKR = "(루나가 평정심을 되찾는다.)",
          DialogueId = 51004910,
          GUID = "7FAF790C",
          NextDialogue = 51004912,
          TalkActionId = {
            [1] = "700010:Shock_End"
          }
        },
        [51004911] = {
          ContentKR = "(루나가 더 초조해진 것 같다.)",
          DialogueId = 51004911,
          GUID = "7FAF7936",
          NextDialogue = 51004912,
          TalkActionId = {
            [1] = "700010:Shock_End"
          }
        },
        [51004912] = {
          ContentKR = "다른 사람이 이 종이를 보면 당신이 곤란해지나요?",
          DialogueId = 51004912,
          GUID = "7FAF7960",
          NextDialogue = 51004913,
          SpeakNpcId = 100001
        },
        [51004913] = {
          ContentKR = "(루나가 자기 목을 가리키더니, 곧바로 빈 종이를 집어 들고 무언가를 급히 써 내려간다.)",
          DialogueId = 51004913,
          GUID = "7FAF798A",
          NextDialogue = 51004914,
          TalkActionId = {
            [1] = "700010:Explain02_Start"
          }
        },
        [51004914] = {
          ContentKR = "'전 원래 음유시인이었어요. 그런데 카론인을 증오하는 사람들이 절 납치해서 조롱과 구타를 가했고, 머리카락과 피부엔 칼질까지 했죠.'",
          DialogueId = 51004914,
          GUID = "7FAF79B4",
          NextDialogue = 510049141,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Explain02_End"
          }
        },
        [51004915] = {
          ContentKR = "그런 일을 겪었는데도 아직까지 펜을 놓지 못하는 이유는 뭐예요?",
          DialogueId = 51004915,
          GUID = "7FAF79DE",
          NextDialogue = 51004916,
          SpeakNpcId = 100001
        },
        [51004916] = {
          ContentKR = "(루나가 다시 고개를 숙여 종이에 뭔가를 쓴다.)",
          DialogueId = 51004916,
          GUID = "7FAF7A08",
          NextDialogue = 51004917
        },
        [51004917] = {
          ContentKR = "'마음에 담아놓고 있기엔 너무 고통스러워요.'",
          DialogueId = 51004917,
          GUID = "7FAF7A32",
          NextOptions = {
            [1] = 510049171,
            [2] = 510049172,
            [3] = 510049173
          },
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Disagree"
          },
          bForbidSkipOptions = true
        },
        [51004918] = {
          ContentKR = "'맞아요. 변하는 것도 없고, 제가 쓴 이 글을 남에게 보여줄 용기도 없죠. 그렇지만 그래도 참을 수 없어요.'",
          DialogueId = 51004918,
          GUID = "7FAF7A5C",
          NextDialogue = 51004919,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004919] = {
          ContentKR = "'전 이제 노래도 할 수 없답니다. 글조차 쓰지 못한다면 마지막 남은 소중한 것을 잃는 거라 그때는 정말 아무것도 안 남을 거예요.'",
          DialogueId = 51004919,
          GUID = "7FAF7A86",
          NextDialogue = 51004920,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004920] = {
          ContentKR = "우울하면 좀 더 현실적인 일을 찾아봐요. 그게 더 좋을 거예요. 그리고 글을 쓰더라도, 다음부터는 잃어버리지 않도록 조심해요.",
          DialogueId = 51004920,
          GUID = "7FAF7AB0",
          NextDialogue = 51004921,
          SpeakNpcId = 100001
        },
        [51004921] = {
          ContentKR = "(여자는 한참을 생각하더니 고개를 끄덕였다.)",
          DialogueId = 51004921,
          GUID = "7FAF7ADA",
          NextDialogue = 51004922,
          TalkActionId = {
            [1] = "700010:Agree"
          }
        },
        [51004922] = {
          ContentKR = "'돌려주셔서 정말 고마워요. 이건 제 보답이에요.'",
          DialogueId = 51004922,
          GUID = "7FAF7B04",
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004923] = {
          ContentKR = "'과찬이세요. 저는 종이에만 불평을 쏟아놓는 겁쟁이인걸요. 남에게 보여줄 용기도 없어요.'",
          DialogueId = 51004923,
          GUID = "7FAF7B2E",
          NextDialogue = 51004924,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Disagree"
          }
        },
        [51004924] = {
          ContentKR = "속마음을 써 내려갈 수 있다는 것만으로도 이미 누구보다 용감한 사람이에요. 다만 다음부터는 잃어버리지 않도록 잘 챙기세요.",
          DialogueId = 51004924,
          GUID = "7FAF7B58",
          NextDialogue = 51004925,
          SpeakNpcId = 100001
        },
        [51004925] = {
          ContentKR = "(여자는 미소를 띤 채 고개를 끄덕였다. 눈에는 눈물이 고여 있었다.)",
          DialogueId = 51004925,
          GUID = "7FAF7B82",
          NextDialogue = 51004926
        },
        [51004926] = {
          ContentKR = "'돌려주셔서 정말 고마워요. 이건 제 보답이에요.'",
          DialogueId = 51004926,
          GUID = "7FAF7BAC",
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004927] = {
          ContentKR = "(여자는 갈라진 목소리로 비명을 지르며, 두 손에 얼굴을 파묻었다. 그리고 벌벌 떨면서 가방에서 물건을 꺼냈다.)",
          DialogueId = 51004927,
          GUID = "7FAF7BD6",
          NextDialogue = 51004928,
          TalkActionId = {
            [1] = "700010:Sigh_Start"
          }
        },
        [51004928] = {
          ContentKR = "'이걸 다 드릴 테니까 그 종이는 제발 돌려주세요.'",
          DialogueId = 51004928,
          GUID = "7FAF7C00",
          NextDialogue = 51004929,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004929] = {
          ContentKR = "(흡족한 듯 고개를 끄덕였다. 이 종이가 다른 사람의 손에 들어가면 그녀는 지금보다 더 큰 피해를 입게 된다. 고통을 덜어줬으니 이건 당신이 마땅히 받아야 하는 보상이다.)",
          DialogueId = 51004929,
          GUID = "7FAF7C2A"
        },
        [51004930] = {
          ContentKR = "으으... 아아...",
          DialogueId = 51004930,
          GUID = "7FAF7C54",
          NextDialogue = 51004931,
          SpeakNpcId = 700010
        },
        [51004931] = {
          ContentKR = "(루나는 여전히 알아들을 수 없는 말을 내뱉었고, 나의 시선을 피했다.)",
          DialogueId = 51004931,
          GUID = "7FAF7C7E"
        },
        [51004935] = {
          Camera = "-843.349854,-34.817383,370.464844,0.000092,-16.799791,-21.997007,35.0,100000.0,false,Manual,2.8",
          ContentKR = "죽고 싶어서 환장했어? 당장 내놔!",
          DialogueId = 51004935,
          FinalCamera = "-635.633789,-118.727051,302.828857,0.000092,-16.799791,-21.997007,35.0,100000.0,false,Manual,2.8",
          GUID = "7FAF7C7F",
          NextDialogue = 51004936,
          SpeakNpcId = 700225,
          ToFinalCameraBlendTime = 10
        },
        [51004936] = {
          ContentKR = "어디 보자, 이번엔 또 얼마나 대단한 걸 끄적이고 계셨으려나?",
          DialogueId = 51004936,
          GUID = "7FAF7C80",
          NextDialogue = 51004937,
          SpeakNpcId = 700226
        },
        [51004937] = {
          ContentKR = "저번엔 목이 맛이 가더니, 이번엔 어디냐? 눈? 손?",
          DialogueId = 51004937,
          GUID = "7FAF7C81",
          NextDialogue = 51004938,
          SpeakNpcId = 700225
        },
        [51004938] = {
          ContentKR = "우으.. 아아!",
          DialogueId = 51004938,
          GUID = "7FAF7C82",
          NextDialogue = 51004939,
          SpeakNpcId = 700010
        },
        [51004939] = {
          ContentKR = "(악당들에게 둘러싸인 여자가 허둥지둥 바닥에 흩어진 종이를 주워 모은다. 하얗게 질린 얼굴로 아랫입술을 꼭 깨문 그녀의 눈엔 두려움이 가득하다. 세 사람이 어떤 사이인지는 모르지만, 여자가 위험에 처해 있다는 사실만은 분명하다.)",
          DialogueId = 51004939,
          GUID = "7FAF7C83"
        },
        [51004941] = {
          ContentKR = "(루나는 고맙다는 듯 허겁지겁 허리를 숙여 인사를 건네더니, 곧이어 긴장한 듯 바닥에 흩어진 종이를 다시 주워 모으기 시작한다.)",
          DialogueId = 51004941,
          GUID = "7FAF7C84",
          NextDialogue = 51004942
        },
        [51004942] = {
          ContentKR = "다친 데는 없으세요? 이 종이들은 뭔가요?",
          DialogueId = 51004942,
          GUID = "7FAF7C85",
          NextDialogue = 51004943,
          SpeakNpcId = 100001
        },
        [51004943] = {
          ContentKR = "우으... 흑흑!",
          DialogueId = 51004943,
          GUID = "7FAF7C86",
          NextDialogue = 51004944,
          SpeakNpcId = 700010
        },
        [51004944] = {
          ContentKR = "(그 종이들에 적힌 '처방전'이라는 글자가 눈에 들어온다... 혹시 이 여자는 <H>마르제가 건네준 어떤 단서</>의 관련자 아닐까?)",
          DialogueId = 51004944,
          GUID = "7FAF7C87",
          NextOptions = {
            [1] = 510049011,
            [2] = 510049012
          },
          bForbidSkipOptions = true
        },
        [51004945] = {
          ContentKR = "우으... 우으으음.",
          DialogueId = 51004945,
          GUID = "7FAF7C88",
          NextDialogue = 51004946,
          SpeakNpcId = 700010
        },
        [51004946] = {
          ContentKR = "(여자는 고맙다는 듯 부드럽게 미소 짓는다.)",
          DialogueId = 51004946,
          GUID = "7FAF7C89",
          NextDialogue = 51004947,
          SpeakNpcId = 700010
        },
        [51004947] = {
          ContentKR = "아는 의사 선생님이 하나 있어요. 지금은 아이스레이크 시티 말고 다른 데서 지내는데, 예전에 머물던 곳에 가서 도움이 될 만한 처방전이 있는지 찾아봐 드릴게요.",
          DialogueId = 51004947,
          GUID = "7FAF7C8A",
          NextDialogue = 51004948,
          SpeakNpcId = 100001
        },
        [51004948] = {
          ContentKR = "우으...",
          DialogueId = 51004948,
          GUID = "7FAF7C8B",
          NextDialogue = 51004949,
          SpeakNpcId = 700010
        },
        [51004949] = {
          ContentKR = "(루나는 자신의 목 상태가 절망적이란 걸 아는 듯 고개를 숙인다. 그러나 다시 마주한 그녀의 눈동자는 '만약'의 가능성에 희망을 품고 반짝이고 있었다.)",
          DialogueId = 51004949,
          GUID = "7FAF7C8C"
        },
        [51004950] = {
          ContentKR = "우으... 아아!",
          DialogueId = 51004950,
          GUID = "7FAF7C8D",
          NextDialogue = 51004951,
          SpeakNpcId = 700010
        },
        [51004951] = {
          ContentKR = "(여자는 '정말 가진 돈이 없어요'라고 호소하듯, 날 경계하며 필사적으로 고개를 젓는다.)",
          DialogueId = 51004951,
          GUID = "7FAF7C8E",
          NextDialogue = 51004952,
          SpeakNpcId = 700010
        },
        [51004952] = {
          ContentKR = "저기, 이번엔 도와주러 온 거니까 그렇게 긴장하지 말아요. 저번에 당신 걸 그냥 가져갔지만, 그건 제 방식이 아니었어요.",
          DialogueId = 51004952,
          GUID = "7FAF7C8F",
          NextDialogue = 51004953,
          SpeakNpcId = 100001
        },
        [51004953] = {
          ContentKR = "아는 의사 선생님이 하나 있어요. 지금은 아이스레이크 시티 말고 다른 데서 지내는데, 예전에 머물던 곳에 가서 도움이 될 만한 처방전이 있는지 찾아봐 드릴게요.",
          DialogueId = 51004953,
          GUID = "7FAF7C90",
          NextDialogue = 51004954,
          SpeakNpcId = 100001
        },
        [51004954] = {
          ContentKR = "(루나는 의심스럽다는 표정을 지었다. 지금의 난 그녀에게 그다지 신뢰를 주지 못하는 모양이다.)",
          DialogueId = 51004954,
          GUID = "7FAF7C91"
        },
        [51004955] = {
          ContentKR = "(어느 책장 위)",
          DialogueId = 51004955,
          GUID = "7FAF7C92"
        },
        [51004956] = {
          ContentKR = "(아이스레이크 시티는 종종 원인 모를 감기가 광풍처럼 휩쓸고 지나가곤 한다.\n금방 낫기는 해도, 아이들에게는 여간 고역이 아니다.\n—감기 특효약)",
          DialogueId = 51004956,
          Duration = 4,
          GUID = "7FAF7C93",
          IsBlack = 1,
          NextDialogue = 51004957
        },
        [51004957] = {
          ContentKR = "이건 아닌 것 같아.",
          DialogueId = 51004957,
          Duration = 3,
          GUID = "7FAF7C94",
          SpeakNpcId = 100001
        },
        [51004958] = {
          ContentKR = "(어느 책장 위)",
          DialogueId = 51004958,
          GUID = "7FAF7C95"
        },
        [51004959] = {
          ContentKR = "(수상한 처방전. 침식 치료 약물 개발 도중 만들어진 실패작이었지만, 이후 실험을 통해 몇몇 난치병에 뛰어난 효능을 가지고 있다는 사실이 밝혀졌다.)",
          DialogueId = 51004959,
          Duration = 4,
          GUID = "7FAF7C96",
          IsBlack = 1,
          NextDialogue = 51004960
        },
        [51004960] = {
          ContentKR = "이건 아닌 것 같아.",
          DialogueId = 51004960,
          Duration = 3,
          GUID = "7FAF7C97",
          SpeakNpcId = 100001
        },
        [51004961] = {
          ContentKR = "(바닥 위)",
          DialogueId = 51004961,
          GUID = "7FAF7C98"
        },
        [51004962] = {
          ContentKR = "(배고픔에 못 이겨 로터스를 잘못 먹는 경우가 더러 있는데, \n만약 중독 증상이 심하지 않다면, 이 약으로 체내의 독소를 중화할 수 있다. —로터스 해독제)",
          DialogueId = 51004962,
          Duration = 5,
          GUID = "7FAF7C99",
          IsBlack = 1
        },
        [51004963] = {
          ContentKR = "이게 왜 바닥에 떨어져 있지? 이거, 어쩌면 쓸모가 있을지도 몰라!",
          DialogueId = 51004963,
          Duration = 4,
          GUID = "7FAF7C9A",
          SpeakNpcId = 100001
        },
        [51004964] = {
          ContentKR = "(목을 낫게 해 줄지도 모를 약의 처방전 획득)",
          DialogueId = 51004964,
          Duration = 3,
          GUID = "7FAF7C9B"
        },
        [51004965] = {
          ContentKR = "언젠가 목이 다 낫는다면, 어떤 노래를 부르고 싶으세요?",
          DialogueId = 51004965,
          GUID = "7FAF7C9C",
          NextDialogue = 51004966,
          SpeakNpcId = 100001
        },
        [51004966] = {
          ContentKR = "(루나가 깊은 생각에 빠진 듯 고개를 숙인다.)",
          DialogueId = 51004966,
          GUID = "7FAF7C9D",
          NextDialogue = 51004967,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004967] = {
          ContentKR = "'설령 목소리를 대가로 치러야 한데도, 제 진심을 노래하고 싶어요.'",
          DialogueId = 51004967,
          GUID = "7FAF7C9E",
          NextDialogue = 51004968,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004968] = {
          ContentKR = "(만약 이 처방전이 정말로 치료에 효과가 있다면, 이 음유시인은 오히려 더 큰 위험에 빠지게 되지 않을까...)",
          DialogueId = 51004968,
          GUID = "7FAF7C9F",
          NextOptions = {
            [1] = 51004969,
            [2] = 51004970
          }
        },
        [51004969] = {
          ContentKR = "루나에게 처방전을 건넨다.",
          DialogueId = 51004969,
          GUID = "7FAF7CA0",
          NextDialogue = 51004972
        },
        [51004970] = {
          ContentKR = "처방전의 존재를 숨긴다.",
          DialogueId = 51004970,
          GUID = "7FAF7CA1",
          NextDialogue = 51004979
        },
        [51004971] = {
          ContentKR = "분기 1",
          DialogueId = 51004971,
          GUID = "7FAF7CA2"
        },
        [51004972] = {
          ContentKR = "이 처방전은 제가 잘 아는 의사 선생님이 로터스에 중독된 사람을 치료할 때 쓰던 거예요. 어쩌면 목이 나을지도 모르니까, 한번 써 보세요.",
          DialogueId = 51004972,
          GUID = "7FAF7CA3",
          NextDialogue = 51004973,
          SpeakNpcId = 100001
        },
        [51004973] = {
          ContentKR = "루나는 믿을 수 없다는 듯 미세하게 떨리는 손으로 구겨진 종이를 받아 들곤, 눈시울이 붉어진 채 연신 고개를 숙이며 감사를 전한다.",
          DialogueId = 51004973,
          GUID = "7FAF7CA4",
          NextDialogue = 51004974
        },
        [51004974] = {
          ContentKR = "(목을 낫게 해 줄지도 모를 약의 처방전 소멸)",
          DialogueId = 51004974,
          GUID = "7FAF7CA5",
          NextDialogue = 51004975
        },
        [51004975] = {
          ContentKR = "(그녀에게 처방전을 준 게 잘한 일인지, 그리고 처방전이 효과가 있을지조차 확신이 서지 않는다.)",
          DialogueId = 51004975,
          GUID = "7FAF7CA6",
          NextDialogue = 51004976
        },
        [51004976] = {
          ContentKR = "(결국 모든 것은 음유시인 본인의 몫이라고, 나는 스스로를 납득시켰다.)",
          DialogueId = 51004976,
          GUID = "7FAF7CA7"
        },
        [51004977] = {
          ContentKR = "퀘스트 완료. 해독제 처방전 소멸. 보상 획득(루나 인물 파일 개방)",
          DialogueId = 51004977,
          GUID = "7FAF7CA8"
        },
        [51004978] = {
          ContentKR = "분기 2",
          DialogueId = 51004978,
          GUID = "7FAF7CA9"
        },
        [51004979] = {
          ContentKR = "저랑 아는 사이인 의사 선생님은 이제 아이스레이크 시티에 안 계시니까, 혹시나 해서 예전 집에 가 봤는데, 이미 깔끔하게 치워져 있더라고요.",
          DialogueId = 51004979,
          GUID = "7FAF7CAA",
          NextDialogue = 51004980,
          SpeakNpcId = 100001
        },
        [51004980] = {
          ContentKR = "괜히 기대하게 만들어서 미안해요.",
          DialogueId = 51004980,
          GUID = "7FAF7CAB",
          NextDialogue = 51004981,
          SpeakNpcId = 100001
        },
        [51004981] = {
          ContentKR = "(루나는 마치 '고마워요, 괜찮아요'라고 말하는 것처럼 미소를 지으며 내 어깨를 다독였다.)",
          DialogueId = 51004981,
          GUID = "7FAF7CAC",
          NextDialogue = 51004982
        },
        [51004982] = {
          ContentKR = "(루나는 내 마음이 착잡하단 사실도, 그리고 내가 만에 하나라도 그녀를 위험한 상황에 빠뜨리고 싶지 않아 한다는 것도 알지 못한다.)",
          DialogueId = 51004982,
          GUID = "7FAF7CAD",
          NextDialogue = 51004983
        },
        [51004983] = {
          ContentKR = "(난 앞으로도 펜을 멈추지 않을 그녀를 위해 힘닿는 데까지 위험을 줄여 주었다. 난, 그렇게 생각하기로 했다.)",
          DialogueId = 51004983,
          GUID = "7FAF7CAE"
        },
        [51005001] = {
          ContentKR = "누구시죠...?",
          DialogueId = 51005001,
          GUID = "7FAF87FA",
          NextDialogue = 51005002,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700013:Explain01_Start"
          }
        },
        [51005002] = {
          ContentKR = "(히프노스의 집이 익숙한 듯한 중년 여성이 가구 위에 쌓인 먼지를 닦고 있다. 하지만 이곳은 아무도 들어올 수 없는 곳이다.)",
          DialogueId = 51005002,
          GUID = "7FAF8824",
          NextDialogue = 51005003,
          TalkActionId = {
            [1] = "700013:Explain01_End"
          }
        },
        [51005003] = {
          ContentKR = "미안하구나. 다른 사람이 올 줄은 몰랐어.",
          DialogueId = 51005003,
          GUID = "7FAF884E",
          NextDialogue = 51005004,
          SpeakNpcId = 700013
        },
        [51005004] = {
          ContentKR = "나는 헨릭 씨가 고용한 집사란다. 주기적으로 방문해서 청소와 보수 작업을 하고 있지. 오늘은 원래 약속했던 날이고.",
          DialogueId = 51005004,
          GUID = "7FAF8878",
          NextDialogue = 51005005,
          SpeakNpcId = 700013
        },
        [51005005] = {
          ContentKR = "넌 누구니?",
          DialogueId = 51005005,
          GUID = "7FAF88A2",
          NextDialogue = 51005006,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Explain02_Start"
          }
        },
        [51005006] = {
          ContentKR = "저는 이 옆에 머무르고 있어요. 문이 잘 잠겨 있는지 보러 왔어요.",
          DialogueId = 51005006,
          GUID = "7FAF88CC",
          NextDialogue = 51005007,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700013:Explain02_End"
          }
        },
        [51005007] = {
          ContentKR = "아시는지 모르겠지만, 헨릭 씨는 돌아가셨어요... 그러니 이제 더 안 오셔도 돼요.",
          DialogueId = 51005007,
          GUID = "7FAF88F6",
          NextDialogue = 51005008,
          SpeakNpcId = 100001
        },
        [51005008] = {
          ContentKR = "나도 알고 있단다.",
          DialogueId = 51005008,
          GUID = "7FAF8920",
          NextDialogue = 51005009,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Agree"
          }
        },
        [51005009] = {
          ContentKR = "하지만 헨릭 씨가 미리 급여를 주셨어. 난 이 계약이 끝날 때까지 책임을 다할 생각이지.",
          DialogueId = 51005009,
          GUID = "7FAF894A",
          NextDialogue = 51005010,
          SpeakNpcId = 700013
        }
      }
    end
  },
  {
    MinKey = 51005010,
