    Loader = function()
      return {
        [51005010] = {
          ContentKR = "지금이... 오후 네 시구나. 난 계약대로 세 시간 동안 일할 거야.",
          DialogueId = 51005010,
          GUID = "7FAF8974",
          NextDialogue = 51005011,
          SpeakNpcId = 700013
