        },
        [51005032] = {
          ContentKR = "열쇠를 못 찾고 있었는데, 너한테 있었구나. 잘 보관해 줘서 정말 고맙다.",
          DialogueId = 51005032,
          GUID = "7FAF8D10",
          NextDialogue = 51005033,
          SpeakNpcId = 700013
        },
        [51005033] = {
          ContentKR = "괜찮다면 네가 보는 앞에서 헨릭 씨와의 약속을 이행하고 싶은데...",
          DialogueId = 51005033,
          GUID = "7FAF8D3A",
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Explain02_Start"
          }
        },
        [51005034] = {
          Camera = "299.257812,85.246521,174.804688,-0.0,-9.999997,-170.990723,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(상자가 열리자, 레나는 그 안에 있던 헨릭 씨의 유언장을 꺼내더니, 내가 지켜보는 가운데, 진중한 태도로 내용을 낭독하기 시작했다.)",
          DialogueId = 51005034,
          GUID = "7FAF8D64",
          NextDialogue = 51005035
        },
        [51005035] = {
          Camera = "299.257812,85.246521,174.804688,-0.0,-9.999997,-170.990723,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(이런 비극을 예상하기라도 한 듯 헨릭의 유언장은 담담했지만, 딸의 죽음에는 여전히 깊은 슬픔이 느껴진다. 그리고...)",
          DialogueId = 51005035,
          GUID = "7FAF8D8E",
          NextDialogue = 51005036
        },
        [51005036] = {
          Camera = "-3490.197266,-340.706116,876.251953,0.000004,0.0,0.812196,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "\"제가 죽은 후, 제 명의의 모든 부동산은 레나 벨 씨에게 증여하여...\"",
          DialogueId = 51005036,
          FinalCamera = "-2771.669922,-330.52002,876.251953,0.000004,0.0,0.812196,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8DB8",
          NextDialogue = 51005037,
          SpeakNpcId = 700013,
          ToFinalCameraBlendTime = 7
        },
        [51005037] = {
          Camera = "-956.953125,124.710449,851.333984,0.000029,-16.600037,26.61047,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "\"히프노스의 집과 카론 환자를 위해 고생한 것에 대해 고마움을 표하겠습니다.\"",
          DialogueId = 51005037,
          FinalCamera = "-938.859375,88.569275,851.333984,0.000038,-16.600002,26.610426,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8DE2",
          NextDialogue = 51005038,
          SpeakNpcId = 700013,
          ToFinalCameraBlendTime = 7
        },
        [51005038] = {
          Camera = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "\"레나 씨께 깊은 존경을 표하며, 감사 인사를 전합니다.\"",
          DialogueId = 51005038,
          GUID = "7FAF8E0C",
          NextDialogue = 51005039,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Disagree"
          }
        },
        [51005039] = {
          Camera = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...",
          DialogueId = 51005039,
          GUID = "7FAF8E36",
          NextDialogue = 510050391,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          }
        },
        [51005040] = {
          ContentKR = "나는 홀로 헨릭의 사무실을 나왔다.\n흐느끼는 레나 아주머니는 혼자만의 시간이 필요할 테니, 이 시간만큼은 방해하고 싶지 않았다.",
          DialogueId = 51005040,
          Duration = 4,
          GUID = "7FAF8E60",
          NextDialogue = 51005041
        },
        [51005041] = {
          ContentKR = "이제, 내게 새로운 집주인이 생겼다.",
          DialogueId = 51005041,
          Duration = 2,
          GUID = "7FAF8E8A"
        },
        [51005042] = {
          Camera = "460.455078,-127.329834,335.509766,0.000047,-28.799341,157.208237,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(히프노스의 집 구조를 원히 알고 있는 레나 아주머니 덕분에 수월하게 상자를 발견했지만, 상자 옆에 웬 나무 상자 하나가 놓여 있었다.)",
          DialogueId = 51005042,
          FinalCamera = "460.455078,-148.0,335.509766,0.000054,-28.799347,157.208237,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8EB4",
          NextDialogue = 51005043,
          ToFinalCameraBlendTime = 7
        },
        [51005043] = {
          Camera = "-372.582031,8.945923,112.0,0.0,0.0,0.208069,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(우선 그 수상한 나무 상자를 열어 보았다. 수려한 필체의 편지 하나가 들어 있었고, 나는 그 편지를 꺼내 소리 내어 또박또박 읽기 시작했다.)",
          DialogueId = 51005043,
          FinalCamera = "-350.582031,9.078125,112.0,0.0,0.0,0.408069,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8EDE",
          NextDialogue = 51005044,
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 7,
          TurnTo = {
            [1] = "700098:n(100001)"
          }
        },
        [51005044] = {
          ContentKR = "이 편지를 읽고 계실 때쯤이면, 저희는 '히프노스의 집'을 떠난 후일 거예요.\n그날 밤, 프시케에게 일어났던 일로 방위대가 움직이기 시작해서, 더는 아이스레이크 시티에 머물 수 없게 됐거든요.\n그래서 방위대의 조사가 여기까지 미치기 전에 모두를 데리고 떠났어요.\n저희 때문에 슬퍼하지 마세요. 저희가 갑작스러운 침식으로 무고한 사람들을 해칠까 봐 걱정하지 않으셔도 되고요.\n저희는 황야로 가서, 아무도 알지 못하는 먼 곳을 향해 떠돌 거예요.\n이 방랑의 끝이 죽음일지, 아니면 처음 만나는 기적일지는 모르겠지만...\n저희는 마지막 순간까지 희망의 끈을 놓지 않을 거예요.\n프시케가 저희한테 알려 줬던 것처럼요.\n그리고, 그동안 저희를 위해 베풀어 주신 모든 것에 감사드려요.\n—엘리사 테일러",
          DialogueId = 51005044,
          DialoguePanelType = "{type:showtext;topic:Reading_Title_200208;content:Reading_Content_200208}",
          GUID = "7FAF8F08",
          NextDialogue = 51005045
        },
        [51005045] = {
          Camera = "299.257812,85.246521,174.804688,-0.0,-9.999997,-170.990723,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그랬구나... 아이들은 무사히... 여길 떠난 거야.",
          DialogueId = 51005045,
          GUID = "7FAF8F32",
          NextDialogue = 51005046,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          TurnTo = {
            [1] = "700098:p(140)"
          }
        },
        [51005046] = {
          Camera = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(긴 침묵 후, 레나는 힘겹게 열쇠를 구멍 속으로 밀어 넣으려 했지만, 떨리는 손 때문에 열쇠를 놓치기 일쑤였다.)",
          DialogueId = 51005046,
          GUID = "7FAF8F5C",
          NextDialogue = 51005047
        },
        [51005047] = {
          ContentKR = "...같이 해 봐요.",
          DialogueId = 51005047,
          GUID = "7FAF8F86",
          IsBlack = 1,
          NextDialogue = 51005048,
          SpeakNpcId = 100001
        },
        [51005048] = {
          ContentKR = "미안, 고마워.",
          DialogueId = 51005048,
          GUID = "7FAF8FB0",
          IsBlack = 1,
          SpeakNpcId = 700013
        },
        [51005101] = {
          ContentKR = "{nickname}?",
          DialogueId = 51005101,
          GUID = "7FAF9862",
          NextDialogue = 51005102,
          SpeakNpcId = 700115
        },
        [51005102] = {
          ContentKR = "지난 일은 고마웠어요! 생활비를 받은 빈민가 주민들도 감사 인사를 전해달라고 했어요!",
          DialogueId = 51005102,
          GUID = "7FAF988C",
          NextOptions = {
            [1] = 51005103
          },
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005103] = {
          ContentKR = "별거 아니야.",
          DialogueId = 51005103,
          GUID = "7FAF98B6",
          NextDialogue = 51005104
        },
        [51005104] = {
          ContentKR = "정말 겸손하시네요! 당신처럼 친절한데 능력도 좋고 예의까지 다 갖춘 사람은 정말 오랜만이에요!",
          DialogueId = 51005104,
          GUID = "7FAF98E0",
          NextDialogue = 51005105,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_Start"
          }
        },
        [51005105] = {
          ContentKR = "아이스레이크 시티에 있으니까 어때요?",
          DialogueId = 51005105,
          GUID = "7FAF990A",
          NextOptions = {
            [1] = 510051051,
            [2] = 510051052,
            [3] = 510051053
          },
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_End"
          },
          bForbidSkipOptions = true
        },
        [51005106] = {
          ContentKR = "목표까지 달리는 게 인생이라고 하지만, 그 여정의 풍경을 하나도 안 즐기기엔 너무 아쉽잖아요!",
          DialogueId = 51005106,
          GUID = "7FAF9934",
          NextDialogue = 51005109,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005107] = {
          ContentKR = "맞아요!!! 저도 아이스레이크 시티에 처음 왔을 때 그랬어요! 이곳의 규칙도 잘 모르겠고 사람들도 특이했고요!",
          DialogueId = 51005107,
          GUID = "7FAF995E",
          NextDialogue = 51005109,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005108] = {
          ContentKR = "그쪽 고향도 치안이 별로였군요... 설마 당신도 도망친 건 아니죠?",
          DialogueId = 51005108,
          GUID = "7FAF9988",
          NextDialogue = 51005109,
          SpeakNpcId = 700115
        },
        [51005109] = {
          ContentKR = "아니에요, 이 얘기는 여기까지 하죠.",
          DialogueId = 51005109,
          GUID = "7FAF99B2",
          NextDialogue = 51005110,
          SpeakNpcId = 700115
        },
        [51005110] = {
          ContentKR = "대신 방금 입고된 물건들 좀 봐요! 전부 희귀한 것들이랍니다. 전에 도둑을 잡아 주셨으니 특별히 20% 할인해 줄게요~",
          DialogueId = 51005110,
          GUID = "7FAF99DC",
          NextDialogue = 51005111,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Explain02_Start"
          }
        },
        [51005111] = {
          ContentKR = "('방금 입고된 물건'을 관찰하기 시작한다. 작은 목제 진열대에 쌓여 있는 물건은 대부분 사용감이 있었지만, 깨끗하게 닦여 있었다.)",
          DialogueId = 51005111,
          GUID = "7FAF9A06",
          NextOptions = {
            [1] = 510051111,
            [2] = 510051112,
            [3] = 510051113
          },
          TalkActionId = {
            [1] = "700115:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51005112] = {
          ContentKR = "재미있잖아요. 돈만 따지면 하나도 재미없다고요!",
          DialogueId = 51005112,
          GUID = "7FAF9A30",
          NextDialogue = 51005115,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005113] = {
          ContentKR = "당연하죠! 제가 얼마나 착한데요! 전부 주인을 잃어버린 보물이에요. 이런 걸 낭비하는 거야 말로 나쁜 일이니까 새로운 집을 찾아주려는 거라고요!",
          DialogueId = 51005113,
          GUID = "7FAF9A5A",
          NextDialogue = 51005115,
          SpeakNpcId = 700115
        },
        [51005114] = {
          ContentKR = "헤헤, 영업 비밀이에요!",
          DialogueId = 51005114,
          GUID = "7FAF9A84",
          NextDialogue = 51005115,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005115] = {
          ContentKR = "(호의를 거절하기 어렵다. 마르제의 '가판대'에서 필요한 물건을 찾아본다.)",
          DialogueId = 51005115,
          GUID = "7FAF9AAE",
          NextOptions = {
            [1] = 510051151,
            [2] = 510051152,
            [3] = 510051153
          },
          RestartTag = 51005115,
          bForbidSkipOptions = true
        },
        [51005116] = {
          ContentKR = "마음에 드는 게 없으면 됐어요! 새로 입고되면 그때 다시 와요.",
          DialogueId = 51005116,
          GUID = "7FAF9AD8",
          SpeakNpcId = 700115
        },
        [51005117] = {
          ContentKR = "역시 보는 눈이 있으시네요. 한 번에 이렇게 좋은 걸 알아보다니! 탐정 같은 예리함을 가진 것 같아요.",
          DialogueId = 51005117,
          GUID = "7FAF9B02",
          NextOptions = {
            [1] = 51005118
          },
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005118] = {
          ContentKR = "탐정? 그게 무슨 소리야...",
          DialogueId = 51005118,
          GUID = "7FAF9B2C",
          NextDialogue = 51005119
        },
        [51005119] = {
          ContentKR = "당신이 고른 것들은 가치가 없기도, 또 있기도 해요. 가치가 없다는 건 말 그대로 아무도 쳐다보지 않을 정도로 몇 푼 안 된다는 말이죠.",
          DialogueId = 51005119,
          GUID = "7FAF9B56",
          NextDialogue = 51005120,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Think_Start"
          }
        },
        [51005120] = {
          ContentKR = "가치가 있다는 건... 다들 '사연'을 갖고 있는 물건 같거든요! 그래서 고른 거 아닌가요?",
          DialogueId = 51005120,
          GUID = "7FAF9B80",
          NextDialogue = 51005121,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Think_End"
          }
        },
        [51005121] = {
          ContentKR = "뛰어난 인내심과 관찰력을 가졌다면, 이 보물들에 숨겨진 사연과 비밀을 밝힐 수 있어요!",
          DialogueId = 51005121,
          GUID = "7FAF9BAA",
          NextDialogue = 51005122,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_Start"
          }
        },
        [51005122] = {
          ContentKR = "쓰레기통을 무시하지 마요. 여러 사건과 소문의 진실은 그 안에 숨겨져 있거든요! 저도 쓰레기통 덕분에 이 도시를 알아갈 수 있었어요.",
          DialogueId = 51005122,
          GUID = "7FAF9BD4",
          NextDialogue = 51005123,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_End"
          }
        },
        [51005123] = {
          ContentKR = "자, 이제 궁금하죠? 이 도시에 대해 더 알고 싶죠? 그럼 여기서 계산해 드릴게요!",
          DialogueId = 51005123,
          GUID = "7FAF9BFE",
          NextDialogue = 51005124,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Confident_Start"
          }
        },
        [51005124] = {
          ContentKR = "(왠지 끌려다니는 느낌이다...)",
          DialogueId = 51005124,
          GUID = "7FAF9C28",
          NextDialogue = 51005125,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700115:Confident_End"
          }
        },
        [51005125] = {
          ContentKR = "잠깐, 잠깐, 그냥 영업 멘트니까 지금의 그 '장사꾼' 같다는 표정은 사양이에요! 그리고 당신도 이 물건들이 뭔가 특별하다는 걸 알아차렸으면서, 그냥 두려고요?",
          DialogueId = 51005125,
          GUID = "7FAF9C52",
          NextOptions = {
            [1] = 510051251,
            [2] = 510051252,
            [3] = 510051253
          },
          SpeakNpcId = 700115,
          bForbidSkipOptions = true
        },
        [51005126] = {
          ContentKR = "너무 정직하시니까 제가 좀 미안해지네요...",
          DialogueId = 51005126,
          GUID = "7FAF9C7C",
          NextDialogue = 51005129,
          SpeakNpcId = 700115
        },
        [51005127] = {
          ContentKR = "계산적인 것도 월석 사냥꾼의 공통점이군요...",
          DialogueId = 51005127,
          GUID = "7FAF9CA6",
          NextDialogue = 51005129,
          SpeakNpcId = 700115
        },
        [51005128] = {
          ContentKR = "자, 잠깐만요! 다시 생각해 봐요!",
          DialogueId = 51005128,
          GUID = "7FAF9CD0",
          NextDialogue = 51005129,
          SpeakNpcId = 700115
        },
        [51005129] = {
          ContentKR = "도둑을 잡아 주셨으니, 감사의 뜻으로 이 세 개를 다 드릴게요.",
          DialogueId = 51005129,
          GUID = "7FAF9CFA",
          NextDialogue = 51005130,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_Start"
          }
        },
        [51005130] = {
          ContentKR = "(마르제가 다짜고짜 물건들을 품에 안겨준다.)",
          DialogueId = 51005130,
          GUID = "7FAF9D24",
          NextDialogue = 51005131,
          TalkActionId = {
            [1] = "700115:Talk02_End"
          }
        },
        [51005131] = {
          ContentKR = "행운을 빌어요, 탐정님!",
          DialogueId = 51005131,
          GUID = "7FAF9D4E",
          NextDialogue = 51005132,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Explain02_Start"
          }
        },
        [51005132] = {
          ContentKR = "이것들의 사연을 알아낸 후에, 아이스레이크 시티에 대한 느낌을 다시 말해줘요!",
          DialogueId = 51005132,
          GUID = "7FAF9D78",
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Explain02_End"
          }
        },
        [51005201] = {
          Camera = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "어서 와요!",
          DialogueId = 51005201,
          FacialId = {
            [1] = "700127:Smile02"
          },
          GUID = "7FAFA8CA",
          NextDialogue = 51005202,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Explain02_Start"
          }
        },
        [51005202] = {
          Camera = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "어떤 사연을 알아냈는지 어서 알려줘요!",
          DialogueId = 51005202,
          GUID = "7FAFA8F4",
          NextOptions = {
            [1] = 510052021,
            [2] = 510052022,
            [3] = 510052023
          },
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Explain02_End"
          }
        },
        [51005203] = {
          Camera = "0.445557,77.976562,129.532715,0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "앞으로 글씨를 쓸 수 없는 건, 루나에게 가혹하겠네요... 다른 사람에게 들키지 않도록 제가 루나의 종이 쓰레기를 잘 살펴야겠어요!",
          DialogueId = 51005203,
          GUID = "7FAFA91E",
          NextDialogue = 51005206,
          Scripts = "SEQ{PlayAnimation{ActorId{700127},AnimationId{\"Sigh_Start\"},Duration{2}},PlayAnimation{ActorId{700127},AnimationId{\"Sigh_End\"},Duration{1}}}",
          SpeakNpcId = 700127
        },
        [51005204] = {
          Camera = "0.445557,77.976562,129.532715,0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "바깥 세상은 생각만큼 아름답지 않을 수도 있는데... 그래도 그런 희망이 필요한 거겠죠.",
          DialogueId = 51005204,
          FacialId = {
            [1] = "700127:Iyada01"
          },
          GUID = "7FAFA948",
          NextDialogue = 51005206,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Agree"
          }
        },
        [51005205] = {
          Camera = "0.445557,77.976562,129.532715,0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "두 분 모두 잘됐네요! 착한 사람들에게 주어지는 운명의 보상이겠죠!",
          DialogueId = 51005205,
          FacialId = {
            [1] = "700127:Satisfy01"
          },
          GUID = "7FAFA972",
          NextDialogue = 51005206,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Agree"
          }
        },
        [51005206] = {
          Camera = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "멋져요! 당신은 정말 예리한 탐정이에요!",
          DialogueId = 51005206,
          FacialId = {
            [1] = "700127:Ahaha02"
          },
          GUID = "7FAFA99C",
          NextDialogue = 51005207,
          SpeakNpcId = 700127
        },
        [51005207] = {
          Camera = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아이스레이크 시티에서는 보잘것없는 곳에서도 새로운 기쁨과... 놀라움을 경험할 수 있어요.",
          DialogueId = 51005207,
          GUID = "7FAFA9C6",
          NextDialogue = 51005208,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Explain02_Start"
          }
        },
        [51005208] = {
          Camera = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이제 어때요? 한 번 둘러본 후에 새로운 소감이 생겼나요?",
          DialogueId = 51005208,
          FacialId = {
            [1] = "700127:Confident02"
          },
          GUID = "7FAFA9F0",
          NextOptions = {
            [1] = 510052081,
            [2] = 510052082,
            [3] = 510052083,
            [4] = 510052084,
            [5] = 510052085
          },
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51005209] = {
          Camera = "0.445557,77.976562,129.532715,0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "와... 정말 당신다운 대답이네요! 제가 예상했던 답을 다 빗나갔어요.",
          DialogueId = 51005209,
          FacialId = {
            [1] = "700127:Happy01"
          },
          GUID = "7FAFAA1A",
          NextDialogue = 51005210,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Think_Start"
          }
        },
        [51005210] = {
          Camera = "52.368652,-229.308594,141.289062,0.000091,-3.599974,111.20826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "당신이 여기에 머물 것 같은 예감이 들어요. 금방 떠날 거라면 이렇게 복잡한 생각을 왜 하겠어요!",
          DialogueId = 51005210,
          GUID = "7FAFAA44",
          NextDialogue = 51005211,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Think_End",
            [2] = "100001:Agree"
          }
        },
        [51005211] = {
          Camera = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그러니 앞으로 우리가 함께할 시간은 많을 거예요, 그렇죠?",
          DialogueId = 51005211,
          GUID = "7FAFAA6E",
          NextDialogue = 51005212,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Confident_Start"
          }
        },
        [51005212] = {
          Camera = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이미 누군가가 했을 것 같지만, 제가 한 번 더 해야겠어요.",
          DialogueId = 51005212,
          GUID = "7FAFAA98",
          NextDialogue = 51005213,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Confident_End"
          }
        },
        [51005213] = {
          Camera = "12.572754,75.52832,130.532715,-0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "자, 그렇다면... 아이스레이크 시티에 오신 걸 환영합니다!",
          DialogueId = 51005213,
          FacialId = {
            [1] = "700127:Happy02"
          },
          GUID = "7FAFAAC2",
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Talk02_Start"
          }
        },
        [51005301] = {
          ContentKR = "잘 처리하면 좋은 음식이 될 거야!",
          DialogueId = 51005301,
          GUID = "7FAFB932",
          NextDialogue = 51005302,
          SpeakNpcId = 700116
        },
        [51005302] = {
          ContentKR = "...비린내는 사라졌지만, 해물 본연의 맛이 나지 않아...",
          DialogueId = 51005302,
          GUID = "7FAFB95C",
          NextDialogue = 51005303,
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Think_Start"
          }
        },
        [51005303] = {
          ContentKR = "(남자는 빠르게 말하며 충혈된 눈으로 수첩을 뚫어지게 보고 있다. 옆에는 이름 모를 해산물이 널려 있다. 파가 달라붙은 손으로 빠르게 무언가 써 내려간다.)",
          DialogueId = 51005303,
          GUID = "7FAFB986",
          NextOptions = {
            [1] = 510053031,
            [2] = 510053032
          },
          TalkActionId = {
            [1] = "700116:Think_End"
          },
          bForbidSkipOptions = true
        },
        [51005304] = {
          ContentKR = "(고리가 살짝 녹슨 것을 보니, 최근엔 이 낡은 수첩을 깨끗이 관리한 것 같지는 않다.)",
          DialogueId = 51005304,
          GUID = "7FAFB9B0",
          NextDialogue = 51005305
        },
        [51005305] = {
          ContentKR = "(가까이 가서 보니, 복잡한 도형과 선 사이로 향신료와 조리법이 써 있다. 레시피인 것 같다.)",
          DialogueId = 51005305,
          GUID = "7FAFB9DA",
          NextDialogue = 51005307
        },
        [51005306] = {
          ContentKR = "(지금은 자리를 뜨는 게 최선이다. 하지만 몸을 돌리는 순간 바닥에 흐르는 액체를 밟아 소리가 난다.)",
          DialogueId = 51005306,
          GUID = "7FAFBA04",
          NextDialogue = 51005307
        },
        [51005307] = {
          ContentKR = "(남자가 나를 발견했다.)",
          DialogueId = 51005307,
          GUID = "7FAFBA2E",
          NextDialogue = 51005308
        },
        [51005308] = {
          ContentKR = "...누구시죠?",
          DialogueId = 51005308,
          GUID = "7FAFBA58",
          NextDialogue = 51005309,
          SpeakNpcId = 700116
        },
        [51005309] = {
          ContentKR = "지나가던 월석 사냥꾼입니다.",
          DialogueId = 51005309,
          GUID = "7FAFBA82",
          NextDialogue = 51005310,
          SpeakNpcId = 100001
        },
        [51005310] = {
          ContentKR = "월석 사냥꾼이라면, 저와 더 맛있는 요리를 만드는 의뢰는 어떤가요?",
          DialogueId = 51005310,
          GUID = "7FAFBAAC",
          NextOptions = {
            [1] = 51000001,
            [2] = 51000002
          },
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Explain02_Start"
          },
          bForbidSkipOptions = true
        },
        [51005311] = {
          ContentKR = "정말 고마워요. 첫 번째 요리는 활어와 새우를 절이는 어부들의 전통 방식을 응용한 거예요. 번거로우시겠지만, 절임에 쓸 재료들을 낚아 와 주세요. 미끼는 여기 있어요.",
          DialogueId = 51005311,
          GUID = "7FAFBAD6",
          NextOptions = {
            [1] = 510053111,
            [2] = 510053112
          },
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51005312] = {
          ContentKR = "네! 저는 그사이에 소독도 하고 요리 준비를 해 놓을게요. 미끼가 바닥나면, 다시 절 찾아오시면 돼요.",
          DialogueId = 51005312,
          GUID = "7FAFBB00",
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Agree"
          }
        },
        [51005313] = {
          ContentKR = "여기 있는 천연 염전에서 절임에 필요한 재료를 얻을 수 있을 것 같아. 조금 모아서 가져가자.",
          DialogueId = 51005313,
          GUID = "7FAFBB2A",
          SpeakNpcId = 100001
        },
        [51005314] = {
          ContentKR = "물고기를 낚았다. 이제 마커스에게 돌아가자.",
          DialogueId = 51005314,
          GUID = "7FAFBB54",
          SpeakNpcId = 100001
        },
        [51005315] = {
          ContentKR = "물고기를 낚았다. 이제 마커스에게 돌아가자.",
          DialogueId = 51005315,
          GUID = "7FAFBB7E",
          SpeakNpcId = 100001
        },
        [51005401] = {
          ContentKR = "파는 작게 썰고... 해산물은 씻어서 소금과 식초를 넣어야 해. 아이스레이크 시티 사람들 입맛을 생각하면 설탕을 좀 더 넣어야겠어...",
          DialogueId = 51005401,
          GUID = "7FAFC99A",
          NextDialogue = 51005402,
          SpeakNpcId = 700116
        },
        [51005402] = {
          ContentKR = "(재료를 받아 든 마커스는 조리법을 중얼거리며 길모퉁이로 사라진다.)",
          DialogueId = 51005402,
          GUID = "7FAFC9C4"
        },
        [51005403] = {
          ContentKR = "(얼마 후 갑자기 어디선가 마커스가 나타난다. 눈 위로 넘어진 뒤에야 본인의 추태를 깨달은 그는 민망한 듯 웃으며 일어나 옷을 턴다.)",
          DialogueId = 51005403,
          GUID = "7FAFC9EE",
          NextDialogue = 51005404
        },
        [51005404] = {
          ContentKR = "...죄송해요.",
          DialogueId = 51005404,
          GUID = "7FAFCA18",
          NextDialogue = 51005405,
          SpeakNpcId = 700116
        },
        [51005405] = {
          ContentKR = "맛 좀 봐봐요. 아이스레이크 시티 특유의 맛이 느껴지나요?",
          DialogueId = 51005405,
          GUID = "7FAFCA42",
          NextDialogue = 51005406,
          SpeakNpcId = 700116
        },
        [51005406] = {
          ContentKR = "(마커스가 품에서 밀봉된 해산물을 꺼낸다. 해산물이 담긴 어두운색의 소스는 은은한 빛이 반짝이고, 그 위를 덮은 랩을 뚫고 진한 향이 새어 나온다.)",
          DialogueId = 51005406,
          GUID = "7FAFCA6C",
          NextOptions = {
            [1] = 510054061,
            [2] = 510054062,
            [3] = 510054063
          },
          TalkActionId = {
            [1] = "700116:Give"
          }
        },
        [51005407] = {
          ContentKR = "요리에 대한 편견을 깨봐요. 이런 특별한 음식에 도전하지 않으면 인생의 즐거움은 줄어들게 되는 법이죠.",
          DialogueId = 51005407,
          GUID = "7FAFCA96",
          NextDialogue = 51005410,
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Disagree"
          }
        },
        [51005408] = {
          ContentKR = "하하, 됐어요, 됐어. 그러다 곧 울겠어요.",
          DialogueId = 51005408,
          GUID = "7FAFCAC0",
          NextDialogue = 51005410,
          SpeakNpcId = 700116
        },
        [51005409] = {
          ContentKR = "흥. 모두가 당신처럼 다양한 식재료에 편견이 있는 게 아니라 다행이군요.",
          DialogueId = 51005409,
          GUID = "7FAFCAEA",
          NextDialogue = 51005410,
          SpeakNpcId = 700116
        },
        [51005410] = {
          ContentKR = "음... 어쨌든 더 개선이 필요하겠네요.",
          DialogueId = 51005410,
          GUID = "7FAFCB14",
          NextDialogue = 51005411,
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Agree"
          }
        },
        [51005411] = {
          ContentKR = "두 번째 음식도 부탁해요, 요리 파트너님!",
          DialogueId = 51005411,
          GUID = "7FAFCB3E",
          SpeakNpcId = 700116
        },
        [51005501] = {
          ContentKR = "삶는 건 속을 따뜻하게 해주니 에피타이저로 괜찮지만, 아직...",
          DialogueId = 51005501,
          GUID = "7FAFDA02",
          NextDialogue = 51005502,
          SpeakNpcId = 700117,
          TalkActionId = {
            [1] = "700117:Think_Start"
          }
        },
        [51005502] = {
          ContentKR = "(마커스의 하얀 얼굴은 아이스레이크의 찬바람에도 빨갛게 얼지 않았다. 얼핏 보면 누군가 두고 간 얼음 조각상처럼 보일 정도다.)",
          DialogueId = 51005502,
          GUID = "7FAFDA2C",
          NextDialogue = 51005503
        },
        [51005503] = {
          ContentKR = "(그렇지만 그는 열악한 환경과 아픈 몸을 신경 쓰지 않는다.)",
          DialogueId = 51005503,
          GUID = "7FAFDA56",
          NextDialogue = 51005504
        },
        [51005504] = {
          ContentKR = "(그는 재료와 조미료, 조리법을 하나씩 말하며, 최고의 요리를 만들기 위한 방법을 고심 중이다.)",
          DialogueId = 51005504,
          GUID = "7FAFDA80",
          NextDialogue = 51005505,
          TalkActionId = {
            [1] = "700117:Think_End"
          }
        },
        [51005505] = {
          ContentKR = "파트너님, 오셨군요!",
          DialogueId = 51005505,
          GUID = "7FAFDAAA",
          NextDialogue = 51005506,
          SpeakNpcId = 700117,
          TurnTo = {
            [1] = "700117:n(0)"
          }
        },
        [51005506] = {
          ContentKR = "본론부터 말할게요. 마블 피쉬가 몇 마리 더 필요해요. 구하기 힘든 생선이지만, 파트너라면 문제없을 거라고 믿어요. 꼭 좀 부탁해요!",
          DialogueId = 51005506,
          GUID = "7FAFDAD4",
          NextDialogue = 51005507,
          SpeakNpcId = 700117
        },
        [51005507] = {
          ContentKR = "(구하기는 더 어렵겠지만, 나로선 오히려 다행이었다. 적어도 이번에는 익히지 않은 음식을 맛볼 일은 없겠지.)",
          DialogueId = 51005507,
          GUID = "7FAFDAFE"
        },
        [51005508] = {
          ContentKR = "한참을 낚시한 끝에 마커스가 필요하다는 마블 피쉬를 얻었다.",
          DialogueId = 51005508,
          Duration = 3,
          GUID = "7FAFDB28"
        },
        [51005601] = {
          ContentKR = "(마커스는 가만히 서서 아이스베리의 껍질을 까고 있다. 아무 말도 하지 않으니 더 얼음 조각상처럼 보인다. 간혹 처음 겪는 고통을 참는 듯 미간을 찌푸린다.)",
          DialogueId = 51005601,
          GUID = "7FAFEA6A",
          NextOptions = {
            [1] = 510056011,
            [2] = 510056012
          },
          bForbidSkipOptions = true
        },
        [51005602] = {
          ContentKR = "(껍질에 핏자국과 흙이 묻어 있다. 힘이 너무 강한 탓인지 몇 개는 모양이 망가졌다. 마커스의 손바닥에 난 상처를 보니, 이건 가까운 절벽에서 마커스가 직접 딴 아이스베리인 것 같다.)",
          DialogueId = 51005602,
          GUID = "7FAFEA94",
          NextOptions = {
            [1] = 51005604
          }
        },
        [51005603] = {
          ContentKR = "(마커스의 옷 한 부분에 방금 다친 것처럼 피가 배어 있었다. 피는 멎었지만, 꽤 큰 부상이다.)",
          DialogueId = 51005603,
          GUID = "7FAFEABE",
          NextOptions = {
            [1] = 51005604
          }
        },
        [51005604] = {
          ContentKR = "피가...",
          DialogueId = 51005604,
          GUID = "7FAFEAE8",
          NextDialogue = 51005605,
          SpeakNpcId = 100001
        },
        [51005605] = {
          ContentKR = "별건 아니고, 아이스베리를 따다가 살짝 넘어졌을 뿐이에요. 표정을 보니까, 마블 피쉬를 구한 모양이군요. 역시 해낼 줄 알았어요. 정말 고마워요.",
          DialogueId = 51005605,
          GUID = "7FAFEB12",
          NextDialogue = 51005606,
          SpeakNpcId = 700117,
          TurnTo = {
            [1] = "700117:n(0)"
          }
        },
        [51005606] = {
          ContentKR = "(부상에 대한 말을 아낀 마커스는 냄비에 아이스베리를 넣고 저은 뒤 조금 맛본다.)",
          DialogueId = 51005606,
          GUID = "7FAFEB3C",
          NextDialogue = 51005607
        },
        [51005607] = {
          ContentKR = "신선한 아이스베리가 들어가니 향이 더 진해지는군요.",
          DialogueId = 51005607,
          GUID = "7FAFEB66",
          NextDialogue = 51005608,
          SpeakNpcId = 700117,
          TalkActionId = {
            [1] = "700117:Agree"
          }
        },
        [51005608] = {
          ContentKR = "마블 피쉬 조리법도 바꿔야겠어요...",
          DialogueId = 51005608,
          GUID = "7FAFEB90",
          NextDialogue = 51005609,
          SpeakNpcId = 700117
        },
        [51005609] = {
          ContentKR = "(마커스는 다친 몸으로 생선의 기름을 걷고, 데치고, 찌는 길고 복잡한 과정을 마친다.)",
          DialogueId = 51005609,
          GUID = "7FAFEBBA",
          NextDialogue = 51005610
        },
        [51005610] = {
          ContentKR = "(음식의 향이 나기 시작하자, 불 옆에 있던 마커스가 일어났다. 그리고 요리를 차리고 평가를 기다리고 있다.)",
          DialogueId = 51005610,
          GUID = "7FAFEBE4",
          NextDialogue = 51005611
        },
        [51005611] = {
          ContentKR = "흠흠... 다 됐어요. 먹어보고, 정말 맛있고 특별한지 알려줘요.",
          DialogueId = 51005611,
          GUID = "7FAFEC0E",
          NextOptions = {
            [1] = 51005612
          },
          SpeakNpcId = 700117,
          TalkActionId = {
            [1] = "700117:Give"
          }
        },
        [51005612] = {
          ContentKR = "맛있어요. 아주 따뜻해요.",
          DialogueId = 51005612,
          GUID = "7FAFEC38",
          NextDialogue = 51005613
        },
        [51005613] = {
          ContentKR = "다행이에요. 내성으로 돌아가서 사장님께 이 소식을 전해야겠어요!",
          DialogueId = 51005613,
          GUID = "7FAFEC62",
          NextDialogue = 51005614,
          SpeakNpcId = 700117
        },
        [51005614] = {
          ContentKR = "고마워요! 이건 우리가 같이 만든 음식이에요. 분명 모두 좋아할 거예요! 사장님도 칭찬을 아끼지 않을 거고요!",
          DialogueId = 51005614,
          GUID = "7FAFEC8C",
          SpeakNpcId = 700117
        },
        [51005701] = {
          ContentKR = "...",
          DialogueId = 51005701,
          GUID = "7FAFFAD2",
          NextDialogue = 51005702
        },
        [51005702] = {
          ContentKR = "(세 번째 만난 마커스는 다리에 도시락을 올려놓은 채 가만히 앉아 있다. 오랫동안 잠을 못 잔 듯 초췌하고 지쳐 보인다.)",
          DialogueId = 51005702,
          GUID = "7FAFFAFC",
          NextDialogue = 51005703
        },
        [51005703] = {
          ContentKR = "(몸에 난 상처는 아직도 제대로 치료하지 않았다. 이곳이 더운 곳이었다면 상처에서는 불쾌한 냄새가 났을 것이다.)",
          DialogueId = 51005703,
          GUID = "7FAFFB26",
          NextOptions = {
            [1] = 51005704
          }
        },
        [51005704] = {
          ContentKR = "...괜찮아요? 사장님은 뭐라고 하셨어요?",
          DialogueId = 51005704,
          GUID = "7FAFFB50",
          NextDialogue = 51005705
        },
        [51005705] = {
          ContentKR = "...",
          DialogueId = 51005705,
          GUID = "7FAFFB7A",
          LookAt = {
            [1] = "700121:n(0)"
          },
          NextDialogue = 51005706,
          SpeakNpcId = 700121
        },
        [51005706] = {
          ContentKR = "...하하, 거들떠보지도 않았어요. 그동안 제 요리로는 돈을 못 벌었다면서, 저를 다시 고용하지 않겠대요.",
          DialogueId = 51005706,
          GUID = "7FAFFBA4",
          NextOptions = {
            [1] = 51005707
          },
          SpeakNpcId = 700121
        },
        [51005707] = {
          ContentKR = "...",
          DialogueId = 51005707,
          GUID = "7FAFFBCE",
          NextDialogue = 51005708
        },
        [51005708] = {
          ContentKR = "괜찮아요. 이제 마지막 요리도 완성했는데, 먹어볼래요?",
          DialogueId = 51005708,
          GUID = "7FAFFBF8",
          NextDialogue = 51005709,
          SpeakNpcId = 700121
        },
        [51005709] = {
          ContentKR = "(마커스가 떨리는 두 손으로 도시락 뚜껑을 열자, 스튜와 미트볼의 향기가 한데 어우러져 흘러나오며 식욕을 자극한다.)",
          DialogueId = 51005709,
          GUID = "7FAFFC22",
          NextDialogue = 51005710
        },
        [51005710] = {
          ContentKR = "(높으신 분들이 즐겨 먹는 스테이크는 아니었지만, 하루의 고단함을 달래 줄 식사로는 충분하다. 게다가 별 모양 해시 브라운 몇 조각을 곁들여, 요리에 특별한 정성을 더했다.)",
          DialogueId = 51005710,
          GUID = "7FAFFC4C",
          NextDialogue = 51005711
        },
        [51005711] = {
          ContentKR = "(한 입 먹으니 평범한 모습과 달리 황홀한 맛이 나서, 기운이 솟고 기분이 좋아진다. 심지어 아이스레이크의 추위도 두렵지 않을 정도다.)",
          DialogueId = 51005711,
          GUID = "7FAFFC76",
          NextDialogue = 51005712
        },
        [51005712] = {
          ContentKR = "(도시락 밑에는 수정한 흔적이 가득한 레시피가 적힌 종이가 있다. 그는 이제 레시피의 새로운 주인이 생겼다는 듯 고개를 끄덕인다. 그리고 웃으며 평가를 기다린다.)",
          DialogueId = 51005712,
          GUID = "7FAFFCA0",
          NextOptions = {
            [1] = 510057121,
            [2] = 510057122
          },
          bForbidSkipOptions = true
        },
        [51005713] = {
          ContentKR = "제 음식을 먹어줘서 고마워요...",
          DialogueId = 51005713,
          GUID = "7FAFFCCA",
          NextDialogue = 51005714,
          SpeakNpcId = 700121
        },
        [51005714] = {
          ContentKR = "(마커스는 길게 숨을 내쉰 뒤, 팔을 축 늘어뜨린 채 천천히 눈을 감았다.)",
          DialogueId = 51005714,
          GUID = "7FAFFCF4",
          NextDialogue = 51005715
        },
        [51005715] = {
          ContentKR = "그동안 재료를 찾아주느라 고생했으니 푹 쉬어요... 저도...",
          DialogueId = 51005715,
          GUID = "7FAFFD1E",
          NextDialogue = 51005719,
          SpeakNpcId = 700121
        },
        [51005716] = {
          ContentKR = "그렇게 많이 실패했는데도, 당신은 제가 좋은 음식을 만들 수 있다고 믿는군요... 제 음식을 좋아해 줘서... 고마워요.",
          DialogueId = 51005716,
          GUID = "7FAFFD48",
          NextDialogue = 51005717,
          SpeakNpcId = 700121
        },
        [51005717] = {
          ContentKR = "(마커스는 길게 숨을 내쉰 뒤, 팔을 축 늘어뜨린 채 천천히 눈을 감는다.)",
          DialogueId = 51005717,
          GUID = "7FAFFD72",
          NextDialogue = 51005718
        },
        [51005718] = {
          ContentKR = "파트너를 위해서 다시 힘을 내야죠. 우선 지금은 좀 쉴게요...",
          DialogueId = 51005718,
          GUID = "7FAFFD9C",
          NextDialogue = 51005719,
          SpeakNpcId = 700121
        },
        [51005719] = {
          ContentKR = "(흡족한 미소를 보니, 마커스는 그가 가장 원했던 평가를 들은 것 같다.)",
          DialogueId = 51005719,
          GUID = "7FAFFDC6"
        },
        [51005801] = {
          Camera = "-210.938385,14.624023,190.298828,0.000005,-33.268826,14.713709,27.0,1.5,false,Disable,1.2",
          ContentKR = "(어떻게 해도 상자가 열리지 않는다.)",
          DialogueId = 51005801,
          GUID = "7FB00B3A",
          NextDialogue = 51005802,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}"
        },
        [51005802] = {
