        },
        [51005808] = {
          Camera = "202.494812,-61.686523,45.185059,0.000138,8.606803,150.299393,35.000011,1.5,false,Disable,1.2",
          ContentKR = "오늘은 구름도 없고 날이 정말 좋네.",
          DialogueId = 51005808,
          GUID = "7FB00C60",
          LookAt = {
            [1] = "100001:n(700125)"
          },
          NextDialogue = 51005809,
          SpeakNpcId = 700125
        },
        [51005809] = {
          Camera = "-644.993774,-361.563477,276.576172,0.000161,-16.793268,38.694996,35.000011,1.5,false,Disable,1.2",
          ContentKR = "(상자 옆으로 또 다른 남자가 다가왔다. 뒷짐 지고 있는 손에서 검은 물감이 뚝뚝 떨어지고 있다.)",
          DialogueId = 51005809,
          FinalCamera = "-632.271545,-377.451172,276.576172,0.000162,-16.793268,38.694847,35.000011,1.5,false,Disable,1.2",
          GUID = "7FB00C8A",
          NextDialogue = 51005810,
          ToFinalCameraBlendTime = 10
        },
        [51005810] = {
          ContentKR = "(그는 휘파람을 불며 느긋한 척을 했고, 바닥에 놓인 상자 위에는 '제국 삼 형제의 보물'이라는 큰 글자가 나타났다. 분명 셋째가 방금 쓴 것이다.)",
          DialogueId = 51005810,
          GUID = "7FB00CB4",
          NextDialogue = 51005811
        },
        [51005811] = {
          Camera = "1.0383,-161.240234,125.036621,0.000154,-3.793118,125.094276,35.000011,1.5,false,Disable,1.2",
          ContentKR = "감히 우리 제국 삼 형제의 물건을 건드리려고 하다니. 우리한테 배상해야 할 거야. 무려 칠… 팔… 구… 구 다음이 뭐지?",
          DialogueId = 51005811,
          GUID = "7FB00CDE",
          NextOptions = {
            [1] = 51005812,
            [2] = 51005813
          },
          Scripts = "PlayAnimation{_delay{3},ActorId{700123},AnimationId{\"Think_Start\"},Duration{1}}",
          SpeakNpcId = 700123,
          TalkActionId = {
            [1] = "700123:Confident_End"
          },
          TurnTo = {
            [1] = "100001:n(700123)"
          }
        },
        [51005812] = {
          ContentKR = "십이야.",
          DialogueId = 51005812,
          GUID = "7FB00D08",
          NextDialogue = 51005814
        },
        [51005813] = {
          ContentKR = "영이야.",
          DialogueId = 51005813,
          GUID = "7FB00D32",
          NextDialogue = 51005814
        },
        [51005814] = {
          ContentKR = "아, 그렇구나. 알려줘서 고마워.",
          DialogueId = 51005814,
          GUID = "7FB00D5C",
          NextDialogue = 51005815,
          SpeakNpcId = 700123,
