        [51005815] = {
          Camera = "-25.328522,-87.751953,115.732422,0.000161,1.406718,133.292084,35.000015,1.5,false,Disable,1.2",
          ContentKR = "아니, 너한테 물어보는 거 아니거든?",
          DialogueId = 51005815,
          FinalCamera = "-93.570923,-15.314453,118.177246,0.000161,1.406718,133.292084,35.000015,1.5,false,Disable,1.2",
          GUID = "7FB00D86",
