          Duration = 3,
          GUID = "7FB05D6C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700145
        },
        [51006303] = {
          ContentKR = "뭐야? 지붕에 개는 또 왜 있는 거고?",
