          Duration = 3,
          GUID = "7FB05D96",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 51006304,
          SpeakNpcId = 700145
        },
        [51006304] = {
          ContentKR = "멍멍——",
          DialogueId = 51006304,
          Duration = 2,
          GUID = "7FB05DC0",
          SpeakNpcName = "UI_Npc_Name_Dog"
        },
        [51006305] = {
          ContentKR = "방금은 컨디션이 조금 별로였던 거지? 서두르지 말고 한 번 더 해보자! 난 네가 할 수 있다고 믿어!",
