          Duration = 3,
          GUID = "7FB05DEA",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700146
        },
        [51006401] = {
          ContentKR = "오, {nickname} 실력이 꽤 좋네. 그럼 이제 두 번째 도전으로 가볼까? 날 따라와.",
          DialogueId = 51006401,
          Duration = 3,
          GUID = "7FB06DAA",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 51006402,
