          GUID = "7FB0B40C",
          NextDialogue = 51006831,
          NextOptions = {
            [1] = 51006831,
            [2] = 51006832
          },
          SpeakNpcId = 100001
        },
        [51006831] = {
          ContentKR = "제가 안개의 바다로 가서 그 친구를 데려올 수 있을까요?",
          DialogueId = 51006831,
          GUID = "7FB0B436",
          NextDialogue = 51006833
        },
        [51006832] = {
