        [51006901] = {
          Camera = "475.811523,676.893555,129.602295,0.000004,0.0,-119.200165,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(기차 매표소가 눈에 들어오자 마르제에게서 얻은 '물건'이 떠오른다. 그중에 하나가 '차표'와 관련된 것 같다.)",
          DialogueId = 51006901,
          FinalCamera = "475.811523,694.0,129.602295,0.000004,0.0,-119.200157,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB0BFB2",
          LookAt = {
            [1] = "700147:n(700148)",
            [2] = "700148:n(700147)"
          },
          NextDialogue = 51006902,
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 5
        },
        [51006902] = {
          Camera = "475.811523,694.0,129.602295,0.000004,0.0,-119.200157,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(하필이면 이때 한 이국적인 차림새의 카론과 매표원 사이에 싸움이 일어난다.)",
          DialogueId = 51006902,
          GUID = "7FB0BFDC",
          NextDialogue = 51006903,
          TalkActionId = {
            [1] = "700147:Confident_Start",
            [2] = "100001:Think_End"
          }
        },
        [51006903] = {
          Camera = "50.741211,214.74707,179.342529,0.000012,-8.799981,-110.198242,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "돈 없으면 저리 가세요!",
          DialogueId = 51006903,
          GUID = "7FB0C006",
          NextDialogue = 51006904,
          SpeakNpcId = 700147
        },
        [51006904] = {
          Camera = "70.262695,-223.553711,140.896484,0.00001,0.0,109.401634,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그냥 질문 좀 하려는 건데 왜 화를 내요!",
          DialogueId = 51006904,
          GUID = "7FB0C030",
          NextDialogue = 51006905,
          SpeakNpcId = 700148,
          TalkActionId = {
            [1] = "700147:Confident_End",
            [2] = "700148:Shock_Start"
          }
        },
        [51006905] = {
          Camera = "50.741211,214.74707,179.342529,0.000012,-8.799981,-110.198242,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아, 네, 알겠습니다. 억양도 이상한 가난뱅이 선생님, 그럼 제가 예의 바르게 가격을 알려드린 후에는 어떻게 하실 건가요? 주머니에 땡전 한 푼 없으면서 갑질이라도 하시게요?",
          DialogueId = 51006905,
          GUID = "7FB0C05A",
          NextDialogue = 51006906,
          SpeakNpcId = 700147,
          TalkActionId = {
            [1] = "700147:Talk03_Start",
            [2] = "700148:Shock_End"
          }
        },
        [51006906] = {
          Camera = "33.833008,-38.410156,159.227783,0.00001,0.999987,101.202133,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "뭐라고요? 내가 돈이 없는 건 어떻게...",
          DialogueId = 51006906,
          GUID = "7FB0C084",
          NextDialogue = 51006907,
          SpeakNpcId = 700148,
          TalkActionId = {
            [1] = "700148:Explain01_Start",
            [2] = "700147:Talk03_End"
          }
        },
        [51006907] = {
          Camera = "8.34668,69.227539,155.484863,0.000015,-7.799837,-93.597458,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "어떻게요? 카론들 돈 몇 푼 없는 거야 뻔하죠. 여기는 부자나 귀족, 높은 분들을 위한 곳이에요. 빈털터리는 사절이라고요!",
          DialogueId = 51006907,
          GUID = "7FB0C0AE",
          NextDialogue = 51006908,
          SpeakNpcId = 700147,
          TalkActionId = {
            [1] = "700148:Explain01_End",
            [2] = "700147:Confident_Start"
          }
        },
        [51006908] = {
          Camera = "70.262695,-223.553711,140.896484,0.00001,0.0,109.401634,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(이방인은 입술을 부르르 떨더니 방언으로 반격하는데, 알아듣지 못하는 매표원은 이방인을 한 번 흘기고 만다. 체면을 구긴 상인이 씩씩거리며 떠난다.)",
          DialogueId = 51006908,
          GUID = "7FB0C0D8",
          Scripts = "PARA{MoveTo{_delay{2},ActorId{700148},MoveSpeed{75},TargetPoint{\"QuestPoint_20021901Move\"}},CameraMoveTo{_delay{2},TargetPosition{\"479.638672,673.591797,127.602295,0.000004,-0.600005,-125.400406,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}}"
        },
        [51006921] = {
          ContentKR = "멀끔하게 생겨 놓고, 왜 우리 밥그릇까지 넘보는 거야?",
          DialogueId = 51006921,
          GUID = "7FB0C0D9",
          NextOptions = {
            [1] = 51006922,
            [2] = 51006923
          },
          SpeakNpcId = 700230
        },
        [51006922] = {
          ContentKR = "전 쓰레기통 뒤지는 취미는 없어요.",
          DialogueId = 51006922,
          GUID = "7FB0C0DA",
          NextDialogue = 51006924
        },
        [51006923] = {
          ContentKR = "어디서 발뺌이야. 내가 이 두 눈으로 똑똑히 봤다고.",
          DialogueId = 51006923,
          GUID = "7FB0C0DB",
          NextDialogue = 51006924
        },
        [51006924] = {
          ContentKR = "어제 제복을 입은 어떤 여자가 울면서 그 상자를 여기 던져 버렸지. 어떤 넝마주이 할머니가 딱한 마음에 괜찮냐고 물었는데, 그 성질머리 더러운 여자가 남의 일에 신경 끄라고 쏴붙이더라니까.",
          DialogueId = 51006924,
          GUID = "7FB0C0DC",
          NextDialogue = 51006925,
          SpeakNpcId = 700230
        },
        [51006925] = {
          ContentKR = "그래, 네가 들고 있는 그 상자 말하는 거야. 그런데도 쓰레기통에서 주운 게 아니라고?",
          DialogueId = 51006925,
          GUID = "7FB0C0DD",
          NextDialogue = 51006926,
          SpeakNpcId = 700230
        },
        [51006926] = {
          ContentKR = "제가 주운 게 아니... 설명하기도 귀찮네요. 어쨌든, 주인에 대한 단서를 주신 건 감사해요.",
          DialogueId = 51006926,
          GUID = "7FB0C0DE",
          NextDialogue = 51006927,
          SpeakNpcId = 700230
        },
        [51006927] = {
          ContentKR = "(제복을 입은 까칠한 여자라... 마르제한테 받은 '그 물건'하고 관련된 사람이려나?)",
          DialogueId = 51006927,
          GUID = "7FB0C0DF",
          NextDialogue = 51006928,
          SpeakNpcId = 100001
        },
        [51006928] = {
          ContentKR = "(제복을 입은 까칠한 여자라... 마르제한테 받은 '그 물건'하고 관련된 사람이려나?)",
          DialogueId = 51006928,
          GUID = "7FB0C0E0",
          SpeakNpcId = 100001
        },
        [51006931] = {
          ContentKR = "매표원이 되고 1년하고도 8개월이 지나서야, 난 간신히 아이스레이크 시티에서 스칼렛까지 가는 푯값을 모을 수 있었어요.",
          DialogueId = 51006931,
          GUID = "7FB0C49E",
          NextDialogue = 51006932,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51006932] = {
          ContentKR = "잘된 거 아니에요? 조금씩 꿈에 다가서고 있는 거잖아요.",
          DialogueId = 51006932,
          GUID = "7FB0C4C8",
          NextDialogue = 51006933,
          SpeakNpcId = 100001
        },
        [51006933] = {
          ContentKR = "꿈에 다가서요? <H>카론 보호비</> 잊었어요? 푯값은 그 보호비에 비하면 새 발의 피라고요! 내가 5년은 쫄쫄 굶어야 그 애가 있는 곳으로 갈 표를 살 수 있단 거예요! 그런데 나한테는 먹여 살려야 할 가족도 있으니까...",
          DialogueId = 51006933,
          GUID = "7FB0C4F2",
          NextDialogue = 51007147,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007001] = {
          ContentKR = "기차 정보 물으러 왔어요? 아서요, 쌀쌀맞은 여자가 버티고 있거든요!",
          DialogueId = 51007001,
          GUID = "7FB0D01A",
          LookAt = {
            [1] = "700149:n(0)"
          },
          NextOptions = {
            [1] = 510070011,
            [2] = 510070012
          },
          SpeakNpcId = 700149,
          TurnTo = {
            [1] = "700149:n(0)"
          },
          bForbidSkipOptions = true
        },
        [51007002] = {
          ContentKR = "더는 못 참아요! 아주, 몹시, 매우 떠나고 싶어요!",
          DialogueId = 51007002,
          GUID = "7FB0D044",
          LookAt = {
            [1] = "700149:n(0)"
          },
          NextDialogue = 51007004,
          SpeakNpcId = 700149,
          TurnTo = {
            [1] = "700149:n(0)"
          }
        },
        [51007003] = {
          ContentKR = "배우고 있어요! 고향이랑 말씨가 달라서 그런 것뿐이에요!",
          DialogueId = 51007003,
          GUID = "7FB0D06E",
          LookAt = {
            [1] = "700149:n(0)"
          },
          NextDialogue = 51007004,
          SpeakNpcId = 700149,
          TurnTo = {
            [1] = "700149:n(0)"
          }
        },
        [51007004] = {
          ContentKR = "(만만치 않아 보이는 매표원이다. 하지만 언젠가 아이스레이크 시티를 떠나려면 이 여자를 상대해야만 한다. 지금 뭐든 해 봐야 하지 않을까?)",
          DialogueId = 51007004,
          GUID = "7FB0D098",
          LookAt = {
            [1] = "700149:n(0)"
          },
          NextDialogue = 51007005,
          RestartTag = 51007004,
          TurnTo = {
            [1] = "700149:n(0)"
          }
        },
        [51007005] = {
          ContentKR = "(마르제에게 얻은 '정보'가 있으니, 그게 대화의 포문을 열어 줄지도 모른다...)",
          DialogueId = 51007005,
          GUID = "7FB0D0C2",
          LookAt = {
            [1] = "700149:n(0)"
          },
          NextOptions = {
            [1] = 510070051
          },
          TurnTo = {
            [1] = "700149:n(0)"
          },
          bForbidSkipOptions = true
        },
        [51007006] = {
          ContentKR = "(뜻대로 풀리지 않는다. 지금은 좋은 방법이 떠오르지 않는다.)",
          DialogueId = 51007006,
          GUID = "7FB0D0EC"
        },
        [51007007] = {
          ContentKR = "고마워요! 멋지던데요! 다 지켜봤어요!",
          DialogueId = 51007007,
          GUID = "7FB0D116",
          SpeakNpcId = 700149,
          TalkActionId = {
            [1] = "700149:Agree"
          }
        },
        [51007101] = {
          ContentKR = "(이방인과 매표소로 걸어간다. 매표원 제시카가 위아래로 훑어보더니 차가운 말투로 말을 건넨다.)",
          DialogueId = 51007101,
          GUID = "7FB0E082",
          NextDialogue = 51007102
        },
        [51007102] = {
          ContentKR = "가난뱅이 카론이 한 명 더 늘었네요?",
          DialogueId = 51007102,
