          DialogueId = 51007578,
          GUID = "7FB12EC4",
          ImprPlusId = 1004,
          NextDialogue = 51007581
        },
        [51007579] = {
          ContentKR = "갑자기 할 일이 생각났어.",
          DialogueId = 51007579,
          GUID = "7FB12EEE",
          ImprPlusId = 1003,
          NextDialogue = 51007581
        },
        [51007580] = {
          ContentKR = "더 물어볼 거면 돈을 더 내도록 해.",
          DialogueId = 51007580,
          GUID = "7FB12F18",
          ImprPlusId = 1001,
          NextDialogue = 51007581
        },
        [51007581] = {
          ContentKR = "앗... 그, 그럼 오늘은 여기까지만 물어볼게요.",
          DialogueId = 51007581,
          GUID = "7FB12F42",
          NextDialogue = 51007582,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Agree"
          }
        },
        [51007582] = {
          ContentKR = "고마워요, {性别:형|누나}! 이 실버들은 오늘 보수예요. 받으세요.",
          DialogueId = 51007582,
          GUID = "7FB12F6C",
          NextDialogue = 51007583,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Give"
          }
        },
        [51007583] = {
          ContentKR = "다음에 또 용돈 모으면, 다시 찾아와서 다른 질문을 할게요!",
          DialogueId = 51007583,
          GUID = "7FB12F96",
          SpeakNpcId = 700011
        },
        [51007601] = {
          ContentKR = "쥐들이 다 어디 간 걸까...",
          DialogueId = 51007601,
          GUID = "7FB1328A",
          NextDialogue = 51007602,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Think_Start"
          }
        },
        [51007602] = {
          ContentKR = "(소년은 목을 길게 빼고, 호기심 가득한 눈으로 하수도 입구를 살피고 있다.)",
          DialogueId = 51007602,
          GUID = "7FB132B4",
          NextOptions = {
            [1] = 51007603,
            [2] = 51007604
          }
        },
        [51007603] = {
          ContentKR = "(인사한다.)",
          DialogueId = 51007603,
          GUID = "7FB132DE",
          NextDialogue = 51007607
        },
        [51007604] = {
          ContentKR = "(놀라게 한다.)",
          DialogueId = 51007604,
          GUID = "7FB13308",
          NextDialogue = 51007605
        },
        [51007605] = {
          ContentKR = "으앗?! 휴, 당신이었군요...",
          DialogueId = 51007605,
          GUID = "7FB13332",
          NextDialogue = 51007607,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Shock_Start"
          }
        },
        [51007607] = {
          ContentKR = "{$XiAoTag(Value_1,Value_2)$|탄이:시빌라} {性别: 형|누나}, 우연이네요! 또 만났어요!",
          DialogueId = 51007607,
          GUID = "7FB13386",
          NextDialogue = 51007608,
          SpeakNpcId = 700204
        },
        [51007608] = {
          ContentKR = "왜 이렇게 한가한 거예요? 일 안 하세요? 엄마가요, 카론들은 평소엔 공장에서 밤낮없이 계속 일한다고 그러셨거든요.",
          DialogueId = 51007608,
          GUID = "7FB133B0",
          NextDialogue = 51007609,
          SpeakNpcId = 700204
        },
        [51007609] = {
          ContentKR = "난 월석 사냥꾼이야.",
          DialogueId = 51007609,
          GUID = "7FB133DA",
          NextDialogue = 51007610,
          SpeakNpcId = 100001
        },
        [51007610] = {
          ContentKR = "아, 친구들한테 들은 적 있어요! 월석 사냥꾼은 '돈만 주면 뭐든지 하는 바보'라고 그랬죠.",
          DialogueId = 51007610,
          GUID = "7FB13404",
          NextDialogue = 51007611,
          SpeakNpcId = 700204
        },
        [51007611] = {
          ContentKR = "그런데 그건 걔들이 하는 말이고, 실제론 어떤 일을 하는지 알려 줄 수 있어요?",
          DialogueId = 51007611,
          GUID = "7FB1342E",
          NextOptions = {
            [1] = 51007612,
            [2] = 51007614,
            [3] = 51007616
          },
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007612] = {
          ContentKR = "(몸에 있는 흉터를 보여 준다.)",
          DialogueId = 51007612,
          GUID = "7FB13458",
          NextDialogue = 51007613
        },
        [51007613] = {
          ContentKR = "세상에, 엄청 위험한 일인가 보네요...",
          DialogueId = 51007613,
          GUID = "7FB13482",
          NextDialogue = 51007618,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Shock_Start"
          }
        },
        [51007614] = {
          ContentKR = "(벌어들인 보수를 보여 준다.)",
          DialogueId = 51007614,
          GUID = "7FB134AC",
          NextDialogue = 51007615
        },
        [51007615] = {
          ContentKR = "와, 돈을 이렇게 많이 벌 수 있군요!",
          DialogueId = 51007615,
          GUID = "7FB134D6",
          NextDialogue = 51007618,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Shock_Start"
          }
        },
        [51007616] = {
          ContentKR = "(무기를 꺼내 겁을 준다.)",
          DialogueId = 51007616,
          GUID = "7FB13500",
          NextDialogue = 51007617
        },
        [51007617] = {
          ContentKR = "어? 엄청 강하단 뜻이에요?",
          DialogueId = 51007617,
          GUID = "7FB1352A",
          NextDialogue = 51007618,
          SpeakNpcId = 700204
        },
        [51007618] = {
          ContentKR = "음... 실제로 일하는 걸 엄청 보고 싶은데... 아! 좋은 생각이 났어요!",
          DialogueId = 51007618,
          GUID = "7FB13554",
          NextDialogue = 51007619,
          SpeakNpcId = 700204
        },
        [51007619] = {
          ContentKR = "마침 하수도 생태 환경을 조사하려고 했는데, 같이 가 주실래요?",
          DialogueId = 51007619,
          GUID = "7FB1357E",
          NextDialogue = 51007620,
          SpeakNpcId = 700204
        },
        [51007620] = {
          ContentKR = "제가 의뢰를 맡겼다고 생각해 주시면 돼요. 보수도 드릴 거고요!",
          DialogueId = 51007620,
          GUID = "7FB135A8",
          NextDialogue = 51007623,
          SpeakNpcId = 700204
        },
        [51007623] = {
          ContentKR = "야호! 그럼 지금 바로 출발하죠.",
          DialogueId = 51007623,
          GUID = "7FB13626",
          NextDialogue = 51007624,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007624] = {
          ContentKR = "그거 아세요? 사람들은 쥐를 짜증 나는 생물이라고 하는데, 제가 봤을 땐 정말 흥미로운 동물이에요!",
          DialogueId = 51007624,
          GUID = "7FB13650",
          NextDialogue = 51007625,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007625] = {
          ContentKR = "제가 전에 여기서 늠름하고 커다란 쥐를 본 적이 있어요. 동화 속에 나오는 '전사 쥐'랑 엄청 닮았더라고요.",
          DialogueId = 51007625,
          GUID = "7FB1367A",
          NextDialogue = 51007626,
          SpeakNpcId = 700204
        },
        [51007626] = {
          ContentKR = "'전사 쥐'는 태어날 때부터 허약한 작은 쥐였는데, 계속해서 어려움을 극복하고 마지막엔 무리를 지키는 대영웅이 됐어요!",
          DialogueId = 51007626,
          GUID = "7FB136A4",
          NextDialogue = 51007627,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Angry01_Start"
          }
        },
        [51007627] = {
          ContentKR = "제가 봤던 그 커다란 쥐는 온몸에 흉터가 잔뜩 있었어요. 용감히 싸우다 생긴 상처들이 분명해요. 얘기하다 보니까 생각났는데, 이상하지만 등에 조그만 병도 하나 메고 있더라고요. 어쩌면 특별한 물건 같은 걸지도 몰라요...",
          DialogueId = 51007627,
          GUID = "7FB136CE",
          NextOptions = {
            [1] = 51007628,
            [2] = 51007631,
            [3] = 51007636
          },
          SpeakNpcId = 700204
        },
        [51007628] = {
          ContentKR = "실험 도구일 수도 있어.",
          DialogueId = 51007628,
          GUID = "7FB136F8",
          ImprPlusId = 1003,
          NextDialogue = 51007629
        },
        [51007629] = {
          ContentKR = "그럴 수도 있겠어요. 누군가 쥐를 실험 대상으로 쓰고 있는 걸지도요... 생각해 보니까 살짝 오싹한걸요...",
          DialogueId = 51007629,
          GUID = "7FB13722",
          NextDialogue = 51007630,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007630] = {
          ContentKR = "그렇지만, 그 쥐는 용감하게 자기 운명을 받아들였어요! 정말 영웅다운 모습이죠! 아쉬운 게 있다면...",
          DialogueId = 51007630,
          GUID = "7FB1374C",
          NextDialogue = 51007638,
          SpeakNpcId = 700204
        },
        [51007631] = {
          ContentKR = "동화가 현실이 된 것 같네. 아주 흥미로운걸.",
          DialogueId = 51007631,
          GUID = "7FB13776",
          ImprPlusId = 1004,
          NextDialogue = 51007632
        },
        [51007632] = {
          ContentKR = "헤헤, 저도 그렇게 생각해요!",
          DialogueId = 51007632,
          GUID = "7FB137A0",
          NextDialogue = 51007633,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007633] = {
          ContentKR = "으, 아쉬운 게 있다면... 앞으론 만날 기회가 영영 없다는 거지만요.",
          DialogueId = 51007633,
          GUID = "7FB137CA",
          NextOptions = {
            [1] = 51007634,
            [2] = 51007635
          },
          SpeakNpcId = 700204
        },
        [51007634] = {
          ContentKR = "왜 못 만나?",
          DialogueId = 51007634,
          GUID = "7FB137F4",
          NextDialogue = 51007638
        },
        [51007635] = {
          ContentKR = "날 없애서 입막음하려는 사람처럼 말하네...",
          DialogueId = 51007635,
          GUID = "7FB1381E",
          NextDialogue = 51007638
        },
        [51007636] = {
          ContentKR = "걔가 널 잡아먹을 뻔했단 얘기처럼 들리는데.",
          DialogueId = 51007636,
          GUID = "7FB13848",
          ImprPlusId = 1005,
          NextDialogue = 51007637
        },
        [51007637] = {
          ContentKR = "아니거든요! 엄청 순했고, 저한테 덤벼든 적도 없단 말이에요! 게다가, 이젠 이 세상에 없어요...",
          DialogueId = 51007637,
          GUID = "7FB13872",
          NextDialogue = 51007638,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007638] = {
          ContentKR = "며칠 전에, 그 전사 쥐가 어떤 거지 아저씨한테 잡혀서 꼬치구이가 되는 걸 봤거든요... 훌쩍...",
          DialogueId = 51007638,
          GUID = "7FB1389C",
          NextDialogue = 51007639,
          SpeakNpcId = 700204
        },
        [51007639] = {
          ContentKR = "하... 슬프긴 하지만, 연구를 하다 보면 늘 돌발 상황이 생기곤 해요. 이제, 전 걔가 보살피던 새끼 쥐들이 어떻게 지내는지 확인하고 싶어요.",
          DialogueId = 51007639,
          GUID = "7FB138C6",
          NextDialogue = 51007640,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007640] = {
          ContentKR = "출발하죠. 소리만 잘 들으면 쥐들이 사는 곳을 알아낼 수 있을 거예요!",
          DialogueId = 51007640,
          GUID = "7FB138F0",
          NextOptions = {
            [1] = 51007641,
            [2] = 51007643
          },
          SpeakNpcId = 700204
        },
        [51007641] = {
          ContentKR = "알겠어. 내 뒤에 꼭 붙어서 잘 따라와. 지켜 줄게.",
          DialogueId = 51007641,
          GUID = "7FB1391A",
          NextDialogue = 51007642
        },
        [51007642] = {
          ContentKR = "고마워요! 정말 든든하네요!",
          DialogueId = 51007642,
          GUID = "7FB13944",
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007643] = {
          ContentKR = "겁이 나서 그런데, 네가 앞장서 줘.",
          DialogueId = 51007643,
          GUID = "7FB1396E",
          NextDialogue = 51007644
        },
        [51007644] = {
          ContentKR = "아니죠? 조금 전까지만 해도 엄청 자신만만했잖아요...",
          DialogueId = 51007644,
          GUID = "7FB13998",
          NextDialogue = 51007645,
          SpeakNpcId = 700204
        },
        [51007645] = {
          ContentKR = "뭐, 어쩔 수 없네요. 그럼 절 따라오세요.",
          DialogueId = 51007645,
          GUID = "7FB139C2",
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Sigh_Start"
          }
        },
        [51007646] = {
          ContentKR = "하수도 안이 생각보다 꽤 넓네요...",
          DialogueId = 51007646,
          GUID = "7FB139EC",
          NextDialogue = 51007647,
          SpeakNpcId = 700204
        },
        [51007647] = {
          ContentKR = "(구석에서 회색 그림자 하나가 휙 지나갔다. 새끼 쥐인 모양이다.)",
          DialogueId = 51007647,
          GUID = "7FB13A16",
          NextDialogue = 51007648
        },
        [51007648] = {
          ContentKR = "앗, 봤어요? 꼬리가 좀 잘려 있는 저 새끼 쥐요. 전에 본 적이 있는데, 전사 쥐의 동료예요!",
          DialogueId = 51007648,
          GUID = "7FB13A40",
          NextDialogue = 51007649,
          SpeakNpcId = 700204
        },
        [51007649] = {
          ContentKR = "어?! 왜 도망갔지?",
          DialogueId = 51007649,
          GUID = "7FB13A6A",
          NextDialogue = 51007650,
          SpeakNpcId = 700204
        },
        [51007650] = {
          ContentKR = "절 기억 못 하나 봐요...",
          DialogueId = 51007650,
          GUID = "7FB13A94",
          NextDialogue = 51007651,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Think_Start"
          }
        },
        [51007651] = {
          ContentKR = "(소년은 생각에 잠긴 듯 자그마한 미간을 찌푸린다.)",
          DialogueId = 51007651,
          GUID = "7FB13ABE",
          NextDialogue = 51007652
        },
        [51007652] = {
          ContentKR = "{$XiAoTag(Value_1,Value_2)$|탄이:시빌라} {性别:형|누나}, 동물한테도 감정이 있다고 생각해요? 너무너무 알고 싶은데, 전 얘네 말을 알아들을 수 없으니까...",
          DialogueId = 51007652,
          GUID = "7FB13AE8",
          NextOptions = {
            [1] = 51007653,
            [2] = 51007656
          },
          SpeakNpcId = 700204
        },
        [51007653] = {
          ContentKR = "네가 감정이 있다고 믿는다면, 있는 거야.",
          DialogueId = 51007653,
          GUID = "7FB13B12",
          ImprPlusId = 1004,
          NextDialogue = 51007654
        },
        [51007654] = {
          ContentKR = "아뇨, 안 돼요. 그건 너무 주관적이잖아요. 연구는 증거가 있어야 해요!",
          DialogueId = 51007654,
          GUID = "7FB13B3C",
          NextDialogue = 51007655,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007655] = {
          ContentKR = "쟤들이 어떤 행동을 하는지 관찰하면, 알아낼 수 있을지도 몰라요.",
          DialogueId = 51007655,
          GUID = "7FB13B66",
          NextDialogue = 51007658,
          SpeakNpcId = 700204
        },
        [51007656] = {
          ContentKR = "감정은 말로만 전할 수 있는 게 아닌걸. 쟤들의 행동을 잘 관찰해 보면, 네 궁금증도 풀릴 거야.",
          DialogueId = 51007656,
          GUID = "7FB13B90",
          ImprPlusId = 1003,
          NextDialogue = 51007657
        },
        [51007657] = {
          ContentKR = "오! 진짜 그러네요!",
          DialogueId = 51007657,
          GUID = "7FB13BBA",
          NextDialogue = 51007658,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007658] = {
          ContentKR = "어디 보자... 이 새끼 쥐들이 전사 쥐를 존경한다면, 얘들도 걔처럼 용감하고, 사람을 잘 따르고, 동료를 아끼겠죠?",
          DialogueId = 51007658,
          GUID = "7FB13BE4",
          NextDialogue = 51007659,
          SpeakNpcId = 700204
        },
        [51007659] = {
          ContentKR = "좋아요! 그럼 당장 가서 확인해 봐요! 아까 그 새끼 쥐는 코너 쪽으로 사라졌으니까, 빨리 쫓아가죠!",
          DialogueId = 51007659,
          GUID = "7FB13C0E",
          SpeakNpcId = 700204
        },
        [51007660] = {
          ContentKR = "저기 보세요! 저기가 바로 쥐들 집이에요!",
          DialogueId = 51007660,
          GUID = "7FB13C38",
          NextDialogue = 51007661,
          SpeakNpcId = 700204
        },
        [51007661] = {
          ContentKR = "(찍찍거리는 날카로운 소리가 들려오는 생쥐 굴에서 역한 냄새가 풍겨 왔지만, 테오는 아랑곳하지 않고 눈을 크게 뜬 채 쥐들의 행동을 유심히 관찰한다.)",
          DialogueId = 51007661,
          GUID = "7FB13C62",
          NextDialogue = 51007662
        },
        [51007662] = {
          ContentKR = "(새끼 쥐들이 빵 반 조각을 차지하려고 서로 물어뜯으며 싸우고 있다.)",
          DialogueId = 51007662,
          GUID = "7FB13C8C",
          NextDialogue = 51007663
        },
        [51007663] = {
          ContentKR = "어... 얘네는... 동료를 별로 아끼지 않나 봐요.",
          DialogueId = 51007663,
          GUID = "7FB13CB6",
          NextDialogue = 51007664,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Shock_Start"
          }
        },
        [51007664] = {
          ContentKR = "(인기척을 느낀 쥐 몇 마리가 화들짝 놀라 허둥지둥 도망쳤다.)",
          DialogueId = 51007664,
          GUID = "7FB13CE0",
          NextDialogue = 51007665
        },
        [51007665] = {
          ContentKR = "음... 얘네는... 딱히 용감하지도 않네요.",
          DialogueId = 51007665,
          GUID = "7FB13D0A",
          NextDialogue = 51007666,
          SpeakNpcId = 700204
        },
        [51007666] = {
          ContentKR = "(남아있던 쥐 몇 마리가 갑자기 눈빛이 사나워지더니 우리를 향해 달려들었다!)",
          DialogueId = 51007666,
          GUID = "7FB13D34",
          NextDialogue = 51007667
        },
        [51007667] = {
          ContentKR = "으아악! 왜 갑자기 사람을 공격하는 거죠? 너무 예의 없는 거 아니에요?!",
          DialogueId = 51007667,
          GUID = "7FB13D5E",
          NextDialogue = 51007668,
          SpeakNpcId = 700204
        },
        [51007668] = {
          ContentKR = "{$XiAoTag(Value_1,Value_2)$|탄이:시빌라} {性别:형|누나}! 우리 빨리 도망쳐요!",
          DialogueId = 51007668,
          GUID = "7FB13D88",
          NextDialogue = 51007669,
          SpeakNpcId = 700204
        },
        [51007669] = {
          ContentKR = "너 먼저 도망가. 여긴 내가 맡을게.",
          DialogueId = 51007669,
          GUID = "7FB13DB2",
          SpeakNpcId = 100001
        },
        [51007670] = {
          ContentKR = "돌아왔네요, {$XiAoTag(Value_1,Value_2)$|탄이:시빌라} {性别:형|누나}! 아까 멀리서 쥐들하고 싸우는 거 봤어요! 진짜 대단하던데요!",
          DialogueId = 51007670,
          GUID = "7FB13DDC",
          NextDialogue = 51007671,
          SpeakNpcId = 700204
        },
        [51007671] = {
          ContentKR = "'굉장한 전투 능력의 보유자 {$XiAoTag(Value_1,Value_2)$|탄이:시빌라} {性别:형|누나}'... 음, 기록해 뒀어요.",
          DialogueId = 51007671,
          GUID = "7FB13E06",
          NextDialogue = 51007672,
          SpeakNpcId = 700204
        },
        [51007672] = {
          ContentKR = "그나저나... 에휴, 저 새끼 쥐들한테는 감정이란 게 없나 봐요...",
          DialogueId = 51007672,
          GUID = "7FB13E30",
          NextOptions = {
            [1] = 51007673,
            [2] = 51007675
          },
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007673] = {
          ContentKR = "어쩌면 한참 성장 중이라 저런 걸 수도 있어.",
          DialogueId = 51007673,
          GUID = "7FB13E5A",
          NextDialogue = 51007674
        },
        [51007674] = {
          ContentKR = "음...! 맞네요! 쟤네도 다 크면, 그 전사 쥐처럼 훌륭한 어른 쥐가 될지도 몰라요!",
          DialogueId = 51007674,
          GUID = "7FB13E84",
          NextDialogue = 51007677,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007675] = {
          ContentKR = "선생님 역할을 해 줄 어른 쥐가 없어져서 그런 걸지도 몰라.",
          DialogueId = 51007675,
          GUID = "7FB13EAE",
          NextDialogue = 51007676
        },
        [51007676] = {
          ContentKR = "음... 맞아요. 정말 슬픈 일이네요... 지켜 줄 어른 쥐가 사라져 버렸지만, 쟤들이 씩씩하게 자랐으면 좋겠어요.",
          DialogueId = 51007676,
          GUID = "7FB13ED8",
          NextDialogue = 51007677,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007677] = {
          ContentKR = "기록은 다 해 뒀으니까, 오늘 조사는 여기서 끝낼게요.",
          DialogueId = 51007677,
          GUID = "7FB13F02",
          NextDialogue = 51007678,
          SpeakNpcId = 700204
        },
        [51007678] = {
          ContentKR = "같이 와 줘서 고마웠어요, {$XiAoTag(Value_1,Value_2)$|탄이:시빌라} {性别:형|누나}! 오늘 보여 준 모습은 진짜 똑똑하고 듬직했어요! 사람들이 막 월석 사냥꾼 흉을 보던데, 아무래도 사실이 아니었나 봐요.",
          DialogueId = 51007678,
          GUID = "7FB13F2C",
          NextDialogue = 51007679,
          SpeakNpcId = 700204
        },
        [51007679] = {
          ContentKR = "다른 카론들도 이렇게 친절하면 좋을 텐데... 있잖아요. 제가 얼마 전에 성 북쪽에 있는 여관 입구에 있던 초록색 옷을 입은 누나한테 인사를 했거든요? 그런데 아는 척도 안 하더라고요.",
          DialogueId = 51007679,
          GUID = "7FB13F56",
          NextDialogue = 51007680,
          SpeakNpcId = 700204
        },
        [51007680] = {
          ContentKR = "우연히 못 보고 지나친 거겠지.",
          DialogueId = 51007680,
          GUID = "7FB13F80",
          NextDialogue = 51007681,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007681] = {
          ContentKR = "어? 그렇게 말하는 걸 보면... 설마 그 누나랑 아는 사이예요?",
          DialogueId = 51007681,
          GUID = "7FB13FAA",
          NextDialogue = 51007682,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007682] = {
          ContentKR = "응.",
          DialogueId = 51007682,
          GUID = "7FB13FD4",
          NextDialogue = 51007683,
          SpeakNpcId = 100001
        },
        [51007683] = {
          ContentKR = "엄청난데요! 아는 사람이 그렇게 많다니... 그 사람들이랑 어떻게 소통해요? 저한테도 가르쳐 줄 수 있어요?",
          DialogueId = 51007683,
          GUID = "7FB13FFE",
          NextOptions = {
            [1] = 51007684,
            [2] = 51007686
          },
          SpeakNpcId = 700204
        },
        [51007684] = {
          ContentKR = "다양한 사람들이랑 많이 대화하면서 요령을 익히면 돼.",
          DialogueId = 51007684,
          GUID = "7FB14028",
          NextDialogue = 51007685
        },
        [51007685] = {
          ContentKR = "(테오가 공책에 \"{$XiAoTag(Value_1,Value_2)$|탄이:시빌라} {性别:형|누나}의 소통 비결: 다양한 사람들과 대화하며 요령을 쌓는다.\"라고 적는다.)",
          DialogueId = 51007685,
          GUID = "7FB14052",
          NextDialogue = 51007688
        },
        [51007686] = {
          ContentKR = "어떻게 해야 좋을지 모르겠을 땐, 주먹이 답이야.",
          DialogueId = 51007686,
          GUID = "7FB1407C",
          NextDialogue = 51007687
        },
        [51007687] = {
          ContentKR = "(테오가 공책에 \"{$XiAoTag(Value_1,Value_2)$|탄이:시빌라} {性别:형|누나}의 소통 비결: 어떻게 해야 좋을지 모르겠을 때는, 주먹이 답이다.\"라고 적는다.)",
          DialogueId = 51007687,
          GUID = "7FB140A6",
          NextDialogue = 51007688
        },
        [51007688] = {
          ContentKR = "으음... 잘 적어 뒀어요.",
          DialogueId = 51007688,
          GUID = "7FB140D0",
          NextDialogue = 51007689,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007689] = {
          ContentKR = "(근처에서 갑자기 다급한 발소리가 들려오더니, 반듯하게 차려입은 한 여성이 우리를 향해 씩씩거리며 다가왔다.)",
          DialogueId = 51007689,
          GUID = "7FB140FA",
          IsBlack = 1
        },
        [51007690] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentKR = "테오! 너 또 어디 갔었니? 세상에, 꼴이 이게 뭐야. 옷이 왜 이렇게 더러워졌어!",
          DefaultLookAt = "1.0",
          DialogueId = 51007690,
          GUID = "7FB14124",
          NextDialogue = 51007691,
          SpeakNpcId = 700205,
          SpeakNpcName = "UI_CMNpc_Name_DeTiWoman",
          TurnTo = {
            [1] = "700204:n(700205)",
            [2] = "100001:n(700205)",
            [3] = "700205:n(700204)"
          }
        },
        [51007691] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentKR = "엄마...! 저희는 조금 전까지 하수도에서 쥐를 관찰하고 있었어요.",
          DefaultLookAt = "1.0",
          DialogueId = 51007691,
          GUID = "7FB1414E",
          NextDialogue = 51007692,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007692] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentKR = "뭐? 그런 지저분한 생물이 뭐가 볼 게 있다고?",
          DefaultLookAt = "1.0",
          DialogueId = 51007692,
          GUID = "7FB14178",
          NextDialogue = 51007693,
          SpeakNpcId = 700205
        },
        [51007693] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentKR = "수업은 제대로 듣지도 않으면서, 하루 종일 이런 이상한 것만 연구하러 다니고... 내가 너 때문에 못 살아...",
          DefaultLookAt = "1.0",
          DialogueId = 51007693,
          GUID = "7FB141A2",
          NextDialogue = 51007694,
          SpeakNpcId = 700205,
          TalkActionId = {
            [1] = "700205:Sigh_Start"
          }
        },
        [51007694] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentKR = "(한참이나 불평을 늘어놓던 여자의 시선이 마침내 날 향하더니, 잔뜩 경계하며 테오를 자기 뒤로 잡아당겼다.)",
          DefaultLookAt = "1.0",
          DialogueId = 51007694,
          GUID = "7FB141CC",
          NextDialogue = 51007695,
          TurnTo = {
            [1] = "700204:n(100001)",
            [2] = "700205:n(100001)"
          }
        },
        [51007695] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentKR = "누구시죠? 그쪽이 우리 애를 꼬드긴 거군요?",
          DefaultLookAt = "1.0",
          DialogueId = 51007695,
          GUID = "7FB141F6",
          NextOptions = {
            [1] = 51007696,
            [2] = 51007698
          },
          SpeakNpcId = 700205
        },
        [51007696] = {
          ContentKR = "근거도 없이 함부로 사람 모함하지 마세요.",
          DialogueId = 51007696,
          GUID = "7FB14220",
          ImprPlusId = 1002,
          NextDialogue = 51007697
        },
        [51007697] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentKR = "어머, 카론이 잘도 억울하단 소릴 하네요?",
          DefaultLookAt = "1.0",
          DialogueId = 51007697,
          GUID = "7FB1424A",
          NextDialogue = 51007700,
          SpeakNpcId = 700205
        },
        [51007698] = {
          ContentKR = "맞아요, 정답이에요! 바로 저랍니다!",
          DialogueId = 51007698,
          GUID = "7FB14274",
          ImprPlusId = 1005,
          NextDialogue = 51007699
        },
        [51007699] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentKR = "당신...!",
          DefaultLookAt = "1.0",
          DialogueId = 51007699,
          GUID = "7FB1429E",
          NextDialogue = 51007700,
          SpeakNpcId = 700205
        },
        [51007700] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentKR = "테오... 엄마가 몇 번을 말했니, 카론들하고 어울리지 말라니까! 카론은 하나같이 질이 나쁘단 말이야!",
          DefaultLookAt = "1.0",
          DialogueId = 51007700,
          GUID = "7FB142C8",
          NextDialogue = 51007701,
          SpeakNpcId = 700205,
          TurnTo = {
            [1] = "700204:n(700205)",
            [2] = "100001:n(700205)",
            [3] = "700205:n(700204)"
          }
        },
        [51007701] = {
          ContentKR = "(소년은 어머니에게 억지로 끌려 가면서도 슬쩍 고개를 돌려 나를 바라보더니, \"다음에 봐요\"라고 벙긋거리며 작은 꾸러미 하나를 던져 주었다.)",
          DialogueId = 51007701,
          GUID = "7FB142F2",
          IsBlack = 1
        },
        [51007702] = {
          ContentKR = "{$XiAoTag(Value_1,Value_2)$|탄이:시빌라} {性别:형|누나}, {$XiAoTag(Value_1,Value_2)$|탄이:시빌라} {性别:형|누나}! 저 여기 있어요!",
          DialogueId = 51007702,
          GUID = "7FB1431C",
          NextDialogue = 51007703,
          SpeakNpcId = 700204
        },
        [51007703] = {
          ContentKR = "(건물 그늘에 숨은 소년이 나를 향해 신나게 손을 흔든다.)",
          DialogueId = 51007703,
          GUID = "7FB14346",
          NextDialogue = 51007704
        },
        [51007704] = {
          ContentKR = "또 만났네요!",
          DialogueId = 51007704,
          GUID = "7FB14370",
          NextDialogue = 51007705,
          SpeakNpcId = 700204
        },
        [51007705] = {
          ContentKR = "제가 나중에 알아봤는데, 진짜 이름은 {nickname} 맞죠! 칫, 어떻게 애 상대로 거짓말을 할 수 있어요?",
          DialogueId = 51007705,
          GUID = "7FB1439A",
          NextDialogue = 51007706,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Talk03_Start"
          }
        },
        [51007706] = {
          ContentKR = "저번엔 정말 미안했어요. 우리 엄마는 카론이 엄청 무서우신가 봐요.",
          DialogueId = 51007706,
          GUID = "7FB143C4",
          NextDialogue = 51007707,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007707] = {
          ContentKR = "그날, 집에 가니까 엄마가 절 붙잡고 한참 얘기하시더라고요. 대충 \"카론들은 놀고먹는 것만 좋아하는 게으름뱅이에, 타고난 범죄자들이니까 엄청 위험하다\" 뭐 이런 내용이었어요.",
          DialogueId = 51007707,
          GUID = "7FB143EE",
          NextDialogue = 51007708,
          SpeakNpcId = 700204
        },
        [51007708] = {
          ContentKR = "다른 어른들도 비슷하게 말씀하시던데, 전 아무리 생각해도 그게 좀 이상해요!",
          DialogueId = 51007708,
          GUID = "7FB14418",
          NextDialogue = 51007709,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007709] = {
          ContentKR = "전 카론에 대해 알고 싶은데, 제가 겁을 먹고 말을 못 걸거나, 상대 쪽에서 저랑 이야기하고 싶지 않아 하는 경우가 많더라고요. 그래서 말인데요, 저한테 카론의 일상 얘기를 해 주면 안 될까요?",
          DialogueId = 51007709,
          GUID = "7FB14442",
          NextDialogue = 51007710,
          SpeakNpcId = 700204
        },
        [51007710] = {
          ContentKR = "설명보단 직접 데려가서 보여 주는 게 낫겠지. 마침 나한테 카메라도 있으니까, 사진 찍어 가서 차분히 생각해 봐.",
          DialogueId = 51007710,
          GUID = "7FB1446C",
          NextDialogue = 51007711,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007711] = {
          ContentKR = "정말요? 진짜 고마워요!",
          DialogueId = 51007711,
          GUID = "7FB14496",
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007712] = {
          Camera = "-329.898193,-397.409424,278.790771,0.000011,-19.79974,48.99963,22.97237,100000.0,false,Manual,22.0",
          ContentKR = "저기 낡은 노점들 보이지? 다들 해 뜨기도 전에 나와서 장사 준비를 해. 카론은 대부분 저렇게 살아가. 저 사람들이랑 친해지면, 뭐 살 때 좀 싸게 해 줄 수도 있어.",
          DialogueId = 51007712,
          GUID = "7FB144C0",
          NextDialogue = 51007713,
          SpeakNpcId = 100001
        },
        [51007713] = {
          Camera = "-329.898193,-397.409424,278.790771,0.000011,-19.79974,48.99963,22.97237,100000.0,false,Manual,22.0",
          ContentKR = "다들... 엄청 지치고 피곤해 보여요.",
          DialogueId = 51007713,
          GUID = "7FB144EA",
          SpeakNpcId = 700204
        },
        [51007714] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentKR = "카론들은 거의 다 여기 살아.",
          DialogueId = 51007714,
          GUID = "7FB14514",
          NextDialogue = 51007715,
          SpeakNpcId = 100001
        },
        [51007715] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentKR = "으음... 집들이 다 낡았네요. 아, 무섭게 생긴 아저씨가 옆집에서 지붕 고치는 걸 도와주고 있어요. 그리고 저 아이들이 하고 있는 놀이는, 제가 내성에서 친구들이랑 해 봤던 거고요.",
          DialogueId = 51007715,
          GUID = "7FB1453E",
          NextDialogue = 51007716,
          SpeakNpcId = 700204
        },
        [51007716] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentKR = "이제 왜 절 여기 데려온 건지 알겠네요. 말을 거칠게 하거나, 이상한 행동을 하는 카론들도 종종 있지만... 그건 우리 사람도 마찬가지예요.",
          DialogueId = 51007716,
          GUID = "7FB14568",
          NextDialogue = 51007717,
          SpeakNpcId = 700204
        },
        [51007717] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentKR = "머리에 난 뿔만 빼면, 카론이나 우리나 별로 다를 게 없는 것 같아요.",
          DialogueId = 51007717,
          GUID = "7FB14592",
          NextDialogue = 51007718,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007718] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentKR = "조금만 관찰하면 바로 알 수 있는 사실인데, 다들 왜 아직도 그런 잘못된 소문을 믿고 있는 걸까요?",
          DialogueId = 51007718,
          GUID = "7FB145BC",
          NextOptions = {
            [1] = 51007719,
            [2] = 51007720
          },
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Think_Start"
          }
        },
        [51007719] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentKR = "편견은 눈앞의 진실조차 보지 못하게 만들 때가 있거든.",
          DialogueId = 51007719,
          GUID = "7FB145E6",
          NextDialogue = 51007721
        },
        [51007720] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentKR = "다들 일부러 외면하는 걸지도 몰라.",
          DialogueId = 51007720,
          GUID = "7FB14610",
          NextDialogue = 51007721
        },
        [51007721] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentKR = "그런가요...? 복잡하네요... 이 세상엔 연구로 해결할 수 없는 문제도 있나 봐요...",
          DialogueId = 51007721,
          GUID = "7FB1463A",
          NextDialogue = 51007722,
          SpeakNpcId = 700204
        },
        [51007722] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentKR = "이런 생각은 이제 그만할래요. 마침 카메라도 가지고 계시니까, 우리 성 북쪽에 있는 그 히, 히 뭐더라? 히프노스의 집이라는 예쁜 건물 사진도 찍으러 가요! 거기서 기다릴게요!",
          DialogueId = 51007722,
          GUID = "7FB14664",
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007723] = {
          ContentKR = "왔군요! 헤헤, 제가 예전부터 몰래 지켜봤는데, 여기엔 제 또래의 카론 형이랑 누나들이 살고 있어요. 오늘 새롭게 알게 된 사실도 있으니까, 그 사람들이랑... 얘기해 보고 싶어요!",
          DialogueId = 51007723,
          GUID = "7FB1468E",
          NextDialogue = 51007724,
          SpeakNpcId = 700204
        },
        [51007724] = {
          ContentKR = "{nickname}, 저랑 같이 가 주면 안 될까요?",
          DialogueId = 51007724,
          GUID = "7FB146B8",
          NextDialogue = 51007725,
          SpeakNpcId = 700204
        },
        [51007725] = {
          ContentKR = "...",
          DialogueId = 51007725,
          GUID = "7FB146E2",
          NextOptions = {
            [1] = 51007726,
            [2] = 51007727
          },
          SpeakNpcId = 100001
        },
        [51007726] = {
          ContentKR = "(사실대로 말해 준다.)",
          DialogueId = 51007726,
          GUID = "7FB1470C",
          ImprPlusId = 1002,
          NextDialogue = 51007728
        },
        [51007727] = {
          ContentKR = "(사실대로 말할지 망설인다.)",
          DialogueId = 51007727,
          GUID = "7FB14736",
          ImprPlusId = 1004,
          NextDialogue = 51007728
        },
        [51007728] = {
          ContentKR = "지금은... 다들 좀 곤란할 수도 있어...",
          DialogueId = 51007728,
          GUID = "7FB14760",
          NextDialogue = 51007729,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Disagree"
          }
        },
        [51007729] = {
          ContentKR = "어...? 그런가요...",
          DialogueId = 51007729,
          GUID = "7FB1478A",
          NextDialogue = 51007730,
          SpeakNpcId = 700204
        },
        [51007730] = {
          ContentKR = "그럼... 노크해서 물어봐도 될까요? 마침 시간이 있을지도 모르니까, 그냥 물어보기만 할게요!",
          DialogueId = 51007730,
          GUID = "7FB147B4",
          NextDialogue = 51007731,
          SpeakNpcId = 700204
        },
        [51007731] = {
          ContentKR = "...사실, 여기엔 이제 아무도 안 살아. 그러니까, 문 두드릴 필요 없어.",
          DialogueId = 51007731,
          GUID = "7FB147DE",
          NextDialogue = 51007732,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007732] = {
          ContentKR = "어? 왜요? 저번에 몰래 봤을 땐 형이랑 누나가 몇 명이나 있었는걸요.",
          DialogueId = 51007732,
          GUID = "7FB14808",
          NextDialogue = 51007733,
          SpeakNpcId = 700204
        },
        [51007733] = {
          ContentKR = "다들... 이사 갔어...",
          DialogueId = 51007733,
          GUID = "7FB14832",
          NextDialogue = 51007734,
          SpeakNpcId = 100001
        },
        [51007734] = {
          ContentKR = "그럼 언제 돌아와요?",
          DialogueId = 51007734,
          GUID = "7FB1485C",
          NextDialogue = 51007735,
          SpeakNpcId = 700204
        },
        [51007735] = {
          ContentKR = "이 틈에 질문을 정리해야겠어요. 그 초록색 옷을 입은 누나한테 물어보고 싶은 게 있거든요! 그 무섭게 생긴 아저씨한테는... 음, 역시 됐어요.",
          DialogueId = 51007735,
          GUID = "7FB14886",
          NextDialogue = 51007736,
          SpeakNpcId = 700204
        },
        [51007736] = {
          ContentKR = "그 아이들은... 이제 안 돌아올 거야.",
          DialogueId = 51007736,
          GUID = "7FB148B0",
          NextDialogue = 51007737,
          SpeakNpcId = 100001
        },
        [51007737] = {
          ContentKR = "왜요? 군인 아저씨들이 쫓아낸 거예요? 아니면 다른 도시로 이사 간 건가요? 잘됐네요! 다른 데는 아이스레이크 시티보다 훨씬 따뜻할 테니까, 연구할 것도 훨씬 더 많을...",
          DialogueId = 51007737,
          GUID = "7FB148DA",
          NextDialogue = 51007738,
          SpeakNpcId = 700204
        },
        [51007738] = {
          ContentKR = "어?! {性别:형|누나}, 왜 울어요? 토닥토닥해 줄게요! 울지 말아요!",
          DialogueId = 51007738,
          GUID = "7FB14904",
          NextDialogue = 51007739,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Shock_Start"
          }
        },
        [51007739] = {
          ContentKR = "아, 아무것도 아니야. 여관 주인 헨릭 씨는 아주아주 좋은 의사 선생님이라서, 어떤 병을 치료할 방법을 연구하려고 꼬마 조수들이랑 같이 남쪽으로 가셨어. 많은 사람을 구하고 싶어 하셨거든.",
          DialogueId = 51007739,
          GUID = "7FB1492E",
          NextDialogue = 51007740,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Disagree"
          }
        },
        [51007740] = {
          ContentKR = "병이요? 음, 어떤 병인데요?",
          DialogueId = 51007740,
          GUID = "7FB14958",
          NextDialogue = 51007741,
          SpeakNpcId = 700204
        },
        [51007741] = {
          ContentKR = "...카론들만 걸리는 '침식'이란 병이야. 지금은 치료할 방법이 없어서, 많은 카론이 고통받고 있어.",
          DialogueId = 51007741,
          GUID = "7FB14982",
          NextDialogue = 51007742,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Think_Start"
          }
        },
        [51007742] = {
          ContentKR = "어? 치료할 방법이 없다고요? 제가 아는 의사 누나가 그랬는데, 연금원엔 똑똑한 연금술사들이 엄청 많아서, 인간이 걸리는 온갖 난치병을 치료해 줄 방법을 연구한다고...",
          DialogueId = 51007742,
          GUID = "7FB149AC",
          NextDialogue = 51007743,
          SpeakNpcId = 700204
        },
        [51007743] = {
          ContentKR = "(소년은 '인간'이라는 말을 꺼낸 후, 어떤 사실을 깨달은 듯 잠시 멈칫했다.)",
          DialogueId = 51007743,
          GUID = "7FB149D6",
          NextDialogue = 51007744
        },
        [51007744] = {
          ContentKR = "그러니까, 그 어른들은... 카론들이 걸리는 병을 치료해 줄 방법은 연구해 주지 않는 거예요?",
          DialogueId = 51007744,
          GUID = "7FB14A00",
          NextDialogue = 51007745,
          SpeakNpcId = 700204
        },
        [51007745] = {
          ContentKR = "그런 게 어디 있어요... 다 똑같은 사람이잖아요! 어떻게 카론이라는 이유로 치료해 주지 않을 수 있죠!",
          DialogueId = 51007745,
          GUID = "7FB14A2A",
          NextOptions = {
            [1] = 51007746
          },
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007746] = {
          ContentKR = "난 믿어. 여기엔 없을지 몰라도... 이 세상 어딘가에선 누군가 그걸 위해 열심히 노력하고 있을 거라고.",
          DialogueId = 51007746,
          GUID = "7FB14A54",
          ImprPlusId = 1004,
          NextDialogue = 51007747
        },
        [51007747] = {
          ContentKR = "...결심했어요! 연구만으로 사람들의 생각을 바꾸긴 어렵겠지만, 병이라면 해결할 수 있겠죠?",
          DialogueId = 51007747,
          GUID = "7FB14A7E",
          NextDialogue = 51007748,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Angry01_Start"
          }
        },
        [51007748] = {
          ContentKR = "저도 그 병을 연구할래요! 저도 그 의사 선생님처럼 열심히 노력해서 사람을 아주아주 많이 구할 거예요.",
          DialogueId = 51007748,
          GUID = "7FB14AA8",
          NextDialogue = 51007749,
          SpeakNpcId = 700204
        },
        [51007749] = {
          ContentKR = "연금원에는 인간을 도우려는 연금술사들이 정말 많지만, 저는 카론을 돕는 첫 번째 연금술사가 되고 싶어요!",
          DialogueId = 51007749,
          GUID = "7FB14AD2",
          NextDialogue = 51007750,
          SpeakNpcId = 700204
        },
        [51007750] = {
          ContentKR = "제가 기억해 둘 수 있게, 그 병 이름을 여기 적어 줄 수 있어요?",
          DialogueId = 51007750,
          GUID = "7FB14AFC",
          NextDialogue = 51007751,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007751] = {
          ContentKR = "(나는 소년이 건넨 공책에 또박또박 '침식'이라는 두 글자를 적어 넣었다.)",
          DialogueId = 51007751,
          GUID = "7FB14B26",
          NextDialogue = 51007752
        },
        [51007752] = {
          ContentKR = "음, '침식'인가요... 잘 기억해 뒀어요.",
          DialogueId = 51007752,
          GUID = "7FB14B50",
          NextDialogue = 51007753,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007753] = {
          ContentKR = "{nickname}, 이런 걸 알려 줘서 고마워요! 오늘 정말 많은 걸 배웠어요.",
          DialogueId = 51007753,
          GUID = "7FB14B7A",
          NextDialogue = 51007754,
          SpeakNpcId = 700204
        },
        [51007754] = {
          ContentKR = "우리 서로 열심히 노력해요! 엄청 뛰어나시니까, 분명히 아이스레이크 시티 최고의 월석 사냥꾼이 될 수 있을 거예요. 그러면 모두가 카론을 다시 보게 되겠죠.",
          DialogueId = 51007754,
          GUID = "7FB14BA4",
          NextDialogue = 51007755,
          SpeakNpcId = 700204
        },
        [51007755] = {
          ContentKR = "그래, 약속할게.",
          DialogueId = 51007755,
          GUID = "7FB14BCE",
          NextDialogue = 51007756,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Agree"
          }
        },
        [51007756] = {
          ContentKR = "약속이에요!",
          DialogueId = 51007756,
          GUID = "7FB14BF8",
          NextDialogue = 51007757,
          SpeakNpcId = 700204
        },
        [51007757] = {
          ContentKR = "(소년이 손을 흔들며 작별 인사를 건넨다. 아이 특유의 해맑은 미소는 그대로였지만, 어쩐지 예전과는 다르게 사뭇 결연해 보인다.)",
          DialogueId = 51007757,
          GUID = "7FB14C22"
        },
        [51007758] = {
          ContentKR = "{NickName}, 또 만났네! 난 매일 새로운 것들을 열심히 공부하고 있어. 같이 힘내자!",
          DialogueId = 51007758,
          GUID = "7FB14C4C",
          SpeakNpcId = 700204
        },
        [51007801] = {
          Content = "向自然法则扔出的石头，最终一定会砸到自己的头上。",
          DialogueId = 51007801,
          GUID = "7FB1535A",
          NextDialogue = 51007802,
          SpeakNpcId = 700018
        },
        [51007802] = {
          Content = "（这是一个瘦弱潦倒的中年男性，看起来有些神经质，鼻梁上挂着一副厚厚的眼镜。）",
          DialogueId = 51007802,
          GUID = "7FB15384",
          NextDialogue = 51007803
        },
        [51007803] = {
          Content = "（周围散落的报告署名是“阿尔加尔”，你似乎在某些生物学期刊上见过这个名字。）",
          DialogueId = 51007803,
          GUID = "7FB153AE",
          NextOptions = {
            [1] = 51007804,
            [2] = 51007806,
            [3] = 51007808
          }
        },
        [51007804] = {
          Content = "自然是万物的起源，我们理应保护好它。",
          DialogueId = 51007804,
          GUID = "7FB153D8",
          ImprPlusId = 1002,
          NextDialogue = 51007805
        },
        [51007805] = {
          Content = "是的是的，我正是为此而来的。",
          DialogueId = 51007805,
          GUID = "7FB15402",
          NextDialogue = 51007810,
          SpeakNpcId = 100001
        },
        [51007806] = {
          Content = "自然是镜子，破坏它的苦果只会由自己吞食。",
          DialogueId = 51007806,
          GUID = "7FB1542C",
          ImprPlusId = 1001,
          NextDialogue = 51007807
        },
        [51007807] = {
          Content = "深刻的见解，我是生物学者阿尔加尔，很高兴认识你。",
          DialogueId = 51007807,
          GUID = "7FB15456",
          NextDialogue = 51007810,
          SpeakNpcId = 100001
        },
        [51007808] = {
          Content = "笑死，根本活不到砸到我的那天。",
          DialogueId = 51007808,
          GUID = "7FB15480",
          ImprPlusId = 1005,
          NextDialogue = 51007809
        },
        [51007809] = {
          Content = "……",
          DialogueId = 51007809,
          GUID = "7FB154AA",
          NextDialogue = 51007810,
          SpeakNpcId = 100001
        },
        [51007810] = {
          Content = "唉，年轻人，你听说过冰湖城的红角鹿吗？",
          DialogueId = 51007810,
          GUID = "7FB154D4",
          NextDialogue = 51007811,
          SpeakNpcId = 700018
        },
        [51007811] = {
          Content = "那是非常古老的物种，已经存在了三亿多年，至今保留着其原始而古老的相貌。",
          DialogueId = 51007811,
          GUID = "7FB154FE",
          NextDialogue = 51007812,
          SpeakNpcId = 700018
        },
        [51007812] = {
          Content = "这不只是一对红角，这是整片大陆诞生时的......脐血。",
          DialogueId = 51007812,
          GUID = "7FB15528",
          NextDialogue = 51007813,
          SpeakNpcId = 700018
        },
        [51007813] = {
          Content = "（阿尔加尔说话时，原本苍白的脸上浮现出了激动的红晕。可随后他似乎又想起了什么，露出焦虑悲戚的神色。）",
          DialogueId = 51007813,
          GUID = "7FB15552",
          NextDialogue = 51007814
        },
        [51007814] = {
          Content = "所以我一定要阻止那些贪得无厌的猎人，不能再任由他们无节制地狩猎红角鹿了......",
          DialogueId = 51007814,
          GUID = "7FB1557C",
          NextDialogue = 51007815,
          SpeakNpcId = 700018
        },
        [51007815] = {
          Content = "红角鹿的鹿角具有极高的药用价值，内城的贵族们开了高价收购。",
          DialogueId = 51007815,
          GUID = "7FB155A6",
          NextDialogue = 51007816,
          SpeakNpcId = 700018
        },
        [51007816] = {
          Content = "那群贵族们的拥趸像一群见了血肉的苍蝇一样蜂拥而上。他们握着枪杆杀红了眼，射向红角鹿的子弹越多，他们腰间的钱袋越重。",
          DialogueId = 51007816,
          GUID = "7FB155D0",
          NextDialogue = 51007817,
          SpeakNpcId = 700018
        },
        [51007817] = {
          Content = "仅仅十年，冰湖城郊区的红角鹿就从随处可见变成如今濒临灭绝的境地。",
          DialogueId = 51007817,
          GUID = "7FB155FA",
          NextOptions = {
            [1] = 51007818
          },
          RestartTag = 51007817,
          SpeakNpcId = 700018
        },
        [51007818] = {
          Content = "红角鹿活了三亿年，不该被人们的贪婪一朝逼入绝境。",
          DialogueId = 51007818,
          GUID = "7FB15624",
          ImprCheckId = 1063,
          NextDialogue = 51007819
        },
        [51007819] = {
          Content = "算了，多说无益......",
          DialogueId = 51007819,
          GUID = "7FB1564E",
          NextDialogue = 51007820,
          SpeakNpcId = 700018
        },
        [51007820] = {
          Content = "（阿尔加尔叹了口气，瘦弱的身体在转身时踉跄了一下，离开的背影如同一位殉道者。）",
          DialogueId = 51007820,
          GUID = "7FB15678",
          NextDialogue = 51007821,
          SpeakNpcId = 700018
        },
        [51007821] = {
          Content = "正如你所说，它们珍贵的鹿角不该成了猎人的摇钱树。",
          DialogueId = 51007821,
          GUID = "7FB156A2",
          NextDialogue = 51007822,
          SpeakNpcId = 700018
        },
        [51007822] = {
          Content = "红角鹿的繁殖期马上就要到了，我们必须为自然真的做些什么。",
          DialogueId = 51007822,
          GUID = "7FB156CC",
          NextDialogue = 51007823,
          SpeakNpcId = 700018
        },
        [51007823] = {
          Content = "咳，年轻人，可以拜托你帮我阻止那些滥杀红角鹿的猎人吗？",
          DialogueId = 51007823,
          GUID = "7FB156F6",
          NextDialogue = 51007824,
          SpeakNpcId = 700018
        },
        [51007824] = {
          Content = "年轻人，那就靠你了，我在这里等你回来。",
          DialogueId = 51007824,
          GUID = "7FB15720",
          SpeakNpcId = 700018
        },
        [51007825] = {
          Content = "赶走滥杀红角鹿的猎人，已经刻不容缓了。",
          DialogueId = 51007825,
          GUID = "7FB1574A",
          SpeakNpcId = 700018
        },
        [51007826] = {
          Content = "（这只红角鹿的脖颈已经被猎人的子弹击穿，胸腔微弱起伏是它最后的挣扎。）",
          DialogueId = 51007826,
          GUID = "7FB15774",
          NextDialogue = 51007827
        }
      }
    end
  },
  {
