        },
        [51007923] = {
          ContentKR = "(잘못된 출구를 통해 밖으로 나온 달튼은 새하얗게 질린 얼굴로 바닥에 엎드려 속을 게 워냈다. 아무래도 꽤나 덜컹대는 '워터 슬라이드', 아니, 이 '하수도 슬라이드'는 그가 장담했던 것만큼 안전하고 재미있지 않은 모양이다.)",
          DialogueId = 51007923,
          GUID = "7FB1675E",
          NextOptions = {
            [1] = 51007924,
            [2] = 51007925
          }
        },
        [51007924] = {
          ContentKR = "괜찮아요?",
          DialogueId = 51007924,
          GUID = "7FB16788",
          ImprPlusId = 1002,
          NextDialogue = 51007926
        },
        [51007925] = {
          ContentKR = "제대로 못 봤는데, 한 번 더 보여 주시면 안 될까요?",
          DialogueId = 51007925,
          GUID = "7FB167B2",
          ImprPlusId = 1005,
          NextDialogue = 51007926
        },
        [51007926] = {
          Camera = "-310.433411,-170.472031,157.965942,0.000161,-12.197788,12.9158,15.353726,100000.0,false,Manual,22.0",
          ContentKR = "허억... 허억...",
          DialogueId = 51007926,
          GUID = "7FB167DC",
          NextDialogue = 51007927,
          SpeakNpcId = 700191
        },
        [51007927] = {
          ContentKR = "안 되겠어요. 전 일단, 좀 쉬어야 할 것 같아요... 약속했던 보상이에요. 받으세요... 저 먼저 가 볼게요...",
          DialogueId = 51007927,
          GUID = "7FB16806",
          NextDialogue = 51007928,
          SpeakNpcId = 700191,
          TalkActionId = {
            [1] = "700191:Sigh_Start"
          }
        },
        [51007928] = {
          Camera = "-125.646004,-486.612549,465.015015,-0.001072,-47.41058,90.325813,15.353726,100000.0,false,Manual,22.0",
          ContentKR = "하... 대체 어떡해야 싸고 재미있으면서도, 안개 구역 사람들이 부담 없이 탈 수 있는 놀이 기구를 만들 수 있을까...",
          DialogueId = 51007928,
          GUID = "7FB16830",
          NextDialogue = 51007929,
          SpeakNpcId = 700191
        },
        [51007929] = {
          ContentKR = "(달튼은 내게 작은 꾸러미 하나를 건네주고는, 가슴을 움켜쥔 채 뒤도 돌아보지 않고 하수도를 떠났다. 앞으로 그가 자신에게 슬픔을 안겨 준 이 장소에 다시 돌아올 일은 없겠지.)",
          DialogueId = 51007929,
          GUID = "7FB1685A",
          IsBlack = 1
        },
        [51007930] = {
          ContentKR = "안개 구역엔 놀거리가 아무것도 없어. 잠재적인 사업 기회가 있는 건 분명한데, 조금 더 고민해 봐야겠어...",
          DialogueId = 51007930,
          GUID = "7FB16884",
          SpeakNpcId = 700191
        },
        [51008001] = {
          ContentKR = "가, 가세요... 월석 살 생각 없으면 가세요... 괜히 병사들 눈길만 끌지 말고...",
          DialogueId = 51008001,
          GUID = "7FB1742A",
          NextDialogue = 51008002,
          SpeakNpcId = 700113
        },
        [51008002] = {
          ContentKR = "(건장한 체격과는 달리 남자는 구석에서 떨고 있다. 갖고 있는 월석을 팔고 싶어 하는 눈치였지만, 도움을 청하기는 주저하고 있다.)",
          DialogueId = 51008002,
          GUID = "7FB17454",
          NextOptions = {
            [1] = 51008003,
            [2] = 51008004,
            [3] = 51008005,
            [4] = 51008007
          }
        },
        [51008003] = {
          ContentKR = "살 생각은 없지만, 제게도 값만 치른다면 구매자를 알아봐 줄게요.",
          DialogueId = 51008003,
          GUID = "7FB1747E",
          ImprPlusId = 1001,
          NextDialogue = 51008009
        },
        [51008004] = {
          ContentKR = "도움이 필요한가요?",
          DialogueId = 51008004,
          GUID = "7FB174A8",
          ImprPlusId = 1004,
          NextDialogue = 51008009
        },
        [51008005] = {
          ContentKR = "이런 일은 제국이 용납하지 않아요. 문제 일으키기 싫으면 어서 떠나세요.",
          DialogueId = 51008005,
          GUID = "7FB174D2",
          ImprPlusId = 1002,
          NextDialogue = 51008006
        },
        [51008006] = {
          ContentKR = "한 번만 못 본 척해주세요. 월석만 다 팔면 아이스레이크 시티를 떠나 다시 오지 않을게요.",
          DialogueId = 51008006,
          GUID = "7FB174FC",
          NextDialogue = 51008009,
          SpeakNpcId = 700113
        },
        [51008007] = {
          ContentKR = "크흠! 군단 병사가 단속을 부탁했습니다. 통행증을 보여주시죠!",
          DialogueId = 51008007,
          GUID = "7FB17526",
          ImprPlusId = 1005,
          NextDialogue = 51008008
        },
        [51008008] = {
          ContentKR = "(말을 듣자마자 남자는 자루를 챙겨 도망치려 한다. 겨우 농담이었다는 말과 함께 신분을 밝히니 슬그머니 본인의 고충을 털어놓는다.)",
          DialogueId = 51008008,
          GUID = "7FB17550",
          NextDialogue = 51008009,
          SpeakNpcId = 700113
        },
        [51008009] = {
          ContentKR = "구매자를 찾아 주시면 몫의 70%... 아니, 80%를 드릴게요! 부탁이에요, 제발!",
          DialogueId = 51008009,
          GUID = "7FB1757A",
          SpeakNpcId = 700113
        },
        [51008010] = {
          ContentKR = "(남자의 의뢰를 수락하긴 했지만, 그의 표정과 자루에 말라붙어 있는 검붉은 흔적은 이 월석들이 정상적인 물건이 아니라는 걸 말해 주고 있었다.)",
          DialogueId = 51008010,
          GUID = "7FB175A4",
          NextDialogue = 51008011
        },
        [51008011] = {
          ContentKR = "(무턱대고 구매자를 찾다간 골치 아픈 일이 생길 수도 있으니, 아무래도 이 월석들의 출처부터 확인하는 편이 좋을 것 같다.)",
          DialogueId = 51008011,
          GUID = "7FB175CE"
        },
        [51008012] = {
          ContentKR = "(방금 이 풀숲에서 뭔가 반짝인 것 같았는데?)",
          DialogueId = 51008012,
          GUID = "7FB175F8",
          NextOptions = {
            [1] = 51008053
          }
        },
        [51008013] = {
          ContentKR = "(풀숲을 뒤져 봤지만, 아무것도 발견하지 못했다. 아무래도 잘못 본 모양이다.)",
          DialogueId = 51008013,
          GUID = "7FB17622"
        },
        [51008014] = {
          ContentKR = "(풀숲을 뒤지자, 예상대로 은은하게 빛나는 월석을 하나 발견했다. 문제는, 이 월석에도 남자의 자루에 묻어 있던 것과 똑같은 검붉은 피 얼룩이 남아 있다는 점이다.)",
          DialogueId = 51008014,
          GUID = "7FB1764C",
          NextDialogue = 51008015
        },
        [51008015] = {
          ContentKR = "오늘이 길에서 월석을 주울 만큼 유난히 운이 좋은 날은 아닌 것 같은데. 게다가 이런 식으로 피가 묻어 있는 월석이 흔한 것도 아니고...",
          DialogueId = 51008015,
          GUID = "7FB17676",
          NextDialogue = 51008016,
          SpeakNpcId = 100001
        },
        [51008016] = {
          ContentKR = "크르릉!",
          DialogueId = 51008016,
          GUID = "7FB176A0",
          NextDialogue = 51008017
        },
        [51008017] = {
          ContentKR = "일단 성가신 필토이드들부터 처리하자...",
          DialogueId = 51008017,
          GUID = "7FB176CA",
          SpeakNpcId = 100001
        },
        [51008018] = {
          ContentKR = "(바닥엔 아이스레이크의 자갈, 부러진 나뭇가지, 기와 조각 같은 잔해들이 어지럽게 흩어져 있다. 이 정도로 엉망인 걸 보면, 여기서 싸움이 벌어졌던 게 확실하다.)",
          DialogueId = 51008018,
          GUID = "7FB176F4",
          NextDialogue = 51008019
        },
        [51008019] = {
          ContentKR = "(잔해 사이로 찢어진 싸구려 천 조각과 솜이 보인다. 구매자를 찾던 그 남자가 입고 있던 옷과 같은 재질인 것 같다.)",
          DialogueId = 51008019,
          GUID = "7FB1771E"
        },
        [51008020] = {
          ContentKR = "(잔해를 치우자, 피가 묻어 있는 작은 월석 조각 하나가 나왔다.)",
          DialogueId = 51008020,
          GUID = "7FB17748"
        },
        [51008021] = {
          ContentKR = "(주위엔 사람 발자국만 어지럽게 남아 있을 뿐, 필토이드나 짐승의 발자국은 찾아볼 수 없다.)",
          DialogueId = 51008021,
          GUID = "7FB17772"
        },
        [51008022] = {
          ContentKR = "(묵직한 무언가를 끌고 간 자국이 저 멀리까지 남아 있다.)",
          DialogueId = 51008022,
          GUID = "7FB1779C",
          NextDialogue = 51008023
        },
        [51008023] = {
          ContentKR = "음... 여기서 무슨 일이 있었는지 대충 감이 잡히네. 월석에 묻어 있는 피는...",
          DialogueId = 51008023,
          GUID = "7FB177C6",
          NextOptions = {
            [1] = 51008024,
            [2] = 51008026,
            [3] = 51008028
          },
          SpeakNpcId = 100001
        },
        [51008024] = {
          ContentKR = "인간의 피",
          DialogueId = 51008024,
          GUID = "7FB177F0",
          NextDialogue = 51008025
        },
        [51008025] = {
          ContentKR = "(그래, 여기에 필토이드랑 짐승이 다녀간 흔적은 없었어.)",
          DialogueId = 51008025,
          GUID = "7FB1781A",
          NextDialogue = 51008030
        },
        [51008026] = {
          ContentKR = "짐승의 피",
          DialogueId = 51008026,
          GUID = "7FB17844",
          NextDialogue = 51008027
        },
        [51008027] = {
          ContentKR = "(아니야, 짐승이 왔었다면 짐승 발자국이 남아 있었을 거야.)",
          DialogueId = 51008027,
          GUID = "7FB1786E",
          NextDialogue = 51008030
        },
        [51008028] = {
          ContentKR = "필토이드의 피",
          DialogueId = 51008028,
          GUID = "7FB17898",
          NextDialogue = 51008029
        },
        [51008029] = {
          ContentKR = "(아니야, 필토이드가 왔었다면 필토이드의 발자국이 남아 있었을 거야.)",
          DialogueId = 51008029,
          GUID = "7FB178C2",
          NextDialogue = 51008030
        },
        [51008030] = {
          ContentKR = "(누군가 여기서 다른 사람을 습격했던 거야. 이유는 아마... 저 월석 자루 때문이었겠지. 이제 어떻게 할까...)",
          DialogueId = 51008030,
          GUID = "7FB178EC",
          SpeakNpcId = 100001,
          TalkOptions = {
            [1] = 51008031,
            [2] = 51008032
          }
        },
        [51008031] = {
          ContentKR = "어차피 정당하지 못한 방법으로 손에 넣은 물건이잖아. 이 월석은 내가 꿀꺽하자.",
          DialogueId = 51008031,
          GUID = "7FB17916",
          ImprPlusId = 1005
        },
        [51008032] = {
          ContentKR = "나쁜 짓을 했으면 벌을 받아야지. 방위대에 가서 신고하자.",
          DialogueId = 51008032,
          GUID = "7FB17940",
          ImprPlusId = 1002
        },
        [51008033] = {
          ContentKR = "남한테 절대 말 못 할 짓을 저지른 거죠?",
          DialogueId = 51008033,
          GUID = "7FB1796A",
          NextDialogue = 51008034,
          SpeakNpcId = 100001
        },
        [51008034] = {
          ContentKR = "당신은 이 월석을 잊었을 수도 있지만, 이 월석은 아니에요. 이 핏자국의 주인도 당신을 절대 잊지 않을 거고요.",
          DialogueId = 51008034,
          GUID = "7FB17994",
          NextDialogue = 51008035,
          SpeakNpcId = 100001
        },
        [51008035] = {
          ContentKR = "대체... 무슨 소리를 하는 건지 모르겠네요!",
          DialogueId = 51008035,
          GUID = "7FB179BE",
          NextDialogue = 51008036,
          SpeakNpcId = 700113
        },
        [51008036] = {
          ContentKR = "당신 도움 같은 거 필요 없어요. 월석이라뇨? 좀 알아듣게 말해요!",
          DialogueId = 51008036,
          GUID = "7FB179E8",
          NextDialogue = 51008037,
          SpeakNpcId = 700113
        },
        [51008037] = {
          ContentKR = "곧 방위대가 도착할 테니까, 이래 봐야 소용없어요. 그렇지만, 방법이 아예 없는 건 아니에요. 물론, 저한테 그 월석 자루를 넘겨야겠지만요.",
          DialogueId = 51008037,
          GUID = "7FB17A12",
          NextDialogue = 51008038,
          SpeakNpcId = 100001
        },
        [51008038] = {
          ContentKR = "전... 당신...",
          DialogueId = 51008038,
          GUID = "7FB17A3C",
          NextDialogue = 51008039,
          SpeakNpcId = 700113
        },
        [51008039] = {
          ContentKR = "아니면, 그냥 그 사람들 따라가셔도 돼요. 선택은 당신 몫이에요.",
          DialogueId = 51008039,
          GUID = "7FB17A66",
          NextDialogue = 51008040,
          SpeakNpcId = 100001
        },
        [51008040] = {
          ContentKR = "전 기다려 드릴 수 있지만, 방위대는 아닐걸요. 이렇게 머뭇거리는 동안에도, 방위대는 여기로 오고 있어요.",
          DialogueId = 51008040,
          GUID = "7FB17A90",
          NextDialogue = 51008041,
          SpeakNpcId = 100001
        },
        [51008041] = {
          ContentKR = "드릴게요! 전부 다 가져가라고요!",
          DialogueId = 51008041,
          GUID = "7FB17ABA",
          NextDialogue = 51008042,
          SpeakNpcId = 700113
        },
        [51008042] = {
          ContentKR = "다 이 망할 월석 자루 때문이에요! 우연히 이걸 발견하지만 않았어도, 동료들은 아직 살아 있었겠죠! 지금쯤이면 다 같이 쉬고 있었을 텐데...",
          DialogueId = 51008042,
          GUID = "7FB17AE4",
          NextDialogue = 51008043,
          SpeakNpcId = 700113
        },
        [51008043] = {
          ContentKR = "아니지... 오늘은 평소보다 벌이가 좋았으니까, 밤에 다 같이 아스포델에 가서 맥주 한 잔씩 가득 따라 마실 수도 있었을 거예요!",
          DialogueId = 51008043,
          GUID = "7FB17B0E",
          NextDialogue = 51008044,
          SpeakNpcId = 700113
        },
        [51008044] = {
          ContentKR = "코가 삐뚤어지게 마시면서, 밤새 허세도 부리고, 아침이 되면 다시 다 같이...",
          DialogueId = 51008044,
          GUID = "7FB17B38",
          NextDialogue = 51008045,
          SpeakNpcId = 700113
        },
        [51008045] = {
          ContentKR = "이건... 못 줘요!",
          DialogueId = 51008045,
          GUID = "7FB17B62",
          SpeakNpcId = 700113
        },
        [51008046] = {
          Camera = "-607.952148,-441.947266,565.15332,0.000023,-34.799801,23.996548,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "날 속였구나! 방위대는 무슨, 내 월석을 노리는 거잖아!",
          DialogueId = 51008046,
          GUID = "7FB17B8C",
          NextDialogue = 51008047,
          SpeakNpcId = 700113
        },
        [51008047] = {
          ContentKR = "조금 전에 절 공격했던 것처럼, 이걸로 동료들을 때려죽인 건가요?",
          DialogueId = 51008047,
          GUID = "7FB17BB6",
          NextDialogue = 51008048,
          SpeakNpcId = 100001
        },
        [51008048] = {
          ContentKR = "걔네가 먼저 시작했어... 나, 난 정당방위라고!",
          DialogueId = 51008048,
          GUID = "7FB17BE0",
          NextDialogue = 51008049,
          SpeakNpcId = 700113
        },
        [51008049] = {
          ContentKR = "너도... 이 월석 자루를 노리고 있는 주제에, 뭐가 그렇게 잘났어? 네까짓 게 뭔데 날 가르치려 들어?",
          DialogueId = 51008049,
          GUID = "7FB17C0A",
          NextOptions = {
            [1] = 51008050,
            [2] = 51008051
          },
          SpeakNpcId = 700113
        },
        [51008050] = {
          ContentKR = "어른이라면 자기가 저지른 잘못에 책임을 져야죠. 이 월석 자루를 교훈으로 삼으세요.",
          DialogueId = 51008050,
          GUID = "7FB17C34",
          ImprPlusId = 1001,
          NextDialogue = 51008052
        },
        [51008051] = {
          ContentKR = "좋은 사람이 아닌 건 피차일반이에요. 그래도 살려는 드릴 테니까, 눈앞에서 당장 사라져요.",
          DialogueId = 51008051,
          GUID = "7FB17C5E",
          ImprPlusId = 1005,
          NextDialogue = 51008052
        },
        [51008052] = {
          ContentKR = "(피 묻은 월석이 손에서 떨어질 듯 묵직하게 느껴진다. 마치 괴물로 변해 이 세상의 모든 '래리'를 집어 삼켜버릴 것만 같은 무게감이었다.)",
          DialogueId = 51008052,
          GUID = "7FB17C88",
          IsBlack = 1
        },
        [51008053] = {
          ContentKR = "고개 숙여 살짝 뒤져 보자",
          DialogueId = 51008053,
          GUID = "7FB17CB2",
          ImprCheckId = 1070
        },
        [51008054] = {
          ContentKR = "(눈에 거슬리던 필토이드들을 처리하자, 근처 지면에서 무언가 묻혀 있었던 것으로 추정되는 흔적이 드러났다. 난 이 새로운 단서들을 살펴보기로 했다.)",
          DialogueId = 51008054,
          GUID = "7FB17CDC"
        },
        [51009001] = {
          Camera = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "신작 공연을 상연합니다! 신작 공연이에요! 저기요, 한번 체험해 보시지 않겠어요?",
          DialogueId = 51009001,
          GUID = "7FB2183A",
          LookAt = {
            [1] = "700240:n(100001)"
          },
          NextDialogue = 51009002,
          SpeakNpcId = 700240
        },
        [51009002] = {
          ContentKR = "저한테 하신 말씀이세요?",
          DialogueId = 51009002,
          GUID = "7FB21864",
          NextDialogue = 51009003,
          SpeakNpcId = 100001
        },
        [51009003] = {
          ContentKR = "맞아요. 갈레아 극장에서 신개념 '몰입형 연극'을 시범 상연 중이에요!",
          DialogueId = 51009003,
          GUID = "7FB2188E",
          NextDialogue = 51009004,
          SpeakNpcId = 700240
        },
        [51009004] = {
          Camera = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "루카 공화국에서 건너온 완전히 새로운 공연 형식이에요! 더 이상 관객석에 앉아만 있는 게 아니라, 직접 어디 갈지 선택도 하고, 심지어는 이야기의 일부가 될 수도 있어요...",
          DialogueId = 51009004,
          GUID = "7FB218B8",
          NextDialogue = 51009005,
          SpeakNpcId = 700240,
          TalkActionId = {
            [1] = "700240:Explain02_Start"
          }
        },
        [51009005] = {
          ContentKR = "저희는 이 위대한 예술적 시도를 완성하기 위해 지원자가 필요하고요! 지금 상연 중인 건 영웅의 모험 이야기인데, 참여해 보실래요? 특별한 선물도 준비돼 있어요!",
          DialogueId = 51009005,
          GUID = "7FB218E2",
          SpeakNpcId = 700240,
          TalkActionId = {
            [1] = "700240:Explain02_End"
          }
        },
        [51009006] = {
          Camera = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "네, 그러면 절 따라오세요!",
          DialogueId = 51009006,
          GUID = "7FB2190C",
          LookAt = {
            [1] = "700240:n(100001)"
          },
          SpeakNpcId = 700240,
          TalkActionId = {
            [1] = "700240:Explain01_Start"
          }
        },
