          GUID = "7FB22AEE",
          NextDialogue = 51009116,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          }
        },
        [51009116] = {
          Camera = "-47.538391,-157.203125,145.923813,0.00021,-15.601462,76.384178,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "여행을 떠나는 젊은이에게는 무기만큼 든든한 동료가 없지. 걱정할 일이 없도록, 미리 준비해 두어야 한다네.",
          DialogueId = 51009116,
          FacialId = {
            [1] = "230002:Happy02"
          },
          GUID = "7FB22B18",
          NextDialogue = 51009117,
          SpeakNpcId = 230002,
          TalkActionId = {
            [1] = "100001:Explain02_End"
          }
        },
        [51009117] = {
          ContentKR = "이 늙은이는 자네 같은 젊은이를 너무나 많이 봐 왔다네. 이름 없이 스러져 버렸든, 아트라시아의 전설이 되었든, 다들 처음에는 호기심 많고 무모한 철부지에 불과했지.",
          DialogueId = 51009117,
          FacialId = {
            [1] = "230002:Ahaha02"
          },
          GUID = "7FB22B42",
          NextDialogue = 51009118,
          SpeakNpcId = 230002
        },
        [51009118] = {
          ContentKR = "믿음직한 무기야말로, 그런 경솔함과 미숙함을 보완해 주는 좋은 약이 되어 준다네.",
          DialogueId = 51009118,
          FacialId = {
            [1] = "230002:Satisfy01"
          },
          GUID = "7FB22B6C",
          NextDialogue = 51009119,
          SpeakNpcId = 230002
        },
        [51009119] = {
          Camera = "-11.187744,-30.125488,113.694717,0.000209,-16.401381,81.782051,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그다지 필요 없을지도 모르지만, 예비용으로라도 좋으니 이 무기를 받아 두게. 이 늙은이가 해 주는 충고라고 생각하게나.",
          DialogueId = 51009119,
          GUID = "7FB22B96",
          NextDialogue = 51009120,
          SpeakNpcId = 230002
        },
        [51009120] = {
          Camera = "-36.630005,38.096924,125.536903,0.000215,5.798011,-71.413826,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "어르신...",
          DialogueId = 51009120,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB22BC0",
          NextDialogue = 51009121,
          SpeakNpcId = 100001
        },
        [51009121] = {
          Camera = "-23.448242,-113.345947,147.890976,0.000217,-16.601587,81.187027,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "나중에 새로운 소재나 도면을 손에 넣거든 이 늙은이를 찾아오게. 그때 새 무기를 만들어 주겠네.",
          DialogueId = 51009121,
          FacialId = {
            [1] = "230002:Confident02"
          },
          GUID = "7FB22BEA",
          NextDialogue = 51009122,
          SpeakNpcId = 230002
        },
        [51009122] = {
          ContentKR = "하지만 이 무기만큼은... 몇 번이고 다시 벼려 줄 테니, 날이 무뎌지거나, 이가 빠지거나, 심지어는 부러진다 해도 다시 가져와 주게나.",
          DialogueId = 51009122,
          GUID = "7FB22C14",
          NextDialogue = 51009123,
          SpeakNpcId = 230002
        },
        [51009123] = {
          Camera = "-72.498413,-159.67749,187.376312,0.000227,-25.601515,61.982807,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "언제든 이 무기를 손에 쥘 때마다, 자네를 모험으로 이끌었던 처음 그 마음을 떠올릴 수 있기를 바라네.",
          DialogueId = 51009123,
          FacialId = {
            [1] = "230002:Happy02"
          },
          GUID = "7FB22C3E",
          NextDialogue = 51009124,
          SpeakNpcId = 230002
        },
        [51009124] = {
          Camera = "-77.020996,37.951172,120.615501,0.000228,5.798578,-53.617523,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "정말 잘 쓸게요.",
