          SpeakNpcId = 100001
        },
        [51009318] = {
          Content = "是呀。我有一位和你一样头上长着角的精灵朋友，这花就是要送给他的。",
          DialogueId = 51009318,
          GUID = "7FB24C3C",
          NextOptions = {
            [1] = 51009319,
            [2] = 51009321
          },
          SpeakNpcId = 700247
        },
        [51009319] = {
          Content = "“精灵？”",
          DialogueId = 51009319,
          GUID = "7FB24C66",
          NextDialogue = 51009320
        },
        [51009320] = {
          Content = "呵呵，那是他的说法。",
          DialogueId = 51009320,
          GUID = "7FB24C90",
          NextDialogue = 51009323,
          SpeakNpcId = 700247
        },
        [51009321] = {
          Content = "我是卡戎。",
          DialogueId = 51009321,
          GUID = "7FB24CBA",
          NextDialogue = 51009322
        },
        [51009322] = {
          Content = "嗯，“精灵”是他的说法。",
          DialogueId = 51009322,
          GUID = "7FB24CE4",
          NextDialogue = 51009323,
          SpeakNpcId = 700247
        },
        [51009323] = {
          Content = "说起来，外面起风了吗？",
          DialogueId = 51009323,
          GUID = "7FB24D0E",
          NextOptions = {
            [1] = 51009324,
            [2] = 51009326,
            [3] = 51009328
          },
          SpeakNpcId = 700247
        },
        [51009324] = {
          Content = "我没注意。",
          DialogueId = 51009324,
          GUID = "7FB24D38",
          NextDialogue = 51009325
        },
        [51009325] = {
          Content = "这样啊……没关系，我等会儿自己出去确认一下。",
          DialogueId = 51009325,
          GUID = "7FB24D62",
          NextDialogue = 51009330,
          SpeakNpcId = 700247
        },
        [51009326] = {
          Content = "正在刮大风。",
          DialogueId = 51009326,
          GUID = "7FB24D8C",
          NextDialogue = 51009327
        },
        [51009327] = {
          Content = "那就太好了。",
          DialogueId = 51009327,
          GUID = "7FB24DB6",
          NextDialogue = 51009330,
          SpeakNpcId = 700247
        },
        [51009328] = {
          Content = "没有风我也可以制造风。",
          DialogueId = 51009328,
          GUID = "7FB24DE0",
          NextDialogue = 51009329
        },
        [51009329] = {
          Content = "是吗，原来你这么厉害呀！谢谢你的好意。",
          DialogueId = 51009329,
          GUID = "7FB24E0A",
          NextDialogue = 51009330,
          SpeakNpcId = 700247
        },
        [51009330] = {
          Content = "我得等到起风的时候，才能把花送给他呢。",
          DialogueId = 51009330,
          GUID = "7FB24E34",
          NextOptions = {
            [1] = 51009331,
            [2] = 51009333,
            [3] = 51009335
          },
          SpeakNpcId = 700247
        },
        [51009331] = {
          Content = "为什么一定要等起风？",
          DialogueId = 51009331,
          GUID = "7FB24E5E",
          NextDialogue = 51009332
        },
        [51009332] = {
          Content = "因为起风的时候，花才会往空中飘呀。",
          DialogueId = 51009332,
          GUID = "7FB24E88",
          NextDialogue = 51009337,
          SpeakNpcId = 700247
        },
        [51009333] = {
          Content = "莫非你的朋友是风精灵吗？",
          DialogueId = 51009333,
          GUID = "7FB24EB2",
          NextDialogue = 51009334
        },
        [51009334] = {
          Content = "呵呵，很有意思的想法！说不定真的是喔。",
          DialogueId = 51009334,
          GUID = "7FB24EDC",
          NextDialogue = 51009337,
          SpeakNpcId = 700247
        },
        [51009335] = {
          Content = "这是某种特殊的仪式吗？",
          DialogueId = 51009335,
          GUID = "7FB24F06",
          NextDialogue = 51009336
        },
        [51009336] = {
          Content = "嗯……是传递思念的仪式。",
          DialogueId = 51009336,
          GUID = "7FB24F30",
          NextDialogue = 51009337,
          SpeakNpcId = 700247
        },
        [51009337] = {
          Content = "我的那位朋友，在几年前就去天上啦。",
          DialogueId = 51009337,
          GUID = "7FB24F5A",
          NextDialogue = 51009338,
          SpeakNpcId = 700247
        },
        [51009338] = {
          Content = "今天是每年一次的纪念日。",
          DialogueId = 51009338,
          GUID = "7FB24F84",
          NextOptions = {
            [1] = 51009339
          },
          RestartTag = 51009338,
          SpeakNpcId = 700247
        },
        [51009339] = {
          Content = "（提醒她卡戎人的习俗。）",
          DialogueId = 51009339,
          FailDialogue = 51009340,
          GUID = "7FB24FAE",
          ImprCheckId = 1071,
          NextDialogue = 51009341
        },
        [51009340] = {
          Content = "（你一时记不起习俗的细节。）",
          DialogueId = 51009340,
          GUID = "7FB24FD8"
        },
        [51009341] = {
          Content = "在卡戎人的观念中，雾海才是灵魂的归去之地。如果要纪念他，将花送往水中更加合理。",
          DialogueId = 51009341,
          GUID = "7FB25002",
          NextDialogue = 51009342,
          SpeakNpcId = 100001
        },
        [51009342] = {
          Content = "嗯……我知道。但是，他不一样。",
          DialogueId = 51009342,
          GUID = "7FB2502C",
          NextDialogue = 51009343,
          SpeakNpcId = 700247
        },
        [51009343] = {
          Content = "（女子沉默了片刻，看向窗外，眼神中流露着温柔的怀念。）",
          DialogueId = 51009343,
          GUID = "7FB25056",
          NextDialogue = 51009344
        },
        [51009344] = {
          Content = "我第一次遇见他是在城外。我们年纪相仿，性格也很像，所以很快就成了好朋友。",
          DialogueId = 51009344,
          GUID = "7FB25080",
          NextDialogue = 51009345,
          SpeakNpcId = 700247
        },
        [51009345] = {
          Content = "他对我说自己从是天上来的“精灵”……呵呵，其实我早知道他是卡戎人，但每次看到他那么努力地圆谎，实在是舍不得戳穿。",
          DialogueId = 51009345,
          GUID = "7FB250AA",
          NextDialogue = 51009346,
          SpeakNpcId = 700247
        },
        [51009346] = {
          Content = "而且，他确实就像故事里的精灵一样，知道许多我不知道的事，永远有讲不完的新奇见闻。",
          DialogueId = 51009346,
          GUID = "7FB250D4",
          NextOptions = {
            [1] = 51009347,
            [2] = 51009349
          },
          SpeakNpcId = 700247
        },
        [51009347] = {
          Content = "听起来是个很棒的朋友。",
          DialogueId = 51009347,
          GUID = "7FB250FE",
          NextDialogue = 51009348
        },
        [51009348] = {
          Content = "嗯！他是最棒的朋友。",
          DialogueId = 51009348,
          GUID = "7FB25128",
          NextDialogue = 51009351,
          SpeakNpcId = 700247
        },
        [51009349] = {
          Content = "所以他从小到大一直在扮演精灵吗？",
          DialogueId = 51009349,
          GUID = "7FB25152",
          NextDialogue = 51009350
        },
        [51009350] = {
          Content = "呵呵，听起来有点幼稚，对吧？",
          DialogueId = 51009350,
          GUID = "7FB2517C",
          NextDialogue = 51009351,
          SpeakNpcId = 700247
        },
        [51009351] = {
          Content = "我心里一直都有些苦恼——等到我们都长大，过了能理所当然地相信童话的年纪以后，要怎么开口说破这件事？",
          DialogueId = 51009351,
          GUID = "7FB251A6",
          NextDialogue = 51009352,
          SpeakNpcId = 700247
        },
        [51009352] = {
          Content = "无论是我先开口还是他先开口，想象一下都很尴尬呀……",
          DialogueId = 51009352,
          GUID = "7FB251D0",
          NextDialogue = 51009353,
          SpeakNpcId = 700247
        },
        [51009353] = {
          Content = "但最后我们并没有走到那个时间点。他在成年之前便离开了。",
          DialogueId = 51009353,
          GUID = "7FB251FA",
          NextDialogue = 51009354,
          SpeakNpcId = 700247
        },
        [51009354] = {
          Content = "你说，他会不会是想到了这一点，才故意选在那个时候离开的？呵呵，真是个温柔的人啊……",
          DialogueId = 51009354,
          GUID = "7FB25224",
          NextDialogue = 51009355,
          SpeakNpcId = 700247
        },
        [51009355] = {
          Content = "（女子抚摸着柔软的花瓣，轻轻垂下了眼眸。你分辨不出她脸上的情绪。）",
          DialogueId = 51009355,
          GUID = "7FB2524E",
          NextOptions = {
            [1] = 51009356,
            [2] = 51009358,
            [3] = 51009360
          }
        },
        [51009356] = {
          Content = "抱歉，请节哀……",
          DialogueId = 51009356,
          GUID = "7FB25278",
          ImprPlusId = 1002,
          NextDialogue = 51009357
        },
        [51009357] = {
          Content = "没关系，已经过去很多年啦。",
          DialogueId = 51009357,
          GUID = "7FB252A2",
          NextDialogue = 51009362,
          SpeakNpcId = 700247
        },
        [51009358] = {
          Content = "你们都是非常温柔的人。",
          DialogueId = 51009358,
          GUID = "7FB252CC",
          ImprPlusId = 1004,
          NextDialogue = 51009359
        },
        [51009359] = {
          Content = "呵呵，谢谢你。",
          DialogueId = 51009359,
          GUID = "7FB252F6",
          NextDialogue = 51009362,
          SpeakNpcId = 700247
        },
        [51009360] = {
          Content = "成年这个时间点……难道说，他是出现了秽蚀的征兆？",
          DialogueId = 51009360,
          GUID = "7FB25320",
          ImprPlusId = 1003,
          NextDialogue = 51009361
        },
        [51009361] = {
          Content = "嗯，我也这么想。毕竟他离开的时候，刚好是快满十八岁。",
          DialogueId = 51009361,
          GUID = "7FB2534A",
          NextDialogue = 51009362,
          SpeakNpcId = 700247
        },
        [51009362] = {
          Content = "他早就预料到了自己的结局……最后见面的那次，他对我说，自己将要回到天上的故乡，从今往后不能再来找我。",
          DialogueId = 51009362,
          GUID = "7FB25374",
          NextDialogue = 51009363,
          SpeakNpcId = 700247
        },
        [51009363] = {
          Content = "那是他撒谎撒得最拙劣的一次……明明眼泪已经在眼眶里打转了，还拼命挤出一副微笑的表情，用愉快的语调对我说——",
          DialogueId = 51009363,
          GUID = "7FB2539E",
          NextDialogue = 51009364,
          SpeakNpcId = 700247
        },
        [51009364] = {
          Content = "“请你不要感到难过。虽然我不能再来见你，但我会在云端之上一直、一直注视着你……”",
          DialogueId = 51009364,
          GUID = "7FB253C8",
          NextDialogue = 51009365,
          SpeakNpcId = 700247
        },
        [51009365] = {
          Content = "“无论何时，只要你抬头望向天空，你的思念就能够随风抵达我的身边。”",
          DialogueId = 51009365,
          GUID = "7FB253F2",
          NextDialogue = 51009366,
          SpeakNpcId = 700247
        },
        [51009366] = {
          Content = "（说到这里，女子露出了微笑。不知是否是错觉，她的眼中隐约闪过了一丝光亮——那究竟是泪光，还是从玻璃窗中洒下的阳光呢？）",
          DialogueId = 51009366,
          GUID = "7FB2541C",
          NextDialogue = 51009367
        },
        [51009367] = {
          Content = "所以，你才会把花撒向天空……？",
          DialogueId = 51009367,
          GUID = "7FB25446",
          NextDialogue = 51009368,
          SpeakNpcId = 100001
        },
        [51009368] = {
          Content = "嗯。既然那是他想要告诉我的故事，那么我也愿意相信，他的归处不是雾海，而是辽阔的蓝天。",
          DialogueId = 51009368,
          GUID = "7FB25470",
          NextDialogue = 51009369,
          SpeakNpcId = 700247
        },
        [51009369] = {
          Content = "只要将花瓣撒向天空，他就能感受到我的思念。",
          DialogueId = 51009369,
          GUID = "7FB2549A",
          NextOptions = {
            [1] = 51009370,
            [2] = 51009371
          },
          SpeakNpcId = 700247
        },
        [51009370] = {
          Content = "如果他能收到你的花就好了。",
          DialogueId = 51009370,
          GUID = "7FB254C4",
          NextDialogue = 51009372
        },
        [51009371] = {
          Content = "他一定会收到你的花的。",
          DialogueId = 51009371,
          GUID = "7FB254EE",
          NextDialogue = 51009372
        },
        [51009372] = {
          Content = "嗯，谢谢你！",
          DialogueId = 51009372,
          GUID = "7FB25518",
          NextDialogue = 51009373,
          SpeakNpcId = 700247
        },
        [51009373] = {
          Content = "现在回想起来，他大概也早就知道我已经看穿了他的谎话吧。",
          DialogueId = 51009373,
          GUID = "7FB25542",
          NextDialogue = 51009374,
          SpeakNpcId = 700247
        },
        [51009374] = {
          Content = "一个由谎言编织的故事，最后有了一个用谎言写就的结局……不也算是恰如其分吗？",
          DialogueId = 51009374,
          GUID = "7FB2556C",
          NextDialogue = 51009375,
          SpeakNpcId = 700247
        },
        [51009375] = {
          Content = "好啦，我要趁天还没黑，去城外完成和他的约定。",
          DialogueId = 51009375,
          GUID = "7FB25596",
          NextDialogue = 51009376,
          SpeakNpcId = 700247
        },
        [51009376] = {
          Content = "再见了，可爱的小精灵。祝愿你的故事有一个真实而美满的结局。",
          DialogueId = 51009376,
          GUID = "7FB255C0",
          SpeakNpcId = 700247
        },
        [51009377] = {
          Content = "哎呀，小精灵，又见面了。今天的天色很美吧？",
          DialogueId = 51009377,
          GUID = "7FB255EA",
          SpeakNpcId = 700247
        },
        [51009401] = {
          ContentKR = "저기, {性别:존귀한 신사분|아름다운 숙녀분}! 잠시 발걸음 좀 멈춰 주시겠어요?",
          DialogueId = 51009401,
          GUID = "7FB259DA",
          NextDialogue = 51009402,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700306:Talk01_Start"
          }
        },
        [51009402] = {
          ContentKR = "오, 당신을 어떤 말로 담아내야 할까요?",
          DialogueId = 51009402,
          GUID = "7FB25A04",
          NextDialogue = 51009403,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009403] = {
          ContentKR = "말 없는 너구리는 당신을 위해 시를 읊고, 푸른 달은 당신을 황금빛으로 물들이는군요. 바다토끼는 당신의 왕관을 종려나무 열매 보석으로 장식하고, 저는 아무도 없는 쓰레기통 옆에서 당신을 노래한답니다...",
          DialogueId = 51009403,
          GUID = "7FB25A2E",
          NextDialogue = 51009404,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009404] = {
          ContentKR = "제 찬미가 당신의 눈길을 사로잡을 수 있을지는 모르겠지만, 부디... 부디...",
          DialogueId = 51009404,
          GUID = "7FB25A58",
          NextDialogue = 51009405,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009405] = {
          ContentKR = "오! 이 비범한 용모! 당신이 바로 그 유명한 월석 사냥꾼 {nickname} 님이시군요!",
          DialogueId = 51009405,
          GUID = "7FB25A82",
          NextDialogue = 51009406,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700306:Talk01_End"
          }
        },
        [51009406] = {
          ContentKR = "(내가 그렇게 유명했나? ...아니야, 뭔가 다른 속셈이 있는 말투인데...)",
          DialogueId = 51009406,
          GUID = "7FB25AAC",
          NextDialogue = 51009407,
          SpeakNpcId = 100001
        },
        [51009407] = {
          ContentKR = "처음 뵙겠습니다, 저는 페온입니다. 선생님께서 기다리고 계십니다. 절 따라오시죠.",
          DialogueId = 51009407,
          GUID = "7FB25AD6",
          NextDialogue = 51009408,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700306,
          TalkActionId = {
            [1] = "700306:Talk02_Start"
          }
        },
        [51009408] = {
          ContentKR = "선생님이라고요?",
          DialogueId = 51009408,
          GUID = "7FB25B00",
          NextDialogue = 51009409,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700306:Talk02_End"
          }
        },
        [51009409] = {
          ContentKR = "아... 이런, 선생님께서 공개된 장소에선 그렇게 부르지 말라고 하셨는데 깜빡했네요. 하지만 당신이라면 괜찮겠죠...? 부디 비밀로 해주세요.",
          DialogueId = 51009409,
          GUID = "7FB25B2A",
          Scripts = "PlayOrStopBGM{_delay{8},PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700306
        },
        [51009410] = {
          Camera = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "선생님, {nickname} 님을 모셔 왔습니다.",
          DialogueId = 51009410,
          GUID = "7FB25B54",
          LookAt = {
            [1] = "700306:n(700300)"
          },
          NextDialogue = 51009411,
          SpeakNpcId = 700306
        },
        [51009411] = {
          Camera = "-398.734863,102.79834,140.336914,0.000002,-0.59967,-17.199116,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "왔구나, 젊은 월석 사냥꾼.",
          DialogueId = 51009411,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB25B7E",
          LookAt = {
            [1] = "700306:n(100001)"
          },
          NextDialogue = 51009412,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009412] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "어머, 정말 사랑스러운 아이구나. 널 보니 이 도시의 영롱한 첫눈과, 그 위에 흩뿌려진 비둘기 핏빛 석류석이 떠올라. 어디, 한번 어루만져 봐도 될...",
          DialogueId = 51009412,
          GUID = "7FB25BA8",
