          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009415] = {
          ContentKR = "내 이름은 비올레타, 오페라 가수란다.",
          DialogueId = 51009415,
