          TalkActionId = {
            [1] = "100001:Agree"
          }
        },
        [51009419] = {
          Camera = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "\"루카 공화국에서 온 꿈결 같은 목소리, 상식을 뒤엎는 천의 얼굴\", 비올레타 선생님은 아이스레이크 시티 당대 최고의 인기 가수시죠. 갈레아 극장에 가시면 선생님의 초상화가 그려진 커다란 포스터를 보실 수 있습니다.",
          DialogueId = 51009419,
          GUID = "7FB25CCE",
          LookAt = {
            [1] = "100001:n(700306)"
          },
          NextDialogue = 51009420,
          SpeakNpcId = 700306,
          TalkActionId = {
            [1] = "700306:Talk01_Start"
          }
        },
        [51009420] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "사람들이 날 그렇게 묘사하니? 조금 과장되긴 했지만, 마음에 드는구나.",
          DialogueId = 51009420,
          FacialId = {
            [1] = "700300:CM_Happy01"
          },
          GUID = "7FB25CF8",
          LookAt = {
            [1] = "100001:n(700300)"
