        },
        [51009428] = {
          Camera = "-216.009766,106.786621,145.499023,0.000003,1.000056,-22.195528,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "인기가 너무 많아도 때론 골치가 아프지. 날 열렬히 좋아해 주시는 건 감사하지만, 그런 마음을 전부 받아들일 순 없어서 최대한 정중하게 답장을 드리고 있어.",
          DialogueId = 51009428,
          GUID = "7FB25E48",
          NextDialogue = 51009429,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          }
        },
        [51009429] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "이런 편지야 한두 번 받아보는 것도 아니라, 매번 답장을 해주려 노력했어. 그런데 이번에는... 한 상자 가득 와 버렸지 뭐니.",
          DialogueId = 51009429,
          GUID = "7FB25E72",
          NextDialogue = 51009430,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009430] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "그... 그렇게 많이요?!",
          DialogueId = 51009430,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB25E9C",
          NextDialogue = 51009431,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Shock_Start"
          }
        },
        [51009431] = {
          Camera = "-437.178223,124.364746,139.453369,0.000004,-1.399676,-18.998108,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "그래, 전부 같은 사람이 보낸 거야. 처음엔 우편함, 그다음엔 마차 안, 나중엔 문틈, 창가 화분 아래까지...",
          DialogueId = 51009431,
          GUID = "7FB25EC6",
          NextDialogue = 51009432,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "100001:Shock_End"
          }
        },
        [51009432] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "나도 모르는 사이에 저택 구석구석이 비슷한 편지로 가득 차 있었어.",
