          NextDialogue = 51009435,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009435] = {
          ContentKR = "사소한 해프닝 덕에 사람들의 입에 더 오르내릴 수는 있겠지만, 배우로서는 무대 위 연기로만 기억되고 싶어. 부디 이해해 주렴.",
          DialogueId = 51009435,
          GUID = "7FB25F6E",
          NextDialogue = 51009436,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009436] = {
          Camera = "124.308105,149.785156,166.572021,0.000009,-4.799984,-153.390015,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "네, 알겠어요. 편지를 보낸 사람에 대한 단서 같은 건 있나요?",
          DialogueId = 51009436,
          GUID = "7FB25F98",
          NextDialogue = 51009437,
          SpeakNpcId = 100001
        },
        [51009437] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "그걸 깜빡했네. 사실은 편지를 보낸 사람의 주소를 이미 알고 있단다. 익명으로 보냈지만, 정작 본인은 정체를 숨길 생각이 없는 것 같았어.",
          DialogueId = 51009437,
          GUID = "7FB25FC2",
          NextDialogue = 51009438,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009438] = {
          ContentKR = "사랑을 고백하면서 정체를 숨겨야 한다면, 그 가여운 신사가 어떻게 답장을 기다릴 수 있겠니?",
          DialogueId = 51009438,
