        [51009460] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "이 아이스레이크 시티에서 그분을 모르는 사람이 있어? 초판 앨범은 가격이 천정부지라, 석 달 치 월급을 모아도 살 수가 없다고! 하, 그러니까 저렴한 녹음테이프나 들으면서 아쉬움을 달랠 수밖에.",
          DialogueId = 51009460,
          GUID = "7FB26388",
          NextDialogue = 51009461,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "700313:Confident_Start"
          }
        },
        [51009461] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "그럼 얘기가 쉽겠네요. 마침 비올레타 씨에 관한 걸 여쭤보려고 했거든요.",
          DialogueId = 51009461,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB263B2",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009462] = {
          ContentKR = "(꼭 비밀을 지켜달라고 몇 번이고 당부한 후, 비올레타 씨가 스토킹 당하고 있다는 사실을 대략적으로 말해 준다.)",
          DialogueId = 51009462,
          GUID = "7FB263DC"
        },
        [51009463] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "뭐? 그런 일이?! 정말 말도 안 되는 일이로군! 범인이 이 근처에 산다면, 찾아내서 혼꾸멍을 내 주겠어!",
          DialogueId = 51009463,
          GUID = "7FB26406",
          NextDialogue = 51009464,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700313:Angry01_Start"
          }
        },
        [51009464] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "그렇게까지 하실 필요는...",
          DialogueId = 51009464,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB26430",
          NextDialogue = 51009465,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          }
        },
        [51009465] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "그게 무슨 소리야? 사회 질서를 해치는 그런 몹쓸 녀석들은 절대 가만 못 둬. 안심해, 이 근처 주민들은 내가 웬만큼 다 아니까, 단서만 있으면 범인을 찾을 수 있어.",
          DialogueId = 51009465,
          GUID = "7FB2645A",
          NextDialogue = 51009466,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "100001:ScratchHead_End",
            [2] = "700313:Confident_Start"
          }
        },
        [51009466] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "단서라면... 이 편지, 뭔가 짚이는 거 없으세요?",
