        [51009471] = {
          Camera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "스토커...라고? 그럴 리가? 글솜씨는 서툴러도 진심이 느껴지는 게, 그런 불순한 녀석들하곤 차원이 다른걸.",
          DialogueId = 51009471,
          GUID = "7FB26556",
          NextDialogue = 51009472,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Talk01_Start"
          }
        },
        [51009472] = {
          Camera = "224.37207,502.975342,173.965332,0.000078,-3.594175,-121.197639,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "누가 쓴 건지는 이미 알겠네요. 아까는 범인을 따끔하게 혼내 주신다면서요?",
          DialogueId = 51009472,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB26580",
          NextDialogue = 51009473,
          SpeakNpcId = 100001
        },
        [51009473] = {
          Camera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "오해야, 분명 오해라고! 맹세컨대 비올레타 님을 향한 내 진심은... 아니지, 비올레타 님은 열정적인 고백을 가장 좋아한다고 하셨는데? 그런 분이 이걸 스토킹이라고 하셨을 리가 없어!",
          DialogueId = 51009473,
          GUID = "7FB265AA",
          NextDialogue = 51009474,
          SpeakNpcId = 700313
        },
        [51009474] = {
          ContentKR = "...설마 <H>그 녀석이 날 속인 건가</>...?",
          DialogueId = 51009474,
          GUID = "7FB265D4",
          NextDialogue = 51009475,
          SpeakNpcId = 700313
        },
        [51009475] = {
          ContentKR = "잠깐, 이제 알겠다! 너구나! 넌 비올레타 님이 보낸 사람이 아니라, 우리 사이를 갈라놓으려고 하는 거야!",
          DialogueId = 51009475,
          GUID = "7FB265FE",
          NextDialogue = 51009476,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Angry01_Start"
          }
        },
        [51009476] = {
          ContentKR = "널 보낸 게 비올레타 님이란 증거라도 있어? 넌 그냥 나하고 그분 사이를 이간질하려는 거잖아!",
          DialogueId = 51009476,
          GUID = "7FB26628",
          NextDialogue = 51009477,
          SpeakNpcId = 700313
        },
        [51009477] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "감히 이 따위 수작으로 비올레타 님과 추종자들 사이의 믿음을 깨뜨리려고 하다니, 버르장머리를 아주 단단히 고쳐 줘야겠군!",
          DialogueId = 51009477,
          GUID = "7FB26652",
          NextDialogue = 51009478,
          SpeakNpcId = 700313
        },
        [51009478] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "저한테 왜 이러세요...",
          DialogueId = 51009478,
          GUID = "7FB2667C",
          NextDialogue = 51009479,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_End"
          }
        },
        [51009479] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "(일단 이 막무가내인 녀석을 어떻게든 진정시켜야겠어.)",
          DialogueId = 51009479,
          GUID = "7FB266A6",
          SpeakNpcId = 100001
        },
        [51009480] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "비올레타 님, 제가... 조금 더 강했더라면...",
          DialogueId = 51009480,
          GUID = "7FB266D0",
          NextDialogue = 51009481,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Stop01_Start"
