          GUID = "7FB2674E",
          NextDialogue = 51009484,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Disagree"
          }
        },
        [51009484] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "이걸 어떻게 못 알아보겠어! 하긴 너한테 이런 얘길 해 봐야 무슨 소용이겠냐만...",
          DialogueId = 51009484,
          GUID = "7FB26778",
          NextDialogue = 51009485,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Shock_End"
          }
        },
        [51009485] = {
          ContentKR = "네가 이걸 가지고 있다는 건, 내 마음이 확실히 거절당했단 거겠지. 앞으로 다시는 비올레타 님께 폐 끼치는 일 없을 거야. 그분과 행복하길 기원할게.",
          DialogueId = 51009485,
          GUID = "7FB267A2",
          NextOptions = {
            [1] = 510093951,
            [2] = 510093952
          },
          SpeakNpcId = 700313
        },
        [51009486] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "알아들었다니까. 이 불타는 심장에 흐르는 쓸쓸한 눈물을 이해해 달라고!",
          DialogueId = 51009486,
          GUID = "7FB267CC",
          NextDialogue = 51009487,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Stop01_Start"
          }
        },
        [51009487] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "(경비병은 더 이상 대답하지 않고 눈물만 흘린다... 혼자 조용히 있게 내버려두자.)",
          DialogueId = 51009487,
          FacialId = {
            [1] = "100001:None"
          },
