        },
        [51009723] = {
          Camera = "-1245.721924,-374.627869,402.247803,-8.001631,-17.80077,20.798534,23.337744,100000.0,true,DoNotOverride,2.8",
          ContentKR = "잠 못 이루네... 잠 못 이루네!",
