          ToFinalCameraBlendTime = 3
        },
        [51009724] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,true,DoNotOverride,2.8",
          ContentKR = "가엾은 이여, 그대도 나와 같나요? 차가운 복도에서, 사랑과 희망으로 빛나는 저 별을 애타게 바라보나요...",
          DialogueId = 51009724,
          GUID = "7FB28ED8",
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009725] = {
          ContentKR = "(길모퉁이에서 노랫소리가 들려오는데, 둘러봐도 노래하는 사람은 보이지 않는다. 주변을 좀 더 살펴볼까?)",
          DialogueId = 51009725,
          GUID = "7FB28F02"
        },
        [51009726] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,true,DoNotOverride,2.8",
          ContentKR = "끽... 끽끽...",
          DialogueId = 51009726,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB28F2C",
          NextDialogue = 51009727,
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          }
        },
        [51009727] = {
          ContentKR = "뭐야? 거기 누구 있어?",
          DialogueId = 51009727,
          GUID = "7FB28F56",
          NextDialogue = 51009728,
          SpeakNpcId = 100001
        },
        [51009728] = {
          ContentKR = "어머, 미안해요. 저 때문에 놀랐군요? 전 여기 있어요. 앞으로 다섯 걸음만 더요. 그래요, 바로 여기예요.",
          DialogueId = 51009728,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB28F80",
          NextDialogue = 51009729,
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "100001:Shock_End"
          }
        },
        [51009729] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          ContentKR = "좋은 밤이에요, 잠 못 이루는 친구.",
          DialogueId = 51009729,
          GUID = "7FB28FAA",
          NextOptions = {
            [1] = 510096391,
            [2] = 510096392,
            [3] = 510096393
          },
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{"NvzhuPoint_20023201"}},
TurnTo{TurnToDescription{"100001:n(700309)"}}
}]],
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009730] = {
          ContentKR = "착각 아니에요. 당신은 지금 저하고 대화를 나누고 있답니다.",
          DialogueId = 51009730,
          GUID = "7FB28FD4",
          NextDialogue = 51009733,
          SpeakNpcId = 700309
        },
        [51009731] = {
          ContentKR = "왜 누가 꼭 숨어 있어야 하나요? 그냥 말하는 상자일 수도 있잖아요?",
          DialogueId = 51009731,
          GUID = "7FB28FFE",
          NextDialogue = 51009733,
          SpeakNpcId = 700309
        },
        [51009732] = {
          ContentKR = "미안하지만, 전 평범한 상자라 그런 힘은 없어요.",
          DialogueId = 51009732,
          GUID = "7FB29028",
          NextDialogue = 51009733,
          SpeakNpcId = 700309
        },
        [51009733] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "그런데 상자가 어떻게 말을 하는 거야?",
          DialogueId = 51009733,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29052",
          NextDialogue = 51009734,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009734] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          ContentKR = "그거라면... 상자가 노래하는 게 어려울 것 같아요? 아니면 말하는 게 더 어려울 것 같아요?",
          DialogueId = 51009734,
          GUID = "7FB2907C",
          NextDialogue = 51009735,
          SpeakNpcId = 700309
        },
        [51009735] = {
          ContentKR = "노래하는 거.",
          DialogueId = 51009735,
          GUID = "7FB290A6",
          NextDialogue = 51009736,
          SpeakNpcId = 100001
        },
        [51009736] = {
          ContentKR = "하지만 노래하는 상자는 이미 있잖아요. 태엽만 몇 번 감아주면 노래가 나오는걸요. 말하는 건 노래보다 훨씬 쉽고, 게다가 전 오르골보다 더 크고 대단하니까...",
          DialogueId = 51009736,
          GUID = "7FB290D0",
          NextDialogue = 51009737,
          SpeakNpcId = 700309
        },
        [51009737] = {
          ContentKR = "제가 당신하고 이렇게 대화를 나눌 수 있는 거죠. 당신이 지금 저하고 이야기를 나누고 있는 것처럼요.",
          DialogueId = 51009737,
          GUID = "7FB290FA",
          NextDialogue = 51009738,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009738] = {
          ContentKR = "그래도...",
          DialogueId = 51009738,
          GUID = "7FB29124",
          NextDialogue = 51009739,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009739] = {
          ContentKR = "알아요, 의심스러운 거.",
          DialogueId = 51009739,
          GUID = "7FB2914E",
          NextDialogue = 51009740,
          SpeakNpcId = 700309
        },
        [51009740] = {
          ContentKR = "옹이구멍처럼 메아리나 울려 퍼지면 모를까, 상자가 말할 리 없다고 생각하는 거죠. 그렇지만 솔직히 말해서, 말하는 상자를 마다할 사람이 있나요?",
          DialogueId = 51009740,
          GUID = "7FB29178",
          NextDialogue = 51009741,
          SpeakNpcId = 700309
        },
        [51009741] = {
          ContentKR = "당신이 바로 절 열어 보지 않은 것도, 내심 상자가 말을 걸어 줬으면 하는 마음이 있어서 아닐까요?",
          DialogueId = 51009741,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB291A2",
          NextDialogue = 51009742,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Explain01_End"
          }
        },
        [51009742] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "......",
          DialogueId = 51009742,
          GUID = "7FB291CC",
          NextDialogue = 51009743,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009743] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          ContentKR = "제 설명을 납득하신 것 같네요. 그러면 같이 이야기 좀 나눠주실래요?",
          DialogueId = 51009743,
          GUID = "7FB291F6",
          NextDialogue = 51009744,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009744] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "무슨 얘기를 하고 싶은데?",
          DialogueId = 51009744,
          FacialId = {
            [1] = "100001:Uninterested01"
          },
          GUID = "7FB29220",
          NextDialogue = 51009745,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009745] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          ContentKR = "음, 어디 보자... 이틀 전에 아이스레이크 시티 오페라 극장에서 했던 공연 얘기는 어때요?",
          DialogueId = 51009745,
          GUID = "7FB2924A",
          NextDialogue = 51009746,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009746] = {
          ContentKR = "<푸치니>라는 공연인데, 혹시 보셨나요? 여자 주인공은 노래를 잘하던가요?",
          DialogueId = 51009746,
          GUID = "7FB29274",
          NextDialogue = 51009747,
          SpeakNpcId = 700309
        },
        [51009747] = {
          ContentKR = "아시다시피 전 상자라서, 극장에 공연을 보러 갈 수가 없거든요.",
          DialogueId = 51009747,
          GUID = "7FB2929E",
          NextDialogue = 51009748,
          SpeakNpcId = 700309
        },
        [51009748] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "미안, 본 적 없어.",
          DialogueId = 51009748,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB292C8",
          NextDialogue = 51009749,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          }
        },
        [51009749] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          ContentKR = "괜찮아요. 비난하는 게 아니라요, 나중에 기회가 되면 한번 보세요. 아주 좋은 공연이거든요. 푸치니라는 주인공은 아름답고, 선하고... 자유를 좇는 용기도 지녔어요.",
          DialogueId = 51009749,
          GUID = "7FB292F2",
          NextDialogue = 51009750,
          SpeakNpcId = 700309
        },
        [51009750] = {
          ContentKR = "저도 그런 사람이 되고 싶지만, 전 일개 나무 상자일 뿐이죠.",
          DialogueId = 51009750,
          GUID = "7FB2931C",
          NextDialogue = 51009751,
          SpeakNpcId = 700309
        },
        [51009751] = {
          ContentKR = "그래서 전 결심했답니다.",
          DialogueId = 51009751,
          GUID = "7FB29346",
          NextDialogue = 51009752,
          SpeakNpcId = 700309
        },
        [51009752] = {
          ContentKR = "어떤 결심을 했는데?",
          DialogueId = 51009752,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29370",
          NextDialogue = 51009753,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009753] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,true,DoNotOverride,2.8",
          ContentKR = "먼바다로 떠나고 싶어요. 상자라고 해서 길모퉁이에 쌓여 있어야만 하는 건 아니잖아요. 배가 돼서 해류를 따라 정처 없이 떠돌 수도 있어요... 전 바닷물을 느끼고 싶어요. 모래알이 섞인 바람도요.",
          DialogueId = 51009753,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2939A",
          NextDialogue = 51009754,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009754] = {
          ContentKR = "하지만 여길 떠난다는 건, 지금 제가 가진 모든 걸 잃는다는 뜻이기도 해요.",
          DialogueId = 51009754,
          GUID = "7FB293C4",
          NextDialogue = 51009755,
          SpeakNpcId = 700309
        },
        [51009755] = {
          ContentKR = "새장 밖으로 나간다는 건, 보금자리를 잃는다는 의미예요. 자유를 얻는다는 건, 알 수 없는 위험을 감수해야 한다는 거고요.",
          DialogueId = 51009755,
          GUID = "7FB293EE",
          NextDialogue = 51009756,
          SpeakNpcId = 700309
        },
        [51009756] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          ContentKR = "친구로서 조언해 주세요. 전 어떻게 해야 할까요?",
          DialogueId = 51009756,
          GUID = "7FB29418",
          NextOptions = {
            [1] = 510096661,
            [2] = 510096662
          },
          SpeakNpcId = 700309
        },
        [51009757] = {
          ContentKR = "...그건 그렇네요.",
          DialogueId = 51009757,
          GUID = "7FB29442",
          NextDialogue = 51009758,
          SpeakNpcId = 700309
        },
        [51009758] = {
          ContentKR = "상자의 이야기에 어울려 줘서 고마워요. 이제 곧 날이 밝을 거예요. 이 낡은 나무의 마법도 사라져 버리겠죠.",
          DialogueId = 51009758,
          GUID = "7FB2946C",
          NextDialogue = 51009759,
          SpeakNpcId = 700309
        },
        [51009759] = {
          ContentKR = "앞으로 잠 못 드는 밤마다... 아니, 매일 밤 달콤한 꿈을 꾸시길 바랄게요.",
          DialogueId = 51009759,
          GUID = "7FB29496",
          SpeakNpcId = 700309
        },
        [51009760] = {
          ContentKR = "(상자 뒤에 숨었던 작은 요정이 동트기 전에 아이의 머리맡을 몰래 빠져나가는 것처럼, 미약한 진동이 느껴졌다.\n정신을 차리자, 상자 아가씨는 이미 떠나고 없었다.)",
          DialogueId = 51009760,
          GUID = "7FB294C0"
        },
        [51009761] = {
          Camera = "181.495728,-78.722099,88.629395,0.000093,-3.999294,136.804047,30.022871,100000.0,true,DoNotOverride,2.8",
          ContentKR = "(상자 속에서 났던 그 목소리... 나도 모르게 그 페이스에 말려들고 말았어.)",
          DialogueId = 51009761,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB294EA",
          NextDialogue = 51009762,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009762] = {
          Camera = "-5654.617676,-3244.824707,4837.760742,0.000161,-38.599369,19.822903,27.283031,100000.0,true,DoNotOverride,2.8",
          ContentKR = "(어떤 집 꼬마가 장난치는 걸지도 모르니까, 그냥 내버려둘 순 없어. 주변 사람들한테 물어봐야겠다.)",
          DialogueId = 51009762,
          GUID = "7FB29514",
          SpeakNpcId = 100001
        },
        [51009763] = {
          ContentKR = "실례지만... 누구지? 아까부터 계속 우리 집 근처를 어슬렁거리던데.",
          DialogueId = 51009763,
          GUID = "7FB2953E",
          NextDialogue = 51009764,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009764] = {
          ContentKR = "의뢰할 거라도 있어? 사람 찾기? 재료 수집? 다른 의뢰라고 안 받는 건 아니지만, 합법적인 거라야 해.",
          DialogueId = 51009764,
          GUID = "7FB29568",
          NextDialogue = 51009765,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009765] = {
          ContentKR = "의뢰요?",
          DialogueId = 51009765,
          GUID = "7FB29592",
          NextDialogue = 51009766,
          SpeakNpcId = 100001
        },
        [51009766] = {
          ContentKR = "응? 의뢰하러 온 게 아니었어?",
          DialogueId = 51009766,
          GUID = "7FB295BC",
          NextDialogue = 51009767,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009767] = {
          ContentKR = "흠, '월석 사냥꾼 지젤'이라는 이름이 카밀라 말처럼 유명하지는 않은 모양이군.",
          DialogueId = 51009767,
          GUID = "7FB295E6",
          NextDialogue = 51009768,
          SpeakNpcId = 700302
        },
        [51009768] = {
          ContentKR = "월석 사냥꾼 지젤... 그러고 보니 들어본 것 같기도 해요.",
          DialogueId = 51009768,
          GUID = "7FB29610",
          NextDialogue = 51009769,
          SpeakNpcId = 100001
        },
        [51009769] = {
          ContentKR = "내 기분 맞춰 주려고 굳이 그렇게 말할 필요 없어.",
          DialogueId = 51009769,
          GUID = "7FB2963A",
          NextDialogue = 51009770,
          SpeakNpcId = 700302
        },
        [51009770] = {
          ContentKR = "그게 아니라요... 사실은...",
          DialogueId = 51009770,
          GUID = "7FB29664",
          NextDialogue = 51009771,
          SpeakNpcId = 100001
        },
        [51009771] = {
          ContentKR = "(지젤에게 그녀의 집 뒤편에 있던 상자에 대해 설명해 준다.)",
          DialogueId = 51009771,
          GUID = "7FB2968E",
          NextDialogue = 51009772
        },
        [51009772] = {
          ContentKR = "네 말은, 우리 집 뒤에 있던 나무 상자가 말을 걸더니, 오페라를 보라고 추천했다는 거야? 음, 알겠어.",
          DialogueId = 51009772,
          GUID = "7FB296B8",
          NextDialogue = 51009773,
          SpeakNpcId = 700302
        },
        [51009773] = {
          ContentKR = "......",
          DialogueId = 51009773,
          GUID = "7FB296E2",
          NextDialogue = 51009774,
          SpeakNpcId = 100001
        },
        [51009774] = {
          ContentKR = "제가 생각했던 거랑 반응이 좀 다르시네요?",
          DialogueId = 51009774,
          GUID = "7FB2970C",
          NextDialogue = 51009775,
          SpeakNpcId = 100001
        },
        [51009775] = {
          ContentKR = "그런가? 내 성격이 원래 좀 이래. 꼬마가 장난으로 상자에 숨어서 말을 걸었든, 아니면 정말 상자가 말을 했든, 난 다 가능하다고 생각하거든.",
          DialogueId = 51009775,
          GUID = "7FB29736",
          NextDialogue = 51009776,
          SpeakNpcId = 700302
        },
        [51009776] = {
          ContentKR = "알려줘서 고마워. 이 근처 사람들한테 한번 물어볼게.",
          DialogueId = 51009776,
          GUID = "7FB29760",
          NextDialogue = 51009777,
          SpeakNpcId = 700302
        },
        [51009777] = {
          ContentKR = "아, 맞다. 생각났어. 너 {nickname} 맞지? 요즘 월석 사냥꾼들 사이에서 아주 평판 좋은 신입이잖아.",
          DialogueId = 51009777,
          GUID = "7FB2978A",
          NextOptions = {
            [1] = 510096871,
            [2] = 510096872,
            [3] = 510096873
          },
          SpeakNpcId = 700302
        },
        [51009778] = {
          ContentKR = "역시 너였구나. 내 눈썰미도 아직 쓸 만하네.",
          DialogueId = 51009778,
          GUID = "7FB297B4",
          NextDialogue = 51009781,
          SpeakNpcId = 700302
        },
        [51009779] = {
          ContentKR = "그렇게 경계할 거 없어. 너처럼 능력 있는 신인은 금방 소문이 나기 마련이거든.",
          DialogueId = 51009779,
          GUID = "7FB297DE",
          NextDialogue = 51009781,
          SpeakNpcId = 700302
        },
        [51009780] = {
          ContentKR = "너 취향이 좀 별로구나... 한 번 들으면 절대 안 잊을 별명이긴 하지만.",
          DialogueId = 51009780,
          GUID = "7FB29808",
          NextDialogue = 51009781,
          SpeakNpcId = 700302
        },
        [51009781] = {
          ContentKR = "별로 안 바빠 보이는데, 나 좀 도와주지 않을래?",
          DialogueId = 51009781,
          GUID = "7FB29832",
          NextDialogue = 51009782,
          SpeakNpcId = 700302
        },
        [51009782] = {
          ContentKR = "약초 좀 구해다 줘. 종류랑 수량은 목록을 만들어 줄게. 보수는 카밀라한테 미리 맡겨 둘 테니까, 다 모으면 아스포델으로 가져다주면 돼.",
          DialogueId = 51009782,
          GUID = "7FB2985C",
          NextDialogue = 51009783,
          SpeakNpcId = 700302
        },
        [51009783] = {
          ContentKR = "여기가 아니라요?",
          DialogueId = 51009783,
          GUID = "7FB29886",
          NextDialogue = 51009784,
          SpeakNpcId = 100001
        },
        [51009784] = {
          ContentKR = "응, 아스포델에 두면 돼.",
          DialogueId = 51009784,
          GUID = "7FB298B0",
          SpeakNpcId = 700302
        },
        [51009785] = {
          Camera = "777.87793,290.900391,409.416016,0.000004,-23.199877,-161.79744,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "(이 정도면 충분하겠지.)",
          DialogueId = 51009785,
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "7FB298DA",
          NextDialogue = 51009786,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51009786] = {
          Camera = "104.59375,60.244141,114.90918,0.000007,-13.199702,-164.194138,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "(이 약초들... 딱히 희귀 품종도 아닌데, 지젤 씨도 월석 사냥꾼이면서 왜 나한테 부탁한 걸까?)",
          DialogueId = 51009786,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29904",
          NextDialogue = 51009787,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009787] = {
          ContentKR = "(지금 생각해 보니까, 태도도 조금 이상했어...)",
          DialogueId = 51009787,
          GUID = "7FB2992E",
          NextDialogue = 51009788,
          SpeakNpcId = 100001
        },
        [51009788] = {
          ContentKR = "(일단 이 약초들을 아스포델에 가져가자. 간 김에 카밀라 씨한테 한번 물어봐야지.)",
          DialogueId = 51009788,
          GUID = "7FB29958",
          SpeakNpcId = 100001
        },
        [51009789] = {
          Camera = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "안녕, 오늘은 한잔하러 왔어? 아니면 의뢰 들어온 게 있나 보러 온 거야?",
          DialogueId = 51009789,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "7FB29982",
          NextDialogue = 51009790,
          SpeakNpcId = 200003
        },
        [51009790] = {
          ContentKR = "물건 전해드리러 온 거예요. 지젤 씨가 맡긴 의뢰인데, 아스포델에 가져다주면 된다고 했거든요.",
          DialogueId = 51009790,
          GUID = "7FB299AC",
          NextDialogue = 51009791,
          SpeakNpcId = 100001
        },
        [51009791] = {
          ContentKR = "지젤이? 아까 들러서 너 오면 전해 주라고 소포를 맡겨 놓긴 했어. 그런데 뭔가 이상한걸... 의뢰 내용은 뭐였어?",
          DialogueId = 51009791,
          GUID = "7FB299D6",
          NextDialogue = 51009792,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51009792] = {
          ContentKR = "(카밀라 씨에게 지젤 씨가 자기 대신 약초를 채집해 달라고 의뢰했다고 설명했다.)",
          DialogueId = 51009792,
          GUID = "7FB29A00",
          NextDialogue = 51009793
        },
        [51009793] = {
          ContentKR = "......",
          DialogueId = 51009793,
          GUID = "7FB29A2A",
          NextDialogue = 51009794,
          SpeakNpcId = 200003
        },
        [51009794] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "뭔가 잘못됐나요?",
          DialogueId = 51009794,
          GUID = "7FB29A54",
          NextDialogue = 51009795,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009795] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "의뢰 자체는 별거 없는데, 어째서 그런 의뢰를 했을까?",
          DialogueId = 51009795,
          GUID = "7FB29A7E",
          NextDialogue = 51009796,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51009796] = {
          ContentKR = "전부 다 감기 걸렸을 때 쓰는 흔한 약초들이라, 자기가 직접 하면 반나절도 안 걸릴 거야. 굳이 다른 사람한테 부탁할 이유가 없지.",
          DialogueId = 51009796,
          GUID = "7FB29AA8",
          NextDialogue = 51009797,
          SpeakNpcId = 200003
        },
        [51009797] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "그러고 보니까 자기가 월석 사냥꾼이라고 했었어요.",
          DialogueId = 51009797,
          GUID = "7FB29AD2",
          NextDialogue = 51009798,
          SpeakNpcId = 100001
        },
        [51009798] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "맞아. 예전엔 방위대 장교였는데, 16년 전에 어떤 사건 때문에 상부랑 마찰이 생겨서, 방위대를 나와 월석 사냥꾼이 됐거든. 머리 회전도 빠르고 실력도 괜찮아서, 이쪽에선 꽤 유명해.",
          DialogueId = 51009798,
          GUID = "7FB29AFC",
          NextDialogue = 51009799,
          SpeakNpcId = 200003
        },
        [51009799] = {
          ContentKR = "됐다, 이 얘긴 그만하자. 의뢰에 문제가 있는 것도 아니고, 지젤이 미리 말도 해 뒀는데 내가 이러쿵저러쿵할 일은 아니지.",
          DialogueId = 51009799,
          FacialId = {
            [1] = "200003:None"
          },
          GUID = "7FB29B26",
          NextDialogue = 51009800,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk03_End"
          }
        },
        [51009800] = {
          ContentKR = "너한테 이걸 전해 달라고 하더라, 받아.",
          DialogueId = 51009800,
          GUID = "7FB29B50",
          NextDialogue = 51009801,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Give"
          }
        },
        [51009801] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "이건... 의뢰 보수랑, 편지네요?",
          DialogueId = 51009801,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29B7A",
          SpeakNpcId = 100001
        },
        [51009802] = {
          ContentKR = "안녕, 친구.\n엉뚱한 상자의 말벗이 되어 밤늦게까지 함께해 줘서 고마워요. 그리고 제가 여행을 떠날 수 있게 용기를 준 것도요.\n친구들과 선생님껜 미안하지만, 다들 제 선택을 이해해 주실 거예요. 세상은 넓고, 다른 무대에서 모두와 다시 만나면 되는 거니까요.\n그리고, 이건 제 의지니까 지젤을 탓하진 말아 주세요. 제 멋대로 군 건 전데, 다른 사람이 피해를 입진 않았으면 해요.\n아, 그러고 보니까 아직 제 이름을 말해 주지 않았네요.\n하지만 그 이름은 이제 쓰지 않을 거니까, 그러면...\n혹시 나중에 푸치니라는 소녀를 만나게 된다면, 그게 저란 걸 알아봐 주세요. 저도 꼭 당신을 알아볼게요.",
          DialogueId = 51009802,
          Duration = 10,
          GUID = "7FB29BA4"
        },
        [51009803] = {
          Camera = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "희한한 친구를 사귀었구나. 재미있는 이야깃거리가 되겠는걸.",
          DialogueId = 51009803,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "7FB29BCE",
          NextDialogue = 51009804,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk02_Start"
          }
        },
        [51009804] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "아뇨... 사실은 저도 뭐가 어떻게 된 건지 잘 모르겠어요.",
          DialogueId = 51009804,
          FacialId = {
            [1] = "100001:None"
