        [51009814] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "그냥 소문이 그렇다는 거야. 두 사건을 연결할 직접적인 증거는 없으니까.",
