          DialogueId = 51009820,
          GUID = "7FB29E98",
          NextDialogue = 51009821,
          SpeakNpcId = 700307
        },
        [51009821] = {
          ContentKR = "로잘린이 하루 종일 밖에 나돌아 다닐 생각을 못 하게 뭐라도 시키라고 했던 건 당신이잖아요!",
          DialogueId = 51009821,
          FacialId = {
            [1] = "700308:CM_Sad01"
