        [51010012] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,true,DoNotOverride,2.8",
          ContentKR = "좋은 아침이에요, 비올레타 씨.",
          DialogueId = 51010012,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2BE18",
          NextDialogue = 51010013,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51010013] = {
          ContentKR = "왔구나. 자, 여기 티켓이야.",
          DialogueId = 51010013,
          GUID = "7FB2BE42",
          NextDialogue = 51010014,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Give",
            [2] = "100001:Talk02_End"
          }
        },
        [51010014] = {
          ContentKR = "잘 받을게.",
          DialogueId = 51010014,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2BE6C",
          NextDialogue = 51010015,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010015] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,true,Manual,2.8",
          ContentKR = "얼마든지요. 온 세상에 <푸치니>를 알리는 건 바이올렛이 남긴 소원인걸요. 표 두 장 정도는 바이올렛도 이해해 줄 거예요.",
          DialogueId = 51010015,
          GUID = "7FB2BE96",
          NextDialogue = 51010016,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51010016] = {
          ContentKR = "다만...",
          DialogueId = 51010016,
          GUID = "7FB2BEC0",
          NextDialogue = 51010017,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010017] = {
          ContentKR = "로잘린 양 때문에 그러세요?",
          DialogueId = 51010017,
          GUID = "7FB2BEEA",
          NextDialogue = 51010018,
          SpeakNpcId = 100001
        },
        [51010018] = {
          ContentKR = "맞아. 그 아이를 위한 송별 공연이라고는 했지만, 난 아직 그 아이가 아이스레이크 시티에 있는지, 자기가 제일 좋아하던 이 공연을 볼 수 있는지 모르니까.",
          DialogueId = 51010018,
          GUID = "7FB2BF14",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700300:n(700302)"
          },
          NextDialogue = 51010019,
          SpeakNpcId = 700300
        },
        [51010019] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001564,38.587292,100000.0,true,DoNotOverride,2.8",
          ContentKR = "나 보지 마. 걔가 다시 부모한테 잡혀가지 않도록, 나한테도 행방은 알리지 말라고 했으니까.",
          DialogueId = 51010019,
          FacialId = {
            [1] = "700302:CM_Shock01"
          },
          GUID = "7FB2BF3E",
          NextOptions = {
            [1] = 510099291,
            [2] = 510099292
          },
          SpeakNpcId = 700302
        },
        [51010020] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,true,Manual,2.8",
          ContentKR = "그랬으면 좋겠네... 참, {nickname}.",
          DialogueId = 51010020,
          FacialId = {
            [1] = "700302:CM_Idle",
            [2] = "700300:CM_Smile01"
          },
          GUID = "7FB2BF68",
          SpeakNpcId = 700300
        },
        [51010021] = {
          ContentKR = "이번 일로 네 지혜와 행동력에 정말 감탄했어. 전혀 관계없어 보이는 세 가지 사건을 하나로 엮어, 모두가 행복한 결말을 만들어냈잖아.",
          DialogueId = 51010021,
          GUID = "7FB2BF92",
          NextDialogue = 51010022,
          SpeakNpcId = 700300
        },
        [51010022] = {
          ContentKR = "그래서 말인데, 맡기고 싶은 중요한 의뢰가 하나 더 있어. 내 다른 학생과 관련된 일인데, 보수는 걱정 말고, 시간 될 때 극장으로 날 찾아와줘.",
          DialogueId = 51010022,
          GUID = "7FB2BFBC",
          NextDialogue = 51010023,
          SpeakNpcId = 700300
        },
        [51010023] = {
          ContentKR = "하지만 급한 건 아니야. 오늘 밤은 노래와 머나먼 여정을 위한 밤이니까. 두 사람 모두 복잡한 일은 잊고 근사한 휴일을 즐기길 바랄게.",
          DialogueId = 51010023,
          GUID = "7FB2BFE6",
          SpeakNpcId = 700300
        },
        [51010024] = {
          ContentKR = "비올레타 씨가 마련해 준 좌석에 앉아, 공연이 시작되기를 기다린다.",
          DialogueId = 51010024,
          GUID = "7FB2C010",
          NextDialogue = 51010025
        },
        [51010025] = {
          ContentKR = "객석이 서서히 어둠에 잠기고, 한 여성의 힘찬 노랫소리가 기대와 호기심을 싣고 무대 막 뒤편부터 공연장 전체로 울려 퍼진다.",
          DialogueId = 51010025,
          GUID = "7FB2C03A",
          NextDialogue = 51010026
        },
        [51010026] = {
          ContentKR = "객석은 이상할 만큼 조용하고, 이런 분위기가 낯선 나는 왠지 마음이 살짝 불안해진다.",
          DialogueId = 51010026,
          GUID = "7FB2C064",
          NextDialogue = 51010027
        },
        [51010027] = {
          ContentKR = "멋진 장면이 나올 때마다 터져 나오는 감탄사를 삼키는 건 상당한 고역이다. 나도 모르게 튀어나온 소리가 다른 사람의 즐거움을 방해할까 봐 조마조마하다.",
          DialogueId = 51010027,
          GUID = "7FB2C08E",
          NextDialogue = 51010028
        }
      }
    end
  },
  {
    MinKey = 51010028,
    MaxKey = 51010507,
    Loader = function()
      return {
        [51010028] = {
          ContentKR = "하지만 그건 쓸데없는 걱정이었다. 오페라 속 인물들에게 완전히 몰입한 나는, 공연이 끝나는 순간까지 박수 치는 것도 잊고 말았으니까...",
          DialogueId = 51010028,
          GUID = "7FB2C0B8"
        },
        [51010029] = {
