          SpeakNpcId = 700302
        },
        [51010030] = {
          ContentKR = "사람들이 무대에 열광하는 이유를 이제야 조금 알 것 같아요.",
          DialogueId = 51010030,
          FacialId = {
            [1] = "100001:Smile01"
