}]],
          SpeakNpcId = 100001
        },
        [51010059] = {
          ContentKR = "그거, 선물이니까 받아 줘요!",
          DialogueId = 51010059,
          GUID = "7FB2C5CE",
          NextDialogue = 51010060,
