          SpeakNpcName = "UI_CMNpc_Name_Rosalind02"
        },
        [51010060] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "요즘 젊은 애들은 정말 에너지가 넘치네.",
          DialogueId = 51010060,
          GUID = "7FB2C5F8",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010061,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_End"
          }
        },
        [51010061] = {
          ContentKR = "저한테 주는 선물이라는데... 여기 뭔가 수놓아져 있어요. 아까 그 소녀 이름일까요?",
          DialogueId = 51010061,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2C622",
          NextDialogue = 51010062,
          SpeakNpcId = 100001
        },
        [51010062] = {
          ContentKR = "...푸치니?",
          DialogueId = 51010062,
          GUID = "7FB2C64C",
          NextDialogue = 51010063,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51010063] = {
          ContentKR = "나중에 푸치니라는 소녀를 만나게 된다면, 그게 저란 걸 알아봐 주세요. 저도 꼭 당신을 알아볼게요.",
          DialogueId = 51010063,
          GUID = "7FB2C676",
          IsBlack = 1,
          NextDialogue = 51010064
        },
        [51010064] = {
          ContentKR = "뭐야? 왜 웃어?",
          DialogueId = 51010064,
          FacialId = {
            [1] = "100001:Happy02"
          },
          GUID = "7FB2C6A0",
          NextDialogue = 51010065,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51010065] = {
          ContentKR = "지젤 씨도 못 알아봤다니, 천의 얼굴을 가진 게 비올레타 씨 하나만은 아닌 모양이에요.",
          DialogueId = 51010065,
          GUID = "7FB2C6CA",
          NextDialogue = 51010066,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010066] = {
          ContentKR = "인생은 1막짜리 연극이 아니니까, 우린 다른 무대에서 또 만나게 될 거야. 그때까지 즐거운 여행이 되길 바랄게, 상자 아가씨.",
          DialogueId = 51010066,
          GUID = "7FB2C6F4",
          IsBlack = 1,
          SpeakNpcId = 100001
        },
        [51010067] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,true,DoNotOverride,2.8",
          ContentKR = "......",
          DialogueId = 51010067,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "7FB2C71E",
          NextDialogue = 51010068,
          SpeakNpcId = 100001
        },
        [51010068] = {
          ContentKR = "좋은 아침이야, {nickname}. 그런데 표정이 왜 그렇게 어두워?",
          DialogueId = 51010068,
          GUID = "7FB2C748",
          NextDialogue = 51010069,
          SpeakNpcId = 700300
        },
        [51010069] = {
          ContentKR = "비올레타 씨...",
          DialogueId = 51010069,
          GUID = "7FB2C772",
          NextDialogue = 51010070,
          SpeakNpcId = 100001
        },
        [51010070] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,true,Manual,2.8",
          ContentKR = "괜찮으니까 거기까지만 해. 은퇴하는 건 난데, 오히려 네가 더 속상해하는 것 같네.",
          DialogueId = 51010070,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2C79C",
          NextDialogue = 51010071,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51010071] = {
          ContentKR = "넌 소신을 지키는 사람이라면 누구나 했을 법한 선택을 한 것뿐이야. 괜한 부담 갖지 말고, 집 나간 꼬마 하나 잡아냈다고 생각하면 돼, 알겠지?",
          DialogueId = 51010071,
          GUID = "7FB2C7C6",
          NextDialogue = 51010072,
          SpeakNpcId = 700300
        },
        [51010072] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,true,DoNotOverride,2.8",
          ContentKR = "다 모인 것 같네?",
          DialogueId = 51010072,
          GUID = "7FB2C7F0",
          NextDialogue = 51010073,
          Scripts = "MoveTo{ActorId{700302},TargetPoint{\"GisellePoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 700302
        },
        [51010073] = {
          ContentKR = "지젤 씨도 왔군요. 자, 두 사람 티켓이에요.",
          DialogueId = 51010073,
          GUID = "7FB2C81A",
          NextDialogue = 51010074,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51010074] = {
          ContentKR = "잘 받을게. 방위대 친구들한테는 이미 말해 뒀으니까, 공연이 끝날 때까진 아무 일 없을 거야.",
          DialogueId = 51010074,
          GUID = "7FB2C844",
          NextDialogue = 51010075,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010075] = {
          ContentKR = "정말 감사해요. 이제 곧 공연이 시작돼서, 먼저 실례할게요.",
          DialogueId = 51010075,
          GUID = "7FB2C86E",
          NextDialogue = 51010076,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010076] = {
          ContentKR = "우리도 들어가자. 내가 원인 제공을 한 셈이지만, 비올레타의 고별 무대라니까 확실히 기대되긴 하네.",
          DialogueId = 51010076,
          GUID = "7FB2C898",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010077,
          SpeakNpcId = 700302
        },
        [51010077] = {
          ContentKR = "네.",
          DialogueId = 51010077,
          GUID = "7FB2C8C2",
          SpeakNpcId = 100001
        },
        [51010078] = {
          ContentKR = "비올레타 씨가 마련해 준 좌석에 앉아, 공연이 시작되기를 기다린다.",
          DialogueId = 51010078,
          GUID = "7FB2C8EC",
          NextDialogue = 51010079
        },
        [51010079] = {
          ContentKR = "객석이 서서히 어둠에 잠기고, 한 여성의 힘찬 노랫소리가 기대와 호기심을 싣고 무대 막 뒤편부터 공연장 전체로 울려 퍼진다.",
          DialogueId = 51010079,
          GUID = "7FB2C916",
          NextDialogue = 51010080
        },
        [51010080] = {
          ContentKR = "객석은 이상할 만큼 조용하고, 이런 분위기가 낯선 나는 왠지 마음이 살짝 불안해진다.",
          DialogueId = 51010080,
          GUID = "7FB2C940",
          NextDialogue = 51010081
        },
        [51010081] = {
          ContentKR = "멋진 장면이 나올 때마다 터져 나오는 감탄사를 삼키는 건 상당한 고역이다. 나도 모르게 튀어나온 소리가 다른 사람의 즐거움을 방해할까 봐 조마조마하다.",
          DialogueId = 51010081,
          GUID = "7FB2C96A",
          NextDialogue = 51010082
        },
        [51010082] = {
          ContentKR = "하지만 그건 쓸데없는 걱정이었다...",
          DialogueId = 51010082,
          GUID = "7FB2C994",
          NextDialogue = 51010083
        },
        [51010083] = {
          ContentKR = "오페라 속 인물들에게 완전히 몰입한 나는, 공연이 끝나는 순간까지 박수 치는 것도 잊고 말았으니까...",
          DialogueId = 51010083,
          GUID = "7FB2C9BE"
        },
        [51010084] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "지젤, 어떻게 된 건지 설명해 보게!",
          DialogueId = 51010084,
          FacialId = {
            [1] = "700304:CM_Angry01"
          },
          GUID = "7FB2C9E8",
          NextDialogue = 51010085,
          SpeakNpcId = 700304,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700304:Angry01_Start"
          }
        },
        [51010085] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,true,DoNotOverride,2.8",
          ContentKR = "오호? 천하의 파브리스 나리께서 저 같은 사람한테 무슨 설명을 듣고 싶으신 걸까요?",
          DialogueId = 51010085,
          GUID = "7FB2CA12",
          NextDialogue = 51010086,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010086] = {
          ContentKR = "비올레타가 엘로라라고 신고한 게 자네잖나! 그런데 내가 사람들을 데리고 가 봤더니, 무대 뒤엔 개미 새끼 한 마리 없었네!",
          DialogueId = 51010086,
          GUID = "7FB2CA3C",
          NextDialogue = 51010087,
          SpeakNpcId = 700304
        },
        [51010087] = {
          ContentKR = "그 일이었군요... 직접 행차하실 줄 몰랐네요. 책임감이 어마어마하신걸요.",
          DialogueId = 51010087,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2CA66",
          NextDialogue = 51010088,
          SpeakNpcId = 700302
        },
        [51010088] = {
          ContentKR = "비아냥거리지 말게! 이건 명령일세. 어서 날 엘로라가 있는 곳으로 안내해!",
          DialogueId = 51010088,
          GUID = "7FB2CA90",
          NextDialogue = 51010089,
          SpeakNpcId = 700304
        },
        [51010089] = {
          ContentKR = "잊으셨나 본데, 전 이젠 방위대 소속이 아니에요. 그건 당신도 마찬가지고요. 전 평범한 시민으로서 방위대에 정보를 제공한 것뿐이에요.",
          DialogueId = 51010089,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2CABA",
          NextDialogue = 51010090,
          SpeakNpcId = 700302
        },
        [51010090] = {
          ContentKR = "그러니까 전 당신의 명령을 들을 이유가 없어요. 아, 차라리 '월석 사냥꾼 지젤'한테 정식으로 의뢰해 보시는 건 어때요?",
          DialogueId = 51010090,
          GUID = "7FB2CAE4",
          NextDialogue = 51010091,
          SpeakNpcId = 700302
        },
        [51010091] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "이게...! 까짓것, 좋아, 의뢰하지!",
          DialogueId = 51010091,
          GUID = "7FB2CB0E",
          NextDialogue = 51010092,
          SpeakNpcId = 700304,
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51010092] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,true,DoNotOverride,2.8",
          ContentKR = "네, 그 의뢰 거절할게요.",
          DialogueId = 51010092,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2CB38",
          NextDialogue = 51010093,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Talk01_Start"
          }
        },
        [51010093] = {
          ContentKR = "지금 날 우롱하는 건가?!",
          DialogueId = 51010093,
          GUID = "7FB2CB62",
          NextDialogue = 51010094,
          SpeakNpcId = 700304
        },
        [51010094] = {
          ContentKR = "전 지금 백작 영애를 납치했다는 혐의를 받고 있어서, 당분간은 월석 사냥꾼 일도 못 해요.",
          DialogueId = 51010094,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2CB8C",
          NextDialogue = 51010095,
          SpeakNpcId = 700302
        },
        [51010095] = {
          ContentKR = "그러니까, 애초에 제 조언대로 얌전히 협상만 하셨어도, 일이 이렇게까진 복잡해지진 않았을걸요.",
          DialogueId = 51010095,
          GUID = "7FB2CBB6",
          NextDialogue = 51010096,
          SpeakNpcId = 700302
        },
        [51010096] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "자네...! 내가 사람을 잘못 봐도 한참 잘못 봤군. 자네가 엘로라를 찾아낼 거라고 믿었다니.",
          DialogueId = 51010096,
          GUID = "7FB2CBE0",
          NextDialogue = 51010097,
          SpeakNpcId = 700304,
          TalkActionId = {
            [1] = "700302:Talk01_End"
          }
        },
        [51010097] = {
          ContentKR = "엘로라... 이 아비가 꼭 찾아내 주마... 자네! 앞으로 다시는 내 눈에 띄지 않는 게 좋을 걸세!",
          DialogueId = 51010097,
          GUID = "7FB2CC0A",
          NextDialogue = 51010098,
          SpeakNpcId = 700304
        },
        [51010098] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,true,DoNotOverride,2.8",
          ContentKR = "그렇다면 저야 환영이죠.",
          DialogueId = 51010098,
          GUID = "7FB2CC34",
          NextDialogue = 51010099,
          Scripts = "MoveTo{ActorId{700304},TargetPoint{\"FabricePoint_20023305\"},MoveSpeed{150},Visibility{\"Hide\"}}",
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010099] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,true,DoNotOverride,2.8",
          ContentKR = "지젤 씨, 괜찮아요?",
          DialogueId = 51010099,
          FinalCamera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,true,DoNotOverride,2.8",
