        [51010100] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "멀쩡해. 방위대에 있을 땐 아까처럼 쏘아붙일 기회가 없었는데, 속이 다 시원해.",
          DialogueId = 51010100,
          GUID = "7FB2CC88",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010101,
          SpeakNpcId = 700302
        },
        [51010101] = {
          ContentKR = "아까 그 사람은...",
          DialogueId = 51010101,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2CCB2",
          NextDialogue = 51010102,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010102] = {
          ContentKR = "파브리스 러스포드야, 비올레타의 친아버지. 16년 전이나 지금이나 참을성 없는 건 여전하네.",
          DialogueId = 51010102,
          GUID = "7FB2CCDC",
          NextDialogue = 51010103,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51010103] = {
          ContentKR = "비올레타 씨는요?",
          DialogueId = 51010103,
          GUID = "7FB2CD06",
          NextDialogue = 51010104,
          SpeakNpcId = 100001
        },
        [51010104] = {
          ContentKR = "도망쳤어. 파브리스가 사람들을 데리고 들이닥쳤을 땐 이미 개미 새끼 한 마리 없었다더라.",
          DialogueId = 51010104,
          GUID = "7FB2CD30",
          NextDialogue = 51010105,
          SpeakNpcId = 700302
        },
        [51010105] = {
