        [51010106] = {
          Camera = "-442.745117,136.447266,137.21167,0.000002,-3.200169,-35.40036,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "죄, 죄송해요! 앞을 못 봤어요! 혹시 다치신 덴 없으세요? 어디 불편한 덴 없으시고요?",
          DialogueId = 51010106,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2CD84",
          NextDialogue = 51010107,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02"
        },
        [51010107] = {
