          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          TalkActionId = {
            [1] = "700305:Think_Start"
          }
        },
        [51010109] = {
          Camera = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "내 얼굴에 뭐 묻었어?",
          DialogueId = 51010109,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "7FB2CE02",
          NextDialogue = 51010110,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51010110] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "아무것도 아니에요. 헤헤... 약초, 고마웠어요.",
          DialogueId = 51010110,
          FacialId = {
            [1] = "700305:CM_Happy01"
          },
          GUID = "7FB2CE2C",
          NextDialogue = 51010111,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          TalkActionId = {
            [1] = "700305:Think_End"
          }
        },
        [51010111] = {
          ContentKR = "약속 시간에 늦겠다!",
          DialogueId = 51010111,
          GUID = "7FB2CE56",
          NextDialogue = 51010112,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51010112] = {
          ContentKR = "앗, 죄송해요, 저 먼저 가 볼게요! ...잠깐만요, 지금 가요!",
          DialogueId = 51010112,
          GUID = "7FB2CE80",
          NextDialogue = 51010113,
          Scripts = "MoveTo{ActorId{700305},TargetPoint{\"RosalindPoint2_20023305\"},MoveSpeed{250},Visibility{\"Hide\"}}",
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02"
        },
        [51010113] = {
          ContentKR = "약초라니...? 잠깐, 이거 떨어뜨렸어!",
          DialogueId = 51010113,
          GUID = "7FB2CEAA",
          NextDialogue = 51010114,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_Start"
          }
        },
        [51010114] = {
          ContentKR = "그거, 선물이니까 받아 줘요!",
          DialogueId = 51010114,
          GUID = "7FB2CED4",
          NextDialogue = 51010115,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_End"
          }
        },
        [51010115] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "요즘 젊은 애들은 정말 에너지가 넘치네.",
          DialogueId = 51010115,
          GUID = "7FB2CEFE",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010116,
          SpeakNpcId = 700302
        },
        [51010116] = {
          ContentKR = "저한테 주는 선물이래요...",
          DialogueId = 51010116,
          FacialId = {
            [1] = "100001:Doubt01",
            [2] = "700302:CM_Idle"
          },
          GUID = "7FB2CF28",
          NextDialogue = 51010117,
          SpeakNpcId = 100001
        },
        [51010117] = {
          ContentKR = "용감한 나비가 고치를 벗고 하늘로 날갯짓하다, 마치 스토크 한 송이가 꽃밭에 스며들 듯 바람과 함께 자취를 감추는군요.",
          DialogueId = 51010117,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2CF52",
          NextDialogue = 51010118,
          Scripts = "MoveTo{ActorId{700311},TargetPoint{\"ViolettePoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51010118] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "한동안 다시 만나지 못할지도 몰라요... 그러니 그녀가 소중한 친구에게 남기는 이 작별 선물을 받아 주세요.",
          DialogueId = 51010118,
          GUID = "7FB2CF7C",
          LookAt = {
            [1] = "100001:n(700311)",
            [2] = "700302:n(700311)"
          },
          NextDialogue = 51010119,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51010119] = {
          Camera = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "작별 선물이라니... 여기 뭐가 수놓아져 있어요. 아까 그 소녀 이름일까요?",
          DialogueId = 51010119,
          GUID = "7FB2CFA6",
          NextDialogue = 51010120,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51010120] = {
          ContentKR = "...푸치니?",
          DialogueId = 51010120,
          GUID = "7FB2CFD0",
          NextDialogue = 51010121,
          SpeakNpcId = 100001
        },
        [51010121] = {
          ContentKR = "나중에 푸치니라는 소녀를 만나게 된다면, 그게 저란 걸 알아봐 주세요. 저도 꼭 당신을 알아볼게요.",
          DialogueId = 51010121,
          GUID = "7FB2CFFA",
          IsBlack = 1,
          NextDialogue = 51010122
        },
        [51010122] = {
          ContentKR = "그랬군요. 상자 아가씨는 무사히 여행을 시작한 모양이네요. 그렇다면 당신은...",
          DialogueId = 51010122,
          GUID = "7FB2D024",
          NextDialogue = 51010123,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51010123] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "쉿, 진실을 밝힌 건 인정해 줄게. 하지만 비밀을 지킬 줄 아는 아이가 더 사랑스러운 법이란다.",
          DialogueId = 51010123,
          GUID = "7FB2D04E",
          NextDialogue = 51010124,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700311:Disagree"
          }
        },
        [51010124] = {
          ContentKR = "이렇게 대놓고 정체를 밝히다니, 내가 또 귀찮게 하면 어떻게 하려고?",
          DialogueId = 51010124,
          GUID = "7FB2D078",
          NextDialogue = 51010125,
          SpeakNpcId = 700302
        },
        [51010125] = {
          ContentKR = "'비올레타'는 이제 무대에 서지 않겠지만, 난 당분간 여길 떠날 생각이 없어요. 내 학생과 관련된 일만큼은 외면할 수 없거든요. 당신이 날 또 고발하더라도 원망하지 않을게요.",
          DialogueId = 51010125,
          GUID = "7FB2D0A2",
          NextDialogue = 51010126,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51010126] = {
          ContentKR = "......",
          DialogueId = 51010126,
          GUID = "7FB2D0CC",
          NextDialogue = 51010127,
          SpeakNpcId = 700302
        },
        [51010127] = {
          ContentKR = "...모른 척 넘어가 줘서 고마워요.",
          DialogueId = 51010127,
          FacialId = {
            [1] = "700311:CM_Happy01"
          },
          GUID = "7FB2D0F6",
          NextDialogue = 51010128,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700311:Agree"
          }
        },
        [51010128] = {
          ContentKR = "그러면 이만 실례할게요. 두 사람 모두 근사한 휴일을 즐기길 바랄게요.",
          DialogueId = 51010128,
          GUID = "7FB2D120",
          NextDialogue = 51010129,
          Scripts = "MoveTo{ActorId{700311},TargetPoint{\"RosalindPoint2_20023305\"},MoveSpeed{150},Visibility{\"Hide\"}}",
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51010129] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,true,DoNotOverride,2.8",
          ContentKR = "하하, 내가 이럴 줄 알았어. 저런 여자가 순순히 잡혀 줄 리가 없지.",
          DialogueId = 51010129,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2D14A",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010130,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010130] = {
          ContentKR = "어쩐지 조금 즐거워 보이시네요?",
          DialogueId = 51010130,
          GUID = "7FB2D174",
          NextDialogue = 51010131,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010131] = {
          ContentKR = "그래? 솔직히 나도 많이 고민했어. 산 사람의 인생을 희생시키면서까지 죽은 사람의 결백을 밝히는 게 맞는 건가 싶어서...",
          DialogueId = 51010131,
          GUID = "7FB2D19E",
          NextDialogue = 51010132,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51010132] = {
          ContentKR = "너도 봤겠지만, 난 선택을 했지. 그게 바로 이 지젤이라는 사람의 고집이야.",
          DialogueId = 51010132,
          GUID = "7FB2D1C8",
          NextDialogue = 51010133,
          SpeakNpcId = 700302
        },
        [51010133] = {
          ContentKR = "하지만 두 가지 선택지에서 벗어났다는 사실에 마음이 놓이는 걸 보면, 16년 동안 나도 꽤 성장했다는 거겠지?",
          DialogueId = 51010133,
          FacialId = {
            [1] = "700302:CM_Sad01"
          },
          GUID = "7FB2D1F2",
          NextDialogue = 51010134,
          SpeakNpcId = 700302
        },
        [51010134] = {
          ContentKR = "16년 전의 내가 지금 같았다면, 아무도 죽지 않았을지 몰라.",
          DialogueId = 51010134,
          GUID = "7FB2D21C",
          NextDialogue = 51010135,
          SpeakNpcId = 700302
        },
        [51010135] = {
          ContentKR = "지젤 씨 잘못이 아니에요.",
          DialogueId = 51010135,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2D246",
          NextDialogue = 51010136,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Disagree"
          }
        },
        [51010136] = {
          ContentKR = "슬퍼하는 거 아니니까 걱정하지 마. 그냥 '월석 사냥꾼'을 그만두면 뭐로 먹고 살아야 하나 생각 중인 거니까.",
          DialogueId = 51010136,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2D270",
          NextDialogue = 51010137,
          SpeakNpcId = 700302
        },
        [51010137] = {
          ContentKR = "배우는 안 하려고. 비올레타의 공연을 보고 나니까, 농담으로라도 그런 소린 못 하겠더라고...",
          DialogueId = 51010137,
          GUID = "7FB2D29A",
          NextOptions = {
            [1] = 510100471,
            [2] = 510100472
          },
          SpeakNpcId = 700302
        },
        [51010138] = {
          ContentKR = "돈벌이가 꽤 쏠쏠할 것 같았거든.",
          DialogueId = 51010138,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2D2C4",
          NextDialogue = 51010140,
          SpeakNpcId = 700302
        },
        [51010139] = {
          ContentKR = "그만 놀려, 진짜 명탐정님.",
          DialogueId = 51010139,
          GUID = "7FB2D2EE",
          NextDialogue = 51010140,
          SpeakNpcId = 700302
        },
        [51010140] = {
          ContentKR = "그러면 앞으론 뭐 하실 거예요?",
          DialogueId = 51010140,
          GUID = "7FB2D318",
          NextDialogue = 51010141,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010141] = {
          ContentKR = "음... 글쎄. 어차피 시간은 많으니까, 천천히 생각해 보려고.",
          DialogueId = 51010141,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2D342",
          NextDialogue = 51010142,
          SpeakNpcId = 700302
        },
        [51010142] = {
          ContentKR = "세상이라는 무대는 넓잖아. 나한테 어울리는 배역 하나쯤은 찾을 수 있겠지.",
          DialogueId = 51010142,
          GUID = "7FB2D36C",
          SpeakNpcId = 700302
        },
        [51010143] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentKR = "잠깐만요!",
          DialogueId = 51010143,
          FacialId = {
            [1] = "700300:CM_Smile01",
            [2] = "700302:CM_Angry01",
            [3] = "100001:Angry01"
          },
          GUID = "7FB2AA92",
          NextDialogue = 51009894,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_Start"
          }
        },
        [51010201] = {
          ContentKR = "♪용광로가 여명을 불태워, 눈과 강철의 성채를 무너뜨리네...",
          DialogueId = 51010201,
          GUID = "7FB2DD1A",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/env/700342/7FB2DD1A"
        },
        [51010202] = {
          ContentKR = "♪용광로가 여명을 불태워, 눈과 강철의 성채를 무너뜨리네.\n톱니바퀴 목 놓아 노래하며, 샛별을 삼키고, 북방의 위대한 시대를 찬미하라——",
          DialogueId = 51010202,
          GUID = "7FB2DD44",
          NextDialogue = 51010203,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DD44"
        },
        [51010203] = {
          ContentKR = "음? 날 부른 거야...?",
          DialogueId = 51010203,
          GUID = "7FB2DD6E",
          LookAt = {
            [1] = "700342:n(0)"
          },
          NextOptions = {
            [1] = 510102031,
            [2] = 510102032
          },
          SpeakNpcId = 700342,
          TalkActionId = {
            [1] = "700342:Lilikou_Story_Playlyre_End"
          },
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DD6E"
        },
        [51010204] = {
          ContentKR = "고마워, 낯선 여행자님! 사실은 이 노래, 아직 미완성이야. 괜찮다면 같이 만들어 볼래?",
          DialogueId = 51010204,
          GUID = "7FB2DD98",
          NextDialogue = 51010206,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DD98"
        },
        [51010205] = {
          ContentKR = "방해가 됐다면 미안해! 그런데 저 병사분께 물어봤을 땐, 이 도시엔 광장에서 음유시인이 노래하면 안 된다는 법은 없다고 했어.",
          DialogueId = 51010205,
          GUID = "7FB2DDC2",
          NextDialogue = 51010206,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DDC2"
        },
        [51010206] = {
          ContentKR = "다음 구절은 뭐가 좋을까...",
          DialogueId = 51010206,
          GUID = "7FB2DDEC",
          NextDialogue = 51010207,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DDEC"
        },
        [51010207] = {
          ContentKR = "'바람'에 대해 써야 할 것 같아... 바람은 장소에 따라 다 다른 느낌을 주거든...",
          DialogueId = 51010207,
          GUID = "7FB2DE16",
          NextDialogue = 51010208,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE16"
        },
        [51010208] = {
          ContentKR = "엘리시아의 바람엔 저녁 기도의 우유 향이 녹아들어 있고, 루카 공화국의 바람엔 화실의 테레빈유와 카페의 캐러멜 향이, 이스엘의 바람엔 박하 향이 섞여 있어...",
          DialogueId = 51010208,
          GUID = "7FB2DE40",
          NextDialogue = 51010209,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE40"
        },
        [51010209] = {
          ContentKR = "그렇다면 휘페르보레아 제국의 '바람'은 어떤 느낌이려나?",
          DialogueId = 51010209,
          GUID = "7FB2DE6A",
          NextOptions = {
            [1] = 510102091,
            [2] = 510102092,
            [3] = 510102093
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE6A"
        },
        [51010210] = {
          ContentKR = "음... 일리 있는 말이야. 여긴 이 도시처럼 강철 숲이 아주 많으니까.",
          DialogueId = 51010210,
          GUID = "7FB2DE94",
          NextDialogue = 51010211,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE94"
        },
        [51010211] = {
          ContentKR = "바람은 차가워도, 그 끝에 실려 오는 톱니바퀴와 엔진 소리는 언제나 뜨겁게 끓어오르지.",
          DialogueId = 51010211,
          GUID = "7FB2DEBE",
          NextDialogue = 51010212,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DEBE"
        },
        [51010212] = {
          ContentKR = "병사들의 총구도 아마 델 듯이 뜨거울 거야. 다들 표정은 얼음장 같지만...",
          DialogueId = 51010212,
          GUID = "7FB2DEE8",
          NextDialogue = 51010220,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DEE8"
        },
        [51010213] = {
          ContentKR = "그렇네! 이 도시의 4분의 3은 눈으로 이루어져 있으니까. 여기 사람들 말이, 아이스레이크 시티는 일 년에 딱 3개월만 빼고 늘 눈이 내린대.",
          DialogueId = 51010213,
          GUID = "7FB2DF12",
          NextDialogue = 51010214,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF12"
        },
        [51010214] = {
          ContentKR = "게다가 바람과 눈은 늘 함께 다니잖아. 대자연이 우리에게 준 최고의 조합이네!",
          DialogueId = 51010214,
          GUID = "7FB2DF3C",
          NextDialogue = 51010220,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF3C"
        },
        [51010215] = {
          ContentKR = "'눈물'이라... 이 노래의 앞부분에선 한 번도 쓰지 않은 소재인데...",
          DialogueId = 51010215,
          GUID = "7FB2DF66",
          NextDialogue = 51010216,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF66"
        },
        [51010216] = {
          ContentKR = "......",
          DialogueId = 51010216,
          GUID = "7FB2DF90",
          NextDialogue = 51010217,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF90"
        },
        [51010217] = {
          ContentKR = "이 광장에 처음 온 날, 눈먼 광대가 공연하는 걸 봤어. 몇 년 전에 보일러 연기 때문에 그렇게 됐다고 하더라. 어떤 아이가 공연을 보고 배를 잡고 웃으니까, 아이의 하인이 실버를 툭 던져 주었지.",
          DialogueId = 51010217,
          GUID = "7FB2DFBA",
          NextDialogue = 51010218,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DFBA"
        },
        [51010218] = {
          ContentKR = "내가 지금 앉아 있는 이 벤치에선 어떤 퇴역 군인이 딱 하나 남은 훈장을 판다며 소리쳤고, 바로 옆 벤치에선 야윈 어머니가 아픈 아이에게 말라 버린 젖을 물리고 있었어.",
          DialogueId = 51010218,
          GUID = "7FB2DFE4",
          NextDialogue = 51010219,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DFE4"
        },
        [51010219] = {
          ContentKR = "...그때, 이 광장을 스친 바람엔 아마도 '눈물'이 실려 있었을 거야.",
          DialogueId = 51010219,
          GUID = "7FB2E00E",
          NextDialogue = 51010220,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2E00E"
        },
        [51010220] = {
          ContentKR = "조언 고마워, 설원의 장미 같은 여행자님... 이제 곧, 노래를 완성할 수 있을 것 같아.",
          DialogueId = 51010220,
          GUID = "7FB2E038",
          SpeakNpcId = 700342,
          TalkActionId = {
            [1] = "700342:Lilikou_Story_Playlyre_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2E038"
        },
        [51010221] = {
          ContentKR = "조언 고마워, 설원의 장미 같은 여행자님.",
          DialogueId = 51010221,
          GUID = "7FB2E062",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2E062"
        },
        [51010301] = {
          ContentKR = "카론의 안개의 바다 신화에서...",
          DialogueId = 51010301,
          GUID = "7FB2ED82",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/env/700342/7FB2ED82"
        },
        [51010302] = {
          ContentKR = "...가장 재미있는 부분은, 안개 바다의 만물이 삶과 죽음을 영원히 되풀이한다는 거야. 넌 어떻게 생각해? 이디...",
          DialogueId = 51010302,
          GUID = "7FB2EDAC",
          NextDialogue = 51010303,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EDAC"
        },
        [51010303] = {
          ContentKR = "아, 너였구나! 기억나, 저번에 여기서 이야기했었잖아.",
          DialogueId = 51010303,
          GUID = "7FB2EDD6",
          NextDialogue = 51010304,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EDD6"
        },
        [51010304] = {
          ContentKR = "혹시 내 친구 못 봤어? 빨간 머리 여자앤데, 아까까지만 해도 여기 있었거든...",
          DialogueId = 51010304,
          GUID = "7FB2EE00",
          NextOptions = {
            [1] = 51010305
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE00"
        },
        [51010305] = {
          ContentKR = "못 봤어.",
          DialogueId = 51010305,
          GUID = "7FB2EE2A",
          NextDialogue = 51010306
        },
        [51010306] = {
          ContentKR = "알겠어! 그럼 여기서 조금 더 기다려 봐야겠다. 툭하면 갑자기 없어졌다, 다시 나타나곤 하는 애라서 말이야.",
          DialogueId = 51010306,
          GUID = "7FB2EE54",
          NextDialogue = 51010307,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE54"
        },
        [51010307] = {
          ContentKR = "요 며칠 여기서 카론의 고대 신화를 많이 수집했어. 여기 사람들은 그런 얘기를 전혀 거리낌 없이 하더라. 깜짝 놀랐다니까.",
          DialogueId = 51010307,
          GUID = "7FB2EE7E",
          NextDialogue = 51010308,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE7E"
        },
        [51010308] = {
          ContentKR = "나랑 내 친구 고향 엘리시안에서, 카론은 신과 대화하고 권력을 휘두르는 아주 높은 신분이거든. 하지만 고대 신화는 입에 올리기만 해도 아주 위험해.",
          DialogueId = 51010308,
          GUID = "7FB2EEA8",
          NextDialogue = 51010309,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EEA8"
        },
        [51010309] = {
          ContentKR = "참, 카론의 신화에 대해 알아?",
          DialogueId = 51010309,
          GUID = "7FB2EED2",
          NextOptions = {
            [1] = 51010310,
            [2] = 51010311
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EED2"
        },
        [51010310] = {
          ContentKR = "조금은.",
          DialogueId = 51010310,
          GUID = "7FB2EEFC",
          NextDialogue = 51010312
        },
        [51010311] = {
          ContentKR = "전혀 몰라.",
          DialogueId = 51010311,
          GUID = "7FB2EF26",
          NextDialogue = 51010312
        },
        [51010312] = {
          ContentKR = "'카론'은 '안개의 바다에서 온 자'라는 뜻이야...",
          DialogueId = 51010312,
          GUID = "7FB2EF50",
          NextDialogue = 51010313,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EF50"
        },
        [51010313] = {
          ContentKR = "모든 건 안개의 바다에서 시작됐어. 성스러운 나무, 그러니까 성수는 안개의 바다에서 자라는데, 성수의 커다란 잎사귀가 바로 천국의 나무야. 세계는 성수 위에 세워져 있지.",
          DialogueId = 51010313,
          GUID = "7FB2EF7A",
          NextDialogue = 51010314,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EF7A"
        },
        [51010314] = {
          ContentKR = "성수에서 순백의 꽃이 피어나자, 그 속에서 어머니 신 엠블라가 태어났어. 엠블라는 만물을 창조했고, 아버지 신 아스크도 창조했지. 이 두 신 사이에서 카론들의 공통된 선조가 태어난 거야.",
          DialogueId = 51010314,
          GUID = "7FB2EFA4",
          NextDialogue = 51010315,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFA4"
        },
        [51010315] = {
          ContentKR = "그렇지만 <W>죽음의 권능</>을 관장하는 아스크는 재앙의 화신이 됐고, 결국엔 '일식'이란 종말을 불러오고 말았지.",
          DialogueId = 51010315,
          GUID = "7FB2EFCE",
          NextDialogue = 51010316,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFCE"
        },
        [51010316] = {
          ContentKR = "종말이 찾아오자, <H>생명의 권능</>을 관장하는 어머니 신은 자신의 백성들을 지켜 줬고, 조각난 그녀의 영혼은 바다로 흩어져, 마침내 안개의 바다로 돌아갔어.",
          DialogueId = 51010316,
          GUID = "7FB2EFF8",
          NextDialogue = 51010317,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFF8"
        },
        [51010317] = {
          ContentKR = "아버지 신의 육신은 대지로 변했고, 그가 높이 들어 올렸던 팔은 산맥이 되어, 언제 돌아올지 모르는 신을 향해 영원히 뻗어 있게 되었지.",
          DialogueId = 51010317,
          GUID = "7FB2F022",
          NextOptions = {
            [1] = 51010318
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F022"
        },
        [51010318] = {
          ContentKR = "조금 슬픈 이야기네.",
          DialogueId = 51010318,
          GUID = "7FB2F04C",
          NextDialogue = 51010319
        },
        [51010319] = {
          ContentKR = "응. 하지만 고대 신화 중엔 흥미로운 이야기가 하나 더 있어.",
          DialogueId = 51010319,
          GUID = "7FB2F076",
          NextDialogue = 51010320,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F076"
        },
        [51010320] = {
          ContentKR = "종말이 끝난 후, 엠블라랑 아스크가 새로운 세상에서, 새로운 모습으로 태어났다는 이야기야.",
          DialogueId = 51010320,
          GUID = "7FB2F0A0",
          NextDialogue = 51010321,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0A0"
        },
        [51010321] = {
          ContentKR = "새롭게 태어난 두 신은 또다시 새로운 종말과 파멸, 그리고 새로운 시작을 가져온대.",
          DialogueId = 51010321,
          GUID = "7FB2F0CA",
          NextDialogue = 51010322,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0CA"
        },
        [51010322] = {
          ContentKR = "세계는 끝없이 순환하고, 모든 생명은 삶과 죽음을 반복하는 거지.",
          DialogueId = 51010322,
          GUID = "7FB2F0F4",
          NextOptions = {
            [1] = 51010323
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0F4"
        },
        [51010323] = {
          ContentKR = "옛날 사람들도 비극적인 결말을 싫어했나 보네.",
          DialogueId = 51010323,
          GUID = "7FB2F11E",
          NextDialogue = 51010324
        },
        [51010324] = {
          ContentKR = "근데... 살짝 신경 쓰이는 게, 이야기의 작가는 어째서 아버지 신과 어머니 신이 새로운 삶을 얻었다고 믿은 걸까? 다시 말하면, 엠블라와 아스크의 본질을 '정의'하는 건 과연 뭘까?",
          DialogueId = 51010324,
          GUID = "7FB2F148",
          NextDialogue = 51010325,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F148"
        },
        [51010325] = {
          ContentKR = "그들의 육체일까, 영혼일까? 아니면... 다른 무언가일까?",
          DialogueId = 51010325,
          GUID = "7FB2F172",
          NextDialogue = 51010326,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F172"
        },
        [51010326] = {
          ContentKR = "만약... 어디까지나 가정이지만, 어떤 위대한 마법사가 우리 발밑의 대지를 아스크의 모습으로 만들었다고 해봐. 그러면 그 아스크와 새로 태어난 아스크 중에, 누가 우리의 아버지 신인 걸까?",
          DialogueId = 51010326,
          GUID = "7FB2F19C",
          NextOptions = {
            [1] = 510103261,
            [2] = 510103262,
            [3] = 510103263,
            [4] = 510103264
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F19C"
        },
        [51010327] = {
          ContentKR = "그렇게 생각하는구나... 고마워! 덕분에 영감을 많이 얻었어.",
          DialogueId = 51010327,
          GUID = "7FB2F1C6",
          NextDialogue = 51010329,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F1C6"
        },
        [51010328] = {
          ContentKR = "수많은 창작이 다 이런 사소한 질문에서 시작되는 거 아닐까?",
          DialogueId = 51010328,
          GUID = "7FB2F1F0",
          NextDialogue = 51010329,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F1F0"
        },
        [51010329] = {
          ContentKR = "고마워, 촛불의 불꽃 같은 여행자님. 난 이 신화들이 정말 마음에 들어. 이제 이걸 노래로 만들 수 있게 됐네.",
          DialogueId = 51010329,
          GUID = "7FB2F21A",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F21A"
        },
        [51010330] = {
          ContentKR = "우리를 '우리'로 만들어 주는 건 대체 뭘까?",
          DialogueId = 51010330,
          GUID = "7FB2F244",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F244"
        },
        [51010401] = {
          ContentKR = "갈레아 극장...",
          DialogueId = 51010401,
          GUID = "7FB2FDEA",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/env/700342/7FB2FDEA"
        },
        [51010402] = {
          ContentKR = "또 만났네, 백사장 위의 석류석 같은 여행자님. 여길 많이 좋아하나 봐. 나도 그래.",
          DialogueId = 51010402,
          GUID = "7FB2FE14",
          NextDialogue = 51010403,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE14"
        },
        [51010403] = {
          ContentKR = "갈레아 극장에 가 본 적 있어?",
          DialogueId = 51010403,
          GUID = "7FB2FE3E",
          NextOptions = {
            [1] = 510104031,
            [2] = 510104032,
            [3] = 510104033
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE3E"
        },
        [51010404] = {
          ContentKR = "와! 부자구나. 정말 부럽다.",
          DialogueId = 51010404,
          GUID = "7FB2FE68",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE68"
        },
        [51010405] = {
          ContentKR = "음... 나랑 같구나.",
          DialogueId = 51010405,
          GUID = "7FB2FE92",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE92"
        },
        [51010406] = {
          ContentKR = "군단이랑? 우와, 여행자님한테도 이야깃거리가 엄청 많겠구나.",
          DialogueId = 51010406,
          GUID = "7FB2FEBC",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FEBC"
        },
        [51010407] = {
          ContentKR = "난 루카 공화국에 있는 어지간한 극장은 다 가 봤어. 그런데 휘페르보레아 제국의 극장만은 좀처럼 들어가볼 수가 없어.",
          DialogueId = 51010407,
          GUID = "7FB2FEE6",
          NextDialogue = 51010408,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FEE6"
        },
        [51010408] = {
          ContentKR = "여긴 카론이 살기 좋은 곳이 아니란 건 알고 있었지만, 공공시설에서 받는 비용도 생각보다 훨씬 비싸더라.",
