          GUID = "7FB2FF10",
          NextDialogue = 51010409,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF10"
        },
        [51010409] = {
          ContentKR = "운 좋게 해마다 딱 한 번 무료입장이 가능한 축제 날에 맞춰 왔는데, 하필이면 그날 거기서 무력 충돌이 일어났다고 하더라고... 정말 최악이었지.",
          DialogueId = 51010409,
          GUID = "7FB2FF3A",
          NextDialogue = 51010410,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF3A"
        },
        [51010410] = {
          ContentKR = "그래도 다행히 악보는 잔뜩 모았어! 서점 판매가는 나름 합리적이었고, 노래를 불러 주면 악보를 주겠단 분들도 꽤 많았거든. 그리고 어떤 마음씨 좋은 친구가 유명한 노래도 한 곡 가르쳐 줬어!",
          DialogueId = 51010410,
          GUID = "7FB2FF64",
          NextOptions = {
            [1] = 510104101
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF64"
        },
        [51010411] = {
          ContentKR = "며칠 전 일인데, 밤에 달빛 아래 벽에 기대서, 어렵게 구한 악보에서 배운 노래를 흥얼거리고 있었거든. 멜로디가 복잡하진 않아서, 금방 외울 수 있는 노래였어.",
          DialogueId = 51010411,
          GUID = "7FB2FF8E",
          NextDialogue = 51010412,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF8E"
        },
        [51010412] = {
          ContentKR = "근데 노래를 다 부르고 나니까, 갑자기 벽 너머에서 이상한 노크 소리가 들리는 거야... 들어보니까 소리에 어떤 규칙이 있더라. 알다시피, 음유시인은 리듬에 민감한 편이잖아.",
          DialogueId = 51010412,
          GUID = "7FB2FFB8",
          NextDialogue = 51010413,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FFB8"
        },
        [51010413] = {
          ContentKR = "그래서 그 리듬을 분석해 봤더니, 흔하디흔한 옛날식 암호였어. 두 가지 노크 소리로 나한테 신호를 보내고 있더라고.",
          DialogueId = 51010413,
          GUID = "7FB2FFE2",
          NextDialogue = 51010414,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FFE2"
        },
        [51010414] = {
          ContentKR = "벽 너머의 사람은 내가 노래를 잘못 불렀다고 알려 줬어. 그건 여기서 굉장히 유명한 오페라에 나오는 파트였는데, 난 대본을 읽어 본 적이 없으니까, 노래가 관중들에게 전달하려는 감정을 제대로 이해하지 못했던 거야.",
          DialogueId = 51010414,
          GUID = "7FB3000C",
          NextDialogue = 51010415,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB3000C"
        },
        [51010415] = {
          ContentKR = "그 사람은 어떤 이유 때문인지 말을 하거나 노래를 부를 수 없는 상황이었어. 그렇지만 노크로 신호를 보내서 어떻게 불러야 하는지 알려 줄 순 있었지.",
          DialogueId = 51010415,
          GUID = "7FB30036",
          NextDialogue = 51010416,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30036"
        },
        [51010416] = {
          ContentKR = "덕분에 노래를 제대로 부를 수 있게 됐을 때, 감사 인사를 하려고 벽 너머로 달려가 보니까, 그 마음씨 좋은 분은 이미 떠나고 없더라.",
