        [51010708] = {
          ContentKR = "광장의 고양이들도 더 이상 복슬복슬하지 않고, 석고처럼 딱딱하고 미끄러워질 거고...",
          DialogueId = 51010708,
          GUID = "7FB33048",
          NextDialogue = 51010709,
          SpeakNpcId = 700337
        },
        [51010709] = {
          ContentKR = "빵집에서는 폭신폭신한 빵 대신 정체불명의 검은 물체를 굽게 될 테고...",
          DialogueId = 51010709,
          GUID = "7FB33072",
          NextDialogue = 51010710,
          SpeakNpcId = 700337
        },
        [51010710] = {
          ContentKR = "내가 제일 좋아하는 아이스크림도 더는 차갑지 않고, 목구멍에 끈적끈적하게 달라붙을 거야...",
          DialogueId = 51010710,
          GUID = "7FB3309C",
          NextDialogue = 51010711,
          SpeakNpcId = 700337
        },
        [51010711] = {
          ContentKR = "모두가 점차 루나만 해지고, 하얗게 변할 거야...",
          DialogueId = 51010711,
          GUID = "7FB330C6",
          NextDialogue = 51010712,
          SpeakNpcId = 700337
        },
        [51010712] = {
          ContentKR = "그리고 결국...",
          DialogueId = 51010712,
          GUID = "7FB330F0",
          NextDialogue = 51010713,
          SpeakNpcId = 700337
        },
        [51010713] = {
          ContentKR = "꽃집의 아주머니도, 빵집의 아줌마도, 아이스크림을 파는 할아버지도... 다들 루나가 되어버릴 거야!",
          DialogueId = 51010713,
          GUID = "7FB3311A",
          NextOptions = {
            [1] = 51010714,
            [2] = 51010715
          },
          SpeakNpcId = 700337
        },
        [51010714] = {
          ContentKR = "안녕, 루나. 나도 루나가 되고 싶어.",
          DialogueId = 51010714,
          GUID = "7FB33144",
          ImprPlusId = 1005,
          NextDialogue = 51010716,
          SpeakNpcId = 700337
        },
        [51010715] = {
          ContentKR = "정말 끔찍한 종말이네...",
          DialogueId = 51010715,
          GUID = "7FB3316E",
          ImprPlusId = 1004,
          NextDialogue = 51010716,
          SpeakNpcId = 700337
        },
        [51010716] = {
          ContentKR = "너... 그, 그 머리카락이랑 옷, 그리고 키까지... 벌써 루나가 되기 시작한 거야?",
          DialogueId = 51010716,
          GUID = "7FB33198",
          NextDialogue = 51010717,
          SpeakNpcId = 700337
        },
        [51010717] = {
          ContentKR = "역시... 종말... 종말이 온 거야. 모든 게 끝장이야.",
          DialogueId = 51010717,
          GUID = "7FB331C2",
          NextDialogue = 51010718,
          SpeakNpcId = 700337
        },
        [51010718] = {
          ContentKR = "(비관론자 루나는 힘없이 두 손을 늘어뜨린다. 그녀의 멍한 시선은 당신과 겹겹의 건물을 뚫고, 흐릿한 하늘에 고정된다. 그녀가 말한 종말이 곧 현실이 되기라도 할 것처럼.)",
          DialogueId = 51010718,
          GUID = "7FB331EC",
          NextDialogue = 51010719
        },
        [51010719] = {
          ContentKR = "(당연하지만 몇 분이 지나도, 아무 일도 일어나지 않는다. 루나는 더 이상 당신을 바라보지 않고, 그저 \"종말이 온다\"라는 말만 되풀이한다.)",
          DialogueId = 51010719,
          GUID = "7FB33216",
          NextDialogue = 51010720
        },
        [51010720] = {
          ContentKR = "(루나가 되는 게 대체 어떤 느낌일지 궁금하긴 해도, 지금 당신이 할 수 있는 일은 그냥 돌아서서 떠나는 것뿐이다.)",
          DialogueId = 51010720,
          GUID = "7FB33240"
        },
        [51010721] = {
          ContentKR = "종말, 종말이 이미 시작됐어...",
          DialogueId = 51010721,
          GUID = "7FB3326A",
          SpeakNpcId = 700337
        },
        [51010801] = {
          ContentKR = "안녕하세요, 이 꽃이 오늘 옷차림이랑 잘 어울리시네요... 그 애가 살아 있다면 분명 이렇게 말했을 거예요.",
          DialogueId = 51010801,
          GUID = "7FB33F8A",
          NextOptions = {
            [1] = 51010802,
            [2] = 51010803
          },
          SpeakNpcId = 700203
        },
        [51010802] = {
          ContentKR = "절 아세요?",
          DialogueId = 51010802,
          GUID = "7FB33FB4",
          NextDialogue = 51010804
        },
        [51010803] = {
          ContentKR = "'그 아이'라니, 설마...",
          DialogueId = 51010803,
          GUID = "7FB33FDE",
          NextDialogue = 51010804
        },
        [51010804] = {
          ContentKR = "제 딸, 프시케요.",
          DialogueId = 51010804,
          GUID = "7FB34008",
          NextDialogue = 51010805,
          SpeakNpcId = 700203
        },
        [51010805] = {
          ContentKR = "그 아이가 편지에서 '새로 사귄 친구'를 언급한 적이 있거든요. 프시케가 말한 분의 이미지와 너무 닮아서... 제가 착각한 거라면 부디 너그럽게 이해해 주세요.",
          DialogueId = 51010805,
          GUID = "7FB34032",
          NextOptions = {
            [1] = 51010806,
            [2] = 51010807
          },
          SpeakNpcId = 700203,
          bForbidSkipOptions = true
        },
        [51010806] = {
          ContentKR = "...제가 어떤 사람이라고 하던가요?",
          DialogueId = 51010806,
          GUID = "7FB3405C",
          NextDialogue = 51010809
        },
        [51010807] = {
          ContentKR = "...네, 사람 잘못 보셨습니다.",
          DialogueId = 51010807,
          GUID = "7FB34086",
          NextDialogue = 51010808
        },
        [51010808] = {
          ContentKR = "(당신은 도망치듯 자리를 떠난다. 그것은 모두의 아픔이었고, 당신은 더 이상 그 상처를 건드리고 싶지 않다.)",
          DialogueId = 51010808,
          GUID = "7FB340B0",
          Scripts = "SetOutport{FinishType{\"Fail\"}}"
        },
        [51010809] = {
          ContentKR = "아이스레이크 시티에 온 그날로 글로스터 폐광에 들어간 똑똑하고 용감한 분이라고 하더군요. 자기가 본 또래들 중에서 가장 강한 친구라고도 했어요.",
          DialogueId = 51010809,
          GUID = "7FB340DA",
          NextDialogue = 51010810,
          SpeakNpcId = 700203
        },
        [51010810] = {
          ContentKR = "\"그 친구는 아이스레이크 시티의 대부분 사람들과 달라요. 우리가 진작 잃어버린... 정의와 자유에 대한 갈망을 간직하고 있거든요.\"",
          DialogueId = 51010810,
          GUID = "7FB34104",
          NextDialogue = 51010811,
          SpeakNpcId = 700203
        },
        [51010811] = {
          ContentKR = "\"그 친구한테서 전 또 다른 삶을 보게 됐어요.\"",
          DialogueId = 51010811,
          GUID = "7FB3412E",
          NextDialogue = 51010812,
          SpeakNpcId = 700203
        },
        [51010812] = {
          ContentKR = "편지에 그렇게 적혀 있었어요.",
          DialogueId = 51010812,
          GUID = "7FB34158",
          NextDialogue = 51010813,
          SpeakNpcId = 700203
        },
        [51010813] = {
          ContentKR = "(여인은 그 편지를 수도 없이 반복해 읽은 듯 능숙하게 문장을 되뇐다.)",
          DialogueId = 51010813,
          GUID = "7FB34182",
          NextDialogue = 51010814
        },
        [51010814] = {
          ContentKR = "죄송해요, 전...",
          DialogueId = 51010814,
          GUID = "7FB341AC",
          NextDialogue = 51010815,
          SpeakNpcId = 100001
        },
        [51010815] = {
          ContentKR = "사과는 안 해도 돼요. 프시케는 당신이 마지막까지 함께해줘서 분명 행복했을 거예요. 그거면 돼요. 오히려 우리가 감사할 일이죠.",
          DialogueId = 51010815,
          GUID = "7FB341D6",
          NextDialogue = 51010816,
          SpeakNpcId = 700203
        },
        [51010816] = {
          ContentKR = "이 꽃다발 받아요. 우리의 축복이 늘 당신과 함께하길 바라요.",
          DialogueId = 51010816,
          GUID = "7FB34200",
          SpeakNpcId = 700203
        },
        [51010817] = {
          ContentKR = "모든 게 순조롭길, 우리의 축복이 늘 당신과 함께하길 바라요.",
          DialogueId = 51010817,
          GUID = "7FB3422A",
          SpeakNpcId = 700203
        },
        [51010901] = {
          ContentKR = "우리 농장 과일이라 하는 말이 아니라 이런 기술로 키우는 데는 어디에도 없다니까요!",
          DialogueId = 51010901,
          GUID = "7FB34FF2",
          NextDialogue = 51010902,
          SpeakNpcId = 700009
        },
        [51010902] = {
          ContentKR = "과일 좀 드셔보실래요? 좋은 씨앗에 최고급 비료로 저희 온실에서 정성껏 키운 거랍니다. 영양도 풍부하고 맛도 정말 좋아요!",
          DialogueId = 51010902,
          GUID = "7FB3501C",
          NextOptions = {
            [1] = 51010903,
            [2] = 51010905
          },
          SpeakNpcId = 700009
        },
        [51010903] = {
          ContentKR = "온실에서 재배한 과일이라면 굉장히 비싸겠네요.",
          DialogueId = 51010903,
          GUID = "7FB35046",
          ImprPlusId = 1001,
          NextDialogue = 51010904
        },
        [51010904] = {
          ContentKR = "과일마다 다르죠. 그래도 좋은 과일 먹는 것 자체가 얼마나 힘든 일인데요. 저도 전엔 전쟁터에 있었을 땐 꿈도 못 꿨다니까요.",
          DialogueId = 51010904,
          GUID = "7FB35070",
          NextOptions = {
            [1] = 51010907
          },
          SpeakNpcId = 700009
        },
        [51010905] = {
          ContentKR = "온실 재배 기술을 익히기가 쉽지 않았을 텐데요.",
          DialogueId = 51010905,
          GUID = "7FB3509A",
          ImprPlusId = 1003,
          NextDialogue = 51010906
        },
        [51010906] = {
          ContentKR = "저희 할아버지께서 전수해 주셨어요. 처음에는 가업을 물려받을 생각이 전혀 없었지만, 제대한 후로 생각이 바뀌었죠.",
          DialogueId = 51010906,
          GUID = "7FB350C4",
          NextOptions = {
            [1] = 51010907
          },
          SpeakNpcId = 700009
        },
        [51010907] = {
          ContentKR = "군인이셨어요?",
          DialogueId = 51010907,
          GUID = "7FB350EE",
          NextDialogue = 51010908
        },
        [51010908] = {
          ContentKR = "그럼요, 혼자서 세 명 몫은 거뜬히 해내는 군인이었죠!",
          DialogueId = 51010908,
          GUID = "7FB35118",
          NextDialogue = 51010909,
          SpeakNpcId = 700009
        },
        [51010909] = {
          ContentKR = "그러다 다치고 나니 몸이 점점 안 따라주더라고요. 그래서 결국 조기 제대했어요.",
          DialogueId = 51010909,
          GUID = "7FB35142",
          NextDialogue = 51010910,
          SpeakNpcId = 700009
        },
        [51010910] = {
          ContentKR = "알고 보니, 그냥 과일 열심히 키우고, 좋은 사람 만나서 조용히 살아가는 삶도 큰 행복이더군요.",
          DialogueId = 51010910,
          GUID = "7FB3516C",
          NextOptions = {
            [1] = 51010911
          },
          RestartTag = 51010910,
          SpeakNpcId = 700009
        },
        [51010911] = {
          ContentKR = "마음에 둔 분은 있나요?",
          DialogueId = 51010911,
          FailDialogue = 51010912,
          GUID = "7FB35196",
          ImprCheckId = 1075,
          NextDialogue = 51010914
        },
        [51010912] = {
          ContentKR = "(남자는 잠시 말문이 막힌 듯 어버버하다가 힘겹게 말을 내뱉는다.)",
          DialogueId = 51010912,
          GUID = "7FB351C0",
          NextDialogue = 51010913
        },
        [51010913] = {
          ContentKR = "그, 그건 묻지 말아 주세요. 참, 제, 제가 좋은 과일로 골라 드릴게요.",
          DialogueId = 51010913,
          GUID = "7FB351EA",
          SpeakNpcId = 700009
        },
        [51010914] = {
          ContentKR = "(남자의 눈동자가 잠시 반짝이더니, 자신도 모르게 미소 짓다가 금세 당혹스러운 표정을 한다.)",
          DialogueId = 51010914,
          GUID = "7FB35214",
          NextDialogue = 51010915
        },
        [51010915] = {
          ContentKR = "...있긴 한데요, 아직 뒷모습밖에 본 적이 없어요.",
          DialogueId = 51010915,
          GUID = "7FB3523E",
          NextDialogue = 51010916,
          SpeakNpcId = 700009
        },
        [51010916] = {
          ContentKR = "이렇게 오래도록 말 한마디도 못 나눴어요. 휴...",
          DialogueId = 51010916,
          GUID = "7FB35268",
          NextDialogue = 51010917,
          SpeakNpcId = 700009
        },
        [51010917] = {
          ContentKR = "괜히 갑자기 말 걸면 놀랄까 봐서, 건물주 루나한테 대신 전해달라고 부탁했거든요. 근데 어쩜 그렇게 타이밍이 안 맞는지... 매번 집에 없더라고요.",
          DialogueId = 51010917,
          GUID = "7FB35292",
          NextOptions = {
            [1] = 51010918
          },
          SpeakNpcId = 700009
        },
        [51010918] = {
          ContentKR = "겉으론 털털해 보여도, 상대를 존중하는 마음이 보이네요.",
          DialogueId = 51010918,
          GUID = "7FB352BC",
          ImprPlusId = 1002,
          NextDialogue = 51010919
        },
        [51010919] = {
          ContentKR = "하하, 그런 칭찬을 들으니 쑥스럽네요.",
          DialogueId = 51010919,
          GUID = "7FB352E6",
          NextDialogue = 51010920,
          SpeakNpcId = 700009
        },
        [51010920] = {
          ContentKR = "딱 봐도 많이 배우신 분 같은데, 제가 쓴 이 어설픈 문장 좀 다듬어주실 수 있을까요? 제가 글재주가 없어서요.",
          DialogueId = 51010920,
          GUID = "7FB35310",
          NextOptions = {
            [1] = 51010921
          },
          SpeakNpcId = 700009
        },
        [51010921] = {
          ContentKR = "마침 한가한데 그럼 한 번 들려주세요.",
          DialogueId = 51010921,
          GUID = "7FB3533A",
          NextDialogue = 51010922
        },
        [51010922] = {
          ContentKR = "흠흠.",
          DialogueId = 51010922,
          GUID = "7FB35364",
          NextDialogue = 51010923,
          SpeakNpcId = 700009
        },
        [51010923] = {
          ContentKR = "\"당신을 향한 내 마음은 날이 갈수록 더 뜨거워져요. 겨울 온실보다도 더 따뜻하죠.\"",
          DialogueId = 51010923,
          GUID = "7FB3538E",
          NextOptions = {
            [1] = 51010924
          },
          SpeakNpcId = 700009
        },
        [51010924] = {
          ContentKR = "......",
          DialogueId = 51010924,
          GUID = "7FB353B8",
          NextDialogue = 51010925
        },
        [51010925] = {
          ContentKR = "\"당신은 언제쯤 알아줄까요? 내 마음은 과일처럼, 그대가 따러 와주기만을 기다리고 있어요.\"",
          DialogueId = 51010925,
          GUID = "7FB353E2",
          NextDialogue = 51010926,
          SpeakNpcId = 700009
        },
        [51010926] = {
          ContentKR = "\"날 받아주세요, 내 사랑. 제발 이 마음이 썩은 과일처럼 땅바닥에 버려지지 않게 해줘요.\"",
          DialogueId = 51010926,
          GUID = "7FB3540C",
          NextDialogue = 51010927,
          SpeakNpcId = 700009
        },
        [51010927] = {
          ContentKR = "...어떤가요? 다듬을 만한 곳이 있나요?",
          DialogueId = 51010927,
          GUID = "7FB35436",
          NextOptions = {
            [1] = 51010928
          },
          SpeakNpcId = 700009
        },
        [51010928] = {
          ContentKR = "...개성 있고 진솔한 글이네요. 지금 그대로가 좋을 것 같아요.",
          DialogueId = 51010928,
          GUID = "7FB35460",
          NextDialogue = 51010929
        },
        [51010929] = {
          ContentKR = "정말요? 그럼 다행이네요. 좋은 말씀 감사합니다.",
          DialogueId = 51010929,
          GUID = "7FB3548A",
          NextDialogue = 51010930,
          SpeakNpcId = 700009
        },
        [51010930] = {
          ContentKR = "제 마음이 결실을 맺는다면 나중에 과일을 사러 오실 때 아주 싸게 드리겠습니다, 하하.",
          DialogueId = 51010930,
          GUID = "7FB354B4",
          SpeakNpcId = 700009
        },
        [51010931] = {
          ContentKR = "아직 그쪽 답은 없어서요... 휴, 파격 할인은 조금 더 기다리셔야겠네요.",
          DialogueId = 51010931,
          GUID = "7FB354DE",
          SpeakNpcId = 700009
        },
        [51011001] = {
          ContentKR = "잠시만요, 갑자기 말을 걸어 죄송합니다.",
          DialogueId = 51011001,
          GUID = "7FB3605A",
          NextDialogue = 51011002,
          SpeakNpcId = 700008
        },
        [51011002] = {
          ContentKR = "저희 가게의 옷에 영혼이 깃들어 있다면, 꼭 당신처럼 멋진 분께 입혀지길 바랄 거예요.",
          DialogueId = 51011002,
          GUID = "7FB36084",
          NextDialogue = 51011003,
          SpeakNpcId = 700008
        },
        [51011003] = {
          ContentKR = "이대로 당신을 지나친다면, 옷들이 분명 슬퍼할 거예요.",
          DialogueId = 51011003,
          GUID = "7FB360AE",
          NextDialogue = 51011004,
          SpeakNpcId = 700008
        },
        [51011004] = {
          ContentKR = "(눈앞의 남자는 귀족처럼 우아한 분위기로, 말투와 몸짓에 품위가 느껴진다. 포근한 눈웃음은 봄바람처럼 따뜻하다.)",
          DialogueId = 51011004,
          GUID = "7FB360D8",
          NextOptions = {
            [1] = 51011005,
            [2] = 51011006
          }
        },
        [51011005] = {
          ContentKR = "제가 감당할 수 있는 가격일까요?",
          DialogueId = 51011005,
          GUID = "7FB36102",
          ImprPlusId = 1001,
          NextDialogue = 51011007
        },
        [51011006] = {
          ContentKR = "전 마대 자루를 걸쳐도 충분히 소화할 수 있어요.",
          DialogueId = 51011006,
          GUID = "7FB3612C",
          ImprPlusId = 1005,
          NextDialogue = 51011007
        },
        [51011007] = {
          ContentKR = "그럼요. 이건 가게 카탈로그예요. 마음에 드는 디자인이 있으면 얼마든지 입어보셔도 돼요.",
          DialogueId = 51011007,
          GUID = "7FB36156",
          NextDialogue = 51011008,
          SpeakNpcId = 700008
        },
        [51011008] = {
          ContentKR = "(카탈로그에 기록된 디자인이 너무 많아서 무엇부터 봐야 할지 고민될 정도다.)",
          DialogueId = 51011008,
          GUID = "7FB36180",
          NextDialogue = 51011009
        },
        [51011009] = {
          ContentKR = "(이제 삶을 즐겨보는 건 어떨까? 우선 새 옷부터 사는 게 좋겠다. 당신은 화려한 색상의 {性别:치마|옷}을 가리킨다.)",
          DialogueId = 51011009,
          GUID = "7FB361AA",
          NextDialogue = 51011010
        },
        [51011010] = {
          ContentKR = "{性别:죄송합니다. 이건 여성복인 데다, 제 사이즈에 맞춰 제작된 옷이라 고객님께 맞는 사이즈가 없네요...|아쉽게도 이 옷은 제 치수에 맞춰 만든 거라, 손님께 맞는 사이즈가 없네요...}",
          DialogueId = 51011010,
          GUID = "7FB361D4",
          NextOptions = {
            [1] = 51011011
          },
          RestartTag = 51011010,
          SpeakNpcId = 700008
        },
        [51011011] = {
          ContentKR = "전 이 옷이 마음에 들어요. 스타일을 참고할 수 있게 그쪽이 한번 입어봐 주실래요?",
          DialogueId = 51011011,
          FailDialogue = 51011012,
          GUID = "7FB361FE",
          ImprCheckId = 1076,
          NextDialogue = 51011013
        },
        [51011012] = {
          ContentKR = "하하, 농담을 잘하시는 분이네요.",
          DialogueId = 51011012,
          GUID = "7FB36228",
          SpeakNpcId = 700008
        },
        [51011013] = {
          ContentKR = "꼭 보시겠다면... 안 될 것도 없지만, 지금 이 옷으로 갈아입으면 불필요한 오해를 살지도 몰라요.",
          DialogueId = 51011013,
          GUID = "7FB36252",
          NextDialogue = 51011014,
          SpeakNpcId = 700008
        },
        [51011014] = {
          ContentKR = "여자로 오해받을까 봐 걱정되시는 건가요?",
          DialogueId = 51011014,
          GUID = "7FB3627C",
          NextDialogue = 51011015,
          SpeakNpcId = 100001
        },
        [51011015] = {
          ContentKR = "맞긴 한데... 중요한 건 '여자로 착각했다'가 아니라, '착각한 다음에 무슨 일이 생기느냐'예요.",
          DialogueId = 51011015,
          GUID = "7FB362A6",
          NextDialogue = 51011016,
          SpeakNpcId = 700008
        },
        [51011016] = {
          ContentKR = "말로 설명하기 좀 그렇긴 한데...",
          DialogueId = 51011016,
          GUID = "7FB362D0",
          NextDialogue = 51011017,
          SpeakNpcId = 700008
        },
        [51011017] = {
          ContentKR = "설마... 당신을 여자로 오해하고 반한 사람이라도 있는 건가요?!",
          DialogueId = 51011017,
          GUID = "7FB362FA",
          NextDialogue = 51011018,
          SpeakNpcId = 100001
        },
        [51011018] = {
          ContentKR = "아, 현명하신 분이라 설명할 수고를 덜었네요.",
          DialogueId = 51011018,
          GUID = "7FB36324",
          NextDialogue = 51011019,
          SpeakNpcId = 700008
        },
        [51011019] = {
          ContentKR = "그 순애보 씨는 저한테 미모의 여동생이 있다고 굳게 믿고 있더군요. 실제와는 완전히 다른 상황이죠.",
          DialogueId = 51011019,
          GUID = "7FB3634E",
          NextDialogue = 51011020,
          SpeakNpcId = 700008
        },
        [51011020] = {
          ContentKR = "어느 날 귀여운 루나 아가씨가 가게에 찾아와 상대방의 편지를 구구절절 읽기 전까진, 제 행동이 오해를 불러일으켰다는 것조차 몰랐답니다.",
          DialogueId = 51011020,
          GUID = "7FB36378",
          NextDialogue = 51011021,
          SpeakNpcId = 700008
        },
        [51011021] = {
          ContentKR = "그래서 매번 루나 아가씨가 대신 고백을 전하러 올 때마다, 여동생이 외출했다는 거짓말로 둘러댈 수밖에 없었어요.",
          DialogueId = 51011021,
          GUID = "7FB363A2",
          NextDialogue = 51011022,
          SpeakNpcId = 700008
        },
        [51011022] = {
          ContentKR = "왜 사실대로 말하지 않은 거죠?",
          DialogueId = 51011022,
          GUID = "7FB363CC",
          NextDialogue = 51011023,
          SpeakNpcId = 100001
        },
        [51011023] = {
          ContentKR = "왜라니... 재밌으니까요?",
          DialogueId = 51011023,
          GUID = "7FB363F6",
          NextDialogue = 51011024,
          SpeakNpcId = 700008
        },
        [51011024] = {
          ContentKR = "\"당신의 예쁜 스카프는 우리 농장의 아이스베리처럼 싱그럽고 매혹적이에요.\"",
          DialogueId = 51011024,
          GUID = "7FB36420",
          NextDialogue = 51011025,
          SpeakNpcId = 700008
        },
        [51011025] = {
          ContentKR = "\"불꽃처럼 붉은 당신의 드레스는 불의 근원처럼 뜨거워서, 절 긴장하게 만들어요.\"",
          DialogueId = 51011025,
          GUID = "7FB3644A",
          NextDialogue = 51011026,
          SpeakNpcId = 700008
        },
        [51011026] = {
          ContentKR = "제가 어떤 옷차림을 하든, 이틀 뒤면 항상 제 코디에 대한 평가를 해주더라고요.",
          DialogueId = 51011026,
          GUID = "7FB36474",
          NextDialogue = 51011027,
          SpeakNpcId = 700008
        },
        [51011027] = {
          ContentKR = "말투는 좀... 투박하지만, 은근히 참고가 되어서요.",
          DialogueId = 51011027,
          GUID = "7FB3649E",
          NextDialogue = 51011028,
          SpeakNpcId = 700008
        },
        [51011028] = {
          ContentKR = "이 말투, 뭔가 익숙한데...",
          DialogueId = 51011028,
          GUID = "7FB364C8",
          NextDialogue = 51011029,
          SpeakNpcId = 100001
        },
        [51011029] = {
          ContentKR = "설마 그 순애보 씨랑 아는 사이세요? 그렇다면 이 비밀을 꼭 지켜주셔야 해요.",
          DialogueId = 51011029,
          GUID = "7FB364F2",
          NextDialogue = 51011030,
          SpeakNpcId = 700008
        },
        [51011030] = {
          ContentKR = "그냥 새로 디자인한 옷을 평가해 줄 공짜 도구가 필요했던 거잖아요...",
          DialogueId = 51011030,
          GUID = "7FB3651C",
          NextDialogue = 51011031,
          SpeakNpcId = 100001
        },
        [51011031] = {
          ContentKR = "\"그 진실한 분이 내일은 또 어떤 새롭고 기발한 비유로 내 옷을 표현하려나?\" 손님도 이런 일을 겪는다면 같은 호기심이 생기지 않을까요?",
          DialogueId = 51011031,
          GUID = "7FB36546",
          NextDialogue = 51011032,
          SpeakNpcId = 700008
        },
        [51011032] = {
          ContentKR = "다만 요샌 그분의 말투가 예전만 못해요. 잡히지 않는 꿈 앞에서 망설이는 사람처럼요.",
          DialogueId = 51011032,
          GUID = "7FB36570",
          NextDialogue = 51011033,
          SpeakNpcId = 700008
        },
        [51011033] = {
          ContentKR = "너무 밀어내진 말고, 타이밍 봐서 살짝 반응해 줄까 봐요. 그래야 포기하지 않겠죠?",
          DialogueId = 51011033,
          GUID = "7FB3659A",
          NextDialogue = 51011034,
          SpeakNpcId = 700008
        },
        [51011034] = {
          ContentKR = "완전히 이 상황을 즐기고 있잖아요...",
          DialogueId = 51011034,
          GUID = "7FB365C4",
          SpeakNpcId = 100001
        },
        [51011035] = {
          ContentKR = "아, 당신이었군요. 그 비밀은 꼭 지켜주세요. 보답으로 저희 가게에 오시면 평생 할인해 드릴게요.",
          DialogueId = 51011035,
          GUID = "7FB365EE",
          SpeakNpcId = 700008
        },
        [51011101] = {
          ContentKR = "이야, 사장님들 열심히 일하시네!",
          DialogueId = 51011101,
          GUID = "7FB370C2",
          NextDialogue = 51011102,
          SpeakNpcId = 700336
        },
        [51011102] = {
          ContentKR = "난 햇볕 쬐기랑 자는 것밖에 할 줄 모르는데...",
          DialogueId = 51011102,
          GUID = "7FB370EC",
          NextOptions = {
            [1] = 51011103,
            [2] = 51011104,
            [3] = 51011105
          },
          SpeakNpcId = 700336
        },
        [51011103] = {
          ContentKR = "누구나 자기만의 삶의 방식이 있는 법이야.",
          DialogueId = 51011103,
          GUID = "7FB37116",
          ImprPlusId = 1002,
          NextDialogue = 51011106
        },
        [51011104] = {
          ContentKR = "햇볕이나 쬐고 잠이나 자는 게 인생이지!",
          DialogueId = 51011104,
          GUID = "7FB37140",
          ImprPlusId = 1004,
          NextDialogue = 51011106
        },
        [51011105] = {
          ContentKR = "햇볕을 쬐고 잠을 자는 건 건강에 대한 장기 투자야.",
          DialogueId = 51011105,
          GUID = "7FB3716A",
          ImprPlusId = 1003,
          NextDialogue = 51011106
        },
        [51011106] = {
          ContentKR = "오, 뭘 좀 아는데.",
          DialogueId = 51011106,
          GUID = "7FB37194",
          NextDialogue = 51011107,
          SpeakNpcId = 700336
        },
        [51011107] = {
          ContentKR = "근데 일을 안 하니까 어쩐지 죄책감이 느껴지긴 해. 봐봐, 다들 열심히 돈을 벌고 있는데 난 놀고 먹는데도 이렇게 부자라니, 뭔가 미안해지잖아...",
          DialogueId = 51011107,
          GUID = "7FB371BE",
          NextDialogue = 51011108,
          SpeakNpcId = 700336
        },
        [51011108] = {
          ContentKR = "루나는 사람을 돕지 않으면 온몸이 근질근질하고 마음이 불안해지거든, 휴...",
          DialogueId = 51011108,
          GUID = "7FB371E8",
          NextOptions = {
            [1] = 51011109
          },
          RestartTag = 51011108,
          SpeakNpcId = 700336
        },
        [51011109] = {
          ContentKR = "(건물주 루나에게 부자가 되는 비결에 대해 묻는다.)",
          DialogueId = 51011109,
          FailDialogue = 51011110,
          GUID = "7FB37212",
          ImprCheckId = 1077,
          NextDialogue = 51011111
        },
        [51011110] = {
          ContentKR = "...뭐? 하암... 방금 뭐라고 했어...?",
          DialogueId = 51011110,
          GUID = "7FB3723C",
          SpeakNpcId = 700336
        },
        [51011111] = {
          ContentKR = "부자가 되는 비결? 어느 날 실수로 절벽에서 떨어졌는데, 마침 엄청 귀한 돌멩이를 주워서 벼락부자가 됐어. 돈이 너무 많아서 써도 써도 줄어들지 않는다니까...",
          DialogueId = 51011111,
          GUID = "7FB37266",
          NextDialogue = 51011112,
          SpeakNpcId = 700336
        },
        [51011112] = {
          ContentKR = "혹시 너도 한 번 뛰어내려 볼래?",
          DialogueId = 51011112,
          GUID = "7FB37290",
          NextOptions = {
            [1] = 51011113,
            [2] = 51011114
          },
          SpeakNpcId = 700336
        },
        [51011113] = {
          ContentKR = "고맙긴 한데, 이미 해봤어...",
          DialogueId = 51011113,
          GUID = "7FB372BA",
          NextDialogue = 51011115
        },
        [51011114] = {
          ContentKR = "젠장, 왜 똑같이 절벽에서 떨어졌는데 나한테는 행운이 찾아오지 않는 거야!",
          DialogueId = 51011114,
          GUID = "7FB372E4",
          NextDialogue = 51011115
        },
        [51011115] = {
          ContentKR = "음... 그럼 더 도울 일은 없는 것 같네.",
          DialogueId = 51011115,
          GUID = "7FB3730E",
          NextDialogue = 51011116,
          SpeakNpcId = 700336
        },
        [51011116] = {
          ContentKR = "아, 맞다! 과일 파는 워렌 아저씨가 또 전해달라던 말이 있었지! 잘 됐다~ 드디어 할 일이 생겼어!",
          DialogueId = 51011116,
          GUID = "7FB37338",
          SpeakNpcId = 700336
        },
        [51011201] = {
          ContentKR = "......",
          DialogueId = 51011201,
          GUID = "7FB3812A",
          NextDialogue = 51011202,
          SpeakNpcId = 700339
        },
        [51011202] = {
          ContentKR = "(소녀는 말없이 창밖을 바라본다. 그녀의 시선은 끝없이 펼쳐진 하늘 저편, 어디론가를 더듬는 듯하다.)",
          DialogueId = 51011202,
          GUID = "7FB38154",
          NextDialogue = 51011203
        },
        [51011203] = {
          ContentKR = "(그녀에게선 또래답지 않은, 정체되고 낡아가는 듯한 기운이 풍긴다.)",
          DialogueId = 51011203,
          GUID = "7FB3817E",
          NextOptions = {
            [1] = 51011204,
            [2] = 51011220
          }
        },
        [51011204] = {
          ContentKR = "말을 건다.",
          DialogueId = 51011204,
          GUID = "7FB381A8",
          NextDialogue = 51011205
        },
        [51011205] = {
          ContentKR = "(그녀가 금방이라도 돌이킬 수 없는 일을 저지를까 봐 걱정이 된 걸까, 아니면 그녀가 찾고 있는 것에 호기심이 생긴 걸까? 일단 그녀에게 말을 걸어 보자.)",
          DialogueId = 51011205,
          GUID = "7FB381D2",
          NextDialogue = 51011206
        },
        [51011206] = {
          ContentKR = "안녕?",
          DialogueId = 51011206,
          GUID = "7FB381FC",
          NextDialogue = 51011207,
          SpeakNpcId = 100001
        },
        [51011207] = {
          ContentKR = "......",
          DialogueId = 51011207,
          GUID = "7FB38226",
          NextDialogue = 51011208,
          SpeakNpcId = 700339
        },
        [51011208] = {
          ContentKR = "......",
          DialogueId = 51011208,
          GUID = "7FB38250",
          NextDialogue = 51011209,
          SpeakNpcId = 100001
        },
        [51011209] = {
          ContentKR = "할 말이 있는 거면 그냥 얘기해.",
          DialogueId = 51011209,
          GUID = "7FB3827A",
          NextDialogue = 51011210,
          SpeakNpcId = 700339
        },
        [51011210] = {
          ContentKR = "별거 아냐, 그냥 계속 먼 곳을 보고 있길래. 뭘 찾고 있기라도 한 거야?",
          DialogueId = 51011210,
          GUID = "7FB382A4",
          NextDialogue = 51011211,
          SpeakNpcId = 100001
        },
        [51011211] = {
          ContentKR = "글쎄... 아무 데도 보고 있지 않은 걸 수도 있잖아?",
          DialogueId = 51011211,
          GUID = "7FB382CE",
          NextDialogue = 51011212,
          SpeakNpcId = 700339
        },
        [51011212] = {
          ContentKR = "그냥... 무의미하게 시간을 보내는 것뿐이야.",
          DialogueId = 51011212,
          GUID = "7FB382F8",
          NextOptions = {
            [1] = 51011213,
            [2] = 51011215
          },
          SpeakNpcId = 700339
        },
        [51011213] = {
          ContentKR = "나도 가끔 이렇게 멍하니 시간을 보낼 때면 마음이 차분해지더라고.",
          DialogueId = 51011213,
          GUID = "7FB38322",
          ImprPlusId = 1004,
          NextDialogue = 51011214
        },
        [51011214] = {
          ContentKR = "'가끔'이라... 나랑은 많이 다르구나.",
          DialogueId = 51011214,
          GUID = "7FB3834C",
          NextDialogue = 51011217,
          SpeakNpcId = 700339
        },
        [51011215] = {
          ContentKR = "좀 다른 얘기를 해볼까? 음... 저녁엔 뭐 먹을 생각이야?",
          DialogueId = 51011215,
          GUID = "7FB38376",
          ImprPlusId = 1001,
          NextDialogue = 51011216
        },
        [51011216] = {
          ContentKR = "아무거나... 제대로 된 대답이 아니라는 건 알지만, 딱히 먹고 싶은 음식이 없어.",
          DialogueId = 51011216,
          GUID = "7FB383A0",
          NextDialogue = 51011217,
          SpeakNpcId = 700339
        },
        [51011217] = {
          ContentKR = "(소녀는 말없이 고개를 푹 숙인다.)",
          DialogueId = 51011217,
          GUID = "7FB383CA",
