          NextDialogue = 51011404,
          SpeakNpcId = 700340
        },
        [51011404] = {
          ContentKR = "응?",
          DialogueId = 51011404,
          GUID = "7FB3A278",
          NextDialogue = 51011405,
          SpeakNpcId = 100001
        },
        [51011405] = {
          ContentKR = "난간 아직 안 닦았어. 거기 서 있지 마.",
          DialogueId = 51011405,
          GUID = "7FB3A2A2",
          NextDialogue = 51011406,
          SpeakNpcId = 700340
        },
        [51011406] = {
          ContentKR = "(소년의 불안한 눈빛이 향하는 곳을 따라가 보니, 계단 난간이 눈에 들어온다. 낡긴 했지만 반질반질 윤이 나고, 먼지 하나 없이 말끔하다.)",
