        },
        [70010101] = {
          Camera = "240.799805,-19.96875,71.943665,0.000028,-8.199457,146.99736,18.0,100000,false,Manual,2.8",
          ContentKR = "최근 섬의 필토이드들이 점점 더 활발하게 활동하고 있으니, 주민 여러분께서는 언제라도 바다로 대피할 수 있도록 배와 물자를 준비해 두시기 바랍니다.",
          DialogueId = 70010101,
          Duration = 5,
          GUID = "AF435032",
          SpeakNpcId = 102011
        },
        [70010201] = {
          Camera = "299.416992,-190.118652,-59.832947,0.000008,10.199979,140.800186,20.0,100000.0,false,Manual,2.8",
          ContentKR = "주민 여러분께 안내 말씀 드립니다. 휘페르보레아 관리들에게 발각되지 않도록, 낚시 도중 미확인 선박에 다가가지 마세요.\n우리 선조들은 무의미한 전쟁을 피해 이 섬까지 도망쳐 왔습니다. 선조들의 지혜를 믿고, 우리도 이 섬에서의 평화를 지켜나가야 합니다.",
          DialogueId = 70010201,
          Duration = 5,
          GUID = "AF43609A",
          SpeakNpcId = 102012
        },
        [70010301] = {
          Camera = "-364.107666,1506.973633,120.13916,0.000131,13.391685,87.755157,18.0,100000.0,false,Manual,18.0",
          ContentKR = "마을 사람들은 배를 타고 필토이드로 득실거리는 마을을 떠났을 거야. 저 멀리 있는 '천국의 나무'는 그들을 위한 천연 등대가 되겠지.",
          DialogueId = 70010301,
          Duration = 5,
          GUID = "AF437102",
          SpeakNpcId = 102013
        },
        [70010401] = {
          Camera = "-564.918457,-24.525635,71.417542,0.000015,34.991844,0.800468,18.0,1932.963745,false,Manual,2.8",
          ContentKR = "처음 보는 조각상. 이름 모를 신을 모시고 있는 모양이다. 어느 시대의 유물인지 알 수 없다...",
          DialogueId = 70010401,
          Duration = 5,
          GUID = "AF43816A",
          SpeakNpcId = 102014
        },
        [70010501] = {
          Camera = "-33.021576,347.337158,98.72699,0.000062,6.798647,-91.995422,18.0,100000.0,false,Manual,2.8",
          ContentKR = "검날로 새긴 글귀로, 일부 내용만 판독이 가능하다.\n...\n그리오니아의 갈라스는 브렌단 장군을 따라 이곳으로 원정하여, 거짓된 엘리시안의 광신도들을 퇴치하였다. \n...\n모든 수단을 다해 거짓된 신의 흔적을 파괴하라. \n...\n이곳에 남고 싶지만, 섬이 너무 척박하여 머무를 수 있을지 모르겠다. \n...",
          DialogueId = 70010501,
          Duration = 5,
          GUID = "AF4391D2",
          SpeakNpcId = 102015
        },
        [70010601] = {
          Camera = "-1111.150024,-564.398438,447.803864,0.000071,30.199543,17.596375,15.0,100000.0,false,Manual,2.8",
          ContentKR = "거대한 조각상과 양쪽 절벽 가장자리에 남은 건축물로 미뤄보아, 이곳은 오래전에 신전이었던 모양이다.",
          DialogueId = 70010601,
          Duration = 5,
          GUID = "AF43A23A",
          SpeakNpcId = 102016
        },
        [70010701] = {
          Camera = "507.757812,-5157.005371,-457.544922,0.000083,-13.799645,-41.00135,20.0,511.06842,false,Manual,2.8",
          ContentKR = "필토이드의 시체. 아직 온기가 남아있는 것으로 보아, 이곳에서 전투가 벌어진 지 얼마 되지 않은 것 같다.",
          DialogueId = 70010701,
          Duration = 5,
          GUID = "AF43B2A2",
          SpeakNpcId = 102017
        },
        [70010801] = {
          Camera = "454.451172,-463.453125,534.632812,0.000046,-15.999574,138.796616,15.0,100000.0,false,Manual,8.0",
          ContentKR = "채색된 신상은 비록 온전한 상태를 유지하고 있지만, 신상 주변의 파괴된 흔적을 보아 과거 이곳에 약탈이 일어났음을 유추할 수 있다.",
          DialogueId = 70010801,
          Duration = 5,
          GUID = "AF43C30A",
          SpeakNpcId = 102018
        },
        [70010901] = {
          Camera = "-742.34668,128.554199,307.391235,0.000063,-10.999725,71.996475,15.0,100000.0,false,Manual,2.8",
          ContentKR = "연금술에 사용되는 장치인 것 같다. 어째서 신전 유적 안에 있는 걸까.",
          DialogueId = 70010901,
          Duration = 5,
          GUID = "AF43D372",
          SpeakNpcId = 102019
        },
        [70011001] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.8",
          ContentKR = "촬영한 지 십수 년은 족히 된 사진 한 장. 액자의 유리는 닳을 만큼 어루만진 흔적이 역력하다. 사진 속에는 잔잔한 미소를 머금은 채, 산들바람에 머리칼이 살랑이는 한 카론 소녀의 모습이 담겨 있었다.\n사진 뒷면에는 만년필로 적은 '내 딸 헤일리, 스칼렛에서'라는 한 줄의 글이 남겨져 있었다. 생김새가 많이 닮은 건 아니지만, 소녀의 티 없이 맑은 웃음을 보니 왠지 모르게 프시케가 떠올랐다.",
          DialogueId = 70011001,
          Duration = 5,
          GUID = "AF43E3DA",
          SpeakNpcId = 102020
        },
        [70011101] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          ContentKR = "(높은 자료 선반에는 '투숙객'의 자료가 알파벳순으로 깔끔하게 배열되어 있다. 각 자료에는 아이들의 사진 외에도 그들이 히프노스의 집에서 보낸 하루하루가 생생하게 기록되어 있다.)\n\n프시케의 자료\n나이: 17\n증상: 시력과 청력 상실\n\n...\n프시케는 침식 중기에 왔지만, 여전히 씩씩하고 모든 사람에게 따뜻하게 인사했다. 나는 진단 결과에 오류가 있기를 간절히 바랐다. 그래야만 나 자신을 속인 채, 프시케에게 침식이 일어나지 않았고, 그 아이가 원래의 생활로 돌아갈 수 있다고 믿을 수 있을 테니까.\n...\n그 아이는 잠잘 공간을 최소한으로 줄이면서까지 부모님이 방문하며 두고 간 꽃을 전부 침대맡에 놓았다.\n...\n2층의 빈방을 정리했다. 채광이 더 좋아 프시케와 그 아이의 꽃에게 더 좋을 것 같았다.\n...\n프시케는 꽃을 정말 좋아했다. 매일 꽃다발을 꼼꼼하게 정돈하고 다른 아이들에게 나누어주었다. 침식이 아니었더라면 분명 '그리움의 꽃'을 부모님보다 더 잘 가꿀 수 있었을 것이다.\n...\n프시케가 오늘 내게 꽃을 선물했다. 평온하게 웃음 띤 얼굴을 보니 다시... 헤일리가 생각난다...\n...\n장부를 보며 골머리를 앓고 있다가 프시케에게 들켜버렸다. 끈질기게 캐묻는 통에, 결국 사실대로 히프노스의 집 재정에 관한 문제를 알려줄 수밖에 없었다.\n(비고: 최대한 빨리 구매자에게 회신해야겠다. 아이들이 더 걱정하도록 둘 순 없다.)\n...\n프시케가 고택을 청소하기 시작하더니, 내친김에 누군지 모를 녀석에게 방을 빌려주기까지 했다... 그 녀석이 히프노스의 집에서 말썽을 피우지 않았으면 좋겠다.\n...\n<H>프시케가 살고 싶다고 했다. 인간의 신분으로 하루만 더 살 수 있다 해도 좋다면서 말이다. 그 말을 듣고 나는 기쁘면서도 화가 났다.\n그 아이가 드디어 속마음을 토로했다는 것에 기뻤다. 프시케는 너무 오래 강한 척, 아무렇지 않은 척했다.\n화가 난 이유는 그 녀석 때문이다! 그 녀석이 프시케에게 뭘 했는지는 모르겠지만, 죽을 사람에게 살아갈 용기를 주다니, 너무 잔인하다.\n구할 수 없다면 무의미한 희망도 주지 말아야 할 게 아닌가!</>\n...\n(비고: 하지만 그게 정말 프시케의 소원이라면… 침식 억제제 연구를 좀 더 빨리 완료해야겠다. 프시케를 위해, 그 아이들을 위해...)</>",
          DialogueId = 70011101,
          Duration = 5,
          GUID = "AF43F442",
          SpeakNpcId = 102021
        },
        [70011201] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          ContentKR = "아이크의 자료\n나이: 19\n증상: 실명\n아이크는 홀로 히프노스의 집에 왔다. 그의 부모가 아이크의 운명을 견디지 못한 건지 아니면 단순히 매정했던 건지는 확실하지 않지만, 시각 장애가 있는 아이를 혼자서 아이스레이크 시티에 오게 하다니 놀라운 일이다.\n...\n아이크는 책을 읽고 싶다고 했지만 내가 가진 건 그냥 지루하고 긴 의학 서적뿐이었다. 하지만 아이는 신경 쓰지 않고, 매일 내 옆에 앉아서, 내가 읽어주는 내용을 들었다.\n...\n아이크가 잠꼬대로 아버지의 이름을 부르는 것을 들었다.\n...\n플래그슨 주에서 아이크의 아버지를 찾아냈지만, 그는 날 알아채지 못했다. 그는 자장가를 흥얼거리며 팔에 아닌 솔라 아기를 재우느라 여념이 없었다.\n...\n점자로 쓰인 책을 몇 권 샀다. 아이크는 너무나 행복한 표정으로 \"고마워요, 아버지.\"라고 말했다. 날 아버지라고 부르지 말라고 말하려고 했지만 결국 \"음\" 하고만 대답하고 서둘러 병동을 빠져나왔다.\n...",
          DialogueId = 70011201,
          Duration = 5,
          GUID = "AF4404AA",
          SpeakNpcId = 102022
        },
        [70011301] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          ContentKR = "로비의 자료\n나이: 18\n증상: 골형성부전증\n로비가 히프노스의 집에 왔을 때는 온몸이 붕대로 감긴 채였다. 작은 충격만으로도 심각한 골절을 일으킬 수 있었고, 침대에서 일어나는 것조차 힘든 상태였다.\n...\n아이가 햇볕을 더 많이 쬘 수 있도록 침대를 창문으로 옮겼다.\n...\n재활 훈련은 성공적이었다. 레나의 요리가 로비에게 충분한 영양을 제공해서, 로비는 이제 지팡이를 짚고 히프노스의 집을 돌아다닐 수 있게 되었다.\n...\n오늘 로비의 다리가 또 부러졌다. 이곳에 도착했을 때보다 더 심각했다. 아이는 날 귀찮게 하지 않으려고 계단에서 넘어졌을 때도 큰 소리로 부르지 않았다... 최근에 내 표정이 너무 안 좋아서, 아이들이 오히려 날 걱정하기 시작한 것 같다.\n...\n로비가 프시케를 위한 보답으로 꽃을 따오고 싶다고 해서 그러라고 했다. 결국 찾아낸 건 마른 가지 몇 개뿐이었지만, 아이의 얼굴은 행복한 미소로 가득했다.\n...",
          DialogueId = 70011301,
          Duration = 5,
          GUID = "AF441512",
          SpeakNpcId = 102023
        },
        [70011401] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          ContentKR = "조세핀의 자료\n나이: 17\n증상: 장기 변형, 호흡곤란\n침식의 각인이 조세핀의 목에 나타났다. 아이가 너무 활발하게 뛰어다니는 모습을 보니 오히려 안 좋은 예감이 든다.\n...\n조세핀이 갑자기 숨을 헐떡이며 쓰러졌다. 전신 검진 결과는 아주 나빴다. 장기가 심하게 변형되어 앞으로 며칠간 수술실에만 있어야 한다.\n...\n아이의 상태가 조금 나아졌지만, 인공호흡기를 뗄 수 없다. 잠자는 동안 무슨 일이 일어나지 않도록, 매일 밤 아이의 침대 옆에 머물며 호흡기를 단단히 고정하고 땀을 닦아주어야 할 듯하다. 다행히 커피는 여유가 있으므로 견딜 수 있다.\n...",
          DialogueId = 70011401,
          Duration = 5,
          GUID = "AF44257A",
          SpeakNpcId = 102024
        },
        [70011501] = {
          Camera = "589.100586,92.850586,87.400391,0.000028,0.0,-178.390396,22.0,400.0,false,DoNotOverride,2.8",
          ContentKR = "악천후의 영향으로 도시 외곽의 1번 국도에서 심각한 전복 사고가 발생했습니다. 현재 제6군단 휘하 방위대가 긴급 보수 작업을 진행 중이니, 시민 여러분께서는 외출을 자제하시고 외출 시 미끄럼 방지를 위한 조치를 취해 주시기 바랍니다.",
          DialogueId = 70011501,
          Duration = 5,
          GUID = "AF4435E2",
          SpeakNpcId = 102025
        },
        [70011601] = {
          Camera = "-83.132812,-721.489746,92.419189,0.000006,-0.600217,80.994888,20.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "굳게 닫힌 대문이 광갱으로 드나드는 길을 가로막고 있고, 귓가에 들려오는 차가운 기계음이 광갱이 처음 폐쇄될 때의 방송을 간헐적으로 반복하고 있다.\n...\n월석 광맥이 고갈되어... 금일부터 폐기 상태로 분류됩니다... 군단에서는 더 이상 안전을 보장하지 않습니다... 강제 진입 시 발생한 사고에 대해 책임지지 않습니다...",
          DialogueId = 70011601,
          Duration = 5,
          GUID = "AF44464A",
          SpeakNpcId = 102026
        },
        [70011701] = {
          ContentKR = "차가운 기계음이 군단이 광부를 이송할 때의 방송을 반복한다.\n\n제6군단 주둔 부대는 명단에 있는 광부를 플래그슨 주로 호송하여 관련 업무를 계속 수행할 예정입니다. 이송 열차는 글로스터 광갱 폐쇄 3시간 전, 정시에 출발할 예정이오니, 명단에 있는 광부 여러분께서는 다음 사항을 유의하시기 바랍니다.\n1. 소지품의 무게가 5000g을 초과하는 자는 총살될 수 있습니다.\n2. 규정된 시간에 탑승하지 않는 자는 총살될 수 있습니다.\n3. 명단에 의문을 제기하는 자는 총살될 수 있습니다.",
          DialogueId = 70011701,
          Duration = 5,
          GUID = "AF4456B2",
          SpeakNpcId = 102027
        },
        [70011801] = {
          Camera = "-415.066528,-79.582031,152.246094,0.000006,0.599875,-0.799286,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(세월의 흔적이 묻어 있는 오래된 단체 사진. 평민, 부유한 상인, 심지어 내성의 관리들까지 모여 새 가게를 축복하던 아스포델의 개업 당시의 화려함이 느껴진다.)",
          DialogueId = 70011801,
          Duration = 5,
          GUID = "AF44671A",
          SpeakNpcId = 102028
        },
        [70011901] = {
          Camera = "-652.218567,-446.646545,311.657959,0.000055,7.500012,42.603733,10.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(제국 어디서나 볼 수 있는 대형 포스터. \"황제 폐하께 영광을\" 등의 표어가 적혀있다.)",
          DialogueId = 70011901,
          Duration = 5,
          GUID = "AF447782",
          SpeakNpcId = 102029
        },
        [70012001] = {
          Camera = "251.815674,-114.571671,67.927124,0.000047,-3.399658,170.391632,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "다음 기수의 제6군단 선발 심사(카론 전용) 예정. 신청 조건을 충족하는 카론은 치안서에서 직접 서류를 작성할 것. \n운명의 시간이 다가왔다. 블랙 울프의 깃발 아래 율리우스 폐하의 이름을 외치고 휘페르보레아 제국에 충성을 바쳐라! \n\n주의 사항: \n\n1. 심사에서 뛰어난 성적을 거둔 자는 계관카론 훈장을 수여받으며, 내성에 입주할 자격을 얻는다. \n2. 계관카론 훈장을 수여받지 못하였으나 뛰어난 성적을 거둔 자는 외성 방위대에 편입되어 복무하게 된다. \n3. 평가의 최종 해석권은 제6군단 코퀴투스 주 주둔군에 있으며, 평가 도중 발생하는 모든 사고에 대한 책임은 본인이 부담한다.",
          DialogueId = 70012001,
          Duration = 5,
          GUID = "AF4487EA",
          SpeakNpcId = 102030
        },
        [70012101] = {
          Camera = "-413.806396,24.681641,230.520782,0.000089,-29.19894,-18.408882,35.0,400.0,false,DoNotOverride,2.8",
          ContentKR = "저장 탱크에 '액체 폭시코르'라는 문구가 적혀 있다. 제국의 교통 시설, 조명 등 많은 물건에서 이 단어를 볼 수 있는데, 이름으로 판단컨대 월석에서 파생된 어떤 산물인 것 같다.",
          DialogueId = 70012101,
          Duration = 5,
          GUID = "AF449852",
          SpeakNpcId = 102031
        },
        [70012201] = {
          Camera = "-829.676514,67.595215,115.704071,0.000047,28.996904,-8.414193,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "시곗바늘이 12시를 지날 때마다 시계판 위에 토드 웨일즈라는 이름이 잠깐 떠오른다. 기계 기술과 광학 원리를 결합해서 자신의 이름을 작품에 은밀하게 남긴 것을 보면, 웨일즈 씨는 뛰어난 시계 제작자인 것이 틀림없다.",
          DialogueId = 70012201,
          Duration = 5,
          GUID = "AF44A8BA",
          SpeakNpcId = 102032
        },
        [70012301] = {
          Camera = "576.424805,22.139282,190.283051,0.000035,-16.800291,175.187546,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(차량에 다가가자 흥분된 고함 소리가 들린다. \"이야, 너도 PRT20A에 관심이 있구나? 하긴 당연하지! 군용에서 민간용으로 전환된 이 2세대 소형 자동차는 폭시코르 휠을 탑재하고 있는 데다, 수많은 이들로부터 전승된 지혜의 결정체니까! 군용에 비하면 속도는 떨어지지만 폭시코르 휠의 굉음을 들으며 운전을 할 수 있는 것 자체로도 고귀함의 상징이란 말이지...\" 그는 이 차량의 역사부터 구조, 폭시코르 휠, 차체, 심지어 타이어의 무늬까지 쉬지 않고 이야기한다. 탱크, 터닝 등 알 수 없는 단어들이 머릿속을 어지럽히는 가운데, 귓가에 갑자기 정적이 찾아온다. 고개를 들어 주위를 둘러보니, 그 열정에 찬 마니아는 이미 다른 불쌍한 행인에게 달려가 차량에 대해 설명하고 있다.)",
          DialogueId = 70012301,
          Duration = 5,
          GUID = "AF44B922",
          SpeakNpcId = 102033
        },
        [70012401] = {
          Camera = "-712.020264,-289.200195,10.626465,0.000082,16.793509,22.182402,10.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "높게 세워진 기념비. 뒷면에는 제국인들의 이름이 가득 적혀 있고, 앞면에는 짧은 문구가 또렷하게 새겨져 있다.\n\n이 땅의 유구한 평화를 위해 용감하게 희생한 군인들을 기리며 \n황제 폐하께 영광을",
          DialogueId = 70012401,
          Duration = 5,
          GUID = "AF44C98A",
          SpeakNpcId = 102034
        },
        [70012501] = {
          Camera = "-593.807617,-151.208984,181.682983,0.000059,-13.99979,25.798237,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(아이스레이크 시티에서 채광 램프와 곡괭이, 광차를 몇 번째로 보는 건지 모르겠다. 방대한 양의 채광 도구들을 통해 과거 월석 채굴이 진행되었을 때 도시의 화려함을 엿볼 수 있다. 하지만 이 도구들이 쓰레기통 옆에 버려져 먼지가 가득 쌓인 것을 보면 광부들의 영광은 이미 과거의 일이 되었다는 것을 누구나 알 수 있다.)",
          DialogueId = 70012501,
          Duration = 5,
          GUID = "AF44D9F2",
          SpeakNpcId = 102035
        },
        [70012601] = {
          Camera = "-429.546875,-25.467529,208.017578,0.000075,25.39749,-29.411985,20.0,100000.0,false,Manual,2.8",
          ContentKR = "공장의 거대한 그림자가 도시를 뒤덮으며, 마치 개미를 내려다보는 거인처럼 나약한 생명체를 자신의 그림자 아래 가두고, 매일 수천 명의 노동자가 그 안으로 들어가고 나온다. 수백 미터 밖에서도 거인의 멈추지 않는 굉음을 들을 수 있다.",
          DialogueId = 70012601,
          Duration = 5,
          GUID = "AF44EA5A",
          SpeakNpcId = 102036
        },
        [70012701] = {
          Camera = "7.69043,-170.557617,63.654785,0.0,0.0,-89.999939,10.0,100000.0,false,DoNotOverride,2.24",
          ContentKR = "봉쇄된 바리케이드는 아무도 통행할 수 없다. 바리케이드 옆의 눈에 띄는 알림으로 보아, 전방 지역은 제6군단 방위대가 접수한 모양이다.",
          DialogueId = 70012701,
          Duration = 5,
          GUID = "AF44FAC2",
          SpeakNpcId = 102037
        },
        [70012801] = {
          Camera = "902.932129,1093.807129,22.332031,0.000012,7.59978,-122.402924,35.0,100000.0,false,Manual,2.8",
          ContentKR = "액체 폭시코르로 가동하는 난방 시설. 옆에 앉으면 마음까지 따뜻해지는 것 같다. 다만, 위치와 조악한 설치 공법으로 볼 때, 민간의 비전문가가 설치한 것으로 보인다. 제국 정부 입장에서 카론을 위해 난방 시설을 제공한다는 것은 전혀 무의미한 행위이기 때문이다.",
          DialogueId = 70012801,
          Duration = 5,
          GUID = "AF450B2A",
          SpeakNpcId = 102038
        },
        [70012901] = {
          Camera = "538.746094,139.100586,83.406647,0.000042,-10.399529,-172.984406,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "카론을 경멸하는 내용이 지저분한 스프레이 페인트로 빽빽하게 쓰여 있다.",
          DialogueId = 70012901,
          Duration = 5,
          GUID = "AF451B92",
          SpeakNpcId = 102039
        },
        [70013001] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.27",
          ContentKR = "새 한 마리만 들어갈 수 있을 정도로 작은 무덤. 묘비에는 이름 대신 다음과 같은 문구가 적혀 있다.\n\"나의 영원한 동료이자 나의 생명을 구한 영웅, 이곳에 잠들다. —— 코논\"",
          DialogueId = 70013001,
          Duration = 5,
          GUID = "AF452BFA",
          SpeakNpcId = 102040
        },
        [70013101] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.28",
          ContentKR = "노란빛이 은은하게 나는 뜨개가방. 모서리가 볼록한 것을 보아 월석이 가득 차 있음을 알 수 있고, 주머니 밑부분에 붉은 핏자국이 있다.",
          DialogueId = 70013101,
          Duration = 5,
          GUID = "AF453C62",
          SpeakNpcId = 102041
        },
        [70013201] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.29",
          ContentKR = "블록 장난감\n(간단한 블록. 한때 아이들 사이에서 유행했던 스타일이지만, 지금 기준으로는 다소 구식인 듯하다.)",
          DialogueId = 70013201,
          Duration = 5,
          GUID = "AF454CCA",
          SpeakNpcId = 102042
        },
        [70013301] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.30",
          ContentKR = "프시케의 방\n(문에는 녹색 나비 그림판이 걸려 있고, 어린아이의 낙서 같은 필체로 '프시케의 방'이라고 적혀 있다. 아마 프시케가 살던 곳일 것이다. 다만 지금은 문이 잠겨 있는데, 아마도 어머니인 데이지의 뜻에 따른 것으로 보인다.)",
          DialogueId = 70013301,
          Duration = 5,
          GUID = "AF455D32",
          SpeakNpcId = 102043
        },
        [70013401] = {
          Camera = "-274.459961,499.943848,20.897705,0.000001,4.999999,-79.999969,16.0,100000.0,false,Manual,2.8",
          ContentKR = "('룩스 갤러어'라는 이름의 옷 가게 쇼윈도 너머로 우아한 롱 드레스가 보인다. 각 원단의 딱 맞게 사용되어, 착용자의 아름다운 몸매와 우아한 분위기를 강조해 주며, 하란의 체형에 완벽하게 어울린다.)",
          DialogueId = 70013401,
          Duration = 5,
          GUID = "AF456D9A",
          SpeakNpcId = 102044
        },
        [70013501] = {
          Camera = "36.606445,286.352539,23.979492,0.000003,-8.400025,-108.599854,15.0,100000.0,false,Manual,2.32",
          ContentKR = "(리오 옆에 양동이, 걸레 등의 도구가 놓여 있는데, 아마도 바로 옆의 검붉은 얼룩을 청소하기 위한 용도로 보인다. 이전에 여기에서 끔찍한 충돌이 일어났던 것 같다.)",
          DialogueId = 70013501,
          Duration = 5,
          GUID = "AF457E02",
          SpeakNpcId = 102045
        },
        [70013601] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.33",
          ContentKR = "낡고 누렇게 변색된 포스터. 내용을 간신히 알아볼 수 있다.\n\n...\n최고의 가수 비올레타의 공연이 다음 주에 시작됩니다!\n<설국의 아이들> 클래식의 재현, 천상의 노래가 아이스레이크 시티에 울려 퍼집니다!\n단 일주일! 이번 기회를 절대 놓치지 마세요!\n돈만 내시면 내성에 슬쩍 들여보내 드립니다! 엘리트만을 위한 음악의 향연을 경험하세요!\n...\n연락책: 미스터 잭\n접선 방법: 매일 심야 하수도 맨홀 뚜껑 옆에서 접선. 붉은 머리카락의 남자에게 암호 '뻐꾹뻐꾹'을 말할 것.",
          DialogueId = 70013601,
          Duration = 5,
          GUID = "AF458E6A",
          SpeakNpcId = 102046
        },
        [70013701] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.34",
          ContentKR = "(너덜너덜해진 교과서. 빈 공간이 투박한 낙서로 가득하다. 이 낙서에서 페이는 사악한 흑마법을 사용하는 뿔 달린 악마로 묘사된다.)",
          DialogueId = 70013701,
          Duration = 5,
          GUID = "AF459ED2",
          SpeakNpcId = 102047
        },
        [70013801] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.35",
          ContentKR = "이따금 히프노스의 집에서 진지한 표정의 여성과 마주칠 때가 있다. 그녀는 정기적으로 히프노스의 집을 찾아와 청소를 하고, 아이들을 위해 따뜻한 식사를 만들어 주는 모양이다.\n\n누군가 사정을 물으면, 그녀는 \"헨릭 씨가 절 고용했으니, 전 그분을 위해 일해야 해요. 이 일은 원래 그런 법이죠.\"라고 대답하곤 한다.\n\n그녀는 이 상황을 매우 안타깝게 느끼는 것 같았고, 사람들도 눈치껏 더는 캐묻지 않았다.\n\n그렇지만 히프노스의 집 아이들 모두, 레나 아주머니가 헨릭에게서 단 한 푼의 보수도 받지 않았다는 사실을 알고 있다.",
          DialogueId = 70013801,
          Duration = 5,
          GUID = "AF45AF3A",
          SpeakNpcId = 102048
        },
        [70013901] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.36",
          ContentKR = "(온갖 종류의 고물들이 모여 있어, 마틴이 어떤 기준으로 이 물건들을 선택했는지 알 수 없다. 이 물건들의 전 주인은 누구였을까?)",
          DialogueId = 70013901,
          Duration = 5,
          GUID = "AF45BFA2",
          SpeakNpcId = 102049
        },
        [70014001] = {
          Camera = "-394.105225,225.10498,147.011475,0.00004,-19.999113,-46.394775,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(카밀라가 수취를 거절한 술. 앞으로 어디로 유통될지 알 수 없다.)",
          DialogueId = 70014001,
          Duration = 5,
          GUID = "AF45D00A",
          SpeakNpcId = 102050
        },
        [70014101] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.38",
          ContentKR = "발자국\n(아이 발만 한 크기. 바크가 들은 발자국 소리의 출처는 여기인 것 같다.)",
          DialogueId = 70014101,
          Duration = 5,
          GUID = "AF45E072",
          SpeakNpcId = 102051
        },
        [70014201] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.39",
          ContentKR = "팝콘\n(범인의 가방에 작은 구멍이 나서, 팝콘이 길을 따라 떨어진 모양이다. '진한 과일 냄새'... 그랬군.)",
          DialogueId = 70014201,
          Duration = 5,
          GUID = "AF45F0DA",
          SpeakNpcId = 102052
        },
        [70014301] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.40",
          ContentKR = "허름한 텐트. 벨린다의 거처로, 이곳에서 상담해 주는 가게를 운영하고 있다고 한다. 간판도, 명확한 상담 범위도 없으며, 오가는 손님들에겐 말 못 할 사정이 있는 것 같다.",
          DialogueId = 70014301,
          Duration = 5,
          GUID = "AF460142",
          SpeakNpcId = 102053
        },
        [70014401] = {
          Camera = "-277.21875,1095.014038,199.530029,0.000023,24.997671,-88.593628,15.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "액체 폭시코르로 가동되는 거대한 기중기. 공학 아카데미의 개량 덕분에, 작업자가 안에서 조작할 필요 없이, 조종실에서 레버만 당기면 여러 대의 기중기를 움직일 수 있어, 작업 효율이 크게 향상됐다. 하지만 이러한 변화로 인해, 어린 시절 거대한 기중기를 좋아했던 소년들의 꿈과 수많은 노동자의 일자리가 사라졌다.",
          DialogueId = 70014401,
          Duration = 5,
          GUID = "AF4611AA",
          SpeakNpcId = 102054
        },
        [70014501] = {
          Camera = "-553.419922,-854.08313,145.091064,0.000012,-2.200284,52.400944,20.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(라벨로 볼 때, PRT05MV라는 군용 굴착차인 듯하다. 바람과 태양에 노출되어 녹슨 자국이 세월의 흔적을 보여준다. 관리도 수거도 하지 않은 채 놓여 있는데, 차량 보안에 대한 제국의 자신감인지, 아니면 이 폐차에 접근하려는 모든 생물이 군단의 위엄에 압도되어 한 걸음 뒤로 물러나 버리는 것인지는 알 수 없다.)",
          DialogueId = 70014501,
          Duration = 5,
          GUID = "AF462212",
          SpeakNpcId = 102055
        },
        [70014601] = {
          Camera = "18.892578,-214.330688,159.580475,0.000026,-31.400263,99.99868,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(오래된 신문지로 감싼 곰팡이 핀 호밀빵. 빵은 이미 먹을 수 없지만, 신문을 펼쳐 곰팡이를 닦아내면 십여 년 전의 오래된 신문이라는 것을 간신히 알아볼 수 있으며, 그 위에는 제6군단이 글로스터 광갱의 기존 사업주와 합의했다는 관련 보도가 실려 있다.)\n...\n광부들의 이익과 아이스레이크 시티의 발전을 위해 <H>글로스터 광갱은 오늘부로 민간 채굴을 멈추고 군단에 이관된다.</>\n...\n(보도와 함께 게재된 축하 행사 사진 몇 장도 있지만, 이상하게도 잿빛 사진에는 계약서를 든 장교와 환호하는 노동자만 보일 뿐, 광갱의 기존 사업주는 찾을 수 없다. 이 장면을 보고 싶지 않은 건지, 아니면 다시는 볼 수 없게 된 건지는 알 수 없다.)",
          DialogueId = 70014601,
          Duration = 5,
          GUID = "AF46327A",
          SpeakNpcId = 102056
        },
        [70014701] = {
          ContentKR = "구겨진 편지. 필체로 보아 손으로 쓴 것이 아니라 대량 인쇄된 것으로 보인다. \n\n\n제국의 시민들에게\n\n짐은 휘페르보레아의 창건자이자, 그대들의 가장 위대한 황제 디스 1세다. 이 서신은 황성 디즈마니아에서 작성하고 있노라. 그렇다. 짐은 죽지 않았으며, 비술을 통해 살아남았노라.\n짐은 엘리시안을 향한 위대한 여정을 재개하고자 하노라. 허나, 전쟁 자금이 모두 아이스레이크 시티에 있고, 짐의 몸이 불편하여 직접 가지러 갈 수가 없구나. \n만약 그대들에게 제국인의 영광과 끓는 피가 남아 있다면, 지원 자금을 제국 수도 개선대로 233호로 보내주기 바란다. 짐의 몸이 회복되어 모든 전쟁 자금을 회수한 후에는 반드시 두 배로 돌려줄 것을 약속하노라.\n전쟁은 일촉즉발의 상황이니 지체하지 말지어다! 그대들의 지원 자금을 기다리고 있겠다! 때가 되면 번개와 같이 돌아오겠노라!",
          DialogueId = 70014701,
          Duration = 5,
          GUID = "AF4642E2",
          SpeakNpcId = 102057
        },
        [70014801] = {
          Camera = "-233.383423,129.945312,39.479553,0.000071,26.799578,-19.787138,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아이스레이크의 이야기라는 발효 음료. 월석과 비슷한 빛깔을 띠며, 밸브를 돌리면 잔 하나를 가득 채울 수 있다. 한 모금 마시면 아이스레이크를 스치는 차가운 바람 같은 박하의 상쾌함이 입안에 감돈다. 그다음엔 눈부셨던 월석 채굴 사업의 영광을 느끼게 하는 달콤한 목 넘김이 느껴진다. 마지막으로 진흙과 석탄의 쌉싸름한 맛이 오장육부를 가득 채우며 끝없는 여운을 남긴다.\n아이스레이크의 이야기는 그 이름에 걸맞게, 아스포델에서 가장 인기 있는 음료가 될 만하다.",
          DialogueId = 70014801,
          Duration = 5,
          GUID = "AF46534A",
          SpeakNpcId = 102058
        },
        [70014901] = {
          Camera = "144.133301,295.799561,71.270615,0.000111,5.599437,-116.392715,20.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "정교한 톱니바퀴 구조로 이루어져 있으며, 아무리 돌려도 아스포델에는 변화가 생기지 않는다. 하지만 바 뒤쪽에서 들려오는 기계 작동 소리로 미루어 보아 이 톱니바퀴들은 단순한 장식품이 아님을 짐작할 수 있다.\n카밀라가 말했듯이, 상인들은 약간의 이익을 좇다가 교수대에 오르는 일도 생기기도 하니, 아스포델도 그저 발효음료를 파는 것처럼 단순하지 않을지도 모른다.",
          DialogueId = 70014901,
          Duration = 5,
          GUID = "AF4663B2",
          NextDialogue = 70014902,
          SpeakNpcId = 102059
        },
        [70014902] = {
          ContentKR = "카밀라가 말했듯이 상인들은 약간의 이익을 좇다가 교수대에 오르는 일도 생기기도 하니 아스포델도 그저 발효음료를 파는 것처럼 단순하지 않을지도 모른다.)",
          DialogueId = 70014902,
          GUID = "AF4663B3",
          SpeakNpcId = 102059
        },
        [70015001] = {
          Camera = "267.163086,229.933594,218.354156,0.000008,-28.000093,-144.996719,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "제국 시민의 생활에 응용된 대표적인 월석 기술 중 하나. 빛의 밝기는 그저 그렇지만 수명이 길고 비용이 저렴하여, 아이스레이크 시티에서 가장 많이 사용되는 조명이 되었다. 과거 제6군단이 글로스터 광갱을 확장할 때도 이 조명을 많이 사용했다.",
          DialogueId = 70015001,
          Duration = 5,
          GUID = "AF46741A",
          SpeakNpcId = 102060
        },
        [70015101] = {
          Camera = "-293.902832,-246.538574,58.947754,0.000011,22.198734,42.000011,35.0,100000.0,false,Manual,2.8",
          ContentKR = "제국에서 흔히 볼 수 있는 문 위의 장식 스타일이지만, 그 두 개의 작은 사각형을 보고 있자니 뇌리에 \"구경이라도 났어?\"라고 말하는 이상한 얼굴이 자연스럽게 떠오른다.",
          DialogueId = 70015101,
          Duration = 5,
          GUID = "AF46741B",
          SpeakNpcId = 102061
        },
        [70015201] = {
          ContentKR = "해골, 무기, 먹다 남은 음식이 너덜너덜해진 배낭 아래에 깔린 채, 폐광 깊숙한 곳에서 사라져간 월석 사냥꾼들의 최후를 말해 주고 있다.\n배낭은 새것도 있고 오래된 것도 있다. 배낭의 주인들은 자신만은 실패자가 되지 않을 거라 생각하며, 비슷한 목적을 위해 폐광에 들어왔고, 결국 비슷한 비극을 맞이했다.",
          DialogueId = 70015201,
          GUID = "AF4694EA"
        },
        [70015301] = {
          ContentKR = "배낭에 있는 일기장과 이미 광택을 잃은 월석으로 볼 때, 만약 사건이 조금만 늦게 일어났더라면, 배낭의 주인은 더 나은 미래를 맞이할 수 있었을지도 모른다.",
          DialogueId = 70015301,
          GUID = "AF46A552"
        },
        [70015401] = {
          ContentKR = "쓰레기통에 버려진 <아이스레이크 시티 모닝 포스트> 신문. 자세히 들여다보니 글자 몇 개가 잘못 인쇄되어 있어, 아마도 모조품인 것 같다. 펼쳐보니 꽤 충격적인 내용들이 기록되어 있다.",
          DialogueId = 70015401,
          Duration = 5,
          GUID = "AF46B5BA",
          NextDialogue = 70015402,
          SpeakNpcId = 102064
        },
        [70015402] = {
          ContentKR = "모리스 그렌빌의 비밀\n...아이스레이크 시티 시민들은 모두 한순간 빛났다 사라진 그렌빌 가문과 모리스 그렌빌 씨가 생전에 자수성가하여 철강 대부로 올라선 이야기, 그리고 가문 구성원들이 차례로 저주를 받아 미쳐가거나 사고로 죽거나 실종된 이야기를 알고 있다. 하지만 오늘 우리가 이야기하려는 것은 다른 것이다. 왜 그렌빌 씨는 자신의 가난했던 과거를 굳이 남겨두려 했을까?",
          DialogueId = 70015402,
          Duration = 5,
          GUID = "AF46B5E4",
          NextDialogue = 70015403,
          SpeakNpcId = 102064
        },
        [70015403] = {
          ContentKR = "...독자 여러분은 아마 모를 것이다. 모리스가 처음으로 큰돈을 번 것은 그가 소년 시절 이 공학 연금원 고위 관리 밑에서 일할 때였으며, 이 관리는 계관카론이었다. 모리스가 후에 철저한 반카론주의자가 되었다는 사실과 연관 지어 보면, 우리는 소년 시절 모리스와 그의 카론 상사 사이에 틀림없이 무언가 숨겨진 이야기가 있었을 거라고 추측할 수 있다...",
          DialogueId = 70015403,
          Duration = 5,
          GUID = "AF46B60E",
          NextDialogue = 70015404,
          SpeakNpcId = 102064
        },
        [70015404] = {
          ContentKR = "충격! 율리우스 폐하의 진짜 정체는 대역?!\n...당시 신문 보도와 황궁 근무자들의 회고록에는 모두 율리우스 폐하의 즉위 전 언행이 기록되어 있다. 그 당시의 폐하는 의심할 여지 없이 겸손하고 신중하며 우아한 왕자였다. 그렇다면 왜 폐하는 즉위 후 성격이 크게 바뀌었을까? 진실은 단 하나다. 바로... 진짜 폐하는 이미 암살당했고, 지금 발로나 궁전에 앉아 있는 그 황제는 틀림없이 가짜이다!",
          DialogueId = 70015404,
          Duration = 5,
          GUID = "AF46B638",
          NextDialogue = 70015405,
          SpeakNpcId = 102064
        },
        [70015405] = {
          ContentKR = "너무 많은 것을 알게 된 것 같아, 급히 가짜 소식지를 쓰레기통에 다시 던져 넣었다.",
          DialogueId = 70015405,
          Duration = 5,
          GUID = "AF46B662",
          SpeakNpcId = 102064
        },
        [70015501] = {
          Camera = "382.455078,-10.461182,127.896484,0.000083,-5.801112,-108.595062,30.0,96.67099,false,Manual,4.0",
          ContentKR = "촬영한 지 십수 년은 족히 된 사진 한 장. 액자의 유리는 닳을 만큼 어루만진 흔적이 역력하다. 사진 속에는 잔잔한 미소를 머금은 채, 산들바람에 머리칼이 살랑이는 한 카론 소녀의 모습이 담겨 있었다.\n사진 뒷면에는 만년필로 적은 '내 딸 헤일리, 스칼렛에서'라는 한 줄의 글이 남겨져 있었다. 생김새가 많이 닮은 건 아니지만, 소녀의 티 없이 맑은 웃음을 보니 왠지 모르게 프시케가 떠올랐다.",
          DialogueId = 70015501,
          Duration = 5,
          GUID = "AF46C622"
        },
        [70015601] = {
          Camera = "-277.050781,-1.119873,213.634766,0.0,0.0,-179.999985,10.0,100000.0,false,Manual,2.8",
          ContentKR = "일지의 표지에는 간단한 문구가 적혀 있다. \"영혼이 안개의 바다에 편히 잠들기를.\" 두꺼운 일지를 펼치자 익숙한 날짜와 이름들이 보인다.",
          DialogueId = 70015601,
          Duration = 5,
          GUID = "AF46D68A",
          NextDialogue = 70015602
        },
        [70015602] = {
          Camera = "-277.050781,-1.119873,213.634766,0.0,0.0,-179.999985,10.0,100000.0,false,Manual,2.8",
          ContentKR = "...\n9월 3일, 캐롤리나 브라운.\n...\n10월 29일, 헌트 클라크.\n...\n11월 25일, 프시케 프레이.",
          DialogueId = 70015602,
          Duration = 5,
          GUID = "AF46D6B4"
        },
        [70015701] = {
          Camera = "-746.286377,-2980.045654,256.510742,0.000001,14.999996,-44.999969,18.0,100000.0,false,Disable,2.8",
          ContentKR = "월석과 비슷한 색의 수정이다. 하지만 자세히 보면 무늬와 질감이 월석과 완전히 다르고, 그저 평범한 '빛나는 돌'일 뿐이다.",
          DialogueId = 70015701,
          Duration = 5,
          GUID = "AF46E6F2",
          NextDialogue = 70015702
        },
        [70015702] = {
          Camera = "-746.286377,-2980.045654,256.510742,0.000001,14.999996,-44.999969,18.0,100000.0,false,Disable,2.8",
          ContentKR = "인간들은 사용 가치에 따라 광석을 등급별로 나눈다. 월석은 귀중한 자원이지만, 이것들은 쓸모없는 폐품일 뿐이다.\n하지만 바로 이 때문에 모두 채굴되어 분쇄된 후 결국 공장의 차가운 액체 폭시코르가 된 월석과 달리, 이것들은 운 좋게도 온전한 형태로 남아있다.",
          DialogueId = 70015702,
          Duration = 5,
          GUID = "AF46E71C"
        },
        [70016001] = {
          ContentKR = "<H>은촛불 축제</>가 예정대로 갈레아 극장에서 열립니다. 참가자분들은 자신이 원하는 분장을 준비하시고 연기할 신분을 선택해 주세요.\n우리 함께 직업도, 종족도, 갈등도 내려놓고 여기에 모여 황제 폐하의 은총에 몸을 담그고 황제 폐하의 자비로움을 찬양합시다. 황제 폐하께 영광을!",
          DialogueId = 70016001,
          GUID = "AF47182A"
        },
        [70016002] = {
          ContentKR = "두툼한 출석부, 스태프들마다의 하루 일과가 상세하게 기록되어 있다. 리허설 외, 식사와 취침, 심지어 화장실에 다녀온 것까지 전부 기록되어 있다.\n극단장이 독한 마음을 먹고 사람들을 극장 속에 ‘가둔’ 것인지, 아니면 극단장이 자신의 배우들을 보호하기 위해 어쩔 수 없이 그들의 일거수일투족을 지켜보는 것인지 알 수 없다.",
          DialogueId = 70016002,
          GUID = "AF471854"
        },
        [70016003] = {
          ContentKR = "순금으로 만들어진 훈장으로, 편지의 내용에 따르면 제국에 뛰어난 공헌을 한 군인에게만 수여되는 훈장이다.",
          DialogueId = 70016003,
          GUID = "AF47187E"
        },
        [70016004] = {
          ContentKR = "잡동사니들 밑에 깔린 낡은 신문에는 오래 전의 비참한 사고가 기록되어 있다.\n\n<H>침식자는 매우 위험하니 겉모습에 속지 마세요!</>\n9월 24일, 본 시에서 매우 끔찍한 ‘침식’ 사건이 발생했습니다. 제6군단 방위대의 조사를 거쳐 얻어낸 결론은 다음과 같습니다.\n아이스레이크 시티 주민 페실 부부는 9월 13일 눈물의 호수 옆 도로변에서 로비 브라운이라는 청년을 우연히 만났습니다. 페실 부부는 중상을 입은 그를 집으로 데려가 돌보았습니다.\n그러나 로비 브라운은 제국의 잠재적 침식자에 대한 조사를 피해 도시 밖으로 도피한 침식자였고, 페실 부부의 도움을 받을 때 자신의 침식 흔적을 의도적으로 숨겼습니다. 10일 후, 비극이 발생했습니다. 브라운은 필토이드로 변하여 페실 부부를 포함한 아이스레이크 남쪽 구역 시민 수십 명을 살해했습니다. 제6군단 소속 아이스레이크 시티 방위대가 긴급 출동하여 이번 소란을 진압했습니다.\n이번 사태로 총 18명이 사망했고, 그중 3명은 솔라인 것으로 밝혀졌습니다. 그 외 34명이 다쳤습니다. 시민 여러분들, 명심해 주십시오. 신원불명의 카론을 함부로 수용해서는 안 됩니다. 침식자를 발견하게 되면 즉시 치안서에 신고해 주십시오. 그들은 하나도 빠짐없이, 영원히 인간의 적입니다. 의도적으로 침식자에게 협력하거나 침식자를 은폐하는 자는 <휘페르보레아 형사 법전>제 54조에 따라 사형에 처합니다.\n",
          DialogueId = 70016004,
          GUID = "AF4718A8"
        },
        [70016005] = {
          ContentKR = "삐뚤어진 리본이 달린 소박한 선물 상자, 선물 상자 옆에는 제국 최고의 진통제 한 병, 그리고 무슨 이유에서인지 선물 상자에 넣지 못한 쪽지가 있다. 쪽지에는 ‘쾌유하시길 바랍니다.’라는 글귀가 적혀있다.",
          DialogueId = 70016005,
          GUID = "AF4718D2"
        },
        [70016006] = {
          Camera = "-35.015625,151.625,225.035156,0.000034,-14.798724,-71.592674,35.0,100000.0,false,Manual,22.0",
          ContentKR = "(내성 성벽 아래 남매가 함께 찍은 사진, 오른쪽 상단에는 ‘리듬 페실’과 ‘블루스 페실’ 두 이름이 적혀 있으며, 동생 블루스의 제6군단 합격을 축하하는 축사도 적혀 있다.)",
          DialogueId = 70016006,
          GUID = "AF4718FC"
        },
        [70016007] = {
          Camera = "36.316406,112.411133,226.279297,0.00002,-31.198172,-98.592926,35.0,100000.0,false,Manual,22.0",
          ContentKR = "(오랫동안 사용하지 않은 듯한 하모니카, 리듬의 취미라기보다는 어떤 선물에 가깝다.)",
          DialogueId = 70016007,
          GUID = "AF471926"
        },
        [70016008] = {
          ContentKR = "석회벽의 한쪽 구석에는 나이프로 새겨진 글자가 빽빽하게 덮여있다. 어떤 글자는 아이의 필체처럼 삐뚤삐뚤하고, 어떤 글자는 어른의 필체처럼 성숙되어 있다. 글자들은 전부 같은 말이다:\n’더 이상 그 누구도 필토이드에게 죽는 걸 보고만 있지 않겠다.’",
          DialogueId = 70016008,
          GUID = "AF471950"
        },
        [70016009] = {
          ContentKR = "갈레아 극장 소품 목록\n\n여러 스태프들이 기록한 소품 준비 목록, 갈레가 극장에서 지난 반달 동안 사용한 모든 소품의 출입이 상세하게 기록 되어있다.\n\n10월 08일, 의상, 침낭 준비 완료. 확인자: 몬델리 (참고: 식량 비축이 부족하여, <H>남은 한 달간의 집중 리허설을 준비하기 위해선 누군가에게 부탁해서 한 번 더 들여야 한다</>)\n...\n11월 12일, 새로운 마이크 3개 교체 완료. 확인자: 그린델 (참고: 마이크 하나가 소리가 엄청 크다. 푸치 단장님이 그대로 괜찮다고, 바꾸지 말라고 하셨다.)\n11월 14일, 빨간 무대 커튼 교체 완료, 금빛 무대 커튼 창고로 반환 완료. 확인자: 벨\n...\n11월 24일, 잃어버렸던 가발 5개 회수 완료. 확인자: 벨 (참고: 탈의실 구석에 물건이 들어가면 찾기 어렵다. 오늘 가서 한번 치워야겠다.)\n11월 25일, 화관 15개 준비 완료, 승마화 9켤레 준비 완료. 확인자: 몬델리",
          DialogueId = 70016009,
          GUID = "AF47197A"
        },
        [70016010] = {
          ContentKR = "극장 커튼의 재질과 매우 유사한 천으로, 비록 낡았지만 매우 깔끔하게 정리되어 있다. 누군가가 신경 써서 관리한 것이 분명하다.\n\n자세히 관찰하고 만져보면, 이 천이 습격 현장에서 발견된 커튼과 동일한 천이라는 것을 알 수 있다.",
          DialogueId = 70016010,
          GUID = "AF4719A4"
        },
        [70016011] = {
          ContentKR = "마네킹 모델은 비록 오래되었지만, 형태와 자세가 정성스럽게 디자인되어 단정하면서도 우아한 느낌을 풍긴다.",
          DialogueId = 70016011,
          GUID = "AF4719CE"
        },
        [70016012] = {
          ContentKR = "주변에는 거대하고 어지러운 발톱 자국들이 가득하다. 설령 여기가 괴물의 은신처가 아니더라도, 분명 괴물이 자주 활동하는 장소임은 틀림없다. 13군단이 이곳을 봉쇄 구역으로 지정한 이유 중 하나일 것이다.",
          DialogueId = 70016012,
          GUID = "AF4719F8"
        },
        [70016013] = {
          ContentKR = "아이스레이크 시티 하수도 배치도의 일부로, 복잡하게 얽힌 관들이 각 구역을 연결하고 있다. 지도의 많은 구역에 \"방위대 허가 없이 출입 금지\"라는 표시가 돼 있다.",
          DialogueId = 70016013,
          GUID = "AF471A22"
        },
        [70016101] = {
          Camera = "-15.959961,1605.265137,1322.948242,0.000059,-29.399687,-89.596825,20.875948,100000.0,false,Manual,22.0",
          ContentKR = "(포탑 운송 장치의 전원을 복구하려면 네 개의 케이블을 연결해야 한다.)",
          DialogueId = 70016101,
          GUID = "AF472892",
          NextDialogue = 70016102
        },
        [70016102] = {
          Camera = "224.294922,655.639038,672.151611,0.000109,-27.999538,-125.796112,20.875948,100000.0,false,Manual,22.0",
          ContentKR = "(하나는 이미 연결된 상태이다.)",
          DialogueId = 70016102,
          GUID = "AF4728BC",
          NextDialogue = 70016103
        },
        [70016103] = {
          Camera = "-1774.869141,-1374.734619,1171.844727,0.000131,-33.399078,23.004192,20.875948,100000.0,false,Manual,22.0",
          ContentKR = "(나머지 세 개의 케이블을 연결해야 하며, 그것들을 따라가서 회전체를 찾아보자.)",
          DialogueId = 70016103,
          GUID = "AF4728E6"
        },
        [70016104] = {
          Camera = "-5344.007812,-255.292114,647.478394,0.000156,-14.998623,83.199738,20.875948,100000.0,false,Manual,22.0",
          ContentKR = "(이것은 <H>한 세트</>의 회전체이며, <H>특정 시간</> 내에 활성화해야 할 것 같다.)",
          DialogueId = 70016104,
          GUID = "AF472910"
        },
        [70016105] = {
          Camera = "5543.811523,-2108.574219,180.364319,0.000151,-3.998317,-104.994102,20.875948,100000.0,false,Manual,22.0",
          ContentKR = "(들어갈 수 없는 것 같다. <H>멀리서</> 회전체를 활성화할 방법이 있을까?)",
          DialogueId = 70016105,
          GUID = "AF47293A"
        },
        [70016106] = {
          Camera = "157.341797,-91.314453,242.558594,0.0,-60.19952,101.398407,16.122608,100000.0,false,Manual,22.0",
          ContentKR = "(낯선 얼굴이다.)",
          DialogueId = 70016106,
          GUID = "AF472964"
        },
        [70016107] = {
          Camera = "-71.794922,628.722656,135.195312,0.000076,12.199674,-90.596268,17.78793,100000.0,false,Manual,22.0",
          ContentKR = "※ '나르왈' 분대 병사 케일럼의 증언\n\"저는 '그리핀' 소대장 {nickname2}이(가) ▇▇▇▇에서 혼자 나오는 것을 봤습니다. 가슴에 ▇▇▇▇이 있었습니다.\n\"소대장님은 우리에게 중앙 관제실 밖에서 섣불리 움직이지 말라고 지시하며, 자신은▇▇▇▇에 숨은 동맹 멤버가 있는지 확인하러 가 보겠다고 했습니다.\"\n\"약 2분 후 ▇▇▇▇에서 경보음이 들렸고, 펄시 상관과 함께 확인하러 갔습니다. 우리는 '스노우 울프' 분대의 아바르 대장이 피웅덩이에 쓰러져 있는 것을 발견했고, 중앙 관제실의 자폭 모드가 이미 가동된 상태였습니다.\"",
          DialogueId = 70016107,
          GUID = "AF47298E"
        },
        [70016108] = {
          ContentKR = "(병사들은 이미 숨이 멎었다.)",
          DialogueId = 70016108,
          GUID = "AF4729B8"
        },
        [70016109] = {
          ContentKR = "(필토이드의 잔해... 바로 이 괴물들이 병사들의 젊은 생명을 앗아갔다. 하지만 병사들은 마지막 순간에 괴물들에게 치명적인 총격을 남겼다.)",
          DialogueId = 70016109,
          GUID = "AF4729E2"
        },
        [70016110] = {
          Camera = "129.879883,311.569336,152.664062,0.000072,3.399556,-2.996889,17.78793,100000.0,false,Manual,22.0",
          ContentKR = "※ {nickname2}의 가족 관계 조사\n{nickname2}은(는) 3년 전 ▇▇▇▇에서 벌어진 ▇▇▇▇ 사건의 생존자이다. {nickname2}은(는) 기억을 잃었다고 진술했지만, 의식은 명확하고 사고 능력도 우수했다.\n주목할 점은, 사건 당시 다른 생존자들의 증언에 따르면 {nickname2}은(는) 그 ▇▇▇▇에 있을 리 없는 사람이었으니, <H>{性别2:그|그녀}는 진짜 '유령 승객'이다</>.\n당시 13군단은 해당 인물의 신원을 여러 방면으로 조사했지만 실제 신원을 밝혀낼 수 없었으나, ▇▇▇▇일 가능성은 배제되었다. 일각의 추측으로는 지역 주민이 포격을 피하기 위해 ▇▇▇▇에 숨었다가, 강력한 공격으로 인해 뇌 손상을 입어 기억을 잃었을 가능성이 제기되었다.",
          DialogueId = 70016110,
          GUID = "AF47298F"
        },
        [71000000] = {
          ContentKR = "야옹...",
          DialogueId = 71000000,
          Duration = 3,
          GUID = "B1BDB580",
          SpeakNpcId = 800002
        },
        [71000100] = {
          ContentKR = "(외롭게 울고 있는 길고양이가 누군가의 관심을 애타게 기다리고 있다.)",
          DialogueId = 71000100,
          GUID = "B1BDC5E8",
          SpeakNpcId = 800006
        },
        [71000200] = {
          ContentKR = "혹시 여기 고양이 사료 파나요?",
          DialogueId = 71000200,
          GUID = "B1BDD650",
          NextDialogue = 710002001,
          SpeakNpcId = 100001
        },
        [71000210] = {
          ContentKR = "혹시 여기 고양이 사료 파나요?",
          DialogueId = 71000210,
          GUID = "B1BDD7F4",
          NextDialogue = 710002101,
          SpeakNpcId = 100001
        },
        [71000220] = {
          ContentKR = "(고양이 사료를 놓는다)",
          DialogueId = 71000220,
          GUID = "B1BDD998",
          NextDialogue = 710002201,
          SpeakNpcId = 100001
        },
        [71000300] = {
          ContentKR = "(길고양이가 깡충거리며 몇 발짝 달려가더니 멈춰 서서 나를 바라본다. 마치 따라오라는 듯하다.)",
          DialogueId = 71000300,
          Duration = 3,
          GUID = "B1BDE6B8",
          SpeakNpcId = 800006
        },
        [71000310] = {
          ContentKR = "(길고양이가 깡충거리며 몇 발짝 달려가더니 멈춰 서서 나를 바라본다. 마치 따라오라는 듯하다.)",
          DialogueId = 71000310,
          Duration = 3,
          GUID = "B1BDE85C",
          SpeakNpcId = 800006
        },
        [71000320] = {
          ContentKR = "(길고양이가 깡충거리며 몇 발짝 달려가더니 멈춰 서서 나를 바라본다. 마치 따라오라는 듯하다.)",
          DialogueId = 71000320,
          Duration = 3,
          GUID = "B1BDEA00",
          SpeakNpcId = 800006
        },
        [71000330] = {
          ContentKR = "(길고양이가 내 발치를 즐겁게 두 바퀴 돌았다. 만족스러운 표정을 보니 내 마음도 치유되는 것 같다.)",
          DialogueId = 71000330,
          GUID = "B1BDEBA4",
          SpeakNpcId = 800006
        },
        [71000501] = {
          ContentKR = "그만 때리라고, 계속 때리면 비장의 무기를 쓸 거... 좋아, 정 그렇다면... 살려주세요!!",
          DialogueId = 71000501,
          Duration = 3,
          GUID = "B1BE07B2",
          SpeakNpcId = 800005
        },
        [71000502] = {
          ContentKR = "으아아아...",
          DialogueId = 71000502,
          Duration = 3,
          GUID = "B1BE07DC",
          SpeakNpcId = 800005
        },
        [71000503] = {
          ContentKR = "마지막 하나, 끝났어.",
          DialogueId = 71000503,
          GUID = "B1BE0806",
          SpeakNpcId = 818014
        },
        [71000504] = {
          ContentKR = "근처에 적이 더 있나 살펴볼 테니 조심해.",
          DialogueId = 71000504,
          GUID = "B1BE0830",
          NextDialogue = 71000505,
          SpeakNpcId = 818014
        },
        [71000505] = {
          ContentKR = "알겠어, 조심할게!",
          DialogueId = 71000505,
          GUID = "B1BE085A",
          NextDialogue = 71000506,
          SpeakNpcId = 818015
        },
        [71000506] = {
          ContentKR = "어어, 너도 왔구나. 흑흑... 이렇게나 많이들 도와주다니... 이건 모두를 위한 감사 선물이야. 앞으로도 잘 부탁해.",
          DialogueId = 71000506,
          GUID = "B1BE0884",
          Scripts = "TurnTo{TurnToDescription{\"818015:n(0)\"}}",
          SpeakNpcId = 818015
        },
        [71000511] = {
          Camera = "182.995117,-239.510742,101.057129,0.000077,-2.797147,129.385254,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "고마워, 위기는 벗어난 것 같네! 모험을 계속하자.",
          DialogueId = 71000511,
          GUID = "B1BE0956",
          SpeakNpcId = 800005,
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000512] = {
          Camera = "125.800781,-57.036377,76.0,0.000008,0.0,155.202805,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "고마워, 위기는 벗어난 것 같네! 모험을 계속하자.",
          DialogueId = 71000512,
          GUID = "B1BE0980",
          SpeakNpcId = 800005,
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000601] = {
          ContentKR = "(파도에 떠밀려온 나무통들이 해변에 쌓여 있다. 찾아보면 유용한 것들을 발견할 수 있을지도 모른다.)",
          DialogueId = 71000601,
          Duration = 3,
          GUID = "B1BE181A",
          SpeakNpcId = 800006
        },
        [71000612] = {
          ContentKR = "(나무통 바닥에 큰 구멍이 뚫려 있다. 예전에 뭔가 귀중한 것들이 들어있었을지 모르지만, 지금은 쓸모없는 쓰레기일 뿐이다. 다른 나무통을 살펴보자.)",
          DialogueId = 71000612,
          GUID = "B1BE19E8"
        },
        [71000613] = {
          ContentKR = "(나무통 안에는 썩은 생선과 새우 외에는 아무것도 없다. 다른 나무통을 살펴보자.)",
          DialogueId = 71000613,
          GUID = "B1BE1A12"
        },
        [71000615] = {
          ContentKR = "(정성 들여 뒤진 끝에, 드디어 나무통 틈새에서 쓸만한 물자를 발견했다!)",
          DialogueId = 71000615,
          GUID = "B1BE1A66"
        },
        [71000701] = {
          ContentKR = "정말 골치 아프네, 남은 배관이 별로 없는데.",
          DialogueId = 71000701,
          Duration = 3,
          GUID = "B1BE2882",
          SpeakNpcId = 800007
        },
        [71000710] = {
          ContentKR = "무슨 일이죠?",
          DialogueId = 71000710,
          GUID = "B1BE29FC",
          NextDialogue = 71000711,
          SpeakNpcId = 100001
        },
        [71000711] = {
          ContentKR = "거참, 도시의 폭시코르 배관들이 제대로 작동하는지 점검해야 하는데...",
          DialogueId = 71000711,
          Duration = 3,
          GUID = "B1BE2A26",
          NextDialogue = 71000721,
          SpeakNpcId = 800007
        },
        [71000721] = {
          ContentKR = "작업용 로프가 이전 배관 작업을 하다가 끊어졌어. 혹시 남은 배관을 좀 확인해 줄 수 있을까?",
          DialogueId = 71000721,
          Duration = 3,
          GUID = "B1BE2BCA",
          NextOptions = {
            [1] = 710007210,
            [2] = 710007211
          },
          SpeakNpcId = 800007
        },
        [71000741] = {
          ContentKR = "남은 배관의 위치를 표시해 뒀어. 정말 고마워!",
          DialogueId = 71000741,
          Duration = 3,
          GUID = "B1BE2F12",
          SpeakNpcId = 800007
        },
        [71000751] = {
          ContentKR = "(이 배관에는 손상이 없네. 다음 배관을 확인해 보자.)",
          DialogueId = 71000751,
          Duration = 2,
          GUID = "B1BE30B6",
          SpeakNpcId = 800006
        },
        [71000761] = {
          ContentKR = "(마지막 배관도 손상이 없어. 아까 그 작업자에게 가서 알려주자.)",
          DialogueId = 71000761,
          GUID = "B1BE325A",
          SpeakNpcId = 800006
        },
        [71000771] = {
          ContentKR = "모두 괜찮다고? 정말 다행이네! 정말 고마워!",
          DialogueId = 71000771,
          GUID = "B1BE33FE",
          SpeakNpcId = 800007
        },
        [71000780] = {
          ContentKR = "(배관에 약간의 손상이 있다. 작업자에게 알려주자.)",
          DialogueId = 71000780,
          GUID = "B1BE3578",
          SpeakNpcId = 800006
        },
        [71000781] = {
          ContentKR = "하아... 또 야근이네. 내가 공구를 가져올 테니까 이 열쇠로 폭시코르 배관 총밸브를 잠가주지 않겠니?",
          DialogueId = 71000781,
          GUID = "B1BE35A2",
          SpeakNpcId = 800007
        },
        [71000782] = {
          ContentKR = "고마워, 이제 나머지는 내가 할게.",
          DialogueId = 71000782,
          GUID = "B1BE35CC",
          SpeakNpcId = 800007
        },
        [71000801] = {
          ContentKR = "{nickname}! {nickname}! 얼른요! 완전 흥미로운 연구 주제를 찾아냈다고요!",
          DialogueId = 71000801,
          Duration = 3,
          GUID = "B1BE38EA",
          SpeakNpcId = 800011
        },
        [71000802] = {
          ContentKR = "이번 연구에 필요한 재료가 호수 건너편에 있거든요... 도와주실 수 있을까요?",
          DialogueId = 71000802,
          Duration = 3,
          GUID = "B1BE3914",
          NextOptions = {
            [1] = 710008021,
            [2] = 710008022
          },
          SpeakNpcId = 800011
        },
        [71000803] = {
          ContentKR = "이게 테오가 찾던 연구 재료구나. 조금 가져다주자.",
          DialogueId = 71000803,
          Duration = 2,
          GUID = "B1BE393E",
          SpeakNpcId = 100001
        },
        [71000804] = {
          ContentKR = "고마워요! 위대한 연금술사가 되려면... 진짜 배울 게 너무너무 많아요...!",
          DialogueId = 71000804,
          Duration = 2,
          GUID = "B1BE3968",
          SpeakNpcId = 800011
        },
        [71000805] = {
          ContentKR = "...그렇군요. 결국 위대한 연금술사가 되기 위한 첫걸음은... 스스로 연구 재료를 찾아내는 거죠!",
          DialogueId = 71000805,
          GUID = "B1BE3992",
          SpeakNpcId = 800011
        },
        [71000901] = {
          ContentKR = "숨바꼭질, 숨바꼭질, 다 같이 숨바꼭질하자!",
          DialogueId = 71000901,
          Duration = 3,
          GUID = "B1BE4952",
          SpeakNpcId = 800008
        },
        [71000902] = {
          ContentKR = "숨바꼭질, 숨바꼭질, 다 같이 숨바꼭질하자!",
          DialogueId = 71000902,
          GUID = "B1BE497C",
          NextDialogue = 71000903,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"800008:n(0)\"}},LookAt{LookAtDescription{\"800008:n(0)\"}},PlayAnimation{ActorId{800008},AnimationId{\"Explain02_Start\"},Duration{1}}}",
          SpeakNpcId = 800008,
          TurnTo = {
            [1] = "800009:n(0)",
            [2] = "800010:n(0)"
          }
        },
        [71000903] = {
          ContentKR = "좋아! 하지만 난 찾는 거 말고 숨고 싶은데.",
          DialogueId = 71000903,
          Duration = 3,
          GUID = "B1BE49A6",
          NextDialogue = 71000904,
          SpeakNpcId = 800009,
          TalkActionId = {
            [1] = "800009:Explain01_Start"
          }
        },
        [71000904] = {
          ContentKR = "나도. 완전 숨기 좋은 곳을 발견했는데, 거기 숨으면 분명 내가 이길 거야!",
          DialogueId = 71000904,
          Duration = 3,
          GUID = "B1BE49D0",
          NextDialogue = 71000905,
          SpeakNpcId = 800010,
          TalkActionId = {
            [1] = "800010:Talk03_Start"
          }
        },
        [71000905] = {
          ContentKR = "그럼 어떡하지? 같이 숨바꼭질할 사람 없나...",
          DialogueId = 71000905,
          Duration = 3,
          GUID = "B1BE49FA",
          NextDialogue = 71000906,
          SpeakNpcId = 800009
        },
        [71000906] = {
          ContentKR = "(아이들이 지나가는 나를 발견하고는 기대에 찬 눈으로 대답을 기다리고 있다.)",
          DialogueId = 71000906,
          Duration = 3,
          GUID = "B1BE4A24",
          SpeakNpcId = 800006
        },
        [71000907] = {
          ContentKR = "(아이들이 신나서 펄쩍 뛰더니 순식간에 골목 모퉁이로 사라졌다. 이제 이 아이들을 어디서 찾아야 할지 잘 생각해 봐야겠다.)",
          DialogueId = 71000907,
          GUID = "B1BE4A4E"
        },
        [71000908] = {
          ContentKR = "와, 이렇게 빨리 찾아내다니.",
          DialogueId = 71000908,
          GUID = "B1BE4A78",
          SpeakNpcId = 800008
        },
        [71000909] = {
          ContentKR = "정말 대단하세요.",
          DialogueId = 71000909,
          Duration = 2,
          GUID = "B1BE4AA2",
          SpeakNpcId = 800009
        },
        [71000910] = {
          ContentKR = "으악, 내가 지다니...",
          DialogueId = 71000910,
          Duration = 2,
          GUID = "B1BE4ACC",
          SpeakNpcId = 800010
        },
        [71000911] = {
          ContentKR = "알겠어요. 졌으니 인정해야죠. 이건 감사 선물이에요. 다음에 또 우리랑 같이 놀아요!",
          DialogueId = 71000911,
          Duration = 2,
          GUID = "B1BE4AF6",
          SpeakNpcId = 800008
        },
        [71001001] = {
          ContentKR = "(새 차량 한 대. 혹시 이게... 돈 벌 기회일지도?)",
          DialogueId = 71001001,
          Duration = 3,
          GUID = "B1BE59BA",
          SpeakNpcId = 800006
        },
        [71001002] = {
          ContentKR = "(차 안의 폭시코르 에너지 장치가 가득 차 있다. 역시 돈 벌 기회군!)",
          DialogueId = 71001002,
          GUID = "B1BE59E4",
          SpeakNpcId = 800006
        },
        [71001003] = {
          ContentKR = "뭐 하는 거야! 누구 없어요?!",
          DialogueId = 71001003,
          Duration = 2,
          GUID = "B1BE5A0E",
          SpeakNpcId = 818010
        },
        [71001004] = {
          ContentKR = "(이제 아무도 날 막지 않을 것이다. 차 문을 열고 액체 폭시코르로 가득 찬 에너지 장치를 가져가 좋은 값에 팔면 된다. 모든 게 계획대로 진행되었고, 오늘 하루도 기분이 좋다.)",
          DialogueId = 71001004,
          Duration = 4,
          GUID = "B1BE5A38",
          SpeakNpcId = 800006
        },
        [71001005] = {
          ContentKR = "(결국 양심이 유혹을 눌렀다. 차량 보안에 허점이 있음을 성문 경비에게 알리기로 한다.)",
          DialogueId = 71001005,
          Duration = 3,
          GUID = "B1BE5A62",
          SpeakNpcId = 800006
        },
        [71001006] = {
          ContentKR = "알려줘서 고마워. 바로 순찰을 강화해야겠군. 이건 내 성의니 받아줘.",
          DialogueId = 71001006,
          GUID = "B1BE5A8C",
          SpeakNpcId = 818010
        },
        [71001101] = {
          ContentKR = "(필토이드가 몰려옵니다. 물리치세요!)",
          DialogueId = 71001101,
          Duration = 3,
          GUID = "B1BE6A22",
          SpeakNpcId = 800006
        },
        [71001201] = {
          ContentKR = "(당신과 베레가 남긴 흔적 위로 잡초가 무성해졌다. 신상 주변을 정리해 보는 게 좋겠다.)",
          DialogueId = 71001201,
          Duration = 2,
          GUID = "B1BE7A8A",
          SpeakNpcId = 800006
        },
        [71001202] = {
          ContentKR = "(당신의 손길 덕분에 신상 주변이 다시 깔끔해졌고, 기억 속 그 모습으로 되돌아왔다.)",
          DialogueId = 71001202,
          GUID = "B1BE7AB4",
          SpeakNpcId = 800006
        },
        [71001301] = {
          ContentKR = "베레의 말로는 여기가 우리가 살았던 집이라는데, 난 아무것도 기억나지 않아...",
          DialogueId = 71001301,
          GUID = "B1BE8AF2",
          NextDialogue = 71001302,
          SpeakNpcId = 100001
        },
        [71001302] = {
          ContentKR = "주변을 좀 둘러보면 뭔가 떠오를지도 모르겠어.",
          DialogueId = 71001302,
          GUID = "B1BE8B1C",
          SpeakNpcId = 100001
        },
        [71001303] = {
          ContentKR = "가구는 무척 조잡하게 만들어졌고, 못들이 나무 깊숙이 박혀있어. 마을 집 문손잡이처럼. 베레는 어릴 때부터 이렇게 힘이 셌구나.",
          DialogueId = 71001303,
          GUID = "B1BE8B46"
        },
        [71001304] = {
          ContentKR = "이건... 연금술 동화책? 어릴 때 베레가 들려줬던 그 이상한 잠자리 동화들이 전부 이 책에서 나온 거였구나.",
          DialogueId = 71001304,
          GUID = "B1BE8B70",
          NextDialogue = 71001305
        },
        [71001305] = {
          ContentKR = "하지만 책에 적힌 이 메모들은 베레의 글씨체보다 훨씬 반듯한데, 누가 쓴 걸까?",
          DialogueId = 71001305,
          GUID = "B1BE8B9A"
        },
        [71001306] = {
          ContentKR = "베레에 대한 기억은 많이 떠올랐네. 하지만 이곳에 대해서는 아직도 아무것도 기억나지 않아...",
          DialogueId = 71001306,
          GUID = "B1BE8BC4",
          NextDialogue = 71001307,
          SpeakNpcId = 100001
        },
        [71001307] = {
          ContentKR = "됐어, 나중에 자연스럽게 기억나겠지.",
          DialogueId = 71001307,
          GUID = "B1BE8BEE",
          SpeakNpcId = 100001
        },
        [71001401] = {
          ContentKR = "(멀리서도 아이스베리 향이 풍기네요. 몇 개 따서 팔면 좋은 값을 받을 수 있을 텐데요.)",
          DialogueId = 71001401,
          Duration = 4,
          GUID = "B1BE9B5A",
          SpeakNpcId = 800006
        },
        [71001402] = {
          ContentKR = "(이번에 딴 아이스베리는 색도 곱고 과육도 실해서, 이런 특산품이라면 누가 봐도 금방 팔릴 게 분명하다.)",
          DialogueId = 71001402,
          Duration = 4,
          GUID = "B1BE9B84",
          SpeakNpcId = 800006
        },
        [71001403] = {
          ContentKR = "(저 멀리 아이스베리를 수매하는 상인이 둘이 있다. 그들과 이야기를 나눠보고 누구에게 팔지 결정하자.)",
          DialogueId = 71001403,
          Duration = 4,
          GUID = "B1BE9BAE",
          SpeakNpcId = 800006
        },
        [71001404] = {
          ContentKR = "제가 아이스레이크 시티에서 장사한 지도 몇 년은 되었어요. 수익은 적지만 다들 단골이랍니다. 이번 아이스베리는 제가 다 살 테니 이참에 친구가 되는 건 어떨까요. 다들 이 도시에 사는 사람들이니 앞으로 서로 도울 일도 있을 거고요.",
          DialogueId = 71001404,
          GUID = "B1BE9BD8",
          NextOptions = {
            [1] = 710014041,
            [2] = 710014042
          },
          SpeakNpcId = 818002
        },
        [71001405] = {
          ContentKR = "안녕하세요, 아이스베리를 가지고 계시는 것 같은데요. 제가 아이스레이크 시티의 가난한 상인들보다 훨씬 더 많이 쳐줄 수 있는데요. 같이 한몫 벌어보는 게 어때요?",
          DialogueId = 71001405,
          GUID = "B1BE9C02",
          NextOptions = {
            [1] = 710014051,
            [2] = 710014052
          },
          SpeakNpcId = 818003
        },
        [71001406] = {
          ContentKR = "(수익은 적지만 장기적이고 안정적인 인맥을 위해, 결국 현지 상인과 거래를 했다.)",
          DialogueId = 71001406,
          Duration = 3,
          GUID = "B1BE9C2C",
          SpeakNpcId = 800006
        },
        [71001407] = {
          ContentKR = "(미래의 약속보다는 당장의 이익이 더 확실하다. 결국 외지 상인과 거래를 했고, 거액의 수익을 얻었다.)",
          DialogueId = 71001407,
          Duration = 4,
          GUID = "B1BE9C56",
          SpeakNpcId = 800006
        },
        [71001501] = {
          ContentKR = "아이고... 이 망할 물건이 또 고장 났네...",
          DialogueId = 71001501,
          Duration = 3,
          GUID = "B1BEABC2",
          SpeakNpcId = 818006
        },
        [71001502] = {
          ContentKR = "무슨 일이죠?",
          DialogueId = 71001502,
          GUID = "B1BEABEC",
          NextDialogue = 71001503,
          SpeakNpcId = 100001
        },
        [71001503] = {
