        },
        [71005208] = {
          ContentKR = "그래도 아이한테는 말하지 말게. 어린 나이에 가족도 없이 살아가는 가엾은 아이네... 가끔은 거짓이라도, 희망을 주는 것들이 있지 않은가...",
          DialogueId = 71005208,
          GUID = "B1C10B74",
          SpeakNpcId = 818047
        },
        [71005209] = {
          ContentKR = "(소년이 행복 동전을 손으로 만지작거리는 모습을 보고, 당신은 말을 걸었다.)",
          DialogueId = 71005209,
          GUID = "B1C10B9C",
          NextDialogue = 71005210,
          SpeakNpcId = 800006
        },
        [71005210] = {
          ContentKR = "내 왼손에 든 건 행복 동전, 오른손에 든 건 그냥 쿠퍼예요. 뭔가 달라 보이나요?",
          DialogueId = 71005210,
          GUID = "B1C10B9D",
          NextDialogue = 71005211,
          SpeakNpcId = 818048
        },
        [71005211] = {
          ContentKR = "(소년이 두 손을 들어 보이자, 당신은 그것들이 완전히 같은 동전이라는 걸 알 수 있었다.)",
          DialogueId = 71005211,
          GUID = "B1C10B9E",
          NextDialogue = 71005212,
          SpeakNpcId = 800006
        },
        [71005212] = {
          Content = "是呀，幸福硬币就是我们手里的铜币。它不是魔法创造出来的宝贝，而是诞生自大家的善意。",
          DialogueId = 71005212,
          GUID = "B1C10B9F",
          NextDialogue = 71005213,
          SpeakNpcId = 818048
        },
        [71005213] = {
          Content = "一枚幸福硬币就能买到她的笑容，这么轻松的买卖可不多见呀。",
          DialogueId = 71005213,
          GUID = "B1C10BA0",
          SpeakNpcId = 818048
        },
        [71005214] = {
          ContentKR = "어때요? 다들 효과 있다고 하죠?",
          DialogueId = 71005214,
          GUID = "B1C10BC6",
          SpeakNpcId = 818046
        },
        [71005215] = {
          ContentKR = "헤헤~ 정말 어쩔 수 없네요! 그럼 전부 팔게요. 꼭 당신만의 행복을 찾을 수 있길 바랄게요!",
          DialogueId = 71005215,
          GUID = "B1C10BF0",
          SpeakNpcId = 818046
        },
        [71005216] = {
          ContentKR = "스스로... 멋진 말이네요! 저도 나중에 그렇게 될 수 있을까요?",
          DialogueId = 71005216,
          GUID = "B1C10C1A",
          NextDialogue = 71005217,
          SpeakNpcId = 818046
        },
        [71005217] = {
          ContentKR = "물론이지.",
          DialogueId = 71005217,
          GUID = "B1C10C1B",
          NextDialogue = 71005218,
          SpeakNpcId = 100001
        },
        [71005218] = {
          ContentKR = "으음... 그렇구나... 잘 생각해 볼게요! 고마워요!",
          DialogueId = 71005218,
          GUID = "B1C10C1C",
          SpeakNpcId = 818046
        },
        [71005301] = {
          ContentKR = "강도예요, 강도! 누가 좀 도와주세요!",
          DialogueId = 71005301,
          GUID = "B1C11B32",
          SpeakNpcId = 818042
        },
        [71005302] = {
          ContentKR = "뭘 훔쳐 갔는데? 어디로 갔어?",
          DialogueId = 71005302,
          GUID = "B1C11B5C",
          NextDialogue = 71005303,
          SpeakNpcId = 100001
        },
        [71005303] = {
          ContentKR = "저, 저쪽으로 도망갔어요... 흐윽... 외성은 정말 너무 위험해요...",
          DialogueId = 71005303,
          GUID = "B1C11B86",
          SpeakNpcId = 818042
        },
        [71005304] = {
          ContentKR = "내성 인간들은 하나같이 돈이 철철 넘쳐. 이 정도면 몇 달은 놀고먹겠는걸?",
          DialogueId = 71005304,
          GUID = "B1C11C04",
          NextDialogue = 71005305,
          SpeakNpcId = 818043
        },
        [71005305] = {
          ContentKR = "거기 멈춰. 훔친 거 당장 돌려놔.",
          DialogueId = 71005305,
          GUID = "B1C11C2E",
          NextDialogue = 71005306,
          SpeakNpcId = 100001
        },
        [71005306] = {
          ContentKR = "흥, 벌써 정의의 사도 등장인가? 그럼 우리도 봐주지 않겠어!",
          DialogueId = 71005306,
          GUID = "B1C11C58",
          SpeakNpcId = 818043
        },
        [71005307] = {
          ContentKR = "쳇... 오늘 재수가 없군. 튀자!",
          DialogueId = 71005307,
          GUID = "B1C11CAC",
          SpeakNpcId = 818043
        },
        [71005308] = {
          ContentKR = "(강도들은 뿔뿔이 흩어져 도망쳤다. 당신은 바닥에 떨어진 보따리를 줍고, 어떻게 할지 고민에 빠진다.)",
          DialogueId = 71005308,
          GUID = "B1C11CD6",
          SpeakNpcId = 800006
        },
        [71005309] = {
          ContentKR = "(이건 외성이 얼마나 위험한지 알려주는 '수업료'다. 이 정도는 받아도 당연하다. 더 안 뜯어낸 게 자비로운 거지.)",
          DialogueId = 71005309,
          GUID = "B1C11D2A",
          SpeakNpcId = 800006
        },
        [71005310] = {
          ContentKR = "물건 찾아왔어. 이거 맞지?",
          DialogueId = 71005310,
          GUID = "B1C11D54",
          NextDialogue = 71005311,
          SpeakNpcId = 100001
        },
        [71005311] = {
          ContentKR = "맞아요, 맞아요! 정말 고마워요!",
          DialogueId = 71005311,
          GUID = "B1C11D7E",
          NextDialogue = 71005312,
          SpeakNpcId = 818042
        },
        [71005312] = {
          ContentKR = "(소녀는 눈물을 닦더니, 보따리에서 돈을 한 움큼 꺼내 당신 손에 쥐여준다.)",
          DialogueId = 71005312,
          GUID = "B1C11DA8",
          NextDialogue = 71005313,
          SpeakNpcId = 800006
        },
        [71005313] = {
          ContentKR = "이건 감사 인사예요... 외성에도 당신처럼 착한 월석 사냥꾼이 있다니... 정말 다행이에요... 흐흑...",
          DialogueId = 71005313,
          GUID = "B1C11DA9",
          SpeakNpcId = 818042
        },
        [71005401] = {
          ContentKR = "푸짐한 보상이 눈앞에 있습니다! 지나치지 마세요!",
          DialogueId = 71005401,
          GUID = "B1C12B9A",
          SpeakNpcId = 818044
        },
        [71005402] = {
          ContentKR = "오, 거기 월석 사냥꾼! 도전해 볼래요? 이 상자를 열 수 있다면, 안에 든 건 전부 당신 거예요!",
          DialogueId = 71005402,
          GUID = "B1C12BC4",
          SpeakNpcId = 818044
        },
        [71005403] = {
          ContentKR = "(자물쇠 열리는 소리가 들리고, 드디어 성공인가 싶던 순간, 천천히 열리던 상자가 '딸깍'하더니, 갑자기 '쾅!'하고 닫혔다. 그리곤 아무리 열어보려 해도, 열리지 않는다.)",
          DialogueId = 71005403,
          GUID = "B1C12C18",
          SpeakNpcId = 800006
        },
        [71005404] = {
          ContentKR = "아악! 내 보물상자 망가졌잖아요! 물어내요!",
          DialogueId = 71005404,
          GUID = "B1C12C42",
          NextOptions = {
            [1] = 710054041,
            [2] = 710054042
          },
          SpeakNpcId = 818044
        },
        [71005405] = {
          ContentKR = "쉿, 쉿! 조용히 말해요! 저 여기서 계속... 장사해야 한단 말이에요. 이거 드릴 테니까, 조용히 넘어가 주세요. 예?",
          DialogueId = 71005405,
          GUID = "B1C12CC0",
          NextDialogue = 71005406,
          SpeakNpcId = 818044
        },
        [71005406] = {
          ContentKR = "(남자는 더 이상 변명할 수 없다는 걸 깨닫고, 당신에게 돈주머니를 내밀곤, 상자를 안은 채 조용히 자리를 떴다.)",
          DialogueId = 71005406,
          GUID = "B1C12CEA",
          SpeakNpcId = 800006
        },
        [71005407] = {
          ContentKR = "너, 꼭 내 주먹맛을 보고 싶단 얘기지?",
          DialogueId = 71005407,
          GUID = "B1C12D14",
          NextDialogue = 71005408,
          SpeakNpcId = 818044
        },
        [71005408] = {
          ContentKR = "사기꾼 주제에 싸울 배짱도 있네? 해볼 테면 해봐!",
          DialogueId = 71005408,
          GUID = "B1C12D3E",
          SpeakNpcId = 100001
        },
        [71005409] = {
          ContentKR = "(남자는 더 이상 변명할 수 없다는 걸 깨닫고, 당신에게 돈주머니를 내밀곤, 상자를 안은 채 조용히 자리를 떴다.)",
          DialogueId = 71005409,
          GUID = "B1C12D68",
          SpeakNpcId = 800006
        },
        [71005501] = {
          ContentKR = "저기요, 월석 사냥꾼님! 제발... 도와주세요.",
          DialogueId = 71005501,
          GUID = "B1C13C02",
          SpeakNpcId = 818049
        },
        [71005502] = {
          ContentKR = "저기 앞쪽에서... 무서운 소리가 나는데. 혹시... 대신 좀 확인해 주실 수 있을까요?",
          DialogueId = 71005502,
          GUID = "B1C13C2C",
          SpeakNpcId = 818049
        },
        [71005503] = {
          ContentKR = "(딱히 무서울 만한 건 보이지 않는다. 아마도 남자의 착각일 것이다.)",
          DialogueId = 71005503,
          GUID = "B1C13CAA",
          SpeakNpcId = 800006
        },
        [71005504] = {
          ContentKR = "(수로 상류에서 필토이드 몇 마리가 어슬렁거리며 쉰 목소리로 울부짖고 있다. 남자를 놀라게 한 것도 아마 이 소리일 것이다.)",
          DialogueId = 71005504,
          GUID = "B1C13CFE",
          SpeakNpcId = 800006
        },
        [71005505] = {
          ContentKR = "(필토이드를 전부 처치하고 나니, 주변은 다시 조용해졌다. 이제 돌아가서, 남자에게 알려주자.)",
          DialogueId = 71005505,
          GUID = "B1C13D28",
          SpeakNpcId = 800006
        },
        [71005506] = {
          ContentKR = "(수로 옆에 금속 조각 몇 개가 끼어 있어, 가끔 날카로운 소리를 낸다. 남자를 놀라게 한 것도 아마 이 소리일 것이다.)",
          DialogueId = 71005506,
          Duration = 3,
          GUID = "B1C13D52",
          NextDialogue = 71005507,
          SpeakNpcId = 800006
        },
        [71005507] = {
          ContentKR = "(금속을 주웠다. 금속을 사려는 사람은 어디든 있으니, 남자의 의뢰를 마친 후, 적당한 곳에 팔아넘기자.)",
          DialogueId = 71005507,
          GUID = "B1C13D53",
          SpeakNpcId = 800006
        },
        [71005508] = {
          ContentKR = "무서운 소리가 이제 안 들려요. 정말 감사해요...",
          DialogueId = 71005508,
          GUID = "B1C13D7C",
          SpeakNpcId = 818049
        },
        [71005601] = {
          ContentKR = "으아아... 너무 무거워... 낚싯줄이 도무지 안 올라와...",
          DialogueId = 71005601,
          GUID = "B1C14C6A",
          SpeakNpcId = 818050
        },
        [71005602] = {
          ContentKR = "무슨 일인가요?",
          DialogueId = 71005602,
          GUID = "B1C14C94",
          NextDialogue = 71005603,
          SpeakNpcId = 100001
        },
        [71005603] = {
          ContentKR = "월석 사냥꾼이시군. 내 낚싯줄이 저 밑에 쓰레기에 걸렸는데, 도와줄 수 있겠나?",
          DialogueId = 71005603,
          GUID = "B1C14CBE",
          NextOptions = {
            [1] = 710056031,
            [2] = 710056032
          },
          SpeakNpcId = 818050
        },
        [71005604] = {
          ContentKR = "좋아, 내가 이쪽에서 당길 테니, 당신은 저쪽에서 쓰레기를 처리해 줘.",
          DialogueId = 71005604,
          GUID = "B1C14CE8",
          SpeakNpcId = 818050
        },
        [71005605] = {
          ContentKR = "휴— 드디어 올라왔군. 고맙네.",
          DialogueId = 71005605,
          GUID = "B1C14D12",
          SpeakNpcId = 818050
        },
        [71005701] = {
          ContentKR = "살려주세요, 누가 좀 도와주세요.",
          DialogueId = 71005701,
          GUID = "B1C15CD2",
          SpeakNpcId = 818051
        },
        [71005702] = {
          ContentKR = "고맙네... 그런데 혹시, 부탁 하나만 더 해도 될까? 도망치다 보니 낚싯대를 저 앞에 두고 와버렸는데, 거기 필토이드가 몇 마리 있어서 말이지...",
          DialogueId = 71005702,
          GUID = "B1C15CFC",
          NextOptions = {
            [1] = 710057021,
            [2] = 710057022
          },
          SpeakNpcId = 818051
        },
        [71005703] = {
          ContentKR = "고마워! 난 그럼 여기서 기다리지.",
          DialogueId = 71005703,
          GUID = "B1C15D26",
          SpeakNpcId = 818051
        },
        [71005704] = {
          ContentKR = "맞아, 바로 이 낚싯대야, 고마워!",
          DialogueId = 71005704,
          GUID = "B1C15D50",
          SpeakNpcId = 818051
        },
        [71005801] = {
          ContentKR = "저기요, 월석 사냥꾼님! 제가 대박 기회를 찾아냈는데, 보실래요?",
          DialogueId = 71005801,
          GUID = "B1C16D3A",
          SpeakNpcId = 818052
        },
        [71005802] = {
          ContentKR = "앞쪽에서 실버라이트 더미를 발견했는데, 혼자선 도저히 다 못 들겠더라고요. 전부 드릴 테니 관심 있으시면 같이 가요!",
          DialogueId = 71005802,
          GUID = "B1C16D64",
          NextOptions = {
            [1] = 710058031,
            [2] = 710058032
          },
          SpeakNpcId = 818052
        },
        [71005804] = {
          ContentKR = "좋아요, 따라오세요.",
          DialogueId = 71005804,
          GUID = "B1C16DB8",
          SpeakNpcId = 818052
        },
        [71005805] = {
          ContentKR = "첫 번째 더미는 여기 있어요.",
          DialogueId = 71005805,
          GUID = "B1C16DE2",
          SpeakNpcId = 818052
        },
        [71005806] = {
          ContentKR = "앞에 더 있는데, 더 가져가실래요?",
          DialogueId = 71005806,
          GUID = "B1C16E0C",
          NextOptions = {
            [1] = 710058061,
            [2] = 710058062
          },
          SpeakNpcId = 818052
        },
        [71005807] = {
          ContentKR = "좋아요, 따라오세요.",
          DialogueId = 71005807,
          GUID = "B1C16E36",
          SpeakNpcId = 818052
        },
        [71005808] = {
          ContentKR = "두 번째 더미는 여기 있어요.",
          DialogueId = 71005808,
          GUID = "B1C16E60",
          SpeakNpcId = 818052
        },
        [71005809] = {
          ContentKR = "앞에 더 있는데, 더 가져가실래요?",
          DialogueId = 71005809,
          GUID = "B1C16E8A",
          NextOptions = {
            [1] = 710058091,
            [2] = 710058092
          },
          SpeakNpcId = 818052
        },
        [71005810] = {
          ContentKR = "좋아요, 앞으로 가면 보일 거예요.",
          DialogueId = 71005810,
          GUID = "B1C16EB4",
          SpeakNpcId = 818052
        },
        [71005811] = {
          ContentKR = "지금이다! 얘들아, 덮쳐!",
          DialogueId = 71005811,
          GUID = "B1C16EDE",
          NextDialogue = 71005812,
          SpeakNpcId = 818052
        },
        [71005812] = {
          ContentKR = "(실버라이트는 모두 광부로 변장한 강도들이 꾸민 함정이었다. 그들을 물리치자.)",
          DialogueId = 71005812,
          Duration = 3,
          GUID = "B1C16F08",
          SpeakNpcId = 800006
        },
        [71005813] = {
          ContentKR = "(모든 강도를 물리쳤다. 이제 오늘의 수확을 차분히 정리해 보자.)",
          DialogueId = 71005813,
          GUID = "B1C16F32",
          SpeakNpcId = 800006
        },
        [71005814] = {
          ContentKR = "젠장, 조금만 더하면... 아, 아니요, 그냥... 진짜 아쉽네요. 더 방해하지 않을게요. 안녕히 가세요.",
          DialogueId = 71005814,
          GUID = "B1C16F5C",
          SpeakNpcId = 818052
        },
        [71005901] = {
          ContentKR = "아빠 진짜 빨라요! 아빠한텐 아무도 못 이겨요!",
          DialogueId = 71005901,
          GUID = "B1C17DA2",
          SpeakNpcId = 818053
        },
        [71005902] = {
          ContentKR = "있잖아요, 우리 아빠 달리기 진짜 빠르거든요! 우리 아빠랑 달리기 시합하실래요?",
          DialogueId = 71005902,
          GUID = "B1C17DCC",
          NextOptions = {
            [1] = 710059021,
            [2] = 710059022
          },
          SpeakNpcId = 818053,
          bForbidSkipOptions = true
        },
        [71005903] = {
          ContentKR = "하아, 시합이요... 해야죠. 다만, 시합 전에 잠깐 드릴 말씀이 있어서요. 이쪽으로 좀 와주시겠어요?",
          DialogueId = 71005903,
          GUID = "B1C17DF6",
          SpeakNpcId = 818054
        },
        [71005904] = {
          ContentKR = "이 돈을 드릴 테니, 잠시 뒤 시합에서 살~짝만 봐주실 수 있을까요? 사실... 아들한테 제가 세상에서 제일 빠르다고 허풍을 떨었는데, 괜히 실망할까 봐...",
          DialogueId = 71005904,
          GUID = "B1C17E20",
