          DialogueId = 71005906,
          GUID = "B1C17E74",
          SpeakNpcId = 818054
        },
        [71005907] = {
          ContentKR = "그럼 시합 시작이에요! 아빠, 힘내요! 화이팅!!",
          DialogueId = 71005907,
          GUID = "B1C17E9E",
