          DialogueId = 71005909,
          Duration = 1,
          GUID = "B1C17EF2",
          NextDialogue = 71005910,
          SpeakNpcId = 818053
        },
        [71005910] = {
          ContentKR = "하나!",
          DialogueId = 71005910,
          Duration = 1,
          GUID = "B1C17F1C",
          SpeakNpcId = 818053
        },
        [71005911] = {
          ContentKR = "와아! 아빠 진짜 최고예요!",
          DialogueId = 71005911,
          GUID = "B1C17F46",
          NextDialogue = 71005912,
          SpeakNpcId = 818053
        },
        [71005912] = {
          ContentKR = "고맙습니다... 이건 제 작은 성의예요. 모두 가져가세요.",
          DialogueId = 71005912,
          GUID = "B1C17F70",
          SpeakNpcId = 818054
        },
        [71005913] = {
          ContentKR = "어라, 약속했던 거랑 다르잖아요...",
          DialogueId = 71005913,
          GUID = "B1C17F9A",
          NextDialogue = 71005914,
          SpeakNpcId = 818054
        },
        [71005914] = {
          ContentKR = "약속? 무슨 뜻이에요?",
          DialogueId = 71005914,
          GUID = "B1C17FC4",
          NextDialogue = 71005915,
          SpeakNpcId = 818053
        },
        [71005915] = {
          ContentKR = "흐음... 아무것도 아니란다. 미안하다, 아빠가 졌어...",
          DialogueId = 71005915,
          GUID = "B1C17FEE",
          NextDialogue = 71005916,
          SpeakNpcId = 818054
        },
        [71005916] = {
          ContentKR = "괜찮아요 아빠! 이번엔 실수였잖아요. 다음엔 우리 꼭 같이 이겨요!",
          DialogueId = 71005916,
          GUID = "B1C18018",
          NextDialogue = 71005917,
          SpeakNpcId = 818053
        },
        [71005917] = {
          ContentKR = "하아... 알겠다, 알겠어. 그리고 월석 사냥꾼님, 고마워요. 이건 당신이 받아야 할 보상이니 전부 가져가세요.",
          DialogueId = 71005917,
          GUID = "B1C18042",
          SpeakNpcId = 818054
        },
        [71005918] = {
          ContentKR = "미안하구나, 아빠가 졌어...",
          DialogueId = 71005918,
          GUID = "B1C1806C",
          NextDialogue = 71005919,
          SpeakNpcId = 818054
        },
        [71005919] = {
          ContentKR = "괜찮아요 아빠! 이번엔 실수였잖아요. 다음엔 우리 꼭 같이 이겨요!",
          DialogueId = 71005919,
          GUID = "B1C18096",
          NextDialogue = 71005920,
          SpeakNpcId = 818053
        },
        [71005920] = {
          ContentKR = "하아... 알겠다, 알겠어. 그리고 월석 사냥꾼님, 고마워요. 이건 당신이 받아야 할 보상이니 전부 가져가세요.",
          DialogueId = 71005920,
          GUID = "B1C180C0",
          SpeakNpcId = 818054
        },
        [71005921] = {
          Content = "哇，爸爸真的好厉害！",
          DialogueId = 71005921,
          GUID = "B1C180EA",
          NextDialogue = 71005922,
          SpeakNpcId = 818053
        },
        [71005922] = {
          ContentKR = "저기... 일부러 그러신 거죠? 고맙습니다... 이건 제 작은 성의예요. 모두 가져가세요.",
          DialogueId = 71005922,
          GUID = "B1C18114",
          SpeakNpcId = 818054
        },
        [71006001] = {
          ContentKR = "(주변에 떠돌던 필토이드들이 몰려들고 있다. 먼저 녀석들을 처리하고, 마령을 포획하자.)",
          DialogueId = 71006001,
          GUID = "B1C18E0A",
          SpeakNpcId = 800006
        },
        [71006002] = {
          ContentKR = "(싸움 소리에 이끌려, 더 많은 필토이드가 나타났다.)",
          DialogueId = 71006002,
          GUID = "B1C18E34",
          SpeakNpcId = 800006
        },
        [71006003] = {
          ContentKR = "(주변이 잠시 안전해졌다. 지금이 마령을 포획할 기회다.)",
          DialogueId = 71006003,
          GUID = "B1C18E5E",
          SpeakNpcId = 800006
        },
        [71006101] = {
          ContentKR = "아흑... 일하기 싫어... 진짜 너무너무너무 일하기 싫다...",
          DialogueId = 71006101,
          GUID = "B1C19E72",
          SpeakNpcId = 818019
        },
        [71006102] = {
          ContentKR = "하윽... 왜 이번엔 또 폐광까지 배달이야?! 좀 평범한 데서 먹으면 안 돼? 사고라도 나면 어쩌려고! 진짜 이리 뛰고 저리 뛰고 죽겠어...",
          DialogueId = 71006102,
          GUID = "B1C19E9C",
          NextDialogue = 71006103,
          SpeakNpcId = 818019
        },
        [71006103] = {
          ContentKR = "내가 도와줄까?",
          DialogueId = 71006103,
          GUID = "B1C19EC6",
          NextDialogue = 71006104,
          SpeakNpcId = 100001
        },
        [71006104] = {
          ContentKR = "응! 저 아래는 필토이드 천지라 도저히 못 가겠어. 이거 대신 좀 배달해 줘.",
          DialogueId = 71006104,
          GUID = "B1C19EF0",
          NextDialogue = 71006105,
          SpeakNpcId = 818019
        },
        [71006105] = {
          ContentKR = "좋아, 나한테 맡겨.",
          DialogueId = 71006105,
          GUID = "B1C19F1A",
          SpeakNpcId = 100001
        },
        [71006106] = {
          ContentKR = "(수많은 필토이드들이 길을 막고 있다. 다 물리치고 나서 지나가자.)",
          DialogueId = 71006106,
          GUID = "B1C19F44",
          SpeakNpcId = 800006
        },
        [71006107] = {
          ContentKR = "왜 이렇게 늦지...",
          DialogueId = 71006107,
          GUID = "B1C19F6E",
          SpeakNpcId = 818058
        },
        [71006108] = {
          ContentKR = "안녕하세요, 주문하신 음식 배달 왔습니다.",
          DialogueId = 71006108,
          GUID = "B1C19F98",
          NextDialogue = 71006109,
          SpeakNpcId = 100001
        },
        [71006109] = {
          ContentKR = "잠깐만요, 이게 뭐예요? 다 쏟아져서 먹을 수가 없잖아요! '은빛 평화 식당'에서 새로 시작한 배달 서비스라더니 완전 엉망이네요!",
          DialogueId = 71006109,
          GUID = "B1C19FC2",
          NextOptions = {
            [1] = 710061091,
            [2] = 710061092
          },
          SpeakNpcId = 818058,
          bForbidSkipOptions = true
        },
        [71006110] = {
          ContentKR = "그렇군요... 배달일도 제 논문 작성만큼 힘든 일이네요. 됐으니까 이거 받으세요. 방금 화내서 미안해요.",
          DialogueId = 71006110,
          GUID = "B1C19FEC",
          SpeakNpcId = 818058
        },
        [71006111] = {
          ContentKR = "(당신은 지질학자 앞에서 음식을 빠르게 먹어 치웠다.)",
          DialogueId = 71006111,
          Duration = 3,
          GUID = "B1C1A016",
          NextDialogue = 71006112,
          SpeakNpcId = 800006
        },
        [71006112] = {
          ContentKR = "천천히 먹어요! 괜히 체하기라도 하면 제 탓이 되잖아요... 하아... 배달일도 제 논문 작성만큼 힘든 일이네요. 됐으니까 이거 받으세요. 방금 화내서 미안해요.",
          DialogueId = 71006112,
          GUID = "B1C1A040",
          SpeakNpcId = 818058
        },
        [71006201] = {
          ContentKR = "오늘 왜 이러지... 도무지 한 마리도 낚이질 않잖아.",
          DialogueId = 71006201,
          GUID = "B1C1AEDA",
          SpeakNpcId = 818055
        },
        [71006202] = {
          ContentKR = "오, 월석 사냥꾼이군. 여긴 오늘 물고기 자체가 없는 것 같아. 그쪽이 한번 낚아보겠나?",
          DialogueId = 71006202,
          GUID = "B1C1AF04",
          SpeakNpcId = 818055
        },
        [71006203] = {
          ContentKR = "그럼 부탁하네.",
          DialogueId = 71006203,
          GUID = "B1C1AF2E",
          SpeakNpcId = 818055
        },
        [71006204] = {
          Content = "（待捕鱼系统做好后接入捕鱼系统）",
          DialogueId = 71006204,
          Duration = 3,
          GUID = "B1C1AF58",
          SpeakNpcId = 800006
        },
        [71006205] = {
          ContentKR = "이야, 한 번에 낚다니 대단하군. 장소 탓은 아니었나 봐...",
          DialogueId = 71006205,
          GUID = "B1C1AF82",
          NextDialogue = 71006206,
          SpeakNpcId = 818055
        },
        [71006206] = {
          ContentKR = "확인해 줘서 고맙네. 이젠 내가 해보지. 절대 오늘은 빈손으로 돌아갈 순 없으니까 말이야!",
          DialogueId = 71006206,
          GUID = "B1C1AFAC",
          SpeakNpcId = 818055
        },
        [71006301] = {
          ContentKR = "살려주세요, 누가 좀 도와주세요.",
          DialogueId = 71006301,
          GUID = "B1C1BF42",
          SpeakNpcId = 818056
        },
        [71006302] = {
          ContentKR = "고맙네... 저기, 부탁 하나만 더 해도 될까? 요 며칠 물고기를 하나도 못 잡아서, 돌아갈 때마다 사람들한테 놀림받거든... 한 마리만 잡아주겠나?",
          DialogueId = 71006302,
          GUID = "B1C1BF6C",
          SpeakNpcId = 818056
        },
        [71006303] = {
          ContentKR = "고맙네 고마워, 양동이는 옆에 뒀으니 그럼 부탁해~",
          DialogueId = 71006303,
          GUID = "B1C1BF96",
          SpeakNpcId = 818056
        },
        [71006304] = {
          Content = "（待捕鱼系统做好后接入捕鱼系统）",
          DialogueId = 71006304,
          Duration = 3,
          GUID = "B1C1BFC0",
          SpeakNpcId = 800006
        },
        [71006305] = {
          ContentKR = "아이고, 드디어 오늘은 비웃음당할 일 없겠군! 이건 수고에 대한 감사의 표시네!",
          DialogueId = 71006305,
          GUID = "B1C1BFEA",
          SpeakNpcId = 818056
        },
        [71006401] = {
          Content = "（玄色狴犴骤然出现，击退它们！）",
          DialogueId = 71006401,
          GUID = "B1C1CFAA",
          SpeakNpcId = 800006
        },
        [71006501] = {
          Content = "有奖竞猜有奖竞猜，那边那位朋友要不要来看看呀。",
          DialogueId = 71006501,
          GUID = "B1C1E012",
          SpeakNpcId = 818060
        },
        [71006502] = {
          Content = "恰逢奉香大典临近，本店特推出节庆活动，在举办一个叫非常大脑的智力问答活动，答错也有安慰奖，要不要来挑战一下？",
          DialogueId = 71006502,
          GUID = "B1C1E03C",
          NextOptions = {
            [1] = 710065021,
            [2] = 710065022
          },
          SpeakNpcId = 818060,
          bForbidSkipOptions = true
        },
        [71006504] = {
          Content = "好，你先稍作休息，我们马上开始。",
          DialogueId = 71006504,
          GUID = "B1C1E090",
          SpeakNpcId = 818060
        },
        [71006505] = {
          Content = "喂，那边的朋友先别急着去答题，要不要听听我的提议？",
          DialogueId = 71006505,
          GUID = "B1C1E0BA",
          SpeakNpcId = 818061
        },
        [71006506] = {
          Content = "那家伙净出一些麻烦的脑筋急转弯，你要是帮我搬下货，我就直接告诉你答案。如何？这样也省得你动脑子了。",
          DialogueId = 71006506,
          GUID = "B1C1E0E4",
          NextDialogue = 71006507,
          SpeakNpcId = 818061
        },
        [71006507] = {
          Content = "辛苦了，货就在那边的船上。",
          DialogueId = 71006507,
          GUID = "B1C1E10E",
          SpeakNpcId = 818061
        },
        [71006508] = {
          Content = "辛苦了，他今天这个问题应该选第一个。",
          DialogueId = 71006508,
          GUID = "B1C1E138",
          SpeakNpcId = 818061
        },
        [71006509] = {
          Content = "辛苦了，他今天这个问题应该选第二个。",
          DialogueId = 71006509,
          GUID = "B1C1E162",
          SpeakNpcId = 818061
        },
        [71006510] = {
          Content = "辛苦了，他今天这个问题应该选第三个。",
          DialogueId = 71006510,
          GUID = "B1C1E18C",
          SpeakNpcId = 818061
        },
        [71006511] = {
          Content = "休息好了吗？",
          DialogueId = 71006511,
          GUID = "B1C1E1B6",
          NextOptions = {
            [1] = 710065111,
            [2] = 710065112
          },
          SpeakNpcId = 818060,
          bForbidSkipOptions = true
        },
        [71006512] = {
          Content = "休息好了吗？",
          DialogueId = 71006512,
          GUID = "B1C1E1E0",
          NextOptions = {
            [1] = 710065121,
            [2] = 710065122
          },
          SpeakNpcId = 818060,
          bForbidSkipOptions = true
        },
        [71006513] = {
          Content = "休息好了吗？",
          DialogueId = 71006513,
          GUID = "B1C1E20A",
          NextOptions = {
            [1] = 710065131,
            [2] = 710065132
          },
          SpeakNpcId = 818060,
          bForbidSkipOptions = true
        },
        [71006514] = {
          Content = "请听题！织星客丢了一件商品，经过调查找到了甲乙丙三人。甲指责：“是乙偷的！”。乙声称：“是丙偷的！”。丙说：“确实是我偷的！”。仅一人说了真话，请问到底是谁偷走了商品？",
          DialogueId = 71006514,
          GUID = "B1C1E234",
          NextOptions = {
            [1] = 710065141,
            [2] = 710065142,
            [3] = 710065143
          },
          SpeakNpcId = 818060,
          bForbidSkipOptions = true
        },
        [71006515] = {
          Content = "请听题！锦鲤皎皎的好友有三个皎皎朋友，第一个叫黄金皎皎，第二个叫白银皎皎，第三个叫什么？",
          DialogueId = 71006515,
          GUID = "B1C1E25E",
          NextOptions = {
            [1] = 710065151,
            [2] = 710065152,
            [3] = 710065153
          },
          SpeakNpcId = 818060,
          bForbidSkipOptions = true
        },
        [71006516] = {
          Content = "请听题！三人前后排队，各带帽子一顶，帽子颜色可能会出现红、黄、蓝其中一种。最后一人能看到前两人的帽子，中间的人只能看前面。最后一人沉默，接着中间人也沉默。第一人说自己戴黄帽。已知至少一人戴黄帽。下列哪个说法是正确的？",
          DialogueId = 71006516,
          GUID = "B1C1E288",
          NextOptions = {
            [1] = 710065161,
            [2] = 710065162,
            [3] = 710065163
          },
          SpeakNpcId = 818060,
          bForbidSkipOptions = true
        },
        [71006517] = {
          Content = "恭喜你答对了！这是为你准备的豪华奖品，请拿好～",
          DialogueId = 71006517,
          GUID = "B1C1E2B2",
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          SpeakNpcId = 818060
        },
        [71006518] = {
          Content = "回答错误，这是你的安慰奖，欢迎下次再来挑战哦～",
          DialogueId = 71006518,
          GUID = "B1C1E2DC",
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          SpeakNpcId = 818060
        },
        [71006519] = {
          Content = "好吧好吧，还是年轻人有干劲，那你加油。",
          DialogueId = 71006519,
          GUID = "B1C1E306",
          SpeakNpcId = 818061
        },
        [71006520] = {
          Content = "嗯，准备好了再来找我吧！",
          DialogueId = 71006520,
          GUID = "B1C1E330",
          SpeakNpcId = 818060
        },
        [71006601] = {
          Content = "好想要小青蛙呀，咕咕呱呱呱。",
          DialogueId = 71006601,
          GUID = "B1C1F07A",
          SpeakNpcId = 818062
        },
        [71006602] = {
          Content = "小青蛙，好想要小青蛙，小青蛙小青蛙小青蛙。",
          DialogueId = 71006602,
          GUID = "B1C1F0A4",
          NextOptions = {
            [1] = 710066021,
            [2] = 710066022
          },
          SpeakNpcId = 818062,
          bForbidSkipOptions = true
        },
        [71006603] = {
          Content = "（它似乎对青蛙有什么执念，帮它找找看吧。）",
          DialogueId = 71006603,
          GUID = "B1C1F0CE",
          SpeakNpcId = 100001
        },
        [71006604] = {
          Content = "这些应该足够了，回去交给它吧。",
          DialogueId = 71006604,
          GUID = "B1C1F0F8",
          SpeakNpcId = 100001
        },
        [71006605] = {
          Content = "小青蛙，好耶，小青蛙，好～咕呱咕呱。",
          DialogueId = 71006605,
          GUID = "B1C1F122",
          NextDialogue = 71006606,
          SpeakNpcId = 818062
        },
        [71006606] = {
          Content = "（就这样，无由生消失在了你的面前。）",
          DialogueId = 71006606,
          GUID = "B1C1F14C",
          SpeakNpcId = 800006
        },
        [71006701] = {
          Content = "这么简单的题要是再答错，今晚就给我留下来抄一百遍吧。",
          DialogueId = 71006701,
          GUID = "B1C200E2",
          NextDialogue = 71006702,
          SpeakNpcId = 818064
        },
        [71006702] = {
