        [72999999] = {
          DialogueId = 72999999,
          DialoguePanelType = "AllHide",
          Duration = 1.4,
          GUID = "B6BF7256"
        },
        [73000201] = {
          ContentKR = "내가 이 장치를 개선했어. 계속 시험해보고, 개선 효과를 테스트해줘. 엘리시안에서 비싼 돈 주고 가져온 거니까, 이번엔 너도 절대 피할 수 없을 거야.",
          DialogueId = 73000201,
          GUID = "B6BF937A",
          SpeakNpcId = 818022
        },
        [73000202] = {
          ContentKR = "또 시험해 보고 싶어? 알았어. 흠, 너희처럼 날렵한 자들은 이렇게 뛰어다니는 걸 좋아하더라고.",
          DialogueId = 73000202,
          GUID = "B6BF93A4",
          SpeakNpcId = 818022
        },
        [73000203] = {
          ContentKR = "뭐? 또 성공했어? 적어도 한 번은 실패해야지... 안 되겠어, 다시 최적화해야겠어.",
          DialogueId = 73000203,
          GUID = "B6BF93CE",
          SpeakNpcId = 818022
        },
        [73000204] = {
          ContentKR = "그래, 이게 내가 원하던 효과야! 이게 뭘 할 수 있는지는 모르겠지만... 분명히 쓸모가 있을 거야.",
          DialogueId = 73000204,
          GUID = "B6BF93F8",
          SpeakNpcId = 818022
        },
        [73000301] = {
          ContentKR = "또 왔구나, 나도 이 장치를 더 개선했어. 지난번 난이도가 너무 쉬웠어. 이번엔 반드시 널 넘어뜨릴 수 있을 거야.",
          DialogueId = 73000301,
          GUID = "B6BFA3E2",
          SpeakNpcId = 818022
        },
        [73000302] = {
          ContentKR = "또 시험해 보고 싶어? 알았어. 흠, 너희처럼 날렵한 자들은 이렇게 뛰어다니는 걸 좋아하더라고.",
          DialogueId = 73000302,
          GUID = "B6BFA40C",
          SpeakNpcId = 818022
        },
        [73000303] = {
          ContentKR = "뭐야! 또 통과했어! 안 되겠어, 이미 많은 쿠퍼를 써서 개선했는데, 이렇게 포기할 수 없어. 기다려, 기다려.",
          DialogueId = 73000303,
          GUID = "B6BFA436",
          SpeakNpcId = 818022
        },
        [73000304] = {
          ContentKR = "좋아 좋아, 네가 허둥지둥하는 걸 보니 생각났어. 이걸 아이스레이크 시티 입구 앞에 설치해서 누군가 무단으로 들어오는 걸 막자고 상관에게 제안할 수 있겠어...",
          DialogueId = 73000304,
          GUID = "B6BFA460",
          SpeakNpcId = 818022
        },
        [73000401] = {
          ContentKR = "드디어 왔군, 널 기다리고 있었어. 이번엔 모든 재산을 들여 이 장치를 완벽하게 개조했어. 넌 절대 통과할 수 없어.",
          DialogueId = 73000401,
          GUID = "B6BFB44A",
          SpeakNpcId = 818022
        },
        [73000402] = {
          ContentKR = "또 시험해 보고 싶어? 알았어. 흠, 너희처럼 날렵한 자들은 이렇게 뛰어다니는 걸 좋아하더라고.",
          DialogueId = 73000402,
          GUID = "B6BFB474",
          SpeakNpcId = 818022
        },
        [73000403] = {
          ContentKR = "또... 또 실패했어. 됐어... 교회의 물건에 기대한 내 잘못이지. 이게 다 황제 폐하께 불충한 결과야.",
          DialogueId = 73000403,
          GUID = "B6BFB49E",
          SpeakNpcId = 818022
        },
        [73000404] = {
          ContentKR = "이 물건은 여기 둘 테니, 하고 싶은 대로 해봐... 넌 꽤 즐기는 것 같아 보이네.",
          DialogueId = 73000404,
          GUID = "B6BFB4C8",
          SpeakNpcId = 818022
        },
        [73000405] = {
          ContentKR = "어때, 대단하지? 생각해 봤는데, 이걸 황제 폐하께 바쳐서 병사 훈련과 선발에 사용하자고 하면 많은 상금을 받을 수 있을 거야. 그러면 이걸 개선하느라 진 빚을 갚을 수 있을 것 같아.",
          DialogueId = 73000405,
          GUID = "B6BFB4F2",
          SpeakNpcId = 818022
        },
        [73000502] = {
          ContentKR = "(조용히 서 있는 장치에는 조잡한 회전 버튼과 '쉬운', '쉽지 않은', '극한' 세 가지 모드가 있다. 그 수다스러운 병사의 작품이 틀림없다.)",
          DialogueId = 73000502,
          GUID = "B6BFC4DC",
          SpeakNpcId = 818022
        },
        [73000601] = {
          ContentKR = "(운송용 승강기네. 보급품이 있을지도 모르겠지만, 매복한 적이 있는지 주의해야 해.)",
          DialogueId = 73000601,
          ExStoryInfo = "EXPlayer",
          GUID = "B6BFD51A",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD7"
        },
        [73000701] = {
          ContentKR = "이 방은 당분간 안전해. 이제 콘솔을 조작할 수 있어.",
          DialogueId = 73000701,
          ExStoryInfo = "EXPlayer",
          GUID = "B6BFE582",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD8"
        },
        [73000801] = {
          ContentKR = "제어 권한 획득 중입니다. 잠시 기다려 주세요.",
          DialogueId = 73000801,
          GUID = "B6BFF5EA",
          SpeakNpcName = "UI_Npc_MechVoice",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD9"
        },
        [73000901] = {
          ContentKR = "(중앙 관제실은 독립적으로 전력을 공급받고 있군... 여기의 회전체는 동력실 폭발의 영향을 받지 않았어.)",
          DialogueId = 73000901,
          ExStoryInfo = "EXPlayer",
          GUID = "B6C00652",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDDA"
        },
        [73001001] = {
          ContentKR = "회로 오류, 콘솔이 보호 상태입니다. 보호 상태를 해제하려면 회전체를 종료시키세요.",
          DialogueId = 73001001,
          GUID = "B6C016BA",
          SpeakNpcName = "UI_Npc_MechVoice",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDDB"
        },
        [80001001] = {
          ContentKR = "와, 대마법사의 집 앞에 도착했네! 똑똑—— 대마법사, 집에 있어?",
          DialogueId = 80001001,
          GUID = "C8462C3A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462C3A"
        },
        [80001002] = {
          ContentKR = "흠... 대답이 없는 걸 보니 외출했나 보네. 밖에 나가서 찾아봐야겠다!",
          DialogueId = 80001002,
          GUID = "C8462C64",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462C64"
        },
        [80001003] = {
          ContentKR = "앗, 앞쪽 이야기는 아직 색칠이 안 되어 있잖아... 괜찮아, 피나에겐 마법의 붓이 있으니까, 앞으로 가면서 이야기를 색칠하면 돼!",
          DialogueId = 80001003,
          GUID = "C8462C8E",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462C8E"
        },
        [80001004] = {
          ContentKR = "이 길을 따라가서, 대마법사가 어디 갔는지 찾아보자.",
          DialogueId = 80001004,
          GUID = "C8462CB8",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462CB8"
        },
        [80001005] = {
          ContentKR = "어? 정원에 왜 꽃이 한 송이도 없지...",
          DialogueId = 80001005,
          GUID = "C8462CE2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 80001006,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462CE2"
        },
        [80001006] = {
          ContentKR = "피나가 여기에 예쁜 꽃을 피워 줄게!",
          DialogueId = 80001006,
          GUID = "C8462D0C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D0C"
        },
        [80001007] = {
          ContentKR = "이제 정원이 훨씬 아름다워졌어. 계속 앞으로 가 보자!",
          DialogueId = 80001007,
          GUID = "C8462D36",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D36"
        },
        [80001008] = {
          ContentKR = "이건... 나이팅게일이 남긴 깃털이잖아!",
          DialogueId = 80001008,
          GUID = "C8462D60",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80001009,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D60"
        },
        [80001009] = {
          ContentKR = "일단 잘 가지고 있자. 분명히 행운을 가져다줄 거야.",
          DialogueId = 80001009,
          GUID = "C8462D8A",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D8A"
        },
        [80001010] = {
          ContentKR = "앞쪽이 막혀 있네... 어떻게 하면 덩굴이 길을 비켜 줄까?",
          DialogueId = 80001010,
          GUID = "C8462DB4",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462DB4"
        },
        [80001011] = {
          ContentKR = "됐다! 이제 갈 수 있어!",
          DialogueId = 80001011,
          GUID = "C8462DDE",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462DDE"
        },
        [80001012] = {
          ContentKR = "대마법사가 저기 있나?",
          DialogueId = 80001012,
          GUID = "C8462E08",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E08"
        },
        [80001013] = {
          ContentKR = "음? 모닥불이 아직도 타고 있네. 대마법사가 떠난 지 얼마 안 됐나 봐.",
          DialogueId = 80001013,
          GUID = "C8462E32",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E32"
        },
        [80001014] = {
          ContentKR = "와, 사방에 반딧불이가 날아다니네! 꼭 별님한테 날개가 돋아난 것 같아!",
          DialogueId = 80001014,
          GUID = "C8462E5C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E5C"
        },
        [80001015] = {
          ContentKR = "여기도 예쁜 꽃이 피어 있네.",
          DialogueId = 80001015,
          GUID = "C8462E86",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 80001016,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E86"
        },
        [80001016] = {
          ContentKR = "우와, 동그란 버섯도 있어! 저걸 밟고 올라서면, 높이 뛰어오를 수 있겠지?",
          DialogueId = 80001016,
          GUID = "C8462EB0",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462EB0"
        },
        [80001017] = {
          ContentKR = "여기 보물이 있네! 혹시 대마법사가 숨겨 둔 보물일까?",
          DialogueId = 80001017,
          GUID = "C8462EDA",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462EDA"
        },
        [80001018] = {
          ContentKR = "앞쪽엔 길이 없네. 어떻게 가야 하지?",
          DialogueId = 80001018,
          GUID = "C8462F04",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462F04"
        },
        [80001019] = {
          ContentKR = "와...! 귀여운 버섯들아, 피나를 도우러 와 준 거야?",
          DialogueId = 80001019,
          GUID = "C8462F2E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 80001020,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462F2E"
        },
        [80001020] = {
          ContentKR = "정말 고마워. 이제 건너편으로 뛰어넘어 갈 수 있게 됐어.",
          DialogueId = 80001020,
          GUID = "C8462F58",
