        },
        [80004250] = {
          ContentKR = "이 색깔을 고르는 게 아닌가 봐... 다른 색 물감으로 해보자!",
          DialogueId = 80004250,
          Duration = 3,
          GUID = "C8483B09",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B09"
        },
        [80004251] = {
          ContentKR = "다른 색이 더 잘 어울릴 것 같아.",
          DialogueId = 80004251,
          Duration = 3,
          GUID = "C8483B0A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0A"
        },
        [80004252] = {
          ContentKR = "어어? 방금 칠한 색깔이 없어져 버렸네...",
          DialogueId = 80004252,
          Duration = 3,
          GUID = "C8483B0B",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80004253,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0B"
        },
        [80004253] = {
          ContentKR = "더 빨리 색칠해야 하나 봐!",
          DialogueId = 80004253,
          Duration = 3,
          GUID = "C8483B0C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0C"
        },
        [80004254] = {
          Camera = "-4.021118,-147.850586,140.854248,0.000064,-3.469995,89.231857,35.0,160.025635,false,Manual,12.0",
          Content = "（好像还没有把小夜莺的羽毛收集全……要再回去找找看吗？）",
          DialogueId = 80004254,
          Duration = 12,
          GUID = "C8483B0D",
          Scripts = [[
PARA{
CameraMoveTo{_delay{6.5},TargetPosition{"-130.023865,-580.916016,82.43866,0.000115,4.930222,79.821289,35.000011,872.114136,false,Manual,12.0"},duration{8}},
SEQ{
PARA{
