        },
        [80030217] = {
          ContentKR = "근데 난 겨우 여섯 살쯤 된 꼬마였다고. 솔직히 내키지 않았지만, 그래도 품격이 넘치는 신사가 되기 위해 만나는 모든 여성에게 말을 걸었지.",
          DialogueId = 80030217,
          GUID = "C858E57A",
          NextDialogue = 80030218,
          SpeakNpcId = 94202
        },
        [80030218] = {
          ContentKR = "그 모습을 본 누나들이 어떤 표정이었는지 상상이 가? 다음 날 누나들이 신사는 그렇게까지 할 필요 없다고 알려주었으니 다행이었지.",
          DialogueId = 80030218,
          GUID = "C858E5A4",
          NextDialogue = 80030219,
          SpeakNpcId = 94202
        },
        [80030219] = {
          ContentKR = "또 누나들이 사악했던 건, 신사라면 숙녀의 치맛자락에 키스해야 한다고 알려줬다는 거야.",
          DialogueId = 80030219,
          GUID = "C858E5CE",
          NextDialogue = 80030220,
          SpeakNpcId = 94202
        },
        [80030220] = {
          ContentKR = "생각하면 할수록 마음이 아프다. 일단 다신 기억하고 싶지 않은 내 어린 시절을 위해 건배하자.",
          DialogueId = 80030220,
          GUID = "C858E5F8",
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          }
        },
        [80030401] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentKR = "내가 왔어. 난 약속을 잘 지킨다고.",
          DialogueId = 80030401,
          GUID = "C85903AA",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030402,
          SpeakNpcId = 94202
        },
        [80030402] = {
          ContentKR = "자, 이건 개선된 '군용 합금 온도 조절 용기'야. 내가 미리 테스트도 해봤으니 문제없을 거야... 흐아암...",
          DialogueId = 80030402,
          GUID = "C85903D4",
          NextDialogue = 80030403,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk02R_Start"
          }
        },
        [80030403] = {
          ContentKR = "하지만 지금 너무 졸려서 먼저 잠부터 좀 자야겠어. 그리고 휴가도 거의 안 남았는데, 내일 다크서클이 생긴 상태로 시빌라 장군님께 업무 보고를 할 수는 없으니까.",
          DialogueId = 80030403,
          GUID = "C85903FE",
          NextOptions = {
            [1] = 800304031,
            [2] = 800304032
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk02R_End"
          }
        },
        [80030404] = {
          ContentKR = "꽤 예리한데? 걱정이 있긴 해.",
          DialogueId = 80030404,
          GUID = "C8590428",
          NextDialogue = 80030405,
          SpeakNpcId = 94202
        },
        [80030405] = {
          ContentKR = "눈치챘으니 그냥 말해줄게. 사실 악몽을 꿨어.",
          DialogueId = 80030405,
          GUID = "C8590452",
          NextOptions = {
            [1] = 800304071
          },
          SpeakNpcId = 94202
        },
        [80030406] = {
          ContentKR = "그럴 리가. 나처럼 귀찮은 것을 싫어하는 사람은 웬만한 초대는 다 거절한다고.",
          DialogueId = 80030406,
          GUID = "C859047C",
          NextDialogue = 80030407,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          }
        },
        [80030407] = {
          ContentKR = "사실은, 어제 악몽을 꿔서 기분이 좀 안 좋아.",
          DialogueId = 80030407,
          GUID = "C85904A6",
          NextOptions = {
            [1] = 800304071
          },
          SpeakNpcId = 94202
        },
        [80030408] = {
          ContentKR = "휴, 전부터 자주 꾸는 악몽이야. 내 짜증 나는 아버지가 나타나는 꿈.",
          DialogueId = 80030408,
          GUID = "C85904D0",
          NextOptions = {
            [1] = 800304081
          },
          SpeakNpcId = 94202
        },
        [80030409] = {
          ContentKR = "아버지도 제국의 군인이셨어. 하지만 지금은... 침대에 누워계신 지 꽤 되었지.",
          DialogueId = 80030409,
          GUID = "C85904FA",
          NextDialogue = 80030410,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          }
        },
        [80030410] = {
          ContentKR = "내가 누나들에게 속아 신사가 되려던 나이에 아버지는 이미 군단의 부사관이셨어. 아버지는 집에 있는 시간보다 전선에 있는 시간이 더 많았지. 지금의 나처럼.",
          DialogueId = 80030410,
          GUID = "C8590524",
          NextDialogue = 80030411,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          }
        },
        [80030411] = {
          ContentKR = "하지만 아버지는 나와 달리 자신의 군복을 매우 중요하게 여기셨어. 아버지에게는 군대야말로 자신의 집이고, 나와 누나들이 우리 집은 그저 마음대로 갈 수 있는 여관에 불과했나 봐.",
          DialogueId = 80030411,
          GUID = "C859054E",
          NextDialogue = 80030412,
          SpeakNpcId = 94202
        },
        [80030412] = {
          ContentKR = "아버지는 집에 돌아올 때마다 늘 불평하셨어. 황제 폐하의 초상화가 제대로 걸려 있지 않다고 하든가, 누나들이 집에 너무 늦게 들어온다고 하든가였지.",
          DialogueId = 80030412,
          GUID = "C8590578",
          NextDialogue = 80030413,
          SpeakNpcId = 94202
        },
        [80030413] = {
          ContentKR = "그리고 돌아올 때마다 꼭 나에 대해 점검하고는 했지.",
          DialogueId = 80030413,
          GUID = "C85905A2",
          NextDialogue = 80030414,
          SpeakNpcId = 94202
        },
        [80030414] = {
          ContentKR = "몇 센티미터 자랐는지, 몇 권의 책을 읽었는지, 몇 개의 요새 이름을 외웠는지, 몇 가지 생존 기술을 배웠는지, 하나하나 물어봤어.",
          DialogueId = 80030414,
          GUID = "C85905CC",
          NextDialogue = 80030415,
          SpeakNpcId = 94202
        },
        [80030415] = {
          ContentKR = "다른 이야기를 해보려고도 했지만, 아버지는 '군인이 되는 것' 외에는 아무것에도 관심이 없었어.",
          DialogueId = 80030415,
          GUID = "C85905F6",
          NextDialogue = 80030416,
          SpeakNpcId = 94202
        },
        [80030416] = {
          ContentKR = "한 번은 아버지에게 잘 보이기 위해 지금처럼 작은 물건을 만들었어. 조심스럽게 나무로 총을 하나 깎아 만들어 아버지에게 보여드려 칭찬을 받고 싶었나 봐.",
          DialogueId = 80030416,
          GUID = "C8590620",
          NextDialogue = 80030417,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03ToTalkL_Start"
          }
        },
        [80030417] = {
          ContentKR = "하지만 아버지는 총을 탁자 위에 '쾅' 내리치고는 정색하며 \"이런 시간 낭비하는 쓸데없는 일은 접어 치우고 어떻게 하면 훌륭한 군인이 될 수 있을지에나 신경 써\"라고만 했어.",
          DialogueId = 80030417,
          GUID = "C859064A",
          NextDialogue = 80030418,
          SpeakNpcId = 94202
        },
        [80030418] = {
          ContentKR = "그때 갑자기 내 마음속에 뭔가가 생긴 기분이 들었어. 바깥의 바람처럼 차갑고, 칼로 베는 것처럼 날카롭고, 만질 수도 없고, 멈출 수 없는 기분.",
          DialogueId = 80030418,
          GUID = "C8590674",
          NextDialogue = 80030419,
          SpeakNpcId = 94202
        },
        [80030419] = {
          ContentKR = "나중에야 그것이 증오였을 수도 있겠다는 것을 깨달았어. 당시의 마음은 그다지 강렬하지 않았지만, 이미 내 눈앞의 사람을 싫어하고 낯설게 느끼기에 충분했지.",
          DialogueId = 80030419,
          GUID = "C859069E",
          NextDialogue = 80030420,
          SpeakNpcId = 94202
        },
        [80030420] = {
          ContentKR = "그 후 난 더 이상 아버지에게 잘 보이려 하지 않았고, 아버지가 날 검사해도 신경 쓰지 않고, 나를 '쓸데없는 녀석'이라고 해도 상관하지 않았어.",
          DialogueId = 80030420,
          GUID = "C85906C8",
          NextDialogue = 80030421,
          SpeakNpcId = 94202
        },
        [80030421] = {
          ContentKR = "그러던 어느 날, 아버지가 갑자기 집에 돌아오셨는데, 살아는 있지만 의식은 없는 상태였어. 전투에서 부하를 보호하려고 하다가 머리에 파편을 맞았다고 하더라고.",
          DialogueId = 80030421,
          GUID = "C85906F2",
          NextDialogue = 80030422,
          SpeakNpcId = 94202
        },
        [80030422] = {
          ContentKR = "아버지는 따로 모아둔 돈이 없었어. 월급을 받으면 모두 집으로 보냈지. 의식을 잃은 아버지와 같이 집으로 온 것은 번쩍이는 훈장과 두 동강 난 나무총이 다였어.",
          DialogueId = 80030422,
          GUID = "C859071C",
          NextDialogue = 80030423,
          SpeakNpcId = 94202
        },
        [80030423] = {
          ContentKR = "난 아버지가 내게 크게 실망해서 일부로 부러트린 건 줄 알았는데, 아버지의 부하들이 그러더라. 아버지는 항상 이 나무총을 가지고 다니셨는데, 전장에서 쓰러지면서 이렇게 부러진 거라고.",
          DialogueId = 80030423,
          GUID = "C8590746",
          NextDialogue = 80030424,
          SpeakNpcId = 94202
        },
        [80030424] = {
          ContentKR = "아버지는 마음속으로는 나를 인정했던 것 같아. 하지만 나는 이런 식의 인정은 받아들일 수 없었어.",
          DialogueId = 80030424,
          GUID = "C8590770",
          NextDialogue = 80030425,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03ToTalkL_End"
          }
        },
        [80030425] = {
          ContentKR = "정말로 나를 자랑스럽게 생각했다면, 그냥 말로 표현해 주면 되었을 것을, 강요나 압박보다는 간단하게 격려만 해줬어도 좋았을 텐데 말이야.",
          DialogueId = 80030425,
          GUID = "C859079A",
          NextDialogue = 80030426,
          SpeakNpcId = 94202
        },
        [80030426] = {
          ContentKR = "아버지가 다시 일어나서 내 머리를 쥐어박을 일은 없겠지만, 아버지의 바람대로 나도 군단에 들어갔어.",
          DialogueId = 80030426,
          GUID = "C85907C4",
          NextDialogue = 80030427,
          SpeakNpcId = 94202
        },
        [80030427] = {
          ContentKR = "난 군단이 도대체 어떤 곳인지 궁금했어. 도대체 어떤 곳이길래 아버지를 이런 과묵한 사람으로 만들었을까? 또 나는 나대로 아버지의 꾸중을 듣지 않아도 스스로 잘할 수 있다고 증명하고도 싶었고.",
          DialogueId = 80030427,
          GUID = "C85907EE",
          NextDialogue = 80030428,
          SpeakNpcId = 94202
        },
        [80030428] = {
          ContentKR = "하지만 불행히도, 군단에 들어가 보니 아버지가 말한 것들이 틀리지 않았다는 걸 알게 되었지.",
          DialogueId = 80030428,
          GUID = "C8590818",
          NextDialogue = 80030429,
          SpeakNpcId = 94202
        },
        [80030429] = {
          ContentKR = "우리는 군단의 대부분의 사람들과는 다르게, 전장의 시체 더미에서 기어 나와, 그들이 베푸는 훈장을 무릎 꿇고 받았어.",
          DialogueId = 80030429,
          GUID = "C8590842",
          NextDialogue = 80030430,
          SpeakNpcId = 94202
        },
        [80030430] = {
          ContentKR = "번듯한 일자리, 여유 있는 삶, 심지어 생존 그 자체까지 우리의 모든 게 이 작은 훈장들에 담겨 있었어. 아버지는 가족을 위해 자신의 모든 것을 바쳤던 거야.",
          DialogueId = 80030430,
          GUID = "C859086C",
          NextDialogue = 80030431,
          SpeakNpcId = 94202
        },
        [80030431] = {
          ContentKR = "복종하고, 인내하고, 감정을 억누르며, 또 슬픔과 울부짖음에 적응하면서 이 거대한 짐승의 송곳니가 되어버린 거지.",
          DialogueId = 80030431,
          GUID = "C8590896",
          NextDialogue = 80030432,
          SpeakNpcId = 94202
        },
        [80030432] = {
          ContentKR = "난 그렇게까지는 하지 못하지만, 어떻게든 먹고살고, 가족이 지금의 여유를 유지하려면 돈이 필요하니까... 이러지도 저러지도 못하는 쓸모없는 녀석이 되어버렸어.",
          DialogueId = 80030432,
          GUID = "C85908C0",
          NextOptions = {
            [1] = 800304321
          },
          SpeakNpcId = 94202
        },
        [80030433] = {
          ContentKR = "......",
          DialogueId = 80030433,
          GUID = "C85908EA",
          NextDialogue = 80030434,
          SpeakNpcId = 94202
        },
        [80030434] = {
          ContentKR = "역시 예리해. 솔직히 말하면, 나도 계속 우울해하다가 겨우 내가 뭘 하고 있는지 깨달았어.",
          DialogueId = 80030434,
          GUID = "C8590914",
          NextDialogue = 80030435,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          }
        },
        [80030435] = {
          ContentKR = "음, 내 선택이 아버지의 기대에 완전히 부응하는 건 아니지만, 나는 그게 나쁜 일이라고 생각하지 않아.",
          DialogueId = 80030435,
          GUID = "C859093E",
          NextOptions = {
            [1] = 800304351,
            [2] = 800304352
          },
          SpeakNpcId = 94202
        },
        [80030436] = {
          ContentKR = "그랬으면 좋겠다. 그럼 이 악몽은 끝날 수 있겠지.",
          DialogueId = 80030436,
          GUID = "C8590968",
          NextDialogue = 80030438,
          SpeakNpcId = 94202
        },
        [80030437] = {
          ContentKR = "정말 좋은 음료야. 다 마시고 나면 다시는 악몽을 꾸지 않을 것 같은 기분이야.",
          DialogueId = 80030437,
          GUID = "C8590992",
          NextDialogue = 80030438,
          SpeakNpcId = 94202
        },
        [80030438] = {
          ContentKR = "고마워, 내 휴가 친구. 하지만 내일도 휴가를 내는 게 아니라면 일단 잠 좀 보충해야겠어.",
          DialogueId = 80030438,
          GUID = "C85909BC",
          NextDialogue = 80030439,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          }
        },
        [80030439] = {
          ContentKR = "걱정 마, 다음에 만날 때도 나는 여전히 네가 아는 그 랜디일 거야. 만약 또 악몽을 꾼다면, 그때 다시 한번 나한테 음료를 만들어 줘.",
          DialogueId = 80030439,
          GUID = "C85909E6",
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          }
        },
        [80030501] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentKR = "설탕 추가한 따뜻한 음료 한 잔. 아, 내가 수도에서 디저트를 좀 가져왔어. 휴가 때 줄 서서 산 거야. 먹어봐.",
          DialogueId = 80030501,
          GUID = "C8591412",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextOptions = {
            [1] = 800305011,
            [2] = 800305012
          },
          SpeakNpcId = 94202
        },
        [80030502] = {
          ContentKR = "맞아. 초대하기 전 분위기를 잡으려면 단거라도 좀 먹이고 시작하는 게 좋을 것 같아서.",
          DialogueId = 80030502,
          GUID = "C859143C",
          NextDialogue = 80030504,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          }
        },
        [80030503] = {
          ContentKR = "절대 그럴 일 없어! 널 초대하고 싶은 건 사실이지만, 다른 속셈이 있는 건 아니라고!",
          DialogueId = 80030503,
          GUID = "C8591466",
          NextDialogue = 80030504,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          }
        },
        [80030504] = {
          ContentKR = "큼큼... 음, 좀 갑작스럽지만, 나랑 한 곡 추지 않을래?",
          DialogueId = 80030504,
          GUID = "C8591490",
          NextDialogue = 80030505,
          SpeakNpcId = 94202
        },
        [80030505] = {
          ContentKR = "그러니까, 군단은 일부 지방 세력과 좋은 관계를 맺어야 하잖아? 이전에 말했듯이 내성에서 열리는 꼭 필요하지만 귀찮은 사교 모임에 참가해야 해.",
          DialogueId = 80030505,
          GUID = "C85914BA",
          NextDialogue = 80030506,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk02_Start"
          }
        },
        [80030506] = {
          ContentKR = "난 정말 가고 싶지 않아. 출장으로 친다 해도 그 높으신 분들 부인들을 상대하는 것도 귀찮은 일이고.",
          DialogueId = 80030506,
          GUID = "C85914E4",
          NextDialogue = 80030507,
          SpeakNpcId = 94202
        },
        [80030507] = {
          ContentKR = "그래서 이것들을 단번에 해결할 방법을 생각해 냈지. 모두가 인정할 만한 아름다운 여성과 함께 입장해서 춤을 추는 거야.",
          DialogueId = 80030507,
          GUID = "C859150E",
          NextDialogue = 80030508,
          SpeakNpcId = 94202
        },
        [80030508] = {
          ContentKR = "그럼 자기들끼리도 몇 번 만난 적 없는 먼 여자 친척을 내게 소개하려고 하지 않겠지.",
          DialogueId = 80030508,
          GUID = "C8591538",
          NextOptions = {
            [1] = 800305081,
            [2] = 800305082
          },
          SpeakNpcId = 94202
        },
        [80030509] = {
          ContentKR = "에... 아마도... 네가 여장하면 다들 속지 않을까 해서?",
          DialogueId = 80030509,
          GUID = "C8591562",
          NextOptions = {
            [1] = 800305091,
            [2] = 800305092
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk02_End"
          }
        },
        [80030510] = {
          ContentKR = "내가 초대받은 거잖아.",
          DialogueId = 80030510,
          GUID = "C859158C",
          NextDialogue = 80030512,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          }
        },
        [80030511] = {
          ContentKR = "에이, 나도 정말 어쩔 수 없어서 이렇게 물어보는 거란 말이야.",
          DialogueId = 80030511,
          GUID = "C85915B6",
          NextDialogue = 80030512,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          }
        },
        [80030512] = {
          ContentKR = "우리가 여태 같이 마신 술이 몇 잔인데! 넌 이미 내 누나들보다 더 가까운 형제라고! 아니면 나도 네 생각이 나지 않았을 거야!",
          DialogueId = 80030512,
          GUID = "C85915E0",
          NextDialogue = 80030513,
          SpeakNpcId = 94202
        },
        [80030513] = {
          ContentKR = "상황이 이러니 나 좀 도와줘. 앞으로 반년 동안 내 월급의 반을 줄 테니까!",
          DialogueId = 80030513,
          GUID = "C859160A",
          NextDialogue = 80030514,
          SpeakNpcId = 94202
        },
        [80030514] = {
          ContentKR = "정말 내키지 않는다면, 무도회 끝나고 내가 드레스 입은 모습을 네게 보여줄게. 어때?",
          DialogueId = 80030514,
          GUID = "C8591634",
          NextOptions = {
            [1] = 800305141,
            [2] = 800305142
          },
          SpeakNpcId = 94202
        },
        [80030515] = {
          ContentKR = "아니... 아냐, 오해하지 마. 아니아니아니아니야. 난 그런 취미가 없다고. 왜 그런 쪽으로 생각하는 거야?",
          DialogueId = 80030515,
          GUID = "C859165E",
          NextDialogue = 80030516,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          }
        },
        [80030516] = {
          ContentKR = "친구끼리 같이 밥도 먹고, 놀러 다니고, 화장실 가고, 같이 치마도 입고, 그런 거지. 아주 평범한 거야.",
          DialogueId = 80030516,
          GUID = "C8591688",
          NextOptions = {
            [1] = 800305161
          },
          SpeakNpcId = 94202
        },
        [80030517] = {
          ContentKR = "엑, 웃지 마! 난 심각하다고. 아무튼 대답해 줘. 만약 안 된다면, 다른 방법을 생각해 봐야겠지...",
          DialogueId = 80030517,
          GUID = "C85916B2",
          NextOptions = {
            [1] = 800305171,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          }
        },
        [80030518] = {
          ContentKR = "다시 한번 생각해 보면 안 돼? 정 안되면...",
          DialogueId = 80030518,
          GUID = "C85916DC",
          NextDialogue = 80030519,
          SpeakNpcId = 94202
        },
        [80030519] = {
          ContentKR = "잠깐, 동의한다고? 잘 됐다! 넌 정말...정말... 내 가족이나 마찬가지야!",
          DialogueId = 80030519,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C8591706",
          NextDialogue = 80030520,
          SpeakNpcId = 94202
        },
        [80030520] = {
          ContentKR = "이번에는 네게 정말 큰 신세를 졌어. 열심히 휴가 사유를 고민하는 것만큼 열심히 각종 방법을 생각해 내서 이 신세를 갚을게.",
          DialogueId = 80030520,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591730",
          NextDialogue = 80030521,
          SpeakNpcId = 94202
        },
        [80030521] = {
          ContentKR = "하지만 그건 무도회가 끝난 후에 다시 얘기하자. 네가 다른 말하기 전에 돌아가서 옷을 준비해야 해.",
          DialogueId = 80030521,
          GUID = "C859175A",
          NextDialogue = 80030522,
          SpeakNpcId = 94202
        },
        [80030522] = {
          ContentKR = "나중에 봐, 내 휴가 친구.",
          DialogueId = 80030522,
          GUID = "C8591784",
          SpeakNpcId = 94202
        },
        [80030523] = {
          ContentKR = "윽, 다시 한번 생각해 보면 안 돼? 무도회가 끝나면 열심히 휴가 사유를 고민하는 것만큼 노력해서 신세를 갚을게.",
          DialogueId = 80030523,
          GUID = "C85917AE",
          NextDialogue = 80030524,
          SpeakNpcId = 94202
        },
        [80030524] = {
          ContentKR = "하지만 지금은 네가 조용히 생각할 수 있는 공간을 마련해 주는 게 좋을 것 같아. 비록 난 네가 동의하기를 바라고, 네가 꼭 동의할 거라고 믿지만!",
          DialogueId = 80030524,
          GUID = "C85917D8",
          NextDialogue = 80030525,
          SpeakNpcId = 94202
        },
        [80030525] = {
          ContentKR = "그럼 난 먼저 갈게. 좋은 소식을 기다리고 있을게! 내 휴가 친구이자, 휴식 친구.",
          DialogueId = 80030525,
          GUID = "C8591802",
          SpeakNpcId = 94202
        },
        [80030526] = {
          ContentKR = "맞아. 너도 너만큼 적합한 파트너가 없다는 거 잘 알 거 아니야? 그러니까 목숨 하나 살린다 치고 나 좀 도와줘.",
          DialogueId = 80030526,
          GUID = "C8591856",
          NextOptions = {
            [1] = 800305261
          },
          SpeakNpcId = 94202
        },
        [80030527] = {
          ContentKR = "응...?",
          DialogueId = 80030527,
          GUID = "C8591880",
          NextDialogue = 80030528,
          SpeakNpcId = 94202
        },
        [80030528] = {
          ContentKR = "엉?! 그럴 리가? 어떻게 그런 생각을 하고 있지? 정말 널 체포해서 공이라도 세울 생각이었으면 네가 처음 여기 앉을 때부터 그랬겠지!",
          DialogueId = 80030528,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C85918AA",
          NextDialogue = 80030529,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          }
        },
        [80030529] = {
          ContentKR = "굳이 몇 번이나 휴가를 내면서 와서, 무도회라는 거짓말을 하면서 널 잡으려고 할 이유도 없고.",
          DialogueId = 80030529,
          GUID = "C85918D4",
          NextDialogue = 80030530,
          SpeakNpcId = 94202
        },
        [80030530] = {
          ContentKR = "게다가 널 유인한다 해도 꼭 무도회 파트너 초대 명목으로 해야 하나? 네가 거절하면 어떡할 건데?",
          DialogueId = 80030530,
          GUID = "C85918FE",
          NextDialogue = 80030531,
          SpeakNpcId = 94202
        },
        [80030531] = {
          ContentKR = "아, 이거 장난치는 거지? 아니면 네 눈에 내가 나쁘고 멍청하고 성가신 놈으로 보인다는 것밖에 해석이 안 되는데?",
          DialogueId = 80030531,
          GUID = "C8591928",
          NextOptions = {
            [1] = 800305311,
            [2] = 800305312
          },
          SpeakNpcId = 94202
        },
        [80030532] = {
          ContentKR = "다행이야. 정말 날 출세만을 위해 소중한 친구를 배신하는 파렴치한 사람으로 오해했다면, 난 상처받아서 한 달은 휴가를 내야 할지도 몰라.",
          DialogueId = 80030532,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591952",
          NextDialogue = 80030534,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          }
        },
        [80030533] = {
          ContentKR = "야야야, 적어도 뒤에 말은 아니라고 해줘야지! 내가 진지하게 받아들이면 어떻게 하려고!",
          DialogueId = 80030533,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C859197C",
          NextDialogue = 80030534,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          }
        },
        [80030534] = {
          ContentKR = "그래도 한 가지 확실한 건, 넌 사실 처음부터 위험할 거라고 걱정한 적이 없다는 거야.",
          DialogueId = 80030534,
          GUID = "C85919A6",
          NextDialogue = 80030535,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          }
        },
        [80030535] = {
          ContentKR = "그냥 최악의 상황을 가정하고 내 반응을 보고 싶어서 장난친 것이지.",
          DialogueId = 80030535,
          GUID = "C85919D0",
          NextOptions = {
            [1] = 800305351,
            [2] = 800305352
          },
          SpeakNpcId = 94202
        },
        [80030536] = {
          ContentKR = "나만 남을 놀리는 버릇이 있는 줄 알았는데 너도 정말 사악하네... 이런 악취미는 도대체 누구한테서 배운 거야!",
          DialogueId = 80030536,
          GUID = "C85919FA",
          NextDialogue = 80030537,
          SpeakNpcId = 94202
        },
        [80030537] = {
          ContentKR = "머리로는 불가능하다는 걸 알면서도 마음으로는 '정말 그렇게 생각하고 있으면 어떡하지' 하면서 당황했다니까.",
          DialogueId = 80030537,
          GUID = "C8591A24",
          NextDialogue = 80030538,
          SpeakNpcId = 94202
        },
        [80030538] = {
          ContentKR = "그러니 장난에 대한 보상으로 내 초대에 응해줘야 해.",
          DialogueId = 80030538,
          GUID = "C8591A4E",
          NextOptions = {
            [1] = 800305431,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          }
        },
        [80030539] = {
          ContentKR = "뭐?",
          DialogueId = 80030539,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C8591A78",
          NextDialogue = 80030540,
          SpeakNpcId = 94202
        },
        [80030540] = {
          ContentKR = "어, 그래, 맞아! 항상 시도 때도 없이 널 체포하고 싶었다니까! 내가 쉴 생각 하느라 바빠서 움직이지 않았을 뿐이지.",
          DialogueId = 80030540,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591AA2",
          NextDialogue = 80030541,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          }
        },
        [80030541] = {
          ContentKR = "모처럼 열심히 일하려고 했는데, 들통났네. 어쩌나~",
          DialogueId = 80030541,
          GUID = "C8591ACC",
          NextDialogue = 80030542,
          SpeakNpcId = 94202
        },
        [80030542] = {
          ContentKR = "조만간 군단에서 쫓겨나 아이스레이크 시티의 차가운 거리에서 노숙자 생활을 하게 되겠지? 춥고, 배고프고, 돌아갈 집도 없고...",
          DialogueId = 80030542,
          GUID = "C8591AF6",
          NextDialogue = 80030543,
          SpeakNpcId = 94202
        },
        [80030543] = {
          ContentKR = "정말 내가 거리에서 얼음 동상이 되는 걸 지켜만 볼 거야?",
          DialogueId = 80030543,
          GUID = "C8591B20",
          NextOptions = {
            [1] = 800305431,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          }
        },
        [80030544] = {
          ContentKR = "다시 한번 생각해 보면 안 돼? 정 안되면...",
          DialogueId = 80030544,
          GUID = "C8591B4A",
          NextDialogue = 80030545,
          SpeakNpcId = 94202
        },
        [80030545] = {
          ContentKR = "잠깐, 동의한다고? 잘 됐다! 넌 정말...정말... 내 가족이나 마찬가지야!",
          DialogueId = 80030545,
          GUID = "C8591B74",
          NextDialogue = 80030546,
          SpeakNpcId = 94202
        },
        [80030546] = {
