          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B11E"
        },
        [80100116] = {
          ContentKR = "그래도 저는 포기하지 않아요. 이 땅이 이런 모습의 저를 태어나게 했다면, 분명 저를 포용할 수 있는 사람도 태어나게 했을 테니까요.",
          DialogueId = 80100116,
          GUID = "C885B148",
          NextDialogue = 80100117,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B148"
        },
        [80100117] = {
          ContentKR = "그리고 당신, 와인색의 눈동자를 가진 나의 친구, 당신에게서 그 가능성을 봤어요.",
          DialogueId = 80100117,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885B172",
          NextDialogue = 80100118,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B172"
        },
        [80100118] = {
          ContentKR = "그러니 오늘 이 자리를 우리의 첫 달콤한 데이트로 생각하죠. 제 고백에 대한 보답으로 말이에요.",
          DialogueId = 80100118,
          GUID = "C885B19C",
          NextDialogue = 80100119,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B19C"
        },
        [80100119] = {
          ContentKR = "거절해도 좋아요. 하지만 그러면 영원히 제 비밀을 지키기 위해 입술과 혀가 독으로 봉인될지도 몰라요. 어느 쪽이 더 마음에 드나요?",
          DialogueId = 80100119,
          GUID = "C885B1C6",
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B1C6"
        },
        [80100201] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentKR = "또 우리 둘만 남았네요. 모처럼인걸요. 제 그런 면을 알고도 비명을 지르며 도망가지 않는 사람을 만나는 건 말이에요.",
          DialogueId = 80100201,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885BF3A",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801002011
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF3A"
        },
        [80100202] = {
          ContentKR = "눈치채셨지 않나요?",
          DialogueId = 80100202,
          GUID = "C885BF64",
          NextDialogue = 80100203,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF64"
        },
        [80100203] = {
          ContentKR = "팔을 한 번 뻗어 보세요. 얼마나 깨끗한가요. 오래된 굳은살과 상처가 있긴 하지만 그래도 깨끗하잖아요. 또 힘들 때면 그 팔에서는 짭짤한 땀이 나겠죠...",
          DialogueId = 80100203,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885BF8E",
          NextDialogue = 80100204,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF8E"
        },
        [80100204] = {
          ContentKR = "하지만 제 이... 손에서 나오는 건 치명적인 독뿐이에요.",
          DialogueId = 80100204,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885BFB8",
          NextDialogue = 80100205,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BFB8"
        },
        [80100205] = {
          ContentKR = "통제할 수 없는 독액은 말 안 듣는 오랜 친구 같아요. 저는 덕분에 숲에 숨어있던 필토이드를 쫓아내고, 저를 쫓는 병사들을 영원히 잠들게 할 수 있었죠.",
          DialogueId = 80100205,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885BFE2",
          NextDialogue = 80100206,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BFE2"
        },
        [80100206] = {
          ContentKR = "하지만 시도 때도 없이 이빨을 드러내서 제가 가까이하고 싶은 것들도 멀어지게 해요. 제가 샘물로 얼굴을 씻기만 해도, 가까이 다가온 물고기들이 마비되고 질식하니까요.",
          DialogueId = 80100206,
          GUID = "C885C00C",
          NextDialogue = 80100207,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C00C"
        },
        [80100207] = {
          ContentKR = "예전엔 이 독을 싫어했어요. 이 독만 없었다면 저도 또래 여자애들처럼 시장에 가서 옷도 고르고, 벽 모퉁이에 숨어 좋아하는 사람을 훔쳐볼 수 있었을 텐데요.",
          DialogueId = 80100207,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885C036",
          NextOptions = {
            [1] = 801002071,
            [2] = 801002072
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C036"
        },
        [80100208] = {
          ContentKR = "꿈이라기 보다는 한때 잠깐 했던 생각이에요. 지금 생각하면 우습기만 하지만요.",
          DialogueId = 80100208,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C060",
          NextDialogue = 80100210,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C060"
        },
        [80100209] = {
          ContentKR = "익숙해졌다기보다는 길들였다고 할까요. 더 잘 지낼 수 있는 방법을 찾았거든요.",
          DialogueId = 80100209,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C08A",
          NextDialogue = 80100210,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C08A"
        },
        [80100210] = {
          ContentKR = "이제는 몰래 훔쳐보지 않아도 되고, 지루하고 요란하기만 한 대화로 서로를 탐색할 필요도 없어요. 잠깐의 달콤한 포옹이면 눈앞의 사람이 저와 평생을 함께할 수 있는 사람인지 알 수 있으니까요.",
          DialogueId = 80100210,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C0B4",
          NextDialogue = 80100211,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C0B4"
        },
        [80100211] = {
          ContentKR = "독액은 제게 가장 소중한 시금석이에요. 언젠가 저의 포옹을 견디는 사람이 나타난다면, 그 사람이 바로 제 운명의 상대라는 걸 바로 확신할 수 있을 거예요.",
          DialogueId = 80100211,
          GUID = "C885C0DE",
          NextDialogue = 80100212,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C0DE"
        },
        [80100212] = {
          ContentKR = "안타깝게도 그런 사람은 아직 나타나지 않았어요. 어쩌면 영원히 나타나지 않을지도 모르죠. 하지만 이게 속물들의 얄팍하고 재미없는 속삭임보다는 훨씬 로맨틱하지 않나요?",
          DialogueId = 80100212,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885C108",
          NextDialogue = 80100213,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C108"
        },
        [80100213] = {
          ContentKR = "적어도 지금의 저에게 이건 선물이에요. 저를 두려워하는 사람, 저를 협박하는 사람, 저를 동정하는 사람, 저에게 아부하는 사람, 모두가 평등한 시험을 받게 하거든요.",
          DialogueId = 80100213,
          GUID = "C885C132",
          NextDialogue = 80100214,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C132"
        },
        [80100214] = {
          ContentKR = "그래서 지금의 저는 전과 마찬가지로 떠돌아다니고 있지만, 더 이상 다른 사람을 부러워하지 않아요. 제 특별한 독이 저만의 독특한 사랑을 찾아줄 테니까요.",
          DialogueId = 80100214,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C15C",
          NextDialogue = 80100215,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C15C"
        },
        [80100215] = {
          ContentKR = "그럼, 이제 저의 이 두 팔을 벌려 묻고 싶어요. 저와 포옹하겠어요?",
          DialogueId = 80100215,
          GUID = "C885C186",
          NextOptions = {
            [1] = 801002151,
            [2] = 801002152
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C186"
        },
        [80100216] = {
          ContentKR = "후후, 겁내지 마세요. 제 과거 이야기를 이렇게 많이 들은 건 당신이 처음이거든요. 기회는 단 한 번 뿐이지만, 어쩌면 당신이 제가 찾던 바로 그 사람일지도 모르잖아요?",
          DialogueId = 80100216,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885C1B0",
          NextDialogue = 80100218,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C1B0"
        },
        [80100217] = {
          ContentKR = "말은 그렇게 하고선 손에 든 칼로 제 목을 찌르시려고요? 그렇게 경계할 필요 없어요. 느껴지나요? 사실 우리는 같은 부류예요. 둘 다 다른 사람들과는 다른 운명을 타고났죠.",
          DialogueId = 80100217,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885C1DA",
          NextDialogue = 80100218,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C1DA"
        },
        [80100218] = {
          ContentKR = "하하... 당신이 시작한 데이트가 당신의 거절로 끝날 거라고는 생각하지 못했네요. 정말 아쉽네요.",
          DialogueId = 80100218,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C204",
          NextDialogue = 80100219,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C204"
        },
        [80100219] = {
          ContentKR = "하지만 우리에겐 시간이 많아요. 조심하세요. 어느 날 갑자기 제가 뒤에서 당신을 꼭 안아버릴지도 모르니까요.",
          DialogueId = 80100219,
          FacialId = {
            [1] = "92101:Confident02"
          },
          GUID = "C885C22E",
          NextOptions = {
            [1] = 801002191
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C22E"
        },
        [80100220] = {
          ContentKR = "어머, 정말 귀엽네요. 꼭 이빨을 드러낸 아기고양이 같아요... 아무래도 잠시 떨어져 있는 게 좋겠네요. 다음 만남을 기다리고 있을게요. 안녕...",
          DialogueId = 80100220,
          FacialId = {
            [1] = "92101:Happy02"
          },
          GUID = "C885C258",
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C258"
        },
        [80100221] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.396057,51.444664,130.0,false,Manual,2.8",
          ContentKR = "반가워요. 얼마나 지났다고 금방 또 만났네요.",
          DialogueId = 80100221,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C282",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100222,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C282"
        },
        [80100222] = {
          ContentKR = "당신도 저를 그렇게 경계하지는 않는 것 같아 기뻐요. 안심하세요. 저도 지금 당신을 껴안을 생각은 없으니까요. 대신 조언 하나만 할게요.",
          DialogueId = 80100222,
          GUID = "C885C2AC",
          NextDialogue = 80100223,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C2AC"
        },
        [80100223] = {
          ContentKR = "다음에 만날 땐, 저의 목소리가 들리면 꼭 돌아서서 저한테서 시선을 떼지 마세요. 안 그러면... 위험할지도 모르거든요.",
          DialogueId = 80100223,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C2D6",
          NextDialogue = 80100224,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C2D6"
        },
        [80100224] = {
          ContentKR = "그럼, 이번엔 정말로... Arrivederci.",
          DialogueId = 80100224,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C300",
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C300"
        },
        [80100301] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentKR = "오늘은 '사랑의 기운'에 이끌려 왔어요. 제 독액 한 방울 한 방울이 당신을 보고 싶어 했거든요.",
          DialogueId = 80100301,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885CFA2",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100302,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885CFA2"
        },
        [80100302] = {
          ContentKR = "자, 우리가 얼마나 통하는지 한번 볼까요? 제가 다음에 무슨 말을 할지 맞춰보세요.",
          DialogueId = 80100302,
          GUID = "C885CFCC",
          NextOptions = {
            [1] = 801003021,
            [2] = 801003022
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885CFCC"
        },
        [80100303] = {
          ContentKR = "솔직함도 당신의 매력 중 하나죠.",
          DialogueId = 80100303,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885CFF6",
          NextDialogue = 80100304,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885CFF6"
        },
        [80100304] = {
          ContentKR = "말 돌리는 건 이쯤 하고, 바로 옛날이야기를 해보죠.",
          DialogueId = 80100304,
          GUID = "C885D020",
          NextDialogue = 80100307,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D020"
        },
        [80100305] = {
          ContentKR = "맞아요. 역시 우리는 통한다니까요. 앞으로 제가 할 일이 틀리지 않는다는 걸 알겠어요.",
          DialogueId = 80100305,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885D04A",
          NextDialogue = 80100306,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D04A"
        },
        [80100306] = {
          ContentKR = "사실, 당신에게 위험이 다가오고 있다는 걸 솔직하게 알려드리려고요.",
          DialogueId = 80100306,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D074",
          NextDialogue = 80100307,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D074"
        },
        [80100307] = {
          ContentKR = "전에 저와 비슷한 사람을 만난 적이 있어요. 그 여자는 태어날 때부터 화염처럼 붉은 피부를 가졌어요. 성격도 불같아서 쉽게 화내고 복잡한 걸 못 견뎌했죠.",
          DialogueId = 80100307,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885D09E",
          NextDialogue = 80100308,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D09E"
        },
        [80100308] = {
          ContentKR = "어릴 때부터 사람들에게 괴물 같다며 손가락질 받던 저와는 달리, 그 사람은 가문의 사명을 지고 큰 기대를 받으며 자랐어요. 결국 죄수들을 감시하는 정의의 심판관이 되었죠. 또 자신이 노린 범죄자는 절대 놓치지 않았어요.",
          DialogueId = 80100308,
          GUID = "C885D0C8",
          NextDialogue = 80100309,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D0C8"
        },
        [80100309] = {
          ContentKR = "하지만 그 사람의 불꽃은 제 독과 비슷해서, 가까이 오려는 모든 이들을 밀어냈어요. 선의를 품었든, 악의를 품었든, 아무도 접근할 수 없었죠. 아니면 두려움에 멀어지거나요.",
          DialogueId = 80100309,
          GUID = "C885D0F2",
          NextOptions = {
            [1] = 801003091
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D0F2"
        },
        [80100310] = {
          ContentKR = "맞아요. 아시다시피, 저 같은 천성적으로 독을 지닌 괴물은 고의든 아니든 실수로 타인의 목숨을 앗아가게 되죠. 그러니 누군가 저를 쫓는 것도 이상한 일은 아니에요.",
          DialogueId = 80100310,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D11C",
          NextDialogue = 80100311,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D11C"
        },
        [80100311] = {
          ContentKR = "하지만 그 사람의 길고 집요한 추적 과정에서 한 가지를 깨달았어요. 그녀도 저와 마찬가지로 외로운 괴물이라는 걸요. 그래서 저는 이 점을 이용했죠.",
          DialogueId = 80100311,
          GUID = "C885D146",
          NextDialogue = 80100312,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D146"
        },
        [80100312] = {
          ContentKR = "진심 어린 고백을 하는 척했고, 그녀는 잠시 망설였어요. 자신이 이 넓은 아트라시아 대륙에서 유일한 변종이 아니라고, 또 연민과 용서를 통해 저를 멈추게 할 수 있다고 믿게 했죠.",
          DialogueId = 80100312,
          GUID = "C885D170",
          NextDialogue = 80100313,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D170"
        },
        [80100313] = {
          ContentKR = "그리고 저는 그 사람이 증거를 직접 처리한 걸 확인하자마자 바로 도망갔어요.",
          DialogueId = 80100313,
          GUID = "C885D19A",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100314,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D19A"
        },
        [80100314] = {
          ContentKR = "그 사람이 이를 갈며 저를 잡으려 불같이 화내는 모습을 당신은 상상하기 힘들 거예요. 하지만 이해하셨겠죠? 저를 감싸준 당신도 공범으로 여겨져 함께 감옥에 갇힐 수 있다는 걸요.",
          DialogueId = 80100314,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885D1C4",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801003141,
            [2] = 801003142
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D1C4"
        },
        [80100315] = {
          ContentKR = "그랬군요. 처음 당신을 봤을 때 느꼈던 그 매혹적인 위험한 기운의 이유를 이제 알 것 같아요.",
          DialogueId = 80100315,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885D1EE",
          NextDialogue = 80100316,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D1EE"
        },
        [80100316] = {
          ContentKR = "그럼, 제가 앞으로 닥칠 위험에 대해 알려드렸는데도, 피하지 않으신다는 건... 이제 제가 당신에게 더 가까이 다가가도 된다는 뜻으로 받아들여도 될까요?",
          DialogueId = 80100316,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D218",
          NextDialogue = 80100317,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D218"
        },
        [80100317] = {
          ContentKR = "사실 이런 위험한 과거에 대해 알려드리기 전에 좀 망설였어요. 또다시 떠돌아다니게 될까 봐 걱정됐거든요.",
          DialogueId = 80100317,
          GUID = "C885D242",
          NextDialogue = 80100318,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D242"
        },
        [80100318] = {
          ContentKR = "하지만, 그보다도 당신이 더 큰 위험에 처하는 걸 보고 싶지 않았어요. 제 독만으로도 이미 충분히 위험하니까요.",
          DialogueId = 80100318,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885D26C",
          NextDialogue = 80100319,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D26C"
        },
        [80100319] = {
          ContentKR = "다행히 당신의 대답 덕분에 더욱 확신하게 됐어요. 제가 여기 머문다면 반드시 제 운명의 상대를 찾을 수 있을 거라고요.",
          DialogueId = 80100319,
          GUID = "C885D296",
          NextOptions = {
            [1] = 801003191
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D296"
        },
        [80100320] = {
          ContentKR = "그래요, 루카 공화국에서 휘페르보레아까지 찾아다녔지만 만나지 못한 사람이죠. 전에는 그 사람이 제 꿈속에만 존재한다고 생각했어요. 빛나고 찬란하지만 흐릿하고 아른거리는...",
          DialogueId = 80100320,
          GUID = "C885D2C0",
          NextDialogue = 80100321,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D2C0"
        },
        [80100321] = {
          ContentKR = "그 사람이라면 강인한 몸으로 제 모든 독을 견뎌낼 수 있을 거예요... 순수한 마음으로 제 모든 사랑을 받아들일 수 있을 거예요... 또 자비로운 손길로 제 모든 슬픔을 어루만져 줄 거예요...",
          DialogueId = 80100321,
          FacialId = {
            [1] = "92101:Confident02"
          },
          GUID = "C885D2EA",
          NextDialogue = 80100322,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D2EA"
        },
        [80100322] = {
          ContentKR = "그 사람이 제 말을 들었을까요? 어떻게 생각해요?",
          DialogueId = 80100322,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D314",
          NextOptions = {
            [1] = 801003221,
            [2] = 801003222
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D314"
        },
        [80100323] = {
          ContentKR = "아... 풋... 하하하...",
          DialogueId = 80100323,
          FacialId = {
            [1] = "92101:Happy02"
          },
          GUID = "C885D33E",
          NextDialogue = 80100324,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D33E"
        },
        [80100324] = {
          ContentKR = "당신은 역시 귀엽고 이상하네요. 너무 재미있어서 그 매력에서 못 벗어나겠어요.",
          DialogueId = 80100324,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D368",
          NextDialogue = 80100325,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D368"
        },
        [80100325] = {
          ContentKR = "지금 당장 독으로 당신을 감싸버리고 싶지만... 저도 경솔한 장난을 좋아하지는 않으니까요.",
          DialogueId = 80100325,
          GUID = "C885D392",
          NextDialogue = 80100326,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D392"
        },
        [80100326] = {
          ContentKR = "그러니 우리 둘 다 생각할 시간을 가져보는 게 어떨까요? 저도 어떻게 하면 좋을지 곰곰이 생각해 봐야겠어요.",
          DialogueId = 80100326,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D3BC",
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D3BC"
        },
        [80100327] = {
          ContentKR = "교활한 사람이군요. 이렇게 애매모호한 말로 거절하면서도 희미한 가능성은 남겨두는 건가요?",
          DialogueId = 80100327,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D3E6",
          NextDialogue = 80100328,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D3E6"
        },
        [80100328] = {
          ContentKR = "적당한 거리라... 이걸 어떻게 받아들여야 할까요? 제게 가장 적당한 거리는 그림자처럼 떨어지지 않는 건데, 당신에게 적당한 거리는 어떤 건가요?",
          DialogueId = 80100328,
          GUID = "C885D410",
          NextDialogue = 80100329,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D410"
        },
        [80100329] = {
          ContentKR = "비밀연애 중인 사람처럼 다른 사람 앞에선 모르는 척하며, 은근히 곁에 있는 건가요? 아니면 서로 영원히, 다시는 만나지 않는 건가요?",
          DialogueId = 80100329,
          GUID = "C885D43A",
          NextDialogue = 80100330,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D43A"
        },
        [80100330] = {
          ContentKR = "저울의 양쪽 끝에 있는 '좋아'나 '더 좋은 사람을 만날 거야'같은 직접 말하는 간단한 길 보다는 계속 대화하고 탐색하는 걸 좋아하시는 것 같네요.",
          DialogueId = 80100330,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885D464",
          NextDialogue = 80100331,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D464"
        },
        [80100331] = {
          ContentKR = "저는 당신에게 너무 가까이 다가가 위험에 빠뜨릴 수도, 멀리 떨어져 완전히 남이 될 수도 없어요.",
          DialogueId = 80100331,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D48E",
          NextDialogue = 80100332,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D48E"
        },
        [80100332] = {
          ContentKR = "성분 비율이 표기되지 않은 향수를 조향하는 것처럼, 가장 좋은 결과를 낼 때까지 계속 시도하는 것밖에 없겠네요.",
          DialogueId = 80100332,
          GUID = "C885D4B8",
          NextOptions = {
            [1] = 801003321
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D4B8"
        },
        [80100333] = {
          ContentKR = "맞아요. 이렇게 어려운 상황은 처음이거든요. 또 이걸 해결한 뒤엔 제가 찾아 헤매던 그 답을 찾아 운명의 상대를 찾을 거라고 믿고 있어요.",
          DialogueId = 80100333,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D4E2",
          NextOptions = {
            [1] = 801003331
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D4E2"
        },
        [80100334] = {
          ContentKR = "그래요, 루카 공화국에서 휘페르보레아까지 찾아다녔지만 만나지 못한 사람이죠. 전에는 그 사람이 제 꿈속에만 존재한다고 생각했어요. 빛나고 찬란하지만 흐릿하고 아른거리는...",
          DialogueId = 80100334,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D50C",
          NextDialogue = 80100335,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D50C"
        },
        [80100335] = {
          ContentKR = "그 사람이라면 강인한 몸으로 제 모든 독을 견뎌낼 수 있을 거예요... 순수한 마음으로 제 모든 사랑을 받아들일 수 있을 거예요... 또 자비로운 손길로 제 모든 슬픔을 어루만져 줄 거예요...",
          DialogueId = 80100335,
          GUID = "C885D536",
          NextDialogue = 80100336,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D536"
        },
        [80100336] = {
          ContentKR = "그 운명의 상대가, 이토록 귀엽고 특이하고 재미있어서 저를 헤어나지 못하게 만드는 당신인지는...",
          DialogueId = 80100336,
          FacialId = {
            [1] = "92101:Smile01"
          },
          GUID = "C885D560",
          NextDialogue = 80100337,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D560"
        },
        [80100337] = {
          ContentKR = "저한테 시간을 좀 주세요. 제가 어떻게 해야 하면 좋을지 곰곰이 생각해 봐야겠어요.",
          DialogueId = 80100337,
          GUID = "C885D58A",
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D58A"
        },
        [80100401] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentKR = "휴우...",
          DialogueId = 80100401,
          FacialId = {
            [1] = "92101:Sad02"
          },
          GUID = "C885E00A",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801004011,
            [2] = 801004012
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E00A"
        },
        [80100402] = {
          ContentKR = "그래요. 아주 아주 골치 아픈 일이에요. 머릿속이 복잡해요. 그리고 그 골치가 아픈 이유는 바로 당신 때문이에요.",
          DialogueId = 80100402,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E034",
          NextDialogue = 80100404,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E034"
        },
        [80100403] = {
          ContentKR = "아뇨, 시간의 문제가 아니라 사람의 문제예요. 초대를 받은 그 순간부터 계속 머릿속이 복잡했거든요.",
          DialogueId = 80100403,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E05E",
          NextDialogue = 80100404,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E05E"
        },
        [80100404] = {
          ContentKR = "아시나요? 당신은 겉으로는 순수해 보이지만, 당신 또한 독으로 사람을 질식시킬 수도 있다는 사실을?",
          DialogueId = 80100404,
          GUID = "C885E088",
          NextDialogue = 80100405,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E088"
        },
        [80100405] = {
          ContentKR = "당신은 저와 다르게 첫 만남에서 자신의 위험성을 알리지 않았죠. 대신 말로 정교하게 그물을 엮었어요.",
          DialogueId = 80100405,
          GUID = "C885E0B2",
          NextDialogue = 80100406,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E0B2"
        },
        [80100406] = {
          ContentKR = "어쩌면 당신은 의도하지 않았을지도 모르지만, 그래서 더 무서워요. 사람들이 모르는 사이에 여기 머물게 되고, 당신에 의해 조금씩 변하면서 원래의 자신이 아니게 되니까요.",
          DialogueId = 80100406,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885E0DC",
          NextDialogue = 80100407,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E0DC"
        },
        [80100407] = {
          ContentKR = "전 루카 공화국을 떠난 후로 한 곳에서 오래 머무른 적이 거의 없어요. 정말 중요하게 여길 만한 사람도 만나지 못했고요.",
          DialogueId = 80100407,
          GUID = "C885E106",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100408,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E106"
        },
        [80100408] = {
          ContentKR = "이번에도 똑같을 줄 알았어요. 지루해질 때쯤 포옹으로 마지막 작별인사를 하고 떠날 거라고요.",
          DialogueId = 80100408,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E130",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100409,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E130"
        },
        [80100409] = {
          ContentKR = "하지만 이번엔 망설이게 되네요. 제 몸속의 독이 제게 이곳을 떠날 수 없다고 속삭이고 있어요.",
          DialogueId = 80100409,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885E15A",
          NextDialogue = 80100410,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E15A"
        },
        [80100410] = {
          ContentKR = "저도 이런 제 모습을 받아들일 수 없었고, 그래서 이렇게 고민을 시작하게 된 거예요. 그래서 전 오늘, 이 여행의 휴식에 마침표를 찍기로 했어요.",
          DialogueId = 80100410,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E184",
          NextDialogue = 80100411,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E184"
        },
        [80100411] = {
          ContentKR = "간단히 말해서... 제 독으로 당신을 감싸 안으며 작별 인사를 하려고요.",
          DialogueId = 80100411,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885E1AE",
          NextDialogue = 80100412,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E1AE"
        },
        [80100412] = {
          ContentKR = "자, 이제 남은 몇 초 동안 하고 싶은 말이 있나요?",
          DialogueId = 80100412,
          GUID = "C885E1D8",
          NextOptions = {
            [1] = 801004121,
            [2] = 801004122
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E1D8"
        },
        [80100413] = {
          ContentKR = "피하고 있다고요? 설마요. 제가 정말 원하는 게 뭔지 잘 알고 있어요. 저는 그저 당신이 겁에 질린 모습을 보고 싶을 뿐이에요.",
          DialogueId = 80100413,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885E202",
          NextDialogue = 80100414,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E202"
        },
        [80100414] = {
          ContentKR = "딱히 놀라지는 않은 것 같군요. 정말 아쉬워요.",
          DialogueId = 80100414,
          GUID = "C885E22C",
          NextDialogue = 80100416,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E22C"
        },
        [80100415] = {
          ContentKR = "그 정도로 별로였나요? 정말로 하나도 안 놀랐나요? 겁에 질린 얼굴이 보고 싶었는데, 정말 아쉽네요.",
          DialogueId = 80100415,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885E256",
          NextDialogue = 80100416,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E256"
        },
        [80100416] = {
          ContentKR = "그럼 장난은 이제 됐고, 이제 제 진짜 결정을 말씀드릴게요.",
          DialogueId = 80100416,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E280",
          NextDialogue = 80100417,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E280"
        },
        [80100417] = {
          ContentKR = "당신과 함께 보낸 최근 며칠은, 이전의 제 일상과 완전히 달랐어요. 매일 오후 이렇게 당신과 사랑의 말을 건네며 서로를 탐색하는 시간을 가졌죠...",
          DialogueId = 80100417,
          FacialId = {
            [1] = "92101:Smile01"
          },
          GUID = "C885E2AA",
          NextDialogue = 80100418,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E2AA"
        },
        [80100418] = {
          ContentKR = "그리고 헤어진 후에는 우산을 펴고 아무도 없는 골목으로 달려가 우리가 나눈 대화를 되새기며 혼자 춤을 추곤 했어요.",
          DialogueId = 80100418,
          GUID = "C885E2D4",
          NextDialogue = 80100419,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E2D4"
        },
        [80100419] = {
          ContentKR = "후훗... 이것도 나름의 로맨스 아닐까요?",
          DialogueId = 80100419,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E2FE",
          NextDialogue = 80100420,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E2FE"
        },
        [80100420] = {
          ContentKR = "지금까지 저는 제 포옹을 견딜 수 있는 운명의 상대를 찾으려고 했지만 오늘에서야 깨달았어요. 제가 진정으로 원했던 건 그저 하나뿐인 특별한 사랑이었다는 걸요.",
          DialogueId = 80100420,
          FacialId = {
            [1] = "92101:Smile01"
          },
          GUID = "C885E328",
          NextDialogue = 80100421,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E328"
        },
        [80100421] = {
          ContentKR = "'포옹'은 한때 제 시금석이었죠. 하지만 단 한 번 마음이 두근거리자 깨닫게 됐죠. 하나뿐인 특별한 사랑은 그런 검증 따윈 필요 없다는 걸요.",
          DialogueId = 80100421,
          GUID = "C885E352",
          NextDialogue = 80100422,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E352"
        },
        [80100422] = {
          ContentKR = "키스나 포옹도 꼭 필요한 게 아니에요. 오히려 제가 원하는 건 더 오래, 사라지지 않는 잔향 같은 거예요.",
          DialogueId = 80100422,
          GUID = "C885E37C",
          NextDialogue = 80100423,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E37C"
        },
        [80100423] = {
          ContentKR = "매일 아침 서로 인사하고 제가 새로 만든 향수의 향기를 맡아 보고 또 새로운 조합을 시도해 보는 이런 일상이 매일 반복돼도 좋을 것 같아요.",
          DialogueId = 80100423,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885E3A6",
          NextDialogue = 80100424,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E3A6"
        },
        [80100424] = {
          ContentKR = "제 독을 무력화할 수 있는 향수를 만들거나, 독을 정화할 수 있는 마법을 찾아볼 거예요. 고향의 동화 속 인어공주처럼 사랑하는 사람을 위해 온갖 방법을 동원해서 제 자신을 바꿔볼 거예요.",
          DialogueId = 80100424,
          GUID = "C885E3D0",
          NextDialogue = 80100425,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E3D0"
        },
        [80100425] = {
          ContentKR = "어쩌면 언젠가는 당신을 안을 수 있게 될지도 몰라요.",
          DialogueId = 80100425,
          GUID = "C885E3FA",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100426,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E3FA"
        },
        [80100426] = {
          ContentKR = "시험해 보려는 게 아니라 그저... 당신을 사랑하니까요.",
          DialogueId = 80100426,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885E424",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E424"
        },
        [80110100] = {
          ContentKR = "하, 고마워.",
          DialogueId = 80110100,
          GUID = "C88C1748",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1748"
        },
        [80110101] = {
          Camera = "127.060242,12.009277,131.847168,0.0,-0.799959,-137.39563,30.0,150.0,false,Manual,2.8",
          ContentKR = "잘 만든 것 같냐고? 번지수 잘못 찾았어. 나한테 그런거 물어봐도 난 잘 모른다고.",
          DialogueId = 80110101,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C1772",
          LookAt = {
            [1] = "93101:p(18000P3)"
          },
          NextDialogue = 80110102,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1772"
        },
        [80110102] = {
          ContentKR = "나한텐 세상의 모든 술이 다 똑같아. 마실 수만 있으면 그만이지. 유리잔에서 울리는 소리는 마치 시 읊는 것처럼 들리고 말야.",
          DialogueId = 80110102,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C179C",
          NextOptions = {
            [1] = 801101021
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C179C"
        },
        [80110103] = {
          ContentKR = "군단은 싸우는 곳이야, 소풍 가는 곳이 아니라고.",
          DialogueId = 80110103,
          GUID = "C88C17C6",
          NextDialogue = 80110104,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C17C6"
        },
        [80110104] = {
          ContentKR = "잠깐, 방금 '군단'이라고...?",
          DialogueId = 80110104,
          FacialId = {
            [1] = "93101:Doubt01"
          },
          GUID = "C88C17F0",
          NextDialogue = 80110105,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C17F0"
        },
        [80110105] = {
          ContentKR = "...너 뭐야? 무슨 속셈이지? 정체가 뭐야? 누가 보냈어? 어떤 정보를 캐내려는 거야? 바른대로 말해.",
          DialogueId = 80110105,
          GUID = "C88C181A",
          NextOptions = {
            [1] = 801101051,
            [2] = 801101052
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C181A"
        },
        [80110106] = {
          ContentKR = "'월석 사냥꾼' 주제에 알고 있는 게 너무 많군.",
          DialogueId = 80110106,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1844",
          NextDialogue = 80110107,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1844"
        },
        [80110107] = {
          ContentKR = "...이럴 줄 알았다니까, 갑자기 웬 공짜 술인가 했더니 역시 꿍꿍이가 있었군.",
          DialogueId = 80110107,
          GUID = "C88C186E",
          NextDialogue = 80110108,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C186E"
        },
        [80110108] = {
          ContentKR = "나랑 군단에 가서 진득하게 이야기 해보실까? 얌전히 따라와. 괜히 힘들게 묶어서 메고 가게 하지 말고.",
          DialogueId = 80110108,
          FacialId = {
            [1] = "93101:Confident01"
          },
          GUID = "C88C1898",
          NextDialogue = 80110109,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1898"
        },
        [80110109] = {
          ContentKR = "(린이 망설임 없이 총을 꺼내들고, 검은 총구가 내 미간을 겨누고 있는 모습이 머릿속에 떠오른다.)",
          DialogueId = 80110109,
          GUID = "C88C18C2",
          IsBlack = 1,
          NextDialogue = 80110110,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C18C2"
        },
        [80110110] = {
          ContentKR = "(이는 필연적인 결말이 될 것이다. 고개를 저으며 이 무모한 생각을 떨쳐낸다.)",
          DialogueId = 80110110,
          GUID = "C88C18EC",
          IsBlack = 1,
          NextDialogue = 80110111,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C18EC"
        },
        [80110111] = {
          ContentKR = "오해한 것 같아. 그냥 너한테 한잔 대접하고 싶어서야.",
          DialogueId = 80110111,
          GUID = "C88C1916",
          NextDialogue = 80110112,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1916"
        },
        [80110112] = {
          ContentKR = "......",
          DialogueId = 80110112,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1940",
          NextDialogue = 80110113,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1940"
        },
        [80110113] = {
          ContentKR = "내가 너무 예민했나 보네. 음, 크흠, 미안해 {性别:임마|아가씨}.",
          DialogueId = 80110113,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C196A",
          NextDialogue = 80110114,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C196A"
        },
        [80110114] = {
          ContentKR = "예전에 내가 이 일을 했었다는 걸 알고 그걸 핑계로 말 걸면서 군단의 비밀을 캐내려는 뻔뻔한 월석 사냥꾼들도 있었거든.",
          DialogueId = 80110114,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1994",
          NextOptions = {
            [1] = 801101141,
            [2] = 801101142
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1994"
        },
        [80110115] = {
          ContentKR = "맞아, 꽤 오래전 일이지만. 아, 이런 말해도 괜찮으려나?",
          DialogueId = 80110115,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C19BE",
          NextDialogue = 80110116,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C19BE"
        },
        [80110116] = {
          ContentKR = "...뭐, 군단에 과거 신분을 숨기라는 규정은 없으니까.",
          DialogueId = 80110116,
          GUID = "C88C19E8",
          NextOptions = {
            [1] = 801101161
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C19E8"
        },
        [80110117] = {
          ContentKR = "하, 넌 군단이 어떤 곳인지 몰라.",
          DialogueId = 80110117,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C1A12",
          NextDialogue = 80110118,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A12"
        },
        [80110118] = {
          ContentKR = "군단 담장엔 닿기만 해도 통구이가 되는 폭시코르 전기망이 있어. 탈영병이든, 도둑이나 스파이라고 해도 닿기만 하면 끝장이지.",
          DialogueId = 80110118,
          GUID = "C88C1A3C",
          NextDialogue = 80110119,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A3C"
        },
        [80110119] = {
          ContentKR = "근데 그건 눈에 보이는 전기망이라 그나마 피하기 쉽지. 군단엔 보이지 않는 전기망도 있어. 실수로 잘못된 일을 하거나 말을 잘못하면, 어느 순간 '팍' 하고 죽어버릴 수도 있다고.",
          DialogueId = 80110119,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1A66",
          NextDialogue = 80110120,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A66"
        },
        [80110120] = {
          ContentKR = "특히 내 상관은 배신자를 제일 싫어하지. 괜히 정보를 누설해서 죽기는 싫거든.",
          DialogueId = 80110120,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C1A90",
          NextOptions = {
            [1] = 801101201,
            [2] = 801101202
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A90"
        },
        [80110121] = {
          ContentKR = "헛소리 하고 있네. 내가 원해서 들어온 게 아니라고.",
          DialogueId = 80110121,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1ABA",
          NextDialogue = 80110123,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1ABA"
        },
        [80110122] = {
          ContentKR = "멋지다고? 널 멋지게 만들어놓고 언제라도 총에 맞을지도 모르는 상태로 일하라고 하면 좋을 것 같아?",
          DialogueId = 80110122,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1AE4",
          NextDialogue = 80110123,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1AE4"
        },
        [80110123] = {
          ContentKR = "...차라리 예전에 월석 사냥꾼으로 일할 때가 나았어. 몸은 편하진 않았어도 그래도 자유라는 게 있었으니까.",
          DialogueId = 80110123,
          GUID = "C88C1B0E",
          NextDialogue = 80110124,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B0E"
        },
        [80110124] = {
          ContentKR = "모든 의뢰가 목숨을 걸어야 할 정도는 아니었어. 가끔은 개 산책시키기, 사슴 사냥하기 같은 좋은 일거리도 있었고, 큰 일 치르고 나면 '아스포델'에 가서 술 한잔 하며 속을 달랠 수도 있었지.",
          DialogueId = 80110124,
          GUID = "C88C1B38",
          NextDialogue = 80110125,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B38"
        },
        [80110125] = {
          ContentKR = "혼자 일할 수 있었다고. 누구랑 팀 짜지 않아도 되고, 내 계획을 남들에게 설명할 필요도 없고, 임무 수행하면서 쓸모없는 짐덩이들 신경 쓸 필요도 없었어.",
          DialogueId = 80110125,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C1B62",
          NextDialogue = 80110126,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B62"
        },
        [80110126] = {
          ContentKR = "더 중요한 건, 참새처럼 쫑알거리는 시끄러운 상관 신경 쓸 필요가 없다는 거야.",
          DialogueId = 80110126,
          GUID = "C88C1B8C",
          NextOptions = {
            [1] = 801101261
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B8C"
        },
        [80110127] = {
          ContentKR = "이렇게 상관을 욕하는 것도 '잘못된 말'에 포함되는 것 아냐? '감전사' 당하는 거 아냐?",
          DialogueId = 80110127,
          GUID = "C88C1BB6",
          NextDialogue = 80110128,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1BB6"
        },
        [80110128] = {
          ContentKR = "......!",
          DialogueId = 80110128,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C1BE0",
          NextDialogue = 80110129,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1BE0"
        },
        [80110129] = {
          ContentKR = "당연하지! 난 그 귀족 출신 놈들처럼 두꺼운 가죽을 가진 게 아니라고. 아무리 감전시켜도 죽지 않는 거대 필토이드 같은 놈들이랑은 달라. 이 말이 새어나가면 감전사는 아니더라도 엄청난 꼴을 당할 거야.",
          DialogueId = 80110129,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1C0A",
          NextDialogue = 80110130,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C0A"
        },
        [80110130] = {
          ContentKR = "방금 말한 것들이 어디 딴 데서 내 귀에 들리는 날엔 대가리에 구멍 뚫릴 줄 알아.",
          DialogueId = 80110130,
          GUID = "C88C1C34",
          NextOptions = {
            [1] = 801101301
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C34"
        },
        [80110131] = {
          ContentKR = "그런데 생각보단 좀... 의외야.",
          DialogueId = 80110131,
          GUID = "C88C1C5E",
          NextDialogue = 80110132,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C5E"
        },
        [80110132] = {
          ContentKR = "난 린이 휘페르보레아 장교로서 좀 더 '신념' 같은 게 있을 줄 알았거든. 뭐랄까, '명예'라든가 '충성심' 같은 거 말이야.",
          DialogueId = 80110132,
          GUID = "C88C1C88",
          NextDialogue = 80110133,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C88"
        },
        [80110133] = {
          ContentKR = "흥, 그런 건 밑에 있는 신병들 속일 때나 쓰는 말이고. 나는...",
          DialogueId = 80110133,
          GUID = "C88C1CB2",
          NextDialogue = 80110134,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1CB2"
        },
        [80110134] = {
          ContentKR = "많은 사람들이 그런 보이지도 않고 잡히지도 않는 것들을 위해 모든 걸 바치겠지만, 난 아냐. 난 나 자신이 왜 월석 사냥꾼이 됐고, 또 왜 군단에 들어갔는지 잘 알고 있어.",
          DialogueId = 80110134,
          GUID = "C88C1CDC",
          NextDialogue = 80110135,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1CDC"
        },
        [80110135] = {
          ContentKR = "...그저 군단에 들어가면 배불리 먹을 수 있으니까, 그게 다야. 난 처음부터 그걸 잘 알고 있었지. 사실 간단해. 군단에는 내 힘이 필요하고, 난 돈이 필요했던 거고. 이건 그저 서로 필요한 걸 주고받는 거래일뿐이야.",
          DialogueId = 80110135,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C1D06",
          NextDialogue = 80110136,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D06"
        },
        [80110136] = {
          ContentKR = "네가 말한 명예니 신념이니 하는 건 한 톨도 없어.",
          DialogueId = 80110136,
          GUID = "C88C1D30",
          NextOptions = {
            [1] = 801101361
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D30"
        },
        [80110137] = {
          ContentKR = "......!",
          DialogueId = 80110137,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C1D5A",
          NextDialogue = 80110138,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D5A"
        },
        [80110138] = {
          ContentKR = "이 * 씨*, 짜증 나. 이 망할 술을 마시지 말았어야 했어. 마시면 이것저것 지껄이게 돼.",
          DialogueId = 80110138,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1D84",
          NextDialogue = 80110139,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D84"
        },
        [80110139] = {
          ContentKR = "나 간다! 방금 말한 건 아무에게도 말하지 마!",
          DialogueId = 80110139,
          GUID = "C88C1DAE",
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1DAE"
        },
        [80110201] = {
          Camera = "127.060242,12.009277,131.847168,0.0,-0.799959,-137.39563,30.0,150.0,false,Manual,2.8",
          ContentKR = "...한 잔 더.",
          DialogueId = 80110201,
          GUID = "C88C27DA",
          LookAt = {
            [1] = "93101:p(18000P3)"
          },
          NextDialogue = 80110202,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C27DA"
        },
        [80110202] = {
          ContentKR = "있잖아, 평소에 아이스레이크 시티에서 어떻게 일거리를 구해? 역시 '아스포델'이야?",
          DialogueId = 80110202,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2804",
          NextOptions = {
            [1] = 801102021
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2804"
        },
        [80110203] = {
          ContentKR = "그건 예전이랑 하나도 안 변했네. '아스포델'이라... 좋지... 최소한 카밀라는 갑자기 살인이나 강도질 하라고 시키진 않을 테니까.",
          DialogueId = 80110203,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C282E",
          NextOptions = {
            [1] = 801102031
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C282E"
        },
        [80110204] = {
          ContentKR = "하, 아이스레이크 시티가 수도에서 멀리 떨어진 변방이라고 얕봤다간 큰코다쳐. 수도보다 인재들이 더 많이 나온다니까. 특히 치안서가 관리 안 하는 외곽 지역은 더 그래. 하지만 걱정 마, 카밀라랑 일하면서 사적인 일만 따로 안 받으면 그런 의뢰는 볼일 없을 테니.",
          DialogueId = 80110204,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2858",
          NextDialogue = 80110205,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2858"
        },
        [80110205] = {
          ContentKR = "그나저나 카밀라는 어때? 지금도 무서운 호랑이 같아?",
          DialogueId = 80110205,
          GUID = "C88C2882",
          NextOptions = {
            [1] = 801102051,
            [2] = 801102052
          },
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2882"
        },
        [80110206] = {
          ContentKR = "그건 다행이네! 아, 시간 참 빨리 가네. 카밀라가 친절해졌다니, 내 상관은 지금도 호랑이 같은데 말이야.",
          DialogueId = 80110206,
          FacialId = {
            [1] = "93101:Happy01"
          },
          GUID = "C88C28AC",
          NextOptions = {
            [1] = 801102071
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C28AC"
        },
        [80110207] = {
          ContentKR = "그래, 카밀라도 여전하구나... 아, 내 상관이랑 똑같네. 생긴건 참 예쁜데 무서운 호랑이가 따로 없다니까.",
          DialogueId = 80110207,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C28D6",
          NextOptions = {
            [1] = 801102071
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C28D6"
        },
        [80110208] = {
          ContentKR = "이름은... 말 못 해. 말하면 군단 담장 위 전기망에 걸려 감전사할 거야.",
          DialogueId = 80110208,
          GUID = "C88C2900",
          NextDialogue = 80110209,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2900"
        },
        [80110209] = {
          ContentKR = "그 분은 매일 얼굴을 찌푸리고 다녀. 마치 온 군단이 그 분한테 빚진 것처럼 말이야.",
          DialogueId = 80110209,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C292A",
          NextOptions = {
            [1] = 801102091
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C292A"
        },
        [80110210] = {
          ContentKR = "아! 그 분은 이상한 취미가 한가득이야. 예를 들어 보통 사람은 다 총을 쓰잖아? 근데 그 분은 꼭 전기 채찍을 휘두르셔. 총보다 편하대.",
          DialogueId = 80110210,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2954",
          NextDialogue = 80110211,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2954"
        },
        [80110211] = {
          ContentKR = "(가슴이 갑자기 철렁 내려앉았다. 린이 말하는 사람은 내가 찾고 있던 사람, 시빌라를 떠올리게 했다.)",
          DialogueId = 80110211,
          GUID = "C88C297E",
          NextDialogue = 80110212,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C297E"
        },
        [80110212] = {
          ContentKR = "보통 사람들은 생각할 때 조용한 걸 좋아하잖아? 그 분은 시끄러운 녹음을 틀어놓고 듣는다고. 그러면 생각이 더 잘 된다나.",
          DialogueId = 80110212,
          GUID = "C88C29A8",
          NextDialogue = 80110213,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29A8"
        },
        [80110213] = {
          ContentKR = "심지어 사무실에 까마귀를 몇 마리나 키우고 있어. 그 새들이 폐... 아니, 상관에게 보내는 보고서에 똥을 싸도 괜찮대?",
          DialogueId = 80110213,
          GUID = "C88C29D2",
          NextDialogue = 80110214,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29D2"
        },
        [80110214] = {
          ContentKR = "또 있어. 보통 사람들은 강가에 가면 산책하거나, 바람 쐬고, 경치 구경도 하잖아? 내 상관은 강가에 가서 낚시꾼들이 빈손으로 돌아가는 걸 보러 간대. 스트레스 받을 때 그걸 보면 풀린다나 뭐라나.",
          DialogueId = 80110214,
          GUID = "C88C29FC",
          NextDialogue = 80110215,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29FC"
        },
        [80110215] = {
          ContentKR = "뭐 그런 사람이 다 있어!",
