        [80120116] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentKR = "좋아요... 이제 괜찮아요. 그냥 무시 좀 당한 것 뿐이에요. 아이스레이크 시티에서 이렇게 오래 살다 보면 다 일상이라, 이제 익숙해졌어요.",
          DialogueId = 80120116,
          FacialId = {
            [1] = "790019:Unhappy01"
