        [80120120] = {
          Camera = "25.643555,148.86615,117.203857,0.000134,-1.299553,-75.005913,35.0,286.089264,false,Manual,4.0",
          ContentKR = "그러다 몇 달 전에 <휘페르보레아의 빛>이라는 새 교향곡을 썼는데, 황성의 높으신 분들한테 인정을 받아서 돌아가게 됐다나.",
