          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F64AE"
        },
        [80140220] = {
          ContentKR = "우리 집의 그 두 말썽꾸러기가 자네처럼 품위 있고 예의를 갖췄다면, 내 이마 주름도 몇 줄은 덜했겠지.",
