          GUID = "C89F684A",
          NextDialogue = 80140242,
          SpeakNpcId = 790043,
          TalkActionId = {
            [1] = "790043:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F684A"
        },
        [80140242] = {
          Camera = "-166.054688,340.296387,174.617188,0.000012,-4.99993,-47.595356,44.120461,100000.0,false,DoNotOverride,2.8",
          ContentKR = "음, 그것도 나쁘지 않지. 젊은이라면 이런저런 도전을 해야 하는 법이니까. 그런데 말이야, 네 얼굴은 어머니를 똑 닮았는데, 성격은 나를 좀 닮은 것 같군. 다음 공연은 언제지?",
          DialogueId = 80140242,
          GUID = "C89F6874",
          NextDialogue = 80140243,
          SpeakNpcId = 790041,
          TalkActionId = {
            [1] = "790041:Agree"
