          GUID = "C89F7666",
          NextDialogue = 80140328,
          SpeakNpcId = 100336,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7666"
        },
        [80140328] = {
          Camera = "-94.440186,-1.264404,77.296875,0.000414,41.996418,18.421019,14.951323,125.0,false,DoNotOverride,2.8",
          ContentKR = "난 아직도...",
          DialogueId = 80140328,
          FinalCamera = "-94.440186,-1.264404,77.296875,0.000426,42.395412,-2.778932,14.951323,125.0,false,DoNotOverride,2.8",
          GUID = "C89F7690",
          NextDialogue = 80140329,
          SpeakNpcId = 790036,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7690"
        },
        [80140329] = {
          ContentKR = "뭐라고? 저게 지금 웅얼거리는 거야?",
          DialogueId = 80140329,
          GUID = "C89F76BA",
          LookAt = {
            [1] = "100337:n(790058)",
            [2] = "100336:n(790058)"
          },
          NextDialogue = 80140330,
          SpeakNpcId = 100337,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F76BA"
        },
        [80140330] = {
          ContentKR = "난... 다시 원래 모습으로 돌아갈 수 있을까?",
          DialogueId = 80140330,
          GUID = "C89F76E4",
          NextDialogue = 80140331,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F76E4"
        },
        [80140331] = {
          ContentKR = "하하... 하하하! 무슨 허황한 꿈을 꾸는 거야? 우리가 네 머리를 손대지도 않았는데, 혹시 뇌가 불에 타버렸나? 아니면 원래 그렇게 멍청한 거냐?",
          DialogueId = 80140331,
          GUID = "C89F770E",
          NextDialogue = 80140332,
          SpeakNpcId = 100337,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F770E"
        },
        [80140332] = {
          ContentKR = "우리가 원하는 건 괴물, 하나의 그릇, 쓸모 있는 칼이지. 절대로 너 자신이 아니야. 우리가 너를 원래 모습으로 돌려놓을 거로 생각했나?",
          DialogueId = 80140332,
          GUID = "C89F7738",
          NextDialogue = 80140333,
          SpeakNpcId = 100337,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7738"
        },
        [80140333] = {
          ContentKR = "왜, 왜죠?!",
          DialogueId = 80140333,
          GUID = "C89F7762",
          NextDialogue = 80140334,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7762"
        },
        [80140334] = {
          ContentKR = "'왜'라고?",
          DialogueId = 80140334,
          GUID = "C89F778C",
          NextDialogue = 80140335,
          SpeakNpcId = 100337,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F778C"
        },
        [80140335] = {
          ContentKR = "네가 발밑의 개미를 짓밟을 때 이유를 설명하나? 네가 입에 들어 있는 체리를 씹을 때 이유를 설명하나?",
          DialogueId = 80140335,
          GUID = "C89F77B6",
          NextDialogue = 80140336,
          SpeakNpcId = 100337,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F77B6"
        },
        [80140336] = {
          ContentKR = "아, 미안, 깜빡했네. 너 같은 천한 것들은 체리가 어떤 맛인지 평생 알 기회도 없겠지.",
          DialogueId = 80140336,
          GUID = "C89F77E0",
          NextDialogue = 80140337,
          SpeakNpcId = 100337,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F77E0"
        },
        [80140337] = {
          ContentKR = "아직 주사 안 끝났냐? 빨리 움직여라, 시간 낭비하지 말고.",
          DialogueId = 80140337,
          GUID = "C89F780A",
          LookAt = {
            [1] = "100337:n(100336)",
            [2] = "100336:n(100337)"
          },
          NextDialogue = 80140338,
          SpeakNpcId = 100337,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F780A"
        },
        [80140338] = {
          ContentKR = "네, 선생님. 끝났습니다.",
          DialogueId = 80140338,
          GUID = "C89F7834",
          SpeakNpcId = 100336,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7834"
        },
        [80140339] = {
          Camera = "-94.440186,-1.264404,77.296875,0.000404,36.399063,-23.382465,14.951323,125.0,false,DoNotOverride,2.8",
          ContentKR = "...알고 있어.",
          DialogueId = 80140339,
          GUID = "C89F785E",
          NextDialogue = 80140340,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F785E"
        },
        [80140340] = {
          ContentKR = "음? 뭘 안다는 거지?",
          DialogueId = 80140340,
          GUID = "C89F7888",
          LookAt = {
            [1] = "100337:n(790058)",
            [2] = "100336:n(790058)"
          },
          NextDialogue = 80140341,
          SpeakNpcId = 100336,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7888"
        },
        [80140341] = {
          ContentKR = "난 체리가 어떤 맛인지 알아. 어머니와 내가 처음 극단에서 받아들여졌을 때, 극단장님이 우리에게 푸짐한 저녁 식사를 대접해 주셨거든. 디저트는 체리 파이였어.",
          DialogueId = 80140341,
          GUID = "C89F78B2",
          NextDialogue = 80140342,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F78B2"
        },
        [80140342] = {
          ContentKR = "아직도 기억하고 있어. 파이가 잘려 나갈 때, 짙은 붉은색 잼이 금빛의 바삭한 페이스트리 사이로 흘러나왔지. 값싼 사탕 따위와는 비교도 안 될 만큼 달콤하고 향기로운 냄새가 단숨에 식당을 가득 채웠어.",
          DialogueId = 80140342,
          GUID = "C89F78DC",
          NextDialogue = 80140343,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F78DC"
        },
        [80140343] = {
          ContentKR = "극단장님은 연세가 많아 단 음식을 못 드신다고 하시며 자기 몫을 나눠주셨어. 사실은 내가 군침을 흘리는 걸 보고 배려하신 거지.",
          DialogueId = 80140343,
          GUID = "C89F7906",
          NextDialogue = 80140344,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7906"
        },
        [80140344] = {
          ContentKR = "그때 선생님은 젊고 활기 넘치는 아가씨셨는데, 한쪽 손에 파이를 쥐고 조심스레 한 입씩 먹으면서 거울을 몰래 보며 얼굴에 부스러기가 묻진 않았는지 확인하고 계셨어.",
          DialogueId = 80140344,
          GUID = "C89F7930",
          NextDialogue = 80140345,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7930"
        },
        [80140345] = {
          ContentKR = "남은 마지막 한 조각을 두고, 어린 수잔나와 데니스가 대사를 외워 승부를 내자고 했어, 결국 둘 다 틀려서 선생님이 화가 나 거의 숨 막힐 뻔하셨지만.",
          DialogueId = 80140345,
          GUID = "C89F795A",
          NextDialogue = 80140346,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F795A"
        },
        [80140346] = {
          ContentKR = "하하... 지금 다들 어떻게 지내고 있을까. '사기꾼'인 내가 사라졌으니 이제 정상적으로 공연을 준비하고 있겠지.",
          DialogueId = 80140346,
          GUID = "C89F7984",
          NextDialogue = 80140347,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7984"
        },
        [80140347] = {
          ContentKR = "......",
          DialogueId = 80140347,
          GUID = "C89F79AE",
          NextDialogue = 80140348,
          SpeakNpcId = 100336,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F79AE"
        },
        [80140348] = {
