        },
        [80190101] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          DialogueId = 80190101,
          Duration = 3,
          GUID = "C8BF5C72",
          NextDialogue = 80190102,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190102] = {
          ContentKR = "이렇게 큰 집에 혼자 살아? 분위기도 괜찮네. 심지어 바까지 잘 꾸며놨잖아?",
          DialogueId = 80190102,
          FacialId = {
            [1] = "95102:Shock01"
          },
          GUID = "C8BF5C9C",
          NextDialogue = 80190103,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190103] = {
          ContentKR = "괜찮은데? 친구들도 좀 자주 초대해봐. 그래야 이 아이스레이크 시티에서 네 인맥들을 만들 수 있잖아.",
          DialogueId = 80190103,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF5CC6",
          NextDialogue = 80190104,
          SpeakNpcId = 95102
        },
        [80190104] = {
          ContentKR = "그래서, 이번엔 또 무슨 일인데? 너무 골치 아픈 거라면 사양할게. 나 요즘 꽤 큰 건 맡고 있거든.",
          DialogueId = 80190104,
          GUID = "C8BF5CF0",
          NextOptions = {
            [1] = 801901041,
            [2] = 801901042
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190105] = {
          ContentKR = "으윽... 닭살 돋았어. 난 참을 수 있다 쳐도, 다른 사람한테도 이런 말 하면? 감당 못하고 튀어버릴지도 몰라?",
          DialogueId = 80190105,
          GUID = "C8BF5D1A",
          NextDialogue = 80190107,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190106] = {
          ContentKR = "좋아, 그럼 사양 안 할게. 네 솜씨, 내가 직접 맛 좀 봐야겠네?",
          DialogueId = 80190106,
          GUID = "C8BF5D44",
          NextDialogue = 80190107,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190107] = {
          ContentKR = "{空格}",
          DialogueId = 80190107,
          Duration = 3,
          GUID = "C8BF5D6E",
          NextDialogue = 80190108,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190108] = {
          ContentKR = "쯧쯧... 음, 달콤한데 살짝 신맛도 도네. 일부러 따뜻하게 데웠구나? '아스포델'술이랑 비슷한데, 너만의 맛도 있어.",
          DialogueId = 80190108,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF5D98",
          NextDialogue = 80190109,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190109] = {
          ContentKR = "이 한 잔 만들기 꽤 번거로웠겠네. 솔직히 내 기대를 넘었어. 사실 뜨거운 물 한 잔도 기쁘게 마실 수 있는데, 이렇게까지 할 필요는 없었어.",
          DialogueId = 80190109,
          GUID = "C8BF5DC2",
          NextDialogue = 80190110,
          SpeakNpcId = 95102
        },
        [80190110] = {
          ContentKR = "근데 네가 이렇게 들떠 있는 걸 보니까... 아하, 알겠다. 돈 좀 모았겠다 싶어서, 술도 사고 새 물건도 사고! 요즘 말로 하자면, '돈으로 행복 사기'?",
          DialogueId = 80190110,
          GUID = "C8BF5DEC",
          NextOptions = {
            [1] = 801901101,
            [2] = 801901102
          },
          SpeakNpcId = 95102
        },
        [80190111] = {
          ContentKR = "한 잔 하자고 부른 것도 결국 말 좀 해보자는 거잖아? 난 네 마음 잘 읽는 편이니까, 그만큼 내가 특별한 손님인 거지.",
          DialogueId = 80190111,
          GUID = "C8BF5E16",
          NextDialogue = 80190113,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190112] = {
          ContentKR = "알았어, 알았어! 내가 잘못했어. 오늘 돈 낸 건 너잖아, 네가 짱이지. 기분 풀리게 나 한 대 때려.",
          DialogueId = 80190112,
          GUID = "C8BF5E40",
          NextDialogue = 80190113,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190113] = {
          ContentKR = "농담은 농담이고, 반쯤 경험자로서 한마디 하자면— 모든 사람이 네가 '친구'라 여겨 술을 살 만큼의 가치는 있는 건 아니야.",
          DialogueId = 80190113,
          GUID = "C8BF5E6A",
          NextDialogue = 80190114,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190114] = {
          ContentKR = "특히 이 아이스레이크 시티 같은 데선 말이지, 네가 가진 걸 탐내면서 스스로 술친구랍시고 들러붙는 수상한 사람들 꼭 있기 마련이거든.",
          DialogueId = 80190114,
          GUID = "C8BF5E94",
          NextDialogue = 80190115,
          SpeakNpcId = 95102
        },
        [80190115] = {
          ContentKR = "그들은 겉으론 싱글벙글 웃고, 별 수단 다 써서 네 기분 맞춰주겠지만, 막상 일이 터지면? 차라리 길가에 앉은 개한테 기대는 게 나을걸.",
          DialogueId = 80190115,
          GUID = "C8BF5EBE",
          NextOptions = {
            [1] = 801901151
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190116] = {
          ContentKR = "하하 맞아, 맞아. 나 아웃사이더야 네 곁에서 제일 물불 안 가리는 술친구지. 어딘가에 이득이 있다 싶으면, 냄새만으로도 달려올 수 있어.",
          DialogueId = 80190116,
          GUID = "C8BF5EE8",
          NextDialogue = 80190117,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_AgreeHead"
          }
        },
        [80190117] = {
          ContentKR = "이 자리를 노리는 사람들이 있다면, 먼저 자기 실력부터 따져봐야지. 내가 '실컷 얻어먹고 만족'한 다음에나, 그때쯤 한 입 얻어갈 수 있을 걸?",
          DialogueId = 80190117,
          GUID = "C8BF5F12",
          NextOptions = {
            [1] = 801901171,
            [2] = 801901172
          },
          SpeakNpcId = 95102
        },
        [80190118] = {
          ContentKR = "아, 그러지 마. 난 아직 더 있고 싶은걸.",
          DialogueId = 80190118,
          GUID = "C8BF5F3C",
          NextDialogue = 80190120,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190119] = {
          ContentKR = "어? 무슨 일이었지? 난 전혀 몰랐는데?",
          DialogueId = 80190119,
          GUID = "C8BF5F66",
          NextDialogue = 80190120,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190120] = {
          ContentKR = "술맛 괜찮은데? 한 잔만 더 줘. 이거 마시고 바로 다시 일하러 갈게.",
          DialogueId = 80190120,
          GUID = "C8BF5F90",
          SpeakNpcId = 95102
        },
        [80190201] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentKR = "아이쿠, 30분이나 늦어버렸네. 미안하니까 오늘 네가 만든 술이 청어 통조림 맛이 나더라도 원샷할게!",
          DialogueId = 80190201,
          FacialId = {
            [1] = "95102:Ahaha01"
          },
          GUID = "C8BF6CDA",
          NextOptions = {
            [1] = 801902011,
            [2] = 801902012
          },
          SpeakNpcId = 95102
        },
        [80190202] = {
          ContentKR = "하하, 역시 날 너무 잘 아는데?",
          DialogueId = 80190202,
          FacialId = {
            [1] = "95102:Smile02"
          },
          GUID = "C8BF6D04",
          NextDialogue = 80190203,
          SpeakNpcId = 95102
        },
        [80190203] = {
          ContentKR = "며칠 전에 얘기했던 그 큰 건 기억나지? 오늘 웨일즈랑 마무리 짓느라 좀 늦었어.",
          DialogueId = 80190203,
          FacialId = {
            [1] = "95102:None"
          },
          GUID = "C8BF6D2E",
          NextDialogue = 80190204,
          SpeakNpcId = 95102
        },
        [80190204] = {
          ContentKR = "의뢰 자체는 별로 안 어려웠는데, 관련된 인간들이 하나같이 골칫덩이라서 말이지.",
          DialogueId = 80190204,
          GUID = "C8BF6D58",
          NextOptions = {
            [1] = 801902041
          },
          SpeakNpcId = 95102
        },
        [80190205] = {
          ContentKR = "그들은 아니야. 규칙만 잘 지키고, 눈치 좀 보고, 제국의 이익만 건드리지 않으면, 군단의 문제는 충분히 피해갈 수 있어.",
          DialogueId = 80190205,
          GUID = "C8BF6D82",
          NextDialogue = 80190206,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190206] = {
          ContentKR = "그들은 마치 칼과 같지. 위험하고 치명적이지만, 적어도 어떻게 움직일지는 보이거든.",
          DialogueId = 80190206,
          GUID = "C8BF6DAC",
          NextDialogue = 80190207,
          SpeakNpcId = 95102
        },
        [80190207] = {
          ContentKR = "하지만 그들보다 훨씬 더 예측할 수 없고, 폭력적인 무리가 있어. 마치 어둠 속에 숨겨진 폭탄처럼.",
          DialogueId = 80190207,
          GUID = "C8BF6DD6",
          NextDialogue = 80190208,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190208] = {
          ContentKR = "포세이큰 동맹. 목숨조차 아끼지 않는 그 조직과 얽히면, 평범한 일도 순식간에 골치 아픈 악몽이 되지.",
          DialogueId = 80190208,
          GUID = "C8BF6E00",
          NextDialogue = 80190209,
          SpeakNpcId = 95102
        },
        [80190209] = {
          ContentKR = "이번처럼 말이야. 그냥 단순한 물자 운반 의뢰인 줄 알았는데, 웨일즈가 무게가 수상하다며 몰래 구멍을 뚫어 엿보니, 안에 포세이큰 동맹의 불법 무기가 가득 들어 있었던 거야.",
          DialogueId = 80190209,
          GUID = "C8BF6E2A",
          NextDialogue = 80190210,
          SpeakNpcId = 95102
        },
        [80190210] = {
          ContentKR = "그걸 정문으로 들고 갔더라면, 입구에서 바로 총맞고 끝장났겠지.",
          DialogueId = 80190210,
          GUID = "C8BF6E54",
          NextDialogue = 80190211,
          SpeakNpcId = 95102
        },
        [80190211] = {
          ContentKR = "하지만 어쩌면 그게 바로 그들이 노린 그림이었을 수도 있어. 월석 사냥꾼 몇 구의 시체든, 혼란을 틈타 아이스레이크 시티 안으로 들어가는 거든.",
          DialogueId = 80190211,
          GUID = "C8BF6E7E",
          NextDialogue = 80190212,
          SpeakNpcId = 95102
        },
        [80190212] = {
          ContentKR = "혹은 이런 방식으로 자신들의 추종자들에게 보여주려던 걸지도 모르지. 솔라가 카론에게 얼마나 잔혹한지를 말이야.",
          DialogueId = 80190212,
          GUID = "C8BF6EA8",
          NextDialogue = 80190213,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190213] = {
          ContentKR = "도무지 말이 안 되지, 그렇지? 어쨌든 보통 사람이라면 그들의 수법이나 의도를 애초에 상상조차 할 수 없어.",
          DialogueId = 80190213,
          FacialId = {
            [1] = "95102:Angry01"
          },
          GUID = "C8BF6ED2",
          NextDialogue = 80190214,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_Start"
          }
        },
        [80190214] = {
          ContentKR = "결국 우리는 무기를 하수도 쪽으로 빼돌려서, 배수구를 따라 도시 안으로 들여보냈어. 겉보기엔 그냥 평범한 의뢰를 끝낸 것처럼 보이게 말이지.",
          DialogueId = 80190214,
          GUID = "C8BF6EFC",
          NextDialogue = 80190215,
          SpeakNpcId = 95102
        },
        [80190215] = {
          ContentKR = "말로 하니까 별거 아닌 것처럼 들리겠지만, 이 일 때문에 나랑 웨일즈는 며칠을 밤새우고 눈도 못 붙였어.",
          DialogueId = 80190215,
          GUID = "C8BF6F26",
          NextOptions = {
            [1] = 801902151,
            [2] = 801902152
          },
          SpeakNpcId = 95102
        },
        [80190216] = {
          ContentKR = "그건 그거고, 늦은 건 늦은 거지. 웨일즈 쪽이 아무리 바빴어도 말이야.",
          DialogueId = 80190216,
          GUID = "C8BF6F50",
          NextDialogue = 80190218,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190217] = {
          ContentKR = "그건 그거고, 이건 이거지. 술친구란 그런 거야. 술 한잔 있다면, 관 속에서도 기어 나와서 마셔야지.",
          DialogueId = 80190217,
          GUID = "C8BF6F7A",
          NextDialogue = 80190218,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190218] = {
          ContentKR = "{空格}",
          DialogueId = 80190218,
          Duration = 3,
          GUID = "C8BF6FA4",
          NextDialogue = 80190219,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190219] = {
          ContentKR = "하지만 이제는 정말 자러 가야겠다. 가기 전에 한마디만 해둘게— 너 자신을 위해서, 그리고 널 걱정하는 사람들을 위해서라도, 지금의 포세이큰 동맹과는 되도록 엮이지 마.",
          DialogueId = 80190219,
          GUID = "C8BF6FCE",
          NextOptions = {
            [1] = 801902191
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190220] = {
          ContentKR = "...다른 사람들하고 똑같아. 위험해 보이면 그냥 멀리하는 거야, 딱 그 정도.",
          DialogueId = 80190220,
          FacialId = {
            [1] = "95102:Sad01"
          },
          GUID = "C8BF6FF8",
          NextDialogue = 80190221,
          SpeakNpcId = 95102
        },
        [80190221] = {
          ContentKR = "폭력이라는 괴물들이 서로 으깨는 틈바구니 속에서 오래 버티며 얻은 귀중한 교훈이 있어—절대로, 정말로, 절대로 포세이큰 동맹에 가까이 가지 마.",
          DialogueId = 80190221,
          GUID = "C8BF7022",
          NextDialogue = 80190222,
          SpeakNpcId = 95102
        },
        [80190222] = {
          ContentKR = "이건 술자리에서 나오는 헛소리가 아냐... 네 목숨이 달린 진심 어린 충고야.",
          DialogueId = 80190222,
          GUID = "C8BF704C",
          SpeakNpcId = 95102
        },
        [80190301] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentKR = "아웃사이더는 약속대로 나타났지만, 술을 한 모금 마신 뒤로 한동안 아무 말도 하지 않았다.",
          DialogueId = 80190301,
          Duration = 3,
          FacialId = {
            [1] = "95102:Unhappy02"
          },
          GUID = "C8BF7D42",
          NextDialogue = 80190302,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190302] = {
          ContentKR = "......",
          DialogueId = 80190302,
          GUID = "C8BF7D6C",
          NextDialogue = 80190303,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190303] = {
          ContentKR = "......",
          DialogueId = 80190303,
          GUID = "C8BF7D96",
          NextOptions = {
            [1] = 801903031,
            [2] = 801903032
          },
          SpeakNpcId = 95102
        },
        [80190304] = {
          ContentKR = "......",
          DialogueId = 80190304,
          GUID = "C8BF7DC0",
          NextDialogue = 80190305,
          SpeakNpcId = 95102
        },
        [80190305] = {
          ContentKR = "아... 응. 나 괜찮아. 정말이야. 술 맛 좋네. 늘 그렇듯, 수준급이야.",
          DialogueId = 80190305,
          GUID = "C8BF7DEA",
          NextDialogue = 80190306,
          SpeakNpcId = 95102
        },
        [80190306] = {
          ContentKR = "......",
          DialogueId = 80190306,
          GUID = "C8BF7E14",
          NextOptions = {
            [1] = 801903061,
            [2] = 801903062
          },
          SpeakNpcId = 95102
        },
        [80190307] = {
          ContentKR = "하? 뭘 그런 생각을 해. 내가 사람들 앞에서 눈물 흘릴 것 같아? 감정에 휘둘리는 건 나 같은 '술친구'랑은 안 어울려.",
          DialogueId = 80190307,
          FacialId = {
            [1] = "95102:Shock01"
          },
          GUID = "C8BF7E3E",
          NextDialogue = 80190308,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190308] = {
          ContentKR = "근데 요즘은 정말 예전 일이 자꾸 떠올라... 흠, 나이 탓일지도 모르겠네.",
          DialogueId = 80190308,
          FacialId = {
            [1] = "95102:Sad01"
          },
          GUID = "C8BF7E68",
          NextDialogue = 80190309,
          SpeakNpcId = 95102
        },
        [80190309] = {
          ContentKR = "그렇게 진지한 얼굴 하지 마. 계속 얘기할 생각 없어. 겨우 몇 번 술 마셨다고 내가 겪은 일을 전부 들을 수 있을 거라 생각하지는 않겠지?",
          DialogueId = 80190309,
          GUID = "C8BF7E92",
          NextDialogue = 80190310,
          SpeakNpcId = 95102
        },
        [80190310] = {
          ContentKR = "누구에게나 무덤까지 혼자 안고 가야 할 비밀이 몇 개쯤은 있어. 무덤 위엔 남지 않지만, 그게야말로 묻힌 사람에게 가장 중요한 유품이지.",
          DialogueId = 80190310,
          GUID = "C8BF7EBC",
          NextDialogue = 80190311,
          SpeakNpcId = 95102
        },
        [80190311] = {
          ContentKR = "비밀이라는 건 크기도 하고 작기도 하지. 예를 들면, 폭시코르 냄새를 좋아한다거나 딱딱한 생강빵을 씹다가 앞니를 부러뜨린 것 같은 이상한 경험부터, 아무도 모르는 과거 같은 큰 비밀까지.",
          DialogueId = 80190311,
          GUID = "C8BF7EE6",
          NextDialogue = 80190312,
          SpeakNpcId = 95102
        },
        [80190312] = {
          ContentKR = "확실한 건, 겉으론 보이지 않는 이런 비밀들이야말로 그 사람이 어떤 선택을 할지를 가늠하게 해주는 기준이 된다는 거야. 음, 가장 중요하다고 하면 좀 과장일 수 있지만... 내 말이 무슨 뜻인지 알겠지?",
          DialogueId = 80190312,
          GUID = "C8BF7F10",
          NextDialogue = 80190313,
          SpeakNpcId = 95102
        },
        [80190313] = {
          ContentKR = "자신의 비밀이나 과거를 아무렇지도 않게 말하는 사람들은 보통 몇 가지 부류야. 그과거가 그들한테 별로 중요하지 않다든가...",
          DialogueId = 80190313,
          GUID = "C8BF7F3A",
          NextDialogue = 80190314,
          SpeakNpcId = 95102
        },
        [80190314] = {
          ContentKR = "혹은 너로부터의 위로를 기대하며, 사실은 없었던 과거를 만들어낸 걸 수도 있어.",
          DialogueId = 80190314,
          GUID = "C8BF7F64",
          NextDialogue = 80190315,
          SpeakNpcId = 95102
        },
        [80190315] = {
          ContentKR = "어쨌든, 쉽게 속 얘기 다 꺼내는 건 경솔한 짓이야. 그건 자기 약점을 넘겨주는 거고, 상대에 따라선 널 가볍게 볼 수도 있으니까.",
          DialogueId = 80190315,
          GUID = "C8BF7F8E",
          NextOptions = {
            [1] = 801903151,
            [2] = 801903152
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190316] = {
          ContentKR = "그래 그래, 보통은 그렇지. 너 말도 이해돼. 나도 가끔 아스포델에서 누군가한테 나 또 몰래 큰일 몇 개 맡았다고 슬쩍 말하곤 해.",
          DialogueId = 80190316,
          GUID = "C8BF7FB8",
          NextDialogue = 80190317,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_AgreeHead"
          }
        },
        [80190317] = {
          ContentKR = "근데... 좀 변명 같긴 한데, 비밀도 크고 작은 게 있잖아.",
          DialogueId = 80190317,
          GUID = "C8BF7FE2",
          NextOptions = {
            [1] = 801903171
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190318] = {
          ContentKR = "무슨 소리야! 그런 말도 안 되는 생각 하지 마!",
          DialogueId = 80190318,
          GUID = "C8BF800C",
          NextDialogue = 80190319,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190319] = {
          ContentKR = "...바로 너니까 내 과거를 알려줄 수 없는 거야. 괜히 궁금하게 만들려는 게 아니라, 그냥 이해해줬으면 하는 진심 어린 충고야.",
          DialogueId = 80190319,
          GUID = "C8BF8036",
          NextDialogue = 80190320,
          SpeakNpcId = 95102
        },
        [80190320] = {
          ContentKR = "과거의 무덤을 파헤치면 보물이 아니라 죽음이 나올 수도 있어. 모두에게 폐 끼치지 않으려고, 이 일은 내가 혼자 가슴에 묻을게.",
          DialogueId = 80190320,
          GUID = "C8BF8060",
          NextDialogue = 80190321,
          SpeakNpcId = 95102
        },
        [80190321] = {
          ContentKR = "걱정 마. 지난 몇 년 동안 나는 과거를 멀리 던져놨거든. 진짜로 다시 따라온다 해도 내가 감당할 수 있어. 내일 걱정하기보단 오늘을 잘 살자.",
          DialogueId = 80190321,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF808A",
          NextDialogue = 80190322,
          SpeakNpcId = 95102
        },
        [80190322] = {
          ContentKR = "한 잔 더! 아까 그건 너무 빨리 마셔서 맛을 제대로 못 느꼈어.",
          DialogueId = 80190322,
          GUID = "C8BF80B4",
          NextOptions = {
            [1] = 801903221,
            [2] = 801903222
          },
          SpeakNpcId = 95102
        },
        [80190323] = {
          ContentKR = "하하하하. 좋은 술에 좋은 친구랑 두서없이 수다 떠는 이런 하루, 얼마나 좋아~",
          DialogueId = 80190323,
          FacialId = {
            [1] = "95102:Smile02"
          },
          GUID = "C8BF80DE",
          NextOptions = {
            [1] = 801903231
          },
          SpeakNpcId = 95102
        },
        [80190324] = {
          ContentKR = "방금 나 욕한 거 아니야?",
          DialogueId = 80190324,
          GUID = "C8BF8108",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Think_Start"
          }
        },
        [80190401] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentKR = "{空格}",
          DialogueId = 80190401,
          GUID = "C8BF8DAA",
          NextDialogue = 80190402,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190402] = {
          ContentKR = "응? 방금 나 부른 거야?",
          DialogueId = 80190402,
          FacialId = {
            [1] = "95102:Doubt01"
          },
          GUID = "C8BF8DD4",
          NextOptions = {
            [1] = 801904021
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102
        },
        [80190403] = {
          ContentKR = "아... 그래? 요즘 내가 좀 예민해서, 미안해.",
          DialogueId = 80190403,
          FacialId = {
            [1] = "95102:Unhappy01"
          },
          GUID = "C8BF8DFE",
          NextDialogue = 80190404,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190404] = {
          ContentKR = "사실 오래전부터 누가 내 본래 이름을 부르는 환청을 듣곤 했어. 어떤 목소리는 부드럽고, 어떤 건 단단했지.",
          DialogueId = 80190404,
          GUID = "C8BF8E28",
          NextDialogue = 80190405,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_Start"
          }
        },
        [80190405] = {
          ContentKR = "거의 이명 같은 거지. 오래 들으니까 익숙해졌어. 심심할 땐 가짜인 걸 알면서도 대답하기도 해.",
          DialogueId = 80190405,
          GUID = "C8BF8E52",
          NextDialogue = 80190406,
          SpeakNpcId = 95102
        },
        [80190406] = {
          ContentKR = "그런데 최근에 좀 무서운 일이 있었어. 어제 습관처럼 대답했는데, 진짜 누가 '응답'했어.",
          DialogueId = 80190406,
          GUID = "C8BF8E7C",
          NextDialogue = 80190407,
          SpeakNpcId = 95102
        },
        [80190407] = {
          ContentKR = "길모퉁이 쓰레기통이 갑자기 뒤집히더니, 새까만 그림자가 튀어나와 나한테 인사를 했어.",
          DialogueId = 80190407,
          GUID = "C8BF8EA6",
          NextDialogue = 80190408,
          SpeakNpcId = 95102
        },
        [80190408] = {
          ContentKR = "진심으로 그게 그냥 어느 장난꾸러기 애의 장난이었으면 했어. 하지만 안타깝게도 내가 들은 이름은 네가 아는 '아웃사이더'가 아니라 포세이큰 동맹 애들만 부르는 이름이었어.",
          DialogueId = 80190408,
          GUID = "C8BF8ED0",
          NextDialogue = 80190409,
          SpeakNpcId = 95102
        },
        [80190409] = {
          ContentKR = "얼른 못 들은 척하고 지나갔는데, 그 사람이 믿었는지 모르겠어... 에휴, 며칠 전에 그 포세이큰 동맹 일을 전부 웨일즈에게 넘길 걸 그랬어.",
          DialogueId = 80190409,
          GUID = "C8BF8EFA",
          NextOptions = {
            [1] = 801904091
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190410] = {
          ContentKR = "......",
          DialogueId = 80190410,
          GUID = "C8BF8F24",
          NextDialogue = 80190411,
          SpeakNpcId = 95102
        },
        [80190411] = {
          ContentKR = "{空格}",
          DialogueId = 80190411,
          GUID = "C8BF8F4E",
          NextDialogue = 80190412,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190412] = {
          ContentKR = "좋아, 이제 좀 말해줘야 할 것 같아. 안 그러면 길 가다 포세이큰 동맹의 미친놈한테 괜히 찔리고도 누구 탓인지도 모르잖아.",
          DialogueId = 80190412,
          GUID = "C8BF8F78",
          NextDialogue = 80190413,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190413] = {
          ContentKR = "나 예전에 포세이큰 동맹이랑 좀... 문제가 있었거든. 그래서 걔네가 계속 날 찾고 있어. 그리고 며칠 전 그 의뢰가 내 행적을 노출<H>했을지도</> 몰라.",
          DialogueId = 80190413,
          GUID = "C8BF8FA2",
          NextDialogue = 80190414,
          SpeakNpcId = 95102
        },
        [80190414] = {
          ContentKR = "그래서 아이스레이크 시티에서 내 흔적을 지우느라 좀 애먹고 있어. 걔네가 진짜로 단서 따라 날 찾는 일은 없어야 하니까.",
          DialogueId = 80190414,
          GUID = "C8BF8FCC",
          NextDialogue = 80190415,
          SpeakNpcId = 95102
        },
        [80190415] = {
          ContentKR = "만약 걔네가 날 찾아내면, 내 친구들 다 고생하게 될 거야. 하나하나 끌려가서 내 행방 말할 때까지 심문당하겠지. 너도 예외는 아닐 거고.",
          DialogueId = 80190415,
          GUID = "C8BF8FF6",
          NextDialogue = 80190416,
          SpeakNpcId = 95102
        },
        [80190416] = {
          ContentKR = "뭐, 너는 그냥 내가 네 술친구일 뿐이라고 하면 돼. 나랑 관련된 건 전혀 모른다고 말하면 되고...",
          DialogueId = 80190416,
          GUID = "C8BF9020",
          NextOptions = {
            [1] = 801904161,
            [2] = 801904162
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190417] = {
          ContentKR = "에이, 그렇게 급하게 말 끊지 마. 아직 안 일어난 일이잖아. 근데... 진짜 그런 날이 온다면...",
          DialogueId = 80190417,
          GUID = "C8BF904A",
          NextDialogue = 80190418,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Think_Start"
          }
        },
        [80190418] = {
          ContentKR = "그때가 되면 너희도 떠나야 하고, 이 도시도 떠나야 해. 피나는 네가 좀 잘 부탁할게.",
          DialogueId = 80190418,
          GUID = "C8BF9074",
          NextDialogue = 80190419,
          SpeakNpcId = 95102
        },
        [80190419] = {
          ContentKR = "그녀가 물어보면 내가 큰 일 맡았다고만 해줘. 내가 편지를 몇 통 써뒀으니까, 그걸 한 달에 한 통씩 전해주면 한동안은 안심할 거야.",
          DialogueId = 80190419,
          GUID = "C8BF909E",
          NextDialogue = 80190420,
          SpeakNpcId = 95102
        },
        [80190420] = {
          ContentKR = "아, 그리고 내 집 난로 오른쪽 세 번째 벽돌 뒤에 돈 숨겨놨어. 그냥 가져다 써. 또 뭐 있었지...",
          DialogueId = 80190420,
          GUID = "C8BF90C8",
          NextDialogue = 80190421,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Think_End"
          }
        },
        [80190421] = {
          ContentKR = "아웃사이더, 일단 진정해.",
          DialogueId = 80190421,
          GUID = "C8BF90F2",
          NextDialogue = 80190422,
          SpeakNpcId = 790008
        },
        [80190422] = {
          ContentKR = "나 아주 차분해. 아까 내가 한 말 다시 말해봐. 나중에 내가 없을 때, 전부 네가 책임져야 하니까.",
          DialogueId = 80190422,
          GUID = "C8BF911C",
          NextDialogue = 80190423,
          SpeakNpcId = 95102
        },
        [80190423] = {
          ContentKR = "이건 네 평소 모습이 아니잖아. 포세이큰 동맹 때문이야?",
          DialogueId = 80190423,
          GUID = "C8BF9146",
          NextDialogue = 80190424,
          SpeakNpcId = 790008
        },
        [80190424] = {
          ContentKR = "평소? 평소 같아선 끝도 없는 미친놈들 감당 못 해.",
          DialogueId = 80190424,
          FacialId = {
            [1] = "95102:Unacceptable01"
          },
          GUID = "C8BF9170",
          NextDialogue = 80190425,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190425] = {
          ContentKR = "예를 들면, 정보 하나 얻으려고 네 손톱을 하나씩 다 뽑을 놈들이야.",
          DialogueId = 80190425,
          GUID = "C8BF919A",
          NextDialogue = 80190426,
          SpeakNpcId = 95102
        },
        [80190426] = {
          ContentKR = "그리고 이건 고작 그 미친놈들의 고문 시작일 뿐이야... 난 이런 일이 내 친구들한테 벌어지는 거, 보고 싶지 않아...",
          DialogueId = 80190426,
          GUID = "C8BF91C4",
          NextDialogue = 80190427,
          SpeakNpcId = 95102
        },
        [80190427] = {
          ContentKR = "근데 이건 아직 일어나지도 않았고, 너도 말했잖아. 네 행적이 <H>아마도</> 노출됐을 뿐이라고. 그렇지 않아?",
          DialogueId = 80190427,
          GUID = "C8BF91EE",
          NextDialogue = 80190428,
          SpeakNpcId = 790008
        },
        [80190428] = {
          ContentKR = "'아마도'라도 만반의 준비는 해야 해.",
          DialogueId = 80190428,
          GUID = "C8BF9218",
          NextDialogue = 80190429,
          SpeakNpcId = 95102
        },
        [80190429] = {
          ContentKR = "예전에도 그런 '아마도' 있었잖아? 지금이 그때보다 더 위험한 거야?",
          DialogueId = 80190429,
          GUID = "C8BF9242",
          NextDialogue = 80190430,
          SpeakNpcId = 790008
        },
        [80190430] = {
          ContentKR = "진짜 위험했던 때 생각해보면, 이번은 그리 대단한 것도 아니야...",
          DialogueId = 80190430,
          FacialId = {
            [1] = "95102:Think01"
          },
          GUID = "C8BF926C",
          NextDialogue = 80190431,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190431] = {
          ContentKR = "그거 봐, 그땐 어떻게 넘겼어?",
          DialogueId = 80190431,
          GUID = "C8BF9296",
          NextDialogue = 80190432,
          SpeakNpcId = 790008
        },
        [80190432] = {
          ContentKR = "...어떤 건 그냥 괜한 소문이었고, 어떤 건 내가 협박하거나 속이거나, 군단을 끌어들이거나 다른 도시에서 얼굴 비추는 식으로 처리했어.",
          DialogueId = 80190432,
          GUID = "C8BF92C0",
          NextOptions = {
            [1] = 801904321,
            [2] = 801904322
          },
          SpeakNpcId = 95102
        },
        [80190433] = {
          ContentKR = "{空格}",
          DialogueId = 80190433,
          GUID = "C8BF92EA",
          NextDialogue = 80190434,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190434] = {
          ContentKR = "그래... 네 말이 맞아. 방금 나는 좀... 이상했어. 더 위험한 일도 버텼으면서 이번엔 너무 일찍부터 '유언'을 맡겨버렸네.",
          DialogueId = 80190434,
          FacialId = {
            [1] = "95102:None"
          },
          GUID = "C8BF9314",
          NextDialogue = 80190435,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190435] = {
          ContentKR = "너랑 요즘 너무 많이 얘기해서일까, 아니면 무의식적으로 너라는 대장을 의지하고 싶었던 걸까... 아니면 내가 약해진 걸까...",
          DialogueId = 80190435,
          GUID = "C8BF933E",
          NextDialogue = 80190436,
          SpeakNpcId = 95102
        },
        [80190436] = {
          ContentKR = "아니 아니, 말도 안 돼! 오늘 술에 뭔가 이상한 게 분명해! 방금 나 이상한 말 한 거 없지? 없어, 절대 없어, 그치?",
          DialogueId = 80190436,
          GUID = "C8BF9368",
          NextOptions = {
            [1] = 801904361,
            [2] = 801904362
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190437] = {
          ContentKR = "그러니까 아직 안 일어난 '가능성'을 미리 걱정하느니, 일이 닥쳤을 때 나한테 부탁해. 그때면 더 나은 방법이 있을지도 모르잖아.",
          DialogueId = 80190437,
          GUID = "C8BF9392",
          NextDialogue = 80190438,
          SpeakNpcId = 790008
        },
        [80190438] = {
          ContentKR = "크흠, 그 말 좋다. 미래의 나한테 부탁할게! 자자, 한잔하자, 미래의 우리를 위해 건배!",
          DialogueId = 80190438,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF93BC",
          NextDialogue = 80190439,
          SpeakNpcId = 95102
        },
        [80190439] = {
          ContentKR = "{空格}",
          DialogueId = 80190439,
          GUID = "C8BF93E6",
          NextDialogue = 80190440,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190440] = {
          ContentKR = "아, 그런데 하나 사과할 게 있어. 미래에 대한 걱정은 좀 덜었지만, 내 과거에 대해서는 아직 전부 말해줄 수 없어.",
          DialogueId = 80190440,
          GUID = "C8BF9410",
          NextDialogue = 80190441,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190441] = {
          ContentKR = "하지만 약속할게. 언젠가는 내가 아이스레이크 시티로 오기 전에 어떤 길을 걸어왔는지 보여줄게. 그게 나한테 고통이 될 수도 있고, 네가 날 의심하게 만들 수도 있겠지만.",
          DialogueId = 80190441,
          GUID = "C8BF943A",
          NextDialogue = 80190442,
          SpeakNpcId = 95102
        },
        [80190442] = {
          ContentKR = "그래도 난 믿어. 그때가 오면, 너는 여전히 오늘처럼 나를 위해 술 한 잔을 따라줄 거라고. 내 친구야.",
          DialogueId = 80190442,
          GUID = "C8BF9464",
          SpeakNpcId = 95102
        },
        [80200001] = {
          Camera = "371.189178,358.122345,166.996094,0.000053,-4.198886,-152.598816,30.0,1011.382263,false,Manual,2.8",
          ContentKR = "봄에는 나물 캐고, 여름엔 비름이 자라네. 가을엔 탱자가 열리고, 겨울엔 영지...",
          DialogueId = 80200001,
          FinalCamera = "255.737183,256.213654,144.412109,0.000053,-4.398778,-152.798981,30.000002,1011.382263,false,Manual,2.8",
          GUID = "C8C5B4AA",
