          ToFinalCameraBlendTime = 15
        },
        [80200002] = {
          Camera = "-38.314407,-310.574463,154.504883,0.000081,-6.798982,91.19931,30.0,1011.382263,false,Manual,2.8",
          ContentKR = "볕 들지 않는 곳엔 무회목, 빙설 속엔 보라이슬꽃, 풀숲에는 푸른 향여, 향이 짙은 덤불엔 고창...",
          DialogueId = 80200002,
          FinalCamera = "-29.192467,-310.X3083385254,154.504883,0.000081,-6.798975,91.199326,30.0,1011.382263,false,Manual,2.8",
          GUID = "C8C5B4D4",
          NextOptions = {
            [1] = 802000021,
            [2] = 802000022,
            [3] = 802000023
          },
          Scripts = [[
PARA{
