}]],
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          ToFinalCameraBlendTime = 8
        },
        [80200004] = {
          ContentKR = "맞아요. 모두 약으로 쓰이는 식물인데, 어떤 건 그냥 먹어도 돼요.",
          DialogueId = 80200004,
          GUID = "C8C5B528",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          }
        },
        [80200006] = {
          ContentKR = "후후, 이런 것도 아시네요. 맞아요, <초목정요>에 나오는 내용들이에요.",
          DialogueId = 80200006,
          GUID = "C8C5B57C",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          }
        },
        [80200008] = {
          ContentKR = "아니에요, 우리 사이에 그런 데 신경 쓸 필요 없어요. 이렇게 만나러 와 준 것만으로도, 전 기쁘답니다.",
          DialogueId = 80200008,
          GUID = "C8C5B5D0",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          }
        },
        [80200009] = {
          Camera = "-299.287354,935.059692,618.705078,0.000024,-30.199797,-77.19545,30.0,1011.382263,false,Manual,1.2",
          ContentKR = "마침 책도 실컷 읽었으니까, 이제 좀 쉬려던 참이었어요.",
          DialogueId = 80200009,
          FinalCamera = "-309.453308,979.785645,645.397461,0.000024,-30.199797,-77.19545,30.0,1011.382263,false,Manual,1.2",
          GUID = "C8C5B5FA",
