          NextDialogue = 80200103,
          SpeakNpcId = 790008
        },
        [80200103] = {
          Camera = "156.736298,261.858429,-44.504395,0.00016,19.196335,-129.566406,25.0,3742.911621,false,Manual,2.8",
          ContentKR = "<초목정요>의 부록에 실려 있는 노래예요. 약초들이 어디서 자라는지 간단히 소개해서, 사람들이 쉽게 찾을 수 있게 만든 거죠.",
          DialogueId = 80200103,
          Duration = 8,
          FinalCamera = "183.388687,302.15509,-62.86084,0.000161,16.596128,-128.566315,25.000002,3742.911621,false,Manual,2.8",
          GUID = "C8C5C566",
          NextDialogue = 80200104,
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 15
        },
        [80200104] = {
          ContentKR = "이제는 화서 사람이라면 누구나 한두 소절은 흥얼거릴 수 있을 정도로 유명한 노래예요.",
          DialogueId = 80200104,
          Duration = 6,
          GUID = "C8C5C590",
          NextDialogue = 80200105,
          SpeakNpcId = 790053,
          TurnTo = {
            [1] = "790053:p(-170)"
          }
        },
        [80200105] = {
          ContentKR = "알아 두면, 벌레나 뱀에게 물리거나, 갑자기 아플 때 곧바로 약초를 구해서 응급 처치를 할 수 있으니까요.",
          DialogueId = 80200105,
          Duration = 6,
          GUID = "C8C5C5BA",
          NextDialogue = 80200106,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain01_Start"
          }
        },
        [80200106] = {
          Camera = "-2187.130371,-194.541107,374.618164,0.000288,-27.004087,6.03826,25.0,3742.911621,false,Manual,2.8",
          ContentKR = "제가 방금 부른 부분들은, 시냇물 밑에서는 어리연꽃을, 연못에서는 로터스를 구할 수 있다는 거예요. 그리고 회몽초는 대개 나무 밑, 버섯 옆에서 자라지만...",
          DialogueId = 80200106,
          Duration = 8,
          FinalCamera = "-2190.606445,-161.720963,374.618164,0.000287,-27.004074,6.037409,25.0,3742.911621,false,Manual,2.8",
          GUID = "C8C5C5E4",
          NextDialogue = 80200107,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain01_End"
          },
          ToFinalCameraBlendTime = 15
        },
        [80200107] = {
          ContentKR = "음용초라는 식물하고 거의 똑같이 생겨서, 경험 많은 의사나 약초꾼이 아닌 이상, 거의 구별이 불가능해요.",
          DialogueId = 80200107,
          Duration = 10,
          GUID = "C8C5C60E",
