        [80200109] = {
          Camera = "-1918.365234,-1427.544067,372.914551,0.000298,-5.003871,29.641459,25.0,3742.911621,false,Manual,2.8",
          ContentKR = "(부소가 낡은 책을 하나 펼쳐 보여 준다. 루카 공화국의 전위 예술에 버금가는 그림을 본 나와 부소는, 서로를 어색하게 바라볼 뿐이다.)",
          DialogueId = 80200109,
          Duration = 8,
