          NextDialogue = 80200206,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Think_Start"
          }
        },
        [80200206] = {
          Camera = "-37.011719,125.353516,135.46582,0.000068,-2.597596,-30.799438,30.000008,198.114532,false,DoNotOverride,4.214613",
          ContentKR = "내가 먹어보는 게 맞아. 의사는 내가 아니라 부소잖아.",
          DialogueId = 80200206,
          GUID = "C8C5D010",
          NextDialogue = 80200207,
          SpeakNpcId = 790008,
          TalkActionId = {
            [1] = "790008:Talk03_Start"
          }
        },
        [80200207] = {
          ContentKR = "혹시라도 문제가 생기면 난 부소가 있지만, 부소가 쓰러져 버리면? 난 약이랑 고영법을 전혀 모르잖아. 멀뚱멀뚱 보고만 있으라고?",
          DialogueId = 80200207,
          GUID = "C8C5D03A",
          NextDialogue = 80200208,
          SpeakNpcId = 790008,
          TalkActionId = {
            [1] = "790008:Talk03_End"
          }
        },
        [80200208] = {
          Camera = "189.535156,595.197266,351.47168,0.000101,-23.797915,-110.191658,30.000002,198.114532,false,Manual,4.214613",
          ContentKR = "그건... 그래도 안 돼요. 그 부분은 미처 생각을 못 했지만, 다른 방법을 찾아보면....",
          DialogueId = 80200208,
          FinalCamera = "199.355469,621.927734,364.026855,0.000102,-23.797915,-110.191658,30.000002,198.114532,false,Manual,4.214613",
          GUID = "C8C5D064",
          LookAt = {
