          },
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "790053:p(75)"
          }
        },
        [80200209] = {
          ContentKR = "(부소의 말이 끝나기도 전에, 나는 손톱만 한 잎사귀를 떼어 입안에 넣는다.)",
          DialogueId = 80200209,
          GUID = "C8C5D08E",
          LookAt = {
            [1] = "790008:n(790053)"
          },
          NextDialogue = 80200210,
          TurnTo = {
            [1] = "790008:n(790053)",
            [2] = "790053:n(790008)"
          }
        },
        [80200210] = {
          Camera = "10.083984,-16.130859,124.486328,0.000127,5.801269,142.400635,25.000006,523.327209,false,DoNotOverride,1.2",
          ContentKR = "앗!",
          DialogueId = 80200210,
          GUID = "C8C5D0B8",
          NextDialogue = 80200211,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          }
        },
        [80200211] = {
          ContentKR = "왜 이런 행동을... 아니, 지금 이럴 때가 아니라...",
          DialogueId = 80200211,
          GUID = "C8C5D0E2",
          NextDialogue = 80200212,
          Scripts = [[
PARA{
CameraMoveTo{_delay{3.01},TargetPosition{"-54.814453,90.382812,175.259277,0.000145,-23.597721,3.001867,35.0,111.63089,false,Manual,20.07291"},duration{0}},
MoveTo{_delay{3.01},ActorId{790053},TargetPoint{"BP_200301a_fushu01"},MoveSpeed{100},Visibility{"Show"}}
}]],
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          }
        },
        [80200212] = {
          ContentKR = "기분은 좀 어때요?",
          DialogueId = 80200212,
          GUID = "C8C5D10C",
          NextDialogue = 80200213,
          SpeakNpcId = 790053
        },
        [80200213] = {
          Camera = "37.232422,103.78125,138.741211,0.000152,7.400476,169.987396,35.0,111.63089,false,Manual,20.07291",
          ContentKR = "음... 나쁘지 않아. 약간 민트 맛이 나서, 입안이 엄청 상쾌...",
          DialogueId = 80200213,
          GUID = "C8C5D136",
          NextDialogue = 80200214,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{4.01},TargetPosition{"37.232422,103.78125,138.741211,0.000152,7.400476,169.987396,35.0,111.63089,false,Manual,20.07291"},duration{0}},
CameraMoveTo{TargetPosition{"25.619141,105.791016,140.636719,0.000142,55.800377,168.787918,35.0,111.63089,false,Manual,20.07291"},Blend{"easeInOutQuad"},duration{1}}
}]],
          SpeakNpcId = 790008
        },
        [80200214] = {
          ContentKR = "(부소의 얼굴이 점차 흐릿해지면서, 나는 한 가지 사실을 깨달았다. 나는 음용초에 내성이 없는 체질이었다.)",
          DialogueId = 80200214,
          GUID = "C8C5D160",
          IsBlack = 1
        },
        [80200215] = {
          ContentKR = "환각에 진입한다. 주인공은 고영각 안에서 등장하고, NPC 부풍은 주인공에게 등을 돌린 채 서 있다.",
          DialogueId = 80200215,
          GUID = "C8C5D18A"
        },
        [80200216] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentKR = "아... 머리 아파... 여긴 고영각인가?",
          DialogueId = 80200216,
          GUID = "C8C5D1B4",
          NextDialogue = 80200217,
          SpeakNpcId = 790008
        },
        [80200217] = {
          ContentKR = "저 사람은... 부소?",
          DialogueId = 80200217,
          GUID = "C8C5D1DE",
          NextDialogue = 80200218,
          SpeakNpcId = 790008
        },
        [80200218] = {
          ContentKR = "귀찮아, 진짜 귀찮아, 귀찮아 죽겠어!",
          DialogueId = 80200218,
          GUID = "C8C5D208",
          NextDialogue = 80200219,
          SpeakNpcId = 790054,
          SpeakNpcName = "？？？"
        },
        [80200219] = {
          ContentKR = "으, 아침에 일어날 때만 해도, 오늘은 절대 걔 속 긁지 말자고 그렇게 다짐했잖아. 어떻게 아침도 다 먹기 전에 그걸 못 참니!",
          DialogueId = 80200219,
          GUID = "C8C5D232",
          NextDialogue = 80200220,
          SpeakNpcId = 790054,
          SpeakNpcName = "？？？"
        },
        [80200220] = {
          ContentKR = "부풍아, 내가 진짜 못 살아! 넌 대체 왜 이렇게 참을성이 없는 거야! 성격이 아무리 나빠도, 걔는 네 친동생이잖아! 어차피 챙겨 줄 거면서, 왜 자꾸 걜 화나게 만드는 건데!",
          DialogueId = 80200220,
          GUID = "C8C5D25C",
          NextDialogue = 80200221,
          SpeakNpcId = 790054,
          SpeakNpcName = "？？？"
        },
        [80200221] = {
          ContentKR = "나도 어쩔 수가 없어. 부소가 그렇게 정색하고 있으면, 엄청 약 올리고 싶은걸... 걔한테서 웃음이 사라진 게 아니라, 나한테 옮겨 온 거라니까...",
          DialogueId = 80200221,
          GUID = "C8C5D286",
          NextDialogue = 80200222,
          SpeakNpcId = 790054
        },
        [80200222] = {
          ContentKR = "당연한 거 아냐? 다들 나랑 똑같이 생각할걸!",
          DialogueId = 80200222,
          GUID = "C8C5D2B0",
          NextDialogue = 80200223,
          SpeakNpcId = 790054
        },
        [80200223] = {
          ContentKR = "부, 부소? 너 맞아?",
          DialogueId = 80200223,
          GUID = "C8C5D2DA",
          NextDialogue = 80200224,
          SpeakNpcId = 790008
        },
        [80200224] = {
          ContentKR = "아니, 난 걔 쌍둥이 언니 부풍이야. 다들 우리 둘을 헷갈리더라. 너만 그런 게 아니야.",
          DialogueId = 80200224,
          GUID = "C8C5D304",
          NextDialogue = 80200225,
          SpeakNpcId = 790054
        },
        [80200225] = {
          ContentKR = "부소한테 볼일 있어? 이상하네, 걘 원래 남이랑 잘 안 어울리는 앤데. 그 답답이가 아는 사람도 있었네?",
          DialogueId = 80200225,
          GUID = "C8C5D32E",
          NextOptions = {
            [1] = 802002251,
            [2] = 802002252,
            [3] = 802002253
          },
          SpeakNpcId = 790054
        },
        [80200226] = {
          ContentKR = "와... 어린 친구 같은데 걔를 답답이가 아니라 좋은 애라고 칭찬하다니. 좋아, 나쁘지 않네. 부소랑 친구면, 나하고도 친구지!",
          DialogueId = 80200226,
          GUID = "C8C5D382",
          NextDialogue = 80200229,
          SpeakNpcId = 790054
        },
        [80200227] = {
          ContentKR = "우리 고영각에 돈을 뜯으러 왔다고?! 동네 사람들한테 물어봐, 우리 답답이 주머니에 땡전 한 푼 있나. 덤터기 씌우려면 상대를 잘못 골랐어. 부소가 아니라 나한테 씌웠어야지!",
          DialogueId = 80200227,
          GUID = "C8C5D3D6",
          NextDialogue = 80200229,
          SpeakNpcId = 790054
        },
        [80200228] = {
          ContentKR = "와, 입에 침이나 바르고 그런 소리 해. 어디 아픈 거 아니면 얼른 집에 가서 놀아. 착하지?",
          DialogueId = 80200228,
          GUID = "C8C5D42A",
          NextDialogue = 80200229,
          SpeakNpcId = 790054
        },
        [80200229] = {
          ContentKR = "그래서, 고영각엔 무슨 일로 온 거야?",
          DialogueId = 80200229,
          GUID = "C8C5D454",
          NextDialogue = 80200230,
          SpeakNpcId = 790054
        },
        [80200230] = {
          ContentKR = "잘못해서 음용초를 먹는 바람에, 머리도 어지럽고 이상한 게 보여요. 부소라면 낫게 해 줄 것 같아서 찾아온 거예요.",
          DialogueId = 80200230,
          GUID = "C8C5D47E",
          NextDialogue = 80200231,
          SpeakNpcId = 790008
        },
        [80200231] = {
          ContentKR = "운이 없구나. 부소는 지금 단단히 토라져 있으니까, 이럴 땐 안 건드리는 게 좋아. 아쉬운 대로 내가 봐 줄게. 나도 의사거든.",
          DialogueId = 80200231,
          GUID = "C8C5D4A8",
          NextDialogue = 80200232,
          SpeakNpcId = 790054
        },
        [80200232] = {
          ContentKR = "어디 좀 보자...",
          DialogueId = 80200232,
          GUID = "C8C5D4D2",
          NextDialogue = 80200233,
          SpeakNpcId = 790054
        },
        [80200233] = {
          ContentKR = "음... 걷는 건 멀쩡하고, 눈이랑 혀도 안 풀렸고, 말도 똑바로 잘하는 걸 보니까 많이 먹진 않았나 보네. 대충 잎사귀 반 개 정도?",
          DialogueId = 80200233,
          GUID = "C8C5D4FC",
          NextDialogue = 80200234,
          SpeakNpcId = 790054
        },
        [80200234] = {
          ContentKR = "별로 심각하진 않아. 해독제 달이기도 전에 다 나을걸. 겁먹지 말고, 조금만 더 참고 기다려 봐. 금방 괜찮아질 거야.",
          DialogueId = 80200234,
          GUID = "C8C5D526",
          NextDialogue = 80200235,
          SpeakNpcId = 790054
        },
        [80200235] = {
          ContentKR = "정 못 견디겠으면, 내가 가지고 다니는 탱자환이 있는데, 두어 개 씹어 먹으면 좀 나아질 거야.",
          DialogueId = 80200235,
          GUID = "C8C5D550",
          NextDialogue = 80200236,
          SpeakNpcId = 790054
        },
        [80200236] = {
          ContentKR = "평소에 잠도 잘 못 자고, 꿈도 많이 꾸는 편이지? 그래서 회몽초로 낫게 해 보려다가, 거의 똑같이 생긴 음용초를 먹어 버린 모양이네.",
          DialogueId = 80200236,
          GUID = "C8C5D57A",
          NextDialogue = 80200237,
          SpeakNpcId = 790054
        },
        [80200237] = {
          ContentKR = "사실 네 증상엔 땅의 가지랑 틈새의 꽃을 같이 달여 먹는 게 훨씬 효과가 좋아. 회몽초는 잠은 잘 오게 해 주지만, 대신 가슴에 묻지 못한 일들을 꿈에서 보게 되니까, 괜히 마음만 상하거든.",
          DialogueId = 80200237,
          GUID = "C8C5D5A4",
          NextDialogue = 80200238,
          SpeakNpcId = 790054
        },
        [80200238] = {
          ContentKR = "...생김새 말고도, 부소랑 정말 많이 닮았네요.",
          DialogueId = 80200238,
          GUID = "C8C5D5CE",
          NextDialogue = 80200239,
          SpeakNpcId = 790008
        },
        [80200239] = {
          ContentKR = "그런 말은 처음 듣네. 나랑 부소는 쌍둥이지만, 다들 난 '정도를 벗어난' 인간 같다고 하던데. 대풍구장 아홉 번째 규율에 전혀 안 맞다면서 말이야.",
          DialogueId = 80200239,
          GUID = "C8C5D5F8",
          NextDialogue = 80200240,
          SpeakNpcId = 790054
        },
        [80200240] = {
          ContentKR = "부소는 차가워 보이고, 그쪽은 활발해 보이지만, 환자를 대하는 태도는 똑같아요. 진지하면서도 상냥하고, 참을성 있죠.",
          DialogueId = 80200240,
          GUID = "C8C5D622",
          NextDialogue = 80200241,
          SpeakNpcId = 790008
        },
        [80200241] = {
          ContentKR = "너... 부소랑 친하다고 했던 거 믿어 줄게.",
          DialogueId = 80200241,
          GUID = "C8C5D64C",
          NextDialogue = 80200242,
          SpeakNpcId = 790054
        },
        [80200242] = {
          ContentKR = "걔가 좀 꽉 막혔잖아. 하고 싶은 말은 속에 담아 두기만 하고, 말주변도 별로라 속마음을 제대로 표현하질 못해.",
          DialogueId = 80200242,
          GUID = "C8C5D676",
          NextDialogue = 80200243,
          SpeakNpcId = 790054
        },
        [80200243] = {
          ContentKR = "아무래도... 너처럼 속 깊은 사람이라야 걔 친구 노릇을 해 줄 수 있나 보네!",
          DialogueId = 80200243,
          GUID = "C8C5D6A0",
          NextDialogue = 80200244,
          SpeakNpcId = 790054
        },
        [80200244] = {
          ContentKR = "말로 사람 속 긁는 건 내 전문인데, 내가 졌다.",
          DialogueId = 80200244,
          GUID = "C8C5D6CA",
          NextDialogue = 80200245,
          SpeakNpcId = 790054
        },
        [80200245] = {
          ContentKR = "자, 부소의 친구 씨! 이 {性别:누나|언니}가 부탁 하나만 할게. 내 동생을 봐서라도, 당연히 들어 줄 거지?",
          DialogueId = 80200245,
          GUID = "C8C5D6F4",
          NextDialogue = 80200246,
          SpeakNpcId = 790054
        },
        [80200246] = {
          ContentKR = "뭔지 들어 보고요.",
          DialogueId = 80200246,
          GUID = "C8C5D71E",
          NextDialogue = 80200247,
          SpeakNpcId = 790008
        },
        [80200247] = {
          ContentKR = "부소한테 줄 화해의 선물을 하나 찾아다 줄래?",
          DialogueId = 80200247,
          GUID = "C8C5D748",
          NextDialogue = 80200248,
          SpeakNpcId = 790054
        },
        [80200248] = {
          ContentKR = "이 근처에 있는 물가에 수성 오징어가 자주 나타나거든. 나 대신 몇 마리만 낚아 와 줘. 별로 안 어렵지!",
          DialogueId = 80200248,
          GUID = "C8C5D772",
          SpeakNpcId = 790054
        },
        [80200301] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentKR = "와... 진짜 낚았구나, 대단해. 나 같은 만능 천재도 하루 종일 앉아 있어야 한 마리 낚을까 말까인데...",
          DialogueId = 80200301,
          GUID = "C8C5E5E2",
          NextDialogue = 80200302,
          SpeakNpcId = 790054
        },
        [80200302] = {
          ContentKR = "만능 천재는 아닌 걸로 아는데요.",
          DialogueId = 80200302,
          GUID = "C8C5E60C",
          NextDialogue = 80200303,
          SpeakNpcId = 790008
        },
        [80200303] = {
          ContentKR = "부소가 부풍 씨 그림을 보여 준 적 있어요. 꽤 난해하던데요.",
          DialogueId = 80200303,
          GUID = "C8C5E636",
          NextDialogue = 80200304,
          SpeakNpcId = 790008
        },
        [80200304] = {
          ContentKR = "...둘이 그렇게 친했어? 우리 집안 망신거리까지 알려 주면 어떡해?",
          DialogueId = 80200304,
          GUID = "C8C5E660",
          NextDialogue = 80200305,
          SpeakNpcId = 790054
        },
        [80200305] = {
          ContentKR = "크흠... 그런데 부소가 수성 오징어를 좋아한다는 건 진짜 몰랐어요.",
          DialogueId = 80200305,
          GUID = "C8C5E68A",
          NextDialogue = 80200306,
          SpeakNpcId = 790008
        },
        [80200306] = {
          ContentKR = "걔 그거 안 좋아해.",
          DialogueId = 80200306,
          GUID = "C8C5E6B4",
          NextDialogue = 80200307,
          SpeakNpcId = 790054
        },
        [80200307] = {
          ContentKR = "부소가 제일 싫어하는 게 수성 오징어야. 어렸을 땐 그거 보고 놀라서 운 적도 있어!",
          DialogueId = 80200307,
          GUID = "C8C5E6DE",
          NextOptions = {
            [1] = 802003071,
            [2] = 802003072,
            [3] = 802003073
          },
          SpeakNpcId = 790054
        },
        [80200311] = {
          ContentKR = "사실 요즘 걔랑 좀 싸웠거든. 왜 싸웠는지는 대충 알지?",
          DialogueId = 80200311,
          GUID = "C8C5E786",
          NextDialogue = 80200312,
          SpeakNpcId = 790054
        },
        [80200312] = {
          ContentKR = "매번 똑같아. 난 환자를 치료할 수 있는 새로운 방법을 연구하고 싶은데, 걔는 고영법을 고수해야 한다고 생각하거든.",
          DialogueId = 80200312,
          GUID = "C8C5E7B0",
          NextDialogue = 80200313,
          SpeakNpcId = 790054
        },
        [80200313] = {
          ContentKR = "솔직히 말해서, 걔 말도 일리는 있어. 내 방법은 성공할지 못 할지도 불확실한 데다가, 대풍구장을 거스르는 거니까...",
          DialogueId = 80200313,
          GUID = "C8C5E7DA",
          NextDialogue = 80200314,
          SpeakNpcId = 790054
        },
        [80200314] = {
          ContentKR = "나랑 내 연구가 어떤 결말을 맞이하게 될진, 아무도 몰라.",
          DialogueId = 80200314,
          GUID = "C8C5E804",
          NextDialogue = 80200315,
          SpeakNpcId = 790054
        },
        [80200315] = {
          ContentKR = "그래도 이거 하나는 확실해. 계속 고영법을 사용했다간, 부소는 제명에 못 죽을 거야.",
          DialogueId = 80200315,
          GUID = "C8C5E82E",
          NextDialogue = 80200316,
          SpeakNpcId = 790054
        },
        [80200316] = {
          ContentKR = "그리고 난... 그 꼴은 못 봐. 그래서 양보하지 않을 거고, 우린 계속 싸울 수밖에 없어.",
          DialogueId = 80200316,
          GUID = "C8C5E858",
          NextDialogue = 80200317,
          SpeakNpcId = 790054
        },
        [80200317] = {
          ContentKR = "하여간, 언니 속도 모르는 동생을 뒀으니 어쩌겠어. 그렇지만 내가 먼저 사과해야 하더라도, 곱게는 못 넘어가지!",
          DialogueId = 80200317,
          GUID = "C8C5E882",
          NextDialogue = 80200318,
          SpeakNpcId = 790054
        },
        [80200318] = {
          ContentKR = "그런데 난 지금 걔 근처에도 못 가니까, 이 귀염둥이들은 네가 대신 전해 줘! 걔는 널 철석같이 믿으니까, 전혀 의심 안 할걸. 어쩌면 어릴 때처럼 깜짝 놀라서 울어 버릴지도 몰라.",
          DialogueId = 80200318,
          GUID = "C8C5E8AC",
          NextOptions = {
            [1] = 80200319
          },
          SpeakNpcId = 790054
        },
        [80200319] = {
          ContentKR = "수성 오징어라...",
          DialogueId = 80200319,
          GUID = "C8C5E8D6",
          NextDialogue = 80200320
        },
        [80200320] = {
          ContentKR = "그냥 빙빙 돌려서 '오래오래 살았으면 좋겠다'고 말하려는 거잖아요?",
          DialogueId = 80200320,
          GUID = "C8C5E900",
          NextDialogue = 80200321,
          SpeakNpcId = 790008
        },
        [80200321] = {
          ContentKR = "음... 알아도 모르는 척해 줘. 이런 속마음은 얘기해 버리면 재미가 없잖아. 난 부소가 화내는 걸 보고 싶단 말이야!",
          DialogueId = 80200321,
          GUID = "C8C5E92A",
          NextDialogue = 80200322,
          SpeakNpcId = 790054
        },
        [80200322] = {
          ContentKR = "그럼 빨리 가 봐! 얼른!",
          DialogueId = 80200322,
          GUID = "C8C5E954",
          SpeakNpcId = 790054
        },
        [80200323] = {
          ContentKR = "환상에서 깨어나, 약초 채집 퀘스트 지점1로 돌아온다. 부소와 함께 서 있다.",
          DialogueId = 80200323,
          GUID = "C8C5E97E"
        },
        [80200324] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentKR = "깨어났군요!",
          DialogueId = 80200324,
          GUID = "C8C5E9A8",
          NextDialogue = 80200325,
          SpeakNpcId = 790053
        },
        [80200325] = {
          ContentKR = "고작 몇 분이었지만 얼마나 걱정했는지 몰라요... 제가 책 내용을 잘못 기억한 건 아닌지, 독성이 생각보다 강했던 건 아닌지 온갖 걱정을 다 했어요.",
          DialogueId = 80200325,
          GUID = "C8C5E9D2",
          NextDialogue = 80200326,
          SpeakNpcId = 790053
        },
        [80200326] = {
          ContentKR = "고영법을 사용하려고 했었는데, 제가 뭘 끝내기도 전에 정신을 차릴까 봐...",
          DialogueId = 80200326,
          GUID = "C8C5E9FC",
          NextDialogue = 80200327,
          SpeakNpcId = 790053
        },
        [80200327] = {
          ContentKR = "풉... 언니랑 똑같구나...",
          DialogueId = 80200327,
          GUID = "C8C5EA26",
          NextDialogue = 80200328,
          SpeakNpcId = 790008
        },
        [80200328] = {
          ContentKR = "당신도... 언니를 만났어요?",
          DialogueId = 80200328,
          GUID = "C8C5EA50",
          NextDialogue = 80200329,
          SpeakNpcId = 790053
        },
        [80200329] = {
          ContentKR = "응, 혹시 기억나? 싸우고 나서, 언니가 화해의 선물이라면서 부소가 제일 싫어하는 수성 오징어를 줬었잖아.",
          DialogueId = 80200329,
          GUID = "C8C5EA7A",
          NextDialogue = 80200330,
          SpeakNpcId = 790008
        },
        [80200330] = {
          ContentKR = "...까맣게 잊고 있었어요. 정말, 아주 오래전 일이네요.",
          DialogueId = 80200330,
          GUID = "C8C5EAA4",
          NextDialogue = 80200331,
          SpeakNpcId = 790053
        },
        [80200331] = {
          ContentKR = "사과는 받아 줬어?",
          DialogueId = 80200331,
          GUID = "C8C5EACE",
          NextDialogue = 80200332,
          SpeakNpcId = 790008
        },
        [80200332] = {
          ContentKR = "후후... 아니요, 또 한바탕 싸웠어요. 후회하는 건 아니지만...",
          DialogueId = 80200332,
          GUID = "C8C5EAF8",
          NextDialogue = 80200333,
          SpeakNpcId = 790053
        },
        [80200333] = {
          ContentKR = "지금의 저였다면, 그 수성 오징어를 기꺼이 받아 줬을지도 모르겠네요.",
          DialogueId = 80200333,
          GUID = "C8C5EB22",
          NextDialogue = 80200334,
          SpeakNpcId = 790053
        },
        [80200334] = {
          ContentKR = "...어디까지나 가정일 뿐이지만요. 전 다리가 많이 달린 생물은 질색이거든요. 진짜, 진짜로요.",
          DialogueId = 80200334,
          GUID = "C8C5EB4C",
          NextDialogue = 80200335,
          SpeakNpcId = 790053
        },
        [80200335] = {
          ContentKR = "사실... 이런 옛날 일들을 당신한테 보여주지 말아야 했어요. 이미 다 지나간 일이고, 떠나간 사람들이잖아요. 봐도 괜히 마음만 아프고 좋을 게 없는걸요.",
          DialogueId = 80200335,
          GUID = "C8C5EB76",
          NextDialogue = 80200336,
          SpeakNpcId = 790053
        },
        [80200336] = {
          ContentKR = "하지만 이 고영각은 우리 자매가 나고 자란 곳이니까, 이곳 음용초엔 전부 저랑 언니의 옛이야기가 담겨 있을지도 몰라요.",
          DialogueId = 80200336,
          GUID = "C8C5EBA0",
          NextDialogue = 80200337,
          SpeakNpcId = 790053
        },
        [80200337] = {
          ContentKR = "그러니까 다음엔 제가 먹어 볼게요. 괜찮죠?",
          DialogueId = 80200337,
          GUID = "C8C5EBCA",
          NextOptions = {
            [1] = 802003371,
            [2] = 802003372
          },
          SpeakNpcId = 790053
        },
        [80200339] = {
          ContentKR = "고마워요.",
          DialogueId = 80200339,
          GUID = "C8C5EC1E",
          NextDialogue = 80200342,
          SpeakNpcId = 790054
        },
        [80200341] = {
          ContentKR = "후후, 다음에 만날 때 저하고 언니 얘기를 들려줄게요.",
          DialogueId = 80200341,
          GUID = "C8C5EC72",
          NextDialogue = 80200342,
          SpeakNpcId = 790054
        },
        [80200342] = {
          ContentKR = "자, 이제 다음 장소로 가서 찾아보죠.",
          DialogueId = 80200342,
          GUID = "C8C5EC9C",
          SpeakNpcId = 790053
        },
        [80200343] = {
          ContentKR = "장면 전환, 고영각 야외",
          DialogueId = 80200343,
          GUID = "C8C5ECC6"
        },
        [80200344] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentKR = "찾았어요.",
          DialogueId = 80200344,
          GUID = "C8C5ECF0",
          NextDialogue = 80200345,
          SpeakNpcId = 790053
        },
        [80200345] = {
          ContentKR = "문제 하나 낼게요. 이건 음용초일까요? 회몽초일까요?",
          DialogueId = 80200345,
          GUID = "C8C5ED1A",
          NextOptions = {
            [1] = 802003451,
            [2] = 802003452
          },
          SpeakNpcId = 790053
        },
        [80200348] = {
          ContentKR = "눈으론 구별이 안 되지만, 손으로 만져 보면 미묘하게 달라요... 아무리도 이게 우리가 찾던 회몽초인 것 같네요.",
          DialogueId = 80200348,
          GUID = "C8C5ED98",
          NextDialogue = 80200349,
          SpeakNpcId = 790053
        },
        [80200349] = {
          ContentKR = "두 번이나 연달아 실패하지 않았다면, 전 이 차이를 영원히 알아채지 못했을 거예요.",
          DialogueId = 80200349,
          GUID = "C8C5EDC2",
          NextDialogue = 80200350,
          SpeakNpcId = 790053
        },
        [80200350] = {
          ContentKR = "맨 처음 이 두 식물을 발견한 사람은 이걸 어떻게 구분했을까? 그 사람도 우리처럼 하나씩 먹어 봤으려나?",
          DialogueId = 80200350,
          GUID = "C8C5EDEC",
          NextDialogue = 80200351,
          SpeakNpcId = 790008
        },
        [80200351] = {
          ContentKR = "후후... 그러게요. 어떻게 구분했던 걸까요?",
          DialogueId = 80200351,
          GUID = "C8C5EE16",
          NextDialogue = 80200352,
          SpeakNpcId = 790053
        },
        [80200352] = {
          ContentKR = "분명히 수없이 위험에 처하고, 수많은 밤을 새우며 연구했을 거예요. 남들이 이해해 주지 않아도, 고통에 시달리더라도, 절대로 포기하지 않았을 거고요.",
          DialogueId = 80200352,
          GUID = "C8C5EE40",
          NextDialogue = 80200353,
          SpeakNpcId = 790053
        },
        [80200353] = {
          ContentKR = "그 모든 건, 아득한 옛날부터 이어져 내려온, 의술로 인간을 구제한다는 신념을 위해서였겠죠.",
          DialogueId = 80200353,
          GUID = "C8C5EE6A",
          NextDialogue = 80200354,
          SpeakNpcId = 790053
        },
        [80200354] = {
          ContentKR = "사실, 깜빡하고 말 안 한 게 있어. 아까 만난 부풍 씨가 그랬는데, 내 증상엔 땅의 가지랑 틈새의 꽃을 쓰는 게 더 좋대.",
          DialogueId = 80200354,
          GUID = "C8C5EE94",
          NextDialogue = 80200355,
          SpeakNpcId = 790008
        },
        [80200355] = {
          ContentKR = "회몽초를 쓰면 잠은 잘 오겠지만, 가슴에 묻지 못한 일들을 꿈에서 보게 된다더라고.",
          DialogueId = 80200355,
          GUID = "C8C5EEBE",
          NextDialogue = 80200356,
          SpeakNpcId = 790008
        },
        [80200356] = {
          ContentKR = "그러니까, 나한텐 회몽초가 필요 없을 것 같아. 그래도 부소는 먹어 볼 생각이야?",
          DialogueId = 80200356,
          GUID = "C8C5EEE8",
          NextDialogue = 80200357,
          SpeakNpcId = 790008
        },
        [80200357] = {
          ContentKR = "부소는 아무 말 없이, 아까처럼 잎사귀를 입에 넣었다. 이번에는 불안해하지도, 누구를 비난하지도 않았다. 귀에 들려오는 건 고른 숨소리와 희미한 잠꼬대뿐이었다...",
          DialogueId = 80200357,
          GUID = "C8C5EF12",
          IsBlack = 1,
          NextDialogue = 80200358
        },
        [80200358] = {
          ContentKR = "에휴... 다음엔 화해의 선물로 다른 걸 줘야겠네.",
          DialogueId = 80200358,
          GUID = "C8C5EF3C",
          SpeakNpcId = 790053
        },
        [88888801] = {
          DialogueId = 88888801,
          DialoguePanelType = "None",
          Duration = 5,
          GUID = "DE8616EA",
          Scripts = "SEQ{SetRotation{SetRotationDescription{\"888888:n(0)\"}},PlayAnimation{ActorId{0},AnimationId{\"Cat_Interactive01\"}}}",
          SpeakNpcId = 888888,
          bAllowClickSkipScript = false
        },
        [90000001] = {
          ContentKR = "젊은이, 전에 갖고 싶어하던 그 좋은 물건 말이야. 이 늙은이가 보기에 재료가 다 모인 것 같구나.",
          DialogueId = 90000001,
          Duration = 3,
          GUID = "E14E392A",
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Tiejiang"
        },
        [90000011] = {
          ContentKR = "강력한 각인!",
          DialogueId = 90000011,
          GUID = "E14E3ACE"
        },
        [90000012] = {
          ContentKR = "강력한 보물!",
          DialogueId = 90000012,
          GUID = "E14E3AF8"
        },
        [90000013] = {
          ContentKR = "모두 갖고 싶어!",
          DialogueId = 90000013,
          GUID = "E14E3B22"
        },
        [90000021] = {
          ContentKR = "중간 희귀도의 각인 1개를 선택하세요",
          DialogueId = 90000021,
          GUID = "E14E3C72"
        },
        [90000022] = {
          ContentKR = "높은 희귀도의 각인 1개를 무작위로 획득합니다",
          DialogueId = 90000022,
          GUID = "E14E3C9C"
        },
        [90000031] = {
          ContentKR = "낮은 희귀도의 보물 2개를 무작위로 획득합니다",
          DialogueId = 90000031,
          GUID = "E14E3E16"
        },
        [90000032] = {
          ContentKR = "임의 희귀도의 보물 1개를 무작위로 획득합니다",
          DialogueId = 90000032,
          GUID = "E14E3E40"
        },
        [90000041] = {
          ContentKR = "아무것도 얻지 못했습니다",
          DialogueId = 90000041,
          GUID = "E14E3FBA"
        },
        [90000051] = {
          ContentKR = "위대한 각인의 선물자여, 지고하신 당신의 도움이 필요합니다!",
          DialogueId = 90000051,
          GUID = "E14E415E"
        },
        [90000052] = {
          ContentKR = "낮은 희귀도의 각인 1개를 선택하세요",
          DialogueId = 90000052,
          GUID = "E14E4188"
        },
        [90000053] = {
          ContentKR = "중간 희귀도의 각인 1개를 무작위로 획득합니다",
          DialogueId = 90000053,
          GUID = "E14E41B2"
        },
        [90000061] = {
          ContentKR = "위대한 보물의 선물자여, 지고하신 당신의 도움이 필요합니다!",
          DialogueId = 90000061,
