        },
        [101002151] = {
          ContentKR = "(카밀라를 따라 아이스레이크 시티로 간다.)",
          DialogueId = 101002151,
          ExStoryInfo = "Player",
          GUID = "101002151",
          ImprPlusId = 1006,
          NextDialogue = 10100223,
          SpeakNpcId = 100001,
          Subtitle = "(Follow Camilla and Snow to Icelake.)"
        },
        [101002152] = {
