        [101008062] = {
          DialogueId = 101008062,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 10100824,
          GUID = "101008062",
          NextOptions = {
            [1] = 101008061,
            [2] = 101008151,
            [3] = 101008191
          }
        },
        [101008151] = {
