          GUID = "101024191",
          ImprPlusId = 1009,
          NextDialogue = 10102420,
          SpeakNpcId = 200002,
          Subtitle = "It's not really up to them, I suppose."
        },
        [101024192] = {
          ContentKR = "스노우 말이 맞아. 받은 만큼 돌려줘야지.",
          DialogueId = 101024192,
          GUID = "101024192",
          ImprPlusId = 1007,
          NextDialogue = 10102420,
          SpeakNpcId = 200002,
