          ExStoryInfo = "Player",
          GUID = "200008093.0",
          ImprPlusId = 1005,
          NextDialogue = 20000812,
          SpeakNpcId = 100001
        },
        [200008161] = {
          ContentKR = "꽃이 좀 기운이 없어 보여.",
