          ExStoryInfo = "Player",
          GUID = "200008203.0",
          NextDialogue = 20000827,
          SpeakNpcId = 100001
        },
        [200008341] = {
          ContentKR = "(위로한다. 아무리 튼튼한 꽃이라도 연약한 식물이니까, 시들어가는 건 당연한 일이야.)",
